def _window_frame(df: pd.DataFrame, window: str) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=df.columns if isinstance(df, pd.DataFrame) else [])
    days = WINDOW_DAYS.get(window)
    if days is None:
        return df.copy()
    cutoff = pd.Timestamp.utcnow().tz_localize(None).normalize() - pd.Timedelta(days=int(days))
    return df.loc[pd.to_datetime(df["date"], errors="coerce") >= cutoff].copy()


def _latest_value(df: pd.DataFrame) -> Optional[float]:
    if not isinstance(df, pd.DataFrame) or df.empty or "value" not in df.columns:
        return None
    s = pd.to_numeric(df["value"], errors="coerce").dropna()
    return _safe_float(s.iloc[-1]) if not s.empty else None


def _latest_date(df: pd.DataFrame) -> Optional[pd.Timestamp]:
    if not isinstance(df, pd.DataFrame) or df.empty or "date" not in df.columns:
        return None
    work = df.dropna(subset=["date", "value"] if "value" in df.columns else ["date"])
    if work.empty:
        return None
    return pd.to_datetime(work["date"].iloc[-1], errors="coerce")


def _value_asof(df: pd.DataFrame, target_date: pd.Timestamp, max_age_days: int = 14) -> Optional[float]:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return None
    work = df[["date", "value"]].copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce").dt.tz_localize(None)
    work["value"] = pd.to_numeric(work["value"], errors="coerce")
    work = work.dropna().sort_values("date")
    before = work.loc[work["date"] <= pd.Timestamp(target_date).tz_localize(None)]
    if before.empty:
        return None
    row = before.iloc[-1]
    age = (pd.Timestamp(target_date).tz_localize(None) - row["date"]).days
    if age > max_age_days:
        return None
    return _safe_float(row["value"])


def _series_change(df: pd.DataFrame, days: int, max_age_days: int = 14) -> Optional[float]:
    latest = _latest_value(df)
    latest_dt = _latest_date(df)
    if latest is None or latest_dt is None:
        return None
    previous = _value_asof(df, latest_dt - pd.Timedelta(days=days), max_age_days=max_age_days)
    if previous is None:
        return None
    return latest - previous


def _normalize_price_frame(raw: pd.DataFrame) -> pd.DataFrame:
    if raw is None or not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=["date", "close"])
    df = raw.copy()
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = [
            "_".join(str(x) for x in col if str(x) not in {"", "None"}).strip("_").lower()
            for col in df.columns
        ]
    else:
        df.columns = [str(c).strip().lower().replace(" ", "_") for c in df.columns]
    df = df.reset_index() if "date" not in df.columns and "datetime" not in df.columns else df
    date_col = "date" if "date" in df.columns else "datetime" if "datetime" in df.columns else df.columns[0]
    candidates = ["close", "adj_close"] + [c for c in df.columns if "close" in c]
    close_col = next((c for c in candidates if c in df.columns), None)
    if close_col is None:
        return pd.DataFrame(columns=["date", "close"])
    out = pd.DataFrame(
        {
            "date": pd.to_datetime(df[date_col], errors="coerce").dt.tz_localize(None),
            "close": pd.to_numeric(df[close_col], errors="coerce"),
        }
    )
    return out.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


