@dataclass(frozen=True)
class ProviderStatus:
    series_id: str
    source: str
    status: str
    observations: int
    latest_date: Optional[str]
    message: str = ""


@st.cache_data(ttl=21600, show_spinner=False)
def _fetch_fred_series(series_id: str, start_date: str = "1990-01-01") -> Tuple[pd.DataFrame, Dict[str, Any]]:
    series_id = str(series_id or "").upper().strip()
    empty = pd.DataFrame(columns=["date", "value", "series_id"])
    if not series_id:
        return empty, {"status": "invalid", "source": "FRED", "message": "Empty series id"}

    url = FRED_CSV_URL.format(series_id=quote(series_id))
    try:
        if REQUESTS_AVAILABLE and requests is not None:
            response = requests.get(
                url,
                timeout=(5, 25),
                headers={"User-Agent": "QuantTerminal-MarketDesk/1.0"},
            )
            response.raise_for_status()
            raw = pd.read_csv(io.StringIO(response.text))
        else:
            raw = pd.read_csv(url)
        if raw is None or raw.empty or len(raw.columns) < 2:
            return empty, {"status": "empty", "source": "FRED", "message": "No observations returned"}

        date_col = raw.columns[0]
        value_col = series_id if series_id in raw.columns else raw.columns[1]
        out = raw[[date_col, value_col]].copy()
        out.columns = ["date", "value"]
        out["date"] = pd.to_datetime(out["date"], errors="coerce").dt.tz_localize(None)
        out["value"] = pd.to_numeric(out["value"].replace(".", np.nan), errors="coerce")
        out = out.dropna().sort_values("date")
        if start_date:
            out = out.loc[out["date"] >= pd.Timestamp(start_date)]
        out["series_id"] = series_id
        return out.reset_index(drop=True), {"status": "live", "source": "FRED public CSV", "message": ""}
    except Exception as exc:
        return empty, {"status": "unavailable", "source": "FRED public CSV", "message": str(exc)[:180]}


@st.cache_data(ttl=21600, show_spinner=False)
def _load_fred_pack(series_ids: Tuple[str, ...], start_date: str = "1990-01-01") -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, Any]]]:
    pack: Dict[str, pd.DataFrame] = {}
    quality: List[Dict[str, Any]] = []
    for sid in series_ids:
        frame, meta = _fetch_fred_series(sid, start_date=start_date)
        pack[sid] = frame
        latest = _latest_date(frame)
        quality.append(
            {
                "Series": sid,
                "Label": FIXED_INCOME_SERIES.get(sid, {}).get("label", sid),
                "Category": FIXED_INCOME_SERIES.get(sid, {}).get("category", "Other"),
                "Source": meta.get("source", "FRED"),
                "Status": meta.get("status", "unknown"),
                "Observations": len(frame),
                "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
                "Unit": FIXED_INCOME_SERIES.get(sid, {}).get("unit", ""),
                "Frequency": FIXED_INCOME_SERIES.get(sid, {}).get("frequency", ""),
                "Message": meta.get("message", ""),
            }
        )
    return pack, quality


@st.cache_data(ttl=1800, show_spinner=False)
def _fetch_yahoo_history(symbol: str, period: str = "5y") -> Tuple[pd.DataFrame, Dict[str, Any]]:
    empty = pd.DataFrame(columns=["date", "close", "symbol"])
    symbol = str(symbol or "").upper().strip()
    if not symbol:
        return empty, {"status": "invalid", "source": "Yahoo/yfinance", "message": "Empty symbol"}
    if not YFINANCE_AVAILABLE or yf is None:
        return empty, {"status": "provider-required", "source": "Yahoo/yfinance", "message": "yfinance unavailable"}
    try:
        raw = yf.download(symbol, period=period, interval="1d", progress=False, auto_adjust=True, threads=False)
        if raw is None or raw.empty:
            return empty, {"status": "empty", "source": "Yahoo/yfinance", "message": "No observations returned"}
        raw = raw.reset_index()
        if isinstance(raw.columns, pd.MultiIndex):
            raw.columns = [
                "_".join(str(x) for x in col if str(x) not in {"", "None"}).strip("_").lower()
                for col in raw.columns
            ]
        else:
            raw.columns = [str(c).strip().lower().replace(" ", "_") for c in raw.columns]
        date_col = "date" if "date" in raw.columns else "datetime" if "datetime" in raw.columns else raw.columns[0]
        close_candidates = ["close", f"close_{symbol.lower()}"] + [c for c in raw.columns if "close" in c]
        close_col = next((c for c in close_candidates if c in raw.columns), None)
        if close_col is None:
            return empty, {"status": "schema-error", "source": "Yahoo/yfinance", "message": "Close column missing"}
        out = pd.DataFrame(
            {
                "date": pd.to_datetime(raw[date_col], errors="coerce").dt.tz_localize(None),
                "close": pd.to_numeric(raw[close_col], errors="coerce"),
            }
        ).dropna()
        out["symbol"] = symbol
        out = out.drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)
        return out, {"status": "live", "source": "Yahoo/yfinance", "message": ""}
    except Exception as exc:
        return empty, {"status": "unavailable", "source": "Yahoo/yfinance", "message": str(exc)[:180]}


@st.cache_data(ttl=1800, show_spinner=False)
def _load_duration_pack(symbols: Tuple[str, ...], period: str = "5y") -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, Any]]]:
    pack: Dict[str, pd.DataFrame] = {}
    quality: List[Dict[str, Any]] = []
    for symbol in symbols:
        frame, meta = _fetch_yahoo_history(symbol, period=period)
        pack[symbol] = frame
        latest = frame["date"].iloc[-1] if not frame.empty else None
        quality.append(
            {
                "Series": symbol,
                "Label": DURATION_ETFS.get(symbol, {}).get("label", symbol),
                "Category": "Duration ETF",
                "Source": meta.get("source", "Yahoo/yfinance"),
                "Status": meta.get("status", "unknown"),
                "Observations": len(frame),
                "Latest Date": pd.Timestamp(latest).strftime("%Y-%m-%d") if latest is not None else "—",
                "Unit": "Adjusted price",
                "Frequency": "Daily",
                "Message": meta.get("message", ""),
            }
        )
    return pack, quality


