# Fixed Income transforms
# -----------------------------------------------------------------------------


def _curve_snapshot(pack: Mapping[str, pd.DataFrame], asof: Optional[pd.Timestamp] = None) -> pd.DataFrame:
    latest_dates = [_latest_date(pack.get(sid, pd.DataFrame())) for sid in US_CURVE_ORDER]
    latest_dates = [d for d in latest_dates if d is not None and not pd.isna(d)]
    if asof is None:
        if not latest_dates:
            return pd.DataFrame(columns=["Series", "Maturity", "Tenor Years", "Yield"])
        asof = max(latest_dates)

    rows: List[Dict[str, Any]] = []
    for sid in US_CURVE_ORDER:
        meta = FIXED_INCOME_SERIES[sid]
        value = _value_asof(pack.get(sid, pd.DataFrame()), pd.Timestamp(asof), max_age_days=14)
        rows.append(
            {
                "Series": sid,
                "Maturity": meta["label"].replace("US Treasury ", ""),
                "Tenor Years": float(meta["tenor_years"]),
                "Yield": value,
                "As Of": pd.Timestamp(asof).strftime("%Y-%m-%d"),
            }
        )
    return pd.DataFrame(rows)


def _curve_comparison(pack: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    latest_dates = [_latest_date(pack.get(sid, pd.DataFrame())) for sid in US_CURVE_ORDER]
    latest_dates = [d for d in latest_dates if d is not None and not pd.isna(d)]
    if not latest_dates:
        return pd.DataFrame()
    latest = max(latest_dates)
    comparisons = [
        ("Current", latest),
        ("1M ago", latest - pd.Timedelta(days=30)),
        ("3M ago", latest - pd.Timedelta(days=91)),
        ("1Y ago", latest - pd.Timedelta(days=365)),
    ]
    frames = []
    for label, date in comparisons:
        snap = _curve_snapshot(pack, date)
        snap["Snapshot"] = label
        frames.append(snap)
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()


def _curve_surface(pack: Mapping[str, pd.DataFrame], window: str = "5Y", frequency: str = "Monthly") -> pd.DataFrame:
    columns: Dict[str, pd.Series] = {}
    for sid in US_CURVE_ORDER:
        frame = pack.get(sid, pd.DataFrame())
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            continue
        s = frame.set_index("date")["value"].astype(float).sort_index()
        columns[sid] = s
    if not columns:
        return pd.DataFrame()
    wide = pd.concat(columns, axis=1).sort_index()
    days = WINDOW_DAYS.get(window)
    if days is not None:
        wide = wide.loc[wide.index >= wide.index.max() - pd.Timedelta(days=days)]
    rule = "ME" if frequency == "Monthly" else "W-FRI"
    sampled = wide.resample(rule).last()
    # No interpolation. A short forward fill only carries the last available
    # observation within the same reporting neighbourhood.
    sampled = sampled.ffill(limit=1)
    return sampled.dropna(how="all")


def _sovereign_frame(pack: Mapping[str, pd.DataFrame], window: str) -> pd.DataFrame:
    series: Dict[str, pd.Series] = {}
    for country, sid in SOVEREIGN_10Y_SERIES:
        frame = pack.get(sid, pd.DataFrame())
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            continue
        use = _window_frame(frame, window)
        if use.empty:
            continue
        series[country] = use.set_index("date")["value"].astype(float)
    if not series:
        return pd.DataFrame()
    return pd.concat(series, axis=1).sort_index()


def _duration_metrics(pack: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for symbol, meta in DURATION_ETFS.items():
        frame = pack.get(symbol, pd.DataFrame())
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            rows.append(
                {
                    "Symbol": symbol,
                    "Instrument": meta["label"],
                    "Bucket": meta["duration_bucket"],
                    "Last": np.nan,
                    "1M": np.nan,
                    "3M": np.nan,
                    "1Y": np.nan,
                    "Vol 60D": np.nan,
                    "Status": "Unavailable",
                }
            )
            continue
        s = frame.set_index("date")["close"].astype(float).sort_index()
        ret = s.pct_change().dropna()

        def perf(days: int) -> Optional[float]:
            if s.empty:
                return None
            target = s.index.max() - pd.Timedelta(days=days)
            prior = s.loc[s.index <= target]
            if prior.empty or prior.iloc[-1] == 0:
                return None
            return float(s.iloc[-1] / prior.iloc[-1] - 1)

        rows.append(
            {
                "Symbol": symbol,
                "Instrument": meta["label"],
                "Bucket": meta["duration_bucket"],
                "Last": _safe_float(s.iloc[-1]),
                "1M": perf(30),
                "3M": perf(91),
                "1Y": perf(365),
                "Vol 60D": _safe_float(ret.tail(60).std(ddof=1) * math.sqrt(TRADING_DAYS)) if len(ret) >= 30 else np.nan,
                "Status": "OK",
            }
        )
    return pd.DataFrame(rows)


def _fixed_income_summary(pack: Mapping[str, pd.DataFrame]) -> Dict[str, Any]:
    y2 = _latest_value(pack.get("DGS2", pd.DataFrame()))
    y10 = _latest_value(pack.get("DGS10", pd.DataFrame()))
    y30 = _latest_value(pack.get("DGS30", pd.DataFrame()))
    s2s10 = _latest_value(pack.get("T10Y2Y", pd.DataFrame()))
    s3m10 = _latest_value(pack.get("T10Y3M", pd.DataFrame()))
    real10 = _latest_value(pack.get("DFII10", pd.DataFrame()))
    bei10 = _latest_value(pack.get("T10YIE", pd.DataFrame()))
    policy = _latest_value(pack.get("DFF", pd.DataFrame()))

    if s2s10 is None and y10 is not None and y2 is not None:
        s2s10 = y10 - y2

    if s2s10 is None:
        curve_regime = "Unavailable"
        curve_read = "Public curve-spread data are unavailable."
    elif s2s10 < -0.50:
        curve_regime = "Deep inversion"
        curve_read = "Front-end yields materially exceed long yields; restrictive policy and slowdown pricing dominate."
    elif s2s10 < 0:
        curve_regime = "Inverted"
        curve_read = "The curve remains inverted; distinguish late-cycle inversion from an early bull steepening."
    elif s2s10 < 0.75:
        curve_regime = "Flat / modestly positive"
        curve_read = "The curve is near flat to mildly positive; decompose moves into front-end and term-premium components."
    else:
        curve_regime = "Steep"
        curve_read = "The curve is positively sloped; verify whether the steepening is growth-positive or inflation/term-premium driven."

    return {
        "2Y": y2,
        "10Y": y10,
        "30Y": y30,
        "10Y-2Y": s2s10,
        "10Y-3M": s3m10,
        "10Y Real": real10,
        "10Y Breakeven": bei10,
        "Policy": policy,
        "Curve Regime": curve_regime,
        "Curve Read": curve_read,
        "2Y 1M Δ": _series_change(pack.get("DGS2", pd.DataFrame()), 30),
        "10Y 1M Δ": _series_change(pack.get("DGS10", pd.DataFrame()), 30),
        "30Y 1M Δ": _series_change(pack.get("DGS30", pd.DataFrame()), 30),
    }


