def _fixed_income_controls() -> Tuple[str, str, str]:
    c1, c2, c3, c4 = st.columns([1.0, 1.0, 1.0, 1.3], gap="small")
    with c1:
        window = st.selectbox(
            "Window",
            ["1Y", "3Y", "5Y", "10Y", "Max"],
            index=["1Y", "3Y", "5Y", "10Y", "Max"].index(str(st.session_state.get(MARKET_WINDOW_KEY, "5Y"))) if str(st.session_state.get(MARKET_WINDOW_KEY, "5Y")) in ["1Y", "3Y", "5Y", "10Y", "Max"] else 2,
            key="market_fi_window",
        )
        st.session_state[MARKET_WINDOW_KEY] = window
    with c2:
        surface_frequency = st.selectbox(
            "Surface sampling",
            ["Monthly", "Weekly"],
            index=0,
            key="market_fi_surface_frequency",
        )
    with c3:
        chart_page_size = st.selectbox(
            "Chart-book page size",
            [4, 6, 8],
            index=1,
            key="market_fi_chart_page_size",
        )
    with c4:
        show_missing = st.toggle(
            "Show provider-required rows",
            value=True,
            key="market_fi_show_missing",
        )
    return window, surface_frequency, str(chart_page_size) + ("|all" if show_missing else "|ok")


def _fixed_income_chart_registry() -> List[Dict[str, Any]]:
    return [
        {"title": "US Treasury curve snapshots", "group": "Sovereigns", "render": "curve"},
        {"title": "US Treasury curve surface", "group": "Sovereigns", "render": "surface"},
        {"title": "US Treasury tenors", "group": "Sovereigns", "render": "series", "series": ["DGS2", "DGS5", "DGS10", "DGS30"]},
        {"title": "US 10Y–2Y slope", "group": "Curve", "render": "series", "series": ["T10Y2Y"]},
        {"title": "US 10Y–3M slope", "group": "Curve", "render": "series", "series": ["T10Y3M"]},
        {"title": "Fed funds vs 2Y and 10Y", "group": "Policy", "render": "series", "series": ["DFF", "DGS2", "DGS10"]},
        {"title": "Breakeven inflation", "group": "Inflation", "render": "series", "series": ["T5YIE", "T10YIE"]},
        {"title": "TIPS real yields", "group": "Real Yields", "render": "series", "series": ["DFII5", "DFII10", "DFII20", "DFII30"]},
        {"title": "5Y5Y inflation forward", "group": "Inflation", "render": "series", "series": ["T5Y5Y"]},
        {"title": "Developed sovereign 10Y", "group": "Sovereigns", "render": "sovereigns"},
        {"title": "Duration ETF ladder", "group": "Duration", "render": "duration"},
        {"title": "Front-end rates", "group": "Money Markets", "render": "series", "series": ["DFF", "DGS1MO", "DGS3MO", "DGS6MO", "DGS1", "DGS2"]},
    ]


def _render_chart_spec(
    spec: Mapping[str, Any],
    pack: Mapping[str, pd.DataFrame],
    duration_pack: Mapping[str, pd.DataFrame],
    duration_metrics: pd.DataFrame,
    window: str,
    surface_frequency: str,
) -> None:
    kind = spec.get("render")
    title = str(spec.get("title", "Chart"))
    if kind == "curve":
        _plot_curve_comparison(pack)
    elif kind == "surface":
        _plot_curve_surface(pack, window, surface_frequency)
    elif kind == "sovereigns":
        _plot_sovereigns(pack, window)
    elif kind == "duration":
        _plot_duration_returns(duration_metrics)
    else:
        _plot_series(pack, spec.get("series", []), title, window)


def _render_chart_book(
    pack: Mapping[str, pd.DataFrame],
    duration_pack: Mapping[str, pd.DataFrame],
    duration_metrics: pd.DataFrame,
    window: str,
    surface_frequency: str,
    page_size: int,
) -> None:
    registry = _fixed_income_chart_registry()
    groups = ["All"] + sorted({str(x["group"]) for x in registry})
    c1, c2 = st.columns([1.3, 2.7], gap="small")
    with c1:
        group = st.selectbox("Chart group", groups, key="market_fi_chart_group")
    filtered = registry if group == "All" else [x for x in registry if x["group"] == group]
    total_pages = max(1, int(math.ceil(len(filtered) / page_size)))
    page_key = "market_fi_chart_page"
    current = int(st.session_state.get(page_key, 1))
    current = max(1, min(current, total_pages))
    st.session_state[page_key] = current
    with c2:
        n1, n2, n3 = st.columns([1, 2, 1])
        with n1:
            if st.button("← Previous", disabled=current <= 1, key="market_fi_chart_prev", use_container_width=True):
                st.session_state[page_key] = current - 1
                st.rerun()
        with n2:
            st.caption(f"Page {current} of {total_pages} · {len(filtered)} registered charts")
        with n3:
            if st.button("Next →", disabled=current >= total_pages, key="market_fi_chart_next", use_container_width=True):
                st.session_state[page_key] = current + 1
                st.rerun()

    start = (current - 1) * page_size
    for spec in filtered[start : start + page_size]:
        _section(str(spec["title"]), f'{spec["group"]} · registered chart')
        _render_chart_spec(spec, pack, duration_pack, duration_metrics, window, surface_frequency)


def _quality_summary(quality_df: pd.DataFrame) -> Dict[str, Any]:
    if quality_df is None or quality_df.empty:
        return {"loaded": 0, "total": 0, "latest": "—", "provider_required": 0}
    ok = quality_df["Status"].astype(str).isin(["live", "cache", "OK"])
    dates = pd.to_datetime(quality_df["Latest Date"], errors="coerce")
    latest = dates.max()
    return {
        "loaded": int(ok.sum()),
        "total": int(len(quality_df)),
        "latest": latest.strftime("%Y-%m-%d") if pd.notna(latest) else "—",
        "provider_required": int((~ok).sum()),
    }


def _render_fixed_income_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    window, surface_frequency, page_settings = _fixed_income_controls()
    page_size = int(page_settings.split("|")[0])
    show_missing = page_settings.endswith("|all")

    fred_ids = tuple(FIXED_INCOME_SERIES.keys())
    with st.spinner("Loading Fixed Income public data…"):
        pack, fred_quality = _load_fred_pack(fred_ids, start_date="1990-01-01")
        duration_pack, duration_quality = _load_duration_pack(tuple(DURATION_ETFS.keys()), period="10y")

    quality_df = pd.DataFrame(fred_quality + duration_quality)
    summary = _fixed_income_summary(pack)
    duration_metrics = _duration_metrics(duration_pack)

    _render_kpi_grid(summary)
    _html(f'<div class="mk-warning"><b>Curve regime:</b> {_escape(summary["Curve Regime"])} · {_escape(summary["Curve Read"])}</div>')

    tabs = st.tabs([
        "Overview",
        "Yield Curve",
        "Sovereigns",
        "Inflation / Real Yields",
        "Duration",
        "Chart Book",
        "Data Quality",
    ])

    with tabs[0]:
        left, right = st.columns([1.15, 0.85], gap="large")
        with left:
            _plot_curve_comparison(pack)
        with right:
            _plot_series(pack, ["DFF", "DGS2", "DGS10"], "Policy rate and benchmark yields", window)
        c1, c2 = st.columns(2, gap="large")
        with c1:
            _plot_series(pack, ["T10Y2Y", "T10Y3M"], "Curve slopes", window, "Percentage points")
        with c2:
            _plot_series(pack, ["T5YIE", "T10YIE", "DFII10"], "Inflation compensation and 10Y real yield", window)

    with tabs[1]:
        _section("Current curve and historical snapshots", "Observed Treasury constant-maturity yields; no cross-tenor interpolation.")
        _plot_curve_comparison(pack)
        _section("Historical curve surface", "Weekly/monthly last observations preserve missing-data gaps.")
        _plot_curve_surface(pack, window, surface_frequency)
        current_curve = _curve_snapshot(pack)
        display = current_curve.copy()
        if not display.empty:
            display["Yield"] = display["Yield"].map(lambda x: _fmt(x, 3, "%"))
        _section("Curve table", "Latest as-of values by tenor.")
        _html_table(display)

    with tabs[2]:
        _section("Developed sovereign yields", "US daily Treasury data and public OECD/FRED monthly country series are kept at native frequency.")
        _plot_sovereigns(pack, window)
        rows = []
        for country, sid in SOVEREIGN_10Y_SERIES:
            frame = pack.get(sid, pd.DataFrame())
            rows.append(
                {
                    "Country": country,
                    "Series": sid,
                    "Latest": _fmt(_latest_value(frame), 3, "%"),
                    "Latest Date": _latest_date(frame).strftime("%Y-%m-%d") if _latest_date(frame) is not None else "—",
                    "1M Δ": _fmt_signed(_series_change(frame, 30), 3, " pp"),
                    "Frequency": FIXED_INCOME_SERIES.get(sid, {}).get("frequency", ""),
                }
            )
        _html_table(pd.DataFrame(rows))

    with tabs[3]:
        c1, c2 = st.columns(2, gap="large")
        with c1:
            _plot_series(pack, ["T5YIE", "T10YIE", "T5Y5Y"], "Inflation compensation", window)
        with c2:
            _plot_series(pack, ["DFII5", "DFII10", "DFII20", "DFII30"], "TIPS real yields", window)
        _section("Nominal / real decomposition", "Nominal Treasury yields, real yields and breakevens are displayed as separate observed series.")
        _plot_series(pack, ["DGS10", "DFII10", "T10YIE"], "US 10Y nominal, real and breakeven", window)

    with tabs[4]:
        _plot_duration_returns(duration_metrics)
        display = duration_metrics.copy()
        for col in ["1M", "3M", "1Y", "Vol 60D"]:
            if col in display.columns:
                display[col] = display[col].map(_fmt_pct)
        if "Last" in display.columns:
            display["Last"] = display["Last"].map(lambda x: _fmt(x, 2))
        _section("Duration instruments", "Adjusted-price proxies; instrument duration is represented by fund mandate, not a computed effective-duration feed.")
        _html_table(display)

    with tabs[5]:
        _render_chart_book(pack, duration_pack, duration_metrics, window, surface_frequency, page_size)

    with tabs[6]:
        qsum = _quality_summary(quality_df)
        _html(
            '<div class="mk-kpis">'
            + _kpi_card("Series loaded", f'{qsum["loaded"]}/{qsum["total"]}', "Public data and optional market proxies")
            + _kpi_card("Latest observation", str(qsum["latest"]), "Latest date across loaded series")
            + _kpi_card("Provider-required", str(qsum["provider_required"]), "Missing rows are never fabricated")
            + _kpi_card("Registry version", MARKET_INTELLIGENCE_VERSION, "Fixed Income V1")
            + '</div>'
        )
        _section("Series registry and freshness", "Each series retains source, unit, frequency, observation count and provider state.")
        display_quality = quality_df.copy()
        if not show_missing:
            display_quality = display_quality.loc[display_quality["Status"].astype(str).isin(["live", "cache", "OK"])]
        _html_table(display_quality, max_rows=100)
        st.download_button(
            "Download Fixed Income quality registry",
            data=quality_df.to_csv(index=False).encode("utf-8"),
            file_name="marketdesk_fixed_income_quality.csv",
            mime="text/csv",
            key="market_fi_download_quality",
        )


