def _liq_window_frame(df: pd.DataFrame, window: str) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=df.columns if isinstance(df, pd.DataFrame) else [])
    days = LIQUIDITY_WINDOWS.get(str(window), 5 * 370)
    if days is None:
        return df.copy()
    date_col = "date" if "date" in df.columns else None
    if date_col is None:
        return df.copy()
    cutoff = pd.Timestamp.utcnow().tz_localize(None).normalize() - pd.Timedelta(days=int(days))
    return df.loc[pd.to_datetime(df[date_col], errors="coerce") >= cutoff].copy()


def _liq_native_periods(df: pd.DataFrame, years: float = 1.0) -> int:
    if not isinstance(df, pd.DataFrame) or len(df) < 3:
        return 1
    dates = pd.to_datetime(df["date"], errors="coerce").dropna().sort_values()
    if len(dates) < 3:
        return 1
    median_days = max(1.0, float(dates.diff().dt.days.dropna().median()))
    return max(1, int(round(365.25 * years / median_days)))


def _liq_yoy_frame(df: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = df[["date", "value"]].copy().dropna()
    work = work.sort_values("date")
    periods = _liq_native_periods(work, 1.0)
    work["value"] = pd.to_numeric(work["value"], errors="coerce").pct_change(periods) * 100.0
    return work.dropna().reset_index(drop=True)


def _liq_money_growth_frame(pack: Mapping[str, pd.DataFrame], series_id: str) -> pd.DataFrame:
    """Return a comparable YoY money-growth series without double-transforming published growth rates."""
    raw = pack.get(series_id, pd.DataFrame())
    if not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=["date", "value"])
    meta = LIQUIDITY_FRED_SERIES.get(series_id, {})
    if bool(meta.get("already_yoy", False)):
        out = raw[["date", "value"]].copy()
        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["value"] = pd.to_numeric(out["value"], errors="coerce")
        return out.dropna().sort_values("date").reset_index(drop=True)
    return _liq_yoy_frame(raw)


def _liq_ex_us_money_growth_latest(pack: Mapping[str, pd.DataFrame]) -> Optional[float]:
    values: List[float] = []
    for sid in ("EA19MABMM301GYSAM", "JPNMABMM301GYSAM", "GBRMABMM301GYSAM"):
        value = _latest_value(_liq_money_growth_frame(pack, sid))
        if value is not None:
            values.append(float(value))
    return float(np.mean(values)) if values else None


def _liq_zscore_frame(df: pd.DataFrame, years: float = 5.0) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = df[["date", "value"]].copy().dropna().sort_values("date")
    periods = max(20, _liq_native_periods(work, years))
    values = pd.to_numeric(work["value"], errors="coerce")
    mean = values.rolling(periods, min_periods=max(12, periods // 3)).mean()
    std = values.rolling(periods, min_periods=max(12, periods // 3)).std(ddof=1).replace(0, np.nan)
    work["value"] = (values - mean) / std
    return work.dropna().reset_index(drop=True)


def _liq_indexed_frame(df: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = df[["date", "value"]].copy().dropna().sort_values("date")
    values = pd.to_numeric(work["value"], errors="coerce")
    first = _safe_float(values.iloc[0]) if not values.empty else None
    if first in (None, 0):
        return pd.DataFrame(columns=["date", "value"])
    work["value"] = values / float(first) * 100.0
    return work.dropna().reset_index(drop=True)


def _liq_transform_frame(df: pd.DataFrame, view: str) -> pd.DataFrame:
    view = str(view or "Level")
    if view == "YoY %":
        return _liq_yoy_frame(df)
    if view == "Z-score":
        return _liq_zscore_frame(df)
    if view == "Indexed 100":
        return _liq_indexed_frame(df)
    return df[["date", "value"]].copy() if isinstance(df, pd.DataFrame) and not df.empty else pd.DataFrame(columns=["date", "value"])


def _liq_resample(df: pd.DataFrame, frequency: str) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty or frequency == "Native":
        return df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame(columns=["date", "value"])
    rule = "W-FRI" if frequency == "Weekly" else "ME"
    work = df[["date", "value"]].copy().dropna()
    work["date"] = pd.to_datetime(work["date"], errors="coerce").dt.tz_localize(None)
    work["value"] = pd.to_numeric(work["value"], errors="coerce")
    work = work.dropna().set_index("date").sort_index().resample(rule).last().dropna().reset_index()
    return work


def _liq_pct_change_latest(df: pd.DataFrame, years: float = 1.0) -> Optional[float]:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return None
    work = df[["date", "value"]].copy().dropna().sort_values("date")
    periods = _liq_native_periods(work, years)
    values = pd.to_numeric(work["value"], errors="coerce")
    if len(values) <= periods:
        return None
    prev = _safe_float(values.iloc[-1 - periods])
    last = _safe_float(values.iloc[-1])
    if prev in (None, 0) or last is None:
        return None
    return last / prev - 1.0


def _liq_freshness(latest: Optional[pd.Timestamp], expected_days: int) -> str:
    if latest is None or pd.isna(latest):
        return "Missing"
    age = max(0, int((pd.Timestamp.utcnow().tz_localize(None).normalize() - pd.Timestamp(latest).normalize()).days))
    if age <= int(expected_days):
        return "Fresh"
    if age <= int(expected_days) * 2:
        return "Lagged"
    return "Stale"


@st.cache_data(ttl=21600, show_spinner=False)
def _load_liquidity_fred_pack(series_ids: Tuple[str, ...], start_date: str = "1990-01-01") -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, Any]]]:
    pack: Dict[str, pd.DataFrame] = {}
    quality: List[Dict[str, Any]] = []
    for sid in series_ids:
        frame, meta = _fetch_fred_series(sid, start_date=start_date)
        pack[sid] = frame
        latest = _latest_date(frame)
        spec = LIQUIDITY_FRED_SERIES.get(sid, {})
        status = str(meta.get("status", "unknown"))
        quality.append({
            "Series / Instrument": sid,
            "Label": spec.get("label", sid),
            "Category": spec.get("category", "Other"),
            "Source": meta.get("source", "FRED public CSV"),
            "Status": status,
            "Freshness": _liq_freshness(latest, int(spec.get("expected_days", 30))) if status == "live" else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
            "Unit": spec.get("unit", ""),
            "Frequency": spec.get("frequency", ""),
            "Message": meta.get("message", ""),
        })
    return pack, quality


def _coingecko_headers_and_base() -> Tuple[Dict[str, str], str]:
    pro_key = _secret_or_env("COINGECKO_PRO_API_KEY", "")
    demo_key = _secret_or_env("COINGECKO_API_KEY", "") or _secret_or_env("COINGECKO_DEMO_API_KEY", "")
    if pro_key:
        return {"x-cg-pro-api-key": pro_key, "User-Agent": "QuantTerminal-MarketDesk/2.0"}, "https://pro-api.coingecko.com/api/v3"
    headers = {"User-Agent": "QuantTerminal-MarketDesk/2.0"}
    if demo_key:
        headers["x-cg-demo-api-key"] = demo_key
    return headers, "https://api.coingecko.com/api/v3"


@st.cache_data(ttl=1800, show_spinner=False)
def _fetch_coingecko_history(coin_id: str = "bitcoin", days: int = 1825) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    empty = pd.DataFrame(columns=["date", "price", "market_cap", "volume"])
    if not REQUESTS_AVAILABLE or requests is None:
        return empty, {"status": "provider-required", "source": "CoinGecko", "message": "requests unavailable"}
    headers, base = _coingecko_headers_and_base()
    try:
        response = requests.get(
            f"{base}/coins/{quote(str(coin_id))}/market_chart",
            params={"vs_currency": "usd", "days": str(int(days)), "interval": "daily", "precision": "full"},
            headers=headers,
            timeout=(5, 30),
        )
        response.raise_for_status()
        payload = response.json()
        price = pd.DataFrame(payload.get("prices", []), columns=["ts", "price"])
        market_cap = pd.DataFrame(payload.get("market_caps", []), columns=["ts", "market_cap"])
        volume = pd.DataFrame(payload.get("total_volumes", []), columns=["ts", "volume"])
        if price.empty:
            return empty, {"status": "empty", "source": "CoinGecko", "message": "No price observations"}
        out = price.merge(market_cap, on="ts", how="left").merge(volume, on="ts", how="left")
        out["date"] = pd.to_datetime(out["ts"], unit="ms", utc=True, errors="coerce").dt.tz_localize(None)
        for col in ["price", "market_cap", "volume"]:
            out[col] = pd.to_numeric(out[col], errors="coerce")
        out = out[["date", "price", "market_cap", "volume"]].dropna(subset=["date", "price"]).sort_values("date")
        return out.reset_index(drop=True), {"status": "live", "source": "CoinGecko API", "message": ""}
    except Exception as exc:
        return empty, {"status": "unavailable", "source": "CoinGecko API", "message": str(exc)[:180]}


@st.cache_data(ttl=900, show_spinner=False)
def _fetch_coingecko_snapshot() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    if not REQUESTS_AVAILABLE or requests is None:
        return {}, {"status": "provider-required", "source": "CoinGecko", "message": "requests unavailable"}
    headers, base = _coingecko_headers_and_base()
    try:
        global_response = requests.get(f"{base}/global", headers=headers, timeout=(5, 20))
        global_response.raise_for_status()
        global_data = global_response.json().get("data", {})
        stable_response = requests.get(
            f"{base}/coins/markets",
            params={"vs_currency": "usd", "category": "stablecoins", "order": "market_cap_desc", "per_page": 250, "page": 1, "sparkline": "false"},
            headers=headers,
            timeout=(5, 25),
        )
        stable_response.raise_for_status()
        stablecoins = stable_response.json() if isinstance(stable_response.json(), list) else []
        stable_cap = float(np.nansum([_safe_float(x.get("market_cap"), 0.0) or 0.0 for x in stablecoins]))
        snapshot = {
            "total_market_cap_usd": _safe_float((global_data.get("total_market_cap") or {}).get("usd")),
            "total_volume_usd": _safe_float((global_data.get("total_volume") or {}).get("usd")),
            "btc_dominance": _safe_float((global_data.get("market_cap_percentage") or {}).get("btc")),
            "eth_dominance": _safe_float((global_data.get("market_cap_percentage") or {}).get("eth")),
            "market_cap_change_24h": _safe_float(global_data.get("market_cap_change_percentage_24h_usd")),
            "stablecoin_market_cap_usd": stable_cap if stable_cap > 0 else None,
            "active_cryptocurrencies": global_data.get("active_cryptocurrencies"),
            "markets": global_data.get("markets"),
        }
        return snapshot, {"status": "live", "source": "CoinGecko API", "message": ""}
    except Exception as exc:
        return {}, {"status": "unavailable", "source": "CoinGecko API", "message": str(exc)[:180]}


@st.cache_data(ttl=1800, show_spinner=False)
def _load_liquidity_market_pack(symbols: Tuple[str, ...], period: str = "10y") -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, Any]]]:
    pack: Dict[str, pd.DataFrame] = {}
    quality: List[Dict[str, Any]] = []
    for symbol in symbols:
        frame, meta = _fetch_yahoo_history(symbol, period=period)
        value_frame = frame.rename(columns={"close": "value"})[["date", "value"]].copy() if isinstance(frame, pd.DataFrame) and not frame.empty else pd.DataFrame(columns=["date", "value"])
        pack[symbol] = value_frame
        latest = _latest_date(value_frame)
        spec = LIQUIDITY_MARKET_SYMBOLS.get(symbol, {})
        quality.append({
            "Series / Instrument": symbol,
            "Label": spec.get("label", symbol),
            "Category": spec.get("category", "Market Data"),
            "Source": meta.get("source", "Yahoo/yfinance"),
            "Status": meta.get("status", "unknown"),
            "Freshness": _liq_freshness(latest, 8) if meta.get("status") == "live" else "Missing",
            "Observations": len(value_frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
            "Unit": spec.get("unit", ""),
            "Frequency": "Daily",
            "Message": meta.get("message", ""),
        })
    return pack, quality


def _liq_asof_column(base_dates: pd.DataFrame, frame: pd.DataFrame, column_name: str, tolerance_days: int) -> pd.DataFrame:
    base = base_dates.sort_values("date").copy()
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        base[column_name] = np.nan
        return base
    right = frame[["date", "value"]].copy().dropna().sort_values("date")
    right["date"] = pd.to_datetime(right["date"], errors="coerce").dt.tz_localize(None)
    right["value"] = pd.to_numeric(right["value"], errors="coerce")
    right = right.dropna().rename(columns={"value": column_name})
    return pd.merge_asof(base, right, on="date", direction="backward", tolerance=pd.Timedelta(days=int(tolerance_days)))


def _build_g3_balance_sheet(pack: Mapping[str, pd.DataFrame]) -> Tuple[pd.DataFrame, pd.DataFrame]:
    frames = [pack.get("WALCL", pd.DataFrame()), pack.get("ECBASSETSW", pd.DataFrame()), pack.get("JPNASSETS", pd.DataFrame())]
    valid_dates = pd.concat([f[["date"]] for f in frames if isinstance(f, pd.DataFrame) and not f.empty], ignore_index=True) if any(isinstance(f, pd.DataFrame) and not f.empty for f in frames) else pd.DataFrame(columns=["date"])
    if valid_dates.empty:
        return pd.DataFrame(columns=["date", "value"]), pd.DataFrame()
    start = pd.to_datetime(valid_dates["date"], errors="coerce").min()
    end = pd.to_datetime(valid_dates["date"], errors="coerce").max()
    dates = pd.DataFrame({"date": pd.date_range(start=start, end=end, freq="W-FRI")})
    aligned = _liq_asof_column(dates, pack.get("WALCL", pd.DataFrame()), "fed_mn_usd", 14)
    aligned = _liq_asof_column(aligned, pack.get("ECBASSETSW", pd.DataFrame()), "ecb_mn_eur", 21)
    aligned = _liq_asof_column(aligned, pack.get("JPNASSETS", pd.DataFrame()), "boj_100m_jpy", 50)
    aligned = _liq_asof_column(aligned, pack.get("DEXUSEU", pd.DataFrame()), "usd_per_eur", 14)
    aligned = _liq_asof_column(aligned, pack.get("DEXJPUS", pd.DataFrame()), "jpy_per_usd", 14)
    aligned["Fed"] = aligned["fed_mn_usd"] / 1_000_000.0
    aligned["ECB"] = aligned["ecb_mn_eur"] / 1_000_000.0 * aligned["usd_per_eur"]
    aligned["BoJ"] = aligned["boj_100m_jpy"] / 10_000.0 / aligned["jpy_per_usd"]
    aligned["value"] = aligned[["Fed", "ECB", "BoJ"]].sum(axis=1, min_count=3)
    total = aligned[["date", "value"]].dropna().reset_index(drop=True)
    components = aligned[["date", "Fed", "ECB", "BoJ", "value"]].dropna(subset=["value"]).reset_index(drop=True)
    return total, components


def _build_us_net_liquidity(pack: Mapping[str, pd.DataFrame]) -> Tuple[pd.DataFrame, pd.DataFrame]:
    walcl = pack.get("WALCL", pd.DataFrame())
    if not isinstance(walcl, pd.DataFrame) or walcl.empty:
        return pd.DataFrame(columns=["date", "value"]), pd.DataFrame()
    dates = pd.DataFrame({"date": pd.to_datetime(walcl["date"], errors="coerce").dropna().sort_values().unique()})
    aligned = _liq_asof_column(dates, walcl, "fed_mn", 10)
    aligned = _liq_asof_column(aligned, pack.get("WTREGEN", pd.DataFrame()), "tga_mn", 14)
    aligned = _liq_asof_column(aligned, pack.get("RRPONTSYD", pd.DataFrame()), "rrp_bn", 7)
    aligned["Fed"] = aligned["fed_mn"] / 1_000_000.0
    aligned["TGA"] = aligned["tga_mn"] / 1_000_000.0
    aligned["RRP"] = aligned["rrp_bn"] / 1_000.0
    aligned["value"] = aligned["Fed"] - aligned["TGA"] - aligned["RRP"]
    total = aligned[["date", "value"]].dropna().reset_index(drop=True)
    components = aligned[["date", "Fed", "TGA", "RRP", "value"]].dropna(subset=["value"]).reset_index(drop=True)
    return total, components


def _build_real_m2(pack: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    m2 = pack.get("M2SL", pd.DataFrame())
    cpi = pack.get("CPIAUCSL", pd.DataFrame())
    if not isinstance(m2, pd.DataFrame) or m2.empty or not isinstance(cpi, pd.DataFrame) or cpi.empty:
        return pd.DataFrame(columns=["date", "value"])
    dates = m2[["date"]].copy().sort_values("date")
    aligned = _liq_asof_column(dates, m2, "m2", 45)
    aligned = _liq_asof_column(aligned, cpi, "cpi", 45)
    aligned["value"] = aligned["m2"] / aligned["cpi"] * 100.0
    return aligned[["date", "value"]].dropna().reset_index(drop=True)


def _build_debt_ratio(pack: Mapping[str, pd.DataFrame], debt_sid: str) -> pd.DataFrame:
    debt = pack.get(debt_sid, pd.DataFrame())
    gdp = pack.get("GDP", pd.DataFrame())
    if not isinstance(debt, pd.DataFrame) or debt.empty or not isinstance(gdp, pd.DataFrame) or gdp.empty:
        return pd.DataFrame(columns=["date", "value"])
    dates = debt[["date"]].copy().sort_values("date")
    aligned = _liq_asof_column(dates, debt, "debt_mn", 130)
    aligned = _liq_asof_column(aligned, gdp, "gdp_bn", 130)
    aligned["value"] = (aligned["debt_mn"] / 1_000.0) / aligned["gdp_bn"] * 100.0
    return aligned[["date", "value"]].dropna().reset_index(drop=True)


def _market_or_coingecko_price(history: pd.DataFrame, market_pack: Mapping[str, pd.DataFrame], symbol: str) -> pd.DataFrame:
    if isinstance(history, pd.DataFrame) and not history.empty and "price" in history.columns:
        return history[["date", "price"]].rename(columns={"price": "value"}).dropna().reset_index(drop=True)
    frame = market_pack.get(symbol, pd.DataFrame())
    return frame[["date", "value"]].copy() if isinstance(frame, pd.DataFrame) and not frame.empty else pd.DataFrame(columns=["date", "value"])


def _liq_scale(value: Any, low: float, high: float, inverse: bool = False) -> Optional[float]:
    x = _safe_float(value)
    if x is None or high == low:
        return None
    score = max(0.0, min(100.0, (x - low) / (high - low) * 100.0))
    return 100.0 - score if inverse else score


def _build_liquidity_score(pack: Mapping[str, pd.DataFrame], g3: pd.DataFrame, net_liquidity: pd.DataFrame) -> Tuple[Dict[str, Any], pd.DataFrame]:
    def pct100(frame: pd.DataFrame, years: float) -> Optional[float]:
        value = _liq_pct_change_latest(frame, years)
        return None if value is None else value * 100.0

    components = [
        ("G3 central-bank assets YoY", 0.23, pct100(g3, 1.0), -10.0, 15.0, False, "G3 aggregate converted to USD"),
        ("US net liquidity 13W", 0.22, pct100(net_liquidity, 0.25), -8.0, 8.0, False, "Fed assets minus TGA minus ON RRP"),
        ("US M2 YoY", 0.17, pct100(pack.get("M2SL", pd.DataFrame()), 1.0), -5.0, 10.0, False, "Broad-money impulse"),
        ("Ex-US G3 broad-money YoY", 0.10, _liq_ex_us_money_growth_latest(pack), -5.0, 10.0, False, "Mean of Euro area, Japan and UK published M3 growth rates"),
        ("US bank credit YoY", 0.12, pct100(pack.get("TOTBKCR", pd.DataFrame()), 1.0), -5.0, 10.0, False, "Commercial-bank balance-sheet channel"),
        ("US reserve balances 13W", 0.08, pct100(pack.get("WRESBAL", pd.DataFrame()), 0.25), -10.0, 10.0, False, "Bank-reserve impulse"),
        ("Broad dollar 13W", 0.08, pct100(pack.get("DTWEXBGS", pd.DataFrame()), 0.25), -8.0, 8.0, True, "A weaker dollar eases global financial conditions"),
    ]
    rows: List[Dict[str, Any]] = []
    numerator = 0.0
    denominator = 0.0
    for name, weight, raw, low, high, inverse, note in components:
        score = _liq_scale(raw, low, high, inverse=inverse)
        if score is not None:
            numerator += weight * score
            denominator += weight
        rows.append({"Component": name, "Weight": f"{weight:.0%}", "Latest": raw, "Score": score, "Definition": note})
    composite = numerator / denominator if denominator > 0 else 50.0
    if composite >= 67:
        regime = "Expansionary"
        read = "Broad balance-sheet and money impulses are supportive. Confirm with asset transmission rather than treating the score as a trade signal."
    elif composite <= 33:
        regime = "Contractionary"
        read = "Liquidity impulse is restrictive. Risk assets can remain vulnerable unless valuation or growth offsets dominate."
    else:
        regime = "Mixed / Transition"
        read = "The liquidity complex is not delivering a single directional signal. Component dispersion matters more than the headline."
    table = pd.DataFrame(rows)
    table["Contribution"] = [(_safe_float(s) or 0.0) * float(w.strip("%")) / 100.0 for s, w in zip(table["Score"], table["Weight"])]
    return {"score": float(max(0.0, min(100.0, composite))), "regime": regime, "read": read}, table


def _liq_summary(pack: Mapping[str, pd.DataFrame], g3: pd.DataFrame, net_liquidity: pd.DataFrame, btc_price: pd.DataFrame, gold_price: pd.DataFrame, score: Mapping[str, Any]) -> Dict[str, Any]:
    return {
        "score": score.get("score"),
        "regime": score.get("regime"),
        "g3": _latest_value(g3),
        "g3_yoy": _liq_pct_change_latest(g3, 1.0),
        "net": _latest_value(net_liquidity),
        "net_13w": _liq_pct_change_latest(net_liquidity, 0.25),
        "m2_yoy": _liq_pct_change_latest(pack.get("M2SL", pd.DataFrame()), 1.0),
        "bank_credit_yoy": _liq_pct_change_latest(pack.get("TOTBKCR", pd.DataFrame()), 1.0),
        "btc": _latest_value(btc_price),
        "btc_3m": _liq_pct_change_latest(btc_price, 0.25),
        "gold": _latest_value(gold_price),
        "gold_3m": _liq_pct_change_latest(gold_price, 0.25),
    }


def _render_liquidity_kpis(summary: Mapping[str, Any]) -> None:
    score = _safe_float(summary.get("score"), 50.0) or 50.0
    cards = [
        _kpi_card("Liquidity regime", f"{score:.0f}/100", str(summary.get("regime", "—"))),
        _kpi_card("G3 CB assets", _fmt(summary.get("g3"), 2, "T"), f"YoY {_fmt_pct(summary.get('g3_yoy'))}"),
        _kpi_card("US net liquidity", _fmt(summary.get("net"), 2, "T"), f"13W {_fmt_pct(summary.get('net_13w'))}"),
        _kpi_card("US M2", _fmt_pct(summary.get("m2_yoy")), "Year-over-year growth"),
        _kpi_card("US bank credit", _fmt_pct(summary.get("bank_credit_yoy")), "Year-over-year growth"),
        _kpi_card("Bitcoin", f"{_fmt(summary.get('btc'), 0)} USD", f"3M {_fmt_pct(summary.get('btc_3m'))}"),
        _kpi_card("Gold", f"{_fmt(summary.get('gold'), 1)} USD/oz", f"3M {_fmt_pct(summary.get('gold_3m'))}"),
        _kpi_card("Method", "Public", "Official/public data first · no silent synthetic fallback"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')


def _liq_plot(pack: Mapping[str, pd.DataFrame], ids: Sequence[str], registry: Mapping[str, Mapping[str, Any]], title: str, window: str, view: str = "Level", frequency: str = "Native", ytitle: str = "") -> None:
    fig = _base_figure(title, ytitle or view, height=435)
    added = 0
    for sid in ids:
        frame = pack.get(sid, pd.DataFrame())
        frame = _liq_window_frame(frame, window)
        frame = _liq_resample(frame, frequency)
        effective_view = "Level" if bool(registry.get(sid, {}).get("already_yoy", False)) and str(view) == "YoY %" else view
        frame = _liq_transform_frame(frame, effective_view)
        if frame.empty:
            continue
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["value"], mode="lines", name=registry.get(sid, {}).get("label", sid), connectgaps=False))
        added += 1
    if added == 0:
        _html(f'<div class="mk-warning">{_escape(title)} unavailable. Review the provider states in Data Quality.</div>')
        return
    st.plotly_chart(fig, use_container_width=True, config=_plot_config(title.lower().replace(" ", "_")))


def _liq_plot_named(frames: Mapping[str, pd.DataFrame], title: str, window: str, view: str = "Level", frequency: str = "Native", ytitle: str = "") -> None:
    fig = _base_figure(title, ytitle or view, height=435)
    added = 0
    for name, raw in frames.items():
        frame = _liq_window_frame(raw, window)
        frame = _liq_resample(frame, frequency)
        frame = _liq_transform_frame(frame, view)
        if frame.empty:
            continue
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["value"], mode="lines", name=name, connectgaps=False))
        added += 1
    if added == 0:
        _html(f'<div class="mk-warning">{_escape(title)} unavailable.</div>')
        return
    st.plotly_chart(fig, use_container_width=True, config=_plot_config(title.lower().replace(" ", "_")))


def _liq_plot_components(components: pd.DataFrame, cols: Sequence[str], title: str, window: str, ytitle: str) -> None:
    if not isinstance(components, pd.DataFrame) or components.empty:
        _html(f'<div class="mk-warning">{_escape(title)} unavailable.</div>')
        return
    work = _liq_window_frame(components, window)
    fig = _base_figure(title, ytitle, height=445)
    for col in cols:
        if col not in work.columns:
            continue
        fig.add_trace(go.Scatter(x=work["date"], y=work[col], mode="lines", name=col, connectgaps=False))
    st.plotly_chart(fig, use_container_width=True, config=_plot_config(title.lower().replace(" ", "_")))


def _liq_plot_money_heatmap(pack: Mapping[str, pd.DataFrame], window: str) -> None:
    mapping = [
        ("United States", "M2SL"),
        ("Euro Area", "EA19MABMM301GYSAM"),
        ("Japan", "JPNMABMM301GYSAM"),
        ("United Kingdom", "GBRMABMM301GYSAM"),
    ]
    series = {}
    for country, sid in mapping:
        frame = _liq_money_growth_frame(pack, sid)
        frame = _liq_window_frame(frame, window)
        if not frame.empty:
            series[country] = frame.set_index("date")["value"].resample("ME").last()
    if not series:
        _html('<div class="mk-warning">Global money-growth heatmap unavailable.</div>')
        return
    wide = pd.DataFrame(series).tail(36).T
    fig = go.Figure(data=go.Heatmap(z=wide.values, x=wide.columns, y=wide.index, colorbar=dict(title="YoY %"), zmid=0, hovertemplate="%{y}<br>%{x|%Y-%m}<br>%{z:.2f}%<extra></extra>"))
    fig.update_layout(title="Broad-money growth heatmap", height=360, margin=dict(l=30, r=20, t=55, b=30), paper_bgcolor="#06101b", plot_bgcolor="#06101b", font=dict(color="#dce5ef"))
    st.plotly_chart(fig, use_container_width=True, config=_plot_config("money_growth_heatmap"))


def _liq_drawdown_frame(price: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(price, pd.DataFrame) or price.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = price[["date", "value"]].dropna().sort_values("date").copy()
    values = pd.to_numeric(work["value"], errors="coerce")
    work["value"] = values / values.cummax() - 1.0
    return work.dropna().reset_index(drop=True)


def _liq_vol_frame(price: pd.DataFrame, window_days: int = 30) -> pd.DataFrame:
    if not isinstance(price, pd.DataFrame) or price.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = price[["date", "value"]].dropna().sort_values("date").copy()
    ret = np.log(pd.to_numeric(work["value"], errors="coerce")).diff()
    work["value"] = ret.rolling(int(window_days), min_periods=max(10, int(window_days) // 2)).std(ddof=1) * math.sqrt(365.0) * 100.0
    return work.dropna().reset_index(drop=True)


def _liq_ratio_frame(a: pd.DataFrame, b: pd.DataFrame, tolerance_days: int = 10) -> pd.DataFrame:
    if not isinstance(a, pd.DataFrame) or a.empty or not isinstance(b, pd.DataFrame) or b.empty:
        return pd.DataFrame(columns=["date", "value"])
    dates = a[["date"]].copy().sort_values("date")
    aligned = _liq_asof_column(dates, a, "a", tolerance_days)
    aligned = _liq_asof_column(aligned, b, "b", tolerance_days)
    aligned["value"] = aligned["a"] / aligned["b"]
    return aligned[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq_rolling_relation(driver: pd.DataFrame, asset: pd.DataFrame, window_weeks: int = 52) -> Tuple[pd.DataFrame, pd.DataFrame]:
    if not isinstance(driver, pd.DataFrame) or driver.empty or not isinstance(asset, pd.DataFrame) or asset.empty:
        empty = pd.DataFrame(columns=["date", "value"])
        return empty, empty
    d = driver.set_index("date")["value"].resample("W-FRI").last().pct_change()
    a = asset.set_index("date")["value"].resample("W-FRI").last().pct_change()
    aligned = pd.concat([d.rename("driver"), a.rename("asset")], axis=1).dropna()
    corr = aligned["asset"].rolling(window_weeks, min_periods=max(20, window_weeks // 2)).corr(aligned["driver"])
    var = aligned["driver"].rolling(window_weeks, min_periods=max(20, window_weeks // 2)).var(ddof=1)
    cov = aligned["asset"].rolling(window_weeks, min_periods=max(20, window_weeks // 2)).cov(aligned["driver"])
    beta = cov / var.replace(0, np.nan)
    return corr.dropna().rename("value").reset_index(), beta.dropna().rename("value").reset_index()


def _liq_lag_scan(driver: pd.DataFrame, asset: pd.DataFrame, max_lag_weeks: int = 26, horizon_weeks: int = 13) -> pd.DataFrame:
    if not isinstance(driver, pd.DataFrame) or driver.empty or not isinstance(asset, pd.DataFrame) or asset.empty:
        return pd.DataFrame(columns=["Lag Weeks", "Correlation", "Observations"])
    d_level = driver.set_index("date")["value"].resample("W-FRI").last()
    a_level = asset.set_index("date")["value"].resample("W-FRI").last()
    d_impulse = d_level.pct_change(horizon_weeks)
    future_asset = a_level.pct_change(horizon_weeks).shift(-horizon_weeks)
    rows = []
    for lag in range(0, int(max_lag_weeks) + 1, 2):
        aligned = pd.concat([d_impulse.shift(lag).rename("liquidity"), future_asset.rename("asset")], axis=1).dropna()
        rows.append({"Lag Weeks": lag, "Correlation": aligned["liquidity"].corr(aligned["asset"]) if len(aligned) >= 24 else np.nan, "Observations": len(aligned)})
    return pd.DataFrame(rows)


def _liq_plot_lag_scan(scan: pd.DataFrame, title: str) -> None:
    if not isinstance(scan, pd.DataFrame) or scan.empty or scan["Correlation"].notna().sum() == 0:
        _html(f'<div class="mk-warning">{_escape(title)} unavailable: insufficient overlapping history.</div>')
        return
    fig = _base_figure(title, "Correlation", height=390)
    fig.add_trace(go.Bar(x=scan["Lag Weeks"], y=scan["Correlation"], customdata=scan[["Observations"]], hovertemplate="Lag %{x} weeks<br>Correlation %{y:.3f}<br>Obs %{customdata[0]}<extra></extra>"))
    fig.update_yaxes(range=[-1, 1])
    st.plotly_chart(fig, use_container_width=True, config=_plot_config("liquidity_lag_scan"))


def _liq_quality_summary(quality_df: pd.DataFrame) -> Dict[str, Any]:
    if quality_df is None or quality_df.empty:
        return {"loaded": 0, "total": 0, "fresh": 0, "stale": 0, "latest": "—"}
    loaded = quality_df["Status"].astype(str).isin(["live", "cache", "OK"])
    dates = pd.to_datetime(quality_df["Latest Date"], errors="coerce")
    latest = dates.max()
    return {
        "loaded": int(loaded.sum()),
        "total": int(len(quality_df)),
        "fresh": int((quality_df["Freshness"].astype(str) == "Fresh").sum()),
        "stale": int(quality_df["Freshness"].astype(str).isin(["Lagged", "Stale"]).sum()),
        "latest": latest.strftime("%Y-%m-%d") if pd.notna(latest) else "—",
    }


def _liquidity_controls() -> Tuple[str, str, str, int, bool]:
    c1, c2, c3, c4, c5 = st.columns([1.0, 1.0, 1.0, 1.0, 1.25], gap="small")
    with c1:
        window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y", "Max"], index=2, key="market_liq_window")
    with c2:
        view = st.selectbox("View", ["Level", "YoY %", "Z-score", "Indexed 100"], index=0, key="market_liq_view")
    with c3:
        frequency = st.selectbox("Sampling", ["Native", "Weekly", "Monthly"], index=0, key="market_liq_frequency")
    with c4:
        page_size = int(st.selectbox("Chart-book size", [4, 6, 8, 10], index=1, key="market_liq_page_size"))
    with c5:
        show_missing = st.toggle("Show missing/provider rows", value=True, key="market_liq_show_missing")
    st.session_state[MARKET_WINDOW_KEY] = window
    st.session_state[MARKET_VIEW_KEY] = view
    return window, view, frequency, page_size, show_missing


