def _render_placeholder_page(page: str) -> None:
    meta = MARKET_PAGE_META[page]
    _html('<div class="mk-warning"><b>Data route not activated in V1.</b> The navigation and page contract are stable; no synthetic chart is displayed.</div>')
    _section("Planned workstation", "The section is reserved in the router and will be implemented without changing the Economy routes.")
    blocks = []
    for idx, item in enumerate(meta.get("planned", []), 1):
        blocks.append(
            '<div class="mk-placeholder">'
            f'<h4>{idx:02d} · {_escape(item)}</h4>'
            '<p>Provider contract, transformations, chart registry, quality controls and drill-down will be added within this isolated page.</p>'
            '</div>'
        )
    _html('<div class="mk-placeholder-grid">' + ''.join(blocks) + '</div>')

    roadmap = pd.DataFrame(
        [
            {"Layer": "Navigation", "Status": "Implemented", "Contract": f'market_page = "{page}"'},
            {"Layer": "Session state", "Status": "Implemented", "Contract": "market_* keys only"},
            {"Layer": "Provider registry", "Status": "Reserved", "Contract": str(meta.get("providers", ""))},
            {"Layer": "Production data", "Status": "Not loaded", "Contract": "No silent synthetic fallback"},
            {"Layer": "Quality", "Status": "Required before activation", "Contract": "Freshness · source · unit · frequency"},
        ]
    )
    _section("Activation contract", "A page becomes live only when its data and quality layers pass offline and network smoke tests.")
    _html_table(roadmap)


