def _init_market_state() -> None:
    defaults = {
        MARKET_PAGE_KEY: "fixed-income",
        MARKET_SUBPAGE_KEY: "overview",
        MARKET_WINDOW_KEY: "5Y",
        MARKET_VIEW_KEY: "Level",
        MARKET_FOCUS_KEY: "US",
        MARKET_QUALITY_KEY: "Standard",
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value



def render_market_intelligence(
    ticker: str,
    price_data: pd.DataFrame,
    analysis: Optional[dict] = None,
) -> None:
    """Render the selected Markets page inside the Macro / Central Banks mode."""
    _init_market_state()
    _market_css()
    ticker = str(ticker or "").upper().strip()
    analysis = analysis or {}

    valid_pages = {key for key, _ in MARKET_PAGES}
    page = str(st.session_state.get(MARKET_PAGE_KEY, "fixed-income")).strip().lower()
    if page not in valid_pages:
        page = "fixed-income"
        st.session_state[MARKET_PAGE_KEY] = page

    label = MARKET_PAGE_META[page]["label"]
    _html('<div class="mk-shell">')
    try:
        _deskbar(label)
        _hero(page)
        if page == "liquidity":
            _render_liquidity_page(ticker, price_data, analysis)
        elif page == "fixed-income":
            _render_fixed_income_page(ticker, price_data, analysis)
        else:
            _render_placeholder_page(page)
        _html(
            '<div class="mk-footer">'
            f'{_escape(MARKET_INTELLIGENCE_VERSION)} · active route {_escape(page)} · '
            'Economy V31 remains delegated and unchanged · no synthetic production histories.'
            '</div>'
        )
    finally:
        _html('</div>')


