def _liq3_cache_paths(namespace: str, key: str) -> Tuple[_liq3_Path, _liq3_Path]:
    safe = _liq3_hashlib.sha256(str(key).encode("utf-8")).hexdigest()[:20]
    folder = LIQ3_CACHE_ROOT / namespace
    return folder / f"{safe}.csv", folder / f"{safe}.json"


def _liq3_read_disk(namespace: str, key: str) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    data_path, meta_path = _liq3_cache_paths(namespace, key)
    if not data_path.exists() or not meta_path.exists():
        return pd.DataFrame(columns=["date", "value"]), {}
    try:
        frame = pd.read_csv(data_path)
        frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.tz_localize(None)
        frame["value"] = pd.to_numeric(frame["value"], errors="coerce")
        frame = frame.dropna().sort_values("date").reset_index(drop=True)
        meta = _liq3_json.loads(meta_path.read_text(encoding="utf-8"))
        return frame, meta if isinstance(meta, dict) else {}
    except Exception:
        return pd.DataFrame(columns=["date", "value"]), {}


def _liq3_write_disk(namespace: str, key: str, frame: pd.DataFrame, meta: Mapping[str, Any]) -> None:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return
    data_path, meta_path = _liq3_cache_paths(namespace, key)
    try:
        data_path.parent.mkdir(parents=True, exist_ok=True)
        tmp_data = data_path.with_suffix(".tmp.csv")
        tmp_meta = meta_path.with_suffix(".tmp.json")
        frame[["date", "value"]].to_csv(tmp_data, index=False)
        payload = dict(meta)
        payload["cached_at_utc"] = datetime.now(timezone.utc).isoformat()
        tmp_meta.write_text(_liq3_json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        tmp_data.replace(data_path)
        tmp_meta.replace(meta_path)
    except Exception:
        pass


def _liq3_cache_age_hours(meta: Mapping[str, Any]) -> Optional[float]:
    raw = str(meta.get("cached_at_utc", "") or "")
    if not raw:
        return None
    try:
        stamp = pd.Timestamp(raw)
        if stamp.tzinfo is None:
            stamp = stamp.tz_localize("UTC")
        return max(0.0, (pd.Timestamp.now(tz="UTC") - stamp).total_seconds() / 3600.0)
    except Exception:
        return None


def _liq3_parse_fred_csv(text: str, series_id: str, start_date: str) -> pd.DataFrame:
    raw = pd.read_csv(io.StringIO(text))
    if raw.empty or len(raw.columns) < 2:
        return pd.DataFrame(columns=["date", "value"])
    date_col = raw.columns[0]
    value_col = series_id if series_id in raw.columns else raw.columns[1]
    out = raw[[date_col, value_col]].copy()
    out.columns = ["date", "value"]
    out["date"] = pd.to_datetime(out["date"], errors="coerce").dt.tz_localize(None)
    out["value"] = pd.to_numeric(out["value"].replace(".", np.nan), errors="coerce")
    out = out.dropna().sort_values("date")
    if start_date:
        out = out.loc[out["date"] >= pd.Timestamp(start_date)]
    return out.reset_index(drop=True)


def _liq3_parse_fred_api(payload: Mapping[str, Any], start_date: str) -> pd.DataFrame:
    rows = payload.get("observations", []) if isinstance(payload, Mapping) else []
    if not isinstance(rows, list):
        return pd.DataFrame(columns=["date", "value"])
    out = pd.DataFrame(rows)
    if out.empty or "date" not in out.columns or "value" not in out.columns:
        return pd.DataFrame(columns=["date", "value"])
    out = out[["date", "value"]].copy()
    out["date"] = pd.to_datetime(out["date"], errors="coerce").dt.tz_localize(None)
    out["value"] = pd.to_numeric(out["value"].replace(".", np.nan), errors="coerce")
    out = out.dropna().sort_values("date")
    if start_date:
        out = out.loc[out["date"] >= pd.Timestamp(start_date)]
    return out.reset_index(drop=True)


def _liq3_fetch_fred_one(series_id: str, start_date: str, allow_network: bool = True, force_network: bool = False) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    sid = str(series_id).upper().strip()
    cache_key = f"{sid}|{start_date}"
    cached, cached_meta = _liq3_read_disk("fred", cache_key)
    age = _liq3_cache_age_hours(cached_meta)
    if not force_network and not cached.empty and age is not None and age <= LIQ3_CACHE_TTL_HOURS:
        return cached, {"status": "cache", "source": cached_meta.get("source", "FRED disk cache"), "message": "fresh disk cache", "network_error": False}
    if not allow_network:
        if not cached.empty:
            return cached, {"status": "stale-cache", "source": cached_meta.get("source", "FRED stale disk cache"), "message": "provider circuit open; stale cache used", "network_error": True}
        return pd.DataFrame(columns=["date", "value"]), {"status": "provider-unavailable", "source": "FRED", "message": "provider circuit open", "network_error": True}
    if not REQUESTS_AVAILABLE or requests is None:
        if not cached.empty:
            return cached, {"status": "stale-cache", "source": cached_meta.get("source", "FRED stale disk cache"), "message": "requests unavailable; stale cache used", "network_error": True}
        return pd.DataFrame(columns=["date", "value"]), {"status": "provider-required", "source": "FRED", "message": "requests unavailable", "network_error": True}

    api_key = _secret_or_env("FRED_API_KEY", "")
    try:
        if api_key:
            response = requests.get(
                LIQ3_FRED_API_URL,
                params={"series_id": sid, "api_key": api_key, "file_type": "json", "observation_start": start_date, "sort_order": "asc"},
                timeout=(LIQ3_CONNECT_TIMEOUT, LIQ3_READ_TIMEOUT),
                headers={"User-Agent": "QuantTerminal-MarketDesk/3.0"},
            )
            response.raise_for_status()
            frame = _liq3_parse_fred_api(response.json(), start_date)
            source = "FRED API"
        else:
            response = requests.get(
                FRED_CSV_URL.format(series_id=quote(sid)),
                timeout=(LIQ3_CONNECT_TIMEOUT, LIQ3_READ_TIMEOUT),
                headers={"User-Agent": "QuantTerminal-MarketDesk/3.0"},
            )
            response.raise_for_status()
            frame = _liq3_parse_fred_csv(response.text, sid, start_date)
            source = "FRED public CSV"
        if frame.empty:
            raise ValueError("No observations returned")
        meta = {"status": "live", "source": source, "message": "", "network_error": False}
        _liq3_write_disk("fred", cache_key, frame, meta)
        return frame, meta
    except Exception as exc:
        message = str(exc)[:220]
        if not cached.empty:
            return cached, {"status": "stale-cache", "source": cached_meta.get("source", "FRED stale disk cache"), "message": message, "network_error": True}
        return pd.DataFrame(columns=["date", "value"]), {"status": "provider-unavailable", "source": "FRED API" if api_key else "FRED public CSV", "message": message, "network_error": True}


@st.cache_data(ttl=21600, show_spinner=False)
def _liq3_load_fred_pack(series_ids: Tuple[str, ...], start_date: str = "1990-01-01", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    force_network = bool(refresh_token)
    ids = tuple(dict.fromkeys(str(s).upper().strip() for s in series_ids if str(s).strip()))
    started = time.perf_counter()
    pack: Dict[str, pd.DataFrame] = {}
    metas: Dict[str, Dict[str, Any]] = {}
    if not ids:
        return pack, pd.DataFrame(), {"elapsed": 0.0, "circuit_open": False}

    probe = "WALCL" if "WALCL" in ids else ids[0]
    frame, meta = _liq3_fetch_fred_one(probe, start_date, allow_network=True, force_network=force_network)
    pack[probe], metas[probe] = frame, meta
    circuit_open = bool(meta.get("network_error", False) and meta.get("status") not in {"cache", "live"})
    remaining = [sid for sid in ids if sid != probe]

    if circuit_open:
        for sid in remaining:
            f, m = _liq3_fetch_fred_one(sid, start_date, allow_network=False, force_network=False)
            pack[sid], metas[sid] = f, m
    else:
        with _liq3_ThreadPoolExecutor(max_workers=min(LIQ3_MAX_WORKERS, max(1, len(remaining)))) as executor:
            futures = {executor.submit(_liq3_fetch_fred_one, sid, start_date, True, force_network): sid for sid in remaining}
            for future in _liq3_as_completed(futures):
                sid = futures[future]
                try:
                    f, m = future.result()
                except Exception as exc:
                    f, m = pd.DataFrame(columns=["date", "value"]), {"status": "provider-unavailable", "source": "FRED", "message": str(exc)[:180], "network_error": True}
                pack[sid], metas[sid] = f, m

    rows: List[Dict[str, Any]] = []
    for sid in ids:
        frame = pack.get(sid, pd.DataFrame())
        meta = metas.get(sid, {})
        spec = LIQ3_FRED_SERIES.get(sid, {})
        latest = _latest_date(frame)
        status = str(meta.get("status", "unknown"))
        rows.append({
            "Series / Instrument": sid,
            "Label": spec.get("label", sid),
            "Category": spec.get("category", "Other"),
            "Source": meta.get("source", "FRED"),
            "Status": status,
            "Freshness": _liq_freshness(latest, int(spec.get("expected_days", 30))) if not frame.empty else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
            "Unit": spec.get("unit", ""),
            "Frequency": spec.get("frequency", ""),
            "Message": meta.get("message", ""),
        })
    elapsed = time.perf_counter() - started
    return pack, pd.DataFrame(rows), {"elapsed": elapsed, "circuit_open": circuit_open, "provider": "FRED API" if _secret_or_env("FRED_API_KEY", "") else "FRED public CSV"}


def _liq3_market_cache_key(symbol: str, period: str) -> str:
    return f"{symbol}|{period}|1d"


def _liq3_read_market_cache(symbol: str, period: str) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    return _liq3_read_disk("market", _liq3_market_cache_key(symbol, period))


def _liq3_write_market_cache(symbol: str, period: str, frame: pd.DataFrame, source: str) -> None:
    _liq3_write_disk("market", _liq3_market_cache_key(symbol, period), frame, {"status": "live", "source": source, "message": ""})


@st.cache_data(ttl=1800, show_spinner=False)
def _liq3_load_market_pack(symbols: Tuple[str, ...], period: str = "10y", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    force_network = bool(refresh_token)
    ids = tuple(dict.fromkeys(str(s).strip() for s in symbols if str(s).strip()))
    started = time.perf_counter()
    pack: Dict[str, pd.DataFrame] = {}
    rows: List[Dict[str, Any]] = []
    missing: List[str] = []
    cached_meta: Dict[str, Dict[str, Any]] = {}
    for symbol in ids:
        frame, meta = _liq3_read_market_cache(symbol, period)
        age = _liq3_cache_age_hours(meta)
        if not force_network and not frame.empty and age is not None and age <= 0.5:
            pack[symbol] = frame
            cached_meta[symbol] = {"status": "cache", "source": meta.get("source", "Yahoo/yfinance disk cache"), "message": "fresh disk cache"}
        else:
            if not frame.empty:
                pack[symbol] = frame
                cached_meta[symbol] = {"status": "stale-cache", "source": meta.get("source", "Yahoo/yfinance stale cache"), "message": "stale cache; live refresh attempted"}
            missing.append(symbol)

    live_error = ""
    if missing and YFINANCE_AVAILABLE and yf is not None:
        try:
            raw = yf.download(
                list(missing), period=period, interval="1d", progress=False,
                auto_adjust=True, threads=True, group_by="ticker", timeout=8,
            )
            if raw is not None and not raw.empty:
                for symbol in missing:
                    sub = None
                    if isinstance(raw.columns, pd.MultiIndex):
                        level0 = [str(x) for x in raw.columns.get_level_values(0)]
                        if symbol in level0:
                            sub = raw[symbol].copy()
                        else:
                            # Alternate yfinance layout: field on level 0, symbol on level 1.
                            try:
                                sub = raw.xs(symbol, axis=1, level=1).copy()
                            except Exception:
                                sub = None
                    elif len(missing) == 1:
                        sub = raw.copy()
                    if sub is None or sub.empty:
                        continue
                    sub = sub.reset_index()
                    sub.columns = [str(c).strip().lower().replace(" ", "_") for c in sub.columns]
                    date_col = "date" if "date" in sub.columns else "datetime" if "datetime" in sub.columns else sub.columns[0]
                    close_candidates = [c for c in sub.columns if c in {"close", "adj_close"} or "close" in c]
                    close_col = close_candidates[0] if close_candidates else None
                    if close_col is None:
                        continue
                    frame = pd.DataFrame({
                        "date": pd.to_datetime(sub[date_col], errors="coerce").dt.tz_localize(None),
                        "value": pd.to_numeric(sub[close_col], errors="coerce"),
                    }).dropna().sort_values("date").reset_index(drop=True)
                    if not frame.empty:
                        pack[symbol] = frame
                        cached_meta[symbol] = {"status": "live", "source": "Yahoo/yfinance batch", "message": ""}
                        _liq3_write_market_cache(symbol, period, frame, "Yahoo/yfinance batch")
        except Exception as exc:
            live_error = str(exc)[:220]
    elif missing and (not YFINANCE_AVAILABLE or yf is None):
        live_error = "yfinance unavailable"

    for symbol in ids:
        frame = pack.get(symbol, pd.DataFrame(columns=["date", "value"]))
        meta = cached_meta.get(symbol, {})
        status = str(meta.get("status", "provider-unavailable" if frame.empty else "stale-cache"))
        latest = _latest_date(frame)
        spec = LIQ3_MARKET_SYMBOLS.get(symbol, {})
        rows.append({
            "Series / Instrument": symbol,
            "Label": spec.get("label", symbol),
            "Category": spec.get("category", "Market Data"),
            "Source": meta.get("source", "Yahoo/yfinance"),
            "Status": status,
            "Freshness": _liq_freshness(latest, 8) if not frame.empty else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
            "Unit": spec.get("unit", ""),
            "Frequency": "Daily",
            "Message": meta.get("message", live_error),
        })
    return pack, pd.DataFrame(rows), {"elapsed": time.perf_counter() - started, "provider": "Yahoo/yfinance batch", "message": live_error}


@st.cache_data(ttl=900, show_spinner=False)
def _liq3_crypto_snapshot() -> Tuple[Dict[str, Any], Dict[str, Any]]:
    if not REQUESTS_AVAILABLE or requests is None:
        return {}, {"status": "provider-required", "source": "CoinGecko", "message": "requests unavailable"}
    headers, base = _coingecko_headers_and_base()
    try:
        response = requests.get(f"{base}/global", headers=headers, timeout=(2.5, 5.0))
        response.raise_for_status()
        data = response.json().get("data", {})
        snapshot = {
            "total_market_cap_usd": _safe_float((data.get("total_market_cap") or {}).get("usd")),
            "total_volume_usd": _safe_float((data.get("total_volume") or {}).get("usd")),
            "btc_dominance": _safe_float((data.get("market_cap_percentage") or {}).get("btc")),
            "eth_dominance": _safe_float((data.get("market_cap_percentage") or {}).get("eth")),
            "market_cap_change_24h": _safe_float(data.get("market_cap_change_percentage_24h_usd")),
            "active_cryptocurrencies": data.get("active_cryptocurrencies"),
            "markets": data.get("markets"),
        }
        # Stablecoin category is optional and deliberately short-timeout.
        try:
            stable = requests.get(
                f"{base}/coins/markets",
                params={"vs_currency": "usd", "category": "stablecoins", "order": "market_cap_desc", "per_page": 250, "page": 1, "sparkline": "false"},
                headers=headers, timeout=(2.5, 5.0),
            )
            stable.raise_for_status()
            payload = stable.json()
            snapshot["stablecoin_market_cap_usd"] = float(np.nansum([_safe_float(x.get("market_cap"), 0.0) or 0.0 for x in payload])) if isinstance(payload, list) else None
        except Exception:
            snapshot["stablecoin_market_cap_usd"] = None
        return snapshot, {"status": "live", "source": "CoinGecko API", "message": ""}
    except Exception as exc:
        return {}, {"status": "provider-unavailable", "source": "CoinGecko API", "message": str(exc)[:220]}


def _liq3_frame(df: Any) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(columns=["date", "value"])
    if "value" in df.columns:
        out = df[["date", "value"]].copy()
    elif "close" in df.columns:
        out = df[["date", "close"]].rename(columns={"close": "value"})
    else:
        return pd.DataFrame(columns=["date", "value"])
    out["date"] = pd.to_datetime(out["date"], errors="coerce").dt.tz_localize(None)
    out["value"] = pd.to_numeric(out["value"], errors="coerce")
    return out.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _liq3_scale(df: pd.DataFrame, divisor: float = 1.0) -> pd.DataFrame:
    out = _liq3_frame(df)
    if out.empty or divisor == 0:
        return out
    out["value"] = out["value"] / float(divisor)
    return out


def _liq3_time_change(df: pd.DataFrame, days: int, percent: bool = True) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    base = work.copy().rename(columns={"value": "current"})
    lag = work.copy()
    lag["date"] = lag["date"] + pd.Timedelta(days=int(days))
    lag = lag.rename(columns={"value": "previous"})
    merged = pd.merge_asof(base.sort_values("date"), lag.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=max(14, int(days * 0.15))))
    if percent:
        merged["value"] = (merged["current"] / merged["previous"] - 1.0) * 100.0
    else:
        merged["value"] = merged["current"] - merged["previous"]
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq3_index(df: pd.DataFrame) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    first = _safe_float(work["value"].iloc[0])
    if first in (None, 0):
        return pd.DataFrame(columns=["date", "value"])
    work["value"] = work["value"] / float(first) * 100.0
    return work


def _liq3_zscore(df: pd.DataFrame, days: int = 1825) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    dates = work["date"]
    values = work["value"].astype(float)
    median_days = max(1.0, float(dates.diff().dt.days.dropna().median())) if len(dates) > 2 else 7.0
    periods = max(20, int(round(days / median_days)))
    mean = values.rolling(periods, min_periods=max(12, periods // 3)).mean()
    std = values.rolling(periods, min_periods=max(12, periods // 3)).std(ddof=1).replace(0, np.nan)
    work["value"] = (values - mean) / std
    return work.replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq3_drawdown(df: pd.DataFrame) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    peak = work["value"].cummax().replace(0, np.nan)
    work["value"] = (work["value"] / peak - 1.0) * 100.0
    return work.dropna().reset_index(drop=True)


def _liq3_vol(df: pd.DataFrame, window: int = 30) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    returns = work["value"].pct_change()
    work["value"] = returns.rolling(int(window), min_periods=max(10, int(window // 2))).std(ddof=1) * math.sqrt(TRADING_DAYS) * 100.0
    return work.dropna().reset_index(drop=True)


def _liq3_rolling_return(df: pd.DataFrame, days: int) -> pd.DataFrame:
    return _liq3_time_change(df, days, percent=True)


def _liq3_ratio(a: pd.DataFrame, b: pd.DataFrame, multiplier: float = 1.0) -> pd.DataFrame:
    left = _liq3_frame(a).rename(columns={"value": "a"})
    right = _liq3_frame(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=10)).dropna()
    merged["value"] = merged["a"] / merged["b"].replace(0, np.nan) * float(multiplier)
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq3_align_returns(a: pd.DataFrame, b: pd.DataFrame, frequency: str = "W-FRI") -> pd.DataFrame:
    left = _liq3_frame(a)
    right = _liq3_frame(b)
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "a", "b"])
    la = left.set_index("date")["value"].resample(frequency).last().pct_change(fill_method=None)
    rb = right.set_index("date")["value"].resample(frequency).last().pct_change(fill_method=None)
    return pd.concat([la.rename("a"), rb.rename("b")], axis=1).dropna().reset_index()


def _liq3_rolling_pair(a: pd.DataFrame, b: pd.DataFrame, weeks: int = 26, metric: str = "corr") -> pd.DataFrame:
    aligned = _liq3_align_returns(a, b)
    if aligned.empty:
        return pd.DataFrame(columns=["date", "value"])
    if metric == "beta":
        cov = aligned["a"].rolling(weeks, min_periods=max(12, weeks // 2)).cov(aligned["b"])
        var = aligned["b"].rolling(weeks, min_periods=max(12, weeks // 2)).var().replace(0, np.nan)
        value = cov / var
    else:
        value = aligned["a"].rolling(weeks, min_periods=max(12, weeks // 2)).corr(aligned["b"])
    return pd.DataFrame({"date": aligned["date"], "value": value}).replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq3_debt_to_gdp(debt: pd.DataFrame, gdp: pd.DataFrame, debt_unit: str) -> pd.DataFrame:
    left = _liq3_frame(debt).rename(columns={"value": "debt"})
    right = _liq3_frame(gdp).rename(columns={"value": "gdp"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=150)).dropna()
    if debt_unit == "USD mn":
        debt_bn = merged["debt"] / 1000.0
    else:
        debt_bn = merged["debt"]
    merged["value"] = debt_bn / merged["gdp"].replace(0, np.nan) * 100.0
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _liq3_build_context(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], snapshot: Optional[Mapping[str, Any]] = None) -> Dict[str, Any]:
    f = {k: _liq3_frame(v) for k, v in fred.items()}
    m = {k: _liq3_frame(v) for k, v in market.items()}
    # Native-unit conversions.
    fed_t = _liq3_scale(f.get("WALCL", pd.DataFrame()), 1_000_000.0)
    ecb_t_eur = _liq3_scale(f.get("ECBASSETSW", pd.DataFrame()), 1_000_000.0)
    boj_t_jpy = _liq3_scale(f.get("JPNASSETS", pd.DataFrame()), 10_000.0)
    tga_t = _liq3_scale(f.get("WDTGAL", pd.DataFrame()), 1_000_000.0)
    rrp_t = _liq3_scale(f.get("RRPONTSYD", pd.DataFrame()), 1_000.0)
    reserves_t = _liq3_scale(f.get("WRESBAL", pd.DataFrame()), 1_000_000.0)
    m2_t = _liq3_scale(f.get("M2SL", pd.DataFrame()), 1_000.0)

    # G3 in contemporaneous USD. All three banks and both FX conversions are required.
    valid = [x for x in (f.get("WALCL"), f.get("ECBASSETSW"), f.get("JPNASSETS")) if isinstance(x, pd.DataFrame) and not x.empty]
    g3 = pd.DataFrame(columns=["date", "value"])
    g3_comp = pd.DataFrame()
    if len(valid) == 3:
        start = min(pd.to_datetime(x["date"]).min() for x in valid)
        end = max(pd.to_datetime(x["date"]).max() for x in valid)
        base = pd.DataFrame({"date": pd.date_range(start, end, freq="W-FRI")})
        aligned = _liq_asof_column(base, f.get("WALCL", pd.DataFrame()), "fed_mn", 16)
        aligned = _liq_asof_column(aligned, f.get("ECBASSETSW", pd.DataFrame()), "ecb_mn_eur", 21)
        aligned = _liq_asof_column(aligned, f.get("JPNASSETS", pd.DataFrame()), "boj_100m_jpy", 55)
        aligned = _liq_asof_column(aligned, f.get("DEXUSEU", pd.DataFrame()), "usd_per_eur", 14)
        aligned = _liq_asof_column(aligned, f.get("DEXJPUS", pd.DataFrame()), "jpy_per_usd", 14)
        aligned["Fed"] = aligned["fed_mn"] / 1_000_000.0
        aligned["ECB"] = aligned["ecb_mn_eur"] / 1_000_000.0 * aligned["usd_per_eur"]
        aligned["BoJ"] = aligned["boj_100m_jpy"] / 10_000.0 / aligned["jpy_per_usd"]
        aligned["value"] = aligned[["Fed", "ECB", "BoJ"]].sum(axis=1, min_count=3)
        g3 = aligned[["date", "value"]].dropna().reset_index(drop=True)
        g3_comp = aligned[["date", "Fed", "ECB", "BoJ", "value"]].dropna(subset=["value"]).reset_index(drop=True)

    # Fed assets - TGA - ON RRP, all converted to USD trillions.
    net = pd.DataFrame(columns=["date", "value"])
    net_comp = pd.DataFrame()
    if not f.get("WALCL", pd.DataFrame()).empty:
        base = pd.DataFrame({"date": pd.to_datetime(f["WALCL"]["date"], errors="coerce").dropna().sort_values().unique()})
        aligned = _liq_asof_column(base, f.get("WALCL", pd.DataFrame()), "fed_mn", 12)
        aligned = _liq_asof_column(aligned, f.get("WDTGAL", pd.DataFrame()), "tga_mn", 15)
        aligned = _liq_asof_column(aligned, f.get("RRPONTSYD", pd.DataFrame()), "rrp_bn", 8)
        aligned["Fed"] = aligned["fed_mn"] / 1_000_000.0
        aligned["TGA"] = aligned["tga_mn"] / 1_000_000.0
        aligned["RRP"] = aligned["rrp_bn"] / 1_000.0
        aligned["value"] = aligned["Fed"] - aligned["TGA"] - aligned["RRP"]
        net = aligned[["date", "value"]].dropna().reset_index(drop=True)
        net_comp = aligned[["date", "Fed", "TGA", "RRP", "value"]].dropna(subset=["value"]).reset_index(drop=True)

    cpi = f.get("CPIAUCSL", pd.DataFrame())
    real_m2 = pd.DataFrame(columns=["date", "value"])
    if not f.get("M2SL", pd.DataFrame()).empty and not cpi.empty:
        left = f["M2SL"].rename(columns={"value": "m2"})
        right = cpi.rename(columns={"value": "cpi"})
        merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=60)).dropna()
        merged["value"] = merged["m2"] / merged["cpi"].replace(0, np.nan) * 100.0
        real_m2 = merged[["date", "value"]].dropna().reset_index(drop=True)

    corp_gdp = _liq3_debt_to_gdp(f.get("BCNSDODNS", pd.DataFrame()), f.get("GDP", pd.DataFrame()), "USD mn")
    hh_gdp = _liq3_debt_to_gdp(f.get("CMDEBT", pd.DataFrame()), f.get("GDP", pd.DataFrame()), "USD bn")
    mort_gdp = _liq3_debt_to_gdp(f.get("HHMSDODNS", pd.DataFrame()), f.get("GDP", pd.DataFrame()), "USD mn")
    cons_gdp = _liq3_debt_to_gdp(f.get("HCCSDODNS", pd.DataFrame()), f.get("GDP", pd.DataFrame()), "USD mn")

    gold = f.get("GOLDAMGBD228NLBM", pd.DataFrame()) if not f.get("GOLDAMGBD228NLBM", pd.DataFrame()).empty else m.get("GC=F", pd.DataFrame())
    silver = f.get("SLVPRUSD", pd.DataFrame()) if not f.get("SLVPRUSD", pd.DataFrame()).empty else m.get("SI=F", pd.DataFrame())
    btc = m.get("BTC-USD", pd.DataFrame())
    eth = m.get("ETH-USD", pd.DataFrame())

    frames: Dict[str, pd.DataFrame] = {
        **{f"FRED:{k}": v for k, v in f.items()},
        **{f"MKT:{k}": v for k, v in m.items()},
        "FED_T": fed_t, "ECB_T_EUR": ecb_t_eur, "BOJ_T_JPY": boj_t_jpy,
        "TGA_T": tga_t, "RRP_T": rrp_t, "RESERVES_T": reserves_t, "M2_T": m2_t,
        "G3": g3, "NET": net, "REAL_M2": real_m2,
        "CORP_GDP": corp_gdp, "HH_GDP": hh_gdp, "MORT_GDP": mort_gdp, "CONS_GDP": cons_gdp,
        "GOLD": gold, "SILVER": silver, "BTC": btc, "ETH": eth,
        "GOLD_SILVER": _liq3_ratio(gold, silver),
        "ETH_BTC": _liq3_ratio(eth, btc),
        "BTC_GOLD": _liq3_ratio(btc, gold),
        "GOLD_BTC": _liq3_ratio(gold, btc),
        "GDX_GOLD": _liq3_ratio(m.get("GDX", pd.DataFrame()), gold),
        "BANK_CREDIT_M2": _liq3_ratio(f.get("TOTBKCR", pd.DataFrame()), f.get("M2SL", pd.DataFrame())),
    }
    return {"fred": f, "market": m, "frames": frames, "snapshot": dict(snapshot or {}), "g3_components": g3_comp, "net_components": net_comp}


def _liq3_latest(df: pd.DataFrame) -> Optional[float]:
    return _latest_value(_liq3_frame(df))


def _liq3_pct_latest(df: pd.DataFrame, days: int) -> Optional[float]:
    return _liq3_latest(_liq3_time_change(df, days, percent=True))


def _liq3_score(context: Mapping[str, Any]) -> Tuple[Dict[str, Any], pd.DataFrame]:
    frames = context.get("frames", {})
    inputs = [
        ("G3 central-bank assets YoY", 0.23, _liq3_latest(_liq3_time_change(frames.get("G3", pd.DataFrame()), 365, True)), (-8.0, 18.0), False, "G3 aggregate in contemporaneous USD"),
        ("US net liquidity 13W", 0.22, _liq3_latest(_liq3_time_change(frames.get("NET", pd.DataFrame()), 91, True)), (-8.0, 8.0), False, "Fed assets minus TGA minus ON RRP"),
        ("US M2 YoY", 0.17, _liq3_latest(_liq3_time_change(frames.get("FRED:M2SL", pd.DataFrame()), 365, True)), (-5.0, 12.0), False, "Broad-money impulse"),
        ("Ex-US G3 broad-money YoY", 0.10, _liq_ex_us_money_growth_latest(context.get("fred", {})), (-2.0, 10.0), False, "Mean of published Euro area, Japan and UK growth rates"),
        ("US bank credit YoY", 0.12, _liq3_latest(_liq3_time_change(frames.get("FRED:TOTBKCR", pd.DataFrame()), 365, True)), (-5.0, 12.0), False, "Commercial-bank balance-sheet channel"),
        ("US reserve balances 13W", 0.08, _liq3_latest(_liq3_time_change(frames.get("FRED:WRESBAL", pd.DataFrame()), 91, True)), (-12.0, 12.0), False, "Bank-reserve impulse"),
        ("Broad dollar 13W", 0.08, _liq3_latest(_liq3_time_change(frames.get("FRED:DTWEXBGS", pd.DataFrame()), 91, True)), (-8.0, 8.0), True, "A weaker dollar eases global financial conditions"),
    ]
    rows = []
    numerator = 0.0
    denominator = 0.0
    available = 0
    for name, weight, value, bounds, inverse, definition in inputs:
        score = None
        if value is not None and np.isfinite(value):
            low, high = bounds
            score = max(0.0, min(100.0, (float(value) - low) / (high - low) * 100.0))
            if inverse:
                score = 100.0 - score
            numerator += weight * score
            denominator += weight
            available += 1
        rows.append({
            "Component": name,
            "Weight": f"{weight:.0%}",
            "Latest": "—" if value is None else f"{value:+.2f}%",
            "Score": "—" if score is None else f"{score:.1f}",
            "Definition": definition,
            "Contribution": 0.0 if score is None else round(weight * score, 2),
        })
    composite = numerator / denominator if denominator > 0 and available >= 3 else None
    if composite is None:
        regime = "Unavailable"
        read = "Fewer than three score components are available. No neutral value is imputed."
    elif composite >= 65:
        regime = "Expansionary"
        read = "Liquidity and balance-sheet impulses are broadly constructive, subject to cross-asset confirmation."
    elif composite <= 35:
        regime = "Contractionary"
        read = "Liquidity impulses are restrictive. Distinguish policy drainage from growth-driven deleveraging."
    else:
        regime = "Mixed / Transition"
        read = "The liquidity complex is not delivering one directional signal; component dispersion is more informative than the headline."
    return {"score": composite, "regime": regime, "read": read, "coverage": f"{available}/{len(inputs)}"}, pd.DataFrame(rows)


def _liq3_window(df: pd.DataFrame, window: str) -> pd.DataFrame:
    work = _liq3_frame(df)
    days = LIQ3_WINDOW_DAYS.get(str(window), 5 * 370)
    if work.empty or days is None:
        return work
    cutoff = pd.Timestamp.utcnow().tz_localize(None).normalize() - pd.Timedelta(days=int(days))
    return work.loc[work["date"] >= cutoff].copy()


def _liq3_transform(df: pd.DataFrame, transform: str) -> pd.DataFrame:
    name = str(transform or "level").lower()
    if name == "yoy": return _liq3_time_change(df, 365, True)
    if name == "13w": return _liq3_time_change(df, 91, True)
    if name == "1m": return _liq3_time_change(df, 30, True)
    if name == "3m": return _liq3_time_change(df, 91, True)
    if name == "1y_return": return _liq3_rolling_return(df, 365)
    if name == "indexed": return _liq3_index(df)
    if name == "zscore": return _liq3_zscore(df)
    if name == "drawdown": return _liq3_drawdown(df)
    if name == "vol30": return _liq3_vol(df, 30)
    if name == "vol90": return _liq3_vol(df, 90)
    return _liq3_frame(df)


def _liq3_chart_header(title: str, subtitle: str = "", source: str = "") -> None:
    _html(
        '<div class="liq3-chart-head">'
        f'<h3>{_escape(title)}</h3>'
        f'<p>{_escape(subtitle)}</p>'
        + (f'<span>{_escape(source)}</span>' if source else "")
        + '</div>'
    )


def _liq3_base_figure(ytitle: str = "", height: int = 450) -> go.Figure:
    fig = go.Figure()
    fig.update_layout(
        height=height,
        margin=dict(l=58, r=36, t=18, b=48),
        paper_bgcolor="#030b15", plot_bgcolor="#081421",
        font=dict(color="#dce7f1", family="Inter, Arial, sans-serif", size=13),
        legend=dict(orientation="h", yanchor="top", y=-0.16, xanchor="left", x=0, font=dict(size=12)),
        hovermode="x unified",
        xaxis=dict(
            gridcolor="rgba(128,160,188,.18)", zeroline=False, showline=False,
            rangeselector=dict(
                buttons=[
                    dict(count=1, label="1Y", step="year", stepmode="backward"),
                    dict(count=3, label="3Y", step="year", stepmode="backward"),
                    dict(count=5, label="5Y", step="year", stepmode="backward"),
                    dict(label="Max", step="all"),
                ],
                bgcolor="#0a1725", activecolor="#b79b37", bordercolor="rgba(204,183,91,.55)", borderwidth=1, font=dict(color="#e8eef5", size=11), x=0.01, y=1.08,
            ),
            rangeslider=dict(visible=False),
        ),
        yaxis=dict(title=ytitle, gridcolor="rgba(128,160,188,.18)", zerolinecolor="rgba(128,160,188,.25)", showline=False),
        modebar=dict(bgcolor="rgba(0,0,0,0)", color="#7f92a4", activecolor="#d9bf58"),
    )
    return fig


def _liq3_plot_lines(series: Sequence[Tuple[str, pd.DataFrame, str]], title: str, subtitle: str, ytitle: str, window: str, source: str = "Public/market data", height: int = 450, second_axis: Optional[Sequence[str]] = None, log_y: bool = False) -> None:
    second = set(second_axis or [])
    prepared: List[Tuple[str, pd.DataFrame, str]] = []
    for label, frame, transform in series:
        use = _liq3_window(_liq3_transform(frame, transform), window)
        if not use.empty:
            prepared.append((label, use, transform))
    _liq3_chart_header(title, subtitle, source)
    if not prepared:
        _html('<div class="mk-warning">No usable observations for this chart. The provider state is available in Data Quality.</div>')
        return
    fig = _liq3_base_figure(ytitle, height)
    if log_y:
        fig.update_yaxes(type="log")
    if second:
        fig.update_layout(yaxis2=dict(overlaying="y", side="right", title="Secondary", gridcolor="rgba(0,0,0,0)", showline=False))
    for i, (label, use, transform) in enumerate(prepared):
        fig.add_trace(go.Scatter(
            x=use["date"], y=use["value"], mode="lines", name=label,
            line=dict(color=LIQ3_COLORS[i % len(LIQ3_COLORS)], width=3 if i == 0 else 2.2, dash="solid" if i < 2 else "dot"),
            connectgaps=False, yaxis="y2" if label in second else "y",
            hovertemplate="%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>",
        ))
    st.plotly_chart(fig, width="stretch", config=_plot_config(title.lower().replace(" ", "_")[:60]))


def _liq3_plot_components(frame: pd.DataFrame, columns: Sequence[str], title: str, subtitle: str, ytitle: str, window: str, source: str) -> None:
    _liq3_chart_header(title, subtitle, source)
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        _html('<div class="mk-warning">Required components are unavailable.</div>')
        return
    use = frame.copy()
    use["date"] = pd.to_datetime(use["date"], errors="coerce").dt.tz_localize(None)
    days = LIQ3_WINDOW_DAYS.get(window)
    if days is not None:
        use = use.loc[use["date"] >= pd.Timestamp.utcnow().tz_localize(None).normalize() - pd.Timedelta(days=days)]
    fig = _liq3_base_figure(ytitle, 465)
    for i, col in enumerate(columns):
        if col not in use.columns:
            continue
        fig.add_trace(go.Scatter(x=use["date"], y=use[col], mode="lines", stackgroup="one", name=col, line=dict(width=1.8, color=LIQ3_COLORS[i % len(LIQ3_COLORS)]), hovertemplate="%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>"))
    st.plotly_chart(fig, width="stretch", config=_plot_config(title.lower().replace(" ", "_")[:60]))


def _liq3_plot_score(score_table: pd.DataFrame) -> None:
    _liq3_chart_header("Liquidity regime components", "Available components only; missing values are not assigned a neutral score.", "Quant Terminal methodology")
    work = score_table.copy()
    work["Score numeric"] = pd.to_numeric(work["Score"], errors="coerce")
    work = work.dropna(subset=["Score numeric"])
    if work.empty:
        _html('<div class="mk-warning">No score component is currently available.</div>')
        return
    fig = _liq3_base_figure("Score", 420)
    colors = ["#8bc48a" if x >= 60 else "#e87557" if x <= 40 else "#d9bf58" for x in work["Score numeric"]]
    fig.add_trace(go.Bar(x=work["Component"], y=work["Score numeric"], marker_color=colors, text=work["Score numeric"].map(lambda x: f"{x:.0f}"), textposition="outside", hovertemplate="%{x}<br>%{y:.1f}/100<extra></extra>"))
    fig.update_yaxes(range=[0, 105])
    fig.update_xaxes(tickangle=-25)
    st.plotly_chart(fig, width="stretch", config=_plot_config("liquidity_score_components"))


def _liq3_plot_heatmap_money(context: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    series = {
        "US M2": _liq3_time_change(frames.get("FRED:M2SL", pd.DataFrame()), 365, True),
        "Euro area M3": context.get("fred", {}).get("EA19MABMM301GYSAM", pd.DataFrame()),
        "Japan M3": context.get("fred", {}).get("JPNMABMM301GYSAM", pd.DataFrame()),
        "UK M3": context.get("fred", {}).get("GBRMABMM301GYSAM", pd.DataFrame()),
    }
    wide = {}
    for label, frame in series.items():
        use = _liq3_frame(frame)
        if use.empty:
            continue
        wide[label] = use.set_index("date")["value"].resample("ME").last()
    _liq3_chart_header("G4 broad-money growth heatmap", "Published or calculated year-over-year growth, monthly as-of.", "FRED/OECD public series")
    if not wide:
        _html('<div class="mk-warning">Global money-growth heatmap unavailable.</div>')
        return
    df = pd.concat(wide, axis=1).tail(36).T
    fig = go.Figure(go.Heatmap(z=df.to_numpy(dtype=float), x=df.columns, y=df.index, colorscale=[[0, "#8e3e3e"], [0.5, "#17283a"], [1, "#4f9b6f"]], zmid=0, colorbar=dict(title="YoY %"), hovertemplate="%{y}<br>%{x|%b %Y}<br>%{z:.2f}%<extra></extra>"))
    fig.update_layout(height=390, margin=dict(l=80, r=30, t=15, b=45), paper_bgcolor="#030b15", plot_bgcolor="#081421", font=dict(color="#dce7f1"))
    st.plotly_chart(fig, width="stretch", config=_plot_config("g4_money_heatmap"))


def _liq3_plot_corr_matrix(context: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    assets = {
        "G3": frames.get("G3", pd.DataFrame()), "Net Liquidity": frames.get("NET", pd.DataFrame()),
        "Bitcoin": frames.get("BTC", pd.DataFrame()), "Gold": frames.get("GOLD", pd.DataFrame()),
        "S&P 500": frames.get("MKT:SPY", pd.DataFrame()), "Nasdaq": frames.get("MKT:QQQ", pd.DataFrame()),
        "Dollar": frames.get("FRED:DTWEXBGS", pd.DataFrame()),
    }
    returns = {}
    for label, frame in assets.items():
        use = _liq3_frame(frame)
        if use.empty:
            continue
        returns[label] = use.set_index("date")["value"].resample("W-FRI").last().pct_change()
    _liq3_chart_header("Liquidity transmission correlation matrix", "Weekly changes over the most recent two years.", "Quant Terminal calculation")
    if len(returns) < 3:
        _html('<div class="mk-warning">At least three overlapping series are required.</div>')
        return
    wide = pd.concat(returns, axis=1).dropna(how="all").tail(104)
    corr = wide.corr(min_periods=26)
    fig = go.Figure(go.Heatmap(z=corr.to_numpy(dtype=float), x=corr.columns, y=corr.index, zmin=-1, zmax=1, zmid=0, colorscale=[[0, "#9e4f48"], [0.5, "#17283a"], [1, "#5f9fc7"]], text=np.round(corr.to_numpy(dtype=float), 2), texttemplate="%{text}", hovertemplate="%{y} / %{x}<br>%{z:.2f}<extra></extra>"))
    fig.update_layout(height=480, margin=dict(l=90, r=30, t=15, b=85), paper_bgcolor="#030b15", plot_bgcolor="#081421", font=dict(color="#dce7f1"))
    st.plotly_chart(fig, width="stretch", config=_plot_config("liquidity_correlation_matrix"))


def _liq3_plot_lag(context: Mapping[str, Any], asset_ref: str, title: str) -> None:
    frames = context.get("frames", {})
    liquidity = frames.get("NET", pd.DataFrame()) if not frames.get("NET", pd.DataFrame()).empty else frames.get("G3", pd.DataFrame())
    asset = frames.get(asset_ref, pd.DataFrame())
    _liq3_chart_header(title, "Correlation between weekly liquidity changes and subsequent 13-week asset returns; exploratory, not causal.", "Quant Terminal calculation")
    aligned = _liq3_align_returns(liquidity, asset)
    if aligned.empty or len(aligned) < 60:
        _html('<div class="mk-warning">Insufficient overlapping history for the lead-lag scan.</div>')
        return
    liq = aligned.set_index("date")["a"]
    price = _liq3_frame(asset).set_index("date")["value"].resample("W-FRI").last()
    future13 = price.pct_change(13).shift(-13)
    rows = []
    for lag in range(0, 27):
        pair = pd.concat([liq.shift(lag).rename("liq"), future13.rename("future")], axis=1).dropna()
        rows.append((lag, pair["liq"].corr(pair["future"]) if len(pair) >= 30 else np.nan))
    df = pd.DataFrame(rows, columns=["Lag", "Correlation"]).dropna()
    fig = _liq3_base_figure("Correlation", 400)
    fig.add_trace(go.Bar(x=df["Lag"], y=df["Correlation"], marker_color=["#8bc48a" if x >= 0 else "#e87557" for x in df["Correlation"]], hovertemplate="Lag %{x} weeks<br>Corr %{y:.3f}<extra></extra>"))
    fig.update_xaxes(title="Liquidity lead (weeks)")
    st.plotly_chart(fig, width="stretch", config=_plot_config("liquidity_lead_lag"))


def _liq3_fmt_change(value: Optional[float]) -> str:
    return "—" if value is None else f"{value:+.2f}%"


def _liq3_table(df: pd.DataFrame, max_rows: int = 100) -> None:
    if df is None or df.empty:
        _html('<div class="mk-warning">No observations available for this table.</div>')
        return
    use = df.head(max_rows)
    parts = ['<div style="overflow:auto"><table class="mk-table liq3-table"><thead><tr>']
    for col in use.columns:
        parts.append(f'<th>{_escape(col)}</th>')
    parts.append('</tr></thead><tbody>')
    for _, row in use.iterrows():
        parts.append('<tr>')
        for col in use.columns:
            value = row[col]
            if isinstance(value, float) and np.isnan(value): value = "—"
            text = str(value)
            cls = ""
            if text.startswith("+"): cls = " class=\"liq-pos\""
            elif text.startswith("-") and any(ch.isdigit() for ch in text): cls = " class=\"liq-neg\""
            parts.append(f'<td{cls}>{_escape(text)}</td>')
        parts.append('</tr>')
    parts.append('</tbody></table></div>')
    _html(''.join(parts))


