def _liq3_segmented(label: str, options: Sequence[str], key: str, default: str) -> str:
    if key not in st.session_state:
        st.session_state[key] = default
    try:
        value = st.segmented_control(label, options=list(options), selection_mode="single", key=key, label_visibility="collapsed")
        return str(value or default)
    except Exception:
        index = list(options).index(st.session_state.get(key, default)) if st.session_state.get(key, default) in options else 0
        return str(st.radio(label, list(options), index=index, horizontal=True, key=key, label_visibility="collapsed"))


def _liq3_core_kpis(context: Mapping[str, Any], score: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    score_value = score.get("score")
    cards = [
        _kpi_card("Liquidity regime", "—" if score_value is None else f"{score_value:.0f}/100", f'{score.get("regime", "—")} · coverage {score.get("coverage", "0/7")}'),
        _kpi_card("G3 CB assets", _fmt(_liq3_latest(frames.get("G3", pd.DataFrame())), 2, "T"), f'YoY {_liq3_fmt_change(_liq3_pct_latest(frames.get("G3", pd.DataFrame()), 365))}'),
        _kpi_card("US net liquidity", _fmt(_liq3_latest(frames.get("NET", pd.DataFrame())), 2, "T"), f'13W {_liq3_fmt_change(_liq3_pct_latest(frames.get("NET", pd.DataFrame()), 91))}'),
        _kpi_card("US M2", _fmt(_liq3_latest(frames.get("M2_T", pd.DataFrame())), 2, "T"), f'YoY {_liq3_fmt_change(_liq3_pct_latest(frames.get("FRED:M2SL", pd.DataFrame()), 365))}'),
        _kpi_card("US bank credit", _fmt(_liq3_latest(frames.get("FRED:TOTBKCR", pd.DataFrame())), 1, "B"), f'YoY {_liq3_fmt_change(_liq3_pct_latest(frames.get("FRED:TOTBKCR", pd.DataFrame()), 365))}'),
        _kpi_card("Bitcoin", _fmt(_liq3_latest(frames.get("BTC", pd.DataFrame())), 0, " USD"), f'3M {_liq3_fmt_change(_liq3_pct_latest(frames.get("BTC", pd.DataFrame()), 91))}'),
        _kpi_card("Gold", _fmt(_liq3_latest(frames.get("GOLD", pd.DataFrame())), 0, " USD/oz"), f'3M {_liq3_fmt_change(_liq3_pct_latest(frames.get("GOLD", pd.DataFrame()), 91))}'),
        _kpi_card("Method", "Public", "Official/public data first · cached stale data remains labelled"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')


def _liq3_spec(category: str, title: str, series: Sequence[Tuple[str, str, str]], ytitle: str = "", subtitle: str = "", kind: str = "lines", **kwargs: Any) -> Dict[str, Any]:
    return {"category": category, "title": title, "series": list(series), "ytitle": ytitle, "subtitle": subtitle, "kind": kind, **kwargs}


