def _liq3_enrich_context(context: Dict[str, Any]) -> Dict[str, Any]:
    frames = context["frames"]
    fred = context["fred"]
    gdp = fred.get("GDP", pd.DataFrame())
    frames["NET_GDP"] = _liq3_debt_to_gdp(_liq3_scale(frames.get("NET", pd.DataFrame()), 1 / 1000.0), gdp, "USD bn") if not frames.get("NET", pd.DataFrame()).empty else pd.DataFrame(columns=["date", "value"])
    frames["RESERVES_GDP"] = _liq3_debt_to_gdp(_liq3_scale(frames.get("RESERVES_T", pd.DataFrame()), 1 / 1000.0), gdp, "USD bn") if not frames.get("RESERVES_T", pd.DataFrame()).empty else pd.DataFrame(columns=["date", "value"])
    frames["BANK_CREDIT_GDP"] = _liq3_debt_to_gdp(fred.get("TOTBKCR", pd.DataFrame()), gdp, "USD bn")
    frames["CORP_T"] = _liq3_scale(fred.get("BCNSDODNS", pd.DataFrame()), 1_000_000.0)
    frames["HH_T"] = _liq3_scale(fred.get("CMDEBT", pd.DataFrame()), 1_000.0)
    frames["MORT_T"] = _liq3_scale(fred.get("HHMSDODNS", pd.DataFrame()), 1_000_000.0)
    frames["CONS_T"] = _liq3_scale(fred.get("HCCSDODNS", pd.DataFrame()), 1_000_000.0)
    return context


def _liq3_render_snapshot(context: Mapping[str, Any], metric: str, title: str) -> None:
    snap = context.get("snapshot", {})
    _liq3_chart_header(title, "Current CoinGecko global snapshot; no historical series is fabricated.", "CoinGecko")
    if not snap:
        _html('<div class="mk-warning">CoinGecko snapshot unavailable.</div>')
        return
    if metric == "market_caps":
        labels = ["Total crypto market cap", "24H volume"]
        values = [(snap.get("total_market_cap_usd") or 0) / 1e12, (snap.get("total_volume_usd") or 0) / 1e12]
        unit = "USD tn"
    elif metric == "dominance":
        labels = ["Bitcoin", "Ether"]
        values = [snap.get("btc_dominance") or 0, snap.get("eth_dominance") or 0]
        unit = "%"
    elif metric == "stablecoins":
        labels = ["Stablecoin market cap"]
        values = [(snap.get("stablecoin_market_cap_usd") or 0) / 1e9]
        unit = "USD bn"
    else:
        labels = ["24H market-cap change"]
        values = [snap.get("market_cap_change_24h") or 0]
        unit = "%"
    if not any(v != 0 for v in values):
        _html('<div class="mk-warning">Requested snapshot field is unavailable.</div>')
        return
    fig = _liq3_base_figure(unit, 360)
    fig.add_trace(go.Bar(x=labels, y=values, marker_color=[LIQ3_COLORS[i] for i in range(len(labels))], text=[f"{v:,.2f}" for v in values], textposition="outside"))
    st.plotly_chart(fig, width="stretch", config=_plot_config(title.lower().replace(" ", "_")[:60]))


def _liq3_render_performance_matrix(context: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    assets = {"Gold": frames.get("GOLD", pd.DataFrame()), "Silver": frames.get("SILVER", pd.DataFrame()), "Bitcoin": frames.get("BTC", pd.DataFrame()), "S&P 500": frames.get("MKT:SPY", pd.DataFrame())}
    horizons = {"1M": 30, "3M": 91, "6M": 182, "1Y": 365}
    matrix = []
    labels = []
    for label, frame in assets.items():
        if _liq3_frame(frame).empty:
            continue
        labels.append(label)
        matrix.append([_liq3_pct_latest(frame, d) for d in horizons.values()])
    _liq3_chart_header("Hard-money performance matrix", "Price returns across standard horizons.", "Public market data")
    if not matrix:
        _html('<div class="mk-warning">Market prices unavailable.</div>')
        return
    z = np.array(matrix, dtype=float)
    fig = go.Figure(go.Heatmap(z=z, x=list(horizons), y=labels, zmid=0, colorscale=[[0, "#9e4f48"], [0.5, "#17283a"], [1, "#4f9b6f"]], text=np.round(z, 1), texttemplate="%{text}%", hovertemplate="%{y}<br>%{x}: %{z:.2f}%<extra></extra>"))
    fig.update_layout(height=380, margin=dict(l=80, r=30, t=15, b=50), paper_bgcolor="#030b15", plot_bgcolor="#081421", font=dict(color="#dce7f1"))
    st.plotly_chart(fig, width="stretch", config=_plot_config("hard_money_performance_matrix"))


def _liq3_render_spec(spec: Mapping[str, Any], context: Mapping[str, Any], window: str) -> None:
    kind = spec.get("kind", "lines")
    frames = context.get("frames", {})
    title = str(spec.get("title", "Chart"))
    subtitle = str(spec.get("subtitle", ""))
    if kind == "money_heatmap":
        _liq3_plot_heatmap_money(context); return
    if kind == "corr_matrix":
        _liq3_plot_corr_matrix(context); return
    if kind == "pair":
        frame = _liq3_rolling_pair(frames.get(spec.get("left"), pd.DataFrame()), frames.get(spec.get("right"), pd.DataFrame()), int(spec.get("weeks", 26)), str(spec.get("metric", "corr")))
        _liq3_plot_lines([(title, frame, "level")], title, subtitle or "Rolling weekly relationship.", str(spec.get("ytitle", "")), window, "Quant Terminal calculation")
        return
    if kind == "lag":
        _liq3_plot_lag(context, str(spec.get("asset", "BTC")), title); return
    if kind == "snapshot":
        _liq3_render_snapshot(context, str(spec.get("metric", "market_caps")), title); return
    if kind == "performance_matrix":
        _liq3_render_performance_matrix(context); return
    series = []
    for label, ref, transform in spec.get("series", []):
        series.append((str(label), frames.get(str(ref), pd.DataFrame()), str(transform)))
    _liq3_plot_lines(series, title, subtitle, str(spec.get("ytitle", "")), window, "FRED / public market data", log_y=bool(spec.get("log_y", False)))


def _liq3_required_sets(view: str, chart_category: Optional[str] = None) -> Tuple[Tuple[str, ...], Tuple[str, ...], bool]:
    target = chart_category if view == "Chart Book" and chart_category else view
    if target == "Global Liquidity":
        return LIQ3_GLOBAL_FRED, ("BTC-USD", "GC=F", "SPY", "QQQ"), False
    if target == "Leverage & Credit":
        return LIQ3_LEVERAGE_FRED, ("BTC-USD", "GC=F"), False
    if target == "Bitcoin & Crypto":
        return LIQ3_BITCOIN_FRED, ("BTC-USD", "ETH-USD", "GC=F", "SPY", "QQQ"), True
    if target == "Gold & Precious Metals":
        return LIQ3_GOLD_FRED, ("BTC-USD", "GC=F", "SI=F", "GDX", "SLV", "SPY"), False
    if target == "Data Quality":
        return LIQ3_CORE_FRED, ("BTC-USD", "GC=F"), False
    return LIQ3_GLOBAL_FRED, ("BTC-USD", "GC=F", "SPY"), False


def _liq3_merge_context(core: Dict[str, Any], fred_extra: Mapping[str, pd.DataFrame], market_extra: Mapping[str, pd.DataFrame], snapshot: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    fred = dict(core.get("fred", {})); fred.update(fred_extra)
    market = dict(core.get("market", {})); market.update(market_extra)
    return _liq3_enrich_context(_liq3_build_context(fred, market, snapshot))


def _liq3_status_line(fred_diag: Mapping[str, Any], market_diag: Mapping[str, Any], total_elapsed: float, score: Mapping[str, Any]) -> None:
    fclass = "warn" if fred_diag.get("circuit_open") else "ok"
    _html(
        '<div class="liq3-statusline">'
        f'<span class="liq3-pill {fclass}">FRED {fred_diag.get("elapsed", 0):.1f}s · {_escape(fred_diag.get("provider", ""))}</span>'
        f'<span class="liq3-pill ok">Market data {market_diag.get("elapsed", 0):.1f}s</span>'
        f'<span class="liq3-pill">Total {total_elapsed:.1f}s</span>'
        f'<span class="liq3-pill">Score coverage {_escape(score.get("coverage", "0/7"))}</span>'
        + ('<span class="liq3-pill bad">Provider circuit open · cache/fallback mode</span>' if fred_diag.get("circuit_open") else '')
        + '</div>'
    )


