    with c2: _liq3_plot_lines([("C&I", f.get("FRED:BUSLOANS", pd.DataFrame()), "indexed"), ("Real estate", f.get("FRED:REALLN", pd.DataFrame()), "indexed"), ("Consumer", f.get("FRED:CONSUMER", pd.DataFrame()), "indexed")], "Loan composition", "Major loan books rebased to 100.", "Index", window)
