def _liq3_render_chart_book(context: Mapping[str, Any], window: str, category: str, page_size: int) -> None:
    registry = [x for x in _liq3_registry() if x["category"] == category]
    total_pages = max(1, math.ceil(len(registry) / page_size))
    c1, c2 = st.columns([1.1, .9])
    with c1:
        st.caption(f"{len(registry)} registered {category} views")
    with c2:
        page_key = "market_liq3_chart_page_" + category.lower().replace(" ", "_").replace("&", "and") + f"_{page_size}"
        page = st.selectbox("Chart page", list(range(1, total_pages + 1)), key=page_key)
    start = (int(page) - 1) * page_size
    selected = registry[start:start + page_size]
    _html(f'<div class="liq3-regime">Showing {start + 1}–{min(start + page_size, len(registry))} of {len(registry)} {category} charts · page {page}/{total_pages}.</div>')
    for i in range(0, len(selected), 2):
        cols = st.columns(2, gap="large")
        for col, spec in zip(cols, selected[i:i + 2]):
            with col:
                _liq3_render_spec(spec, context, window)


def _liq3_quality_summary(df: pd.DataFrame) -> Dict[str, Any]:
    if df is None or df.empty:
        return {"loaded": 0, "total": 0, "fresh": 0, "stale": 0, "latest": "—"}
    loaded = int((pd.to_numeric(df["Observations"], errors="coerce").fillna(0) > 0).sum())
    fresh = int((df["Freshness"].astype(str) == "Fresh").sum())
    stale = int(df["Freshness"].astype(str).isin(["Lagged", "Stale"]).sum())
    dates = pd.to_datetime(df["Latest Date"], errors="coerce")
    return {"loaded": loaded, "total": len(df), "fresh": fresh, "stale": stale, "latest": dates.max().strftime("%Y-%m-%d") if dates.notna().any() else "—"}


def _liq3_render_quality(quality: pd.DataFrame, diag: Mapping[str, Any], score_table: pd.DataFrame) -> None:
    q = _liq3_quality_summary(quality)
    cards = [
        _kpi_card("Series loaded", f'{q["loaded"]}/{q["total"]}', "Current lazy route or full audit"),
        _kpi_card("Fresh rows", str(q["fresh"]), "Within source-specific freshness tolerance"),
        _kpi_card("Lagged / stale", str(q["stale"]), "Visible; never silently upgraded"),
        _kpi_card("Latest observation", str(q["latest"]), f'Load time {diag.get("elapsed", 0):.1f}s'),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')
    _section("Series registry and freshness", "Source, native frequency, unit, observation count, cache status and provider message are visible for each input.")
    _liq3_table(quality, 150)
    contract = pd.DataFrame([
        {"Layer": "Central-bank assets", "Primary source": "FRED API / official mirrors", "Fallback": "Fresh or stale disk cache", "Rule": "No partial G3 aggregate"},
        {"Layer": "US liquidity plumbing", "Primary source": "Fed H.4.1 / New York Fed via FRED", "Fallback": "Disk cache / provider-required", "Rule": "WALCL − WDTGAL − ON RRP"},
        {"Layer": "Money and leverage", "Primary source": "FRED / Federal Reserve Z.1 and H.8", "Fallback": "Disk cache / provider-required", "Rule": "Native frequency retained"},
        {"Layer": "Bitcoin / crypto", "Primary source": "Yahoo price history + CoinGecko global snapshot", "Fallback": "Disk price cache", "Rule": "No snapshot backfill as history"},
        {"Layer": "Gold / silver", "Primary source": "FRED public series", "Fallback": "Yahoo futures proxies", "Rule": "Fallback source remains explicit"},
        {"Layer": "BIS cross-country credit", "Primary source": "BIS SDMX", "Fallback": "Provider-required", "Rule": "Not activated until dimensions are validated"},
    ])
    _section("Provider contract", "Timeouts are bounded, FRED requests are concurrent, and a failed provider opens a circuit rather than blocking every series for 25 seconds.")
    _liq3_table(contract)
    st.download_button("Download Liquidity data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_liquidity_v3_quality.csv", mime="text/csv", key="market_liq3_download_quality")
    st.download_button("Download Liquidity score composition", data=score_table.to_csv(index=False).encode("utf-8"), file_name="marketdesk_liquidity_v3_score.csv", mime="text/csv", key="market_liq3_download_score")


def _render_liquidity_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, analysis
    _liq3_css()
    _html('<div class="liq3-regime"><b>V3 architecture:</b> lazy subsection execution, concurrent FRED loading, FRED API first, disk cache and bounded provider circuit breaker. A failed data host can no longer produce a ten-minute serial wait.</div>')

    controls = st.columns([1.0, 1.0, 1.0, .9, .72], gap="medium")
    with controls[0]: window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y", "Max"], index=2, key="market_liq3_window")
    with controls[1]: page_size = int(st.selectbox("Chart-book size", [4, 6, 8], index=1, key="market_liq3_page_size"))
    with controls[2]: default_category = st.selectbox("Chart category", ["Global Liquidity", "Leverage & Credit", "Bitcoin & Crypto", "Gold & Precious Metals"], index=0, key="market_liq3_chart_category")
    with controls[3]: show_missing = st.toggle("Show missing rows", value=False, key="market_liq3_show_missing")
    with controls[4]:
        if st.button("Refresh", key="market_liq3_refresh", width="stretch"):
            st.session_state["market_liq3_refresh_nonce"] = int(st.session_state.get("market_liq3_refresh_nonce", 0)) + 1
            st.rerun()
    refresh_nonce = int(st.session_state.get("market_liq3_refresh_nonce", 0))
    view = _liq3_segmented("Liquidity view", LIQ3_VIEW_OPTIONS, "market_liq3_view", "Overview")

    fred_ids, market_ids, need_snapshot = _liq3_required_sets(view, default_category)
    started = time.perf_counter()
    with st.spinner("Loading Liquidity Daily - bounded concurrent providers..."):
        fred_pack, fred_quality, fred_diag = _liq3_load_fred_pack(tuple(fred_ids), "1990-01-01", refresh_nonce)
        market_pack, market_quality, market_diag = _liq3_load_market_pack(tuple(market_ids), "10y", refresh_nonce)
        # Reuse the app's current SPY history when it is available; this avoids a duplicate call.
        app_spy = _normalize_price_frame(price_data)
        if not app_spy.empty and "SPY" in market_ids:
            market_pack["SPY"] = app_spy.rename(columns={"close": "value"})[["date", "value"]]
        snapshot, snapshot_meta = _liq3_crypto_snapshot() if need_snapshot else ({}, {"status": "not-requested", "source": "CoinGecko", "message": "lazy route"})
        context = _liq3_enrich_context(_liq3_build_context(fred_pack, market_pack, snapshot))
        score, score_table = _liq3_score(context)
    total_elapsed = time.perf_counter() - started
    quality = pd.concat([fred_quality, market_quality], ignore_index=True) if not fred_quality.empty or not market_quality.empty else pd.DataFrame()
    if need_snapshot:
        quality = pd.concat([quality, pd.DataFrame([{
            "Series / Instrument": "COINGECKO:GLOBAL", "Label": "Crypto global snapshot", "Category": "Bitcoin & Crypto", "Source": snapshot_meta.get("source", "CoinGecko"), "Status": snapshot_meta.get("status", "unknown"), "Freshness": "Fresh" if snapshot else "Missing", "Observations": 1 if snapshot else 0, "Latest Date": datetime.now().strftime("%Y-%m-%d") if snapshot else "—", "Unit": "USD / %", "Frequency": "Snapshot", "Message": snapshot_meta.get("message", ""),
        }])], ignore_index=True)

    _liq3_core_kpis(context, score)
    _liq3_status_line(fred_diag, market_diag, total_elapsed, score)

    if view == "Overview":
        _liq3_render_overview(context, score, score_table, window)
    elif view == "Global Liquidity":
        _liq3_render_global(context, window)
    elif view == "Leverage & Credit":
        _liq3_render_leverage(context, window)
    elif view == "Bitcoin & Crypto":
        _liq3_render_bitcoin(context, window)
    elif view == "Gold & Precious Metals":
        _liq3_render_gold(context, window)
    elif view == "Chart Book":
        _liq3_render_chart_book(context, window, default_category, page_size)
    else:
        full_audit = st.toggle("Run full 31-series provider audit", value=False, key="market_liq3_full_audit")
        if full_audit:
            with st.spinner("Running full concurrent provider audit..."):
                f_all, q_all, d_all = _liq3_load_fred_pack(LIQ3_ALL_FRED, "1990-01-01", refresh_nonce)
                m_all, qm_all, dm_all = _liq3_load_market_pack(tuple(LIQ3_MARKET_SYMBOLS.keys()), "10y", refresh_nonce)
            del f_all, m_all
            quality = pd.concat([q_all, qm_all], ignore_index=True)
            fred_diag = d_all; market_diag = dm_all
        if not show_missing and not quality.empty:
            quality = quality.loc[pd.to_numeric(quality["Observations"], errors="coerce").fillna(0) > 0]
        _liq3_render_quality(quality, {"elapsed": float(fred_diag.get("elapsed", 0)) + float(market_diag.get("elapsed", 0))}, score_table)


