def _liq4_datetime_ns(values: Any) -> Any:
    """Return timezone-naive datetime64[ns], including on pandas 3.x.

    pandas 3.x preserves second/microsecond datetime resolutions more often than
    earlier releases. merge_asof requires matching key dtypes, so every join key
    is explicitly canonicalised to nanoseconds.
    """
    parsed = pd.to_datetime(values, errors="coerce", utc=True)
    if isinstance(parsed, pd.Series):
        return parsed.dt.tz_convert(None).astype("datetime64[ns]")
    if isinstance(parsed, pd.DatetimeIndex):
        return parsed.tz_convert(None).astype("datetime64[ns]")
    if isinstance(parsed, pd.Timestamp):
        if parsed.tzinfo is not None:
            parsed = parsed.tz_convert(None)
        return pd.Timestamp(parsed.to_datetime64().astype("datetime64[ns]"))
    return parsed


def _liq4_date_frame(df: pd.DataFrame, date_col: str = "date") -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame):
        return pd.DataFrame()
    out = df.copy()
    if date_col not in out.columns:
        return out.iloc[0:0].copy()
    out[date_col] = _liq4_datetime_ns(out[date_col])
    out = out.dropna(subset=[date_col]).sort_values(date_col)
    return out.drop_duplicates(date_col, keep="last").reset_index(drop=True)


def _liq4_merge_asof(
    left: pd.DataFrame,
    right: pd.DataFrame,
    *,
    tolerance: pd.Timedelta,
    direction: str = "backward",
) -> pd.DataFrame:
    l = _liq4_date_frame(left)
    r = _liq4_date_frame(right)
    if l.empty or r.empty:
        return pd.DataFrame()
    # Defensive assertions catch future provider/parser regressions before pandas
    # emits the less actionable dtype mismatch traceback.
    l["date"] = l["date"].astype("datetime64[ns]")
    r["date"] = r["date"].astype("datetime64[ns]")
    return pd.merge_asof(
        l.sort_values("date"),
        r.sort_values("date"),
        on="date",
        direction=direction,
        tolerance=tolerance,
    )


def _liq4_cadence_days(df: pd.DataFrame, default: float = 7.0) -> float:
    work = _liq4_date_frame(df)
    if len(work) < 3:
        return float(default)
    diffs = work["date"].diff().dt.total_seconds().div(86400.0)
    diffs = diffs[(diffs > 0) & np.isfinite(diffs)]
    return float(diffs.median()) if not diffs.empty else float(default)


# Override the shared normaliser: every derived series now carries datetime64[ns].
def _liq3_frame(df: Any) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame({
            "date": pd.Series(dtype="datetime64[ns]"),
            "value": pd.Series(dtype="float64"),
        })
    if "value" in df.columns:
        out = df[["date", "value"]].copy()
    elif "close" in df.columns:
        out = df[["date", "close"]].rename(columns={"close": "value"})
    else:
        return pd.DataFrame({
            "date": pd.Series(dtype="datetime64[ns]"),
            "value": pd.Series(dtype="float64"),
        })
    out["date"] = _liq4_datetime_ns(out["date"])
    out["value"] = pd.to_numeric(out["value"], errors="coerce")
    out = out.dropna(subset=["date", "value"])
    out = out.replace([np.inf, -np.inf], np.nan).dropna(subset=["value"])
    return out.drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _liq_asof_column(base_dates: pd.DataFrame, frame: pd.DataFrame, column_name: str, tolerance_days: int) -> pd.DataFrame:
    base = _liq4_date_frame(base_dates)
    right = _liq3_frame(frame).rename(columns={"value": column_name})
    if base.empty:
        return base
    if right.empty:
        base[column_name] = np.nan
        return base
    merged = _liq4_merge_asof(
        base,
        right,
        tolerance=pd.Timedelta(days=int(tolerance_days)),
        direction="backward",
    )
    if merged.empty:
        base[column_name] = np.nan
        return base
    return merged


def _liq3_time_change(df: pd.DataFrame, days: int, percent: bool = True) -> pd.DataFrame:
    work = _liq3_frame(df)
    if work.empty:
        return work
    base = work.rename(columns={"value": "current"}).copy()
    lag = work.rename(columns={"value": "previous"}).copy()
    lag["date"] = _liq4_datetime_ns(lag["date"] + pd.Timedelta(days=int(days)))
    tolerance_days = max(14, int(days * 0.18), int(_liq4_cadence_days(work) * 1.75))
    merged = _liq4_merge_asof(
        base,
        lag,
        tolerance=pd.Timedelta(days=tolerance_days),
        direction="backward",
    )
    if merged.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    if percent:
        merged["value"] = (merged["current"] / merged["previous"].replace(0, np.nan) - 1.0) * 100.0
    else:
        merged["value"] = merged["current"] - merged["previous"]
    return _liq3_frame(merged[["date", "value"]])


def _liq3_ratio(a: pd.DataFrame, b: pd.DataFrame, multiplier: float = 1.0) -> pd.DataFrame:
    left = _liq3_frame(a).rename(columns={"value": "a"})
    right = _liq3_frame(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    tolerance_days = max(10, int(max(_liq4_cadence_days(left), _liq4_cadence_days(right)) * 1.75))
    merged = _liq4_merge_asof(
        left,
        right,
        tolerance=pd.Timedelta(days=tolerance_days),
        direction="backward",
    )
    if merged.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    merged["value"] = merged["a"] / merged["b"].replace(0, np.nan) * float(multiplier)
    return _liq3_frame(merged[["date", "value"]])


def _liq3_debt_to_gdp(debt: pd.DataFrame, gdp: pd.DataFrame, debt_unit: str) -> pd.DataFrame:
    left = _liq3_frame(debt).rename(columns={"value": "debt"})
    right = _liq3_frame(gdp).rename(columns={"value": "gdp"})
    if left.empty or right.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    merged = _liq4_merge_asof(
        left,
        right,
        tolerance=pd.Timedelta(days=170),
        direction="backward",
    )
    if merged.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    unit = str(debt_unit or "").strip().lower()
    if unit in {"usd mn", "usd million", "usd millions"}:
        debt_bn = merged["debt"] / 1_000.0
    elif unit in {"usd tn", "usd trillion", "usd trillions"}:
        debt_bn = merged["debt"] * 1_000.0
    else:
        debt_bn = merged["debt"]
    merged["value"] = debt_bn / merged["gdp"].replace(0, np.nan) * 100.0
    return _liq3_frame(merged[["date", "value"]])


# Preserve the V3 builder while correcting the one hard-coded unit convention.
_liq3_build_context_v3_before_v4 = _liq3_build_context


def _liq3_build_context(
    fred: Mapping[str, pd.DataFrame],
    market: Mapping[str, pd.DataFrame],
    snapshot: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    context = _liq3_build_context_v3_before_v4(fred, market, snapshot)
    f = context.get("fred", {})
    frames = context.get("frames", {})
    frames["HH_GDP"] = _liq3_debt_to_gdp(
        f.get("CMDEBT", pd.DataFrame()),
        f.get("GDP", pd.DataFrame()),
        "USD mn",
    )
    context["frames"] = frames
    return context


def _liq3_enrich_context(context: Dict[str, Any]) -> Dict[str, Any]:
    frames = context.setdefault("frames", {})
    fred = context.get("fred", {})
    gdp = fred.get("GDP", pd.DataFrame())

    # NET and RESERVES are stored in USD trillions. Convert to USD billions only
    # for the denominator calculation, without altering their displayed units.
    frames["NET_GDP"] = (
        _liq3_debt_to_gdp(_liq3_scale(frames.get("NET", pd.DataFrame()), 0.001), gdp, "USD bn")
        if not _liq3_frame(frames.get("NET", pd.DataFrame())).empty else _liq3_frame(pd.DataFrame())
    )
    frames["RESERVES_GDP"] = (
        _liq3_debt_to_gdp(_liq3_scale(frames.get("RESERVES_T", pd.DataFrame()), 0.001), gdp, "USD bn")
        if not _liq3_frame(frames.get("RESERVES_T", pd.DataFrame())).empty else _liq3_frame(pd.DataFrame())
    )
    frames["BANK_CREDIT_GDP"] = _liq3_debt_to_gdp(fred.get("TOTBKCR", pd.DataFrame()), gdp, "USD bn")

    # Z.1 debt stocks are all millions of dollars. Divide by 1,000,000 to
    # display USD trillions. The V3 code treated CMDEBT as billions, inflating
    # household debt and household debt/GDP by 1,000x.
    frames["CORP_T"] = _liq3_scale(fred.get("BCNSDODNS", pd.DataFrame()), 1_000_000.0)
    frames["HH_T"] = _liq3_scale(fred.get("CMDEBT", pd.DataFrame()), 1_000_000.0)
    frames["MORT_T"] = _liq3_scale(fred.get("HHMSDODNS", pd.DataFrame()), 1_000_000.0)
    frames["CONS_T"] = _liq3_scale(fred.get("HCCSDODNS", pd.DataFrame()), 1_000_000.0)
    frames["HH_GDP"] = _liq3_debt_to_gdp(fred.get("CMDEBT", pd.DataFrame()), gdp, "USD mn")
    frames["CORP_GDP"] = _liq3_debt_to_gdp(fred.get("BCNSDODNS", pd.DataFrame()), gdp, "USD mn")
    frames["MORT_GDP"] = _liq3_debt_to_gdp(fred.get("HHMSDODNS", pd.DataFrame()), gdp, "USD mn")
    frames["CONS_GDP"] = _liq3_debt_to_gdp(fred.get("HCCSDODNS", pd.DataFrame()), gdp, "USD mn")
    context["frames"] = frames
    return context


