def _liq3_segmented(label: str, options: Sequence[str], key: str, default: str) -> str:
    import inspect as _liq4_inspect

    options_list = list(options)
    current = str(st.session_state.get(key, default))
    if current not in options_list:
        current = default
        st.session_state[key] = current
    try:
        parameters = _liq4_inspect.signature(st.segmented_control).parameters
        kwargs = {
            "options": options_list,
            "selection_mode": "single",
            "key": key,
            "label_visibility": "collapsed",
        }
        if "default" in parameters:
            kwargs["default"] = current
        value = st.segmented_control(label, **kwargs)
        return str(value or current)
    except Exception:
        fallback_key = f"{key}_radio_fallback"
        fallback_index = options_list.index(current) if current in options_list else 0
        value = st.radio(
            label,
            options_list,
            index=fallback_index,
            horizontal=True,
            key=fallback_key,
            label_visibility="collapsed",
        )
        st.session_state[key] = value
        return str(value)


def _liq3_chart_header(title: str, subtitle: str = "", source: str = "") -> None:
    _html(
        '<div class="liq3-chart-head">'
        f'<h3>{_escape(title)}</h3>'
        f'<p>{_escape(subtitle)}</p>'
        + (f'<span>{_escape(source)}</span>' if source else "")
        + '</div>'
    )


def _liq4_view_header(view: str) -> None:
    meta = LIQ4_VIEW_META.get(view, LIQ4_VIEW_META["Overview"])
    _html(
        '<div class="liq4-view-head">'
        f'<div class="liq4-view-eyebrow">{_escape(meta["eyebrow"])}</div>'
        f'<h2>{_escape(meta["title"])}</h2>'
        f'<p>{_escape(meta["subtitle"])}</p>'
        '</div>'
    )


def _liq4_render_guard(label: str, fn: Any, *args: Any, **kwargs: Any) -> None:
    try:
        fn(*args, **kwargs)
    except Exception as exc:
        st.error(f"{label} could not be rendered: {type(exc).__name__}: {exc}")
        with st.expander("Technical details", expanded=False):
            st.code(_liq4_traceback.format_exc())


def _liq3_render_chart_book(context: Mapping[str, Any], window: str, category: str, page_size: int) -> None:
    registry = [x for x in _liq3_registry() if x["category"] == category]
    total_pages = max(1, math.ceil(len(registry) / page_size))
    c1, c2 = st.columns([1.1, .9])
    with c1:
        st.caption(f"{len(registry)} registered {category} views")
    with c2:
        page_key = "market_liq3_chart_page_" + category.lower().replace(" ", "_").replace("&", "and") + f"_{page_size}"
        page = st.selectbox("Chart page", list(range(1, total_pages + 1)), key=page_key)
    start = (int(page) - 1) * page_size
    selected = registry[start:start + page_size]
    _html(f'<div class="liq3-regime">Showing {start + 1}–{min(start + page_size, len(registry))} of {len(registry)} {category} charts · page {page}/{total_pages}.</div>')
    for i in range(0, len(selected), 2):
        cols = st.columns(2, gap="large")
        for offset, (col, spec) in enumerate(zip(cols, selected[i:i + 2])):
            with col:
                numbered = dict(spec)
                numbered["title"] = f"{start + i + offset + 1:02d} · {spec['title']}"
                _liq4_render_guard(numbered["title"], _liq3_render_spec, numbered, context, window)


def _render_liquidity_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, analysis
    _liq3_css()

    # Navigation first; controls below are contextual rather than showing
    # Chart Book controls on every subsection.
    view = _liq3_segmented("Liquidity view", LIQ3_VIEW_OPTIONS, "market_liq3_view", "Overview")
    _liq4_view_header(view)

    default_category = str(st.session_state.get("market_liq3_chart_category", "Global Liquidity"))
    page_size = int(st.session_state.get("market_liq3_page_size", 6))
    show_missing = bool(st.session_state.get("market_liq3_show_missing", False))

    if view == "Chart Book":
        controls = st.columns([1.0, 1.15, .9, .72], gap="medium")
        with controls[0]:
            window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y", "Max"], index=2, key="market_liq3_window")
        with controls[1]:
            default_category = st.selectbox(
                "Chart category",
                ["Global Liquidity", "Leverage & Credit", "Bitcoin & Crypto", "Gold & Precious Metals"],
                index=["Global Liquidity", "Leverage & Credit", "Bitcoin & Crypto", "Gold & Precious Metals"].index(default_category) if default_category in ["Global Liquidity", "Leverage & Credit", "Bitcoin & Crypto", "Gold & Precious Metals"] else 0,
                key="market_liq3_chart_category",
            )
        with controls[2]:
            page_size = int(st.selectbox("Charts per page", [4, 6, 8], index=[4, 6, 8].index(page_size) if page_size in [4, 6, 8] else 1, key="market_liq3_page_size"))
        with controls[3]:
            refresh_clicked = st.button("Refresh", key="market_liq3_refresh", width="stretch")
    elif view == "Data Quality":
        controls = st.columns([1.0, 1.0, .72], gap="medium")
        with controls[0]:
            window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y", "Max"], index=2, key="market_liq3_window")
        with controls[1]:
            show_missing = st.toggle("Show missing rows", value=show_missing, key="market_liq3_show_missing")
        with controls[2]:
            refresh_clicked = st.button("Refresh", key="market_liq3_refresh", width="stretch")
    else:
        controls = st.columns([1.0, 2.15, .72], gap="medium")
        with controls[0]:
            window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y", "Max"], index=2, key="market_liq3_window")
        with controls[1]:
            st.caption("Data are loaded only for the selected research family. Native frequencies and provider states are retained.")
        with controls[2]:
            refresh_clicked = st.button("Refresh", key="market_liq3_refresh", width="stretch")

    if refresh_clicked:
        st.session_state["market_liq3_refresh_nonce"] = int(st.session_state.get("market_liq3_refresh_nonce", 0)) + 1
        st.rerun()

    refresh_nonce = int(st.session_state.get("market_liq3_refresh_nonce", 0))
    fred_ids, market_ids, need_snapshot = _liq3_required_sets(view, default_category)
    started = time.perf_counter()

    with st.spinner("Loading Liquidity Daily — bounded concurrent providers..."):
        fred_pack, fred_quality, fred_diag = _liq3_load_fred_pack(tuple(fred_ids), "1990-01-01", refresh_nonce)
        market_pack, market_quality, market_diag = _liq3_load_market_pack(tuple(market_ids), "10y", refresh_nonce)
        app_spy = _normalize_price_frame(price_data)
        if not app_spy.empty and "SPY" in market_ids:
            market_pack["SPY"] = app_spy.rename(columns={"close": "value"})[["date", "value"]]
        snapshot, snapshot_meta = _liq3_crypto_snapshot() if need_snapshot else ({}, {"status": "not-requested", "source": "CoinGecko", "message": "lazy route"})

        # The complete transformation graph is now exception-contained. A single
        # optional ratio cannot invalidate unrelated sections.
        try:
            context = _liq3_enrich_context(_liq3_build_context(fred_pack, market_pack, snapshot))
        except Exception as exc:
            st.error(f"Liquidity transformation layer failed: {type(exc).__name__}: {exc}")
            with st.expander("Transformation traceback", expanded=False):
                st.code(_liq4_traceback.format_exc())
            context = {"fred": dict(fred_pack), "market": dict(market_pack), "frames": {}, "snapshot": dict(snapshot), "g3_components": pd.DataFrame(), "net_components": pd.DataFrame()}
        score, score_table = _liq3_score(context)

    total_elapsed = time.perf_counter() - started
    quality = pd.concat([fred_quality, market_quality], ignore_index=True) if not fred_quality.empty or not market_quality.empty else pd.DataFrame()
    if need_snapshot:
        quality = pd.concat([quality, pd.DataFrame([{
            "Series / Instrument": "COINGECKO:GLOBAL",
            "Label": "Crypto global snapshot",
            "Category": "Bitcoin & Crypto",
            "Source": snapshot_meta.get("source", "CoinGecko"),
            "Status": snapshot_meta.get("status", "unknown"),
            "Freshness": "Fresh" if snapshot else "Missing",
            "Observations": 1 if snapshot else 0,
            "Latest Date": datetime.now().strftime("%Y-%m-%d") if snapshot else "—",
            "Unit": "USD / %",
            "Frequency": "Snapshot",
            "Message": snapshot_meta.get("message", ""),
        }])], ignore_index=True)

    _liq3_core_kpis(context, score)
    _liq3_status_line(fred_diag, market_diag, total_elapsed, score)

    if view == "Overview":
        _liq4_render_guard("Liquidity overview", _liq3_render_overview, context, score, score_table, window)
    elif view == "Global Liquidity":
        _liq4_render_guard("Global Liquidity", _liq3_render_global, context, window)
    elif view == "Leverage & Credit":
        _liq4_render_guard("Leverage & Credit", _liq3_render_leverage, context, window)
    elif view == "Bitcoin & Crypto":
        _liq4_render_guard("Bitcoin & Crypto", _liq3_render_bitcoin, context, window)
    elif view == "Gold & Precious Metals":
        _liq4_render_guard("Gold & Precious Metals", _liq3_render_gold, context, window)
    elif view == "Chart Book":
        _liq4_render_guard("Chart Book", _liq3_render_chart_book, context, window, default_category, page_size)
    else:
        full_audit = st.toggle("Run full 31-series provider audit", value=False, key="market_liq3_full_audit")
        if full_audit:
            with st.spinner("Running full concurrent provider audit..."):
                _f_all, q_all, d_all = _liq3_load_fred_pack(LIQ3_ALL_FRED, "1990-01-01", refresh_nonce)
                _m_all, qm_all, dm_all = _liq3_load_market_pack(tuple(LIQ3_MARKET_SYMBOLS.keys()), "10y", refresh_nonce)
            quality = pd.concat([q_all, qm_all], ignore_index=True)
            fred_diag, market_diag = d_all, dm_all
        if not show_missing and not quality.empty:
            quality = quality.loc[pd.to_numeric(quality["Observations"], errors="coerce").fillna(0) > 0]
        _liq4_render_guard(
            "Data Quality",
            _liq3_render_quality,
            quality,
            {"elapsed": float(fred_diag.get("elapsed", 0)) + float(market_diag.get("elapsed", 0))},
            score_table,
        )


