# ============================================================
# MARKET INTELLIGENCE V5 — LIQUIDITY DAILY FROZEN PARITY/UI
# ============================================================
# Append after V4. This patch does not alter Economy V31, the internal
# Economy/Markets hub, Fixed Income, app.py or asset_class_router.py.
# It finalises:
# - one institutional Trade-Pulse-style card for every chart/table;
# - a single family navigation layer plus an archive filter inside Chart Book;
# - chart-level 1Y/3Y/5Y/10Y/20Y/Max ranges (no redundant page window);
# - RoboMacro public registry counts and the verified Liquidity first-page order;
# - corrected leverage ordering, source labels, units and data-quality metadata;
# - full-width rendering and isolated chart/table failures.
# ============================================================

LIQ5_VERSION = "V5 FROZEN · LIQUIDITY DAILY PARITY / DESIGN"
MARKET_INTELLIGENCE_VERSION = "V5 · LIQUIDITY DAILY FROZEN PARITY/UI + FIXED INCOME"
LIQ5_FAMILIES = ["Global Liquidity", "Leverage & Credit", "Bitcoin & Crypto", "Gold & Precious Metals"]
LIQ5_VIEW_OPTIONS = ["Overview", *LIQ5_FAMILIES, "Chart Book", "Data Quality"]
LIQ5_DEFAULT_INITIAL_WINDOW = "5Y"
LIQ5_COLORS = ["#72b7e8", "#d8b52f", "#e87557", "#8bc48a", "#b48ead", "#78c6c8"]

# Correct public metadata that was still displayed incorrectly in V4.
try:
    LIQ3_FRED_SERIES["CMDEBT"]["unit"] = "USD mn"
    for _sid in ("BUSLOANS", "REALLN", "CONSUMER"):
        LIQ3_FRED_SERIES[_sid]["frequency"] = "Monthly"
        LIQ3_FRED_SERIES[_sid]["fresh_days"] = 75
except Exception:
    pass

_LIQ5_BASE_REGISTRY_FACTORY = _liq3_registry


def _liq5_registry() -> List[Dict[str, Any]]:
    """Return the frozen 124-chart registry in research-publication order."""
    base = [dict(x) for x in _LIQ5_BASE_REGISTRY_FACTORY()]
    by_category: Dict[str, List[Dict[str, Any]]] = {
        family: [dict(x) for x in base if x.get("category") == family]
        for family in LIQ5_FAMILIES
    }

    def take(category: str, title: str) -> Dict[str, Any]:
        for idx, spec in enumerate(by_category[category]):
            if spec.get("title") == title:
                return by_category[category].pop(idx)
        raise KeyError(f"Liquidity registry title missing: {category} / {title}")

    # Public RoboMacro page order verified for the first ten Liquidity charts.
    global_order: List[Dict[str, Any]] = []
    exact_global = [
        ("US Federal Reserve balance sheet", "US Fed Balance Sheet ($T)", None, "USD tn"),
        ("Eurosystem balance sheet", "ECB Balance Sheet (€T)", None, "EUR tn"),
        ("Bank of Japan balance sheet", "Bank of Japan Balance Sheet (¥T)", None, "JPY tn"),
        ("Major central-bank balance sheets aggregate", "Major CB Balance Sheets Aggregate ($T equiv)", None, "USD tn"),
        ("Federal Reserve balance sheet YoY", "US Fed Balance Sheet YoY Change (%)", None, "%"),
        # RoboMacro displays the native FRED M2 level in USD billions.
        ("US M2 money supply", "US M2 Money Supply ($B)", [("US M2", "FRED:M2SL", "level")], "USD bn"),
        ("US M2 money supply YoY", "US M2 Money Supply YoY (%)", None, "%"),
        ("Euro area M3 YoY", "Eurozone M3 YoY (%)", None, "%"),
        ("Japan M3 YoY", "Japan M3 (Broad Money) YoY (%)", None, "%"),
        ("UK M3 YoY", "UK M3 YoY (%)", None, "%"),
    ]
    for old_title, display_title, replacement_series, ytitle in exact_global:
        spec = take("Global Liquidity", old_title)
        spec["title"] = display_title
        spec["parity_title"] = display_title
        spec["parity_status"] = "Verified public order"
        if replacement_series is not None:
            spec["series"] = replacement_series
        spec["ytitle"] = ytitle
        global_order.append(spec)
    for spec in by_category["Global Liquidity"]:
        spec["parity_title"] = spec.get("title", "")
        spec["parity_status"] = "Functional equivalent"
        global_order.append(spec)

    # Leverage is ordered around private-sector leverage first, then bank-credit
    # transmission. This removes the V3/V4 mismatch where the publication opened
    # with H.8 bank credit rather than the leverage stack.
    leverage_titles = [
        "Nonfinancial corporate debt",
        "Nonfinancial corporate debt YoY",
        "Nonfinancial corporate debt / GDP",
        "Household debt",
        "Household debt YoY",
        "Household debt / GDP",
        "Household mortgage debt",
        "Household mortgage debt YoY",
        "Mortgage debt / GDP",
        "Household consumer credit",
        "Household consumer credit YoY",
        "Consumer credit / GDP",
        "Household debt-service ratio",
        "US commercial-bank credit",
        "US commercial-bank credit YoY",
        "US commercial-bank credit / GDP",
        "Loans and leases in bank credit",
        "Commercial and industrial loans",
        "Real estate loans",
        "Consumer loans",
        "Total assets of US commercial banks",
        "Corporate and household debt indexed",
        "Mortgage debt and consumer credit indexed",
        "Bank credit relative to M2",
    ]
    leverage_order = [take("Leverage & Credit", title) for title in leverage_titles]
    leverage_display = {
        "Nonfinancial corporate debt": "US Nonfinancial Corporate Debt ($T)",
        "Nonfinancial corporate debt YoY": "US Corporate Debt YoY (%)",
        "Nonfinancial corporate debt / GDP": "US Corporate Debt / GDP (%)",
        "Household debt": "US Household Debt ($T)",
        "Household debt YoY": "US Household Debt YoY (%)",
        "Household debt / GDP": "US Household Debt / GDP (%)",
        "Household mortgage debt": "US Mortgage Debt ($T)",
        "Household mortgage debt YoY": "US Mortgage Debt YoY (%)",
        "Mortgage debt / GDP": "US Mortgage Debt / GDP (%)",
        "Household consumer credit": "US Consumer Credit ($T)",
        "Household consumer credit YoY": "US Consumer Credit YoY (%)",
        "Consumer credit / GDP": "US Consumer Credit / GDP (%)",
        "Household debt-service ratio": "Household Debt-Service Ratio (%)",
        "US commercial-bank credit": "US Commercial-Bank Credit ($B)",
        "US commercial-bank credit YoY": "US Commercial-Bank Credit YoY (%)",
        "US commercial-bank credit / GDP": "US Commercial-Bank Credit / GDP (%)",
        "Loans and leases in bank credit": "Loans & Leases in Bank Credit ($B)",
        "Commercial and industrial loans": "Commercial & Industrial Loans ($B)",
        "Real estate loans": "Real-Estate Loans ($B)",
        "Consumer loans": "Consumer Loans ($B)",
        "Total assets of US commercial banks": "Total Assets of US Commercial Banks ($B)",
        "Corporate and household debt indexed": "Corporate vs Household Debt (Indexed)",
        "Mortgage debt and consumer credit indexed": "Mortgage Debt vs Consumer Credit (Indexed)",
        "Bank credit relative to M2": "Bank Credit / M2 (Ratio)",
    }
    for spec in leverage_order:
        original = str(spec.get("title", ""))
        spec["title"] = leverage_display.get(original, original)
        spec["parity_title"] = spec["title"]
        spec["parity_status"] = "Functional equivalent"

    bitcoin_order = by_category["Bitcoin & Crypto"]
    gold_order = by_category["Gold & Precious Metals"]
    for spec in bitcoin_order + gold_order:
        spec["parity_title"] = spec.get("title", "")
        spec["parity_status"] = "Functional equivalent"

    registry = global_order + leverage_order + bitcoin_order + gold_order
    counts = {family: len([x for x in registry if x.get("category") == family]) for family in LIQ5_FAMILIES}
    assert counts == {
        "Global Liquidity": 33,
        "Leverage & Credit": 24,
        "Bitcoin & Crypto": 37,
        "Gold & Precious Metals": 30,
    }, counts
    assert len(registry) == 124
    return registry


def _liq3_registry() -> List[Dict[str, Any]]:
    return _liq5_registry()


