LIQ6_VERSION = "V6 FINAL · LIQUIDITY DAILY SCALE / PARITY FREEZE"
MARKET_INTELLIGENCE_VERSION = "V6 · LIQUIDITY DAILY FINAL + FIXED INCOME"
