def _liq6_registry() -> List[Dict[str, Any]]:
    """Return the final 124-view registry with explicit scale and parity metadata."""
    base = [dict(x) for x in _LIQ6_V5_REGISTRY_FACTORY()]
    by_family = {family: [dict(x) for x in base if x.get("category") == family] for family in LIQ6_FAMILIES}

    # Public page evidence: first ten Global Liquidity cards.
    for _idx, spec in enumerate(by_family["Global Liquidity"], 1):
        spec["parity_status"] = "Public page verified" if _idx <= 10 else "Semantic/data parity audited"

    # User-supplied RoboMacro capture: Gold local chart 7 (global card #101).
    gold = by_family["Gold & Precious Metals"]
    original_gold = [dict(x) for x in gold]
    gold_fed_m2 = {
        "category": "Gold & Precious Metals",
        "kind": "lines",
        "title": "Gold vs Fed Balance Sheet & M2",
        "subtitle": "Gold vs Fed QE and money supply – liquidity debasement drivers",
        "series": [
            ("Gold (LHS) (indexed)", "GOLD", "indexed"),
            ("Fed BS (RHS) (indexed)", "FED_T", "indexed"),
            ("M2 (RHS) (indexed)", "FRED:M2SL", "indexed"),
        ],
        "ytitle": "Indexed (100 = Jul 2019)",
        "common_index_start": "2019-07-01",
        "scale_policy": "indexed",
        "source": "Calculated · FRED / public market data",
        "parity_status": "User capture verified",
        "parity_title": "Gold vs Fed Balance Sheet & M2",
    }
    # Keep 30 Gold views: insert the verified chart at #7 and remove the
    # Quant Terminal-only performance matrix from the publication registry.
    gold = original_gold[:6] + [gold_fed_m2] + original_gold[6:29]
    by_family["Gold & Precious Metals"] = gold

    # Correct mathematically invalid indexing of series that can cross zero.
    for spec in by_family["Bitcoin & Crypto"]:
        if spec.get("title") == "Bitcoin and 10Y real yield":
            spec.update({
                "title": "Bitcoin vs 10Y Real Yield",
                "subtitle": "Bitcoin price (LHS) versus the US 10Y TIPS real yield (RHS).",
                "series": [("Bitcoin (LHS)", "BTC", "level"), ("10Y real yield (RHS)", "FRED:DFII10", "level")],
                "ytitle": "USD",
                "second_axis": ["10Y real yield (RHS)"],
                "secondary_title": "%",
                "scale_policy": "positive",
                "secondary_scale_policy": "signed",
                "source": "Yahoo / FRED public data",
            })
        spec["parity_status"] = "Semantic/data parity audited"

    for spec in by_family["Gold & Precious Metals"]:
        if spec.get("title") == "Gold and 10Y real yield":
            spec.update({
                "title": "Gold vs 10Y Real Yield",
                "subtitle": "Gold price (LHS) versus the US 10Y TIPS real yield (RHS, inverted).",
                "series": [("Gold (LHS)", "GOLD", "level"), ("10Y real yield (RHS, inverted)", "FRED:DFII10", "level")],
                "ytitle": "USD/oz",
                "second_axis": ["10Y real yield (RHS, inverted)"],
                "secondary_title": "%",
                "invert_secondary": True,
                "scale_policy": "positive",
                "secondary_scale_policy": "signed",
                "source": "FRED / public market data",
            })
        if spec.get("parity_status") != "User capture verified":
            spec["parity_status"] = "Semantic/data parity audited"

    # Leverage mappings are fully audited against the family contract.
    for spec in by_family["Leverage & Credit"]:
        spec["parity_status"] = "Semantic/data parity audited"

    # Complete metadata used by the final generic renderer.
    default_sources = {
        "Global Liquidity": "FRED / public market data",
        "Leverage & Credit": "Federal Reserve / FRED public data",
        "Bitcoin & Crypto": "Yahoo / CoinGecko / public market data",
        "Gold & Precious Metals": "FRED / Yahoo public market data",
    }
    registry: List[Dict[str, Any]] = []
    for family in LIQ6_FAMILIES:
        for local_order, spec in enumerate(by_family[family], 1):
            item = dict(spec)
            item["order"] = local_order
            item.setdefault("source", default_sources[family])
            item.setdefault("parity_title", item.get("title", ""))
            item.setdefault("parity_status", "Semantic/data parity audited")
            transforms = [str(x[2]) for x in item.get("series", []) if isinstance(x, (tuple, list)) and len(x) >= 3]
            if transforms and all(x == "indexed" for x in transforms) and len(transforms) > 1:
                item.setdefault("common_index_start", "2019-07-01")
                item.setdefault("scale_policy", "indexed")
            if item.get("kind") == "pair":
                item.setdefault("scale_policy", "correlation" if item.get("metric") == "corr" else "signed")
            if item.get("kind") == "lag":
                item.setdefault("scale_policy", "signed")
            registry.append(item)

    counts = {family: len([x for x in registry if x.get("category") == family]) for family in LIQ6_FAMILIES}
    assert counts == {
        "Global Liquidity": 33,
        "Leverage & Credit": 24,
        "Bitcoin & Crypto": 37,
        "Gold & Precious Metals": 30,
    }, counts
    assert len(registry) == 124
    assert [x for x in registry if x.get("category") == "Gold & Precious Metals"][6]["title"] == "Gold vs Fed Balance Sheet & M2"
    return registry


def _liq3_registry() -> List[Dict[str, Any]]:
    return _liq6_registry()


