def _liq6_normalize(frame: pd.DataFrame) -> pd.DataFrame:
    use = _liq3_frame(frame)
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    use = use[["date", "value"]].copy()
    use["date"] = _liq4_datetime_ns(use["date"])
    use["value"] = pd.to_numeric(use["value"], errors="coerce")
    use = use.replace([np.inf, -np.inf], np.nan).dropna(subset=["date", "value"])
    return use.drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _liq6_common_index(series: Sequence[Tuple[str, pd.DataFrame, str]], anchor: Optional[Any] = None) -> List[Tuple[str, pd.DataFrame, str]]:
    raw: List[Tuple[str, pd.DataFrame, str]] = []
    for label, frame, transform in series:
        use = _liq6_normalize(frame)
        if not use.empty:
            raw.append((label, use, transform))
    if not raw:
        return []
    common_start = max(pd.Timestamp(x[1]["date"].min()) for x in raw)
    common_end = min(pd.Timestamp(x[1]["date"].max()) for x in raw)
    requested = pd.Timestamp(anchor) if anchor is not None else LIQ6_INDEX_ANCHOR
    baseline_date = max(common_start, requested)
    if baseline_date > common_end:
        baseline_date = common_start
    out: List[Tuple[str, pd.DataFrame, str]] = []
    for label, use, _transform in raw:
        candidates = use.loc[use["date"] >= baseline_date]
        if candidates.empty:
            candidates = use.loc[use["date"] >= common_start]
        if candidates.empty:
            continue
        base = _safe_float(candidates.iloc[0]["value"])
        if base is None or abs(base) < 1e-12:
            continue
        indexed = use.copy()
        indexed["value"] = indexed["value"] / base * 100.0
        indexed.attrs["index_base_date"] = pd.Timestamp(candidates.iloc[0]["date"])
        out.append((label, indexed, "indexed"))
    return out


def _liq6_prepare_series(series: Sequence[Tuple[str, pd.DataFrame, str]], common_index_start: Optional[Any] = None) -> List[Tuple[str, pd.DataFrame, str]]:
    clean = [(str(label), frame, str(transform)) for label, frame, transform in series]
    if len(clean) > 1 and all(transform == "indexed" for _, _, transform in clean):
        return _liq6_common_index(clean, common_index_start)
    out: List[Tuple[str, pd.DataFrame, str]] = []
    for label, frame, transform in clean:
        use = _liq6_normalize(frame)
        if use.empty:
            continue
        transformed = _liq3_transform(use, transform)
        transformed = _liq6_normalize(transformed)
        if not transformed.empty:
            out.append((label, transformed, transform))
    return out


def _liq6_visible_values(prepared: Sequence[Tuple[str, pd.DataFrame, str]], labels: set, start: pd.Timestamp, end: pd.Timestamp) -> np.ndarray:
    chunks: List[np.ndarray] = []
    for label, frame, _transform in prepared:
        if label not in labels:
            continue
        mask = (frame["date"] >= start) & (frame["date"] <= end)
        values = pd.to_numeric(frame.loc[mask, "value"], errors="coerce").to_numpy(dtype=float)
        values = values[np.isfinite(values)]
        if values.size:
            chunks.append(values)
    return np.concatenate(chunks) if chunks else np.array([], dtype=float)


def _liq6_axis_range(values: np.ndarray, policy: str = "auto", log_axis: bool = False, reverse: bool = False) -> Optional[List[float]]:
    values = np.asarray(values, dtype=float)
    values = values[np.isfinite(values)]
    if values.size == 0:
        return None
    policy = str(policy or "auto").lower()
    if policy == "correlation":
        lo, hi = -1.05, 1.05
    else:
        lo = float(np.nanmin(values)); hi = float(np.nanmax(values))
        # Suppress isolated malformed observations only when they dominate the
        # central range by a very large factor. Legitimate regime extremes remain.
        if values.size >= 40:
            q01, q99 = np.nanquantile(values, [0.01, 0.99])
            central = max(float(q99 - q01), 1e-12)
            if (hi - lo) > 8.0 * central:
                lo, hi = float(q01), float(q99)
        if policy in {"signed", "percent", "beta"}:
            lo = min(lo, 0.0); hi = max(hi, 0.0)
        elif policy == "drawdown":
            lo = min(lo, 0.0); hi = 0.0
        elif policy == "positive":
            if lo <= 0 < hi:
                lo = 0.0
        if math.isclose(lo, hi, rel_tol=1e-12, abs_tol=1e-12):
            delta = max(abs(lo) * 0.08, 1.0 if abs(lo) >= 1 else 0.08)
            lo -= delta; hi += delta
        span = max(hi - lo, 1e-12)
        pad = span * 0.065
        if policy == "drawdown":
            lo -= pad; hi = max(0.0, hi)
        elif policy == "positive":
            lo = max(0.0, lo - pad); hi += pad
        else:
            lo -= pad; hi += pad
    if log_axis:
        positive = values[values > 0]
        if positive.size == 0:
            return None
        lo = max(lo, float(np.nanmin(positive)) * 0.94)
        hi = max(hi, lo * 1.01)
        result = [math.log10(lo), math.log10(hi)]
    else:
        result = [float(lo), float(hi)]
    return result[::-1] if reverse else result


def _liq6_infer_policy(ytitle: str, transforms: Sequence[str], explicit: Optional[str] = None) -> str:
    if explicit:
        return str(explicit)
    low = str(ytitle or "").lower()
    tset = set(transforms)
    if "correlation" in low and "beta" not in low:
        return "correlation"
    if "drawdown" in tset:
        return "drawdown"
    if tset.intersection({"yoy", "13w", "1m", "3m", "1y_return", "vol30", "vol90"}):
        return "signed" if not tset.issubset({"vol30", "vol90"}) else "positive"
    if "ratio" in low or "index" in low or "usd" in low or "level" in low or "tn" in low or "bn" in low:
        return "positive"
    if "%" in low:
        return "signed"
    return "auto"


def _liq6_window_layouts(
    prepared: Sequence[Tuple[str, pd.DataFrame, str]],
    second_axis: set,
    primary_policy: str,
    secondary_policy: str,
    log_y: bool,
    invert_secondary: bool,
) -> Tuple[pd.Timestamp, pd.Timestamp, Dict[str, Dict[str, Any]]]:
    all_dates = pd.concat([x[1]["date"] for x in prepared], ignore_index=True)
    end = pd.Timestamp(all_dates.max()); full_start = pd.Timestamp(all_dates.min())
    primary_labels = {label for label, _, _ in prepared if label not in second_axis}
    secondary_labels = {label for label, _, _ in prepared if label in second_axis}
    layouts: Dict[str, Dict[str, Any]] = {}
    for label, years in LIQ6_WINDOWS:
        start = full_start if years is None else max(full_start, end - pd.DateOffset(years=years))
        pvals = _liq6_visible_values(prepared, primary_labels, start, end)
        svals = _liq6_visible_values(prepared, secondary_labels, start, end)
        change: Dict[str, Any] = {"xaxis.range": [start, end], "xaxis.autorange": False}
        prange = _liq6_axis_range(pvals, primary_policy, log_y, False)
        if prange is not None:
            change["yaxis.range"] = prange; change["yaxis.autorange"] = False
        srange = _liq6_axis_range(svals, secondary_policy, False, invert_secondary)
        if srange is not None:
            change["yaxis2.range"] = srange; change["yaxis2.autorange"] = False
        layouts[label] = change
    return full_start, end, layouts


def _liq6_base_figure(
    ytitle: str = "",
    height: int = 385,
    prepared: Optional[Sequence[Tuple[str, pd.DataFrame, str]]] = None,
    second_axis: Optional[Sequence[str]] = None,
    scale_policy: Optional[str] = None,
    secondary_scale_policy: Optional[str] = None,
    log_y: bool = False,
    secondary_title: str = "Secondary",
    invert_secondary: bool = False,
) -> go.Figure:
    fig = go.Figure()
    fig.update_layout(
        height=height,
        margin=dict(l=58, r=54, t=56, b=62),
        paper_bgcolor="#050c15", plot_bgcolor="#08131f",
        font=dict(color="#dce5ed", family="Inter, Arial, sans-serif", size=11),
        hovermode="x unified",
        legend=dict(orientation="h", y=-.19, x=0, bgcolor="rgba(0,0,0,0)", font=dict(size=10)),
        xaxis=dict(showgrid=True, gridcolor="rgba(130,150,170,.20)", zeroline=False, rangeslider=dict(visible=False)),
        yaxis=dict(title=ytitle, showgrid=True, gridcolor="rgba(130,150,170,.20)", zerolinecolor="rgba(200,200,200,.25)"),
        modebar=dict(bgcolor="rgba(0,0,0,0)", color="#7f8b99", activecolor="#d6bd65"),
        uirevision="liq6-final",
    )
    if log_y:
        fig.update_yaxes(type="log")
    second = set(second_axis or [])
    if second:
        fig.update_layout(yaxis2=dict(overlaying="y", side="right", title=secondary_title, showgrid=False, zeroline=False))
    if prepared:
        transforms = [x[2] for x in prepared if x[0] not in second]
        stransforms = [x[2] for x in prepared if x[0] in second]
        ppolicy = _liq6_infer_policy(ytitle, transforms, scale_policy)
        spolicy = _liq6_infer_policy(secondary_title, stransforms, secondary_scale_policy)
        _full_start, _end, layouts = _liq6_window_layouts(prepared, second, ppolicy, spolicy, log_y, invert_secondary)
        buttons = []
        for label, _years in LIQ6_WINDOWS:
            buttons.append(dict(label=label, method="relayout", args=[layouts[label]]))
        fig.update_layout(
            updatemenus=[dict(
                type="buttons", direction="right", active=2, showactive=True,
                buttons=buttons, x=.01, xanchor="left", y=1.12, yanchor="top",
                bgcolor="#091725", bordercolor="rgba(204,183,91,.60)", borderwidth=1,
                font=dict(color="#dce5ed", size=10), pad=dict(r=3, t=2),
            )]
        )
        fig.update_layout(**layouts[LIQ6_DEFAULT_WINDOW])
    return fig


def _liq6_badge_from_prepared(label: str, frame: pd.DataFrame, unit: str, transform: str) -> Tuple[str, str]:
    if frame.empty:
        return f"{label} —", ""
    row = frame.iloc[-1]
    value = _liq5_fmt_value(row.get("value"), unit)
    date = _liq5_fmt_date(row.get("date"))
    cls = "live"
    x = _safe_float(row.get("value"))
    if x is not None and transform in {"yoy", "13w", "1m", "3m", "1y_return", "drawdown"} and x < 0:
        cls = "neg"
    return f"{label} {value} · {date}", cls


def _liq3_plot_lines(
    series: Sequence[Tuple[str, pd.DataFrame, str]],
    title: str,
    subtitle: str,
    ytitle: str,
    window: str = "Max",
    source: str = "Public / market data",
    height: int = 385,
    second_axis: Optional[Sequence[str]] = None,
    log_y: bool = False,
    secondary_title: str = "Secondary",
    invert_secondary: bool = False,
    scale_policy: Optional[str] = None,
    secondary_scale_policy: Optional[str] = None,
    common_index_start: Optional[Any] = None,
) -> None:
    del window
    prepared = _liq6_prepare_series(series, common_index_start)
    if not prepared:
        _liq5_render_chart_card(title, subtitle, None, [(source, "gold")], empty_message="No usable observations. Provider state is available in Data Quality.")
        return
    second = set(second_axis or [])
    fig = _liq6_base_figure(
        ytitle=ytitle, height=height, prepared=prepared, second_axis=second,
        scale_policy=scale_policy, secondary_scale_policy=secondary_scale_policy,
        log_y=log_y, secondary_title=secondary_title, invert_secondary=invert_secondary,
    )
    badges: List[Tuple[str, str]] = []
    latest_end = max(pd.Timestamp(frame["date"].max()) for _, frame, _ in prepared)
    for i, (label, use, transform) in enumerate(prepared):
        fig.add_trace(go.Scatter(
            x=use["date"], y=use["value"], mode="lines", name=label,
            line=dict(color=LIQ6_COLORS[i % len(LIQ6_COLORS)], width=2.35 if i == 0 else 2.05, dash="solid" if i < 2 else "dot"),
            connectgaps=False, yaxis="y2" if label in second else "y",
            hovertemplate="%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>",
        ))
        unit = secondary_title if label in second else ytitle
        badges.append(_liq6_badge_from_prepared(label, use, unit, transform))
    badges.append((source, "gold"))
    _liq5_render_chart_card(title, subtitle, fig, badges, f"Latest public observation {_liq5_fmt_date(latest_end)}")


def _liq3_plot_components(frame: pd.DataFrame, columns: Sequence[str], title: str, subtitle: str, ytitle: str, window: str = "Max", source: str = "Public data") -> None:
    del window
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        _liq5_render_chart_card(title, subtitle, None, [(source, "gold")], empty_message="Required components are unavailable.")
        return
    use = frame.copy(); use["date"] = _liq4_datetime_ns(use["date"])
    use = use.dropna(subset=["date"]).sort_values("date")
    prepared: List[Tuple[str, pd.DataFrame, str]] = []
    for col in columns:
        if col in use.columns:
            prepared.append((str(col), _liq6_normalize(pd.DataFrame({"date": use["date"], "value": use[col]})), "level"))
    prepared = [x for x in prepared if not x[1].empty]
    if not prepared:
        _liq5_render_chart_card(title, subtitle, None, [(source, "gold")], empty_message="Required components are unavailable.")
        return
    fig = _liq6_base_figure(ytitle, 395, prepared, scale_policy="positive")
    badges: List[Tuple[str, str]] = []
    latest_end = max(pd.Timestamp(x[1]["date"].max()) for x in prepared)
    for i, (col, data, transform) in enumerate(prepared):
        fig.add_trace(go.Scatter(
            x=data["date"], y=data["value"], mode="lines", stackgroup="one", name=col,
            line=dict(width=1.9, color=LIQ6_COLORS[i % len(LIQ6_COLORS)]),
            hovertemplate="%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>",
        ))
        badges.append(_liq6_badge_from_prepared(col, data, ytitle, transform))
    badges.append((source, "gold"))
    _liq5_render_chart_card(title, subtitle, fig, badges, f"Latest public observation {_liq5_fmt_date(latest_end)}")


def _liq3_plot_score(score_table: pd.DataFrame) -> None:
    work = score_table.copy(); work["Score numeric"] = pd.to_numeric(work.get("Score"), errors="coerce")
    work = work.dropna(subset=["Score numeric"])
    if work.empty:
        _liq5_render_chart_card("Liquidity Regime Components", "Available components only; missing values are not assigned a neutral score.", None, [("Quant Terminal methodology", "gold")], empty_message="No score component is currently available.")
        return
    fig = _liq6_base_figure("Score", 355)
    colors = ["#8bc48a" if x >= 60 else "#e87557" if x <= 40 else "#d9bf58" for x in work["Score numeric"]]
    fig.add_trace(go.Bar(x=work["Component"], y=work["Score numeric"], marker_color=colors, text=work["Score numeric"].map(lambda x: f"{x:.0f}"), textposition="outside", hovertemplate="%{x}<br>%{y:.1f}/100<extra></extra>"))
    fig.update_yaxes(range=[0, 108]); fig.update_xaxes(tickangle=-20)
    _liq5_render_chart_card("Liquidity Regime Components", "Available components only; missing values are not assigned a neutral score.", fig, [("Quant Terminal methodology", "gold"), (f"Coverage {len(work)}/7", "live")], "Transparent weighted score — not a trading recommendation")


def _liq3_plot_heatmap_money(context: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    series = {
        "US M2": _liq3_time_change(frames.get("FRED:M2SL", pd.DataFrame()), 365, True),
        "Euro area M3": context.get("fred", {}).get("EA19MABMM301GYSAM", pd.DataFrame()),
        "Japan M3": context.get("fred", {}).get("JPNMABMM301GYSAM", pd.DataFrame()),
        "UK M3": context.get("fred", {}).get("GBRMABMM301GYSAM", pd.DataFrame()),
    }
    wide: Dict[str, pd.Series] = {}
    for label, frame in series.items():
        use = _liq6_normalize(frame)
        if not use.empty:
            wide[label] = use.set_index("date")["value"].resample("ME").last()
    if not wide:
        _liq5_render_chart_card("G4 Broad-Money Growth Heatmap", "Published or calculated year-over-year growth, monthly as-of.", None, [("FRED/OECD public series", "gold")], empty_message="Global money-growth heatmap unavailable.")
        return
    df = pd.concat(wide, axis=1).tail(48).T
    fig = go.Figure(go.Heatmap(z=df.to_numpy(dtype=float), x=df.columns, y=df.index, colorscale=[[0, "#9e4f48"], [0.5, "#17283a"], [1, "#4f9b6f"]], zmid=0, colorbar=dict(title="YoY %", thickness=12), hovertemplate="%{y}<br>%{x|%b %Y}<br>%{z:.2f}%<extra></extra>"))
    fig.update_layout(height=350, margin=dict(l=92, r=42, t=20, b=48), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=10))
    latest_end = max(df.columns) if len(df.columns) else None
    _liq5_render_chart_card("G4 Broad-Money Growth Heatmap", "Published or calculated year-over-year growth, monthly as-of.", fig, [("FRED/OECD public series", "gold"), (f"4 economies · {df.shape[1]} monthly observations", "live")], f"Latest public observation {_liq5_fmt_date(latest_end)}")


def _liq3_plot_corr_matrix(context: Mapping[str, Any]) -> None:
    frames = context.get("frames", {})
    assets = {"G3": frames.get("G3", pd.DataFrame()), "Net Liquidity": frames.get("NET", pd.DataFrame()), "Bitcoin": frames.get("BTC", pd.DataFrame()), "Gold": frames.get("GOLD", pd.DataFrame()), "S&P 500": frames.get("MKT:SPY", pd.DataFrame()), "Nasdaq": frames.get("MKT:QQQ", pd.DataFrame()), "Dollar": frames.get("FRED:DTWEXBGS", pd.DataFrame())}
    returns: Dict[str, pd.Series] = {}
    for label, frame in assets.items():
        use = _liq6_normalize(frame)
        if not use.empty:
            returns[label] = use.set_index("date")["value"].resample("W-FRI").last().pct_change()
    if len(returns) < 3:
        _liq5_render_chart_card("Liquidity Transmission Correlation Matrix", "Weekly changes over the most recent two years.", None, [("Quant Terminal calculation", "gold")], empty_message="At least three overlapping series are required.")
        return
    wide = pd.concat(returns, axis=1).dropna(how="all").tail(104); corr = wide.corr(min_periods=26)
    fig = go.Figure(go.Heatmap(z=corr.to_numpy(dtype=float), x=corr.columns, y=corr.index, zmin=-1, zmax=1, zmid=0, colorscale=[[0, "#9e4f48"], [0.5, "#17283a"], [1, "#5f9fc7"]], text=np.round(corr.to_numpy(dtype=float), 2), texttemplate="%{text}", hovertemplate="%{y} / %{x}<br>%{z:.2f}<extra></extra>"))
    fig.update_layout(height=410, margin=dict(l=98, r=35, t=20, b=85), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=10))
    _liq5_render_chart_card("Liquidity Transmission Correlation Matrix", "Weekly changes over the most recent two years.", fig, [("Quant Terminal calculation", "gold"), (f"{len(corr.columns)} aligned assets", "live")], f"Window ending {_liq5_fmt_date(wide.index.max())}")


def _liq3_plot_lag(context: Mapping[str, Any], asset_ref: str, title: str) -> None:
    frames = context.get("frames", {}); liquidity = frames.get("NET", pd.DataFrame()) if not frames.get("NET", pd.DataFrame()).empty else frames.get("G3", pd.DataFrame()); asset = frames.get(asset_ref, pd.DataFrame())
    aligned = _liq3_align_returns(liquidity, asset)
    if aligned.empty or len(aligned) < 60:
        _liq5_render_chart_card(title, "Correlation between weekly liquidity changes and subsequent 13-week asset returns; exploratory, not causal.", None, [("Quant Terminal calculation", "gold")], empty_message="Insufficient overlapping history for the lead-lag scan.")
        return
    liq = aligned.set_index("date")["a"]; price = _liq6_normalize(asset).set_index("date")["value"].resample("W-FRI").last(); future13 = price.pct_change(13).shift(-13)
    rows = []
    for lag in range(27):
        pair = pd.concat([liq.shift(lag).rename("liq"), future13.rename("future")], axis=1).dropna(); rows.append((lag, pair["liq"].corr(pair["future"]) if len(pair) >= 30 else np.nan))
    df = pd.DataFrame(rows, columns=["Lag", "Correlation"]).dropna()
    fig = _liq6_base_figure("Correlation", 350)
    fig.add_trace(go.Bar(x=df["Lag"], y=df["Correlation"], marker_color=["#8bc48a" if x >= 0 else "#e87557" for x in df["Correlation"]], hovertemplate="Lag %{x} weeks<br>Corr %{y:.3f}<extra></extra>"))
    fig.update_xaxes(title="Liquidity lead (weeks)"); rng = _liq6_axis_range(df["Correlation"].to_numpy(dtype=float), "signed")
    if rng: fig.update_yaxes(range=rng)
    best = df.iloc[df["Correlation"].abs().argmax()] if not df.empty else None; badge = f"Max |corr| at {int(best['Lag'])} weeks: {best['Correlation']:.3f}" if best is not None else "Exploratory scan"
    _liq5_render_chart_card(title, "Correlation between weekly liquidity changes and subsequent 13-week asset returns; exploratory, not causal.", fig, [(badge, "live"), ("Quant Terminal calculation", "gold")], "Exploratory diagnostic — not causal evidence")


def _liq5_table_card(title: str, subtitle: str, df: pd.DataFrame, badges: Sequence[Tuple[str, str]] = (), asof: str = "", max_rows: int = 150) -> None:
    ctx = _liq5_card_open(title, subtitle, asof)
    with ctx:
        _html('<div class="liq5-card-marker"></div>')
        _html(f'<div class="liq5-chart-title">{_escape(title)}</div><div class="liq5-chart-sub">{_escape(subtitle)}</div>' + (f'<div class="liq5-chart-asof">{_escape(asof)}</div>' if asof else "") + _liq5_html_table(df, max_rows))
        if badges:
            _html('<div class="liq5-badges">' + ''.join(f'<span class="liq5-badge {_escape(cls)}">{_escape(text)}</span>' for text, cls in badges) + '</div>')


def _liq3_render_snapshot(context: Mapping[str, Any], metric: str, title: str) -> None:
    snap = context.get("snapshot", {}) or {}
    if metric == "market_caps":
        rows = [{"Metric": "Total crypto market cap", "Value": _fmt((snap.get("total_market_cap_usd") or np.nan) / 1e12 if snap.get("total_market_cap_usd") else None, 2, "T")}, {"Metric": "Active cryptocurrencies", "Value": str(snap.get("active_cryptocurrencies", "—"))}]
    elif metric == "dominance":
        rows = [{"Metric": "Bitcoin dominance", "Value": _fmt(snap.get("btc_dominance"), 2, "%")}, {"Metric": "Ether dominance", "Value": _fmt(snap.get("eth_dominance"), 2, "%")}]
    elif metric == "stablecoins":
        rows = [{"Metric": "Stablecoin market cap", "Value": _fmt((snap.get("stablecoin_market_cap_usd") or np.nan) / 1e9 if snap.get("stablecoin_market_cap_usd") else None, 1, "B")}]
    else:
        rows = [{"Metric": "24H market-cap change", "Value": _fmt(snap.get("market_cap_change_24h"), 2, "%")}]
    _liq5_table_card(title, "Current provider snapshot; snapshot fields are never represented as fabricated history.", pd.DataFrame(rows), [("CoinGecko global snapshot", "gold")], f"Snapshot {_liq5_fmt_date(datetime.now())}", 12)


def _liq3_render_performance_matrix(context: Mapping[str, Any]) -> None:
    # Kept as a Quant Terminal dashboard helper, intentionally outside the
    # frozen 30-chart Gold publication registry.
    frames = context.get("frames", {}); assets = {"Gold": frames.get("GOLD", pd.DataFrame()), "Silver": frames.get("SILVER", pd.DataFrame()), "Bitcoin": frames.get("BTC", pd.DataFrame()), "S&P 500": frames.get("MKT:SPY", pd.DataFrame())}; horizons = {"1M": 30, "3M": 91, "6M": 182, "1Y": 365}
    matrix, labels = [], []
    for label, frame in assets.items():
        if not _liq6_normalize(frame).empty:
            labels.append(label); matrix.append([_liq3_pct_latest(frame, d) for d in horizons.values()])
    if not matrix:
        _liq5_render_chart_card("Hard-Money Performance Matrix", "Price returns across standard horizons.", None, [("Public market data", "gold")], empty_message="Market prices unavailable."); return
    z = np.array(matrix, dtype=float); fig = go.Figure(go.Heatmap(z=z, x=list(horizons), y=labels, zmid=0, colorscale=[[0, "#9e4f48"], [0.5, "#17283a"], [1, "#4f9b6f"]], text=np.round(z, 1), texttemplate="%{text}%", hovertemplate="%{y}<br>%{x}: %{z:.2f}%<extra></extra>"))
    fig.update_layout(height=350, margin=dict(l=78, r=32, t=20, b=48), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=10))
    _liq5_render_chart_card("Hard-Money Performance Matrix", "Price returns across standard horizons.", fig, [("Public market data", "gold"), (f"{len(labels)} assets", "live")], "Returns through latest available close")


def _liq3_render_spec(spec: Mapping[str, Any], context: Mapping[str, Any], window: str) -> None:
    kind = str(spec.get("kind", "lines")); frames = context.get("frames", {}); title = str(spec.get("title", "Chart")); subtitle = str(spec.get("subtitle", ""))
    if kind == "money_heatmap": _liq3_plot_heatmap_money(context); return
    if kind == "corr_matrix": _liq3_plot_corr_matrix(context); return
    if kind == "pair":
        metric = str(spec.get("metric", "corr")); frame = _liq3_rolling_pair(frames.get(spec.get("left"), pd.DataFrame()), frames.get(spec.get("right"), pd.DataFrame()), int(spec.get("weeks", 26)), metric)
        label = "26W rolling correlation" if metric == "corr" else "26W rolling beta"
        _liq3_plot_lines([(label, frame, "level")], title, subtitle or "Rolling weekly relationship.", str(spec.get("ytitle", "")), window, "Quant Terminal calculation", height=360, scale_policy=str(spec.get("scale_policy", "correlation" if metric == "corr" else "signed")))
        return
    if kind == "lag": _liq3_plot_lag(context, str(spec.get("asset", "BTC")), title); return
    if kind == "snapshot": _liq3_render_snapshot(context, str(spec.get("metric", "market_caps")), title); return
    if kind == "performance_matrix": _liq3_render_performance_matrix(context); return
    series = [(str(label), frames.get(str(ref), pd.DataFrame()), str(transform)) for label, ref, transform in spec.get("series", [])]
    _liq3_plot_lines(
        series, title, subtitle, str(spec.get("ytitle", "")), window,
        str(spec.get("source", "FRED / public market data")), height=360,
        second_axis=spec.get("second_axis"), log_y=bool(spec.get("log_y", False)),
        secondary_title=str(spec.get("secondary_title", "Secondary")),
        invert_secondary=bool(spec.get("invert_secondary", False)),
        scale_policy=spec.get("scale_policy"), secondary_scale_policy=spec.get("secondary_scale_policy"),
        common_index_start=spec.get("common_index_start"),
    )


def _liq6_two_column(tasks: Sequence[Any]) -> None:
    for i in range(0, len(tasks), 2):
        cols = st.columns(2, gap="medium")
        for col, task in zip(cols, tasks[i:i + 2]):
            with col:
                task()


def _liq3_render_overview(context: Mapping[str, Any], score: Mapping[str, Any], score_table: pd.DataFrame, window: str = "Max") -> None:
    del window
    _html(f'<div class="liq3-regime"><b>{_escape(score.get("regime", "Unavailable"))}</b> — {_escape(score.get("read", ""))} The composite is analytical, transparent and not a trading recommendation.</div>')
    tasks = [
        lambda: _liq3_plot_lines([("G3 assets", context["frames"].get("G3", pd.DataFrame()), "level"), ("US net liquidity", context["frames"].get("NET", pd.DataFrame()), "level")], "Core Liquidity Aggregates", "Major central-bank assets and the US liquidity-plumbing proxy.", "USD tn", source="Public / market data", height=370, scale_policy="positive"),
        lambda: _liq3_plot_score(score_table),
        lambda: _liq3_plot_heatmap_money(context),
        lambda: _liq3_plot_lines([("Bitcoin", context["frames"].get("BTC", pd.DataFrame()), "indexed"), ("Gold", context["frames"].get("GOLD", pd.DataFrame()), "indexed"), ("S&P 500", context["frames"].get("MKT:SPY", pd.DataFrame()), "indexed")], "Liquidity-Sensitive Assets", "Assets rebased to 100 from the same common date.", "Index", source="Public / market data", height=370, scale_policy="indexed", common_index_start="2019-07-01"),
    ]
    _liq6_two_column(tasks)
    _liq5_table_card("Score Composition", "Every weight, raw input and definition is visible; unavailable components are reweighted, never imputed.", score_table, [("Quant Terminal methodology", "gold"), (f"Coverage {score.get('coverage', '0/7')}", "live")], "Transparent composite construction", 20)


