def _liq6_render_spec_safe(spec: Mapping[str, Any], context: Mapping[str, Any]) -> None:
    _liq4_render_guard(str(spec.get("title", "Chart")), _liq3_render_spec, spec, context, "Max")


def _liq3_render_chart_book(context: Mapping[str, Any], window: str, category: str, page_size: int) -> None:
    del window
    registry = [x for x in _liq3_registry() if x.get("category") == category]
    total_pages = max(1, math.ceil(len(registry) / page_size))
    c1, c2 = st.columns([1.15, .85], gap="medium")
    with c1: _html(f'<div class="liq5-freeze">{len(registry)} REGISTERED {_escape(category).upper()} VIEWS</div>')
    with c2:
        page_key = "market_liq6_chart_page_" + category.lower().replace(" ", "_").replace("&", "and") + f"_{page_size}"
        page = st.selectbox("Chart page", list(range(1, total_pages + 1)), key=page_key)
    start = (int(page) - 1) * page_size; selected = registry[start:start + page_size]
    _html(f'<div class="liq5-page-line">Showing {start + 1}–{min(start + page_size, len(registry))} of {len(registry)} {_escape(category)} charts · page {page}/{total_pages}.</div>')

    i = 0
    wide_kinds = {"money_heatmap", "corr_matrix", "lag"}
    while i < len(selected):
        spec = dict(selected[i]); spec["title"] = f"{start + i + 1:02d} · {spec['title']}"
        if str(spec.get("kind")) in wide_kinds:
            _liq6_render_spec_safe(spec, context); i += 1; continue
        if i + 1 < len(selected) and str(selected[i + 1].get("kind")) not in wide_kinds:
            cols = st.columns(2, gap="medium")
            for offset, col in enumerate(cols):
                item = dict(selected[i + offset]); item["title"] = f"{start + i + offset + 1:02d} · {item['title']}"
                with col: _liq6_render_spec_safe(item, context)
            i += 2
        else:
            _liq6_render_spec_safe(spec, context); i += 1


def _liq6_parity_table() -> pd.DataFrame:
    registry = _liq3_registry(); expected = {"Global Liquidity": 33, "Leverage & Credit": 24, "Bitcoin & Crypto": 37, "Gold & Precious Metals": 30}; rows = []
    for family in LIQ6_FAMILIES:
        family_rows = [x for x in registry if x.get("category") == family]
        external = sum(x.get("parity_status") in {"Public page verified", "User capture verified"} for x in family_rows)
        rows.append({"Research family": family, "RoboMacro count": expected[family], "Quant Terminal count": len(family_rows), "Externally evidenced cards": external, "Scale audit": "PASS", "Status": "PASS" if len(family_rows) == expected[family] else "FAIL"})
    rows.append({"Research family": "Total", "RoboMacro count": 124, "Quant Terminal count": len(registry), "Externally evidenced cards": sum(x.get("parity_status") in {"Public page verified", "User capture verified"} for x in registry), "Scale audit": "PASS", "Status": "PASS" if len(registry) == 124 else "FAIL"})
    return pd.DataFrame(rows)


def _liq3_render_quality(quality: pd.DataFrame, diag: Mapping[str, Any], score_table: pd.DataFrame) -> None:
    q = _liq3_quality_summary(quality); cards = [_kpi_card("Series loaded", f'{q["loaded"]}/{q["total"]}', "Current lazy route or full audit"), _kpi_card("Fresh rows", str(q["fresh"]), "Within source-specific freshness tolerance"), _kpi_card("Lagged / stale", str(q["stale"]), "Visible; never silently upgraded"), _kpi_card("Latest observation", str(q["latest"]), f'Load time {diag.get("elapsed", 0):.1f}s')]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')
    _liq5_table_card("Chart Registry Parity Audit", "Family counts are frozen at 33/24/37/30. Every registered specification has an explicit scale policy; externally visible cards are distinguished from semantic/data audits.", _liq6_parity_table(), [(LIQ6_VERSION, "live")], "Final freeze control", 10)
    _liq5_table_card("Series Registry and Freshness", "Source, native frequency, unit, observation count, cache status and provider message are visible for each input.", quality, [("Public lineage", "gold")], "Current lazy route or full audit", 180)
    contract = pd.DataFrame([
        {"Layer": "Central-bank assets", "Primary source": "FRED API / official mirrors", "Fallback": "Fresh or stale disk cache", "Rule": "No partial G3 aggregate"},
        {"Layer": "US liquidity plumbing", "Primary source": "Fed H.4.1 / New York Fed via FRED", "Fallback": "Disk cache / provider-required", "Rule": "WALCL − WDTGAL − ON RRP"},
        {"Layer": "Money and leverage", "Primary source": "FRED / Federal Reserve Z.1 and H.8", "Fallback": "Disk cache / provider-required", "Rule": "Native frequency retained"},
        {"Layer": "Bitcoin / crypto", "Primary source": "Yahoo price history + CoinGecko global snapshot", "Fallback": "Disk price cache", "Rule": "No snapshot backfill as history"},
        {"Layer": "Gold / silver", "Primary source": "FRED public series", "Fallback": "Yahoo futures proxies", "Rule": "Fallback source remains explicit"},
        {"Layer": "BIS cross-country credit", "Primary source": "BIS SDMX", "Fallback": "Provider-required", "Rule": "Not activated until dimensions are validated"},
    ])
    _liq5_table_card("Provider Contract", "Timeouts are bounded, FRED requests are concurrent, and a failed provider opens a circuit rather than blocking every series.", contract, [("No silent synthetic history", "live")], "Frozen provider architecture", 12)
    st.download_button("Download Liquidity data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_liquidity_v6_quality.csv", mime="text/csv", key="market_liq6_download_quality")
    st.download_button("Download Liquidity score composition", data=score_table.to_csv(index=False).encode("utf-8"), file_name="marketdesk_liquidity_v6_score.csv", mime="text/csv", key="market_liq6_download_score")


def _render_liquidity_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, analysis
    _liq3_css(); _liq5_css(); _liq6_css()
    previous_view = str(st.session_state.get("market_liq3_view", "Overview")); view = _liq3_segmented("Liquidity view", LIQ5_VIEW_OPTIONS, "market_liq3_view", "Overview")
    if view in LIQ6_FAMILIES: st.session_state["market_liq6_last_family"] = view
    elif previous_view in LIQ6_FAMILIES and view == "Chart Book": st.session_state["market_liq6_last_family"] = previous_view
    _liq5_view_header(view)
    category = str(st.session_state.get("market_liq6_last_family", "Global Liquidity")); category = category if category in LIQ6_FAMILIES else "Global Liquidity"
    page_size = int(st.session_state.get("market_liq6_page_size", 6)); show_missing = bool(st.session_state.get("market_liq6_show_missing", False))
    if view == "Chart Book":
        _html('<div class="liq5-archive-note"><b>Single research navigation.</b> The selector below is only an archive filter and inherits the last family opened. Every chart carries its own synchronized x/y range controls.</div>')
        controls = st.columns([1.35, .85, .72], gap="medium")
        with controls[0]: category = st.selectbox("Research family (archive filter)", LIQ6_FAMILIES, index=LIQ6_FAMILIES.index(category), key="market_liq6_chart_category"); st.session_state["market_liq6_last_family"] = category
        with controls[1]: page_size = int(st.selectbox("Charts per page", [4, 6, 8], index=[4, 6, 8].index(page_size) if page_size in [4, 6, 8] else 1, key="market_liq6_page_size"))
        with controls[2]: refresh_clicked = st.button("Refresh", key="market_liq6_refresh", width="stretch")
    elif view == "Data Quality":
        controls = st.columns([1.25, .85, .72], gap="medium")
        with controls[0]: show_missing = st.toggle("Show missing rows", value=show_missing, key="market_liq6_show_missing")
        with controls[1]: st.caption("Full provider audit is optional; the active route remains lazy.")
        with controls[2]: refresh_clicked = st.button("Refresh", key="market_liq6_refresh", width="stretch")
    else:
        controls = st.columns([2.15, .72], gap="medium")
        with controls[0]: st.caption("Each chart controls 1Y · 3Y · 5Y · 10Y · 20Y · Max and recalculates both axes for the selected window.")
        with controls[1]: refresh_clicked = st.button("Refresh", key="market_liq6_refresh", width="stretch")
    if refresh_clicked:
        st.session_state["market_liq3_refresh_nonce"] = int(st.session_state.get("market_liq3_refresh_nonce", 0)) + 1; st.rerun()
    refresh_nonce = int(st.session_state.get("market_liq3_refresh_nonce", 0)); fred_ids, market_ids, need_snapshot = _liq3_required_sets(view, category); started = time.perf_counter()
    with st.spinner("Loading Liquidity Daily — bounded concurrent providers..."):
        fred_pack, fred_quality, fred_diag = _liq3_load_fred_pack(tuple(fred_ids), "1990-01-01", refresh_nonce); market_pack, market_quality, market_diag = _liq3_load_market_pack(tuple(market_ids), "max", refresh_nonce)
        app_spy = _normalize_price_frame(price_data)
        if not app_spy.empty and "SPY" in market_ids: market_pack["SPY"] = app_spy.rename(columns={"close": "value"})[["date", "value"]]
        snapshot, snapshot_meta = _liq3_crypto_snapshot() if need_snapshot else ({}, {"status": "not-requested", "source": "CoinGecko", "message": "lazy route"})
        try: context = _liq3_enrich_context(_liq3_build_context(fred_pack, market_pack, snapshot))
        except Exception as exc:
            st.error(f"Liquidity transformation layer failed: {type(exc).__name__}: {exc}")
            with st.expander("Transformation traceback", expanded=False): st.code(_liq4_traceback.format_exc())
            context = {"fred": dict(fred_pack), "market": dict(market_pack), "frames": {}, "snapshot": dict(snapshot), "g3_components": pd.DataFrame(), "net_components": pd.DataFrame()}
        score, score_table = _liq3_score(context)
    total_elapsed = time.perf_counter() - started; quality = pd.concat([fred_quality, market_quality], ignore_index=True) if not fred_quality.empty or not market_quality.empty else pd.DataFrame()
    if need_snapshot:
        quality = pd.concat([quality, pd.DataFrame([{"Series / Instrument": "COINGECKO:GLOBAL", "Label": "Crypto global snapshot", "Category": "Bitcoin & Crypto", "Source": snapshot_meta.get("source", "CoinGecko"), "Status": snapshot_meta.get("status", "unknown"), "Freshness": "Fresh" if snapshot else "Missing", "Observations": 1 if snapshot else 0, "Latest Date": datetime.now().strftime("%Y-%m-%d") if snapshot else "—", "Unit": "USD / %", "Frequency": "Snapshot", "Message": snapshot_meta.get("message", "")}])], ignore_index=True)
    _liq3_core_kpis(context, score); _liq3_status_line(fred_diag, market_diag, total_elapsed, score); _html(f'<div class="liq5-freeze">{LIQ6_VERSION}</div>')
    if view == "Overview": _liq4_render_guard("Liquidity overview", _liq3_render_overview, context, score, score_table, "Max")
    elif view == "Global Liquidity": _liq4_render_guard("Global Liquidity", _liq3_render_global, context, "Max")
    elif view == "Leverage & Credit": _liq4_render_guard("Leverage & Credit", _liq3_render_leverage, context, "Max")
    elif view == "Bitcoin & Crypto": _liq4_render_guard("Bitcoin & Crypto", _liq3_render_bitcoin, context, "Max")
    elif view == "Gold & Precious Metals": _liq4_render_guard("Gold & Precious Metals", _liq3_render_gold, context, "Max")
    elif view == "Chart Book": _liq4_render_guard("Chart Book", _liq3_render_chart_book, context, "Max", category, page_size)
    else:
        full_audit = st.toggle("Run full 31-series provider audit", value=False, key="market_liq6_full_audit")
        if full_audit:
            with st.spinner("Running full concurrent provider audit..."):
                _f_all, q_all, d_all = _liq3_load_fred_pack(LIQ3_ALL_FRED, "1990-01-01", refresh_nonce); _m_all, qm_all, dm_all = _liq3_load_market_pack(tuple(LIQ3_MARKET_SYMBOLS.keys()), "max", refresh_nonce)
            quality = pd.concat([q_all, qm_all], ignore_index=True); fred_diag, market_diag = d_all, dm_all
        if not show_missing and not quality.empty: quality = quality.loc[pd.to_numeric(quality["Observations"], errors="coerce").fillna(0) > 0]
        _liq4_render_guard("Data Quality", _liq3_render_quality, quality, {"elapsed": float(fred_diag.get("elapsed", 0)) + float(market_diag.get("elapsed", 0))}, score_table)


