def _fx7_cache_paths(namespace: str, key: str) -> Tuple[_fx7_Path, _fx7_Path]:
    safe = _fx7_hashlib.sha256(str(key).encode("utf-8")).hexdigest()[:24]
    folder = FX7_CACHE_ROOT / namespace
    return folder / f"{safe}.csv", folder / f"{safe}.json"


def _fx7_read_cache(namespace: str, key: str) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    data_path, meta_path = _fx7_cache_paths(namespace, key)
    if not data_path.exists() or not meta_path.exists():
        return pd.DataFrame(), {}
    try:
        frame = pd.read_csv(data_path, dtype=str)
        if "date" in frame.columns:
            frame["date"] = pd.to_datetime(frame["date"], errors="coerce").dt.tz_localize(None)
        identifier_columns = {"code", "cftc_contract_market_code", "pair", "symbol", "currency", "tenor"}
        for col in frame.columns:
            if col == "date":
                continue
            if str(col).lower() in identifier_columns:
                frame[col] = frame[col].astype("string").str.strip()
                continue
            raw = frame[col]
            converted = pd.to_numeric(raw, errors="coerce")
            nonempty = raw.notna() & raw.astype(str).str.strip().ne("")
            if not nonempty.any() or converted.loc[nonempty].notna().all():
                frame[col] = converted
        meta = _fx7_json.loads(meta_path.read_text(encoding="utf-8"))
        return frame.dropna(how="all").reset_index(drop=True), meta if isinstance(meta, dict) else {}
    except Exception:
        return pd.DataFrame(), {}


def _fx7_write_cache(namespace: str, key: str, frame: pd.DataFrame, meta: Mapping[str, Any]) -> None:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return
    data_path, meta_path = _fx7_cache_paths(namespace, key)
    try:
        data_path.parent.mkdir(parents=True, exist_ok=True)
        frame.to_csv(data_path, index=False)
        payload = dict(meta)
        payload["cached_at_utc"] = datetime.now(timezone.utc).isoformat()
        meta_path.write_text(_fx7_json.dumps(payload, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass


def _fx7_cache_age(meta: Mapping[str, Any]) -> Optional[float]:
    raw = str(meta.get("cached_at_utc", "") or "")
    if not raw:
        return None
    try:
        stamp = pd.Timestamp(raw)
        if stamp.tzinfo is None:
            stamp = stamp.tz_localize("UTC")
        return max(0.0, (pd.Timestamp.now(tz="UTC") - stamp).total_seconds() / 3600.0)
    except Exception:
        return None


def _fx7_frame(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=["date", "value"])
    use = frame.copy()
    if "date" not in use.columns:
        use = use.reset_index()
    if "value" not in use.columns:
        candidates = [c for c in use.columns if str(c).lower() in {"close", "adj close", "adj_close", "price"}]
        if not candidates:
            candidates = [c for c in use.columns if c != "date"]
        if not candidates:
            return pd.DataFrame(columns=["date", "value"])
        use = use.rename(columns={candidates[0]: "value"})
    use["date"] = pd.to_datetime(use["date"], errors="coerce").dt.tz_localize(None).astype("datetime64[ns]")
    use["value"] = pd.to_numeric(use["value"], errors="coerce")
    return use[["date", "value"]].dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _fx7_pct_change(frame: pd.DataFrame, periods: int) -> Optional[float]:
    use = _fx7_frame(frame)
    if len(use) <= periods:
        return None
    a = _safe_float(use.iloc[-1]["value"])
    b = _safe_float(use.iloc[-periods - 1]["value"])
    if a is None or b in {None, 0}:
        return None
    return (a / b - 1.0) * 100.0


def _fx7_log_returns(frame: pd.DataFrame) -> pd.DataFrame:
    use = _fx7_frame(frame)
    if use.empty:
        return use
    values = use["value"].where(use["value"] > 0)
    out = pd.DataFrame({"date": use["date"], "value": np.log(values).diff()})
    return out.dropna().reset_index(drop=True)


def _fx7_rvol(frame: pd.DataFrame, window: int) -> pd.DataFrame:
    ret = _fx7_log_returns(frame)
    if ret.empty:
        return ret
    return pd.DataFrame({"date": ret["date"], "value": ret["value"].rolling(window).std(ddof=1) * math.sqrt(252.0) * 100.0}).dropna().reset_index(drop=True)


def _fx7_rolling_corr(left: pd.DataFrame, right: pd.DataFrame, window: int = 20) -> pd.DataFrame:
    a = _fx7_frame(left).rename(columns={"value": "a"})
    b = _fx7_frame(right).rename(columns={"value": "b"})
    if a.empty or b.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(a.sort_values("date"), b.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna()
    merged["value"] = merged["a"].rolling(window).corr(merged["b"])
    return merged[["date", "value"]].dropna().reset_index(drop=True)


def _fx7_latest(frame: pd.DataFrame) -> Optional[float]:
    use = _fx7_frame(frame)
    return _safe_float(use.iloc[-1]["value"]) if not use.empty else None


def _fx7_latest_date(frame: pd.DataFrame) -> Optional[pd.Timestamp]:
    use = _fx7_frame(frame)
    return pd.Timestamp(use.iloc[-1]["date"]) if not use.empty else None


def _fx7_twelve_key() -> str:
    for name in ("TWELVE_DATA_API_KEY", "TWELVEDATA_API_KEY", "TWELVE_API_KEY"):
        value = _secret_or_env(name, "")
        if value:
            return value
    return ""


def _fx7_parse_twelve(payload: Mapping[str, Any]) -> pd.DataFrame:
    values = payload.get("values", []) if isinstance(payload, Mapping) else []
    if not isinstance(values, list) or not values:
        return pd.DataFrame(columns=["date", "value"])
    raw = pd.DataFrame(values)
    if "datetime" not in raw.columns or "close" not in raw.columns:
        return pd.DataFrame(columns=["date", "value"])
    out = pd.DataFrame({"date": pd.to_datetime(raw["datetime"], errors="coerce"), "value": pd.to_numeric(raw["close"], errors="coerce")})
    return _fx7_frame(out)


def _fx7_fetch_twelve(pair: str, force: bool = False) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    spec = FX7_PAIRS[pair]
    cache_key = f"{pair}|1day|max"
    cached, meta = _fx7_read_cache("spot", cache_key)
    age = _fx7_cache_age(meta)
    if not force and not cached.empty and age is not None and age <= FX7_CACHE_TTL_HOURS:
        return _fx7_frame(cached), {"status": "cache", "source": meta.get("source", "Twelve Data cache"), "message": "fresh disk cache"}
    api_key = _fx7_twelve_key()
    if not api_key or not REQUESTS_AVAILABLE or requests is None:
        return _fx7_frame(cached), {"status": "stale-cache" if not cached.empty else "not-configured", "source": meta.get("source", "Twelve Data"), "message": "Twelve Data API key not configured"}
    try:
        response = requests.get(
            "https://api.twelvedata.com/time_series",
            params={"symbol": spec["td"], "interval": "1day", "outputsize": 5000, "order": "ASC", "apikey": api_key},
            timeout=(FX7_CONNECT_TIMEOUT, FX7_READ_TIMEOUT),
            headers={"User-Agent": "QuantTerminal-MarketDesk-FX/7.0"},
        )
        response.raise_for_status()
        payload = response.json()
        if isinstance(payload, Mapping) and str(payload.get("status", "")).lower() == "error":
            raise ValueError(str(payload.get("message", "Twelve Data error")))
        frame = _fx7_parse_twelve(payload)
        if frame.empty:
            raise ValueError("No Twelve Data observations")
        _fx7_write_cache("spot", cache_key, frame, {"source": "Twelve Data", "status": "live"})
        return frame, {"status": "live", "source": "Twelve Data", "message": ""}
    except Exception as exc:
        return _fx7_frame(cached), {"status": "stale-cache" if not cached.empty else "provider-unavailable", "source": meta.get("source", "Twelve Data"), "message": str(exc)[:220]}


@st.cache_data(ttl=1800, show_spinner=False)
def _fx7_load_spot_pack(pairs: Tuple[str, ...], refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter()
    requested = tuple(dict.fromkeys(p for p in pairs if p in FX7_PAIRS))
    pack: Dict[str, pd.DataFrame] = {}
    meta: Dict[str, Dict[str, Any]] = {}
    force = bool(refresh_token)

    if _fx7_twelve_key() and requested:
        with _fx7_ThreadPoolExecutor(max_workers=min(6, len(requested))) as executor:
            futures = {executor.submit(_fx7_fetch_twelve, pair, force): pair for pair in requested}
            for future in _fx7_as_completed(futures):
                pair = futures[future]
                try:
                    frame, state = future.result()
                except Exception as exc:
                    frame, state = pd.DataFrame(), {"status": "provider-unavailable", "source": "Twelve Data", "message": str(exc)[:180]}
                if not frame.empty:
                    pack[pair] = _fx7_frame(frame)
                meta[pair] = state

    missing = [p for p in requested if p not in pack or pack[p].empty]
    if missing:
        yf_symbols = tuple(FX7_PAIRS[p]["yf"] for p in missing)
        yf_pack, _yf_quality, yf_diag = _liq3_load_market_pack(yf_symbols, "max", refresh_token)
        for pair in missing:
            symbol = FX7_PAIRS[pair]["yf"]
            frame = _fx7_frame(yf_pack.get(symbol, pd.DataFrame()))
            if not frame.empty:
                pack[pair] = frame
                meta[pair] = {"status": "live-or-cache", "source": "Yahoo/yfinance batch", "message": "Twelve Data fallback" if _fx7_twelve_key() else ""}
            elif pair not in meta:
                meta[pair] = {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": str(yf_diag)}

    rows = []
    for pair in requested:
        frame = _fx7_frame(pack.get(pair, pd.DataFrame()))
        latest = _fx7_latest_date(frame)
        state = meta.get(pair, {})
        rows.append({
            "Series / Instrument": pair,
            "Label": pair,
            "Category": "FX Spot",
            "Source": state.get("source", "Twelve Data / Yahoo"),
            "Status": state.get("status", "provider-unavailable"),
            "Freshness": _liq_freshness(latest, 8) if latest is not None else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—",
            "Unit": pair,
            "Frequency": "Daily",
            "Message": state.get("message", ""),
        })
    return pack, pd.DataFrame(rows), {"elapsed": time.perf_counter() - started, "provider": "Twelve Data + Yahoo" if _fx7_twelve_key() else "Yahoo/yfinance batch"}


@st.cache_data(ttl=1800, show_spinner=False)
def _fx7_load_context_markets(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    symbols = tuple(spec["yf"] for spec in FX7_CONTEXT_MARKETS.values())
    raw, quality, diag = _liq3_load_market_pack(symbols, "max", refresh_token)
    pack = {key: _fx7_frame(raw.get(spec["yf"], pd.DataFrame())) for key, spec in FX7_CONTEXT_MARKETS.items()}
    if not quality.empty:
        reverse = {spec["yf"]: key for key, spec in FX7_CONTEXT_MARKETS.items()}
        quality = quality.copy()
        quality["Series / Instrument"] = quality["Series / Instrument"].map(lambda x: reverse.get(str(x), str(x)))
        quality["Category"] = "FX Context"
    return pack, quality, diag


def _fx7_load_rates(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    ids = tuple(spec["sid"] for spec in FX7_RATE_SERIES.values())
    pack, quality, diag = _liq3_load_fred_pack(ids, "1990-01-01", refresh_token)
    out = {ccy: _fx7_frame(pack.get(spec["sid"], pd.DataFrame())) for ccy, spec in FX7_RATE_SERIES.items()}
    return out, quality, diag


def _fx7_cftc_cache_key() -> str:
    return "tff-futures-only|g10-fx|2018"


def _fx7_fetch_cftc(force: bool = False) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    cached, meta = _fx7_read_cache("cftc", _fx7_cftc_cache_key())
    age = _fx7_cache_age(meta)
    if not force and not cached.empty and age is not None and age <= FX7_CFTC_CACHE_TTL_HOURS:
        raw = cached
        status, source, message = "cache", meta.get("source", "CFTC TFF cache"), "fresh disk cache"
    else:
        raw = pd.DataFrame()
        status, source, message = "provider-unavailable", "CFTC Socrata TFF", ""
        if REQUESTS_AVAILABLE and requests is not None:
            try:
                codes = ",".join(f"'{x}'" for x in FX7_CFTC_CODES.values())
                params = {
                    "$select": "report_date_as_yyyy_mm_dd,cftc_contract_market_code,market_and_exchange_names,open_interest_all,lev_money_positions_long_all,lev_money_positions_short_all",
                    "$where": f"cftc_contract_market_code in ({codes}) AND report_date_as_yyyy_mm_dd >= '2018-01-01T00:00:00.000'",
                    "$order": "report_date_as_yyyy_mm_dd ASC",
                    "$limit": 5000,
                }
                response = requests.get(
                    "https://publicreporting.cftc.gov/resource/gpe5-46if.json",
                    params=params,
                    timeout=(FX7_CONNECT_TIMEOUT, FX7_READ_TIMEOUT),
                    headers={"User-Agent": "QuantTerminal-MarketDesk-FX/7.0"},
                )
                response.raise_for_status()
                raw = pd.DataFrame(response.json())
                if raw.empty:
                    raise ValueError("No CFTC TFF rows")
                raw["date"] = pd.to_datetime(raw["report_date_as_yyyy_mm_dd"], errors="coerce").dt.tz_localize(None)
                raw["code"] = raw["cftc_contract_market_code"].astype(str).str.strip()
                raw["open_interest"] = pd.to_numeric(raw["open_interest_all"], errors="coerce")
                raw["long"] = pd.to_numeric(raw["lev_money_positions_long_all"], errors="coerce")
                raw["short"] = pd.to_numeric(raw["lev_money_positions_short_all"], errors="coerce")
                raw["net"] = raw["long"] - raw["short"]
                raw = raw[["date", "code", "open_interest", "long", "short", "net"]].dropna(subset=["date", "code", "net"])
                _fx7_write_cache("cftc", _fx7_cftc_cache_key(), raw, {"source": "CFTC Socrata TFF", "status": "live"})
                status, source = "live", "CFTC Socrata TFF"
            except Exception as exc:
                message = str(exc)[:220]
        if raw.empty and not cached.empty:
            raw = cached
            status, source = "stale-cache", meta.get("source", "CFTC TFF cache")
            message = message or "live refresh failed; stale cache used"

    frames: Dict[str, pd.DataFrame] = {}
    rows = []
    reverse = {code: ccy for ccy, code in FX7_CFTC_CODES.items()}
    if not raw.empty:
        raw = raw.copy()
        if "date" not in raw.columns and "report_date_as_yyyy_mm_dd" in raw.columns:
            raw["date"] = pd.to_datetime(raw["report_date_as_yyyy_mm_dd"], errors="coerce")
        if "code" not in raw.columns and "cftc_contract_market_code" in raw.columns:
            raw["code"] = raw["cftc_contract_market_code"].astype(str).str.strip()
        for col in ("open_interest", "long", "short", "net"):
            if col in raw.columns:
                raw[col] = pd.to_numeric(raw[col], errors="coerce")
        for code, ccy in reverse.items():
            sub = raw.loc[raw["code"].astype(str).str.strip() == code].copy().sort_values("date")
            if sub.empty:
                continue
            sub["zscore"] = (sub["net"] - sub["net"].rolling(104, min_periods=52).mean()) / sub["net"].rolling(104, min_periods=52).std(ddof=1)
            frames[ccy] = sub[["date", "net", "open_interest", "long", "short", "zscore"]].dropna(subset=["date"]).reset_index(drop=True)
    for ccy, code in FX7_CFTC_CODES.items():
        frame = frames.get(ccy, pd.DataFrame())
        latest = pd.Timestamp(frame["date"].max()) if not frame.empty else None
        rows.append({
            "Series / Instrument": f"CFTC:{ccy}", "Label": f"{ccy} leveraged-money positioning", "Category": "FX Positioning",
            "Source": source, "Status": status if not frame.empty else "provider-unavailable", "Freshness": _liq_freshness(latest, 12) if latest is not None else "Missing",
            "Observations": len(frame), "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—", "Unit": "Contracts", "Frequency": "Weekly", "Message": message,
        })
    return frames, pd.DataFrame(rows), {"provider": source, "status": status, "message": message}


@st.cache_data(ttl=21600, show_spinner=False)
def _fx7_load_cftc(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    return _fx7_fetch_cftc(bool(refresh_token))


def _fx7_pair_stats(pair: str, frame: pd.DataFrame) -> Dict[str, Any]:
    use = _fx7_frame(frame)
    rv5, rv20, rv60, rv252 = (_fx7_rvol(use, x) for x in (5, 20, 60, 252))
    current20 = _fx7_latest(rv20)
    historical = rv20.tail(300)["value"] if not rv20.empty else pd.Series(dtype=float)
    percentile = float((historical <= current20).mean() * 100.0) if current20 is not None and not historical.empty else None
    return {
        "pair": pair,
        "spot": _fx7_latest(use),
        "date": _fx7_latest_date(use),
        "chg1": _fx7_pct_change(use, 1),
        "chg5": _fx7_pct_change(use, 5),
        "chg20": _fx7_pct_change(use, 20),
        "chg60": _fx7_pct_change(use, 60),
        "rv5": _fx7_latest(rv5), "rv20": current20, "rv60": _fx7_latest(rv60), "rv252": _fx7_latest(rv252),
        "pctile": percentile,
        "rv5_frame": rv5, "rv20_frame": rv20, "rv60_frame": rv60, "rv252_frame": rv252,
    }


def _fx7_signal(percentile: Optional[float]) -> str:
    if percentile is None:
        return "Unavailable"
    if percentile < 30:
        return "Cheap"
    if percentile > 70:
        return "Rich"
    return "Fair"


def _fx7_percentile_band(percentile: Optional[float]) -> str:
    if percentile is None or not np.isfinite(percentile):
        return "Unavailable"
    if percentile < 30:
        return "Low"
    if percentile > 70:
        return "High"
    return "Fair"


def _fx7_regime(stats: Mapping[str, Any]) -> Tuple[str, str]:
    rv5 = _safe_float(stats.get("rv5")); rv60 = _safe_float(stats.get("rv60")); pct = _safe_float(stats.get("pctile"))
    ratio = rv5 / rv60 if rv5 is not None and rv60 not in {None, 0} else None
    if ratio is None:
        return "Unavailable", "Insufficient realized-volatility history."
    if ratio > 1.8:
        return "Event Risk", "Short-window volatility is spiking relative to the 60-day regime."
    if ratio > 1.3 and pct is not None and pct > 70:
        return "Sustained Stress", "Short-term volatility is elevated and the 20-day level is historically rich."
    return "Calm", "Short-term volatility remains inside the normal range."


def _fx7_rate_latest(rates: Mapping[str, pd.DataFrame], ccy: str) -> Optional[float]:
    return _fx7_latest(rates.get(ccy, pd.DataFrame()))


def _fx7_pair_carry(pair: str, rates: Mapping[str, pd.DataFrame]) -> Optional[float]:
    spec = FX7_PAIRS[pair]
    base = _fx7_rate_latest(rates, spec["base"]); quote = _fx7_rate_latest(rates, spec["quote"])
    if base is None or quote is None:
        return None
    return base - quote


def _fx7_currency_usd_frames(spot: Mapping[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    out: Dict[str, pd.DataFrame] = {}
    direct = {"EUR": "EURUSD", "GBP": "GBPUSD", "AUD": "AUDUSD"}
    inverse = {"JPY": "USDJPY", "CHF": "USDCHF", "CAD": "USDCAD", "NOK": "USDNOK", "SEK": "USDSEK"}
    for ccy, pair in direct.items():
        out[ccy] = _fx7_frame(spot.get(pair, pd.DataFrame()))
    for ccy, pair in inverse.items():
        use = _fx7_frame(spot.get(pair, pd.DataFrame()))
        if not use.empty:
            use = use.copy(); use["value"] = 1.0 / use["value"].replace(0, np.nan); out[ccy] = use.dropna()
    date_parts = [f["date"] for f in out.values() if isinstance(f, pd.DataFrame) and not f.empty and "date" in f.columns]
    all_dates = pd.concat(date_parts, ignore_index=True) if date_parts else pd.Series(dtype="datetime64[ns]")
    if not all_dates.empty:
        idx = pd.DataFrame({"date": pd.Series(pd.to_datetime(all_dates.unique())).sort_values()})
        idx["value"] = 1.0; out["USD"] = idx.reset_index(drop=True)
    return out


def _fx7_cross_frame(currency_usd: Mapping[str, pd.DataFrame], long_ccy: str, short_ccy: str) -> pd.DataFrame:
    a = _fx7_frame(currency_usd.get(long_ccy, pd.DataFrame())).rename(columns={"value": "a"})
    b = _fx7_frame(currency_usd.get(short_ccy, pd.DataFrame())).rename(columns={"value": "b"})
    if a.empty or b.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(a.sort_values("date"), b.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna()
    merged["value"] = merged["a"] / merged["b"].replace(0, np.nan)
    return _fx7_frame(merged[["date", "value"]])


def _fx7_carry_matrices(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame]) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    currencies = list(FX7_CARRY_CURRENCIES)
    rate_map = {c: _fx7_rate_latest(rates, c) for c in currencies}
    carry = pd.DataFrame(index=currencies, columns=currencies, dtype=float)
    vol = pd.DataFrame(index=currencies, columns=currencies, dtype=float)
    ctv = pd.DataFrame(index=currencies, columns=currencies, dtype=float)
    currency_usd = _fx7_currency_usd_frames(spot)
    for row in currencies:
        for col in currencies:
            if row == col:
                continue
            r1, r2 = rate_map.get(row), rate_map.get(col)
            if r1 is not None and r2 is not None:
                carry.loc[row, col] = r1 - r2
            cross = _fx7_cross_frame(currency_usd, row, col)
            rv = _fx7_latest(_fx7_rvol(cross, 90))
            if rv is not None:
                vol.loc[row, col] = rv
            if pd.notna(carry.loc[row, col]) and rv not in {None, 0}:
                ctv.loc[row, col] = float(np.clip(carry.loc[row, col] / rv, -5, 5))
    return carry, vol, ctv


def _fx7_build_monitor_table(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    rows = []
    for pair in FX7_PAIRS:
        stats = _fx7_pair_stats(pair, spot.get(pair, pd.DataFrame()))
        carry = _fx7_pair_carry(pair, rates)
        ctv = carry / stats["rv20"] if carry is not None and stats["rv20"] not in {None, 0} else None
        rows.append({
            "Pair": pair,
            "Spot": stats["spot"],
            "Chg%": stats["chg1"],
            "5D RVol": stats["rv5"],
            "20D RVol": stats["rv20"],
            "60D RVol": stats["rv60"],
            "252D RVol": stats["rv252"],
            "20D Pctile": stats["pctile"],
            "Signal": _fx7_signal(stats["pctile"]),
            "Carry": carry,
            "Carry/Vol": ctv,
            "Latest Date": stats["date"].strftime("%Y-%m-%d") if stats["date"] is not None else "—",
        })
    return pd.DataFrame(rows)


def _fx7_fmt_monitor_table(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df
    out = df.copy()
    decimals = {p: FX7_PAIRS[p]["decimals"] for p in FX7_PAIRS}
    out["Spot"] = ["—" if pd.isna(v) else f"{v:.{decimals.get(p, 4)}f}" for p, v in zip(out["Pair"], out["Spot"])]
    for col in ("Chg%", "5D RVol", "20D RVol", "60D RVol", "252D RVol", "20D Pctile", "Carry"):
        out[col] = out[col].map(lambda x: "—" if pd.isna(x) else f"{x:+.2f}%" if col in {"Chg%", "Carry"} else f"{x:.2f}%" if col != "20D Pctile" else f"{x:.0f}th")
    out["Carry/Vol"] = out["Carry/Vol"].map(lambda x: "—" if pd.isna(x) else f"{x:+.3f}")
    return out


def _fx7_monitor_view_table(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df
    out = _fx7_fmt_monitor_table(df)
    pct = []
    for _, raw in df.iterrows():
        value = _safe_float(raw.get("20D Pctile"))
        pct.append("—" if value is None else f"{_fx7_percentile_band(value)} {value:.0f}%")
    out["20D Pctile (vs 1Y)"] = pct
    cols = ["Pair", "Spot", "Chg%", "5D RVol", "20D RVol", "60D RVol", "252D RVol", "20D Pctile (vs 1Y)"]
    return out[[c for c in cols if c in out.columns]]


def _fx7_rv_view_table(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df
    out = _fx7_fmt_monitor_table(df)
    cols = ["Pair", "20D RVol", "60D RVol", "252D RVol", "20D Pctile", "Signal", "Carry/Vol"]
    return out[[c for c in cols if c in out.columns]]


def _fx7_base_figure(ytitle: str = "", height: int = 385) -> go.Figure:
    fig = go.Figure()
    fig.update_layout(
        height=height, margin=dict(l=58, r=52, t=48, b=62), paper_bgcolor="#050c15", plot_bgcolor="#08131f",
        font=dict(color="#dce5ed", family="Inter, Arial, sans-serif", size=11), hovermode="x unified",
        legend=dict(orientation="h", y=-.19, x=0, bgcolor="rgba(0,0,0,0)", font=dict(size=10)),
        xaxis=dict(showgrid=True, gridcolor="rgba(130,150,170,.20)", zeroline=False),
        yaxis=dict(title=ytitle, showgrid=True, gridcolor="rgba(130,150,170,.20)", zerolinecolor="rgba(200,200,200,.25)"),
        modebar=dict(bgcolor="rgba(0,0,0,0)", color="#7f8b99", activecolor="#d6bd65"), uirevision="fx7-final",
    )
    return fig


def _fx7_window_buttons(fig: go.Figure, series: Sequence[pd.DataFrame], y_policy: str = "auto", y2_series: Sequence[pd.DataFrame] = (), y2_policy: str = "auto", invert_y2: bool = False) -> None:
    frames = [_fx7_frame(x) for x in series if not _fx7_frame(x).empty]
    if not frames:
        return
    end = max(pd.Timestamp(x["date"].max()) for x in frames)
    start_all = min(pd.Timestamp(x["date"].min()) for x in frames)
    buttons = []
    for label, years in FX7_WINDOWS:
        start = start_all if years is None else max(start_all, end - pd.DateOffset(years=years))
        vals = []
        for frame in frames:
            mask = (frame["date"] >= start) & (frame["date"] <= end)
            vals.extend(pd.to_numeric(frame.loc[mask, "value"], errors="coerce").dropna().tolist())
        change: Dict[str, Any] = {"xaxis.range": [start, end], "xaxis.autorange": False}
        rng = _liq6_axis_range(np.asarray(vals, dtype=float), y_policy)
        if rng is not None:
            change["yaxis.range"] = rng; change["yaxis.autorange"] = False
        if y2_series:
            vals2 = []
            for frame in y2_series:
                use = _fx7_frame(frame); mask = (use["date"] >= start) & (use["date"] <= end)
                vals2.extend(pd.to_numeric(use.loc[mask, "value"], errors="coerce").dropna().tolist())
            rng2 = _liq6_axis_range(np.asarray(vals2, dtype=float), y2_policy, reverse=invert_y2)
            if rng2 is not None:
                change["yaxis2.range"] = rng2; change["yaxis2.autorange"] = False
        buttons.append(dict(label=label, method="relayout", args=[change]))
    fig.update_layout(updatemenus=[dict(type="buttons", direction="right", active=2, buttons=buttons, x=.01, xanchor="left", y=1.12, yanchor="top", bgcolor="#091725", bordercolor="rgba(204,183,91,.60)", borderwidth=1, font=dict(color="#dce5ed", size=10))])
    if len(buttons) >= 3:
        fig.update_layout(**buttons[2]["args"][0])


def _fx7_line_card(title: str, subtitle: str, series: Sequence[Tuple[str, pd.DataFrame]], ytitle: str, source: str, second_axis: Optional[Sequence[str]] = None, y_policy: str = "auto", y2_policy: str = "auto", invert_y2: bool = False, height: int = 385) -> None:
    prepared = [(label, _fx7_frame(frame)) for label, frame in series if not _fx7_frame(frame).empty]
    if not prepared:
        _liq5_render_chart_card(title, subtitle, None, [(source, "gold")], empty_message="No usable observations for this chart.")
        return
    second = set(second_axis or [])
    fig = _fx7_base_figure(ytitle, height)
    y2_frames = []
    for idx, (label, frame) in enumerate(prepared):
        secondary = label in second
        if secondary:
            y2_frames.append(frame)
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["value"], name=label, mode="lines", line=dict(color=FX7_COLORS[idx % len(FX7_COLORS)], width=2), yaxis="y2" if secondary else "y", hovertemplate=f"{label}: %{{y:.4f}}<extra></extra>"))
    if second:
        fig.update_layout(yaxis2=dict(overlaying="y", side="right", title="Secondary", showgrid=False, zeroline=False))
    _fx7_window_buttons(fig, [f for l, f in prepared if l not in second], y_policy, y2_frames, y2_policy, invert_y2)
    latest = max(pd.Timestamp(f["date"].max()) for _, f in prepared)
    badges = []
    for label, frame in prepared[:4]:
        badges.append((f"{label} {_liq5_fmt_value(_fx7_latest(frame))} · {_liq5_fmt_date(_fx7_latest_date(frame))}", "live"))
    badges.append((source, "gold"))
    _liq5_render_chart_card(title, subtitle, fig, badges, f"Latest public observation {_liq5_fmt_date(latest)}")


def _fx7_heatmap_card(title: str, subtitle: str, matrix: pd.DataFrame, source: str, unit: str = "", zmid: Optional[float] = 0.0, colorscale: Optional[Any] = None, height: int = 480) -> None:
    if matrix.empty:
        _liq5_render_chart_card(title, subtitle, None, [(source, "gold")], empty_message="Matrix unavailable.")
        return
    colors = colorscale or [[0, "#9e4f48"], [0.5, "#17283a"], [1, "#4f9b6f"]]
    text = matrix.map(lambda x: "—" if pd.isna(x) else f"{x:.2f}{unit}")
    fig = go.Figure(go.Heatmap(z=matrix.to_numpy(dtype=float), x=list(matrix.columns), y=list(matrix.index), colorscale=colors, zmid=zmid, text=text.to_numpy(), texttemplate="%{text}", hovertemplate="Long %{y}<br>Short %{x}<br>%{z:.3f}<extra></extra>", colorbar=dict(title=unit or "Value")))
    fig.update_layout(height=height, margin=dict(l=70, r=42, t=24, b=54), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=11), xaxis=dict(side="top"), yaxis=dict(autorange="reversed"))
    _liq5_render_chart_card(title, subtitle, fig, [(source, "gold")], "Latest available inputs")


