def _fx7_header(view: str) -> None:
    meta = {
        "Overview": ("G10 FX · SPOT · CARRY · VOLATILITY", "FX intelligence overview", "Cross-pair spot, realized volatility, carry, regimes and positioning in one institutional dashboard."),
        "Monitor": ("G10 SPOT · REALIZED VOLATILITY", "FX volatility monitor", "Live G10 spot ladder with 5D/20D/60D/252D realized volatility, percentile context and pair drill-down."),
        "Surface Builder": ("OTC QUOTES · SMILE · TERM STRUCTURE", "FX implied-volatility surface builder", "Build a quote-consistent smile from ATM, risk-reversal and butterfly inputs; no free source is presented as an OTC market quote."),
        "Greeks & Scenarios": ("GARMAN–KOHLHAGEN · VANNA · VOLGA", "FX options Greeks and scenarios", "Smile-aware option repricing under spot and volatility shocks using the surface stored in this session."),
        "Regime": ("CALM · EVENT RISK · SUSTAINED STRESS", "FX volatility regime classifier", "Classify each pair from the 5D/60D realized-vol ratio and the 20D volatility percentile."),
        "RV Signals": ("CHEAP · FAIR · RICH", "FX volatility relative-value screener", "Rank G10 pairs by realized-volatility percentile, carry-to-vol and cross-pair volatility clustering."),
        "Carry Matrix": ("3M RATES · REALIZED VOL · CARRY/VOL", "G10 FX carry trade matrix", "Every G10 currency cross in one grid: rate differential, 90-day realized volatility and carry per unit of risk."),
        "Positioning": ("CFTC TFF · LEVERAGED MONEY · CROWDING", "FX positioning monitor", "Weekly leveraged-money futures positioning with two-year z-scores and positioning-versus-volatility diagnostics."),
        "Data Quality": ("AUDIT · FRESHNESS · LINEAGE", "FX data quality and provider controls", "Spot, rates, CFTC, cache state, native frequency and user-surface lineage."),
    }
    kicker, title, subtitle = meta.get(view, meta["Overview"])
    _html(f'<div class="fx7-kicker">{_escape(kicker)}</div><div class="fx7-title">{_escape(title)}</div><div class="fx7-sub">{_escape(subtitle)}</div>')


def _fx7_kpis(monitor: pd.DataFrame, context: Mapping[str, pd.DataFrame], selected_pair: str) -> None:
    row = monitor.loc[monitor["Pair"] == selected_pair].iloc[0] if not monitor.empty and selected_pair in set(monitor["Pair"]) else None
    dxy = _fx7_latest(context.get("DXY", pd.DataFrame())); vix = _fx7_latest(context.get("VIX", pd.DataFrame()))
    spx = _fx7_latest(context.get("SPX_FUT", pd.DataFrame())); gold = _fx7_latest(context.get("GOLD", pd.DataFrame()))
    cards = []
    if row is not None:
        decimals = FX7_PAIRS[selected_pair]["decimals"]
        spot = "—" if pd.isna(row["Spot"]) else f"{row['Spot']:.{decimals}f}"
        cards += [
            _kpi_card(selected_pair, spot, f"1D {_liq3_fmt_change(row['Chg%'])}"),
            _kpi_card("20D realized vol", _fmt(row["20D RVol"], 2, "%"), f"{_fx7_signal(row['20D Pctile'])} · {row['20D Pctile']:.0f}th" if pd.notna(row["20D Pctile"]) else "Unavailable"),
            _kpi_card("Carry / vol", _fmt(row["Carry/Vol"], 3, ""), f"3M rate differential {_liq3_fmt_change(row['Carry'])}" if pd.notna(row["Carry"]) else "Rate input unavailable"),
        ]
    cards += [
        _kpi_card("DXY", _fmt(dxy, 2, ""), f"1D {_liq3_fmt_change(_fx7_pct_change(context.get('DXY', pd.DataFrame()), 1))}"),
        _kpi_card("S&P futures", _fmt(spx, 1, ""), f"1D {_liq3_fmt_change(_fx7_pct_change(context.get('SPX_FUT', pd.DataFrame()), 1))}"),
        _kpi_card("VIX", _fmt(vix, 2, ""), f"1D {_liq3_fmt_change(_fx7_pct_change(context.get('VIX', pd.DataFrame()), 1))}"),
        _kpi_card("Gold", _fmt(gold, 1, ""), f"1D {_liq3_fmt_change(_fx7_pct_change(context.get('GOLD', pd.DataFrame()), 1))}"),
        _kpi_card("Universe", "10 pairs", "G10 spot and volatility"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards[:8]) + '</div>')


def _fx7_spot_performance_matrix(spot: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    rows = []
    for pair in FX7_PAIRS:
        frame = spot.get(pair, pd.DataFrame())
        rows.append({"Pair": pair, "1D": _fx7_pct_change(frame, 1), "5D": _fx7_pct_change(frame, 5), "1M": _fx7_pct_change(frame, 20), "3M": _fx7_pct_change(frame, 60), "1Y": _fx7_pct_change(frame, 252)})
    return pd.DataFrame(rows).set_index("Pair")


def _fx7_render_overview(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame], context: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], monitor: pd.DataFrame, selected_pair: str) -> None:
    tasks = []
    perf = _fx7_spot_performance_matrix(spot)
    def performance():
        fig = go.Figure(go.Heatmap(z=perf.to_numpy(dtype=float), x=list(perf.columns), y=list(perf.index), zmid=0, colorscale=[[0, "#9e4f48"], [.5, "#17283a"], [1, "#4f9b6f"]], text=np.round(perf.to_numpy(dtype=float), 2), texttemplate="%{text}%", hovertemplate="%{y}<br>%{x}: %{z:.2f}%<extra></extra>"))
        fig.update_layout(height=420, margin=dict(l=70, r=30, t=20, b=52), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=11))
        _liq5_render_chart_card("G10 Spot Performance", "Daily through one-year spot returns; quote direction follows the displayed pair.", fig, [("Twelve Data / Yahoo", "gold")], f"Latest public observation {_liq5_fmt_date(max((_fx7_latest_date(x) for x in spot.values() if _fx7_latest_date(x) is not None), default=None))}")
    tasks.append(performance)
    def vol_percentiles():
        use = monitor.dropna(subset=["20D Pctile"]).sort_values("20D Pctile")
        fig = _fx7_base_figure("20D percentile", 420)
        fig.add_trace(go.Bar(x=use["20D Pctile"], y=use["Pair"], orientation="h", marker_color=["#74b981" if x < 33 else "#d9bf58" if x <= 67 else "#e87557" for x in use["20D Pctile"]], text=use["Signal"], textposition="outside", hovertemplate="%{y}: %{x:.0f}th<extra></extra>"))
        fig.update_xaxes(range=[0, 100]); fig.update_layout(showlegend=False)
        _liq5_render_chart_card("G10 Realized-Volatility Percentiles", "Current 20D realized volatility relative to each pair's trailing one-year distribution.", fig, [("Cheap <30 · Rich >70", "gold")], "Current cross-section")
    tasks.append(vol_percentiles)
    def carry_rank():
        use = monitor.dropna(subset=["Carry/Vol"]).sort_values("Carry/Vol")
        fig = _fx7_base_figure("Carry / vol", 420)
        fig.add_trace(go.Bar(x=use["Carry/Vol"], y=use["Pair"], orientation="h", marker_color=["#8bc48a" if x >= 0 else "#e87557" for x in use["Carry/Vol"]], hovertemplate="%{y}: %{x:.3f}<extra></extra>"))
        _liq5_render_chart_card("Carry per Unit of Realized Volatility", "3M base-minus-quote rate differential divided by current 20D realized volatility.", fig, [("FRED/OECD + spot history", "gold")], "Latest available rate and spot inputs")
    tasks.append(carry_rank)
    def risk_pulse():
        raw = [("DXY", context.get("DXY", pd.DataFrame()), "indexed"), ("S&P futures", context.get("SPX_FUT", pd.DataFrame()), "indexed"), ("VIX", context.get("VIX", pd.DataFrame()), "indexed"), ("Gold", context.get("GOLD", pd.DataFrame()), "indexed")]
        prepared = _liq6_common_index(raw)
        _fx7_line_card("Dollar & Risk Pulse", "DXY, S&P futures, VIX and gold rebased to 100 from the same common date.", [(label, frame) for label, frame, _mode in prepared], "Index", "Yahoo / public market data", y_policy="positive", height=420)
    tasks.append(risk_pulse)
    def positioning_extremes():
        rows = []
        for ccy, frame in cftc.items():
            if frame.empty:
                continue
            latest = frame.iloc[-1]
            rows.append({"Currency": ccy, "Net contracts": latest.get("net"), "Z-score": latest.get("zscore"), "Open interest": latest.get("open_interest"), "Date": pd.Timestamp(latest.get("date")).strftime("%Y-%m-%d")})
        table = pd.DataFrame(rows).sort_values("Z-score") if rows else pd.DataFrame()
        _liq5_table_card("CFTC Leveraged-Money Crowding", "Net currency-futures positioning; z-scores use a rolling two-year history.", table, [("CFTC TFF", "gold")], "Weekly public report", 20)
    tasks.append(positioning_extremes)
    _liq6_two_column(tasks)
    _liq5_table_card("G10 Spot and Volatility Ladder", "Core G10 spot and realized-volatility ladder with percentile context.", _fx7_monitor_view_table(monitor), [("Public / market data", "gold")], "Latest native-frequency observations", 20)


def _fx7_render_monitor(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame], monitor: pd.DataFrame, selected_pair: str) -> None:
    _liq5_table_card("G10 Spot & Realized Volatility", "Select a pair above to update every drill-down chart below.", _fx7_monitor_view_table(monitor), [("20D percentile versus trailing 1Y", "gold")], "Daily spot history", 20)
    stats = _fx7_pair_stats(selected_pair, spot.get(selected_pair, pd.DataFrame()))
    rv20 = stats["rv20_frame"]
    def cone():
        if rv20.empty:
            _liq5_render_chart_card(f"{selected_pair} — 20D Realized Vol vs Cone", "Rolling 20D realized vol with full-history percentile bands.", None, empty_message="Realized-volatility history unavailable."); return
        p10, p25, p75, p90 = np.nanpercentile(rv20["value"], [10, 25, 75, 90])
        fig = _fx7_base_figure("Annualized %", 390)
        fig.add_hrect(y0=p10, y1=p25, fillcolor="rgba(116,185,230,.14)", line_width=0)
        fig.add_hrect(y0=p25, y1=p75, fillcolor="rgba(139,196,138,.10)", line_width=0)
        fig.add_hrect(y0=p75, y1=p90, fillcolor="rgba(232,117,87,.14)", line_width=0)
        fig.add_trace(go.Scatter(x=rv20["date"], y=rv20["value"], name="20D RVol", line=dict(color="#d9bf58", width=2.2)))
        for value, label in ((p10, "p10"), (p25, "p25"), (p75, "p75"), (p90, "p90")):
            fig.add_hline(y=value, line_dash="dot", line_color="rgba(180,190,200,.45)", annotation_text=label)
        _fx7_window_buttons(fig, [rv20], "positive")
        _liq5_render_chart_card(f"{selected_pair} — 20D Realized Vol vs Cone", "Gold line is rolling 20D realized volatility; bands show the pair's own historical distribution.", fig, [(f"Current {stats['rv20']:.2f}%", "live"), (f"{stats['pctile']:.0f}th percentile", "gold")], f"Latest public observation {_liq5_fmt_date(stats['date'])}")
    def spot_vol_beta():
        ret = _fx7_log_returns(spot.get(selected_pair, pd.DataFrame()))
        vol_change = _fx7_frame(rv20); vol_change["value"] = vol_change["value"].diff()
        corr = _fx7_rolling_corr(ret, vol_change, 20)
        _fx7_line_card(f"{selected_pair} — Spot-Vol Beta", "Rolling 20-day correlation between daily spot returns and changes in 20D realized volatility.", [("20D correlation", corr)], "Correlation", "Quant Terminal calculation", y_policy="correlation")
    def spot_chart():
        _fx7_line_card(f"{selected_pair} Spot", "Daily close for directional and volatility-regime context.", [(selected_pair, spot.get(selected_pair, pd.DataFrame()))], selected_pair, "Twelve Data / Yahoo", y_policy="positive")
    def return_distribution():
        ret = _fx7_log_returns(spot.get(selected_pair, pd.DataFrame())).tail(252)
        if ret.empty:
            _liq5_render_chart_card("Daily Return Distribution (1Y)", "Histogram of daily log returns.", None, empty_message="Returns unavailable."); return
        values = ret["value"] * 100.0; mu, sigma = values.mean(), values.std(ddof=1)
        hist, bins = np.histogram(values, bins=35); centers = (bins[:-1] + bins[1:]) / 2
        fig = _fx7_base_figure("Observations", 385)
        fig.add_trace(go.Bar(x=centers, y=hist, marker_color=["#e87557" if abs(x - mu) > 2 * sigma else "#74b9e6" for x in centers], hovertemplate="Return %{x:.3f}%<br>Count %{y}<extra></extra>"))
        fig.add_vline(x=mu + 2 * sigma, line_dash="dot", line_color="#e87557"); fig.add_vline(x=mu - 2 * sigma, line_dash="dot", line_color="#e87557")
        _liq5_render_chart_card("Daily Return Distribution (1Y)", "Tails beyond ±2σ are highlighted; this is a realized-return diagnostic, not a normality assumption.", fig, [(f"μ={mu:.3f}%", "live"), (f"σ={sigma:.3f}%", "gold")], "Trailing 252 observations")
    def term_structure():
        labels = ["5D", "20D", "60D", "1Y"]; vals = [stats["rv5"], stats["rv20"], stats["rv60"], stats["rv252"]]
        fig = _fx7_base_figure("Annualized %", 385)
        fig.add_trace(go.Scatter(x=labels, y=vals, mode="lines+markers", line=dict(color="#74b9e6", width=2.4), marker=dict(size=9), hovertemplate="%{x}: %{y:.2f}%<extra></extra>"))
        fig.update_layout(showlegend=False)
        shape = "Front-loaded" if vals[0] is not None and vals[-1] is not None and vals[0] > vals[-1] else "Upward sloping"
        _liq5_render_chart_card(f"{selected_pair} Realized Vol Term Structure", "Annualized realized volatility across standard lookback horizons.", fig, [(shape, "gold")], f"Latest public observation {_liq5_fmt_date(stats['date'])}")
    _liq6_two_column([cone, spot_vol_beta, spot_chart, return_distribution, term_structure])


def _fx7_default_surface_quotes(pair: str, spot: Mapping[str, pd.DataFrame]) -> Dict[str, Dict[str, float]]:
    stats = _fx7_pair_stats(pair, spot.get(pair, pd.DataFrame()))
    base = max(2.0, stats.get("rv20") or stats.get("rv60") or 8.0)
    ret = _fx7_log_returns(spot.get(pair, pd.DataFrame()))
    skew = float(np.clip(-ret.tail(252)["value"].skew() * 0.35 if not ret.empty else 0.0, -1.8, 1.8))
    kurt = max(0.0, float(ret.tail(756)["value"].kurt() if len(ret) >= 60 else 0.0))
    rv20_frame = _fx7_rvol(spot.get(pair, pd.DataFrame()), 20)
    if rv20_frame.empty:
        vov = 0.0
    else:
        rv_change = rv20_frame["value"].pct_change().replace([np.inf, -np.inf], np.nan)
        vov = float(rv_change.rolling(20, min_periods=10).std(ddof=1).tail(60).mean() * math.sqrt(252.0))
        if not np.isfinite(vov):
            vov = 0.0
    tenors = (("1W", 7/365), ("1M", 1/12), ("3M", .25), ("6M", .5), ("1Y", 1.0), ("2Y", 2.0))
    out = {}
    for name, t in tenors:
        atm = base * (0.94 + 0.08 * math.sqrt(max(t, .02)))
        bf25 = float(np.clip(0.05 + 0.025 * kurt + 0.08 * math.sqrt(max(vov, 0)) + 0.06 * math.sqrt(t), 0.05, 0.45))
        out[name] = {"T": t, "ATM": atm, "RR25": skew * (0.75 + 0.15 * math.sqrt(t)), "BF25": bf25, "RR10": skew * 1.35, "BF10": min(.75, bf25 * 1.8)}
    return out


def _fx7_surface_from_quotes(pair: str, spot_value: float, rd: float, rf: float, quotes: Mapping[str, Mapping[str, float]]) -> Dict[str, Any]:
    delta_grid = np.array([.10, .25, .50, .75, .90])
    rows, smiles, diagnostics = [], {}, []
    for tenor, q in quotes.items():
        t = float(q.get("T", 0)); atm = float(q.get("ATM", np.nan)); rr25 = float(q.get("RR25", 0)); bf25 = max(0.0, float(q.get("BF25", 0))); rr10 = float(q.get("RR10", rr25 * 1.35)); bf10 = max(0.0, float(q.get("BF10", bf25 * 1.8)))
        if not np.isfinite(atm) or atm <= 0 or t <= 0:
            continue
        v25c, v25p = atm + bf25 + rr25 / 2.0, atm + bf25 - rr25 / 2.0
        v10c, v10p = atm + bf10 + rr10 / 2.0, atm + bf10 - rr10 / 2.0
        vols = np.array([v10p, v25p, atm, v25c, v10c], dtype=float)
        vols = np.maximum(vols, .01)
        smiles[tenor] = {"T": t, "delta": delta_grid.tolist(), "vol": vols.tolist(), "ATM": atm, "RR25": rr25, "BF25": bf25, "RR10": rr10, "BF10": bf10}
        forward = spot_value * math.exp((rd - rf) / 100.0 * t)
        diagnostics.append({"Tenor": tenor, "ATM": atm, "25Δ Put": v25p, "25Δ Call": v25c, "25Δ RR": rr25, "25Δ BF": bf25, "10Δ Put": v10p, "10Δ Call": v10c, "10Δ RR": rr10, "10Δ BF": bf10, "Forward": forward})
        for d, v in zip(delta_grid, vols):
            rows.append({"Tenor": tenor, "T": t, "Delta": d, "Vol": v})
    return {"pair": pair, "spot": spot_value, "rd": rd, "rf": rf, "smiles": smiles, "grid": rows, "diagnostics": diagnostics, "built_at": datetime.now(timezone.utc).isoformat()}


def _fx7_render_surface_builder(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame], selected_pair: str) -> None:
    spec = FX7_PAIRS[selected_pair]
    spot_value = _fx7_latest(spot.get(selected_pair, pd.DataFrame())) or 1.0
    rd = _fx7_rate_latest(rates, spec["quote"]) or 0.0
    rf = _fx7_rate_latest(rates, spec["base"]) or 0.0
    # Garman-Kohlhagen domestic rate is quote currency; foreign rate is base currency.
    defaults = _fx7_default_surface_quotes(selected_pair, spot)
    _html('<div class="fx7-note"><b>OTC quote contract.</b> Auto-fill is an indicative realized-data estimate. It is never labelled as a live OTC implied-volatility quote. Override it with Bloomberg, Refinitiv or broker ATM/RR/BF quotes for production pricing.</div>')
    top = st.columns(3, gap="medium")
    with top[0]: spot_value = float(st.number_input("Spot", min_value=0.0001, value=float(spot_value), step=0.0001, key=f"market_fx7_surface_spot_{selected_pair}"))
    with top[1]: rd = float(st.number_input("Domestic rate % p.a. (quote currency)", value=float(rd), step=.05, key=f"market_fx7_surface_rd_{selected_pair}"))
    with top[2]: rf = float(st.number_input("Foreign rate % p.a. (base currency)", value=float(rf), step=.05, key=f"market_fx7_surface_rf_{selected_pair}"))
    quotes: Dict[str, Dict[str, float]] = {}
    _html('<div class="fx7-kicker">Tenor quotes · values in vol points</div>')
    for tenor, default in defaults.items():
        cols = st.columns([.55, 1, 1, 1, 1, 1], gap="small")
        with cols[0]: st.markdown(f"**{tenor}**")
        keys = (("ATM", "ATM Vol %"), ("RR25", "25Δ RR %"), ("BF25", "25Δ BF %"), ("RR10", "10Δ RR %"), ("BF10", "10Δ BF %"))
        row = {"T": default["T"]}
        for col, (field, label) in zip(cols[1:], keys):
            with col:
                row[field] = float(st.number_input(label, value=float(default[field]), step=.01, format="%.3f", key=f"market_fx7_{selected_pair}_{tenor}_{field}", label_visibility="collapsed"))
        quotes[tenor] = row
    actions = st.columns(2, gap="medium")
    with actions[0]: auto_fill = st.button("Auto-fill indicative quotes", key=f"market_fx7_autofill_surface_{selected_pair}", width="stretch")
    with actions[1]: build = st.button("Build / refresh surface", key=f"market_fx7_build_surface_{selected_pair}", width="stretch")
    if auto_fill:
        for tenor, default in defaults.items():
            for field in ("ATM", "RR25", "BF25", "RR10", "BF10"):
                st.session_state[f"market_fx7_{selected_pair}_{tenor}_{field}"] = float(default[field])
        st.rerun()
    state_key = f"market_fx7_surface_state_{selected_pair}"
    if build or state_key not in st.session_state:
        st.session_state[state_key] = _fx7_surface_from_quotes(selected_pair, spot_value, rd, rf, quotes)
    surface = st.session_state.get(state_key, {})
    grid = pd.DataFrame(surface.get("grid", []))
    diagnostics = pd.DataFrame(surface.get("diagnostics", []))
    if grid.empty:
        st.warning("No valid tenor quotes were supplied.")
        return
    tasks = []
    def surface3d():
        pivot = grid.pivot(index="T", columns="Delta", values="Vol").sort_index()
        fig = go.Figure(go.Surface(x=np.array(pivot.columns), y=np.array(pivot.index), z=pivot.to_numpy(), colorscale="Viridis", colorbar=dict(title="Vol %"), hovertemplate="Delta %{x:.2f}<br>T %{y:.2f}y<br>Vol %{z:.2f}%<extra></extra>"))
        fig.update_layout(height=430, margin=dict(l=28, r=28, t=28, b=28), paper_bgcolor="#050c15", scene=dict(xaxis_title="Call delta", yaxis_title="Tenor (years)", zaxis_title="Implied vol %", bgcolor="#08131f"), font=dict(color="#dce5ed"))
        _liq5_render_chart_card(f"{selected_pair} Implied-Volatility Surface", "Quote-consistent smile grid anchored by ATM, risk-reversal and butterfly inputs.", fig, [("User quote / model-labelled", "gold")], "Current session surface")
    tasks.append(surface3d)
    def smiles():
        fig = _fx7_base_figure("Implied vol %", 430)
        for idx, (tenor, smile) in enumerate(surface.get("smiles", {}).items()):
            fig.add_trace(go.Scatter(x=smile["delta"], y=smile["vol"], name=tenor, mode="lines+markers", line=dict(color=FX7_COLORS[idx % len(FX7_COLORS)])))
        fig.update_xaxes(title="Call delta")
        _liq5_render_chart_card(f"{selected_pair} Smile by Tenor", "10Δ put through 10Δ call, reconstructed from the supplied quote convention.", fig, [("ATM / RR / BF", "gold")], "Current session surface")
    tasks.append(smiles)
    def terms():
        use = diagnostics.copy()
        fig = _fx7_base_figure("Vol points", 430)
        for idx, col in enumerate(("ATM", "25Δ RR", "25Δ BF", "10Δ RR", "10Δ BF")):
            fig.add_trace(go.Scatter(x=use["Tenor"], y=use[col], name=col, mode="lines+markers", line=dict(color=FX7_COLORS[idx % len(FX7_COLORS)])))
        _liq5_render_chart_card("ATM / Risk-Reversal / Butterfly Term Structure", "Input term structure and reconstructed wing diagnostics.", fig, [("User supplied or model-labelled", "gold")], "Current session surface")
    tasks.append(terms)
    _liq6_two_column(tasks)
    _liq5_table_card("Surface Diagnostics", "25Δ and 10Δ call/put volatilities plus covered-interest-parity forwards.", diagnostics.round(4), [("Garman–Kohlhagen forward convention", "gold")], "Current session surface", 20)


def _fx7_norm_cdf(x: float) -> float:
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def _fx7_norm_pdf(x: float) -> float:
    return math.exp(-0.5 * x * x) / math.sqrt(2.0 * math.pi)


def _fx7_gk(spot: float, strike: float, t: float, rd: float, rf: float, vol: float, call: bool = True) -> Dict[str, float]:
    rd /= 100.0; rf /= 100.0; vol /= 100.0
    t = max(t, 1e-8); vol = max(vol, 1e-8); spot = max(spot, 1e-12); strike = max(strike, 1e-12)
    root = math.sqrt(t); d1 = (math.log(spot / strike) + (rd - rf + .5 * vol * vol) * t) / (vol * root); d2 = d1 - vol * root
    sign = 1.0 if call else -1.0
    price = sign * (spot * math.exp(-rf * t) * _fx7_norm_cdf(sign * d1) - strike * math.exp(-rd * t) * _fx7_norm_cdf(sign * d2))
    delta = sign * math.exp(-rf * t) * _fx7_norm_cdf(sign * d1)
    gamma = math.exp(-rf * t) * _fx7_norm_pdf(d1) / (spot * vol * root)
    vega = spot * math.exp(-rf * t) * _fx7_norm_pdf(d1) * root / 100.0
    theta = (-(spot * math.exp(-rf * t) * _fx7_norm_pdf(d1) * vol) / (2 * root) + sign * rf * spot * math.exp(-rf * t) * _fx7_norm_cdf(sign * d1) - sign * rd * strike * math.exp(-rd * t) * _fx7_norm_cdf(sign * d2)) / 365.0
    vanna = -math.exp(-rf * t) * _fx7_norm_pdf(d1) * d2 / vol / 100.0
    volga = vega * d1 * d2 / vol / 100.0
    return {"price": price, "delta": delta, "gamma": gamma, "vega": vega, "theta": theta, "vanna": vanna, "volga": volga, "d1": d1, "d2": d2}


def _fx7_surface_atm(surface: Mapping[str, Any], tenor: str) -> Tuple[float, float]:
    smile = (surface.get("smiles", {}) or {}).get(tenor, {})
    return float(smile.get("ATM", np.nan)), float(smile.get("T", np.nan))


def _fx7_surface_local_vol(surface: Mapping[str, Any], tenor: str, spot: float, strike: float) -> float:
    smile = (surface.get("smiles", {}) or {}).get(tenor, {})
    deltas = np.asarray(smile.get("delta", []), dtype=float)
    vols = np.asarray(smile.get("vol", []), dtype=float)
    atm = _safe_float(smile.get("ATM"))
    t = max(float(smile.get("T", 0.0) or 0.0), 1e-8)
    if deltas.size < 2 or vols.size != deltas.size:
        return max(0.01, atm or 0.01)
    rd = float(surface.get("rd", 0.0) or 0.0) / 100.0
    rf = float(surface.get("rf", 0.0) or 0.0) / 100.0
    forward = max(float(spot), 1e-12) * math.exp((rd - rf) * t)
    scale = max((atm or float(np.nanmedian(vols))) / 100.0 * math.sqrt(t), 1e-4)
    standardized_moneyness = math.log(max(forward, 1e-12) / max(float(strike), 1e-12)) / scale
    smile_coordinate = 0.5 + 0.4 * math.tanh(standardized_moneyness / 2.0)
    return float(max(0.01, np.interp(smile_coordinate, deltas, vols)))


def _fx7_render_greeks(selected_pair: str) -> None:
    state_key = f"market_fx7_surface_state_{selected_pair}"
    surface = st.session_state.get(state_key)
    if not isinstance(surface, Mapping) or not surface.get("smiles"):
        st.warning("Build a surface in Surface Builder first. The simulator does not use canned implied-volatility data.")
        return
    tenors = list(surface["smiles"].keys())
    controls = st.columns(6, gap="small")
    with controls[0]: tenor = st.selectbox("Tenor", tenors, index=min(2, len(tenors)-1), key=f"market_fx7_greek_tenor_{selected_pair}")
    atm, t = _fx7_surface_atm(surface, tenor)
    with controls[1]: option = st.selectbox("Option", ["Call", "Put"], key=f"market_fx7_greek_type_{selected_pair}")
    with controls[2]: strike = float(st.number_input("Strike", min_value=.0001, value=float(surface["spot"]), step=.0001, key=f"market_fx7_greek_strike_{selected_pair}"))
    with controls[3]: notional = float(st.number_input("Notional", min_value=1_000.0, value=1_000_000.0, step=100_000.0, key=f"market_fx7_greek_notional_{selected_pair}"))
    with controls[4]: spot_shock = float(st.number_input("Spot shock %", value=0.0, step=.5, key=f"market_fx7_greek_spotshock_{selected_pair}"))
    with controls[5]: vol_shock = float(st.number_input("Vol shock pts", value=0.0, step=.25, key=f"market_fx7_greek_volshock_{selected_pair}"))
    base_spot = float(surface["spot"])
    local_vol = _fx7_surface_local_vol(surface, tenor, base_spot, strike)
    shocked_spot = base_spot * (1 + spot_shock/100)
    shocked_local_vol = max(.01, _fx7_surface_local_vol(surface, tenor, shocked_spot, strike) + vol_shock)
    base = _fx7_gk(base_spot, strike, t, float(surface["rd"]), float(surface["rf"]), local_vol, option == "Call")
    shocked = _fx7_gk(shocked_spot, strike, t, float(surface["rd"]), float(surface["rf"]), shocked_local_vol, option == "Call")
    pnl = (shocked["price"] - base["price"]) * notional
    cards = [
        _kpi_card("Premium", _fmt(base["price"] * notional, 0, ""), f"{local_vol:.2f}% local smile vol"),
        _kpi_card("Scenario P&L", _fmt(pnl, 0, ""), f"Spot {spot_shock:+.1f}% · Vol {vol_shock:+.2f}"),
        _kpi_card("Delta", _fmt(base["delta"] * notional, 0, ""), "Base-currency delta"),
        _kpi_card("Gamma", _fmt(base["gamma"] * notional, 2, ""), "Per spot unit²"),
        _kpi_card("Vega", _fmt(base["vega"] * notional, 0, ""), "Per vol point"),
        _kpi_card("Theta", _fmt(base["theta"] * notional, 0, ""), "Per calendar day"),
        _kpi_card("Vanna", _fmt(base["vanna"] * notional, 0, ""), "Delta-vol cross sensitivity"),
        _kpi_card("Volga", _fmt(base["volga"] * notional, 0, ""), "Vega convexity"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')
    spot_grid = np.array([-5, -3, -2, -1, 0, 1, 2, 3, 5], dtype=float)
    vol_grid = np.array([-2, -1, -.5, 0, .5, 1, 2], dtype=float)
    z = np.zeros((len(vol_grid), len(spot_grid)))
    for i, vs in enumerate(vol_grid):
        for j, ss in enumerate(spot_grid):
            scenario_spot = base_spot * (1 + ss/100)
            scenario_vol = max(.01, _fx7_surface_local_vol(surface, tenor, scenario_spot, strike) + vs)
            value = _fx7_gk(scenario_spot, strike, t, float(surface["rd"]), float(surface["rf"]), scenario_vol, option == "Call")["price"]
            z[i, j] = (value - base["price"]) * notional
    fig = go.Figure(go.Heatmap(z=z, x=[f"{x:+.0f}%" for x in spot_grid], y=[f"{x:+.1f}" for x in vol_grid], zmid=0, colorscale=[[0, "#9e4f48"], [.5, "#17283a"], [1, "#4f9b6f"]], text=np.round(z, 0), texttemplate="%{text:,.0f}", hovertemplate="Spot %{x}<br>Vol %{y} pts<br>P&L %{z:,.0f}<extra></extra>"))
    fig.update_layout(height=470, margin=dict(l=70, r=36, t=22, b=58), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed"), xaxis_title="Spot shock", yaxis_title="Vol shock (pts)")
    _liq5_render_chart_card(f"{selected_pair} {tenor} {option} Scenario Matrix", "Smile-consistent scenario repricing: spot shocks move the option across the stored smile and vol shocks shift the local surface level.", fig, [("Garman–Kohlhagen", "gold"), ("User/session surface", "live")], "Current scenario")
    greeks_df = pd.DataFrame([{"Metric": k.title(), "Per unit": v, "Position": v * notional} for k, v in base.items() if k not in {"d1", "d2"}])
    _liq5_table_card("Greeks Detail", "Analytical first- and second-order sensitivities at the current surface point.", greeks_df, [("No canned implied-vol data", "gold")], f"{selected_pair} · {tenor} · {option}", 20)


def _fx7_render_regime(spot: Mapping[str, pd.DataFrame], monitor: pd.DataFrame, selected_pair: str) -> None:
    rows = []
    for _, row in monitor.iterrows():
        stats = _fx7_pair_stats(row["Pair"], spot.get(row["Pair"], pd.DataFrame()))
        regime, read = _fx7_regime(stats)
        ratio = stats["rv5"] / stats["rv60"] if stats["rv5"] is not None and stats["rv60"] not in {None, 0} else None
        rows.append({"Pair": row["Pair"], "Regime": regime, "5D RVol": stats["rv5"], "20D RVol": stats["rv20"], "60D RVol": stats["rv60"], "5D/60D": ratio, "20D Pctile": stats["pctile"], "Read": read})
    table = pd.DataFrame(rows)
    _liq5_table_card("G10 Volatility Regime Grid", "Event Risk: 5D/60D > 1.8. Sustained Stress: ratio > 1.3 and 20D percentile > 70. Otherwise Calm.", table.round(3), [("Realized-volatility only", "gold")], "Current classification", 20)
    stats = _fx7_pair_stats(selected_pair, spot.get(selected_pair, pd.DataFrame()))
    rv5, rv20, rv60 = stats["rv5_frame"], stats["rv20_frame"], stats["rv60_frame"]
    a = _fx7_frame(rv5).rename(columns={"value": "rv5"}); b = _fx7_frame(rv60).rename(columns={"value": "rv60"})
    merged = pd.merge_asof(a, b, on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna() if not a.empty and not b.empty else pd.DataFrame()
    ratio_frame = pd.DataFrame({"date": merged["date"], "value": merged["rv5"] / merged["rv60"].replace(0, np.nan)}).dropna() if not merged.empty else pd.DataFrame()
    def ratio_chart():
        if ratio_frame.empty:
            _liq5_render_chart_card(f"{selected_pair} — Short/Long Vol Ratio", "5D / 60D realized volatility.", None, empty_message="Ratio unavailable."); return
        fig = _fx7_base_figure("5D / 60D", 390)
        fig.add_trace(go.Scatter(x=ratio_frame["date"], y=ratio_frame["value"], name="5D / 60D", line=dict(color="#74b9e6", width=2)))
        fig.add_hline(y=1.3, line_dash="dash", line_color="#d9bf58", annotation_text="Stress threshold")
        fig.add_hline(y=1.8, line_dash="dash", line_color="#e87557", annotation_text="Event Risk")
        _fx7_window_buttons(fig, [ratio_frame], "positive")
        regime, _read = _fx7_regime(stats)
        _liq5_render_chart_card(f"{selected_pair} — Short/Long Vol Ratio", "Above 1.8 signals Event Risk; 1.3–1.8 plus rich 20D vol signals Sustained Stress.", fig, [(regime, "gold")], f"Latest public observation {_liq5_fmt_date(stats['date'])}")
    def levels():
        _fx7_line_card("5D vs 60D Realized Vol", "Absolute volatility levels reveal whether the ratio move comes from a short-end spike or long-window compression.", [("5D RVol", rv5), ("60D RVol", rv60), ("20D RVol", rv20)], "Annualized %", "Public market data", y_policy="positive")
    _liq6_two_column([ratio_chart, levels])


def _fx7_render_rv(spot: Mapping[str, pd.DataFrame], monitor: pd.DataFrame) -> None:
    _liq5_table_card("FX Vol Relative-Value Screener", "All G10 pairs ranked by current 20D realized-vol percentile, with carry-to-vol when the 3M rate inputs are available.", _fx7_rv_view_table(monitor.sort_values("20D Pctile", ascending=False)), [("Cheap <30 · Fair 30–70 · Rich >70", "gold")], "Current cross-section", 20)
    tasks = []
    def volbar():
        use = monitor.dropna(subset=["20D RVol"]).sort_values("20D RVol")
        fig = _fx7_base_figure("20D RVol %", 400)
        fig.add_trace(go.Bar(x=use["20D RVol"], y=use["Pair"], orientation="h", marker_color=["#74b981" if s == "Cheap" else "#d9bf58" if s == "Fair" else "#e87557" for s in use["Signal"]]))
        _liq5_render_chart_card("20D Realized Vol (color = signal)", "Green = cheap, gold = fair, red = rich relative to each pair's own one-year distribution.", fig, [("Daily spot history", "gold")], "Current cross-section")
    tasks.append(volbar)
    def carrybar():
        use = monitor.dropna(subset=["Carry/Vol"]).sort_values("Carry/Vol")
        fig = _fx7_base_figure("Carry / vol", 400)
        fig.add_trace(go.Bar(x=use["Carry/Vol"], y=use["Pair"], orientation="h", marker_color=["#8bc48a" if x >= 0 else "#e87557" for x in use["Carry/Vol"]]))
        _liq5_render_chart_card("Carry / Vol Ratio", "3M rate differential divided by 20D realized volatility.", fig, [("FRED/OECD + spot history", "gold")], "Current cross-section")
    tasks.append(carrybar)
    def scatter():
        use = monitor.dropna(subset=["Carry/Vol", "20D Pctile"])
        fig = _fx7_base_figure("20D percentile", 400)
        fig.add_trace(go.Scatter(x=use["Carry/Vol"], y=use["20D Pctile"], mode="markers+text", text=use["Pair"], textposition="top center", marker=dict(size=11, color=use["20D Pctile"], colorscale="RdYlGn_r", cmin=0, cmax=100), hovertemplate="%{text}<br>Carry/Vol %{x:.3f}<br>Pctile %{y:.0f}<extra></extra>"))
        fig.add_hline(y=30, line_dash="dot", line_color="#74b981"); fig.add_hline(y=70, line_dash="dot", line_color="#e87557"); fig.add_vline(x=0, line_dash="dot", line_color="#8b98a7")
        fig.update_xaxes(title="Carry / Vol")
        _liq5_render_chart_card("Carry/Vol vs 20D Percentile", "Top-right: positive carry and rich realized vol; bottom-right: positive carry with historically cheap vol.", fig, [("Cross-sectional diagnostic", "gold")], "Current inputs")
    tasks.append(scatter)
    def corr_matrix():
        cols = {}
        for pair, frame in spot.items():
            rv = _fx7_rvol(frame, 20)
            if not rv.empty:
                weekly = rv.set_index("date")["value"].resample("W-FRI").last().diff().rename(pair)
                cols[pair] = weekly
        if not cols:
            _liq5_render_chart_card("G10 Vol Correlation Matrix", "Correlation of weekly 20D realized-volatility changes.", None, empty_message="Volatility histories unavailable."); return
        merged = pd.concat(cols.values(), axis=1).dropna(how="all").tail(120).corr()
        fig = go.Figure(go.Heatmap(z=merged.to_numpy(), x=list(merged.columns), y=list(merged.index), zmin=-1, zmax=1, zmid=0, colorscale=[[0, "#9e4f48"], [.5, "#17283a"], [1, "#4c8eb8"]], text=np.round(merged.to_numpy(), 2), texttemplate="%{text}", hovertemplate="%{y} / %{x}: %{z:.2f}<extra></extra>"))
        fig.update_layout(height=520, margin=dict(l=70, r=32, t=22, b=70), paper_bgcolor="#050c15", font=dict(color="#dce5ed"))
        _liq5_render_chart_card("G10 Vol Correlation Matrix", "Pearson correlation of weekly changes in 20D realized volatility over the last 120 observations.", fig, [("Vol-clustering diagnostic", "gold")], "Trailing 120 observations")
    tasks.append(corr_matrix)
    _liq6_two_column(tasks)


def _fx7_render_carry(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame]) -> None:
    carry, vol, ctv = _fx7_carry_matrices(spot, rates)
    _fx7_heatmap_card("G10 FX Carry Matrix", "3M interest-rate differential: row currency minus column currency. Positive means long row / short column earns carry.", carry, "FRED/OECD 3M interbank rates", "%")
    _fx7_heatmap_card("G10 Cross Realized Volatility", "90-day annualized realized volatility for every derived G10 cross.", vol, "Daily G10 spot history", "%", zmid=None, colorscale="Viridis")
    ctv_display = pd.concat([ctv, pd.DataFrame([ctv.mean(axis=0, skipna=True)], index=["Average"])])
    _fx7_heatmap_card("Carry per 1% of Vol", "Rate differential divided by 90-day realized FX volatility; values are capped at ±5. The final row is the average by funding currency.", ctv_display, "FRED/OECD + spot history", "", zmid=0)
    records = []
    for row in carry.index:
        for col in carry.columns:
            if row == col or pd.isna(carry.loc[row, col]):
                continue
            records.append({"Trade": f"{row}{col}", "Long": row, "Short": col, "Carry": carry.loc[row, col], "90D Vol": vol.loc[row, col], "Carry/Vol": ctv.loc[row, col]})
    top = pd.DataFrame(records).sort_values("Carry", ascending=False).head(10) if records else pd.DataFrame()
    tasks = []
    def top10():
        if top.empty:
            _liq5_render_chart_card("Top 10 Carry Trades", "Best cross-currency carry trades.", None, empty_message="Rate inputs unavailable."); return
        fig = _fx7_base_figure("3M carry %", 420)
        fig.add_trace(go.Bar(x=top["Trade"], y=top["Carry"], marker_color="#d9bf58", text=top["Carry"].map(lambda x: f"{x:.2f}%"), textposition="outside"))
        _liq5_render_chart_card("Top 10 Carry Trades", "Best long/short cross-currency carry ranked by the latest 3M rate differential.", fig, [("Long first currency / short second", "gold")], "Latest available monthly rates")
    tasks.append(top10)
    def rate_ladder():
        rows = [{"Currency": c, "3M rate": _fx7_rate_latest(rates, c), "Latest date": _liq5_fmt_date(_fx7_latest_date(rates.get(c, pd.DataFrame())))} for c in FX7_CARRY_CURRENCIES]
        table = pd.DataFrame(rows).sort_values("3M rate", ascending=False)
        _liq5_table_card("G10 3M Rate Ladder", "Native monthly interbank-rate inputs used in the carry matrix.", table, [("FRED/OECD", "gold")], "Latest native-frequency observations", 20)
    tasks.append(rate_ladder)
    _liq6_two_column(tasks)


def _fx7_position_label(z: Optional[float]) -> str:
    if z is None or not np.isfinite(z):
        return "Unavailable"
    if z <= -2: return "Very Short"
    if z <= -1: return "Short"
    if z < 0: return "Mildly Short"
    if z < 1: return "Mildly Long"
    if z < 2: return "Long"
    return "Very Long"


def _fx7_render_positioning(cftc: Mapping[str, pd.DataFrame], monitor: pd.DataFrame) -> None:
    rows = []
    tasks = []
    for ccy in FX7_CFTC_CODES:
        frame = cftc.get(ccy, pd.DataFrame())
        if frame.empty:
            continue
        latest = frame.iloc[-1]; z = _safe_float(latest.get("zscore")); net = _safe_float(latest.get("net")); oi = _safe_float(latest.get("open_interest"))
        rows.append({"Currency": ccy, "Net contracts": net, "Z-score": z, "Signal": _fx7_position_label(z), "Open interest": oi, "Latest date": pd.Timestamp(latest["date"]).strftime("%Y-%m-%d")})
        def make_task(ccy=ccy, frame=frame, z=z, net=net):
            def task():
                netf = pd.DataFrame({"date": frame["date"], "value": frame["net"]})
                zf = pd.DataFrame({"date": frame["date"], "value": frame["zscore"]})
                _fx7_line_card(ccy, "Net leveraged-money positions with rolling two-year z-score.", [("Net contracts", netf), ("Z-score", zf)], "Contracts", "CFTC TFF", second_axis=["Z-score"], y_policy="signed", y2_policy="signed", height=380)
            return task
        tasks.append(make_task())
    summary = pd.DataFrame(rows).sort_values("Z-score") if rows else pd.DataFrame()
    _liq5_table_card("CFTC Positioning — Traders in Financial Futures", "Net Leveraged Money positions in G10 FX futures; z-score versus rolling two-year history.", summary, [("CFTC weekly public data", "gold")], "Latest weekly report", 20)
    _liq6_two_column(tasks)
    # Positioning × vol regime.
    if not summary.empty:
        pair_for_ccy = {"EUR": "EURUSD", "GBP": "GBPUSD", "JPY": "USDJPY", "CHF": "USDCHF", "CAD": "USDCAD", "AUD": "AUDUSD", "NZD": None}
        points = []
        for _, row in summary.iterrows():
            pair = pair_for_ccy.get(row["Currency"])
            pct = None
            if pair:
                match = monitor.loc[monitor["Pair"] == pair]
                if not match.empty: pct = _safe_float(match.iloc[0]["20D Pctile"])
            if pct is not None and pd.notna(row["Z-score"]):
                points.append({"Currency": row["Currency"], "Z": row["Z-score"], "Pct": pct})
        p = pd.DataFrame(points)
        if not p.empty:
            fig = _fx7_base_figure("20D RVol percentile", 460)
            fig.add_trace(go.Scatter(x=p["Z"], y=p["Pct"], mode="markers+text", text=p["Currency"], textposition="top center", marker=dict(size=14, color=p["Pct"], colorscale="RdYlGn_r", cmin=0, cmax=100)))
            fig.add_vline(x=-1, line_dash="dot", line_color="#74b9e6"); fig.add_vline(x=1, line_dash="dot", line_color="#e87557"); fig.add_hline(y=30, line_dash="dot", line_color="#74b981"); fig.add_hline(y=70, line_dash="dot", line_color="#e87557")
            fig.update_xaxes(title="Net leveraged-money z-score")
            _liq5_render_chart_card("Positioning × Vol Regime", "Crowding versus current realized-volatility richness. Extremes are risk inputs, not timing signals.", fig, [("CFTC + spot realized vol", "gold")], "Latest common observations")


def _fx7_render_quality(quality: pd.DataFrame, surface_exists: bool, diagnostics: Mapping[str, Any]) -> None:
    q = quality.copy() if isinstance(quality, pd.DataFrame) else pd.DataFrame()
    loaded = int((pd.to_numeric(q.get("Observations", pd.Series(dtype=float)), errors="coerce").fillna(0) > 0).sum()) if not q.empty else 0
    total = len(q)
    fresh = int(q.get("Freshness", pd.Series(dtype=str)).isin(["Fresh"]).sum()) if not q.empty else 0
    stale = int(q.get("Freshness", pd.Series(dtype=str)).isin(["Lagged", "Stale"]).sum()) if not q.empty else 0
    latest = "—"
    if not q.empty and "Latest Date" in q:
        dates = pd.to_datetime(q["Latest Date"], errors="coerce"); latest = dates.max().strftime("%Y-%m-%d") if dates.notna().any() else "—"
    cards = [_kpi_card("Series loaded", f"{loaded}/{total}", "Active lazy route"), _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"), _kpi_card("Lagged / stale", str(stale), "Never silently upgraded"), _kpi_card("Latest observation", latest, f"Load time {diagnostics.get('elapsed', 0):.1f}s")]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')
    _liq5_table_card("FX Series Registry and Freshness", "Spot, 3M rates, CFTC positioning, cache state and provider messages.", q, [("Public lineage", "gold")], "Current lazy route", 180)
    contract = pd.DataFrame([
        {"Layer": "G10 spot", "Primary source": "Twelve Data when configured", "Fallback": "Yahoo/yfinance batch + disk cache", "Rule": "Daily close; no fabricated intraday history"},
        {"Layer": "Realized volatility", "Primary source": "Calculated from daily log returns", "Fallback": "None", "Rule": "Annualized at √252"},
        {"Layer": "Carry", "Primary source": "FRED/OECD 3M interbank rates", "Fallback": "Provider-required", "Rule": "Native monthly frequency retained"},
        {"Layer": "Positioning", "Primary source": "CFTC TFF Futures Only / Leveraged Money", "Fallback": "Fresh or stale disk cache", "Rule": "Weekly report; 2Y rolling z-score"},
        {"Layer": "Implied vol", "Primary source": "User OTC ATM/RR/BF quotes", "Fallback": "Explicit realized-data model estimate", "Rule": "Model estimate never presented as market quote"},
        {"Layer": "Greeks", "Primary source": "Garman–Kohlhagen + session surface", "Fallback": "None", "Rule": "No surface = no scenario output"},
        {"Layer": "Intraday event reaction tape", "Primary source": "Calendar-aligned intraday provider", "Fallback": "Provider-required", "Rule": "No fabricated 1H/4H event returns"},
    ])
    _liq5_table_card("FX Provider Contract", "Timeouts are bounded and each layer retains its source, unit, frequency and fallback state.", contract, [("No silent synthetic production history", "live")], "Frozen architecture", 20)
    surface_df = pd.DataFrame([{"Pair": pair, "Surface available": f"market_fx7_surface_state_{pair}" in st.session_state} for pair in FX7_PAIRS])
    _liq5_table_card("Session Surface Registry", "User/model-labelled surfaces are session-local and never represented as historical market observations.", surface_df, [("Current pair surface available" if surface_exists else "No current pair surface", "gold")], "Session state", 20)
    if not q.empty:
        st.download_button("Download FX data-quality registry", q.to_csv(index=False).encode("utf-8"), "marketdesk_fx_v7_quality.csv", "text/csv", key="market_fx7_download_quality")


def _fx7_required(view: str, selected_pair: str) -> Tuple[Tuple[str, ...], bool, bool, bool]:
    # pairs, rates, context, CFTC. Pair-only tools do not download the full G10 pack.
    selected = (selected_pair,) if selected_pair in FX7_PAIRS else ("EURUSD",)
    if view == "Surface Builder": return selected, True, False, False
    if view == "Greeks & Scenarios": return selected, False, False, False
    if view == "Positioning": return tuple(FX7_PAIRS), False, False, True
    if view == "Carry Matrix": return tuple(FX7_PAIRS), True, False, False
    if view == "Data Quality": return tuple(FX7_PAIRS), True, True, True
    if view == "Overview": return tuple(FX7_PAIRS), True, True, True
    if view in {"Monitor", "Regime", "RV Signals"}: return tuple(FX7_PAIRS), True, False, False
    return tuple(FX7_PAIRS), True, True, False


def _render_fx_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, price_data, analysis
    _liq3_css(); _liq5_css(); _liq6_css(); _fx7_css()
    view = _liq3_segmented("FX view", FX7_VIEW_OPTIONS, "market_fx7_view", "Overview")
    _fx7_header(view)
    selected_pair = str(st.session_state.get("market_fx7_pair", "EURUSD"))
    if selected_pair not in FX7_PAIRS: selected_pair = "EURUSD"
    cols = st.columns([1.05, 2.1, .72], gap="medium")
    with cols[0]: selected_pair = st.selectbox("Pair", list(FX7_PAIRS), index=list(FX7_PAIRS).index(selected_pair), key="market_fx7_pair")
    with cols[1]: st.caption("Daily spot data are public/market fallbacks; OTC implied-volatility fields require user quotes or remain explicitly model-labelled.")
    with cols[2]: refresh = st.button("Refresh", key="market_fx7_refresh", width="stretch")
    if refresh:
        st.session_state["market_fx7_refresh_nonce"] = int(st.session_state.get("market_fx7_refresh_nonce", 0)) + 1
        st.rerun()
    nonce = int(st.session_state.get("market_fx7_refresh_nonce", 0))
    pairs, need_rates, need_context, need_cftc = _fx7_required(view, selected_pair)
    started = time.perf_counter()
    with st.spinner("Loading FX — bounded public providers..."):
        spot, q_spot, d_spot = _fx7_load_spot_pack(pairs, nonce)
        rates, q_rates, d_rates = _fx7_load_rates(nonce) if need_rates else ({}, pd.DataFrame(), {"elapsed": 0.0, "provider": "not-requested"})
        context, q_context, d_context = _fx7_load_context_markets(nonce) if need_context else ({}, pd.DataFrame(), {"elapsed": 0.0, "provider": "not-requested"})
        cftc, q_cftc, d_cftc = _fx7_load_cftc(nonce) if need_cftc else ({}, pd.DataFrame(), {"provider": "not-requested"})
        monitor = _fx7_build_monitor_table(spot, rates)
    elapsed = time.perf_counter() - started
    quality = pd.concat([x for x in (q_spot, q_rates, q_context, q_cftc) if isinstance(x, pd.DataFrame) and not x.empty], ignore_index=True) if any(isinstance(x, pd.DataFrame) and not x.empty for x in (q_spot, q_rates, q_context, q_cftc)) else pd.DataFrame()
    _fx7_kpis(monitor, context, selected_pair)
    _html(f'<div class="fx7-note"><b>{FX7_VERSION}</b> · Spot {d_spot.get("elapsed",0):.1f}s · Rates {d_rates.get("elapsed",0):.1f}s · Total {elapsed:.1f}s · active route {view}.</div>')
    try:
        if view == "Overview": _fx7_render_overview(spot, rates, context, cftc, monitor, selected_pair)
        elif view == "Monitor": _fx7_render_monitor(spot, rates, monitor, selected_pair)
        elif view == "Surface Builder": _fx7_render_surface_builder(spot, rates, selected_pair)
        elif view == "Greeks & Scenarios": _fx7_render_greeks(selected_pair)
        elif view == "Regime": _fx7_render_regime(spot, monitor, selected_pair)
        elif view == "RV Signals": _fx7_render_rv(spot, monitor)
        elif view == "Carry Matrix": _fx7_render_carry(spot, rates)
        elif view == "Positioning": _fx7_render_positioning(cftc, monitor)
        else: _fx7_render_quality(quality, f"market_fx7_surface_state_{selected_pair}" in st.session_state, {"elapsed": elapsed})
    except Exception as exc:
        st.error(f"FX route failed: {type(exc).__name__}: {exc}")
        with st.expander("FX traceback", expanded=False): st.code(_fx7_traceback.format_exc())


# Final public renderer override. Non-FX pages delegate exactly to the V6
