FX8_CANONICAL_CARRY_ORDER = ("NOK", "AUD", "USD", "EUR", "GBP", "CAD", "SEK", "JPY", "CHF")
FX8_TENORS = (("1W", 7/365), ("1M", 1/12), ("3M", .25), ("6M", .5), ("1Y", 1.0), ("2Y", 2.0))

MARKET_INTELLIGENCE_VERSION = FX8_VERSION + " + LIQUIDITY V6 + FIXED INCOME"
