FX9_VERSION = "V9 · FX UI AND STABILITY FINAL"
FX8_VERSION = FX9_VERSION


def _fx9_ordinal(value: Any) -> str:
    x = _safe_float(value)
    if x is None:
        return "—"
    n = int(round(x))
    suffix = "th" if 10 <= (n % 100) <= 20 else {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"


def _fx7_fmt_monitor_table(df: pd.DataFrame) -> pd.DataFrame:
    """Presentation-only formatting; calculations remain unchanged."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df
    out = df.copy()
    decimals = {p: FX7_PAIRS[p]["decimals"] for p in FX7_PAIRS}
    out["Spot"] = ["—" if pd.isna(v) else f"{v:.{decimals.get(p, 4)}f}" for p, v in zip(out["Pair"], out["Spot"])]
    for col in ("Chg%", "5D RVol", "20D RVol", "60D RVol", "252D RVol", "Carry"):
        if col in out:
            out[col] = out[col].map(
                lambda x, _col=col: "—" if pd.isna(x) else f"{x:+.2f}%" if _col in {"Chg%", "Carry"} else f"{x:.2f}%"
            )
    if "20D Pctile" in out:
        out["20D Pctile"] = out["20D Pctile"].map(_fx9_ordinal)
    if "Carry/Vol" in out:
        out["Carry/Vol"] = out["Carry/Vol"].map(lambda x: "—" if pd.isna(x) else f"{x:+.3f}")
    return out


def _fx7_window_buttons(
    fig: go.Figure,
    series: Sequence[pd.DataFrame],
    y_policy: str = "auto",
    y2_series: Sequence[pd.DataFrame] = (),
    y2_policy: str = "auto",
    invert_y2: bool = False,
) -> None:
    """
    Plotly rangeselector buttons accept step/count/stepmode only.
    Axis relayout payloads therefore belong in an updatemenu, not in
    layout.xaxis.rangeselector. This also lets each window carry its own
    y/y2 range so the visible data are never flattened by old extremes.
    """
    primary = [_fx7_frame(frame) for frame in series]
    secondary = [_fx7_frame(frame) for frame in y2_series]
    all_frames = [frame for frame in primary + secondary if not frame.empty]
    if not all_frames:
        return

    end = max(pd.Timestamp(frame["date"].max()) for frame in all_frames)
    start_all = min(pd.Timestamp(frame["date"].min()) for frame in all_frames)
    windows: Tuple[Tuple[str, Optional[int]], ...] = (
        ("1Y", 365), ("3Y", 1095), ("5Y", 1825), ("10Y", 3650), ("Max", None)
    )

    buttons: List[Dict[str, Any]] = []
    layouts: List[Dict[str, Any]] = []
    for label, days in windows:
        start = start_all if days is None else max(start_all, end - pd.Timedelta(days=days))
        change: Dict[str, Any] = {
            "xaxis.range": [start, end],
            "xaxis.autorange": False,
        }

        vals: List[float] = []
        for frame in primary:
            if frame.empty:
                continue
            mask = (frame["date"] >= start) & (frame["date"] <= end)
            vals.extend(pd.to_numeric(frame.loc[mask, "value"], errors="coerce").dropna().astype(float).tolist())
        rng = _liq6_axis_range(np.asarray(vals, dtype=float), y_policy)
        if rng is not None:
            change["yaxis.range"] = rng
            change["yaxis.autorange"] = False

        vals2: List[float] = []
        for frame in secondary:
            if frame.empty:
                continue
            mask = (frame["date"] >= start) & (frame["date"] <= end)
            vals2.extend(pd.to_numeric(frame.loc[mask, "value"], errors="coerce").dropna().astype(float).tolist())
        if vals2:
            rng2 = _liq6_axis_range(np.asarray(vals2, dtype=float), y2_policy, reverse=invert_y2)
            if rng2 is not None:
                change["yaxis2.range"] = rng2
                change["yaxis2.autorange"] = False

        layouts.append(change)
        buttons.append(dict(label=label, method="relayout", args=[change]))

    fig.update_layout(
        updatemenus=[dict(
            type="buttons",
            direction="right",
            active=0,
            buttons=buttons,
            x=.01,
            xanchor="left",
            y=1.13,
            yanchor="top",
            bgcolor="#091725",
            bordercolor="rgba(204,183,91,.60)",
            borderwidth=1,
            font=dict(color="#dce5ed", size=10),
            pad=dict(r=4, t=2, b=2, l=4),
        )],
        xaxis=dict(rangeslider=dict(visible=False)),
    )
    if layouts:
        fig.update_layout(**layouts[0])


def _fx7_kpis(monitor: pd.DataFrame, context: Mapping[str, pd.DataFrame], selected_pair: str) -> None:
    """Never render empty DXY/VIX/Gold cards on lazy non-overview routes."""
    row = monitor.loc[monitor["Pair"] == selected_pair].iloc[0] if isinstance(monitor, pd.DataFrame) and not monitor.empty and selected_pair in set(monitor["Pair"]) else None
    cards: List[str] = []
    if row is not None:
        decimals = FX7_PAIRS[selected_pair]["decimals"]
        spot = "—" if pd.isna(row.get("Spot")) else f"{row['Spot']:.{decimals}f}"
        pct = _safe_float(row.get("20D Pctile"))
        ratio = None
        rv5, rv60 = _safe_float(row.get("5D RVol")), _safe_float(row.get("60D RVol"))
        if rv5 is not None and rv60 not in {None, 0}:
            ratio = rv5 / rv60
        cards.extend([
            _kpi_card(selected_pair, spot, f"1D {_liq3_fmt_change(row.get('Chg%'))}"),
            _kpi_card("20D realized vol", _fmt(row.get("20D RVol"), 2, "%"), f"{_fx7_signal(pct)} · {_fx9_ordinal(pct)}" if pct is not None else "Unavailable"),
            _kpi_card("Carry / vol", _fmt(row.get("Carry/Vol"), 3, ""), f"3M rate differential {_liq3_fmt_change(row.get('Carry'))}" if pd.notna(row.get("Carry")) else "Rate input unavailable"),
        ])

        has_context = any(isinstance(context.get(key), pd.DataFrame) and not context.get(key).empty for key in ("DXY", "SPX_FUT", "VIX", "GOLD"))
        if has_context:
            for key, label, dec, unit in (("DXY", "DXY", 2, ""), ("SPX_FUT", "S&P futures", 1, ""), ("VIX", "VIX", 2, ""), ("GOLD", "Gold", 1, "")):
                frame = context.get(key, pd.DataFrame())
                cards.append(_kpi_card(label, _fmt(_fx7_latest(frame), dec, unit), f"1D {_liq3_fmt_change(_fx7_pct_change(frame, 1))}"))
        else:
            cards.extend([
                _kpi_card("5D realized vol", _fmt(row.get("5D RVol"), 2, "%"), "Short window"),
                _kpi_card("60D realized vol", _fmt(row.get("60D RVol"), 2, "%"), "Regime anchor"),
                _kpi_card("252D realized vol", _fmt(row.get("252D RVol"), 2, "%"), "One-year window"),
                _kpi_card("5D / 60D", _fmt(ratio, 2, ""), ("Event Risk" if ratio is not None and ratio > 1.8 else "Sustained Stress" if ratio is not None and ratio > 1.3 and pct is not None and pct > 70 else "Calm" if ratio is not None else "Unavailable")),
            ])
    cards.append(_kpi_card("Universe", "10 pairs", "G10 spot and volatility"))
    _html('<div class="mk-kpis">' + ''.join(cards[:8]) + '</div>')


