def _fx7_render_overview(spot: Mapping[str, pd.DataFrame], rates: Mapping[str, pd.DataFrame], context: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], monitor: pd.DataFrame, selected_pair: str) -> None:
    """Overview parity: exact 30/70 RV thresholds and restored card renderer."""
    tasks: List[Any] = []
    perf = _fx7_spot_performance_matrix(spot)

    def performance() -> None:
        fig = go.Figure(go.Heatmap(
            z=perf.to_numpy(dtype=float), x=list(perf.columns), y=list(perf.index), zmid=0,
            colorscale=[[0, "#9e4f48"], [.5, "#17283a"], [1, "#4f9b6f"]],
            text=np.round(perf.to_numpy(dtype=float), 2), texttemplate="%{text}%",
            hovertemplate="%{y}<br>%{x}: %{z:.2f}%<extra></extra>",
        ))
        fig.update_layout(height=420, margin=dict(l=70, r=30, t=20, b=52), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=11))
        latest = max((_fx7_latest_date(x) for x in spot.values() if _fx7_latest_date(x) is not None), default=None)
        _liq5_render_chart_card("G10 Spot Performance", "Daily through one-year spot returns; quote direction follows the displayed pair.", fig, [("Twelve Data / Yahoo", "gold")], f"Latest public observation {_liq5_fmt_date(latest)}")
    tasks.append(performance)

    def vol_percentiles() -> None:
        use = monitor.dropna(subset=["20D Pctile"]).sort_values("20D Pctile")
        fig = _fx7_base_figure("20D percentile", 420)
        colors = ["#74b981" if x < 30 else "#d9bf58" if x <= 70 else "#e87557" for x in use["20D Pctile"]]
        labels = [_fx7_signal(x) for x in use["20D Pctile"]]
        fig.add_trace(go.Bar(
            x=use["20D Pctile"], y=use["Pair"], orientation="h", marker_color=colors,
            text=labels, textposition="outside", customdata=[_fx9_ordinal(x) for x in use["20D Pctile"]],
            hovertemplate="%{y}: %{customdata}<extra></extra>",
        ))
        fig.update_xaxes(range=[0, 100]); fig.update_layout(showlegend=False)
        _liq5_render_chart_card("G10 Realized-Volatility Percentiles", "Current 20D realized volatility relative to each pair's trailing one-year distribution.", fig, [("Cheap <30 · Rich >70", "gold")], "Current cross-section")
    tasks.append(vol_percentiles)

    def carry_rank() -> None:
        use = monitor.dropna(subset=["Carry/Vol"]).sort_values("Carry/Vol")
        fig = _fx7_base_figure("Carry / vol", 420)
        fig.add_trace(go.Bar(x=use["Carry/Vol"], y=use["Pair"], orientation="h", marker_color=["#8bc48a" if x >= 0 else "#e87557" for x in use["Carry/Vol"]], hovertemplate="%{y}: %{x:.3f}<extra></extra>"))
        _liq5_render_chart_card("Carry per Unit of Realized Volatility", "3M base-minus-quote rate differential divided by current 20D realized volatility.", fig, [("FRED/OECD + spot history", "gold")], "Latest available rate and spot inputs")
    tasks.append(carry_rank)

    def risk_pulse() -> None:
        raw = [("DXY", context.get("DXY", pd.DataFrame()), "indexed"), ("S&P futures", context.get("SPX_FUT", pd.DataFrame()), "indexed"), ("VIX", context.get("VIX", pd.DataFrame()), "indexed"), ("Gold", context.get("GOLD", pd.DataFrame()), "indexed")]
        prepared = _liq6_common_index(raw)
        _fx7_line_card("Dollar & Risk Pulse", "DXY, S&P futures, VIX and gold rebased to 100 from the same common date.", [(label, frame) for label, frame, _mode in prepared], "Index", "Yahoo / public market data", y_policy="positive", height=420)
    tasks.append(risk_pulse)

    def positioning_extremes() -> None:
        rows = []
        for ccy, frame in cftc.items():
            if not isinstance(frame, pd.DataFrame) or frame.empty:
                continue
            latest = frame.iloc[-1]
            rows.append({"Currency": ccy, "Net contracts": latest.get("net"), "Z-score": latest.get("zscore"), "Open interest": latest.get("open_interest"), "Date": pd.Timestamp(latest.get("date")).strftime("%Y-%m-%d")})
        table = pd.DataFrame(rows).sort_values("Z-score") if rows else pd.DataFrame()
        _liq5_table_card("CFTC Leveraged-Money Crowding", "Net currency-futures positioning; z-scores use a rolling two-year history.", table, [("CFTC TFF", "gold")], "Weekly public report", 20)
    tasks.append(positioning_extremes)

    _liq6_two_column(tasks)
    _liq5_table_card("G10 Spot and Volatility Ladder", "Core G10 spot and realized-volatility ladder with percentile context.", _fx7_monitor_view_table(monitor), [("Public / market data", "gold")], "Latest native-frequency observations", 20)

def _render_fx_page(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    # V8 accidentally called only _fx7_css(), dropping the frozen card/table CSS.
    _liq3_css(); _liq5_css(); _liq6_css(); _fx7_css(); _fx9_css()
    view = st.segmented_control("FX research view", FX7_VIEW_OPTIONS, key="market_fx7_view", label_visibility="collapsed") or "Overview"
    _fx7_header(view)
    selected_pair = str(st.session_state.get("market_fx7_pair", "EURUSD")); selected_pair = selected_pair if selected_pair in FX7_PAIRS else "EURUSD"
    cols = st.columns([1.05, 2.1, .72], gap="medium")
    with cols[0]:
        selected_pair = st.selectbox("Pair", list(FX7_PAIRS), index=list(FX7_PAIRS).index(selected_pair), key="market_fx7_pair")
    with cols[1]:
        st.caption("Daily spot data are public/market fallbacks; OTC implied-volatility fields require user quotes or remain explicitly model-labelled.")
    with cols[2]:
        refresh = st.button("Refresh", key="market_fx9_refresh", width="stretch")
    if refresh:
        st.session_state["market_fx8_refresh_nonce"] = int(st.session_state.get("market_fx8_refresh_nonce", 0)) + 1
        st.rerun()

    nonce = int(st.session_state.get("market_fx8_refresh_nonce", 0))
    pairs, need_rates, need_context, need_cftc, need_nzd = _fx8_required(view, selected_pair)
    started = time.perf_counter()
    with st.spinner("Loading FX — bounded public providers..."):
        spot, q_spot, d_spot = _fx8_load_spot_pack(pairs, nonce)
        rates, q_rates, _d_rates = _fx7_load_rates(nonce) if need_rates else ({}, pd.DataFrame(), {})
        context, q_context, _d_context = _fx7_load_context_markets(nonce) if need_context else ({}, pd.DataFrame(), {})
        cftc, q_cftc, _d_cftc = _fx8_load_cftc(nonce) if need_cftc else ({}, pd.DataFrame(), {})
        nzd_spot, q_nzd = _fx8_load_nzd(nonce) if need_nzd else (pd.DataFrame(), pd.DataFrame())
        monitor = _fx7_build_monitor_table(spot, rates)
    elapsed = time.perf_counter() - started
    parts = [x for x in (q_spot, q_rates, q_context, q_cftc, q_nzd) if isinstance(x, pd.DataFrame) and not x.empty]
    quality = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()

    _fx7_kpis(monitor, context, selected_pair)
    _html(f'<div class="fx7-note"><b>{_escape(FX9_VERSION)}</b> · Wall load {elapsed:.1f}s · Spot provider {_escape(d_spot.get("provider", "—"))} · active route {_escape(view)}.</div>')
    try:
        if view == "Overview": _fx7_render_overview(spot, rates, context, cftc, monitor, selected_pair)
        elif view == "Monitor": _fx7_render_monitor(spot, rates, monitor, selected_pair)
        elif view == "Surface Builder": _fx8_render_surface_builder(spot, rates, selected_pair)
        elif view == "Greeks & Scenarios": _fx8_render_greeks(selected_pair)
        elif view == "Regime": _fx7_render_regime(spot, monitor, selected_pair)
        elif view == "RV Signals": _fx8_render_rv(spot, monitor)
        elif view == "Carry Matrix": _fx8_render_carry(spot, rates)
        elif view == "Positioning": _fx8_render_positioning(cftc, monitor, nzd_spot)
        else: _fx8_render_quality(quality, selected_pair, {"elapsed": elapsed})
    except Exception as exc:
        st.error(f"FX route failed: {type(exc).__name__}: {exc}")
        with st.expander("FX traceback", expanded=False):
            st.code(_fx7_traceback.format_exc())


