def _fi10_header(view: str) -> None:
    meta = {
        "Overview": ("G7 FIXED INCOME · STRATEGY · ALLOCATION", "Fixed Income intelligence overview", "Sovereign curves, policy, inflation, credit, money markets and duration signals in one workstation."),
        "Curve Surface": ("RATES & CURVES · 3D SURFACE", "Yield curve history surface", "Observed US Treasury curves sampled through time; foreign multi-tenor surfaces remain provider-required."),
        "Sovereigns": ("G7 SOVEREIGN YIELDS · CURVES · DURATION", "Sovereign rates and duration", "US curve structure, G7 benchmark yields and Treasury duration instruments."),
        "Central Banks": ("POLICY RATES · DIVERGENCE · TRANSMISSION", "Central-bank policy rates", "Fed, ECB, BoJ and BoE policy divergence against market-implied rates."),
        "Inflation": ("BREAKEVENS · REAL YIELDS · INFLATION", "Inflation and real-rate observatory", "Breakevens, TIPS real yields and nominal/real decomposition."),
        "Credit": ("OAS · RATINGS · FINANCIAL CONDITIONS", "Credit-spread observatory", "Investment-grade, high-yield, BBB and distressed-credit risk premia."),
        "MBS": ("MORTGAGES · AGENCY MBS · DURATION", "Mortgage and MBS observatory", "Primary mortgage rates, Treasury spreads, Fed holdings and agency-MBS instruments."),
        "EM Bonds": ("HARD CURRENCY · LOCAL CURRENCY · DOLLAR", "Emerging-market bond observatory", "Hard-currency and local-currency EM debt risk, return and dollar sensitivity."),
        "Money Markets": ("SOFR · EFFR · IORB · FRONT END", "Money-market and front-end rates", "Overnight policy transmission, Treasury bills and reverse-repo plumbing."),
        "Macro": ("LABOR · INFLATION · FINANCIAL STRESS", "Macro rates transmission", "Labor, inflation and financial-stress relationships with the Treasury curve."),
        "Cross-Asset": ("DURATION · EQUITIES · GOLD · VOLATILITY", "Cross-asset bond allocation", "Duration performance, volatility, dollar and credit-equity transmission."),
        "Chart Book": ("45 CHARTS · 9 RESEARCH FAMILIES", "Fixed Income chart book", "RoboMacro-aligned chart ordering with page-level lazy loading."),
        "Data Quality": ("AUDIT · FRESHNESS · LINEAGE", "Fixed Income data quality and provider controls", "Source, cache state, native frequency and provider-required contracts."),
    }
    kicker, title, subtitle = meta.get(view, meta["Overview"])
    _html(f'<div class="fx7-kicker">{_escape(kicker)}</div><div class="fi10-section-title">{_escape(title)}</div><div class="fi10-section-sub">{_escape(subtitle)}</div>')


def _render_fixed_income_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css()
    view = st.segmented_control("Fixed Income research view", FI10_VIEW_OPTIONS, key="market_fi10_view", label_visibility="collapsed") or "Overview"
    _fi10_header(view)
    controls = st.columns([1.0, 1.0, 1.0, .8], gap="medium")
    with controls[0]:
        level_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_fi10_level_mode")
    with controls[1]:
        smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_fi10_smoothing")
    chart_category = "All"
    with controls[2]:
        if view == "Chart Book":
            chart_category = st.selectbox("Research family", ["All"] + list(FI10_CATEGORY_ORDER), key="market_fi10_chart_category")
        elif view == "Curve Surface":
            st.selectbox("Surface sampling", ["Weekly", "Monthly"], key="market_fi10_surface_sampling")
        else:
            st.caption("Only the active route is loaded.")
    with controls[3]:
        refresh = st.button("Refresh", key="market_fi10_refresh", width="stretch")
    if refresh:
        st.session_state["market_fi10_refresh_nonce"] = int(st.session_state.get("market_fi10_refresh_nonce", 0)) + 1
        st.rerun()
    nonce = int(st.session_state.get("market_fi10_refresh_nonce", 0))
    fred_ids, symbols = _fi10_required(view, chart_category)
    started = time.perf_counter()
    with st.spinner("Loading Fixed Income — bounded public providers..."):
        fred, q_fred, d_fred = _fi10_load_fred(fred_ids, "1990-01-01", nonce)
        market, q_market, d_market = _fi10_load_market(symbols, "max", nonce)
    elapsed = time.perf_counter() - started
    quality = pd.concat([x for x in (q_fred, q_market) if isinstance(x, pd.DataFrame) and not x.empty], ignore_index=True) if any(isinstance(x, pd.DataFrame) and not x.empty for x in (q_fred, q_market)) else pd.DataFrame()
    _fi10_kpis(fred, market)
    _html(f'<div class="fi10-note"><b>{_escape(FI10_VERSION)}</b> · Wall load {elapsed:.1f}s · FRED {d_fred.get("elapsed",0):.1f}s · Market {d_market.get("elapsed",0):.1f}s · active route {_escape(view)}.</div>')
    try:
        if view == "Overview":
            _fi10_overview(fred, market, level_mode, smoothing)
        elif view == "Curve Surface":
            sampling = str(st.session_state.get("market_fi10_surface_sampling", "Weekly"))
            c = st.columns([1, 1, 2], gap="medium")
            with c[0]: country = st.selectbox("Country", ["US", "UK", "Germany", "Japan", "Canada", "Australia"], key="market_fi10_surface_country")
            with c[1]: window = st.selectbox("Window", ["1Y", "3Y", "5Y", "10Y"], index=1, key="market_fi10_surface_window")
            if country == "US":
                _fi10_surface_card(fred, sampling, window)
                _fi10_curve_card(fred)
            else:
                sid = dict((c, s) for c, s in (("UK", "IRLTLT01GBM156N"), ("Germany", "IRLTLT01DEM156N"), ("Japan", "IRLTLT01JPM156N"), ("Canada", "IRLTLT01CAM156N"), ("Australia", "IRLTLT01AUM156N"))).get(country)
                _html('<div class="mk-warning"><b>Full multi-tenor surface provider required.</b> Public OECD/FRED coverage for this route supplies the benchmark 10Y history only; no foreign curve is synthesized.</div>')
                _fi10_line_card(f"{country} 10-Year Sovereign Yield", "Native-frequency public benchmark series.", [(country, fred.get(sid, pd.DataFrame()))], "%", "FRED / OECD", level_mode, smoothing, difference_like=True)
        elif view in FI10_CATEGORY_ORDER:
            _fi10_category_view(view, fred, market, level_mode, smoothing)
        elif view == "Chart Book":
            _fi10_chart_book(fred, market, chart_category, level_mode, smoothing)
        else:
            _fi10_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market})
    except Exception as exc:
        st.error(f"Fixed Income route failed: {type(exc).__name__}: {exc}")
        with st.expander("Fixed Income traceback", expanded=False):
            import traceback as _fi10_traceback
            st.code(_fi10_traceback.format_exc())


