def _fi10_quality(quality: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    if quality is None:
        quality = pd.DataFrame()
    loaded = int((~quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).isin(["Lagged", "Stale"]).sum()) if not quality.empty else 0
    dates = pd.to_datetime(quality.get("Latest Date", pd.Series(dtype=str)), errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    latest = dates.max()
    _html('<div class="mk-kpis">' + ''.join([
        _kpi_card("Series loaded", f"{loaded}/{len(quality)}", "Active lazy route"),
        _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"),
        _kpi_card("Lagged / stale", str(lagged), "Visible and excluded where required"),
        _kpi_card("Latest observation", _liq5_fmt_date(latest), f"Wall load {diagnostics.get('elapsed',0):.1f}s"),
    ]) + '</div>')
    _liq5_table_card("Fixed Income Series Registry and Freshness", "Source, unit, native frequency, cache state and provider messages.", quality, [("Public lineage", "gold")], "Current lazy route", 200)
    contract = pd.DataFrame([
        {"Layer": "US curve / spreads", "Primary source": "FRED Treasury constant maturities", "Fallback": "Fresh or stale disk cache", "Rule": "Observed pillars only; no cross-tenor interpolation"},
        {"Layer": "UK sovereign curve", "Primary source": "Bank of England fitted nominal gilt archive", "Fallback": "Stale disk cache", "Rule": "Official fitted spot pillars"},
        {"Layer": "Germany sovereign curve", "Primary source": "Deutsche Bundesbank current Federal securities", "Fallback": "Stale disk cache", "Rule": "Observed benchmark maturity buckets"},
        {"Layer": "Japan sovereign curve", "Primary source": "Japan Ministry of Finance JGB yields", "Fallback": "Stale disk cache", "Rule": "Official constant-maturity pillars"},
        {"Layer": "Canada sovereign curve", "Primary source": "Bank of Canada benchmark bond yields", "Fallback": "Stale disk cache", "Rule": "Official daily benchmark series"},
        {"Layer": "Australia sovereign curve", "Primary source": "RBA Table F2 daily government-bond yields", "Fallback": "Stale disk cache", "Rule": "Official government-bond pillars; weekly sampled in the surface"},
        {"Layer": "Policy / money markets", "Primary source": "FRED + official BoE Bank Rate", "Fallback": "Proxy only when explicitly labelled", "Rule": "No SONIA presented as Bank Rate when official series exists"},
        {"Layer": "Credit / mortgages", "Primary source": "FRED / ICE BofA / Freddie Mac", "Fallback": "Disk cache", "Rule": "No fabricated spread history"},
        {"Layer": "ETFs / cross-asset", "Primary source": "Yahoo/yfinance batch", "Fallback": "Disk cache", "Rule": "Adjusted-price proxy; window start rebased to 100"},
    ])
    _liq5_table_card("Fixed Income Provider Contract", "Frozen source, freshness and modelling rules.", contract, [("No silent synthetic production history", "live")], FI11_VERSION, 40)
    st.download_button("Download Fixed Income data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_fixed_income_quality_v11.csv", mime="text/csv", key="market_fi11_download_quality")


# Final Fixed Income page. The public market router is not replaced: V10's
# final renderer resolves this function dynamically and continues to delegate
# every non-Fixed-Income route to the frozen V9 implementation.
def _render_fixed_income_page(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css()
    view = st.segmented_control("Fixed Income research view", FI10_VIEW_OPTIONS, key="market_fi10_view", label_visibility="collapsed") or "Overview"
    _fi10_header(view)
    controls = st.columns([1.0, 1.0, 1.0, .8], gap="medium")
    with controls[0]:
        level_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_fi10_level_mode")
    with controls[1]:
        smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_fi10_smoothing")
    chart_category = "All"
    with controls[2]:
        if view == "Chart Book":
            chart_category = st.selectbox("Research family", ["All"] + list(FI10_CATEGORY_ORDER), key="market_fi10_chart_category")
        elif view == "Curve Surface":
            st.selectbox("Surface sampling", ["Weekly", "Monthly"], key="market_fi10_surface_sampling")
        else:
            st.caption("Only the active route is loaded.")
    with controls[3]:
        refresh = st.button("Refresh", key="market_fi10_refresh", width="stretch")
    if refresh:
        st.session_state["market_fi10_refresh_nonce"] = int(st.session_state.get("market_fi10_refresh_nonce", 0)) + 1
        st.rerun()
    nonce = int(st.session_state.get("market_fi10_refresh_nonce", 0))
    fred_ids, symbols = _fi10_required(view, chart_category)
    started = time.perf_counter()
    with st.spinner("Loading Fixed Income — bounded public providers..."):
        fred, q_fred, d_fred = _fi10_load_fred(fred_ids, "1990-01-01", nonce)
        market, q_market, d_market = _fi10_load_market(symbols, "max", nonce)
    elapsed = time.perf_counter() - started
    quality = pd.concat([x for x in (q_fred, q_market) if isinstance(x, pd.DataFrame) and not x.empty], ignore_index=True) if any(isinstance(x, pd.DataFrame) and not x.empty for x in (q_fred, q_market)) else pd.DataFrame()
    _fi10_kpis(fred, market)
    _html(f'<div class="fi10-note"><b>{_escape(FI11_VERSION)}</b> · Wall load {elapsed:.1f}s · FRED/BoE {d_fred.get("elapsed",0):.1f}s · Market {d_market.get("elapsed",0):.1f}s · active route {_escape(view)}.</div>')
    try:
        if view == "Overview":
            _fi10_overview(fred, market, level_mode, smoothing)
        elif view == "Curve Surface":
            sampling = str(st.session_state.get("market_fi10_surface_sampling", "Weekly"))
            c = st.columns([2.35, 1.25], gap="medium")
            with c[0]:
                country = st.segmented_control(
                    "Country", list(FI11_SURFACE_COUNTRIES),
                    key="market_fi10_surface_country", selection_mode="single",
                ) or "US"
            with c[1]:
                window = st.segmented_control(
                    "Window", list(FI11_SURFACE_WINDOWS),
                    key="market_fi10_surface_window", selection_mode="single",
                ) or "3Y"
            st.caption("Hover the ribbon surface to inspect dates. The preview slider pins the detail curve. Foreign providers load only when selected and remain in the bounded disk cache.")
            with st.spinner(f"Loading {country} sovereign curve surface..."):
                panel, surface_meta = _fi11_load_surface_panel(country, fred, nonce)
            _fi11_surface_workspace(country, panel, surface_meta, sampling, window)
        elif view in FI10_CATEGORY_ORDER:
            _fi10_category_view(view, fred, market, level_mode, smoothing)
        elif view == "Chart Book":
            _fi10_chart_book(fred, market, chart_category, level_mode, smoothing)
        else:
            _fi10_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market})
    except Exception as exc:
        st.error(f"Fixed Income route failed: {type(exc).__name__}: {exc}")
        with st.expander("Fixed Income traceback", expanded=False):
            import traceback as _fi11_traceback
            st.code(_fi11_traceback.format_exc())


