def _cr12_norm(frame: Any) -> pd.DataFrame:
    use = _liq3_frame(frame)
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    use = use[["date", "value"]].copy()
    use["date"] = pd.to_datetime(use["date"], errors="coerce").dt.tz_localize(None).astype("datetime64[ns]")
    use["value"] = pd.to_numeric(use["value"], errors="coerce")
    return use.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _cr12_latest(frame: Any) -> Optional[float]:
    use = _cr12_norm(frame)
    return _safe_float(use["value"].iloc[-1]) if not use.empty else None


def _cr12_latest_date(frame: Any) -> Optional[pd.Timestamp]:
    use = _cr12_norm(frame)
    return pd.Timestamp(use["date"].iloc[-1]) if not use.empty else None


def _cr12_asof_change(frame: Any, days: int = 30) -> Optional[float]:
    use = _cr12_norm(frame)
    if use.empty:
        return None
    end = pd.Timestamp(use["date"].iloc[-1])
    target = end - pd.Timedelta(days=int(days))
    older = use.loc[use["date"] <= target]
    if older.empty:
        return None
    return _safe_float(use["value"].iloc[-1] - older["value"].iloc[-1])


def _cr12_rolling_percentile(frame: Any, window: int = 756) -> pd.DataFrame:
    use = _cr12_norm(frame)
    if use.empty:
        return use
    values = use["value"]
    pct = values.rolling(window, min_periods=max(60, min(252, window // 3))).apply(lambda x: float(pd.Series(x).rank(pct=True).iloc[-1] * 100.0), raw=False)
    return pd.DataFrame({"date": use["date"], "value": pct}).dropna().reset_index(drop=True)


def _cr12_rolling_zscore(frame: Any, window: int = 252) -> pd.DataFrame:
    use = _cr12_norm(frame)
    if use.empty:
        return use
    s = use["value"]
    mean = s.rolling(window, min_periods=max(60, window // 3)).mean()
    std = s.rolling(window, min_periods=max(60, window // 3)).std(ddof=0).replace(0, np.nan)
    return pd.DataFrame({"date": use["date"], "value": (s - mean) / std}).dropna().reset_index(drop=True)


def _cr12_change(frame: Any, periods: int = 20) -> pd.DataFrame:
    use = _cr12_norm(frame)
    if use.empty:
        return use
    use["value"] = use["value"].diff(int(periods))
    return use.dropna().reset_index(drop=True)


def _cr12_spread(a: Any, b: Any, tolerance_days: int = 15) -> pd.DataFrame:
    left, right = _cr12_norm(a), _cr12_norm(b)
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    left = left.rename(columns={"value": "a"})
    right = right.rename(columns={"value": "b"})
    merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=tolerance_days)).dropna()
    return pd.DataFrame({"date": merged["date"], "value": merged["a"] - merged["b"]}).reset_index(drop=True)


def _cr12_market_ratio(a: Any, b: Any) -> pd.DataFrame:
    left, right = _cr12_norm(a), _cr12_norm(b)
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(left.rename(columns={"value": "a"}), right.rename(columns={"value": "b"}), on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna()
    merged = merged.loc[merged["b"].ne(0)]
    return pd.DataFrame({"date": merged["date"], "value": merged["a"] / merged["b"]}).reset_index(drop=True)


def _cr12_drawdown(frame: Any) -> pd.DataFrame:
    use = _cr12_norm(frame)
    if use.empty:
        return use
    peak = use["value"].cummax().replace(0, np.nan)
    use["value"] = (use["value"] / peak - 1.0) * 100.0
    return use.dropna().reset_index(drop=True)


def _cr12_current_percentile(frame: Any, window: int = 756) -> Optional[float]:
    use = _cr12_norm(frame)
    if use.empty:
        return None
    tail = use["value"].tail(window).dropna()
    if len(tail) < 20:
        return None
    return float((tail <= tail.iloc[-1]).mean() * 100.0)


def _cr12_freshness(latest: Optional[pd.Timestamp], expected_days: int) -> str:
    if latest is None or pd.isna(latest):
        return "Missing"
    now = pd.Timestamp.now(tz="UTC").tz_localize(None).normalize()
    age = max(0, int((now - pd.Timestamp(latest).tz_localize(None).normalize()).days))
    if age <= expected_days:
        return "Fresh"
    if age <= expected_days * 2:
        return "Lagged"
    return "Stale"


@st.cache_data(ttl=21600, show_spinner=False)
def _cr12_load_fred(series_ids: Tuple[str, ...], start_date: str = "1990-01-01", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    ids = tuple(dict.fromkeys(str(x).upper().strip() for x in series_ids if str(x).strip()))
    started = time.perf_counter()
    if not ids:
        return {}, pd.DataFrame(), {"elapsed": 0.0, "provider": "not-requested", "circuit_open": False}
    force = bool(refresh_token)
    pack: Dict[str, pd.DataFrame] = {}
    metas: Dict[str, Dict[str, Any]] = {}
    probe = "BAMLC0A0CM" if "BAMLC0A0CM" in ids else ids[0]
    frame, meta = _liq3_fetch_fred_one(probe, start_date, allow_network=True, force_network=force)
    pack[probe], metas[probe] = frame, meta
    circuit = bool(meta.get("network_error", False) and meta.get("status") not in {"live", "cache"})
    remaining = [sid for sid in ids if sid != probe]
    if circuit:
        for sid in remaining:
            f, m = _liq3_fetch_fred_one(sid, start_date, allow_network=False, force_network=False)
            pack[sid], metas[sid] = f, m
    else:
        with _liq3_ThreadPoolExecutor(max_workers=min(CR12_MAX_WORKERS, max(1, len(remaining)))) as executor:
            futures = {executor.submit(_liq3_fetch_fred_one, sid, start_date, True, force): sid for sid in remaining}
            for future in _liq3_as_completed(futures):
                sid = futures[future]
                try:
                    f, m = future.result()
                except Exception as exc:
                    f, m = pd.DataFrame(columns=["date", "value"]), {"status": "provider-unavailable", "source": "FRED", "message": str(exc)[:180], "network_error": True}
                pack[sid], metas[sid] = f, m
    rows = []
    for sid in ids:
        use = _cr12_norm(pack.get(sid, pd.DataFrame()))
        pack[sid] = use
        spec = CR12_FRED_SERIES.get(sid, {})
        meta = metas.get(sid, {})
        latest = _cr12_latest_date(use)
        rows.append({
            "Series / Instrument": sid,
            "Label": spec.get("label", sid),
            "Category": spec.get("family", "Credit"),
            "Source": meta.get("source", "FRED"),
            "Status": meta.get("status", "unknown"),
            "Freshness": _cr12_freshness(latest, int(spec.get("expected_days", 30))) if not use.empty else "Missing",
            "Observations": len(use),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—",
            "Unit": spec.get("unit", ""),
            "Frequency": spec.get("frequency", ""),
            "Message": meta.get("message", ""),
        })
    return pack, pd.DataFrame(rows), {"elapsed": time.perf_counter() - started, "provider": meta.get("source", "FRED"), "circuit_open": circuit}


@st.cache_data(ttl=21600, show_spinner=False)
def _cr12_load_market(symbols: Tuple[str, ...], period: str = "max", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    ids = tuple(dict.fromkeys(str(x).strip() for x in symbols if str(x).strip()))
    if not ids:
        return {}, pd.DataFrame(), {"elapsed": 0.0, "provider": "not-requested"}
    pack, raw_quality, diag = _liq3_load_market_pack(ids, period=period, refresh_token=refresh_token)
    qmap = {str(row.get("Series / Instrument")): row for _, row in raw_quality.iterrows()} if isinstance(raw_quality, pd.DataFrame) and not raw_quality.empty else {}
    rows = []
    for symbol in ids:
        frame = _cr12_norm(pack.get(symbol, pd.DataFrame()))
        pack[symbol] = frame
        old = qmap.get(symbol, {})
        spec = CR12_MARKET_SYMBOLS.get(symbol, {})
        latest = _cr12_latest_date(frame)
        rows.append({
            "Series / Instrument": symbol,
            "Label": spec.get("label", symbol),
            "Category": spec.get("family", "Credit"),
            "Source": old.get("Source", "Yahoo/yfinance batch"),
            "Status": old.get("Status", "provider-unavailable" if frame.empty else "live"),
            "Freshness": _cr12_freshness(latest, 8) if not frame.empty else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—",
            "Unit": "Adjusted price",
            "Frequency": "Daily",
            "Message": old.get("Message", ""),
        })
    return pack, pd.DataFrame(rows), diag


