def _cr12_header(view: str) -> None:
    meta = {
        "Dashboard": ("CREDIT MARKETS · DASHBOARD", "Credit markets intelligence dashboard", "The same IG, HY, EM/Europe and conditions blocks used by RoboMacro, extended with transparent institutional diagnostics."),
        "US Investment Grade": ("US IG · RATINGS · MATURITY", "US investment-grade credit", "OAS, effective yields, rating dispersion, maturity structure and valuation percentiles."),
        "US High Yield": ("US HY · RATINGS · DISTRESS", "US high-yield credit", "BB, B and CCC risk premia, all-in yields, valuation percentiles and stress impulses."),
        "EM & Europe": ("EM · EUROPE · REGIONAL RISK", "Emerging-market and European credit", "Corporate and high-yield spreads across EM, Euro and Latin American credit."),
        "ETFs & Conditions": ("ETFS · NFCI · SLOOS · CURVE", "Credit ETFs and financial conditions", "Tradable credit proxies, lending standards, financial conditions and macro transmission."),
        "Distress Regime": ("PERCENTILES · STRESS · DRAWDOWN", "Credit distress regime", "Transparent composite regime built from public spreads, lending conditions and market proxies."),
        "Chart Book": (f"{len(CR12_CHARTS)} CHARTS · 6 RESEARCH FAMILIES", "Credit chart book", "Page-level lazy loading with a frozen chart registry and source lineage."),
        "Data Quality": ("AUDIT · FRESHNESS · LINEAGE", "Credit data quality and provider controls", "Series source, freshness, native frequency, cache state and transformation rules."),
    }
    kicker, title, subtitle = meta.get(view, meta["Dashboard"])
    _html(f'<div class="fx7-kicker">{_escape(kicker)}</div><div class="cr12-section-title">{_escape(title)}</div><div class="cr12-section-sub">{_escape(subtitle)}</div>')


def _cr12_fmt_value(value: Optional[float], unit: str = "%") -> str:
    if value is None or not np.isfinite(value):
        return "—"
    if unit in {"%", "pp"}:
        return f"{value:.2f}"
    return f"{value:.2f}"


def _cr12_dashboard_group(title: str, rows: Sequence[Tuple[str, str, str]]) -> str:
    body = []
    for label, value, change in rows:
        try:
            num = float(change.replace("+", "").split()[0])
            cls = "cr12-up" if num < 0 else "cr12-down" if num > 0 else "cr12-flat"
        except Exception:
            cls = "cr12-flat"
        body.append(f'<div class="cr12-kpi-row"><div class="cr12-kpi-label">{_escape(label)}</div><div class="cr12-kpi-value">{_escape(value)}</div><div class="cr12-kpi-change {cls}">{_escape(change)}</div></div>')
    return f'<div class="cr12-kpi-group"><h4>{_escape(title)}</h4>{"".join(body)}</div>'


def _cr12_dashboard_kpis(fred: Mapping[str, pd.DataFrame]) -> None:
    groups = [
        ("Investment Grade", (("US IG OAS", "BAMLC0A0CM"), ("AAA", "BAMLC0A1CAAA"), ("BBB", "BAMLC0A4CBBB"), ("IG Yield", "BAMLC0A0CMEY"))),
        ("High Yield", (("US HY OAS", "BAMLH0A0HYM2"), ("BB", "BAMLH0A1HYBB"), ("CCC", "BAMLH0A3HYC"), ("HY Yield", "BAMLH0A0HYM2EY"))),
        ("EM & Europe", (("EM Corporate", "BAMLEMCBPIOAS"), ("EM High Yield", "BAMLEMHBHYCRPIOAS"), ("Euro HY", "BAMLHE00EHYIOAS"), ("LatAm", "BAMLEMRLCRPILAOAS"))),
        ("Conditions", (("NFCI", "NFCI"), ("Banks Tightening %", "DRTSCILM"), ("Baa–10Y", "BAA10Y"), ("10Y–2Y", "T10Y2Y"))),
    ]
    cards = []
    for title, items in groups:
        rows = []
        for label, sid in items:
            val = _cr12_latest(fred.get(sid, pd.DataFrame()))
            change = _cr12_asof_change(fred.get(sid, pd.DataFrame()), 30)
            rows.append((label, _cr12_fmt_value(val), (f"{change:+.2f} 1M" if change is not None else "— 1M")))
        cards.append(_cr12_dashboard_group(title, rows))
    _html('<div class="cr12-dashboard-grid">' + ''.join(cards) + '</div>')


def _cr12_kpis(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> None:
    ig = _cr12_latest(fred.get("BAMLC0A0CM", pd.DataFrame()))
    hy = _cr12_latest(fred.get("BAMLH0A0HYM2", pd.DataFrame()))
    ccc = _cr12_latest(fred.get("BAMLH0A3HYC", pd.DataFrame()))
    em = _cr12_latest(fred.get("BAMLEMCBPIOAS", pd.DataFrame()))
    nfci = _cr12_latest(fred.get("NFCI", pd.DataFrame()))
    sloos = _cr12_latest(fred.get("DRTSCILM", pd.DataFrame()))
    baa = _cr12_latest(fred.get("BAA10Y", pd.DataFrame()))
    regime = _cr12_regime_snapshot(fred, market)
    cards = [
        _kpi_card("US IG OAS", f"{ig:.2f}%" if ig is not None else "—", "Investment-grade premium"),
        _kpi_card("US HY OAS", f"{hy:.2f}%" if hy is not None else "—", "High-yield premium"),
        _kpi_card("CCC OAS", f"{ccc:.2f}%" if ccc is not None else "—", "Distressed-quality tail"),
        _kpi_card("EM Corporate", f"{em:.2f}%" if em is not None else "—", "Emerging-market credit"),
        _kpi_card("NFCI", f"{nfci:.2f}" if nfci is not None else "—", "Financial conditions"),
        _kpi_card("Banks Tightening", f"{sloos:.1f}%" if sloos is not None else "—", "SLOOS C&I standards"),
        _kpi_card("Baa–10Y", f"{baa:.2f} pp" if baa is not None else "—", "Moody's spread"),
        _kpi_card("Credit Regime", regime.get("label", "—"), f"Score {regime.get('score', '—')} · coverage {regime.get('coverage', 0)}/6"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')


def _cr12_base_figure(ytitle: str, height: int = 410) -> go.Figure:
    return _fi10_base_figure(ytitle, height)


def _cr12_snapshot_card(title: str, subtitle: str, fred: Mapping[str, pd.DataFrame], ids: Sequence[str]) -> None:
    labels, vals, dates = [], [], []
    for sid in ids:
        val = _cr12_latest(fred.get(sid, pd.DataFrame()))
        if val is None:
            continue
        labels.append(CR12_FRED_SERIES.get(sid, {}).get("label", sid))
        vals.append(val)
        dates.append(_cr12_latest_date(fred.get(sid, pd.DataFrame())))
    if not vals:
        _liq5_render_chart_card(title, subtitle, None, [("FRED / ICE BofA", "gold")], empty_message="No usable observations.")
        return
    fig = _cr12_base_figure("OAS %", 390)
    fig.add_trace(go.Scatter(x=labels, y=vals, mode="lines+markers", line=dict(color="#74b9e6", width=3), marker=dict(size=9, color="#d9bf58"), hovertemplate="%{x}<br>%{y:.2f}%<extra></extra>"))
    fig.update_xaxes(type="category")
    badges = [(f"{label} {val:.2f}", "live") for label, val in zip(labels, vals)] + [("FRED / ICE BofA", "gold")]
    latest = max([d for d in dates if d is not None], default=None)
    _liq5_render_chart_card(title, subtitle, fig, badges, f"Latest public observation {_liq5_fmt_date(latest)}")


