def _cr12_risk_return_card(title: str, subtitle: str, market: Mapping[str, pd.DataFrame], symbols: Sequence[str]) -> None:
    rows = []
    for symbol in symbols:
        frame = _cr12_norm(market.get(symbol, pd.DataFrame()))
        if len(frame) < 70:
            continue
        s = frame.set_index("date")["value"]
        ret = (s.iloc[-1] / s.iloc[max(0, len(s)-253)] - 1.0) * 100.0 if len(s) > 20 else np.nan
        vol = np.log(s / s.shift(1)).tail(60).std(ddof=0) * math.sqrt(252) * 100.0
        rows.append((symbol, ret, vol))
    if not rows:
        _liq5_render_chart_card(title, subtitle, None, [("Yahoo/yfinance", "gold")], empty_message="No usable market observations.")
        return
    fig = _cr12_base_figure("1Y return %", 410)
    for i, (symbol, ret, vol) in enumerate(rows):
        fig.add_trace(go.Scatter(x=[vol], y=[ret], mode="markers+text", text=[symbol], textposition="top center", name=symbol, marker=dict(size=12, color=CR12_COLORS[i % len(CR12_COLORS)]), hovertemplate=f"{symbol}<br>60D vol %{{x:.2f}}%<br>1Y return %{{y:.2f}}%<extra></extra>"))
    fig.update_xaxes(title="60D annualized volatility %")
    fig.update_layout(showlegend=False)
    _liq5_render_chart_card(title, subtitle, fig, [("Yahoo/yfinance batch", "gold")], "Latest available inputs")


def _cr12_regime_components(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> List[Tuple[str, Optional[float], float]]:
    components: List[Tuple[str, Optional[float], float]] = []
    components.append(("HY OAS", _cr12_current_percentile(fred.get("BAMLH0A0HYM2", pd.DataFrame())), .25))
    components.append(("CCC OAS", _cr12_current_percentile(fred.get("BAMLH0A3HYC", pd.DataFrame())), .20))
    components.append(("EM HY OAS", _cr12_current_percentile(fred.get("BAMLEMHBHYCRPIOAS", pd.DataFrame())), .15))
    components.append(("NFCI", _cr12_current_percentile(fred.get("NFCI", pd.DataFrame())), .15))
    components.append(("SLOOS", _cr12_current_percentile(fred.get("DRTSCILM", pd.DataFrame()), 80), .15))
    dd = _cr12_drawdown(market.get("HYG", pd.DataFrame()))
    dd_pct = None
    if not dd.empty:
        # More negative drawdown means more stress; invert its historical percentile.
        tail = (-dd["value"]).tail(756).dropna()
        dd_pct = float((tail <= tail.iloc[-1]).mean() * 100.0) if len(tail) >= 20 else None
    components.append(("HYG drawdown", dd_pct, .10))
    return components


def _cr12_regime_snapshot(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> Dict[str, Any]:
    comps = _cr12_regime_components(fred, market)
    avail = [(name, val, weight) for name, val, weight in comps if val is not None and np.isfinite(val)]
    if not avail:
        return {"score": None, "label": "Unavailable", "coverage": 0, "components": comps}
    total_w = sum(w for _, _, w in avail)
    score = sum(float(v) * w for _, v, w in avail) / total_w if total_w else None
    if score is None:
        label = "Unavailable"
    elif score < 30:
        label = "Benign"
    elif score < 55:
        label = "Watch"
    elif score < 75:
        label = "Stressed"
    else:
        label = "Distress"
    return {"score": round(score, 1) if score is not None else None, "label": label, "coverage": len(avail), "components": comps}


def _cr12_regime_history(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    series = []
    weights = []
    for sid, weight in (("BAMLH0A0HYM2", .25), ("BAMLH0A3HYC", .20), ("BAMLEMHBHYCRPIOAS", .15), ("NFCI", .15), ("DRTSCILM", .15)):
        pct = _cr12_rolling_percentile(fred.get(sid, pd.DataFrame()), 756 if sid != "DRTSCILM" else 80)
        if pct.empty:
            continue
        series.append(pct.set_index("date")["value"].rename(sid)); weights.append(weight)
    dd = _cr12_drawdown(market.get("HYG", pd.DataFrame()))
    if not dd.empty:
        s = (-dd.set_index("date")["value"])
        pct = s.rolling(756, min_periods=60).apply(lambda x: float(pd.Series(x).rank(pct=True).iloc[-1] * 100.0), raw=False).dropna()
        if not pct.empty:
            series.append(pct.rename("HYG_DD")); weights.append(.10)
    if not series:
        return pd.DataFrame(columns=["date", "value"])
    panel = pd.concat(series, axis=1).sort_index().ffill(limit=70)
    out = []
    for dt, row in panel.iterrows():
        valid = row.dropna()
        if valid.empty:
            continue
        num = den = 0.0
        for col, w in zip(panel.columns, weights):
            if pd.notna(row.get(col)):
                num += float(row[col]) * w; den += w
        if den > 0:
            out.append((dt, num / den))
    return pd.DataFrame(out, columns=["date", "value"])


def _cr12_regime_history_card(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> None:
    hist = _cr12_regime_history(fred, market)
    if hist.empty:
        _liq5_render_chart_card("Credit Distress Composite", "Transparent 0–100 composite.", None, [("Quant Terminal methodology", "gold")], empty_message="Insufficient component coverage.")
        return
    fig = _cr12_base_figure("Stress score", 420)
    fig.add_hrect(y0=0, y1=30, fillcolor="rgba(58,176,118,.08)", line_width=0)
    fig.add_hrect(y0=30, y1=55, fillcolor="rgba(217,191,88,.08)", line_width=0)
    fig.add_hrect(y0=55, y1=75, fillcolor="rgba(232,117,87,.08)", line_width=0)
    fig.add_hrect(y0=75, y1=100, fillcolor="rgba(198,63,72,.12)", line_width=0)
    fig.add_trace(go.Scatter(x=hist["date"], y=hist["value"], mode="lines", name="Credit stress", line=dict(color="#74b9e6", width=3), hovertemplate="%{x|%d %b %Y}<br>%{y:.1f}<extra></extra>"))
    fig.update_yaxes(range=[0, 100])
    snap = _cr12_regime_snapshot(fred, market)
    _liq5_render_chart_card("Credit Distress Composite", "Weighted public-data regime. Benign <30, Watch 30–55, Stressed 55–75, Distress >75.", fig, [(f"{snap['label']} · {snap['score'] if snap['score'] is not None else '—'}", "live"), ("Not a trading recommendation", "gold")], f"Coverage {snap['coverage']}/6")


def _cr12_regime_matrix_card(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> None:
    snap = _cr12_regime_snapshot(fred, market)
    labels, values = [], []
    for name, value, _weight in snap["components"]:
        if value is not None and np.isfinite(value):
            labels.append(name); values.append(float(value))
    if not values:
        _liq5_render_chart_card("Current Credit Risk Matrix", "Cross-factor percentile heatmap.", None, [("Quant Terminal methodology", "gold")], empty_message="No component observations.")
        return
    fig = go.Figure(go.Heatmap(z=[values], x=labels, y=["Current"], zmin=0, zmax=100, colorscale=[[0, "#39b77a"], [.5, "#d9bf58"], [1, "#d95c5c"]], text=[[f"{v:.0f}" for v in values]], texttemplate="%{text}", colorbar=dict(title="Stress"), hovertemplate="%{x}<br>%{z:.1f}<extra></extra>"))
    fig.update_layout(height=300, margin=dict(l=55,r=35,t=25,b=80), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed"))
    _liq5_render_chart_card("Current Credit Risk Matrix", "Three-year historical percentiles; higher readings indicate greater stress.", fig, [(f"Composite {snap['score'] if snap['score'] is not None else '—'}", "live"), ("Transparent methodology", "gold")], "Latest available inputs")


def _cr12_percentile_snapshot_card(fred: Mapping[str, pd.DataFrame], ids: Sequence[str]) -> None:
    labels, values = [], []
    for sid in ids:
        val = _cr12_current_percentile(fred.get(sid, pd.DataFrame()))
