def _cr12_hy_drawdown_card(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> None:
    _fi10_line_card("HY OAS vs HYG Drawdown", "Cash-bond spread versus ETF drawdown; separate axes preserve scale.", [("HY OAS", fred.get("BAMLH0A0HYM2", pd.DataFrame())), ("HYG drawdown", _cr12_drawdown(market.get("HYG", pd.DataFrame())))], "%", "FRED + Yahoo/yfinance", "Levels", "Raw", allow_yoy=False, second_axis=("HYG drawdown",), right_title="HYG drawdown %", y_policy="positive", y2_policy="auto")


def _cr12_render_spec(spec: Mapping[str, Any], fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    title = f"{int(spec['n'])}. {spec['title']}"
    subtitle = str(spec.get("subtitle", ""))
    kind = str(spec.get("kind", "fred"))
    if kind == "fred":
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in spec.get("ids", ())]
        _fi10_line_card(title, subtitle, items, "%", "FRED / ICE BofA public data", view_mode, smoothing, difference_like=True, y_policy="positive")
    elif kind == "snapshot":
        _cr12_snapshot_card(title, subtitle, fred, spec.get("ids", ()))
    elif kind == "percentile":
        sid = tuple(spec.get("ids", ()))[0]
        _cr12_percentile_card(title, subtitle, fred.get(sid, pd.DataFrame()))
    elif kind == "zscore":
        sid = tuple(spec.get("ids", ()))[0]
        _cr12_zscore_card(title, subtitle, fred.get(sid, pd.DataFrame()))
    elif kind == "spread":
        frame = _cr12_spread(fred.get(spec.get("a"), pd.DataFrame()), fred.get(spec.get("b"), pd.DataFrame()))
        _fi10_line_card(title, subtitle, [(str(spec.get("label", "Spread")), frame)], "pp", "FRED / Quant Terminal calculation", "Levels", smoothing, allow_yoy=False, difference_like=True)
    elif kind == "change":
        sid = tuple(spec.get("ids", ()))[0]
        frame = _cr12_change(fred.get(sid, pd.DataFrame()), int(spec.get("periods", 20)))
        _fi10_line_card(title, subtitle, [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), frame)], "pp", "FRED / Quant Terminal calculation", "Levels", smoothing, allow_yoy=False, difference_like=True)
    elif kind == "dual":
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in tuple(spec.get("left", ())) + tuple(spec.get("right", ()))]
        right_labels = [CR12_FRED_SERIES.get(sid, {}).get("label", sid) for sid in spec.get("right", ())]
        _fi10_line_card(title, subtitle, items, "%", "FRED / public data", "Levels", smoothing, allow_yoy=False, second_axis=right_labels, right_title=str(spec.get("right_title", "Secondary")), y_policy="auto", y2_policy="auto")
    elif kind == "fred_market_dual":
        left_ids = tuple(spec.get("left", ())); symbols = tuple(spec.get("market", ()))
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in left_ids] + [(sym, market.get(sym, pd.DataFrame())) for sym in symbols]
        _fi10_line_card(title, subtitle, items, "%", "FRED + Yahoo/yfinance", "Levels", smoothing, allow_yoy=False, second_axis=list(symbols), right_title=str(spec.get("right_title", "Market")), y_policy="positive", y2_policy="positive")
    elif kind == "market_index":
        _fi11_indexed_card(title, subtitle, [(sym, market.get(sym, pd.DataFrame())) for sym in spec.get("symbols", ())], smoothing, "Yahoo/yfinance batch")
    elif kind == "market_ratio":
        _cr12_market_ratio_card(title, subtitle, market, str(spec.get("a")), str(spec.get("b")), str(spec.get("label", "Ratio")))
    elif kind == "risk_return":
        _cr12_risk_return_card(title, subtitle, market, spec.get("symbols", ()))
    elif kind == "regime_history":
        _cr12_regime_history_card(fred, market)
    elif kind == "regime_matrix":
        _cr12_regime_matrix_card(fred, market)
    elif kind == "percentile_snapshot":
        _cr12_percentile_snapshot_card(fred, spec.get("ids", ()))
    elif kind == "hy_drawdown":
        _cr12_hy_drawdown_card(fred, market)
    else:
        _liq5_render_chart_card(title, subtitle, None, [("Provider-required", "gold")], empty_message=f"Unsupported chart kind: {kind}")


def _cr12_specs_for_family(family: str) -> List[Dict[str, Any]]:
    return [dict(x) for x in CR12_CHARTS if x["family"] == family]


def _cr12_requirements(specs: Sequence[Mapping[str, Any]]) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    fred: List[str] = []
    market: List[str] = []
    for spec in specs:
        for key in ("ids", "left", "right"):
            fred.extend(list(spec.get(key, ()) or ()))
        if spec.get("kind") == "spread":
            fred.extend([spec.get("a"), spec.get("b")])
        for key in ("symbols", "market"):
            market.extend(list(spec.get(key, ()) or ()))
        if spec.get("kind") == "market_ratio":
            market.extend([spec.get("a"), spec.get("b")])
        if spec.get("kind") in {"regime_history", "regime_matrix", "hy_drawdown"}:
            fred.extend(["BAMLH0A0HYM2", "BAMLH0A3HYC", "BAMLEMHBHYCRPIOAS", "NFCI", "DRTSCILM"])
            market.append("HYG")
        if spec.get("kind") == "percentile_snapshot":
            fred.extend(list(spec.get("ids", ()) or ()))
    return tuple(dict.fromkeys(x for x in fred if x)), tuple(dict.fromkeys(x for x in market if x))


def _cr12_required(view: str, family_filter: str = "All") -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    if view == "Dashboard":
        specs = _cr12_specs_for_family("Dashboard")
        fred = list(CR12_DASHBOARD_SERIES)
        f2, m2 = _cr12_requirements(specs)
        fred.extend(f2); market = list(m2)
        fred.extend(["BAMLH0A3HYC", "BAMLEMHBHYCRPIOAS", "NFCI", "DRTSCILM"]); market.append("HYG")
    elif view == "Chart Book":
        specs = [dict(x) for x in CR12_CHARTS if family_filter == "All" or x["family"] == family_filter]
        total_pages = max(1, int(math.ceil(len(specs) / CR12_CHART_PAGE_SIZE)))
        current = max(1, min(int(st.session_state.get("market_cr12_chart_page", 1)), total_pages))
        page_specs = specs[(current - 1) * CR12_CHART_PAGE_SIZE: current * CR12_CHART_PAGE_SIZE]
        fred, market = map(list, _cr12_requirements(page_specs))
    elif view == "Data Quality":
        return tuple(CR12_FRED_SERIES), tuple(CR12_MARKET_SYMBOLS)
    else:
        fred, market = map(list, _cr12_requirements(_cr12_specs_for_family(view)))
    # Keep KPI strip useful without loading the entire universe.
    core = ["BAMLC0A0CM", "BAMLH0A0HYM2", "BAMLH0A3HYC", "BAMLEMCBPIOAS", "NFCI", "DRTSCILM", "BAA10Y"]
    fred = list(dict.fromkeys(list(fred) + core))
    return tuple(fred), tuple(dict.fromkeys(market))


def _cr12_dashboard(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    _cr12_dashboard_kpis(fred)
    tasks = [lambda spec=spec: _cr12_render_spec(spec, fred, market, view_mode, smoothing) for spec in _cr12_specs_for_family("Dashboard")]
    _liq6_two_column(tasks)
    snap = _cr12_regime_snapshot(fred, market)
    rows = []
    for name, value, weight in snap["components"]:
        rows.append({"Component": name, "Stress percentile": round(value, 1) if value is not None else np.nan, "Weight": f"{weight:.0%}", "Available": value is not None})
    _liq5_table_card("Credit Regime Composition", "Transparent public-data score; missing components are removed and remaining weights are normalized.", pd.DataFrame(rows), [(f"{snap['label']} · {snap['score'] if snap['score'] is not None else '—'}", "live"), ("Not a trading recommendation", "gold")], f"Coverage {snap['coverage']}/6", 20)


def _cr12_family_view(view: str, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    specs = _cr12_specs_for_family(view)
    tasks = [lambda spec=spec: _cr12_render_spec(spec, fred, market, view_mode, smoothing) for spec in specs]
    _liq6_two_column(tasks)
    if view == "US Investment Grade":
        rows = []
        for rating, sid_oas, sid_yield in (("AAA", "BAMLC0A1CAAA", "BAMLC0A1CAAAEY"), ("AA", "BAMLC0A2CAA", "BAMLC0A2CAAEY"), ("A", "BAMLC0A3CA", "BAMLC0A3CAEY"), ("BBB", "BAMLC0A4CBBB", "BAMLC0A4CBBBEY")):
            rows.append({"Rating": rating, "OAS %": _cr12_latest(fred.get(sid_oas, pd.DataFrame())), "Effective yield %": _cr12_latest(fred.get(sid_yield, pd.DataFrame())), "OAS percentile": _cr12_current_percentile(fred.get(sid_oas, pd.DataFrame())), "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid_oas, pd.DataFrame())))})
        _liq5_table_card("US IG Rating Ladder", "Current OAS, effective yield and historical percentile by rating.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)
    elif view == "US High Yield":
        rows = []
        for rating, sid_oas, sid_yield in (("BB", "BAMLH0A1HYBB", "BAMLH0A1HYBBEY"), ("B", "BAMLH0A2HYB", "BAMLH0A2HYBEY"), ("CCC & lower", "BAMLH0A3HYC", "BAMLH0A3HYCEY")):
            rows.append({"Rating": rating, "OAS %": _cr12_latest(fred.get(sid_oas, pd.DataFrame())), "Effective yield %": _cr12_latest(fred.get(sid_yield, pd.DataFrame())), "OAS percentile": _cr12_current_percentile(fred.get(sid_oas, pd.DataFrame())), "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid_oas, pd.DataFrame())))})
        _liq5_table_card("US HY Rating Ladder", "Current OAS, effective yield and historical percentile by rating.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)
    elif view == "EM & Europe":
        rows = []
        for label, sid in (("EM Corporate", "BAMLEMCBPIOAS"), ("EM High Yield", "BAMLEMHBHYCRPIOAS"), ("Euro High Yield", "BAMLHE00EHYIOAS"), ("Latin America", "BAMLEMRLCRPILAOAS")):
            rows.append({"Universe": label, "OAS %": _cr12_latest(fred.get(sid, pd.DataFrame())), "1M Δ pp": _cr12_asof_change(fred.get(sid, pd.DataFrame()), 30), "Percentile": _cr12_current_percentile(fred.get(sid, pd.DataFrame())), "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid, pd.DataFrame())))})
        _liq5_table_card("EM & Europe Credit Ladder", "Regional spread, monthly change and historical percentile.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)
    elif view == "ETFs & Conditions":
        rows = []
        for symbol in ("LQD", "VCIT", "VCLT", "HYG", "JNK", "ANGL", "FALN", "BKLN"):
            frame = _cr12_norm(market.get(symbol, pd.DataFrame()))
            if frame.empty:
                rows.append({"ETF": symbol, "Price": np.nan, "1M %": np.nan, "1Y %": np.nan, "60D vol %": np.nan, "Drawdown %": np.nan})
                continue
            s = frame.set_index("date")["value"]
            rows.append({"ETF": symbol, "Price": s.iloc[-1], "1M %": (s.iloc[-1] / s.iloc[max(0, len(s)-22)] - 1) * 100 if len(s) > 22 else np.nan, "1Y %": (s.iloc[-1] / s.iloc[max(0, len(s)-253)] - 1) * 100 if len(s) > 20 else np.nan, "60D vol %": np.log(s/s.shift(1)).tail(60).std(ddof=0)*math.sqrt(252)*100, "Drawdown %": (s.iloc[-1]/s.cummax().iloc[-1]-1)*100})
        _liq5_table_card("Credit ETF Monitor", "Adjusted-price proxies with return, volatility and drawdown diagnostics.", pd.DataFrame(rows), [("Yahoo/yfinance batch", "gold")], "Latest market observations", 30)


def _cr12_chart_book(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], family_filter: str, view_mode: str, smoothing: str) -> None:
    specs = [dict(x) for x in CR12_CHARTS if family_filter == "All" or x["family"] == family_filter]
    total_pages = max(1, int(math.ceil(len(specs) / CR12_CHART_PAGE_SIZE)))
    current = max(1, min(int(st.session_state.get("market_cr12_chart_page", 1)), total_pages))
    c = st.columns([1, 2.1, 1], gap="medium")
    with c[0]:
        if st.button("← Previous", key="market_cr12_prev", disabled=current <= 1, width="stretch"):
            st.session_state["market_cr12_chart_page"] = current - 1; st.rerun()
    with c[1]:
        st.markdown(f"<div style='text-align:center;color:#aeb9c4;padding:.55rem'>Showing {(current-1)*CR12_CHART_PAGE_SIZE+1}–{min(current*CR12_CHART_PAGE_SIZE,len(specs))} of {len(specs)} charts · Page {current} of {total_pages}</div>", unsafe_allow_html=True)
    with c[2]:
        if st.button("Next →", key="market_cr12_next", disabled=current >= total_pages, width="stretch"):
            st.session_state["market_cr12_chart_page"] = current + 1; st.rerun()
    page_specs = specs[(current - 1) * CR12_CHART_PAGE_SIZE: current * CR12_CHART_PAGE_SIZE]
    _liq6_two_column([lambda spec=spec: _cr12_render_spec(spec, fred, market, view_mode, smoothing) for spec in page_specs])


def _cr12_quality(quality: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    if quality is None:
        quality = pd.DataFrame()
    loaded = int((~quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).isin(["Lagged", "Stale"]).sum()) if not quality.empty else 0
    dates = pd.to_datetime(quality.get("Latest Date", pd.Series(dtype=str)), errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    latest = dates.max()
    _html('<div class="mk-kpis">' + ''.join([
        _kpi_card("Series loaded", f"{loaded}/{len(quality)}", "Active lazy route"),
        _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"),
        _kpi_card("Lagged / stale", str(lagged), "Visible; not silently imputed"),
        _kpi_card("Latest observation", _liq5_fmt_date(latest), f"Wall load {diagnostics.get('elapsed',0):.1f}s"),
    ]) + '</div>')
    _liq5_table_card("Credit Series Registry and Freshness", "FRED/ICE BofA spreads and yields, SLOOS, financial conditions and market proxies.", quality, [("Public / market lineage", "gold")], "Current lazy route", 200)
    contract = pd.DataFrame([
        {"Layer": "US IG / HY spreads", "Primary source": "FRED / ICE BofA index OAS", "Fallback": "Fresh or stale disk cache", "Rule": "Native daily close; no fabricated extension"},
        {"Layer": "Effective yields", "Primary source": "FRED / ICE BofA effective-yield indices", "Fallback": "Disk cache", "Rule": "Separated from OAS; not interpreted as spread"},
        {"Layer": "EM / Europe", "Primary source": "FRED / ICE BofA regional indices", "Fallback": "Disk cache", "Rule": "Currency and universe labels remain explicit"},
        {"Layer": "Lending standards", "Primary source": "Federal Reserve SLOOS via FRED", "Fallback": "Disk cache", "Rule": "Quarterly native frequency retained"},
        {"Layer": "Conditions", "Primary source": "Chicago Fed NFCI / St. Louis Fed stress", "Fallback": "Disk cache", "Rule": "No resampling presented as new observation"},
        {"Layer": "Credit ETFs", "Primary source": "Yahoo/yfinance adjusted-price batch", "Fallback": "Disk cache", "Rule": "Market proxy; not a bond-index OAS"},
        {"Layer": "Distress composite", "Primary source": "Transparent percentile calculation", "Fallback": "Unavailable if coverage is insufficient", "Rule": "Weights renormalized over available inputs"},
    ])
    _liq5_table_card("Credit Provider Contract", "Frozen source, frequency and modelling rules.", contract, [("No silent synthetic production history", "live")], CR12_VERSION, 40)
    parity = pd.DataFrame([{"Order": x["n"], "Family": x["family"], "Title": x["title"], "Kind": x["kind"], "Status": "Registered / tested"} for x in CR12_CHARTS])
    _liq5_table_card("Credit Chart Registry", "Frozen chart order and research-family assignment.", parity, [(f"{len(CR12_CHARTS)} charts", "gold")], "RoboMacro-aligned public dashboard + institutional extensions", 100)
    st.download_button("Download Credit data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_credit_quality_v12.csv", mime="text/csv", key="market_cr12_download_quality")


def _render_credit_page(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css()
    view = st.segmented_control("Credit research view", CR12_VIEW_OPTIONS, key="market_cr12_view", label_visibility="collapsed") or "Dashboard"
    _cr12_header(view)
    controls = st.columns([1.05, 1.0, 1.05, .75], gap="medium")
    with controls[0]:
        view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_cr12_level_mode")
    with controls[1]:
        smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_cr12_smoothing")
    family_filter = "All"
    with controls[2]:
        if view == "Chart Book":
            family_filter = st.selectbox("Research family", ["All"] + list(CR12_FAMILIES), key="market_cr12_family_filter")
        else:
            st.caption("Only the active credit route is loaded.")
    with controls[3]:
        refresh = st.button("Refresh", key="market_cr12_refresh", width="stretch")
    if refresh:
        st.session_state["market_cr12_refresh_nonce"] = int(st.session_state.get("market_cr12_refresh_nonce", 0)) + 1
        st.rerun()
    nonce = int(st.session_state.get("market_cr12_refresh_nonce", 0))
    fred_ids, symbols = _cr12_required(view, family_filter)
    started = time.perf_counter()
    with st.spinner("Loading Credit — bounded public providers..."):
        fred, q_fred, d_fred = _cr12_load_fred(fred_ids, "1990-01-01", nonce)
        market, q_market, d_market = _cr12_load_market(symbols, "max", nonce)
    elapsed = time.perf_counter() - started
    parts = [x for x in (q_fred, q_market) if isinstance(x, pd.DataFrame) and not x.empty]
    quality = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    _cr12_kpis(fred, market)
    _html(f'<div class="cr12-note"><b>{_escape(CR12_VERSION)}</b> · Wall load {elapsed:.1f}s · FRED {d_fred.get("elapsed",0):.1f}s · Market {d_market.get("elapsed",0):.1f}s · active route {_escape(view)}.</div>')
    try:
        if view == "Dashboard":
            _cr12_dashboard(fred, market, view_mode, smoothing)
        elif view in CR12_FAMILIES and view != "Dashboard":
            _cr12_family_view(view, fred, market, view_mode, smoothing)
        elif view == "Chart Book":
            _cr12_chart_book(fred, market, family_filter, view_mode, smoothing)
        else:
            _cr12_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market})
    except Exception as exc:
        st.error(f"Credit route failed: {type(exc).__name__}: {exc}")
        with st.expander("Credit traceback", expanded=False):
            import traceback as _cr12_traceback
            st.code(_cr12_traceback.format_exc())


