def _cr12_required(view: str, family_filter: str = "All") -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    fred, market = _cr12_required_v12(view, family_filter)
    fred = tuple(dict.fromkeys(tuple(fred) + _CR13_REGIME_FRED))
    market = tuple(dict.fromkeys(tuple(market) + _CR13_REGIME_MARKET))
    return fred, market


def _cr13_source_for_id(series_id: str) -> str:
    sid = str(series_id or "").upper()
    if sid.startswith("BAML"):
        return "ICE BofA via FRED"
    if sid == "NFCI":
        return "Chicago Fed via FRED"
    if sid == "DRTSCILM":
        return "Federal Reserve SLOOS via FRED"
    if sid == "BAA10Y":
        return "Moody's Baa spread via FRED"
    if sid == "T10Y2Y":
        return "US Treasury curve via FRED"
    if sid == "STLFSI4":
        return "St. Louis Fed via FRED"
    if sid == "USREC":
        return "NBER recession indicator via FRED"
    return "FRED public data"


def _cr13_source_for_ids(series_ids: Sequence[str]) -> str:
    labels = []
    for sid in series_ids:
        label = _cr13_source_for_id(str(sid))
        if label not in labels:
            labels.append(label)
    return " + ".join(labels) if labels else "FRED public data"


def _cr13_unit_for_ids(series_ids: Sequence[str]) -> str:
    units = []
    for sid in series_ids:
        unit = str(CR12_FRED_SERIES.get(str(sid), {}).get("unit", "")).strip()
        if unit and unit not in units:
            units.append(unit)
    if len(units) == 1:
        return units[0]
    return "Value"


_cr12_render_spec_v12 = _cr12_render_spec


def _cr12_render_spec(spec: Mapping[str, Any], fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    """V13 lineage-aware wrapper; all non-lineage branches delegate to V12."""
    title = f"{int(spec['n'])}. {spec['title']}"
    subtitle = str(spec.get("subtitle", ""))
    kind = str(spec.get("kind", "fred"))

    if kind == "fred":
        ids = tuple(spec.get("ids", ()) or ())
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in ids]
        unit = _cr13_unit_for_ids(ids)
        y_policy = "positive" if unit in {"%", "pp"} and not any(sid in {"T10Y2Y", "NFCI", "STLFSI4"} for sid in ids) else "auto"
        _fi10_line_card(
            title, subtitle, items, unit, _cr13_source_for_ids(ids),
            view_mode, smoothing, difference_like=unit in {"%", "pp"}, y_policy=y_policy,
        )
        return

    if kind == "dual":
        left_ids = tuple(spec.get("left", ()) or ())
        right_ids = tuple(spec.get("right", ()) or ())
        all_ids = left_ids + right_ids
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in all_ids]
        right_labels = [CR12_FRED_SERIES.get(sid, {}).get("label", sid) for sid in right_ids]
        _fi10_line_card(
            title, subtitle, items, _cr13_unit_for_ids(left_ids), _cr13_source_for_ids(all_ids),
            "Levels", smoothing, allow_yoy=False, second_axis=right_labels,
            right_title=str(spec.get("right_title", "Secondary")), y_policy="auto", y2_policy="auto",
        )
        return

    if kind == "fred_market_dual":
        left_ids = tuple(spec.get("left", ()) or ())
        symbols = tuple(spec.get("market", ()) or ())
        items = [(CR12_FRED_SERIES.get(sid, {}).get("label", sid), fred.get(sid, pd.DataFrame())) for sid in left_ids]
        items += [(sym, market.get(sym, pd.DataFrame())) for sym in symbols]
        source = _cr13_source_for_ids(left_ids) + " + Yahoo/yfinance"
        _fi10_line_card(
            title, subtitle, items, _cr13_unit_for_ids(left_ids), source,
            "Levels", smoothing, allow_yoy=False, second_axis=list(symbols),
            right_title=str(spec.get("right_title", "Market")), y_policy="auto", y2_policy="positive",
        )
        return

    return _cr12_render_spec_v12(spec, fred, market, view_mode, smoothing)


def _cr13_round(value: Any, digits: int = 2) -> Any:
    val = _safe_float(value)
    return round(val, digits) if val is not None and np.isfinite(val) else np.nan


def _cr13_market_asof(frame: Any) -> str:
    return _liq5_fmt_date(_cr12_latest_date(frame))


# Re-render the family tables with institutional precision rather than raw
# Python floats. Chart rendering remains the tested V12/V13 registry.
def _cr12_family_view(view: str, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    specs = _cr12_specs_for_family(view)
    tasks = [lambda spec=spec: _cr12_render_spec(spec, fred, market, view_mode, smoothing) for spec in specs]
    _liq6_two_column(tasks)

    if view == "US Investment Grade":
        rows = []
        for rating, sid_oas, sid_yield in (
            ("AAA", "BAMLC0A1CAAA", "BAMLC0A1CAAAEY"),
            ("AA", "BAMLC0A2CAA", "BAMLC0A2CAAEY"),
            ("A", "BAMLC0A3CA", "BAMLC0A3CAEY"),
            ("BBB", "BAMLC0A4CBBB", "BAMLC0A4CBBBEY"),
        ):
            rows.append({
                "Rating": rating,
                "OAS %": _cr13_round(_cr12_latest(fred.get(sid_oas, pd.DataFrame())), 2),
                "Effective yield %": _cr13_round(_cr12_latest(fred.get(sid_yield, pd.DataFrame())), 2),
                "OAS percentile": _cr13_round(_cr12_current_percentile(fred.get(sid_oas, pd.DataFrame())), 1),
                "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid_oas, pd.DataFrame()))),
            })
        _liq5_table_card("US IG Rating Ladder", "Current OAS, effective yield and historical percentile by rating.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)

    elif view == "US High Yield":
        rows = []
        for rating, sid_oas, sid_yield in (
            ("BB", "BAMLH0A1HYBB", "BAMLH0A1HYBBEY"),
            ("B", "BAMLH0A2HYB", "BAMLH0A2HYBEY"),
            ("CCC & lower", "BAMLH0A3HYC", "BAMLH0A3HYCEY"),
        ):
            rows.append({
                "Rating": rating,
                "OAS %": _cr13_round(_cr12_latest(fred.get(sid_oas, pd.DataFrame())), 2),
                "Effective yield %": _cr13_round(_cr12_latest(fred.get(sid_yield, pd.DataFrame())), 2),
                "OAS percentile": _cr13_round(_cr12_current_percentile(fred.get(sid_oas, pd.DataFrame())), 1),
                "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid_oas, pd.DataFrame()))),
            })
        _liq5_table_card("US HY Rating Ladder", "Current OAS, effective yield and historical percentile by rating.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)

    elif view == "EM & Europe":
        rows = []
        for label, sid in (
            ("EM Corporate", "BAMLEMCBPIOAS"),
            ("EM High Yield", "BAMLEMHBHYCRPIOAS"),
            ("Euro High Yield", "BAMLHE00EHYIOAS"),
            ("Latin America", "BAMLEMRLCRPILAOAS"),
        ):
            rows.append({
                "Universe": label,
                "OAS %": _cr13_round(_cr12_latest(fred.get(sid, pd.DataFrame())), 2),
                "1M Δ pp": _cr13_round(_cr12_asof_change(fred.get(sid, pd.DataFrame()), 30), 2),
                "Percentile": _cr13_round(_cr12_current_percentile(fred.get(sid, pd.DataFrame())), 1),
                "As of": _liq5_fmt_date(_cr12_latest_date(fred.get(sid, pd.DataFrame()))),
            })
        _liq5_table_card("EM & Europe Credit Ladder", "Regional spread, monthly change and historical percentile.", pd.DataFrame(rows), [("FRED / ICE BofA", "gold")], "Latest native-frequency observations", 20)

    elif view == "ETFs & Conditions":
        rows = []
        for symbol in ("LQD", "VCIT", "VCLT", "HYG", "JNK", "ANGL", "FALN", "BKLN"):
            frame = _cr12_norm(market.get(symbol, pd.DataFrame()))
            if frame.empty:
                rows.append({"ETF": symbol, "Price": np.nan, "1M %": np.nan, "1Y %": np.nan, "60D vol %": np.nan, "Drawdown %": np.nan, "As of": "—"})
                continue
            s = frame.set_index("date")["value"].dropna()
            ret_1m = (s.iloc[-1] / s.iloc[-22] - 1.0) * 100.0 if len(s) >= 22 else np.nan
            ret_1y = (s.iloc[-1] / s.iloc[-253] - 1.0) * 100.0 if len(s) >= 253 else np.nan
            vol_60 = np.log(s / s.shift(1)).tail(60).std(ddof=0) * math.sqrt(252) * 100.0 if len(s) >= 20 else np.nan
            drawdown = (s.iloc[-1] / s.cummax().iloc[-1] - 1.0) * 100.0 if not s.empty else np.nan
            rows.append({
                "ETF": symbol,
                "Price": _cr13_round(s.iloc[-1], 2),
                "1M %": _cr13_round(ret_1m, 2),
                "1Y %": _cr13_round(ret_1y, 2),
                "60D vol %": _cr13_round(vol_60, 2),
                "Drawdown %": _cr13_round(drawdown, 2),
                "As of": _cr13_market_asof(frame),
            })
        _liq5_table_card("Credit ETF Monitor", "Adjusted-price proxies with return, volatility and drawdown diagnostics.", pd.DataFrame(rows), [("Yahoo/yfinance batch", "gold")], "Latest market observations", 30)


def _cr12_quality(quality: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    if quality is None:
        quality = pd.DataFrame()
    loaded = int((~quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).isin(["Lagged", "Stale"]).sum()) if not quality.empty else 0
    dates = pd.to_datetime(quality.get("Latest Date", pd.Series(dtype=str)), errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    latest = dates.max()
    _html('<div class="mk-kpis">' + ''.join([
        _kpi_card("Series loaded", f"{loaded}/{len(quality)}", "Full Credit audit route"),
        _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"),
        _kpi_card("Lagged / stale", str(lagged), "Visible; not silently imputed"),
        _kpi_card("Latest observation", _liq5_fmt_date(latest), f"Wall load {diagnostics.get('elapsed',0):.1f}s"),
    ]) + '</div>')
    _liq5_table_card("Credit Series Registry and Freshness", "FRED/ICE BofA spreads and yields, SLOOS, financial conditions and market proxies.", quality, [("Public / market lineage", "gold")], "Current full audit", 200)

    contract = pd.DataFrame([
        {"Layer": "US IG / HY spreads", "Primary source": "FRED / ICE BofA index OAS", "Fallback": "Fresh or stale disk cache", "Rule": "Native daily close; no fabricated extension"},
        {"Layer": "Effective yields", "Primary source": "FRED / ICE BofA effective-yield indices", "Fallback": "Disk cache", "Rule": "Separated from OAS; not interpreted as spread"},
        {"Layer": "EM / Europe", "Primary source": "FRED / ICE BofA regional indices", "Fallback": "Disk cache", "Rule": "Currency and universe labels remain explicit"},
        {"Layer": "Lending standards", "Primary source": "Federal Reserve SLOOS via FRED", "Fallback": "Disk cache", "Rule": "Quarterly native frequency retained"},
        {"Layer": "Conditions", "Primary source": "Chicago Fed NFCI / St. Louis Fed stress", "Fallback": "Disk cache", "Rule": "No resampling presented as a new observation"},
        {"Layer": "Baa–Treasury", "Primary source": "Moody's Baa spread via FRED", "Fallback": "Disk cache", "Rule": "Not labelled as an ICE BofA series"},
        {"Layer": "Credit ETFs", "Primary source": "Yahoo/yfinance adjusted-price batch", "Fallback": "Disk cache", "Rule": "Market proxy; not a bond-index OAS"},
        {"Layer": "Distress composite", "Primary source": "Transparent percentile calculation", "Fallback": "Unavailable if coverage is insufficient", "Rule": "Six core inputs loaded on every Credit route"},
    ])
    _liq5_table_card("Credit Provider Contract", "Frozen source, frequency and modelling rules.", contract, [("No silent synthetic production history", "live")], CR13_VERSION, 50)

    parity = pd.DataFrame([
        {
            "Order": x["n"],
            "Family": x["family"],
            "Title": x["title"],
            "Kind": x["kind"],
            "Status": "Public RoboMacro parity verified" if int(x["n"]) <= 2 else "Institutional extension tested",
        }
        for x in CR12_CHARTS
    ])
    _liq5_table_card("Credit Chart Registry", "Public-dashboard parity is separated from internal institutional extensions.", parity, [(f"{len(CR12_CHARTS)} charts", "gold")], "2 public parity charts + 42 tested extensions", 100)
    st.download_button("Download Credit data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_credit_quality_v13.csv", mime="text/csv", key="market_cr13_download_quality")


# V13 renderer: retain lazy routing and providers, but show only the actual wall
# time of the current rerun. Cached provider diagnostics no longer appear as
# impossible component durations greater than the wall time.
def _render_credit_page(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css()
    view = st.segmented_control("Credit research view", CR12_VIEW_OPTIONS, key="market_cr12_view", label_visibility="collapsed") or "Dashboard"
    _cr12_header(view)
    controls = st.columns([1.05, 1.0, 1.05, .75], gap="medium")
    with controls[0]:
        view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_cr12_level_mode")
    with controls[1]:
        smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_cr12_smoothing")
    family_filter = "All"
    with controls[2]:
        if view == "Chart Book":
            family_filter = st.selectbox("Research family", ["All"] + list(CR12_FAMILIES), key="market_cr12_family_filter")
        else:
            st.caption("Only the active credit route is loaded.")
    with controls[3]:
        refresh = st.button("Refresh", key="market_cr12_refresh", width="stretch")
    if refresh:
        st.session_state["market_cr12_refresh_nonce"] = int(st.session_state.get("market_cr12_refresh_nonce", 0)) + 1
        st.rerun()

    nonce = int(st.session_state.get("market_cr12_refresh_nonce", 0))
    fred_ids, symbols = _cr12_required(view, family_filter)
    started = time.perf_counter()
    with st.spinner("Loading Credit — bounded public providers..."):
        fred, q_fred, d_fred = _cr12_load_fred(fred_ids, "1990-01-01", nonce)
        market, q_market, d_market = _cr12_load_market(symbols, "max", nonce)
    elapsed = time.perf_counter() - started
    parts = [x for x in (q_fred, q_market) if isinstance(x, pd.DataFrame) and not x.empty]
    quality = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()

    _cr12_kpis(fred, market)
    fred_provider = str(d_fred.get("provider", "FRED"))
    market_provider = str(d_market.get("provider", "market data"))
    _html(
        f'<div class="cr12-note"><b>{_escape(CR13_VERSION)}</b> · '
        f'Wall load {elapsed:.1f}s · FRED {_escape(fred_provider)} · '
        f'Market {_escape(market_provider)} · active route {_escape(view)}.</div>'
    )

    try:
        if view == "Dashboard":
            _cr12_dashboard(fred, market, view_mode, smoothing)
        elif view in CR12_FAMILIES and view != "Dashboard":
            _cr12_family_view(view, fred, market, view_mode, smoothing)
        elif view == "Chart Book":
            _cr12_chart_book(fred, market, family_filter, view_mode, smoothing)
        else:
            _cr12_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market})
    except Exception as exc:
        st.error(f"Credit route failed: {type(exc).__name__}: {exc}")
        with st.expander("Credit traceback", expanded=False):
            import traceback as _cr13_traceback
            st.code(_cr13_traceback.format_exc())


