def _eq14_norm(frame: Any) -> pd.DataFrame:
    use = _liq3_frame(frame)
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    use = use[["date", "value"]].copy()
    use["date"] = pd.to_datetime(use["date"], errors="coerce").dt.tz_localize(None).astype("datetime64[ns]")
    use["value"] = pd.to_numeric(use["value"], errors="coerce")
    return use.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _eq14_latest(frame: Any) -> Optional[float]:
    use = _eq14_norm(frame)
    return _safe_float(use["value"].iloc[-1]) if not use.empty else None


def _eq14_latest_date(frame: Any) -> Optional[pd.Timestamp]:
    use = _eq14_norm(frame)
    return pd.Timestamp(use["date"].iloc[-1]) if not use.empty else None


def _eq14_ratio(a: Any, b: Any, tolerance_days: int = 10) -> pd.DataFrame:
    left = _eq14_norm(a).rename(columns={"value": "a"})
    right = _eq14_norm(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    left["date"] = left["date"].astype("datetime64[ns]"); right["date"] = right["date"].astype("datetime64[ns]")
    merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=int(tolerance_days)))
    merged["value"] = merged["a"] / merged["b"].replace(0, np.nan)
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _eq14_spread(a: Any, b: Any, tolerance_days: int = 100) -> pd.DataFrame:
    left = _eq14_norm(a).rename(columns={"value": "a"})
    right = _eq14_norm(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(left.sort_values("date"), right.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=int(tolerance_days)))
    merged["value"] = merged["a"] - merged["b"]
    return merged[["date", "value"]].dropna().reset_index(drop=True)


def _eq14_yoy(frame: Any) -> pd.DataFrame:
    use = _eq14_norm(frame)
    if use.empty:
        return use
    s = use.set_index("date")["value"]
    # Calendar alignment handles monthly, weekly and daily public series.
    out = pd.DataFrame({"date": s.index, "value": s.pct_change(12, fill_method=None) * 100.0}) if len(s) > 0 and pd.infer_freq(s.index[:min(len(s), 20)]) in {"MS", "M", "ME"} else pd.DataFrame()
    if out.empty or out["value"].dropna().empty:
        shifted = s.copy().rename("current").reset_index()
        prior = s.copy().rename("prior").reset_index(); prior["date"] = prior["date"] + pd.DateOffset(years=1)
        shifted["date"] = shifted["date"].astype("datetime64[ns]"); prior["date"] = prior["date"].astype("datetime64[ns]")
        merged = pd.merge_asof(shifted.sort_values("date"), prior.sort_values("date"), on="date", direction="nearest", tolerance=pd.Timedelta(days=45))
        merged["value"] = (merged["current"] / merged["prior"] - 1.0) * 100.0
        out = merged[["date", "value"]]
    return out.replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _eq14_drawdown(frame: Any) -> pd.DataFrame:
    use = _eq14_norm(frame)
    if use.empty:
        return use
    s = use["value"]
    return pd.DataFrame({"date": use["date"], "value": (s / s.cummax() - 1.0) * 100.0}).dropna().reset_index(drop=True)


def _eq14_vol(frame: Any, window: int) -> pd.DataFrame:
    use = _eq14_norm(frame)
    if use.empty:
        return use
    r = np.log(use["value"] / use["value"].shift(1))
    v = r.rolling(int(window), min_periods=max(10, int(window)//2)).std(ddof=0) * math.sqrt(252.0) * 100.0
    return pd.DataFrame({"date": use["date"], "value": v}).dropna().reset_index(drop=True)


def _eq14_return(frame: Any, periods: int) -> Optional[float]:
    use = _eq14_norm(frame)
    if use.empty or len(use) <= periods:
        return None
    return _safe_float((use["value"].iloc[-1] / use["value"].iloc[-1-periods] - 1.0) * 100.0)


def _eq14_percentile(frame: Any, window: int = 756) -> pd.DataFrame:
    use = _eq14_norm(frame)
    if use.empty:
        return use
    minp = max(60, min(252, window // 3))
    p = use["value"].rolling(window, min_periods=minp).apply(lambda x: float(pd.Series(x).rank(pct=True).iloc[-1] * 100.0), raw=False)
    return pd.DataFrame({"date": use["date"], "value": p}).dropna().reset_index(drop=True)


def _eq14_current_percentile(frame: Any, window: int = 756) -> Optional[float]:
    p = _eq14_percentile(frame, window)
    return _eq14_latest(p)


def _eq14_ffill_to_daily(frame: Any, days: int = 370) -> pd.DataFrame:
    use = _eq14_norm(frame)
    if use.empty:
        return use
    idx = pd.date_range(use["date"].min(), use["date"].max(), freq="D")
    s = use.set_index("date")["value"].reindex(idx).ffill(limit=int(days))
    return pd.DataFrame({"date": s.index, "value": s.values}).dropna().reset_index(drop=True)


def _eq14_buffett(fred: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    cap = _eq14_norm(fred.get("BOGZ1LM883164105Q", pd.DataFrame())).rename(columns={"value": "cap_mn"})
    gdp = _eq14_norm(fred.get("GDP", pd.DataFrame())).rename(columns={"value": "gdp_bn"})
    if cap.empty or gdp.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(cap.sort_values("date"), gdp.sort_values("date"), on="date", direction="nearest", tolerance=pd.Timedelta(days=100))
    merged["value"] = (merged["cap_mn"] / 1000.0) / merged["gdp_bn"] * 100.0
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _eq14_earnings_yield(cape: Any) -> pd.DataFrame:
    use = _eq14_norm(cape)
    if use.empty:
        return use
    out = use.copy(); out["value"] = 100.0 / out["value"].replace(0, np.nan)
    return out.replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _eq14_erp(cape: Any, real_yield: Any) -> pd.DataFrame:
    ey = _eq14_ffill_to_daily(_eq14_earnings_yield(cape), 70).rename(columns={"value": "ey"})
    ry = _eq14_norm(real_yield).rename(columns={"value": "ry"})
    if ey.empty or ry.empty:
        return pd.DataFrame(columns=["date", "value"])
    ey["date"] = pd.to_datetime(ey["date"], errors="coerce").astype("datetime64[ns]")
    ry["date"] = pd.to_datetime(ry["date"], errors="coerce").astype("datetime64[ns]")
    merged = pd.merge_asof(ry.sort_values("date"), ey.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=70))
    merged["value"] = merged["ey"] - merged["ry"]
    return merged[["date", "value"]].dropna().reset_index(drop=True)


def _eq14_parse_shiller_excel(raw: bytes) -> pd.DataFrame:
    try:
        data = pd.read_excel(io.BytesIO(raw), sheet_name="Data", header=None)
    except Exception:
        data = pd.read_excel(io.BytesIO(raw), header=None)
    header_idx = None
    for i in range(min(25, len(data))):
        vals = [str(x).strip().lower() for x in data.iloc[i].tolist()]
        if "date" in vals and any("cape" in x for x in vals):
            header_idx = i; break
    if header_idx is None:
        raise ValueError("Shiller workbook header not found")
    headers = [str(x).strip() for x in data.iloc[header_idx].tolist()]
    body = data.iloc[header_idx+1:].copy(); body.columns = headers
    date_col = next((c for c in body.columns if str(c).strip().lower() == "date"), None)
    cape_col = next((c for c in body.columns if "cape" in str(c).lower() and "tr" not in str(c).lower()), None)
    if date_col is None or cape_col is None:
        raise ValueError("Shiller Date/CAPE columns not found")
    def parse_date(v: Any) -> pd.Timestamp:
        if isinstance(v, (pd.Timestamp, datetime)):
            return pd.Timestamp(v).tz_localize(None)
        try:
            x = float(v); year = int(x); month = int(round((x-year)*100)); month = max(1, min(12, month)); return pd.Timestamp(year=year, month=month, day=1)
        except Exception:
            return pd.to_datetime(v, errors="coerce")
    out = pd.DataFrame({"date": body[date_col].map(parse_date), "value": pd.to_numeric(body[cape_col], errors="coerce")})
    return _eq14_norm(out)


@st.cache_data(ttl=86400, show_spinner=False)
def _eq14_load_shiller(refresh_token: int = 0) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter(); cache = EQ14_CACHE_DIR / "shiller_cape.csv"
    force = bool(refresh_token)
    errors: List[str] = []
    if not force and cache.exists():
        try:
            frame = _eq14_norm(pd.read_csv(cache))
            if not frame.empty:
                latest = _eq14_latest_date(frame)
                q = pd.DataFrame([{"Series / Instrument": "SHILLER_CAPE", "Label": "Shiller CAPE Ratio", "Category": "Models", "Source": "Robert Shiller / Yale cache", "Status": "cache", "Freshness": _cr12_freshness(latest, 65), "Observations": len(frame), "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—", "Unit": "Ratio", "Frequency": "Monthly", "Message": "parsed disk cache"}])
                return frame, q, {"elapsed": time.perf_counter()-started, "provider": "Yale cache"}
        except Exception as exc:
            errors.append(str(exc))
    if REQUESTS_AVAILABLE:
        for url in EQ14_SHILLER_URLS:
            try:
                response = requests.get(url, timeout=(3.0, 12.0), headers={"User-Agent": "Mozilla/5.0 QuantTerminal/1.0"})
                response.raise_for_status()
                frame = _eq14_parse_shiller_excel(response.content)
                if frame.empty:
                    raise ValueError("empty Shiller dataset")
                frame.to_csv(cache, index=False)
                latest = _eq14_latest_date(frame)
                q = pd.DataFrame([{"Series / Instrument": "SHILLER_CAPE", "Label": "Shiller CAPE Ratio", "Category": "Models", "Source": "Robert Shiller / Yale", "Status": "live", "Freshness": _cr12_freshness(latest, 65), "Observations": len(frame), "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—", "Unit": "Ratio", "Frequency": "Monthly", "Message": "official workbook"}])
                return frame, q, {"elapsed": time.perf_counter()-started, "provider": "Yale"}
            except Exception as exc:
                errors.append(f"{url}: {exc}")
    if cache.exists():
        try:
            frame = _eq14_norm(pd.read_csv(cache)); latest = _eq14_latest_date(frame)
            q = pd.DataFrame([{"Series / Instrument": "SHILLER_CAPE", "Label": "Shiller CAPE Ratio", "Category": "Models", "Source": "Robert Shiller / Yale stale cache", "Status": "stale-cache", "Freshness": "Stale", "Observations": len(frame), "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—", "Unit": "Ratio", "Frequency": "Monthly", "Message": "; ".join(errors)[-240:]}])
            return frame, q, {"elapsed": time.perf_counter()-started, "provider": "Yale stale cache"}
        except Exception:
            pass
    q = pd.DataFrame([{"Series / Instrument": "SHILLER_CAPE", "Label": "Shiller CAPE Ratio", "Category": "Models", "Source": "Robert Shiller / Yale", "Status": "provider-unavailable", "Freshness": "Missing", "Observations": 0, "Latest Date": "—", "Unit": "Ratio", "Frequency": "Monthly", "Message": "; ".join(errors)[-240:]}])
    return pd.DataFrame(columns=["date", "value"]), q, {"elapsed": time.perf_counter()-started, "provider": "Yale unavailable"}


@st.cache_data(ttl=21600, show_spinner=False)
def _eq14_load_fred(series_ids: Tuple[str, ...], start_date: str = "1980-01-01", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    pack, quality, diag = _cr12_load_fred(tuple(series_ids), start_date, refresh_token)
    if quality is None: quality = pd.DataFrame()
    if not quality.empty:
        quality = quality.copy()
        for i, row in quality.iterrows():
            sid = str(row.get("Series / Instrument", "")); spec = EQ14_FRED_SERIES.get(sid, {})
            quality.at[i, "Label"] = spec.get("label", sid)
            quality.at[i, "Category"] = spec.get("family", "Equity Strategy")
            quality.at[i, "Unit"] = spec.get("unit", row.get("Unit", ""))
            quality.at[i, "Frequency"] = spec.get("frequency", row.get("Frequency", ""))
            latest = _eq14_latest_date(pack.get(sid, pd.DataFrame()))
            quality.at[i, "Freshness"] = _cr12_freshness(latest, int(spec.get("expected_days", 30))) if latest is not None else "Missing"
    return pack, quality, diag


@st.cache_data(ttl=21600, show_spinner=False)
def _eq14_load_market(symbols: Tuple[str, ...], period: str = "max", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    pack, quality, diag = _cr12_load_market(tuple(symbols), period, refresh_token)
    if quality is None: quality = pd.DataFrame()
    if not quality.empty:
        quality = quality.copy()
        for i, row in quality.iterrows():
            sym = str(row.get("Series / Instrument", "")); spec = EQ14_MARKET_SYMBOLS.get(sym, {})
            quality.at[i, "Label"] = spec.get("label", sym)
            quality.at[i, "Category"] = spec.get("family", "Equity Strategy")
    return pack, quality, diag


