def _eq14_market_index_card(title:str,subtitle:str,market:Mapping[str,pd.DataFrame],symbols:Sequence[str],smoothing:str)->None:
    _fi11_indexed_card(title,subtitle,[(s,market.get(s,pd.DataFrame())) for s in symbols],smoothing,"Yahoo/yfinance adjusted-price batch")


def _eq14_mixed_index_card(title:str,subtitle:str,fred:Mapping[str,pd.DataFrame],market:Mapping[str,pd.DataFrame],fred_ids:Sequence[str],symbols:Sequence[str],smoothing:str)->None:
    items=[(EQ14_FRED_SERIES.get(s,{}).get("label",s),fred.get(s,pd.DataFrame())) for s in fred_ids]+[(s,market.get(s,pd.DataFrame())) for s in symbols]
    _fi11_indexed_card(title,subtitle,items,smoothing,"FRED + Yahoo/yfinance")


def _eq14_risk_return(title:str,subtitle:str,market:Mapping[str,pd.DataFrame],symbols:Sequence[str])->None:
    rows=[]
    for sym in symbols:
        use=_eq14_norm(market.get(sym,pd.DataFrame()))
        if len(use)<70: continue
        s=use.set_index("date")["value"]; r=np.log(s/s.shift(1)); ret=(s.iloc[-1]/s.iloc[-253]-1)*100 if len(s)>=253 else np.nan; vol=r.tail(60).std(ddof=0)*math.sqrt(252)*100
        if np.isfinite(ret) and np.isfinite(vol): rows.append((sym,float(vol),float(ret)))
    if not rows:
        _liq5_render_chart_card(title,subtitle,None,[("Yahoo/yfinance batch","gold")],empty_message="Insufficient one-year history."); return
    fig=_eq14_base_figure("1Y return %",420)
    fig.add_trace(go.Scatter(x=[x[1] for x in rows],y=[x[2] for x in rows],mode="markers+text",text=[x[0] for x in rows],textposition="top center",marker=dict(size=13,color=list(EQ14_COLORS[:len(rows)])),hovertemplate="%{text}<br>60D vol %{x:.2f}%<br>1Y return %{y:.2f}%<extra></extra>"))
    fig.update_xaxes(title="60D annualized volatility %")
    _liq5_render_chart_card(title,subtitle,fig,[("Yahoo/yfinance batch","gold")],"Latest available inputs")


def _eq14_correlation(title:str,subtitle:str,market:Mapping[str,pd.DataFrame],symbols:Sequence[str])->None:
    cols=[]
    for sym in symbols:
        use=_eq14_norm(market.get(sym,pd.DataFrame()))
        if use.empty: continue
        cols.append(np.log(use.set_index("date")["value"]/use.set_index("date")["value"].shift(1)).rename(sym))
    if len(cols)<2:
        _liq5_render_chart_card(title,subtitle,None,[("Yahoo/yfinance batch","gold")],empty_message="Insufficient factor histories."); return
    panel=pd.concat(cols,axis=1).tail(252); corr=panel.corr()
    fig=go.Figure(go.Heatmap(z=corr.values,x=corr.columns,y=corr.index,zmin=-1,zmax=1,colorscale=[[0,"#9e4f48"],[.5,"#0b1723"],[1,"#4f9b6f"]],text=np.round(corr.values,2),texttemplate="%{text}",hovertemplate="%{y} / %{x}<br>%{z:.2f}<extra></extra>"))
    fig.update_layout(height=430,margin=dict(l=80,r=35,t=25,b=80),paper_bgcolor="#050c15",plot_bgcolor="#08131f",font=dict(color="#dce5ed",size=11))
    _liq5_render_chart_card(title,subtitle,fig,[("Daily returns · 1Y window","live"),("Yahoo/yfinance batch","gold")],"Latest available inputs")


def _eq14_render_spec(spec:Mapping[str,Any],fred:Mapping[str,pd.DataFrame],market:Mapping[str,pd.DataFrame],cape:pd.DataFrame,view_mode:str,smoothing:str)->None:
    title=f"{int(spec['n'])}. {spec['title']}"; subtitle=str(spec.get("subtitle","")); kind=str(spec.get("kind",""))
    if kind=="cape":
        _eq14_line_card(title,subtitle,[("Shiller CAPE",cape)],"Ratio","Robert Shiller / Yale","Levels",smoothing,allow_yoy=False,y_policy="positive")
    elif kind=="erp":
        frame=_eq14_erp(cape,fred.get("DFII10",pd.DataFrame())); _eq14_line_card(title,subtitle,[("Equity Risk Premium",frame)],"pp","Yale + FRED / Quant Terminal calculation","Levels",smoothing,allow_yoy=False,difference_like=True)
    elif kind=="fed_model":
        ey=_eq14_earnings_yield(cape); _eq14_line_card(title,subtitle,[("S&P earnings yield",ey),("US 10Y nominal yield",fred.get("DGS10",pd.DataFrame()))],"%","Yale + FRED","Levels",smoothing,allow_yoy=False,difference_like=True)
    elif kind=="buffett":
        frame=_eq14_buffett(fred); _eq14_line_card(title,subtitle,[("Market cap / GDP",frame)],"%","Federal Reserve Z.1 + BEA GDP via FRED","Levels",smoothing,allow_yoy=False,y_policy="positive")
    elif kind=="fred":
        ids=tuple(spec.get("ids",())); items=[(EQ14_FRED_SERIES.get(s,{}).get("label",s),fred.get(s,pd.DataFrame())) for s in ids]; unit=EQ14_FRED_SERIES.get(ids[0],{}).get("unit","") if ids else ""
        _eq14_line_card(title,subtitle,items,unit,"FRED / public data",view_mode,smoothing,difference_like=bool(spec.get("zero",False)),allow_yoy=True)
    elif kind=="fred_dual":
        left=tuple(spec.get("left",())); right=tuple(spec.get("right",())); items=[(EQ14_FRED_SERIES.get(s,{}).get("label",s),fred.get(s,pd.DataFrame())) for s in left+right]; rlabels=[EQ14_FRED_SERIES.get(s,{}).get("label",s) for s in right]
        _eq14_line_card(title,subtitle,items,EQ14_FRED_SERIES.get(left[0],{}).get("unit","") if left else "","FRED / public data","Levels",smoothing,allow_yoy=False,second_axis=rlabels,right_title=str(spec.get("right_title","Secondary")),difference_like=True)
    elif kind=="yoy":
        sid=str(spec.get("id")); frame=_eq14_yoy(fred.get(sid,pd.DataFrame())); _eq14_line_card(title,subtitle,[(f"{EQ14_FRED_SERIES.get(sid,{}).get('label',sid)} YoY",frame)],"%","FRED / Quant Terminal calendar-year transformation","Levels",smoothing,allow_yoy=False,difference_like=True)
    elif kind=="market":
        syms=tuple(spec.get("symbols",())); items=[(s,market.get(s,pd.DataFrame())) for s in syms]; _eq14_line_card(title,subtitle,items,"Adjusted price","Yahoo/yfinance batch",view_mode,smoothing,allow_yoy=True,y_policy="positive")
    elif kind=="market_ratio":
        frame=_eq14_ratio(market.get(spec.get("a"),pd.DataFrame()),market.get(spec.get("b"),pd.DataFrame())); _eq14_line_card(title,subtitle,[(str(spec.get("label","Ratio")),frame)],"Ratio","Yahoo/yfinance batch","Levels",smoothing,allow_yoy=False,y_policy="positive")
    elif kind=="market_index":
        _eq14_market_index_card(title,subtitle,market,tuple(spec.get("symbols",())),smoothing)
    elif kind=="drawdown":
        frame=_eq14_drawdown(market.get(spec.get("symbol"),pd.DataFrame())); _eq14_line_card(title,subtitle,[(str(spec.get("symbol")),frame)],"%","Yahoo/yfinance batch","Levels",smoothing,allow_yoy=False,difference_like=True)
    elif kind=="realized_vol":
        sym=str(spec.get("symbol")); items=[(f"{w}D realized vol",_eq14_vol(market.get(sym,pd.DataFrame()),int(w))) for w in tuple(spec.get("windows",(20,60)))]; _eq14_line_card(title,subtitle,items,"% annualized","Yahoo/yfinance batch","Levels",smoothing,allow_yoy=False,y_policy="positive")
    elif kind=="risk_return":
        _eq14_risk_return(title,subtitle,market,tuple(spec.get("symbols",())))
    elif kind=="correlation":
        _eq14_correlation(title,subtitle,market,tuple(spec.get("symbols",())))
    elif kind=="market_dual":
        left=tuple(spec.get("left",())); right=tuple(spec.get("right",())); items=[(s,market.get(s,pd.DataFrame())) for s in left+right]
        _eq14_line_card(title,subtitle,items,"Market level","Yahoo/yfinance batch","Levels",smoothing,allow_yoy=False,second_axis=list(right),right_title=str(spec.get("right_title","Secondary")),y_policy="positive",y2_policy="positive")
    elif kind=="mixed_index":
        _eq14_mixed_index_card(title,subtitle,fred,market,tuple(spec.get("fred",())),tuple(spec.get("market",())),smoothing)


def _eq14_kpis(cape:pd.DataFrame,fred:Mapping[str,pd.DataFrame],market:Mapping[str,pd.DataFrame])->None:
    reg=_eq14_regime(cape,fred,market); breadth=_eq14_latest(reg["breadth"]); cyc=_eq14_latest(reg["cyc"]); erp=_eq14_latest(reg["erp"])
    leader="—"; best=-1e9
    for name,sym in EQ14_FACTOR_MAP:
        v=_eq14_return(market.get(sym,pd.DataFrame()),63); b=_eq14_return(market.get("SPY",pd.DataFrame()),63)
        if v is not None and b is not None and v-b>best: leader=name; best=v-b
    cards=[
        _kpi_card("Shiller CAPE",_fmt(_eq14_latest(cape),1),"Long-run valuation"),
        _kpi_card("Equity risk premium",_fmt(erp,2," pp"),"1/CAPE minus 10Y real"),
        _kpi_card("Breadth RSP/SPY",_fmt(breadth,3),"Equal-weight leadership"),
        _kpi_card("Cyclical XLY/XLP",_fmt(cyc,3),"Risk-on rotation"),
        _kpi_card("3M factor leader",leader,f"{best:+.1f}% vs SPY" if best>-1e8 else "Insufficient data"),
        _kpi_card("VIX",_fmt(_eq14_latest(market.get("^VIX",pd.DataFrame())),1),"Equity-implied volatility"),
        _kpi_card("10Y real yield",_fmt(_eq14_latest(fred.get("DFII10",pd.DataFrame())),2,"%"),"Discount-rate pressure"),
        _kpi_card("Equity regime",reg["label"],f"Score {reg['score'] if reg['score'] is not None else '—'} · coverage {reg['coverage']}/7"),
    ]
    _html('<div class="mk-kpis">'+''.join(cards)+'</div>')


def _eq14_dashboard(cape:pd.DataFrame,fred:Mapping[str,pd.DataFrame],market:Mapping[str,pd.DataFrame],view_mode:str,smoothing:str)->None:
    relative=st.segmented_control("Factor matrix view",["vs S&P 500","Absolute Return"],key="market_eq14_factor_matrix_view",default="vs S&P 500")!="Absolute Return"
    _html('<div class="eq14-group">FACTOR STRATEGY</div><div class="eq14-title">Style-Factor Rotation Matrix</div><div class="eq14-sub">Trailing returns for Value, Growth, Small Cap, Low Vol, Momentum and Quality across 1M, 3M, 6M and 12M windows.</div>')
    _eq14_rotation_matrix(market,relative)
    _html('<div class="eq14-note">Relative return = factor return minus SPY return over the same observation window. Positive values indicate outperformance. Yahoo/yfinance adjusted-price proxies.</div>')
    key_specs=[EQ14_CHARTS[i-1] for i in (1,2,9,10)]
    _liq6_two_column([lambda spec=spec:_eq14_render_spec(spec,fred,market,cape,view_mode,smoothing) for spec in key_specs])
    reg=_eq14_regime(cape,fred,market)
    rows=pd.DataFrame([{"Component":n,"Stress percentile":round(v,1) if v is not None else np.nan,"Weight":f"{w:.0%}","Available":a} for n,v,w,a in reg["components"]])
    _liq5_table_card("Equity Regime Composition","Transparent public-data score; missing inputs are excluded and weights are renormalized.",rows,[(f"{reg['label']} · {reg['score'] if reg['score'] is not None else '—'}","live"),("Not an automatic recommendation","gold")],f"Coverage {reg['coverage']}/7",20)


