def _eq14_quality(quality:pd.DataFrame,diagnostics:Mapping[str,Any])->None:
    quality=quality if isinstance(quality,pd.DataFrame) else pd.DataFrame()
    loaded=int((~quality.get("Freshness",pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh=int(quality.get("Freshness",pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged=int(quality.get("Freshness",pd.Series(dtype=str)).astype(str).isin(["Lagged","Stale"]).sum()) if not quality.empty else 0
    dates=pd.to_datetime(quality.get("Latest Date",pd.Series(dtype=str)),errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    _html('<div class="mk-kpis">'+''.join([_kpi_card("Series loaded",f"{loaded}/{len(quality)}","Full Equity Strategy audit"),_kpi_card("Fresh rows",str(fresh),"Source-specific tolerances"),_kpi_card("Lagged / stale",str(lagged),"Visible; never silently imputed"),_kpi_card("Latest observation",_liq5_fmt_date(dates.max()),f"Wall load {diagnostics.get('elapsed',0):.1f}s")])+'</div>')
    _liq5_table_card("Equity Strategy Series Registry","Yale valuation data, FRED public macro/rates and market proxies.",quality,[("Public / market lineage","gold")],"Current full audit",250)
    contract=pd.DataFrame([
        {"Layer":"CAPE / earnings yield","Primary source":"Robert Shiller / Yale official workbook","Fallback":"Fresh or stale parsed disk cache","Rule":"No synthetic CAPE; monthly native history retained"},
        {"Layer":"Valuation / Buffett","Primary source":"Federal Reserve Z.1 + BEA GDP via FRED","Fallback":"Disk cache","Rule":"Quarterly native frequency; market value converted from USD mn"},
        {"Layer":"Rates / credit / macro","Primary source":"FRED public series","Fallback":"Disk cache","Rule":"No forward-looking interpolation"},
        {"Layer":"Equity / factor / sector ETFs","Primary source":"Yahoo/yfinance adjusted-price batch","Fallback":"Disk cache","Rule":"Tradable proxy, not a proprietary factor index"},
        {"Layer":"Factor rotation","Primary source":"Observed ETF returns","Fallback":"Unavailable","Rule":"Relative = ETF return − SPY return over identical window"},
        {"Layer":"Earnings revisions","Primary source":"Licensed point-in-time analyst-estimate provider","Fallback":"Provider-required","Rule":"No fabricated or survivorship-biased revision history"},
        {"Layer":"Regime composite","Primary source":"Transparent public-data percentiles","Fallback":"Unavailable if insufficient coverage","Rule":"Weights renormalized over real available inputs"},
    ])
    _liq5_table_card("Equity Strategy Provider Contract","Frozen source, frequency and modelling rules.",contract,[("No silent synthetic production history","live")],EQ14_VERSION,50)
    registry=pd.DataFrame([{"Order":x["n"],"Family":x["family"],"Title":x["title"],"Kind":x["kind"],"Status":"Public RoboMacro parity verified" if int(x["n"])<=10 else "Institutional extension tested"} for x in EQ14_CHARTS])
    _liq5_table_card("Equity Strategy Chart Registry","The ten public RoboMacro chart definitions are separated from 36 tested institutional extensions.",registry,[(f"{len(EQ14_CHARTS)} charts","gold")],"10 public parity charts + 36 extensions",100)
    st.download_button("Download Equity Strategy data-quality registry",data=quality.to_csv(index=False).encode("utf-8"),file_name="marketdesk_equity_strategy_quality_v14.csv",mime="text/csv",key="market_eq14_download_quality")


def _render_equity_strategy_page(ticker:str,price_data:pd.DataFrame,analysis:Optional[dict])->None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css(); _eq14_css()
    view=st.segmented_control("Equity Strategy research view",EQ14_VIEW_OPTIONS,key="market_eq14_view",label_visibility="collapsed") or "Dashboard"
    _eq14_header(view)
    controls=st.columns([1.05,1.0,1.05,.75],gap="medium")
    with controls[0]: view_mode=st.selectbox("View",["Levels","YoY %"],key="market_eq14_level_mode")
    with controls[1]: smoothing=st.selectbox("Smoothing",["Raw","7D","28D"],key="market_eq14_smoothing")
    family_filter="All"
    with controls[2]:
        if view=="Chart Book": family_filter=st.selectbox("Research family",["All"]+list(EQ14_FAMILIES),key="market_eq14_family_filter")
        else: st.caption("Only the active Equity Strategy route is loaded.")
    with controls[3]: refresh=st.button("Refresh",key="market_eq14_refresh",width="stretch")
    if refresh:
        st.session_state["market_eq14_refresh_nonce"]=int(st.session_state.get("market_eq14_refresh_nonce",0))+1; st.rerun()
    nonce=int(st.session_state.get("market_eq14_refresh_nonce",0)); fred_ids,symbols,need_shiller=_eq14_required(view,family_filter)
    started=time.perf_counter()
    with st.spinner("Loading Equity Strategy — bounded public providers..."):
        with _eq14_ThreadPoolExecutor(max_workers=3) as ex:
            f_fred=ex.submit(_eq14_load_fred,fred_ids,"1870-01-01",nonce)
            f_market=ex.submit(_eq14_load_market,symbols,"max",nonce)
            f_shiller=ex.submit(_eq14_load_shiller,nonce) if need_shiller or view in {"Dashboard","Regime","Data Quality"} else None
            fred,q_fred,d_fred=f_fred.result(); market,q_market,d_market=f_market.result()
            if f_shiller is not None: cape,q_shiller,d_shiller=f_shiller.result()
            else: cape=pd.DataFrame(columns=["date","value"]); q_shiller=pd.DataFrame(); d_shiller={"provider":"not-requested","elapsed":0.0}
    elapsed=time.perf_counter()-started
    parts=[q for q in (q_fred,q_market,q_shiller) if isinstance(q,pd.DataFrame) and not q.empty]; quality=pd.concat(parts,ignore_index=True) if parts else pd.DataFrame()
    _eq14_kpis(cape,fred,market)
    _html(f'<div class="eq14-note"><b>{_escape(EQ14_VERSION)}</b> · Wall load {elapsed:.1f}s · FRED {_escape(str(d_fred.get("provider","FRED")))} · Market {_escape(str(d_market.get("provider","market")))} · CAPE {_escape(str(d_shiller.get("provider","not requested")))} · active route {_escape(view)}.</div>')
    try:
        if view=="Dashboard": _eq14_dashboard(cape,fred,market,view_mode,smoothing)
        elif view in EQ14_FAMILIES: _eq14_family_view(view,fred,market,cape,view_mode,smoothing)
        elif view=="Regime": _eq14_regime_view(cape,fred,market,smoothing)
        elif view=="Chart Book": _eq14_chart_book(cape,fred,market,family_filter,view_mode,smoothing)
        else: _eq14_quality(quality,{"elapsed":elapsed,"fred":d_fred,"market":d_market,"shiller":d_shiller})
    except Exception as exc:
        st.error(f"Equity Strategy route failed: {type(exc).__name__}: {exc}")
        with st.expander("Equity Strategy traceback",expanded=False):
            import traceback as _eq14_traceback
            st.code(_eq14_traceback.format_exc())


