def _eq15_parse_multpl_html(raw: bytes) -> pd.DataFrame:
    """Parse Multpl's public monthly CAPE table without requiring lxml/xlrd."""
    text = raw.decode("utf-8", errors="ignore")
    rows: List[Tuple[pd.Timestamp, float]] = []
    # First try HTML tables. This path is robust when pandas/lxml is present.
    try:
        for table in pd.read_html(io.StringIO(text)):
            cols = [str(c).strip().lower() for c in table.columns]
            if "date" in cols and "value" in cols:
                dcol = table.columns[cols.index("date")]
                vcol = table.columns[cols.index("value")]
                for d, v in zip(table[dcol], table[vcol]):
                    dt = pd.to_datetime(d, errors="coerce")
                    val = pd.to_numeric(v, errors="coerce")
                    if pd.notna(dt) and pd.notna(val):
                        rows.append((pd.Timestamp(dt).tz_localize(None), float(val)))
                if rows:
                    break
    except Exception:
        pass
    # Fallback to the simple two-cell row structure used by the site.
    if not rows:
        cell_re = _eq15_re.compile(r"<td[^>]*>(.*?)</td>\s*<td[^>]*>(.*?)</td>", _eq15_re.I | _eq15_re.S)
        strip_re = _eq15_re.compile(r"<[^>]+>")
        for a, b in cell_re.findall(text):
            d = strip_re.sub("", a).replace("&nbsp;", " ").strip()
            v = strip_re.sub("", b).replace("&nbsp;", " ").replace(",", "").strip()
            dt = pd.to_datetime(d, errors="coerce")
            val = pd.to_numeric(v, errors="coerce")
            if pd.notna(dt) and pd.notna(val):
                rows.append((pd.Timestamp(dt).tz_localize(None), float(val)))
    if not rows:
        raise ValueError("Multpl CAPE table could not be parsed")
    return _eq14_norm(pd.DataFrame(rows, columns=["date", "value"]))


def _eq15_parse_in2013_html(raw: bytes) -> pd.DataFrame:
    text = raw.decode("utf-8", errors="ignore")
    try:
        tables = pd.read_html(io.StringIO(text))
    except Exception as exc:
        raise ValueError(f"In2013Dollars CAPE tables unavailable: {exc}")
    for table in tables:
        flat = [str(c).strip().lower() for c in table.columns]
        if "year" in flat and "month" in flat and any("shiller" in c and "pe" in c for c in flat):
            ycol = table.columns[flat.index("year")]
            mcol = table.columns[flat.index("month")]
            pidx = next(i for i, c in enumerate(flat) if "shiller" in c and "pe" in c)
            pcol = table.columns[pidx]
            out = pd.DataFrame({
                "date": pd.to_datetime(
                    table[ycol].astype(str).str.replace(r"\.0$", "", regex=True)
                    + "-" + table[mcol].astype(str).str.replace(r"\.0$", "", regex=True)
                    + "-01",
                    errors="coerce",
                ),
                "value": pd.to_numeric(table[pcol], errors="coerce"),
            })
            out = _eq14_norm(out)
            if not out.empty:
                return out
    raise ValueError("In2013Dollars monthly CAPE table not found")


def _eq15_parse_datahub_cape(raw: bytes) -> pd.DataFrame:
    """Parse the public Shiller-derived DataHub CSV; PE10 zeros are missing, not observations."""
    table = pd.read_csv(io.BytesIO(raw))
    cmap = {str(c).strip().lower(): c for c in table.columns}
    if "date" not in cmap or "pe10" not in cmap:
        raise ValueError("DataHub CAPE schema missing Date/PE10")
    out = pd.DataFrame({
        "date": pd.to_datetime(table[cmap["date"]], errors="coerce"),
        "value": pd.to_numeric(table[cmap["pe10"]], errors="coerce"),
    })
    out = out[out["value"] > 0]
    out = _eq14_norm(out)
    if len(out) < 100:
        raise ValueError("DataHub CAPE history is insufficient")
    return out


def _eq15_parse_current_cape(raw: bytes, kind: str) -> Tuple[pd.Timestamp, float]:
    """Extract one current public CAPE observation without inventing a date or value."""
    text = raw.decode("utf-8", errors="ignore")
    plain = _eq15_re.sub(r"<[^>]+>", " ", text)
    plain = _eq15_re.sub(r"\s+", " ", plain)
    if kind == "multpl_current":
        vm = _eq15_re.search(r"Current Shiller PE Ratio\s*:?\s*([0-9]+(?:\.[0-9]+)?)", plain, _eq15_re.I)
        dm = _eq15_re.search(r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)[a-z]*\s+([A-Z][a-z]{2}\s+\d{1,2})(?:,?\s*(\d{4}))?", plain)
        if vm:
            year = int(dm.group(2)) if dm and dm.group(2) else pd.Timestamp.utcnow().year
            dt = pd.to_datetime(f"{dm.group(1)} {year}", errors="coerce") if dm else pd.Timestamp.utcnow().normalize().tz_localize(None)
            if pd.notna(dt):
                return pd.Timestamp(dt).tz_localize(None), float(vm.group(1))
    elif kind == "gurufocus_current":
        vm = _eq15_re.search(r"(?:Last Value|currently)\s*([0-9]+(?:\.[0-9]+)?)", plain, _eq15_re.I)
        dm = _eq15_re.search(r"(?:As of|Latest Period)\s*(\d{4}-\d{2}(?:-\d{2})?)", plain, _eq15_re.I)
        if vm and dm:
            dt = pd.to_datetime(dm.group(1), errors="coerce")
            if pd.notna(dt):
                return pd.Timestamp(dt).tz_localize(None), float(vm.group(1))
    raise ValueError(f"Current CAPE snapshot could not be parsed from {kind}")


def _eq15_public_cape_bundle(headers: Mapping[str, str]) -> Tuple[pd.DataFrame, str]:
    """Independent CSV history plus a separately sourced current snapshot."""
    hist_r = requests.get(EQ15_CAPE_DATAHUB_URL, timeout=(3.0, 10.0), headers=dict(headers))
    hist_r.raise_for_status()
    history = _eq15_parse_datahub_cape(hist_r.content)
    snapshot_errors: List[str] = []
    for source, url, kind in EQ15_CAPE_SNAPSHOT_URLS:
        try:
            r = requests.get(url, timeout=(3.0, 10.0), headers=dict(headers))
            r.raise_for_status()
            dt, value = _eq15_parse_current_cape(r.content, kind)
            history = _eq14_norm(pd.concat([history, pd.DataFrame({"date": [dt], "value": [value]})], ignore_index=True))
            return history, f"DataHub Shiller history + {source}"
        except Exception as exc:
            snapshot_errors.append(f"{source}: {exc}")
    # Historical data are still useful, but their last date remains visible and may be stale.
    return history, "DataHub Shiller-derived historical CSV (current snapshot unavailable)"


@st.cache_data(ttl=86400, show_spinner=False)
def _eq15_load_cape(refresh_token: int = 0) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter()
    cache = EQ15_CACHE_DIR / "shiller_cape.csv"
    meta_cache = EQ15_CACHE_DIR / "shiller_cape_source.txt"
    force = bool(refresh_token)
    errors: List[str] = []

    def quality(frame: pd.DataFrame, source: str, status: str, message: str) -> pd.DataFrame:
        latest = _eq14_latest_date(frame)
        return pd.DataFrame([{
            "Series / Instrument": "SHILLER_CAPE",
            "Label": "Shiller CAPE Ratio",
            "Category": "Models",
            "Source": source,
            "Status": status,
            "Freshness": _cr12_freshness(latest, 45) if latest is not None else "Missing",
            "Observations": len(frame),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—",
            "Unit": "Ratio",
            "Frequency": "Monthly + current observation",
            "Message": message,
        }])

    if cache.exists() and not force:
        try:
            frame = _eq14_norm(pd.read_csv(cache))
            if not frame.empty:
                source = meta_cache.read_text(encoding="utf-8").strip() if meta_cache.exists() else "Shiller CAPE disk cache"
                q = quality(frame, source, "cache", "parsed disk cache")
                latest = _eq14_latest_date(frame)
                # Cache is still acceptable even if monthly; a refresh button forces network.
                if latest is not None and (pd.Timestamp.utcnow().tz_localize(None) - latest).days <= 45:
                    return frame, q, {"elapsed": time.perf_counter() - started, "provider": source}
        except Exception as exc:
            errors.append(f"cache: {exc}")

    if REQUESTS_AVAILABLE:
        for source, url, kind in EQ15_CAPE_URLS:
            try:
                headers = {
                    "User-Agent": "Mozilla/5.0 (compatible; QuantTerminal/1.0; +research)",
                    "Accept": "text/html,application/xhtml+xml,application/vnd.ms-excel,text/csv,*/*",
                }
                response = requests.get(url, timeout=(3.0, 10.0), headers=headers)
                response.raise_for_status()
                if kind == "multpl":
                    frame = _eq15_parse_multpl_html(response.content)
                elif kind == "yale":
                    frame = _eq14_parse_shiller_excel(response.content)
                else:
                    frame = _eq15_parse_in2013_html(response.content)
                if frame.empty or len(frame) < 50:
                    raise ValueError("insufficient CAPE history")
                frame.to_csv(cache, index=False)
                meta_cache.write_text(source, encoding="utf-8")
                q = quality(frame, source, "live", "public Shiller-derived history; no synthetic backfill")
                return frame, q, {"elapsed": time.perf_counter() - started, "provider": source}
            except Exception as exc:
                errors.append(f"{source}: {exc}")
        # Dependency-light fallback: a public CSV for the long history plus a
        # separately parsed current public snapshot. No PE10 zeros are retained.
        try:
            headers = {
                "User-Agent": "Mozilla/5.0 (compatible; QuantTerminal/1.0; +research)",
                "Accept": "text/csv,text/html,*/*",
            }
            frame, source = _eq15_public_cape_bundle(headers)
            frame.to_csv(cache, index=False)
            meta_cache.write_text(source, encoding="utf-8")
            q = quality(frame, source, "live", "public Shiller-derived history; current snapshot appended only when parsed")
            return frame, q, {"elapsed": time.perf_counter() - started, "provider": source}
        except Exception as exc:
            errors.append(f"public CSV fallback: {exc}")

    if cache.exists():
        try:
            frame = _eq14_norm(pd.read_csv(cache))
            source = meta_cache.read_text(encoding="utf-8").strip() if meta_cache.exists() else "Shiller CAPE stale cache"
            q = quality(frame, source, "stale-cache", "; ".join(errors)[-300:])
            q.loc[:, "Freshness"] = "Stale"
            return frame, q, {"elapsed": time.perf_counter() - started, "provider": f"{source} stale cache"}
        except Exception as exc:
            errors.append(f"stale cache: {exc}")

    q = quality(pd.DataFrame(columns=["date", "value"]), "Shiller data providers", "provider-unavailable", "; ".join(errors)[-300:])
    return pd.DataFrame(columns=["date", "value"]), q, {"elapsed": time.perf_counter() - started, "provider": "CAPE unavailable"}


def _eq15_common_panel(a: Any, b: Any) -> pd.DataFrame:
    left = _eq14_norm(a).rename(columns={"value": "a"})
    right = _eq14_norm(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "a", "b"])
    # Market series share trading calendars; an inner merge guarantees identical endpoints.
    return left.merge(right, on="date", how="inner").dropna().sort_values("date").reset_index(drop=True)


def _eq15_window_return(frame: Any, months: int, end_date: Optional[pd.Timestamp] = None) -> Optional[float]:
    use = _eq14_norm(frame)
    if use.empty:
        return None
    if end_date is not None:
        use = use[use["date"] <= pd.Timestamp(end_date)]
    if len(use) < 2:
        return None
    end = pd.Timestamp(use["date"].iloc[-1])
    target = end - pd.DateOffset(months=int(months))
    prior = use[use["date"] <= target]
    if prior.empty:
        after = use[use["date"] >= target]
        if after.empty:
            return None
        start_row = after.iloc[0]
    else:
        start_row = prior.iloc[-1]
    if abs((pd.Timestamp(start_row["date"]) - target).days) > 12:
        return None
    start = _safe_float(start_row["value"])
    finish = _safe_float(use["value"].iloc[-1])
    if start is None or finish is None or start == 0:
        return None
    return (finish / start - 1.0) * 100.0


def _eq15_pair_returns(a: Any, b: Any, months: int) -> Tuple[Optional[float], Optional[float]]:
    panel = _eq15_common_panel(a, b)
    if panel.empty:
        return None, None
    end = pd.Timestamp(panel["date"].iloc[-1])
    target = end - pd.DateOffset(months=int(months))
    prior = panel[panel["date"] <= target]
    if prior.empty:
        after = panel[panel["date"] >= target]
        if after.empty:
            return None, None
        row = after.iloc[0]
    else:
        row = prior.iloc[-1]
    if abs((pd.Timestamp(row["date"]) - target).days) > 12:
        return None, None
    a0, b0 = _safe_float(row["a"]), _safe_float(row["b"])
    a1, b1 = _safe_float(panel["a"].iloc[-1]), _safe_float(panel["b"].iloc[-1])
    if None in (a0, b0, a1, b1) or a0 == 0 or b0 == 0:
        return None, None
    return (a1 / a0 - 1.0) * 100.0, (b1 / b0 - 1.0) * 100.0


def _eq15_relative_path(a: Any, b: Any, months: int = 3) -> pd.DataFrame:
    panel = _eq15_common_panel(a, b)
    if panel.empty:
        return pd.DataFrame(columns=["date", "value"])
    end = pd.Timestamp(panel["date"].iloc[-1])
    panel = panel[panel["date"] >= end - pd.DateOffset(months=int(months))].copy()
    if panel.empty:
        return pd.DataFrame(columns=["date", "value"])
    a0, b0 = panel["a"].iloc[0], panel["b"].iloc[0]
    if not np.isfinite(a0) or not np.isfinite(b0) or a0 == 0 or b0 == 0:
        return pd.DataFrame(columns=["date", "value"])
    panel["value"] = ((panel["a"] / a0) / (panel["b"] / b0) - 1.0) * 100.0
    return panel[["date", "value"]].dropna().reset_index(drop=True)


def _eq15_spark_svg(frame: Any, benchmark: Any = None) -> str:
    use = _eq15_relative_path(frame, benchmark, 3) if benchmark is not None else _eq14_norm(frame).tail(63)
    if len(use) < 3:
        return '<span style="color:#68798a">—</span>'
    vals = pd.to_numeric(use["value"], errors="coerce").dropna().to_numpy(dtype=float)
    if len(vals) < 3:
        return "—"
    lo, hi = float(np.nanmin(vals)), float(np.nanmax(vals)); span = hi - lo if hi > lo else 1.0
    xs = np.linspace(2, 108, len(vals)); ys = 25 - (vals - lo) / span * 22
    points = " ".join(f"{x:.1f},{y:.1f}" for x, y in zip(xs, ys))
    color = "#63d598" if vals[-1] >= vals[0] else "#ef826f"
    return f'<svg class="eq14-spark" viewBox="0 0 110 28"><polyline fill="none" stroke="{color}" stroke-width="2" points="{points}"/></svg>'


def _eq15_rotation_values(market: Mapping[str, pd.DataFrame], relative: bool) -> List[Dict[str, Any]]:
    bench = market.get("SPY", pd.DataFrame())
    rows: List[Dict[str, Any]] = []
    for name, sym in EQ14_FACTOR_MAP:
        vals: Dict[str, Optional[float]] = {}
        for label, months in EQ15_FACTOR_WINDOWS:
            if relative:
                rf, rb = _eq15_pair_returns(market.get(sym, pd.DataFrame()), bench, months)
                vals[label] = (rf - rb) if rf is not None and rb is not None else None
            else:
                vals[label] = _eq15_window_return(market.get(sym, pd.DataFrame()), months)
        rows.append({"name": name, "symbol": sym, "values": vals})
    return rows


def _eq15_rotation_matrix(market: Mapping[str, pd.DataFrame], relative: bool = True) -> None:
    headers = ["Factor", "ETF", "1M", "3M", "6M", "12M", "3M Trend"]
    rows = _eq15_rotation_values(market, relative)
    html = ['<table class="eq14-matrix"><thead><tr>'] + [f'<th>{_escape(h)}</th>' for h in headers] + ['</tr></thead><tbody>']
    for row in rows:
        html.append(f'<tr><td class="eq14-factor">{_escape(row["name"])}</td><td><span class="eq14-ticker">{_escape(row["symbol"])}</span></td>')
        for label, _months in EQ15_FACTOR_WINDOWS:
            v = row["values"].get(label)
            text = "—" if v is None else f"{v:+.1f}%"
            html.append(f'<td class="eq14-cell {_eq14_color_class(v)}">{text}</td>')
        spark = _eq15_spark_svg(market.get(row["symbol"], pd.DataFrame()), market.get("SPY", pd.DataFrame()) if relative else None)
        html.append(f'<td>{spark}</td></tr>')
    html.append('</tbody></table>')
    _html(''.join(html))


def _eq15_factor_table(market: Mapping[str, pd.DataFrame], relative: bool = True) -> pd.DataFrame:
    rows = []
    bench = market.get("SPY", pd.DataFrame())
    for name, sym in EQ14_FACTOR_MAP:
        row: Dict[str, Any] = {"Factor": name, "ETF": sym}
        for label, months in EQ15_FACTOR_WINDOWS:
            if relative:
                rf, rb = _eq15_pair_returns(market.get(sym, pd.DataFrame()), bench, months)
                value = (rf - rb) if rf is not None and rb is not None else None
            else:
                value = _eq15_window_return(market.get(sym, pd.DataFrame()), months)
            row[f"{label} %"] = round(value, 2) if value is not None else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def _eq15_buffett_official(fred: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    cap = _eq14_norm(fred.get("NCBEILQ027S", pd.DataFrame())).rename(columns={"value": "cap_mn"})
    gdp = _eq14_norm(fred.get("GDP", pd.DataFrame())).rename(columns={"value": "gdp_bn"})
    if cap.empty or gdp.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(cap.sort_values("date"), gdp.sort_values("date"), on="date", direction="nearest", tolerance=pd.Timedelta(days=110))
    merged["value"] = (merged["cap_mn"] / 1000.0) / merged["gdp_bn"] * 100.0
    return merged[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _eq15_buffett_nowcast(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    official = _eq15_buffett_official(fred).rename(columns={"value": "official_ratio"})
    spy = _eq14_norm(market.get("SPY", pd.DataFrame())).rename(columns={"value": "spy"})
    if official.empty:
        return pd.DataFrame(columns=["date", "value"])
    if spy.empty:
        return official.rename(columns={"official_ratio": "value"})[["date", "value"]]
    anchors = pd.merge_asof(
        official.sort_values("date"), spy.sort_values("date"), on="date",
        direction="nearest", tolerance=pd.Timedelta(days=12),
    ).rename(columns={"spy": "spy_anchor", "date": "anchor_date"})
    anchors = anchors.dropna(subset=["official_ratio", "spy_anchor"]).sort_values("anchor_date")
    if anchors.empty:
        return official.rename(columns={"official_ratio": "value"})[["date", "value"]]
    daily = pd.merge_asof(
        spy.sort_values("date"), anchors.sort_values("anchor_date"),
        left_on="date", right_on="anchor_date", direction="backward",
    )
    daily["value"] = daily["official_ratio"] * daily["spy"] / daily["spy_anchor"]
    daily = daily[["date", "value"]].replace([np.inf, -np.inf], np.nan).dropna()
    if daily.empty:
        return official.rename(columns={"official_ratio": "value"})[["date", "value"]]
    # RoboMacro labels the series monthly but exposes a current observation.
    monthly = daily.assign(month=daily["date"].dt.to_period("M")).groupby("month", as_index=False).tail(1)
    latest = daily.tail(1)
    return _eq14_norm(pd.concat([monthly[["date", "value"]], latest[["date", "value"]]], ignore_index=True))


def _eq15_earnings_yield(cape: Any) -> pd.DataFrame:
    return _eq14_earnings_yield(cape)


def _eq15_erp(cape: Any, real_yield: Any) -> pd.DataFrame:
    ey = _eq14_norm(_eq15_earnings_yield(cape)).rename(columns={"value": "ey"})
    ry = _eq14_norm(real_yield).rename(columns={"value": "ry"})
    if ey.empty or ry.empty:
        return pd.DataFrame(columns=["date", "value"])
    merged = pd.merge_asof(ry.sort_values("date"), ey.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=50))
    merged["value"] = merged["ey"] - merged["ry"]
    return merged[["date", "value"]].dropna().reset_index(drop=True)


def _eq15_fred_source(sid: str) -> str:
    if sid.startswith("BAML"):
        return "FRED / ICE BofA index data"
    if sid == "NFCI":
        return "Chicago Fed NFCI via FRED"
    if sid in {"DGS10", "DFII10", "T10YIE", "T10Y2Y"}:
        return "US Treasury / FRED public data"
    if sid == "NCBEILQ027S":
        return "Federal Reserve Z.1 via FRED"
    if sid == "GDP":
        return "BEA GDP via FRED"
    if sid == "USREC":
        return "NBER recession indicator via FRED"
    return "FRED public data"


def _eq15_market_label(symbol: str) -> str:
    if symbol == "^VIX": return "VIX"
    if symbol == "^MOVE": return "MOVE"
    if symbol == "JPY=X": return "USD/JPY"
    if symbol == "EURUSD=X": return "EUR/USD"
    return symbol


def _eq15_market_unit(symbols: Sequence[str]) -> str:
    if len(symbols) == 1 and symbols[0] in {"^VIX", "^MOVE"}:
        return "Index points"
    return "Adjusted price"


def _eq15_regime(cape: Any, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> Dict[str, Any]:
    erp = _eq15_erp(cape, fred.get("DFII10", pd.DataFrame()))
    breadth = _eq14_ratio(market.get("RSP", pd.DataFrame()), market.get("SPY", pd.DataFrame()))
    cyc = _eq14_ratio(market.get("XLY", pd.DataFrame()), market.get("XLP", pd.DataFrame()))
    vix = market.get("^VIX", pd.DataFrame()); nfci = fred.get("NFCI", pd.DataFrame())
    mom = _eq14_ratio(market.get("MTUM", pd.DataFrame()), market.get("SPY", pd.DataFrame()))
    comps = (
        ("CAPE valuation", _eq14_current_percentile(cape), .20, False),
        ("Equity risk premium", _eq14_current_percentile(erp), .20, True),
        ("Market breadth", _eq14_current_percentile(breadth), .15, True),
        ("Cyclical leadership", _eq14_current_percentile(cyc), .10, True),
        ("Financial conditions", _eq14_current_percentile(nfci), .15, False),
        ("VIX", _eq14_current_percentile(vix), .10, False),
        ("Momentum leadership", _eq14_current_percentile(mom), .10, True),
    )
    used = []
    for name, val, weight, reverse in comps:
        stress = (100.0 - val) if val is not None and reverse else val
        used.append((name, stress, weight, val is not None))
    available = [x for x in used if x[3]]
    denom = sum(x[2] for x in available)
    score = sum(float(x[1]) * x[2] for x in available) / denom if denom > 0 else None
    if score is None: label = "Unavailable"
    elif score < 30: label = "Risk-on"
    elif score < 55: label = "Balanced"
    elif score < 75: label = "Defensive"
    else: label = "Stress"
    return {
        "score": round(score, 1) if score is not None else None,
        "label": label,
        "coverage": len(available),
        "components": used,
        "erp": erp,
        "breadth": breadth,
        "cyc": cyc,
        "mom": mom,
    }


def _eq15_regime_history(cape: Any, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    raw = {
        "CAPE valuation": _eq14_percentile(cape),
        "ERP": _eq14_percentile(_eq15_erp(cape, fred.get("DFII10", pd.DataFrame()))),
        "Breadth": _eq14_percentile(_eq14_ratio(market.get("RSP", pd.DataFrame()), market.get("SPY", pd.DataFrame()))),
        "Cyclical": _eq14_percentile(_eq14_ratio(market.get("XLY", pd.DataFrame()), market.get("XLP", pd.DataFrame()))),
        "NFCI": _eq14_percentile(fred.get("NFCI", pd.DataFrame())),
        "VIX": _eq14_percentile(market.get("^VIX", pd.DataFrame())),
        "Momentum": _eq14_percentile(_eq14_ratio(market.get("MTUM", pd.DataFrame()), market.get("SPY", pd.DataFrame()))),
    }
    weights = {"CAPE valuation": .20, "ERP": .20, "Breadth": .15, "Cyclical": .10, "NFCI": .15, "VIX": .10, "Momentum": .10}
    reverse = {"ERP", "Breadth", "Cyclical", "Momentum"}
    series = []
    for name, frame in raw.items():
        use = _eq14_norm(frame)
        if use.empty: continue
        s = use.set_index("date")["value"].rename(name)
        if name in reverse: s = 100.0 - s
        series.append(s)
    if not series:
        return pd.DataFrame(columns=["date", "value"])
    panel = pd.concat(series, axis=1).sort_index().ffill(limit=45)
    num = pd.Series(0.0, index=panel.index); den = pd.Series(0.0, index=panel.index); count = pd.Series(0, index=panel.index)
    for col in panel.columns:
        w = weights[col]; mask = panel[col].notna()
        num.loc[mask] += panel.loc[mask, col] * w; den.loc[mask] += w; count.loc[mask] += 1
    score = (num / den.replace(0, np.nan)).where(count >= 4).clip(0, 100)
    return pd.DataFrame({"date": score.index, "value": score.values}).dropna().reset_index(drop=True)


def _eq15_requirements(specs: Sequence[Mapping[str, Any]]) -> Tuple[Tuple[str, ...], Tuple[str, ...], bool]:
    fred, market, shiller = _eq14_requirements(specs)
    f = list(fred); m = list(market)
    # Correct Buffett series requirement.
    if any(str(x.get("kind", "")) == "buffett" for x in specs):
        f = [x for x in f if x != "BOGZ1LM883164105Q"]
        f.extend(["NCBEILQ027S", "GDP"]); m.append("SPY")
    return tuple(dict.fromkeys(f)), tuple(dict.fromkeys(m)), shiller


def _eq15_required(view: str, family_filter: str) -> Tuple[Tuple[str, ...], Tuple[str, ...], bool]:
    if view == "Dashboard":
        specs = _eq14_specs_for_family("Models")[:10]
    elif view == "Regime":
        specs = []
    elif view == "Chart Book":
        specs_all = [dict(x) for x in EQ14_CHARTS if family_filter == "All" or x["family"] == family_filter]
        pages = max(1, int(math.ceil(len(specs_all) / EQ14_CHART_PAGE_SIZE)))
        current = max(1, min(int(st.session_state.get("market_eq14_chart_page", 1)), pages))
        specs = specs_all[(current - 1) * EQ14_CHART_PAGE_SIZE: current * EQ14_CHART_PAGE_SIZE]
    elif view == "Data Quality":
        specs = list(EQ14_CHARTS)
    elif view in EQ14_FAMILIES:
        specs = _eq14_specs_for_family(view)
    else:
        specs = []
    fred, market, shiller = _eq15_requirements(specs)
    f = list(fred); m = list(market)
    if view == "Data Quality":
        f = list(dict.fromkeys(list(EQ14_FRED_SERIES.keys()) + ["NCBEILQ027S"]))
        m = list(EQ14_MARKET_SYMBOLS.keys())
    # Route-invariant KPI/regime strip. Batch market loading makes this cheap.
    f.extend(EQ15_CORE_FRED); m.extend(EQ15_CORE_MARKET)
    return tuple(dict.fromkeys(f)), tuple(dict.fromkeys(m)), True


def _eq15_line_card(title: str, subtitle: str, items: Sequence[Tuple[str, pd.DataFrame]], unit: str, source: str, view_mode: str, smoothing: str, **kwargs: Any) -> None:
    _fi10_line_card(title, subtitle, items, unit, source, view_mode, smoothing, **kwargs)


def _eq15_render_spec(spec: Mapping[str, Any], fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cape: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    title = f"{int(spec['n'])}. {spec['title']}"; subtitle = str(spec.get("subtitle", "")); kind = str(spec.get("kind", ""))
    if kind == "cape":
        _eq15_line_card(title, subtitle, [("Shiller CAPE", cape)], "Ratio", "Robert Shiller data · Yale/Multpl public fallback", view_mode, smoothing, allow_yoy=True, y_policy="positive")
    elif kind == "erp":
        frame = _eq15_erp(cape, fred.get("DFII10", pd.DataFrame()))
        _eq15_line_card(title, subtitle, [("Equity Risk Premium", frame)], "pp", "Shiller CAPE + US 10Y real yield / transparent calculation", "Levels", smoothing, allow_yoy=False, difference_like=True)
    elif kind == "fed_model":
        ey = _eq15_earnings_yield(cape)
        _eq15_line_card(title, subtitle, [("S&P earnings yield", ey), ("US 10Y nominal yield", fred.get("DGS10", pd.DataFrame()))], "%", "Shiller CAPE + US Treasury / FRED", "Levels", smoothing, allow_yoy=False, y_policy="positive")
    elif kind == "buffett":
        frame = _eq15_buffett_nowcast(fred, market)
        _eq15_line_card(title, "Total market value / GDP; official quarterly anchor marked to market with SPY between releases.", [("Market cap / GDP", frame)], "%", "Federal Reserve Z.1 NCBEILQ027S + BEA GDP; transparent SPY nowcast", view_mode, smoothing, allow_yoy=True, y_policy="positive")
    elif kind == "fred":
        ids = tuple(spec.get("ids", ())); items = [(EQ14_FRED_SERIES.get(s, {}).get("label", s), fred.get(s, pd.DataFrame())) for s in ids]
        unit = EQ14_FRED_SERIES.get(ids[0], {}).get("unit", "") if ids else ""
        source = _eq15_fred_source(ids[0]) if len(ids) == 1 else "FRED public data"
        _eq15_line_card(title, subtitle, items, unit, source, view_mode, smoothing, difference_like=bool(spec.get("zero", False)), allow_yoy=True)
    elif kind == "fred_dual":
        left = tuple(spec.get("left", ())); right = tuple(spec.get("right", ()))
        items = [(EQ14_FRED_SERIES.get(s, {}).get("label", s), fred.get(s, pd.DataFrame())) for s in left + right]
        rlabels = [EQ14_FRED_SERIES.get(s, {}).get("label", s) for s in right]
        _eq15_line_card(title, subtitle, items, EQ14_FRED_SERIES.get(left[0], {}).get("unit", "") if left else "", "FRED public data", "Levels", smoothing, allow_yoy=False, second_axis=rlabels, right_title=str(spec.get("right_title", "Secondary")), difference_like=True)
    elif kind == "yoy":
        sid = str(spec.get("id")); frame = _eq14_yoy(fred.get(sid, pd.DataFrame()))
        _eq15_line_card(title, subtitle, [(f"{EQ14_FRED_SERIES.get(sid, {}).get('label', sid)} YoY", frame)], "%", f"{_eq15_fred_source(sid)} · calendar-year transformation", "Levels", smoothing, allow_yoy=False, difference_like=True)
    elif kind == "market":
        syms = tuple(spec.get("symbols", ())); items = [(_eq15_market_label(s), market.get(s, pd.DataFrame())) for s in syms]
        _eq15_line_card(title, subtitle, items, _eq15_market_unit(syms), "Yahoo/yfinance batch", view_mode, smoothing, allow_yoy=True, y_policy="positive")
    elif kind == "market_ratio":
        frame = _eq14_ratio(market.get(spec.get("a"), pd.DataFrame()), market.get(spec.get("b"), pd.DataFrame()))
        _eq15_line_card(title, subtitle, [(str(spec.get("label", "Ratio")), frame)], "Ratio", "Yahoo/yfinance adjusted-price batch", view_mode, smoothing, allow_yoy=True, y_policy="positive")
    elif kind == "market_index":
        _fi11_indexed_card(title, subtitle, [(_eq15_market_label(s), market.get(s, pd.DataFrame())) for s in tuple(spec.get("symbols", ()))], smoothing, "Yahoo/yfinance adjusted-price batch")
    elif kind == "drawdown":
        frame = _eq14_drawdown(market.get(spec.get("symbol"), pd.DataFrame()))
        _eq15_line_card(title, subtitle, [(str(spec.get("symbol")), frame)], "%", "Yahoo/yfinance adjusted-price batch", "Levels", smoothing, allow_yoy=False, difference_like=True)
    elif kind == "realized_vol":
        sym = str(spec.get("symbol")); items = [(f"{w}D realized vol", _eq14_vol(market.get(sym, pd.DataFrame()), int(w))) for w in tuple(spec.get("windows", (20, 60)))]
        _eq15_line_card(title, subtitle, items, "% annualized", "Yahoo/yfinance adjusted-price batch", "Levels", smoothing, allow_yoy=False, y_policy="positive")
    elif kind == "risk_return":
        _eq14_risk_return(title, subtitle, market, tuple(spec.get("symbols", ())))
    elif kind == "correlation":
        _eq14_correlation(title, subtitle, market, tuple(spec.get("symbols", ())))
    elif kind == "market_dual":
        left = tuple(spec.get("left", ())); right = tuple(spec.get("right", ()))
        items = [(_eq15_market_label(s), market.get(s, pd.DataFrame())) for s in left + right]
        rlabels = [_eq15_market_label(s) for s in right]
        _eq15_line_card(title, subtitle, items, "Market level", "Yahoo/yfinance batch", "Levels", smoothing, allow_yoy=False, second_axis=rlabels, right_title=str(spec.get("right_title", "Secondary")), y_policy="positive", y2_policy="positive")
    elif kind == "mixed_index":
        items = [(EQ14_FRED_SERIES.get(s, {}).get("label", s), fred.get(s, pd.DataFrame())) for s in tuple(spec.get("fred", ()))] + [(_eq15_market_label(s), market.get(s, pd.DataFrame())) for s in tuple(spec.get("market", ()))]
        _fi11_indexed_card(title, subtitle, items, smoothing, "FRED + Yahoo/yfinance; common-date indexation")


def _eq15_kpis(cape: pd.DataFrame, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> None:
    reg = _eq15_regime(cape, fred, market); breadth = _eq14_latest(reg["breadth"]); cyc = _eq14_latest(reg["cyc"]); erp = _eq14_latest(reg["erp"])
    leader = "—"; best: Optional[float] = None
    for name, sym in EQ14_FACTOR_MAP:
        rf, rb = _eq15_pair_returns(market.get(sym, pd.DataFrame()), market.get("SPY", pd.DataFrame()), 3)
        excess = (rf - rb) if rf is not None and rb is not None else None
        if excess is not None and (best is None or excess > best):
            leader, best = name, excess
    cards = [
        _kpi_card("Shiller CAPE", _fmt(_eq14_latest(cape), 1), "Long-run valuation"),
        _kpi_card("Equity risk premium", _fmt(erp, 2, " pp"), "1/CAPE minus 10Y real"),
        _kpi_card("Breadth RSP/SPY", _fmt(breadth, 3), "Equal-weight leadership"),
        _kpi_card("Cyclical XLY/XLP", _fmt(cyc, 3), "Risk-on rotation"),
        _kpi_card("3M factor leader", leader, f"{best:+.1f}% vs SPY" if best is not None else "Insufficient data"),
        _kpi_card("VIX", _fmt(_eq14_latest(market.get("^VIX", pd.DataFrame())), 1), "Equity-implied volatility"),
        _kpi_card("10Y real yield", _fmt(_eq14_latest(fred.get("DFII10", pd.DataFrame())), 2, "%"), "Discount-rate pressure"),
        _kpi_card("Equity regime", reg["label"], f"Score {reg['score'] if reg['score'] is not None else '—'} · coverage {reg['coverage']}/7"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')


def _eq15_dashboard(cape: pd.DataFrame, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], view_mode: str, smoothing: str) -> None:
    mode = st.segmented_control("Factor matrix view", ["vs S&P 500", "Absolute Return"], key="market_eq15_factor_matrix_view", default="vs S&P 500") or "vs S&P 500"
    relative = mode == "vs S&P 500"
    _html('<div class="eq14-group">FACTOR STRATEGY</div><div class="eq14-title">Style-Factor Rotation Matrix</div><div class="eq14-sub">Trailing calendar returns for Value, Growth, Small Cap, Low Vol, Momentum and Quality across 1M, 3M, 6M and 12M windows.</div>')
    _eq15_rotation_matrix(market, relative)
    note = "Relative return = factor total return minus SPY total return, using identical common start/end dates." if relative else "Absolute return = each factor ETF total return over the same calendar window convention."
    _html(f'<div class="eq14-note">{_escape(note)} Yahoo/yfinance adjusted-price proxies; sparklines show the 3-month relative-return path.</div>')
    key_specs = [EQ14_CHARTS[i - 1] for i in (1, 2, 9, 10)]
    _liq6_two_column([lambda spec=spec: _eq15_render_spec(spec, fred, market, cape, view_mode, smoothing) for spec in key_specs])
    reg = _eq15_regime(cape, fred, market)
    rows = pd.DataFrame([{"Component": n, "Stress percentile": round(v, 1) if v is not None else np.nan, "Weight": f"{w:.0%}", "Available": "Yes" if a else "No"} for n, v, w, a in reg["components"]])
    _liq5_table_card("Equity Regime Composition", "Transparent seven-factor public-data score; missing inputs are excluded and weights are renormalized.", rows, [(f"{reg['label']} · {reg['score'] if reg['score'] is not None else '—'}", "live"), ("Not an automatic recommendation", "gold")], f"Coverage {reg['coverage']}/7", 20)


def _eq15_sector_table(market: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    rows = []; spy = market.get("SPY", pd.DataFrame())
    for name, sym in EQ14_SECTOR_MAP:
        r1, b1 = _eq15_pair_returns(market.get(sym, pd.DataFrame()), spy, 1)
        r3, b3 = _eq15_pair_returns(market.get(sym, pd.DataFrame()), spy, 3)
        r12 = _eq15_window_return(market.get(sym, pd.DataFrame()), 12)
        rows.append({
            "Sector": name, "ETF": sym,
            "1M vs SPY %": round(r1 - b1, 2) if r1 is not None and b1 is not None else np.nan,
            "3M vs SPY %": round(r3 - b3, 2) if r3 is not None and b3 is not None else np.nan,
            "12M return %": round(r12, 2) if r12 is not None else np.nan,
        })
    return pd.DataFrame(rows)


def _eq15_family_view(view: str, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cape: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    specs = _eq14_specs_for_family(view)
    _liq6_two_column([lambda spec=spec: _eq15_render_spec(spec, fred, market, cape, view_mode, smoothing) for spec in specs])
    if view == "Factors":
        df = _eq15_factor_table(market, True)
        _liq5_table_card("Style-Factor Rotation Monitor", "Calendar-aligned excess returns versus SPY across the same four windows.", df, [("Yahoo/yfinance batch", "gold")], "Latest common market observations", 20)
    elif view == "Equities":
        _liq5_table_card("US Sector Rotation Monitor", "Sector excess returns versus SPY and trailing absolute return; all windows use common calendar endpoints.", _eq15_sector_table(market), [("Yahoo/yfinance batch", "gold")], "Latest common market observations", 30)
    elif view == "Models":
        definitions = pd.DataFrame([
            {"Model": "Shiller CAPE", "Construction": "Price / 10Y average real earnings", "Interpretation": "Long-horizon valuation; not a timing signal"},
            {"Model": "Equity Risk Premium", "Construction": "100/CAPE − 10Y real yield", "Interpretation": "Positive = equity earnings yield exceeds real discount rate"},
            {"Model": "Yield Gap / Fed Model", "Construction": "100/CAPE and 10Y nominal yield", "Interpretation": "Two-line comparison; not a structural fair-value equation"},
            {"Model": "Buffett Indicator", "Construction": "NCBEILQ027S / nominal GDP; SPY mark-to-market between quarterly releases", "Interpretation": "Transparent current estimate anchored to official Z.1 data"},
        ])
        _liq5_table_card("Model Construction Rules", "Definitions, sources and limitations are explicit; no model is presented as an automatic trade signal.", definitions, [("Transparent methodology", "gold")], EQ15_VERSION, 20)


def _eq15_regime_view(cape: pd.DataFrame, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], smoothing: str) -> None:
    reg = _eq15_regime(cape, fred, market); hist = _eq15_regime_history(cape, fred, market)
    _eq15_line_card("Equity Strategy Regime Composite", "Weighted stress percentile. Risk-on <30, Balanced 30–55, Defensive 55–75, Stress >75.", [("Stress score", hist)], "Score", "Quant Terminal transparent methodology", "Levels", smoothing, allow_yoy=False, y_policy="positive")
    labels, vals = [], []
    for name, val, _w, available in reg["components"]:
        if available and val is not None:
            labels.append(name); vals.append(float(val))
    if vals:
        fig = go.Figure(go.Heatmap(z=[vals], x=labels, y=["Current"], zmin=0, zmax=100, colorscale=[[0, "#4f9b6f"], [.5, "#d9bf58"], [1, "#9e4f48"]], text=[[f"{v:.0f}" for v in vals]], texttemplate="%{text}", hovertemplate="%{x}<br>Stress %{z:.0f}<extra></extra>"))
        fig.update_layout(height=300, margin=dict(l=70, r=35, t=20, b=95), paper_bgcolor="#050c15", plot_bgcolor="#08131f", font=dict(color="#dce5ed", size=11))
        _liq5_render_chart_card("Current Equity Risk Matrix", "Cross-factor percentiles; green is benign and red is stressed.", fig, [(f"Composite {reg['score'] if reg['score'] is not None else '—'}", "live"), ("Not a trading recommendation", "gold")], "Latest available inputs")
    tasks = [
        lambda: _eq15_line_card("Breadth and Cyclical Leadership", "RSP/SPY and XLY/XLP on independent axes so neither signal is visually compressed.", [("RSP / SPY", reg["breadth"]), ("XLY / XLP", reg["cyc"])], "RSP / SPY", "Yahoo/yfinance batch", "Levels", smoothing, allow_yoy=False, second_axis=["XLY / XLP"], right_title="XLY / XLP", y_policy="positive", y2_policy="positive"),
        lambda: _eq15_line_card("Valuation and Discount Rate", "Equity risk premium and 10Y real yield on independent axes.", [("Equity risk premium", reg["erp"]), ("10Y real yield", fred.get("DFII10", pd.DataFrame()))], "ERP pp", "Shiller CAPE + US Treasury / FRED", "Levels", smoothing, allow_yoy=False, second_axis=["10Y real yield"], right_title="Real yield %", difference_like=True),
    ]
    _liq6_two_column(tasks)
    rows = pd.DataFrame([{"Component": n, "Stress percentile": round(v, 1) if v is not None else np.nan, "Weight": f"{w:.0%}", "Available": "Yes" if a else "No"} for n, v, w, a in reg["components"]])
    _liq5_table_card("Regime Methodology", "The composite is descriptive and route-invariant; missing factors are not replaced by neutral values.", rows, [(f"{reg['label']} · {reg['score'] if reg['score'] is not None else '—'}", "live")], f"Coverage {reg['coverage']}/7", 20)


def _eq15_chart_book(cape: pd.DataFrame, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], family_filter: str, view_mode: str, smoothing: str) -> None:
    specs = [dict(x) for x in EQ14_CHARTS if family_filter == "All" or x["family"] == family_filter]
    pages = max(1, int(math.ceil(len(specs) / EQ14_CHART_PAGE_SIZE)))
    current = max(1, min(int(st.session_state.get("market_eq14_chart_page", 1)), pages))
    cols = st.columns([1, 2.1, 1], gap="medium")
    with cols[0]:
        if st.button("← Previous", key="market_eq15_prev", disabled=current <= 1, width="stretch"):
            st.session_state["market_eq14_chart_page"] = current - 1; st.rerun()
    with cols[1]:
        st.markdown(f"<div style='text-align:center;color:#aeb9c4;padding:.55rem'>Showing {(current-1)*EQ14_CHART_PAGE_SIZE+1}–{min(current*EQ14_CHART_PAGE_SIZE,len(specs))} of {len(specs)} charts · Page {current} of {pages}</div>", unsafe_allow_html=True)
    with cols[2]:
        if st.button("Next →", key="market_eq15_next", disabled=current >= pages, width="stretch"):
            st.session_state["market_eq14_chart_page"] = current + 1; st.rerun()
    page = specs[(current - 1) * EQ14_CHART_PAGE_SIZE: current * EQ14_CHART_PAGE_SIZE]
    _liq6_two_column([lambda spec=spec: _eq15_render_spec(spec, fred, market, cape, view_mode, smoothing) for spec in page])


def _eq15_quality(quality: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    quality = quality if isinstance(quality, pd.DataFrame) else pd.DataFrame()
    loaded = int((~quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).isin(["Lagged", "Stale"]).sum()) if not quality.empty else 0
    dates = pd.to_datetime(quality.get("Latest Date", pd.Series(dtype=str)), errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    _html('<div class="mk-kpis">' + ''.join([
        _kpi_card("Series loaded", f"{loaded}/{len(quality)}", "Full Equity Strategy audit"),
        _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"),
        _kpi_card("Lagged / stale", str(lagged), "Visible; never silently imputed"),
        _kpi_card("Latest observation", _liq5_fmt_date(dates.max()), f"Wall load {diagnostics.get('elapsed', 0):.1f}s"),
    ]) + '</div>')
    _liq5_table_card("Equity Strategy Series Registry", "CAPE, FRED macro/rates and market proxies with explicit source and freshness.", quality, [("Public / market lineage", "gold")], "Current full audit", 260)
    contract = pd.DataFrame([
        {"Layer": "CAPE / earnings yield", "Primary source": "Robert Shiller data; Multpl public table preferred for current compatibility", "Fallback": "Yale workbook / In2013Dollars / disk cache", "Rule": "No fabricated history; source is visible"},
        {"Layer": "Buffett indicator", "Primary source": "NCBEILQ027S + GDP via FRED", "Fallback": "Disk cache", "Rule": "Official quarterly anchor; SPY mark-to-market is explicitly labelled"},
        {"Layer": "Rates / credit / macro", "Primary source": "FRED public series", "Fallback": "Disk cache", "Rule": "No forward-looking interpolation"},
        {"Layer": "Equity / factor / sector ETFs", "Primary source": "Yahoo/yfinance adjusted-price batch", "Fallback": "Disk cache", "Rule": "Calendar windows use common endpoints"},
        {"Layer": "Factor rotation", "Primary source": "Observed ETF total returns", "Fallback": "Unavailable", "Rule": "Relative = factor − SPY over identical dates"},
        {"Layer": "Earnings revisions", "Primary source": "Licensed point-in-time analyst-estimate provider", "Fallback": "Provider-required", "Rule": "No fabricated or survivorship-biased revision history"},
        {"Layer": "Regime composite", "Primary source": "Seven transparent public-data percentiles", "Fallback": "Unavailable if insufficient coverage", "Rule": "Identical core inputs on every route"},
    ])
    _liq5_table_card("Equity Strategy Provider Contract", "Frozen source, frequency and modelling rules.", contract, [("No silent synthetic production history", "live")], EQ15_VERSION, 50)
    registry = pd.DataFrame([{
        "Order": x["n"], "Family": x["family"], "Title": x["title"], "Kind": x["kind"],
        "Status": "Public RoboMacro parity verified" if int(x["n"]) <= 10 else "Institutional extension — data/design tested",
    } for x in EQ14_CHARTS])
    _liq5_table_card("Equity Strategy Chart Registry", "The public factor matrix and charts 1–10 are parity-checked; charts 11–46 are tested institutional extensions within the public families.", registry, [(f"{len(EQ14_CHARTS)} charts", "gold")], "10 public parity charts + 36 extensions", 110)
    st.download_button("Download Equity Strategy data-quality registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_equity_strategy_quality_v15.csv", mime="text/csv", key="market_eq15_download_quality")


def _render_equity_strategy_page_v15(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css(); _eq14_css()
    view = st.segmented_control("Equity Strategy research view", EQ14_VIEW_OPTIONS, key="market_eq14_view", label_visibility="collapsed") or "Dashboard"
    _eq14_header(view)
    controls = st.columns([1.05, 1.0, 1.05, .75], gap="medium")
    with controls[0]: view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_eq14_level_mode")
    with controls[1]: smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_eq14_smoothing")
    family_filter = "All"
    with controls[2]:
        if view == "Chart Book":
            family_filter = st.selectbox("Research family", ["All"] + list(EQ14_FAMILIES), key="market_eq14_family_filter")
        else:
            st.caption("Only the active Equity Strategy route is loaded.")
    with controls[3]: refresh = st.button("Refresh", key="market_eq15_refresh", width="stretch")
    if refresh:
        st.session_state["market_eq15_refresh_nonce"] = int(st.session_state.get("market_eq15_refresh_nonce", 0)) + 1; st.rerun()
    nonce = int(st.session_state.get("market_eq15_refresh_nonce", 0))
    fred_ids, symbols, _need_shiller = _eq15_required(view, family_filter)
    started = time.perf_counter()
    with st.spinner("Loading Equity Strategy — bounded public providers..."):
        with _eq15_ThreadPoolExecutor(max_workers=3) as ex:
            f_fred = ex.submit(_eq14_load_fred, fred_ids, "1870-01-01", nonce)
            f_market = ex.submit(_eq14_load_market, symbols, "max", nonce)
            f_cape = ex.submit(_eq15_load_cape, nonce)
            fred, q_fred, d_fred = f_fred.result(); market, q_market, d_market = f_market.result(); cape, q_cape, d_cape = f_cape.result()
    elapsed = time.perf_counter() - started
    parts = [q for q in (q_fred, q_market, q_cape) if isinstance(q, pd.DataFrame) and not q.empty]
    quality = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    _eq15_kpis(cape, fred, market)
    _html(f'<div class="eq14-note"><b>{_escape(EQ15_VERSION)}</b> · Wall load {elapsed:.1f}s · FRED {_escape(str(d_fred.get("provider", "FRED")))} · Market {_escape(str(d_market.get("provider", "market")))} · CAPE {_escape(str(d_cape.get("provider", "CAPE")))} · active route {_escape(view)}.</div>')
    try:
        if view == "Dashboard": _eq15_dashboard(cape, fred, market, view_mode, smoothing)
        elif view in EQ14_FAMILIES: _eq15_family_view(view, fred, market, cape, view_mode, smoothing)
        elif view == "Regime": _eq15_regime_view(cape, fred, market, smoothing)
        elif view == "Chart Book": _eq15_chart_book(cape, fred, market, family_filter, view_mode, smoothing)
        else: _eq15_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market, "cape": d_cape})
    except Exception as exc:
        st.error(f"Equity Strategy route failed: {type(exc).__name__}: {exc}")
        with st.expander("Equity Strategy traceback", expanded=False):
            import traceback as _eq15_traceback
            st.code(_eq15_traceback.format_exc())


