def _eq16_chart_book(cape: pd.DataFrame, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], origin_filter: str, family_filter: str, view_mode: str, smoothing: str) -> None:
    specs = _eq16_specs(origin_filter, family_filter)
    pages = max(1, int(math.ceil(len(specs) / EQ16_PAGE_SIZE)))
    current = max(1, min(int(st.session_state.get("market_eq16_chart_page", 1)), pages))
    cols = st.columns([1, 2.2, 1], gap="medium")
    with cols[0]:
        if st.button("← Previous", key="market_eq16_prev", disabled=current <= 1, width="stretch"):
            st.session_state["market_eq16_chart_page"] = current - 1; st.rerun()
    with cols[1]:
        start = 0 if not specs else (current - 1) * EQ16_PAGE_SIZE + 1
        end = min(current * EQ16_PAGE_SIZE, len(specs))
        st.markdown(f"<div style='text-align:center;color:#aeb9c4;padding:.55rem'>Showing {start}–{end} of {len(specs)} charts · Page {current} of {pages}</div>", unsafe_allow_html=True)
    with cols[2]:
        if st.button("Next →", key="market_eq16_next", disabled=current >= pages, width="stretch"):
            st.session_state["market_eq16_chart_page"] = current + 1; st.rerun()
    page = specs[(current - 1) * EQ16_PAGE_SIZE: current * EQ16_PAGE_SIZE]
    _liq6_two_column([lambda spec=spec: _eq16_render_spec(spec, fred, market, cape, view_mode, smoothing) for spec in page])


def _eq16_chart_registry() -> pd.DataFrame:
    rows = []
    for spec in EQ16_ALL_CHARTS:
        rows.append({
            "Order": int(spec["n"]), "Origin": spec.get("origin", ""), "Family": spec.get("family", ""),
            "Title": spec.get("title", ""), "Kind": spec.get("kind", ""),
            "Frequency": spec.get("frequency", ""), "Series": int(spec.get("series_count", 0)),
            "Parity status": spec.get("parity", ""),
        })
    return pd.DataFrame(rows)


def _eq16_audit_checks() -> pd.DataFrame:
    registry = _eq16_chart_registry()
    versus = registry[registry["Title"].str.contains(r"\bvs\b", case=False, regex=True)]
    ratio_exceptions = {9, 10, 39}
    bad_vs = versus[(versus["Series"] < 2) & (~versus["Order"].isin(ratio_exceptions))]
    checks = [
        ("Reference chart count", len(EQ16_REFERENCE_CHARTS) == 46, f"{len(EQ16_REFERENCE_CHARTS)}/46"),
        ("Extension chart count", len(EQ16_EXTENSION_CHARTS) == 22, f"{len(EQ16_EXTENSION_CHARTS)}/22"),
        ("Total chart count", len(EQ16_ALL_CHARTS) == 68, f"{len(EQ16_ALL_CHARTS)}/68"),
        ("Unique chart order", registry["Order"].is_unique, str(registry["Order"].nunique())),
        ("Unique chart titles", registry["Title"].is_unique, str(registry["Title"].nunique())),
        ("Factor vs cards are multi-series", bad_vs.empty, "PASS" if bad_vs.empty else ", ".join(bad_vs["Title"].tolist())),
        ("Direct public parity cards", int((registry["Parity status"] == "Direct public parity").sum()) == 10, str(int((registry["Parity status"] == "Direct public parity").sum()))),
        ("All extension cards explicitly tagged", int((registry["Origin"] == "JARVIS extensions").sum()) == 22, str(int((registry["Origin"] == "JARVIS extensions").sum()))),
    ]
    return pd.DataFrame([{"Check": name, "Result": "PASS" if ok else "FAIL", "Detail": detail} for name, ok, detail in checks])


def _eq16_quality(quality: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    quality = quality if isinstance(quality, pd.DataFrame) else pd.DataFrame()
    loaded = int((~quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Missing")).sum()) if not quality.empty else 0
    fresh = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).eq("Fresh").sum()) if not quality.empty else 0
    lagged = int(quality.get("Freshness", pd.Series(dtype=str)).astype(str).isin(["Lagged", "Stale"]).sum()) if not quality.empty else 0
    dates = pd.to_datetime(quality.get("Latest Date", pd.Series(dtype=str)), errors="coerce") if not quality.empty else pd.Series(dtype="datetime64[ns]")
    _html('<div class="mk-kpis">' + ''.join([
        _kpi_card("Series loaded", f"{loaded}/{len(quality)}", "Full active data audit"),
        _kpi_card("Fresh rows", str(fresh), "Source-specific tolerances"),
        _kpi_card("Lagged / stale", str(lagged), "Visible; never silently imputed"),
        _kpi_card("Chart registry", f"46 + 22 = {EQ16_TOTAL_COUNT}", f"Wall load {diagnostics.get('elapsed', 0):.1f}s"),
    ]) + '</div>')
    _liq5_table_card("Equity Strategy Series Registry", "CAPE, FRED macro/rates and market proxies with explicit source and freshness.", quality, [("Public / market lineage", "gold")], "Current full audit", 260)
    contract = pd.DataFrame([
        {"Layer": "CAPE / earnings yield", "Primary source": "Robert Shiller data; Multpl public table", "Fallback": "Yale workbook / In2013Dollars / disk cache", "Rule": "No fabricated history; source visible"},
        {"Layer": "Buffett indicator", "Primary source": "NCBEILQ027S + GDP via FRED", "Fallback": "Disk cache", "Rule": "Official anchor; SPY nowcast explicitly labelled"},
        {"Layer": "Rates / credit / macro", "Primary source": "FRED public series", "Fallback": "Disk cache", "Rule": "No forward-looking interpolation"},
        {"Layer": "Equity / factor / sector ETFs", "Primary source": "Yahoo/yfinance adjusted-price batch", "Fallback": "Disk cache", "Rule": "Common endpoints and one active-route batch"},
        {"Layer": "Factor rotation matrix", "Primary source": "Observed ETF total returns", "Fallback": "Unavailable", "Rule": "Seven public bands; relative = factor − SPY"},
        {"Layer": "Reference registry", "Primary source": "46 public architecture slots", "Fallback": "None", "Rule": "First ten direct parity; hidden definitions tagged as reconstruction"},
        {"Layer": "Extension registry", "Primary source": "22 JARVIS diagnostics", "Fallback": "None", "Rule": "Always counted outside the reference 46"},
        {"Layer": "Earnings revisions", "Primary source": "Licensed point-in-time provider", "Fallback": "Provider-required", "Rule": "No fabricated revision history"},
    ])
    _liq5_table_card("Equity Strategy Provider Contract", "Frozen source, frequency and modelling rules.", contract, [("No silent synthetic production history", "live")], EQ16_VERSION, 50)
    registry = _eq16_chart_registry()
    _liq5_table_card("Equity Strategy Chart Registry", "The 46-chart reference set and the 22 institutional additions are separate, countable and filterable.", registry, [("68 total charts", "gold"), ("46 reference", "live"), ("22 extensions", "gold")], "Direct public parity restricted to cards 1–10", 180)
    checks = _eq16_audit_checks()
    _liq5_table_card("Equity Strategy Structural Audit", "Automated invariants for count, identity, origin and multi-series comparison cards.", checks, [("All checks must pass", "gold")], "V16 freeze gate", 20)
    st.download_button("Download Equity Strategy series registry", data=quality.to_csv(index=False).encode("utf-8"), file_name="marketdesk_equity_strategy_series_v16.csv", mime="text/csv", key="market_eq16_download_quality")
    st.download_button("Download Equity Strategy chart registry", data=registry.to_csv(index=False).encode("utf-8"), file_name="marketdesk_equity_strategy_charts_v16.csv", mime="text/csv", key="market_eq16_download_charts")


def _render_equity_strategy_page_v16(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css(); _eq14_css(); _eq16_css()
    view = st.segmented_control("Equity Strategy research view", EQ14_VIEW_OPTIONS, key="market_eq16_view", label_visibility="collapsed") or "Dashboard"
    _eq16_header(view)
    if view == "Chart Book":
        controls = st.columns([.9, .9, 1.05, 1.0, .72], gap="medium")
    else:
        controls = st.columns([1.05, 1.0, 1.05, .75], gap="medium")
    with controls[0]: view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_eq16_level_mode")
    with controls[1]: smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_eq16_smoothing")
    origin_filter, family_filter = "All charts", "All"
    if view == "Chart Book":
        with controls[2]: origin_filter = st.selectbox("Chart set", list(EQ16_ORIGINS), key="market_eq16_origin_filter")
        with controls[3]: family_filter = st.selectbox("Research family", ["All"] + list(EQ16_FAMILIES), key="market_eq16_family_filter")
        with controls[4]: refresh = st.button("Refresh", key="market_eq16_refresh", width="stretch")
    else:
        with controls[2]: st.caption("Only the active Equity Strategy route is loaded.")
        with controls[3]: refresh = st.button("Refresh", key="market_eq16_refresh", width="stretch")
    if refresh:
        st.session_state["market_eq16_refresh_nonce"] = int(st.session_state.get("market_eq16_refresh_nonce", 0)) + 1; st.rerun()
    nonce = int(st.session_state.get("market_eq16_refresh_nonce", 0))
    fred_ids, symbols, _need_shiller = _eq16_required(view, origin_filter, family_filter)
    started = time.perf_counter()
    with st.spinner("Loading Equity Strategy — bounded public providers..."):
        with _eq15_ThreadPoolExecutor(max_workers=3) as ex:
            f_fred = ex.submit(_eq14_load_fred, fred_ids, "1870-01-01", nonce)
            f_market = ex.submit(_eq14_load_market, symbols, "max", nonce)
            f_cape = ex.submit(_eq15_load_cape, nonce)
            fred, q_fred, d_fred = f_fred.result(); market, q_market, d_market = f_market.result(); cape, q_cape, d_cape = f_cape.result()
    elapsed = time.perf_counter() - started
    parts = [q for q in (q_fred, q_market, q_cape) if isinstance(q, pd.DataFrame) and not q.empty]
    quality = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    _eq15_kpis(cape, fred, market)
    _html(f'<div class="eq14-note"><b>{_escape(EQ16_VERSION)}</b> · 46 reference + 22 extensions · Wall load {elapsed:.1f}s · FRED {_escape(str(d_fred.get("provider", "FRED")))} · Market {_escape(str(d_market.get("provider", "market")))} · CAPE {_escape(str(d_cape.get("provider", "CAPE")))} · active route {_escape(view)}.</div>')
    try:
        if view == "Dashboard": _eq16_dashboard(cape, fred, market, view_mode, smoothing)
        elif view in EQ14_FAMILIES: _eq16_family_view(view, fred, market, cape, view_mode, smoothing)
        elif view == "Regime": _eq16_regime_view(cape, fred, market, smoothing)
        elif view == "Chart Book": _eq16_chart_book(cape, fred, market, origin_filter, family_filter, view_mode, smoothing)
        else: _eq16_quality(quality, {"elapsed": elapsed, "fred": d_fred, "market": d_market, "cape": d_cape})
    except Exception as exc:
        st.error(f"Equity Strategy route failed: {type(exc).__name__}: {exc}")
        with st.expander("Equity Strategy traceback", expanded=False):
            import traceback as _eq16_traceback
            st.code(_eq16_traceback.format_exc())


# Preserve the complete V15 implementation and override only Equity Strategy.
_render_market_intelligence_v15 = render_market_intelligence


def render_market_intelligence(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict] = None) -> None:
    _init_market_state(); page = str(st.session_state.get(MARKET_PAGE_KEY, "fixed-income")).strip().lower()
    if page != "equity-strategy":
        return _render_market_intelligence_v15(ticker, price_data, analysis)
    _market_css(); ticker = str(ticker or "").upper().strip(); analysis = analysis or {}
    _html('<div class="mk-shell">')
    try:
        _deskbar("Equity Strategy"); _hero("equity-strategy"); _render_equity_strategy_page_v16(ticker, price_data, analysis)
        _html('<div class="mk-footer">' + _escape(EQ16_VERSION) + ' · 46 reference charts + 22 JARVIS extensions · Liquidity V6, FX V9, Fixed Income V11 and Credit V13 delegated unchanged · no synthetic production histories.</div>')
    finally:
        _html('</div>')


