COM17_PUBLIC_CHARTS = tuple(x for x in COM17_CHARTS if x["origin"] == "RoboMacro public parity")
COM17_EXTENSION_CHARTS = tuple(x for x in COM17_CHARTS if x["origin"] == "JARVIS extensions")


def _com17_norm(frame: Any) -> pd.DataFrame:
    return _eq14_norm(frame)


def _com17_latest(frame: Any) -> Optional[float]:
    return _eq14_latest(frame)


def _com17_latest_date(frame: Any) -> Optional[pd.Timestamp]:
    return _eq14_latest_date(frame)


def _com17_market_label(symbol: str) -> str:
    return COM17_MARKET_SYMBOLS.get(symbol, {}).get("label", symbol)


def _com17_fred_label(series_id: str) -> str:
    return COM17_FRED_SERIES.get(series_id, {}).get("label", series_id)


def _com17_source_for_fred(series_id: str) -> str:
    if series_id.startswith("P"):
        return "IMF Primary Commodity Prices via FRED"
    return "FRED public data"


@st.cache_data(ttl=21600, show_spinner=False)
def _com17_load_fred(series_ids: Tuple[str, ...], start_date: str = "1980-01-01", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    pack, quality, diag = _cr12_load_fred(tuple(series_ids), start_date, refresh_token)
    quality = quality.copy() if isinstance(quality, pd.DataFrame) else pd.DataFrame()
    if not quality.empty:
        for i, row in quality.iterrows():
            sid = str(row.get("Series / Instrument", "")); spec = COM17_FRED_SERIES.get(sid, {})
            quality.at[i, "Label"] = spec.get("label", sid)
            quality.at[i, "Category"] = spec.get("family", "Commodities")
            quality.at[i, "Unit"] = spec.get("unit", row.get("Unit", ""))
            quality.at[i, "Frequency"] = spec.get("frequency", row.get("Frequency", ""))
            latest = _com17_latest_date(pack.get(sid, pd.DataFrame()))
            quality.at[i, "Freshness"] = _cr12_freshness(latest, int(spec.get("expected_days", 75))) if latest is not None else "Missing"
    return pack, quality, diag


@st.cache_data(ttl=21600, show_spinner=False)
def _com17_load_market(symbols: Tuple[str, ...], period: str = "max", refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    pack, quality, diag = _cr12_load_market(tuple(symbols), period, refresh_token)
    quality = quality.copy() if isinstance(quality, pd.DataFrame) else pd.DataFrame()
    if not quality.empty:
        for i, row in quality.iterrows():
            sym = str(row.get("Series / Instrument", "")); spec = COM17_MARKET_SYMBOLS.get(sym, {})
            quality.at[i, "Label"] = spec.get("label", sym)
            quality.at[i, "Category"] = spec.get("family", "Commodities")
            quality.at[i, "Unit"] = spec.get("unit", row.get("Unit", "Adjusted price"))
            quality.at[i, "Frequency"] = "Daily"
    return pack, quality, diag


def _com17_cache_age_hours(path: _com17_Path) -> Optional[float]:
    try:
        return max(0.0, (time.time() - path.stat().st_mtime) / 3600.0)
    except Exception:
        return None


def _com17_cftc_parse(raw: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=["date", "code", "name", "open_interest", "long", "short", "net", "zscore", "net_pct_oi"])
    work = raw.copy(); work.columns = [str(c).strip().lower() for c in work.columns]
    def pick(candidates: Sequence[str], contains: Sequence[str] = ()) -> Optional[str]:
        for c in candidates:
            if c in work.columns: return c
        for c in work.columns:
            if all(token in c for token in contains): return c
        return None
    date_col = pick(("report_date_as_yyyy_mm_dd", "report_date"), ("report", "date"))
    code_col = pick(("cftc_contract_market_code", "contract_market_code"), ("contract", "market", "code"))
    name_col = pick(("market_and_exchange_names", "market_and_exchange_name"), ("market", "exchange"))
    oi_col = pick(("open_interest_all",), ("open_interest",))
    long_col = pick(("m_money_positions_long_all", "m_money_positions_long"), ("m_money", "positions", "long"))
    short_col = pick(("m_money_positions_short_all", "m_money_positions_short"), ("m_money", "positions", "short"))
    if not all((date_col, code_col, long_col, short_col)):
        return pd.DataFrame(columns=["date", "code", "name", "open_interest", "long", "short", "net", "zscore", "net_pct_oi"])
    out = pd.DataFrame({
        "date": pd.to_datetime(work[date_col], errors="coerce"),
        "code": work[code_col].astype(str).str.strip().str.zfill(6),
        "name": work[name_col].astype(str) if name_col else "",
        "open_interest": pd.to_numeric(work[oi_col], errors="coerce") if oi_col else np.nan,
        "long": pd.to_numeric(work[long_col], errors="coerce"),
        "short": pd.to_numeric(work[short_col], errors="coerce"),
    })
    out["net"] = out["long"] - out["short"]
    out = out.dropna(subset=["date", "code", "net"]).sort_values(["code", "date"]).drop_duplicates(["code", "date"], keep="last")
    out["zscore"] = out.groupby("code")["net"].transform(lambda s: (s - s.rolling(104, min_periods=52).mean()) / s.rolling(104, min_periods=52).std(ddof=0).replace(0, np.nan))
    out["net_pct_oi"] = out["net"] / out["open_interest"].replace(0, np.nan) * 100.0
    return out.reset_index(drop=True)


@st.cache_data(ttl=21600, show_spinner=False)
def _com17_load_cftc(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter(); cache = COM17_CACHE_DIR / "cftc_disaggregated.csv"; force = bool(refresh_token)
    raw = pd.DataFrame(); status = "provider-unavailable"; source = "CFTC Disaggregated Futures Only"; message = ""
    age = _com17_cache_age_hours(cache)
    if not force and cache.exists() and age is not None and age <= COM17_CFTC_TTL_HOURS:
        try:
            raw = pd.read_csv(cache, dtype={"cftc_contract_market_code": str, "code": str}); status = "cache"; message = "fresh disk cache"
        except Exception as exc:
            message = str(exc)
    if raw.empty and REQUESTS_AVAILABLE:
        try:
            codes = ",".join(f"'{x}'" for x in COM17_CFTC_CODES.values())
            params = {
                "$where": f"cftc_contract_market_code in ({codes}) AND report_date_as_yyyy_mm_dd >= '2016-01-01T00:00:00.000'",
                "$limit": "50000",
                "$order": "report_date_as_yyyy_mm_dd ASC",
            }
            response = requests.get("https://publicreporting.cftc.gov/resource/72hh-3qpy.json", params=params, timeout=(4.0, 12.0), headers={"User-Agent": "QuantTerminal-MarketDesk-Commodities/17.0"})
            response.raise_for_status(); raw = pd.DataFrame(response.json())
            parsed = _com17_cftc_parse(raw)
            if parsed.empty:
                raise ValueError("No compatible CFTC disaggregated rows")
            raw.to_csv(cache, index=False); status = "live"; message = "official Socrata API"
        except Exception as exc:
            message = str(exc)
    if raw.empty and cache.exists():
        try:
            raw = pd.read_csv(cache, dtype={"cftc_contract_market_code": str, "code": str}); status = "stale-cache"; message = message or "stale disk cache"
        except Exception:
            pass
    parsed = _com17_cftc_parse(raw); frames: Dict[str, pd.DataFrame] = {}; rows: List[Dict[str, Any]] = []
    for commodity, code in COM17_CFTC_CODES.items():
        use = parsed.loc[parsed["code"] == str(code).zfill(6)].copy() if not parsed.empty else pd.DataFrame()
        if not use.empty:
            frames[commodity] = use[["date", "net", "zscore", "open_interest", "net_pct_oi"]].reset_index(drop=True)
        latest = pd.Timestamp(use["date"].max()) if not use.empty else None
        rows.append({
            "Series / Instrument": f"CFTC:{commodity}", "Label": f"{commodity} managed-money positioning", "Category": "Positioning",
            "Source": source, "Status": status if not use.empty else "provider-unavailable", "Freshness": _cr12_freshness(latest, 14) if latest is not None else "Missing",
            "Observations": len(use), "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—", "Unit": "Contracts", "Frequency": "Weekly", "Message": message,
        })
    return frames, pd.DataFrame(rows), {"elapsed": time.perf_counter() - started, "provider": source, "status": status, "message": message}


def _com17_transform(frame: Any, view_mode: str, smoothing: str, allow_yoy: bool = True) -> pd.DataFrame:
    return _fi10_transform(frame, view_mode, smoothing, allow_yoy=allow_yoy, difference_like=False)


def _com17_line_card(title: str, subtitle: str, items: Sequence[Tuple[str, pd.DataFrame]], unit: str, source: str, view_mode: str, smoothing: str, **kwargs: Any) -> None:
    _fi10_line_card(title, subtitle, items, unit, source, view_mode, smoothing, **kwargs)


def _com17_calendar_return(frame: Any, months: int) -> Optional[float]:
    use = _com17_norm(frame)
    if use.empty: return None
    end = pd.Timestamp(use["date"].max()); start = end - pd.DateOffset(months=int(months))
    before = use.loc[use["date"] <= start]
    if before.empty: return None
    a = _safe_float(before["value"].iloc[-1]); b = _safe_float(use["value"].iloc[-1])
    return (b / a - 1.0) * 100.0 if a not in {None, 0} and b is not None else None


def _com17_return_heatmap_data(market: Mapping[str, pd.DataFrame], symbols: Sequence[str]) -> Tuple[np.ndarray, List[str], List[str]]:
    horizons = (("1M", 1), ("3M", 3), ("6M", 6), ("12M", 12)); rows, labels = [], []
    for sym in symbols:
        frame = market.get(sym, pd.DataFrame())
        vals = [_com17_calendar_return(frame, m) for _, m in horizons]
        if any(v is not None for v in vals): rows.append([np.nan if v is None else v for v in vals]); labels.append(_com17_market_label(sym))
    return np.asarray(rows, dtype=float), [x[0] for x in horizons], labels


def _com17_fred_return_heatmap_data(fred: Mapping[str, pd.DataFrame], ids: Sequence[str]) -> Tuple[np.ndarray, List[str], List[str]]:
    horizons = (("1M", 1), ("3M", 3), ("6M", 6), ("12M", 12)); rows, labels = [], []
    for sid in ids:
        frame = fred.get(sid, pd.DataFrame()); vals = [_com17_calendar_return(frame, m) for _, m in horizons]
        if any(v is not None for v in vals): rows.append([np.nan if v is None else v for v in vals]); labels.append(_com17_fred_label(sid))
    return np.asarray(rows, dtype=float), [x[0] for x in horizons], labels


def _com17_best_carbon(market: Mapping[str, pd.DataFrame]) -> Tuple[str, pd.DataFrame, str]:
    for sym, label in (("KEUA.L", "European Carbon Allowance ETF"), ("KRBN", "Global Carbon Allowance ETF"), ("GRN", "Global Carbon ETN")):
        frame = _com17_norm(market.get(sym, pd.DataFrame()))
        if not frame.empty: return sym, frame, label
    return "", pd.DataFrame(columns=["date", "value"]), "Carbon provider required"


def _com17_risk_return(title: str, subtitle: str, market: Mapping[str, pd.DataFrame], symbols: Sequence[str]) -> None:
    rows = []
    for sym in symbols:
        use = _com17_norm(market.get(sym, pd.DataFrame()))
        if len(use) < 80: continue
        ret = _com17_calendar_return(use, 12); vol = _com17_latest(_eq14_vol(use, 60))
        if ret is not None and vol is not None: rows.append((sym, ret, vol))
    if not rows:
        _liq5_render_chart_card(title, subtitle, None, [("Yahoo/yfinance batch", "gold")], empty_message="No usable market observations."); return
    fig = _fi10_base_figure("1Y return %", 420)
    for i, (sym, ret, vol) in enumerate(rows):
        fig.add_trace(go.Scatter(x=[vol], y=[ret], mode="markers+text", text=[sym], textposition="top center", name=sym, marker=dict(size=11, color=COM17_COLORS[i % len(COM17_COLORS)]), hovertemplate=f"{sym}<br>60D vol %{{x:.2f}}%<br>1Y return %{{y:.2f}}%<extra></extra>"))
    fig.update_xaxes(title="60D annualized volatility %"); fig.update_yaxes(title="1Y return %")
    _liq5_render_chart_card(title, subtitle, fig, [("Yahoo/yfinance batch", "gold")], "Latest available inputs")


def _com17_correlation(title: str, subtitle: str, market: Mapping[str, pd.DataFrame], symbols: Sequence[str]) -> None:
    series: Dict[str, pd.Series] = {}
    for sym in symbols:
        use = _com17_norm(market.get(sym, pd.DataFrame()))
        if not use.empty: series[sym] = use.set_index("date")["value"].pct_change(fill_method=None)
    if len(series) < 2:
        _liq5_render_chart_card(title, subtitle, None, [("Yahoo/yfinance batch", "gold")], empty_message="Insufficient overlapping histories."); return
    wide = pd.concat(series, axis=1).dropna(how="all").tail(252); corr = wide.corr(min_periods=60)
    _fi10_heatmap_card(title, subtitle, corr.to_numpy(), list(corr.columns), list(corr.index), ".2f", "Daily returns · 1Y window", 0)


def _com17_seasonality(title: str, subtitle: str, market: Mapping[str, pd.DataFrame], symbols: Sequence[str]) -> None:
    rows = []
    for sym in symbols:
        use = _com17_norm(market.get(sym, pd.DataFrame()))
        if len(use) < 500: continue
        monthly = use.set_index("date")["value"].resample("ME").last().pct_change(fill_method=None) * 100.0
        row = monthly.groupby(monthly.index.month).mean().reindex(range(1, 13))
        rows.append(row.to_numpy());
    if not rows:
        _liq5_render_chart_card(title, subtitle, None, [("Yahoo/yfinance batch", "gold")], empty_message="Insufficient history for seasonality."); return
    labels = [_com17_market_label(s) for s in symbols[:len(rows)]]
    _fi10_heatmap_card(title, subtitle, np.asarray(rows), ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"], labels, ".2f", "Average monthly returns", 0)


def _com17_cftc_single(title: str, subtitle: str, commodity: str, cftc: Mapping[str, pd.DataFrame]) -> None:
    use = cftc.get(commodity, pd.DataFrame())
    if use is None or use.empty:
        _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="CFTC managed-money history unavailable."); return
    net = use[["date", "net"]].rename(columns={"net": "value"}); z = use[["date", "zscore"]].rename(columns={"zscore": "value"}).dropna()
    _com17_line_card(title, subtitle, [("Net contracts", net), ("Z-score", z)], "Contracts", "CFTC Disaggregated Futures Only", "Levels", "Raw", allow_yoy=False, second_axis=["Z-score"], right_title="2Y z-score", y_policy="signed", y2_policy="signed")


def _com17_cftc_composite(title: str, subtitle: str, commodities: Sequence[str], cftc: Mapping[str, pd.DataFrame]) -> None:
    items = []
    for name in commodities:
        use = cftc.get(name, pd.DataFrame())
        if use is not None and not use.empty:
            items.append((name, use[["date", "zscore"]].rename(columns={"zscore": "value"}).dropna()))
    _com17_line_card(title, subtitle, items, "2Y z-score", "CFTC Disaggregated Futures Only", "Levels", "Raw", allow_yoy=False, difference_like=True, y_policy="signed")


def _com17_cftc_summary(cftc: Mapping[str, pd.DataFrame]) -> pd.DataFrame:
    rows = []
    for name in COM17_CFTC_CODES:
        use = cftc.get(name, pd.DataFrame())
        if use is None or use.empty: continue
        row = use.iloc[-1]
        rows.append({"Commodity": name, "Net contracts": int(row["net"]) if pd.notna(row["net"]) else np.nan, "2Y z-score": round(float(row["zscore"]), 2) if pd.notna(row["zscore"]) else np.nan, "Net / OI %": round(float(row["net_pct_oi"]), 2) if pd.notna(row["net_pct_oi"]) else np.nan, "Open interest": int(row["open_interest"]) if pd.notna(row["open_interest"]) else np.nan, "Latest": pd.Timestamp(row["date"]).strftime("%d %b %Y")})
    return pd.DataFrame(rows).sort_values("2Y z-score", ascending=False) if rows else pd.DataFrame()


def _com17_public_tables(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame]) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    def row(label: str, frame: Any, unit: str, source: str) -> Dict[str, Any]:
        v = _com17_latest(frame); d = _com17_latest_date(frame); change = _com17_calendar_return(frame, 1)
        return {"Benchmark": label, "Latest": _fmt(v, 2), "1M %": f"{change:+.2f}%" if change is not None else "—", "As of": _liq5_fmt_date(d), "Unit": unit, "Source": source}
    metals = pd.DataFrame([
        row("Gold (futures)", market.get("GC=F", pd.DataFrame()), "USD/oz", "Market data"),
        row("Silver (futures)", market.get("SI=F", pd.DataFrame()), "USD/oz", "Market data"),
        row("Copper (IMF)", fred.get("PCOPPUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
        row("Iron Ore (IMF)", fred.get("PIORECRUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
    ])
    agriculture = pd.DataFrame([
        row("Wheat", fred.get("PWHEAMTUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
        row("Corn", fred.get("PMAIZMTUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
        row("Soybeans", fred.get("PSOYBUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
        row("Coffee Arabica", fred.get("PCOFFOTMUSDM", pd.DataFrame()), "US cents/lb", "FRED (IMF)"),
    ])
    bulk = pd.DataFrame([
        row("Australian Coal", fred.get("PCOALAUUSDM", pd.DataFrame()), "USD/mt", "FRED (IMF)"),
        row("All-Commodity Index", fred.get("PALLFNFINDEXM", pd.DataFrame()), "Index", "FRED (IMF)"),
        row("Food Index", fred.get("PFOODINDEXM", pd.DataFrame()), "Index", "FRED (IMF)"),
        row("Energy Index", fred.get("PNRGINDEXM", pd.DataFrame()), "Index", "FRED (IMF)"),
    ])
    return metals, agriculture, bulk


def _com17_kpis(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame]) -> None:
    carbon_sym, carbon, carbon_label = _com17_best_carbon(market)
    cards = [
        _kpi_card("Gold", _fmt(_com17_latest(market.get("GC=F", pd.DataFrame())), 1), "USD/oz futures"),
        _kpi_card("Silver", _fmt(_com17_latest(market.get("SI=F", pd.DataFrame())), 2), "USD/oz futures"),
        _kpi_card("Iron ore", _fmt(_com17_latest(fred.get("PIORECRUSDM", pd.DataFrame())), 2), "USD/mt · IMF"),
        _kpi_card("Carbon", _fmt(_com17_latest(carbon), 2), carbon_label),
        _kpi_card("Thermal coal", _fmt(_com17_latest(fred.get("PCOALAUUSDM", pd.DataFrame())), 2), "USD/mt · IMF Australia"),
        _kpi_card("Platinum", _fmt(_com17_latest(market.get("PL=F", pd.DataFrame())), 1), "USD/oz futures"),
        _kpi_card("Palladium", _fmt(_com17_latest(market.get("PA=F", pd.DataFrame())), 1), "USD/oz futures"),
        _kpi_card("CFTC coverage", f"{len([x for x in cftc.values() if isinstance(x,pd.DataFrame) and not x.empty])}/{len(COM17_CFTC_CODES)}", "Weekly managed money"),
    ]
    _html('<div class="mk-kpis">' + ''.join(cards) + '</div>')


