COM18_ALL_CHARTS: Tuple[Dict[str, Any], ...] = tuple(COM17_CHARTS) + COM18_EXTRA_CHARTS
COM18_BY_N = {int(x["n"]): x for x in COM18_ALL_CHARTS}


def _com18_norm_col(name: Any) -> str:
    return " ".join(str(name).strip().lower().replace("_", " ").replace("-", " ").split())


def _com18_pick_column(columns: Sequence[Any], candidates: Sequence[str]) -> Optional[str]:
    norm = {_com18_norm_col(c): str(c) for c in columns}
    for cand in candidates:
        if _com18_norm_col(cand) in norm:
            return norm[_com18_norm_col(cand)]
    for cand in candidates:
        token = _com18_norm_col(cand)
        for key, original in norm.items():
            if token and token in key:
                return original
    return None


@st.cache_data(ttl=21600, show_spinner=False)
def _com18_load_wasde(refresh_token: int = 0) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    """Load the latest official USDA historical-WASDE CSV with bounded fallbacks."""
    started = time.perf_counter(); cache = COM18_CACHE_DIR / "wasde_latest.csv"; meta = COM18_CACHE_DIR / "wasde_latest_meta.txt"
    source, status, message = "USDA WASDE", "provider-unavailable", ""
    raw = pd.DataFrame()
    if REQUESTS_AVAILABLE:
        now = pd.Timestamp.utcnow().tz_localize(None)
        candidates: List[str] = []
        for back in range(0, 4):
            d = now - pd.DateOffset(months=back)
            candidates.append(f"https://www.usda.gov/sites/default/files/documents/oce-wasde-report-data-{d.year}-{d.month:02d}.csv")
        for url in candidates:
            try:
                r = requests.get(url, timeout=(3.0, 9.0), headers={"User-Agent": "QuantTerminal/1.0"})
                if r.ok and len(r.content) > 5000:
                    raw = pd.read_csv(io.BytesIO(r.content), low_memory=False)
                    if not raw.empty:
                        raw.to_csv(cache, index=False); meta.write_text(url, encoding="utf-8")
                        source, status, message = "USDA historical WASDE CSV", "live", url
                        break
            except Exception as exc:
                message = str(exc)
    if raw.empty and cache.exists():
        try:
            raw = pd.read_csv(cache, low_memory=False)
            age = _com17_cache_age_hours(cache)
            source = "USDA WASDE disk cache"; status = "cache" if age is not None and age <= 240 else "stale-cache"
            message = meta.read_text(encoding="utf-8") if meta.exists() else "cached official WASDE CSV"
        except Exception as exc:
            message = str(exc)
    if raw.empty:
        quality = pd.DataFrame([{
            "Series / Instrument": "USDA:WASDE", "Label": "USDA WASDE balance sheets", "Category": "Agriculture Fundamentals",
            "Source": source, "Status": status, "Freshness": "Missing", "Observations": 0, "Latest Date": "—",
            "Unit": "Mixed", "Frequency": "Monthly release", "Message": message or "Provider unavailable; no synthetic balance sheet.",
        }])
        return pd.DataFrame(), quality, {"elapsed": time.perf_counter()-started, "provider": source, "status": status, "message": message}

    # Normalize the schema without depending on one historical CSV vintage.
    cols = list(raw.columns)
    mapping = {
        "report_date": _com18_pick_column(cols, ["ReportDate", "Report Date", "ReleaseDate", "Release Date"]),
        "commodity": _com18_pick_column(cols, ["Commodity", "Commodity Name"]),
        "region": _com18_pick_column(cols, ["Region", "Country", "Geography"]),
        "market_year": _com18_pick_column(cols, ["MarketYear", "Market Year", "Marketing Year"]),
        "attribute": _com18_pick_column(cols, ["Attribute", "Attribute Name", "Item"]),
        "value": _com18_pick_column(cols, ["Value", "Forecast Value"]),
        "unit": _com18_pick_column(cols, ["Unit", "Units"]),
        "release_date": _com18_pick_column(cols, ["ReleaseDate", "Release Date", "ReportDate", "Report Date"]),
    }
    if not all(mapping.get(k) for k in ("commodity","attribute","value")):
        quality = pd.DataFrame([{
            "Series / Instrument": "USDA:WASDE", "Label": "USDA WASDE balance sheets", "Category": "Agriculture Fundamentals",
            "Source": source, "Status": "schema-error", "Freshness": "Missing", "Observations": len(raw), "Latest Date": "—",
            "Unit": "Mixed", "Frequency": "Monthly release", "Message": f"Unrecognized schema: {list(raw.columns)[:12]}",
        }])
        return pd.DataFrame(), quality, {"elapsed": time.perf_counter()-started, "provider": source, "status": "schema-error", "message": "unrecognized schema"}
    out = pd.DataFrame()
    for target, original in mapping.items():
        if original:
            out[target] = raw[original]
    out["commodity"] = out["commodity"].astype(str).str.strip()
    out["attribute"] = out["attribute"].astype(str).str.strip()
    out["region"] = out.get("region", pd.Series("", index=out.index)).astype(str).str.strip()
    out["market_year"] = out.get("market_year", pd.Series("", index=out.index)).astype(str).str.strip()
    out["unit"] = out.get("unit", pd.Series("", index=out.index)).astype(str).str.strip()
    out["value"] = pd.to_numeric(out["value"].astype(str).str.replace(",", "", regex=False), errors="coerce")
    out["release_date"] = pd.to_datetime(out.get("release_date", out.get("report_date")), errors="coerce")
    out = out.dropna(subset=["value"]).reset_index(drop=True)
    latest = out["release_date"].max() if "release_date" in out else pd.NaT
    quality = pd.DataFrame([{
        "Series / Instrument": "USDA:WASDE", "Label": "USDA WASDE balance sheets", "Category": "Agriculture Fundamentals",
        "Source": source, "Status": status, "Freshness": _cr12_freshness(latest, 45) if pd.notna(latest) else "Lagged",
        "Observations": len(out), "Latest Date": latest.strftime("%Y-%m-%d") if pd.notna(latest) else "—",
        "Unit": "Mixed", "Frequency": "Monthly release", "Message": message,
    }])
    return out, quality, {"elapsed": time.perf_counter()-started, "provider": source, "status": status, "message": message}


def _com18_wasde_rows(wasde: pd.DataFrame, commodity: str, region: str = "United States") -> pd.DataFrame:
    if not isinstance(wasde, pd.DataFrame) or wasde.empty:
        return pd.DataFrame()
    use = wasde.copy()
    c = use["commodity"].astype(str).str.lower()
    aliases = {
        "corn": ("corn", "maize"), "wheat": ("wheat",), "soybeans": ("soybean", "soybeans"),
        "cotton": ("cotton",), "sugar": ("sugar",), "milk": ("milk", "dairy"),
    }
    tokens = aliases.get(commodity.lower(), (commodity.lower(),))
    mask = pd.Series(False, index=use.index)
    for token in tokens:
        mask |= c.str.contains(token, na=False)
    use = use.loc[mask].copy()
    if region and "region" in use:
        r = use["region"].astype(str).str.lower()
        preferred = r.str.contains(r"united states|u\.s\.|usa", regex=True, na=False)
        if preferred.any(): use = use.loc[preferred].copy()
    return use


def _com18_attr_match(frame: pd.DataFrame, tokens: Sequence[str]) -> pd.DataFrame:
    if frame.empty: return frame
    a = frame["attribute"].astype(str).str.lower()
    mask = pd.Series(False, index=frame.index)
    for token in tokens: mask |= a.str.contains(token.lower(), na=False)
    return frame.loc[mask].copy()


def _com18_wasde_latest_balance(wasde: pd.DataFrame, commodity: str) -> pd.DataFrame:
    use = _com18_wasde_rows(wasde, commodity)
    if use.empty: return pd.DataFrame()
    latest = use["release_date"].max()
    if pd.notna(latest): use = use.loc[use["release_date"] == latest].copy()
    years = list(dict.fromkeys(use["market_year"].astype(str).tolist()))[-4:]
    use = use.loc[use["market_year"].astype(str).isin(years)].copy()
    wanted = {
        "Beginning Stocks": ("beginning stock",), "Production": ("production",), "Imports": ("import",),
        "Domestic Use": ("domestic", "total use"), "Exports": ("export",), "Ending Stocks": ("ending stock",),
    }
    rows: List[Dict[str, Any]] = []
    for year in years:
        yy = use.loc[use["market_year"].astype(str) == str(year)]
        row: Dict[str, Any] = {"Market year": year}
        for label, tokens in wanted.items():
            hit = _com18_attr_match(yy, tokens)
            row[label] = float(hit["value"].iloc[-1]) if not hit.empty else np.nan
        if pd.notna(row.get("Ending Stocks")) and pd.notna(row.get("Domestic Use")) and row.get("Domestic Use") not in (0, None):
            row["Stocks / Use %"] = row["Ending Stocks"] / row["Domestic Use"] * 100.0
        else: row["Stocks / Use %"] = np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def _com18_wasde_stock_use_series(wasde: pd.DataFrame, commodity: str) -> pd.DataFrame:
    tab = _com18_wasde_latest_balance(wasde, commodity)
    if tab.empty: return pd.DataFrame(columns=["date","value"])
    dates = []
    for x in tab["Market year"].astype(str):
        m = pd.Series(x).str.extract(r"(\d{4})")[0].iloc[0]
        dates.append(pd.Timestamp(f"{m}-01-01") if isinstance(m, str) else pd.NaT)
    return _eq14_norm(pd.DataFrame({"date": dates, "value": tab["Stocks / Use %"]}))


def _com18_wasde_revision_series(wasde: pd.DataFrame, commodity: str) -> pd.DataFrame:
    use = _com18_wasde_rows(wasde, commodity)
    if use.empty: return pd.DataFrame(columns=["date","value"])
    end = _com18_attr_match(use, ("ending stock",))
    if end.empty: return pd.DataFrame(columns=["date","value"])
    current_year = end["market_year"].astype(str).iloc[-1]
    end = end.loc[end["market_year"].astype(str) == current_year].copy()
    out = end.groupby("release_date", as_index=False)["value"].last().rename(columns={"release_date":"date"})
    return _eq14_norm(out)


def _com18_valuation_rows(market: Mapping[str,pd.DataFrame], cftc: Mapping[str,pd.DataFrame]) -> pd.DataFrame:
    mapping = {
        "Wheat": "ZW=F", "Corn": "ZC=F", "Soybeans": "ZS=F", "Coffee": "KC=F",
        "Sugar": "SB=F", "Cocoa": "CC=F", "Cotton": "CT=F", "Live Cattle": "LE=F",
        "Lean Hogs": "HE=F", "Milk": "DC=F",
    }
    rows = []
    for name, sym in mapping.items():
        use = _com17_norm(market.get(sym, pd.DataFrame()))
        if use.empty: continue
        hist = use.tail(2520); latest = _com17_latest(hist)
        pct = float((hist["value"] <= latest).mean()*100.0) if latest is not None and len(hist) else np.nan
        mean, std = hist["value"].mean(), hist["value"].std(ddof=0)
        z = (latest-mean)/std if latest is not None and std and np.isfinite(std) else np.nan
        ret = _com17_calendar_return(use, 12)
        pos = cftc.get(name, pd.DataFrame())
        pz = float(pos["zscore"].dropna().iloc[-1]) if isinstance(pos, pd.DataFrame) and not pos.empty and pos["zscore"].notna().any() else np.nan
        rows.append({"Commodity": name, "Symbol": sym, "Price percentile": round(pct,1), "Price z-score": round(z,2), "12M %": round(ret,2) if ret is not None else np.nan, "CFTC z-score": round(pz,2) if np.isfinite(pz) else np.nan})
    return pd.DataFrame(rows)


def _com18_soy_crush(market: Mapping[str,pd.DataFrame]) -> pd.DataFrame:
    # Standard transparent board-crush approximation per bushel:
    # 48 lb meal and 11 lb oil output from one 60 lb soybean bushel.
    beans = _com17_norm(market.get("ZS=F", pd.DataFrame())); meal = _com17_norm(market.get("ZM=F", pd.DataFrame())); oil = _com17_norm(market.get("ZL=F", pd.DataFrame()))
    if beans.empty or meal.empty or oil.empty: return pd.DataFrame(columns=["date","value"])
    b = beans.rename(columns={"value":"beans"}); m = meal.rename(columns={"value":"meal"}); o = oil.rename(columns={"value":"oil"})
    merged = pd.merge_asof(b.sort_values("date"), m.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5))
    merged = pd.merge_asof(merged.sort_values("date"), o.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna()
    # Futures conventions: soybeans cents/bu, meal USD/short ton, oil cents/lb.
    revenue = merged["meal"] * (48.0/2000.0) + merged["oil"] * (11.0/100.0)
    cost = merged["beans"] / 100.0
    return _eq14_norm(pd.DataFrame({"date": merged["date"], "value": revenue-cost}))


def _com18_cattle_margin(market: Mapping[str,pd.DataFrame]) -> pd.DataFrame:
    live = _com17_norm(market.get("LE=F", pd.DataFrame())); feeder = _com17_norm(market.get("GF=F", pd.DataFrame())); corn = _com17_norm(market.get("ZC=F", pd.DataFrame()))
    if live.empty or feeder.empty or corn.empty: return pd.DataFrame(columns=["date","value"])
    a = live.rename(columns={"value":"live"}); b = feeder.rename(columns={"value":"feeder"}); c = corn.rename(columns={"value":"corn"})
    merged = pd.merge_asof(a.sort_values("date"), b.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5))
    merged = pd.merge_asof(merged.sort_values("date"), c.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=5)).dropna()
    # Relative-value proxy only; normalized inputs avoid pretending to be a cash feedlot P&L.
    for col in ("live","feeder","corn"):
        merged[col] = merged[col] / merged[col].rolling(252, min_periods=60).mean()
    proxy = merged["live"] - 0.70*merged["feeder"] - 0.30*merged["corn"]
    return _eq14_norm(pd.DataFrame({"date": merged["date"], "value": proxy}))


def _com18_required(main_view: str, subview: str, origin: str = "All charts", family: str = "All") -> Tuple[Tuple[str,...],Tuple[str,...],bool,bool]:
    fred: set[str] = set(); market: set[str] = set(); need_cftc = False; need_wasde = False
    # Persistent snapshot strip inputs.
    fred.update(("PIORECRUSDM","PCOALAUUSDM")); market.update(("GC=F","SI=F","PL=F","PA=F","KEUA.L","KRBN","GRN"))
    if main_view == "Dashboard":
        fred.update(("PALLFNFINDEXM","PFOODINDEXM","PNRGINDEXM","PCOPPUSDM","PWHEAMTUSDM","PMAIZMTUSDM","PSOYBUSDM","PCOFFOTMUSDM")); market.update(("GC=F","SI=F"))
    elif main_view == "Metals":
        fred.update(("PCOPPUSDM","PIORECRUSDM","PALUMUSDM","PNICKUSDM","PZINCUSDM","PLEADUSDM","PTINUSDM")); market.update(("GC=F","SI=F","HG=F","PL=F","PA=F","DBB"))
        if subview == "Positioning": need_cftc = True
        if subview == "Macro Sensitivity": fred.update(("DTWEXBGS","DFII10")); market.add("SPY")
    elif main_view == "Agriculture":
        fred.update(COM18_FRED_EXTRA.keys()); fred.update(("PWHEAMTUSDM","PMAIZMTUSDM","PSOYBUSDM","PCOFFOTMUSDM","PCOFFROBUSDM"))
        market.update(("ZW=F","ZC=F","ZS=F","ZL=F","ZM=F","ZR=F","KC=F","SB=F","CC=F","CT=F","OJ=F","LE=F","HE=F","GF=F","DC=F","DBA"))
        if subview in ("Overview","Fundamentals"): need_wasde = True
        if subview in ("Overview","Positioning","Valuation"): need_cftc = True
    elif main_view == "Carbon & Bulk":
        fred.update(("PCOALAUUSDM","PIORECRUSDM","PINDUINDEXM","PNFUELINDEXM","DTWEXBGS","DFII10")); market.update(("KEUA.L","KRBN","GRN","DBB"))
    elif main_view == "Data Quality":
        fred.update(COM17_FRED_SERIES.keys()); market.update(COM17_MARKET_SYMBOLS.keys()); need_cftc = True; need_wasde = True
    elif main_view == "Chart Book":
        specs = list(COM18_ALL_CHARTS)
        if origin != "All charts": specs = [x for x in specs if x.get("origin") == origin]
        if family != "All": specs = [x for x in specs if x.get("domain", x.get("family")) == family]
        page = max(1, int(st.session_state.get("market_com18_chart_page",1))); specs = specs[(page-1)*COM18_PAGE_SIZE:page*COM18_PAGE_SIZE]
        for spec in specs:
            f, m, c = _com18_spec_requirements(spec); fred.update(f); market.update(m); need_cftc |= c; need_wasde |= spec.get("kind","").startswith("wasde") or spec.get("kind") == "agri_signal_matrix"
    return tuple(sorted(fred)), tuple(sorted(market)), need_cftc, need_wasde


def _com18_spec_requirements(spec: Mapping[str,Any]) -> Tuple[List[str],List[str],bool]:
    if int(spec.get("n",0)) <= 54:
        return _com17_spec_requirements(spec)
    f = list(spec.get("ids", ())); m = list(spec.get("symbols", ())); c = False
    kind = str(spec.get("kind",""))
    if kind in ("cftc_composite","cftc_agri_ladder","cftc_agri_heatmap","price_positioning","agri_signal_matrix"): c = True
    if kind == "soy_crush": m += ["ZS=F","ZM=F","ZL=F"]
    if kind == "cattle_margin": m += ["LE=F","GF=F","ZC=F"]
    if kind == "agri_ratios": m += ["ZW=F","ZC=F","ZS=F","KC=F","CC=F","LE=F"]
    if kind in ("valuation_ladder","valuation_heatmap","price_positioning","agri_signal_matrix"):
        m += ["ZW=F","ZC=F","ZS=F","KC=F","SB=F","CC=F","CT=F","LE=F","HE=F","DC=F"]
    if kind == "metals_macro_corr": m += ["GC=F","SI=F","HG=F"]; f += ["DTWEXBGS","DFII10"]
    if kind in ("carbon_valuation","carbon_macro"): m += ["KEUA.L","KRBN","GRN"]
    if kind == "carbon_macro": f += ["DTWEXBGS","DFII10"]
    return sorted(set(f)), sorted(set(m)), c


def _com18_cftc_subset(cftc: Mapping[str,pd.DataFrame], names: Sequence[str]) -> pd.DataFrame:
    table = _com17_cftc_summary(cftc)
    if table.empty: return table
    return table.loc[table["Commodity"].isin(list(names))].copy()


def _com18_render_extra(spec: Mapping[str,Any], fred: Mapping[str,pd.DataFrame], market: Mapping[str,pd.DataFrame], cftc: Mapping[str,pd.DataFrame], wasde: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    title = f'{int(spec["n"])}. {spec["title"]}'; subtitle = str(spec.get("subtitle","")); kind = str(spec.get("kind",""))
    if kind in ("market_index","vol_ladder","fred_index","seasonality","cftc_composite"):
        # Delegate to the frozen V17 renderer without pre-numbering the title;
        # _com17_render_spec adds the chart order exactly once.
        proxy = dict(spec)
        _com17_render_spec(proxy, fred, market, cftc, view_mode, smoothing); return
    if kind == "wasde_stu":
        commodity = str(spec.get("commodity")); frame = _com18_wasde_stock_use_series(wasde, commodity)
        _com17_line_card(title, subtitle, [(f"{commodity} stocks/use",frame)], "%", "USDA WASDE", "Levels", "Raw", allow_yoy=False, y_policy="positive")
    elif kind == "wasde_revision":
        items = [(x, _com18_wasde_revision_series(wasde,x)) for x in ("Corn","Wheat","Soybeans")]
        _com17_line_card(title, subtitle, items, "Reported units", "USDA historical WASDE CSV", "Levels", "Raw", allow_yoy=False, y_policy="positive")
    elif kind in ("cftc_agri_ladder","cftc_agri_heatmap"):
        names = ("Wheat","Corn","Soybeans","Coffee","Sugar","Cocoa","Cotton","Live Cattle","Lean Hogs","Feeder Cattle")
        table = _com18_cftc_subset(cftc,names)
        if kind == "cftc_agri_ladder":
            if table.empty: _liq5_render_chart_card(title,subtitle,None,[("CFTC Disaggregated Futures Only","gold")],empty_message="CFTC agriculture positioning unavailable.")
            else:
                fig = _fi10_base_figure("Net contracts",420); colors=["#72c48f" if v>=0 else "#e87557" for v in table["Net contracts"]]
                fig.add_trace(go.Bar(x=table["Commodity"],y=table["Net contracts"],marker_color=colors,name="Net contracts")); fig.update_xaxes(tickangle=-35)
                _liq5_render_chart_card(title,subtitle,fig,[("CFTC Disaggregated Futures Only","gold")],"Latest weekly reports")
        else:
            z=table[["2Y z-score"]].T.to_numpy() if not table.empty else np.empty((0,0)); x=list(table["Commodity"]) if not table.empty else []
            _fi10_heatmap_card(title,subtitle,z,x,["Current"],".2f","CFTC Disaggregated Futures Only",0)
    elif kind == "soy_crush":
        frame = _com18_soy_crush(market); _com17_line_card(title,subtitle,[("Board crush proxy",frame)],"USD/bu proxy","Yahoo/yfinance continuous futures", "Levels","Raw",allow_yoy=False,y_policy="signed")
    elif kind == "cattle_margin":
        frame = _com18_cattle_margin(market); _com17_line_card(title,subtitle,[("Relative margin proxy",frame)],"Normalized spread","Yahoo/yfinance continuous futures", "Levels","Raw",allow_yoy=False,y_policy="signed")
    elif kind == "agri_ratios":
        items=[]
        for label,a,b in (("Wheat/Corn","ZW=F","ZC=F"),("Soybeans/Corn","ZS=F","ZC=F"),("Coffee/Cocoa","KC=F","CC=F"),("Live Cattle/Corn","LE=F","ZC=F")):
            items.append((label,_eq14_ratio(market.get(a,pd.DataFrame()),market.get(b,pd.DataFrame()))))
        _com17_line_card(title,subtitle,items,"Ratio","Yahoo/yfinance adjusted-price batch","Levels","Raw",allow_yoy=False,y_policy="positive")
    elif kind in ("valuation_ladder","valuation_heatmap"):
        table=_com18_valuation_rows(market,cftc)
        if kind=="valuation_ladder":
            if table.empty: _liq5_render_chart_card(title,subtitle,None,[("Market data","gold")],empty_message="Valuation history unavailable.")
            else:
                table=table.sort_values("Price percentile",ascending=False); fig=_fi10_base_figure("Historical percentile",420)
                fig.add_trace(go.Bar(x=table["Commodity"],y=table["Price percentile"],marker_color=[COM18_COLORS[i%len(COM18_COLORS)] for i in range(len(table))])); fig.update_yaxes(range=[0,100]); fig.update_xaxes(tickangle=-35)
                _liq5_render_chart_card(title,subtitle,fig,[("10Y or available market history","gold")],"Current observations")
        else:
            if table.empty: z=np.empty((0,0)); x=[]
            else: z=table[["Price z-score","12M %","CFTC z-score"]].to_numpy(); x=list(table["Commodity"])
            _fi10_heatmap_card(title,subtitle,z,["Price z-score","12M %","CFTC z-score"],x,".2f","Market data + CFTC",0)
    elif kind == "price_positioning":
        table=_com18_valuation_rows(market,cftc).dropna(subset=["12M %","CFTC z-score"])
        if table.empty: _liq5_render_chart_card(title,subtitle,None,[("Market data + CFTC","gold")],empty_message="Overlapping price and positioning data unavailable.")
        else:
            fig=_fi10_base_figure("12M return %",420)
            for i,row in table.iterrows(): fig.add_trace(go.Scatter(x=[row["CFTC z-score"]],y=[row["12M %"]],mode="markers+text",text=[row["Commodity"]],textposition="top center",name=row["Commodity"],marker=dict(size=11,color=COM18_COLORS[i%len(COM18_COLORS)])))
            fig.update_xaxes(title="CFTC 2Y z-score"); fig.update_yaxes(title="12M return %")
            _liq5_render_chart_card(title,subtitle,fig,[("Yahoo/yfinance + CFTC","gold")],"Latest overlapping inputs")
    elif kind == "metals_macro_corr":
        inputs={"Gold":market.get("GC=F",pd.DataFrame()),"Silver":market.get("SI=F",pd.DataFrame()),"Copper":market.get("HG=F",pd.DataFrame()),"Dollar":fred.get("DTWEXBGS",pd.DataFrame()),"Real yield":fred.get("DFII10",pd.DataFrame())}
        _com18_corr_card(title,subtitle,inputs)
    elif kind == "carbon_valuation":
        _,frame,label=_com17_best_carbon(market)
        if frame.empty: _liq5_render_chart_card(title,subtitle,None,[("Public proxy","gold")],empty_message="Carbon proxy unavailable.")
        else:
            hist=frame.tail(2520); roll=hist["value"].rolling(252,min_periods=60); z=(hist["value"]-roll.mean())/roll.std(ddof=0)
            pct=hist["value"].rolling(252,min_periods=60).apply(lambda x: pd.Series(x).rank(pct=True).iloc[-1]*100,raw=False)
            _com17_line_card(title,subtitle,[("Price percentile",pd.DataFrame({"date":hist["date"],"value":pct})),("Price z-score",pd.DataFrame({"date":hist["date"],"value":z}))],"Percentile","Public carbon proxy", "Levels","Raw",allow_yoy=False,second_axis=["Price z-score"],right_title="Z-score",y_policy="positive",y2_policy="signed")
    elif kind == "carbon_macro":
        _,frame,label=_com17_best_carbon(market)
        _com17_line_card(title,subtitle,[(label,frame),("Broad Dollar",fred.get("DTWEXBGS",pd.DataFrame())),("10Y Real Yield",fred.get("DFII10",pd.DataFrame()))],"Carbon proxy","Public proxy + FRED","Levels",smoothing,allow_yoy=False,second_axis=["Broad Dollar","10Y Real Yield"],right_title="Macro factors",y_policy="positive",y2_policy="signed")
    elif kind == "fred_valuation":
        rows=[]
        for sid in spec.get("ids",()):
            use=_com17_norm(fred.get(sid,pd.DataFrame())); latest=_com17_latest(use)
            if use.empty or latest is None: continue
            hist=use.tail(120); pct=float((hist["value"]<=latest).mean()*100); z=(latest-hist["value"].mean())/(hist["value"].std(ddof=0) or np.nan)
            rows.append((_com17_fred_label(sid),pct,z))
        if not rows: _liq5_render_chart_card(title,subtitle,None,[("IMF/FRED","gold")],empty_message="Bulk valuation history unavailable.")
        else:
            fig=_fi10_base_figure("Historical percentile",420); fig.add_trace(go.Bar(x=[r[0] for r in rows],y=[r[1] for r in rows],marker_color=COM18_COLORS[:len(rows)])); fig.update_yaxes(range=[0,100]); _liq5_render_chart_card(title,subtitle,fig,[("IMF Primary Commodity Prices","gold")],"Current observations")
    elif kind == "agri_signal_matrix":
        table=_com18_valuation_rows(market,cftc)
        if table.empty: z=np.empty((0,0)); x=[]
        else:
            # Normalize dimensions to comparable signed scores.
            score=np.column_stack([(table["12M %"].fillna(0)/20).clip(-2,2),(table["Price z-score"].fillna(0)).clip(-2,2),(table["CFTC z-score"].fillna(0)).clip(-2,2)])
            z=score; x=list(table["Commodity"])
        _fi10_heatmap_card(title,subtitle,z,["Momentum","Valuation","Positioning"],x,".2f","Transparent public-data diagnostics",0)
    else:
        _liq5_render_chart_card(title,subtitle,None,[("Provider contract","gold")],empty_message=f"Unsupported V18 chart kind: {kind}")


def _com18_corr_card(title: str, subtitle: str, inputs: Mapping[str,pd.DataFrame]) -> None:
    series={}
    for label,frame in inputs.items():
        use=_com17_norm(frame)
        if not use.empty: series[label]=use.set_index("date")["value"].resample("W-FRI").last().pct_change(fill_method=None)
    if len(series)<3: _liq5_render_chart_card(title,subtitle,None,[("Public data","gold")],empty_message="Insufficient overlapping histories."); return
    wide=pd.concat(series,axis=1).dropna(how="all").tail(156); corr=wide.corr(min_periods=30)
    _fi10_heatmap_card(title,subtitle,corr.to_numpy(),list(corr.columns),list(corr.index),".2f","Weekly changes · 3Y window",0)


def _com18_render_spec(spec: Mapping[str,Any], fred: Mapping[str,pd.DataFrame], market: Mapping[str,pd.DataFrame], cftc: Mapping[str,pd.DataFrame], wasde: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    if int(spec.get("n",0)) <= 54:
        _com17_render_spec(spec,fred,market,cftc,view_mode,smoothing)
    else:
        _com18_render_extra(spec,fred,market,cftc,wasde,view_mode,smoothing)


def _com18_table_agri_monitor(market: Mapping[str,pd.DataFrame], symbols: Sequence[str]) -> pd.DataFrame:
    rows=[]
    for sym in symbols:
        frame=market.get(sym,pd.DataFrame()); latest=_com17_latest(frame)
        rows.append({"Instrument":_com17_market_label(sym),"Symbol":sym,"Latest":round(latest,3) if latest is not None else np.nan,"1M %":round(_com17_calendar_return(frame,1),2) if _com17_calendar_return(frame,1) is not None else np.nan,"3M %":round(_com17_calendar_return(frame,3),2) if _com17_calendar_return(frame,3) is not None else np.nan,"12M %":round(_com17_calendar_return(frame,12),2) if _com17_calendar_return(frame,12) is not None else np.nan})
    return pd.DataFrame(rows)


