def _com18_seasonality_table(market: Mapping[str,pd.DataFrame]) -> pd.DataFrame:
    now_month=pd.Timestamp.utcnow().month; next_month=1 if now_month==12 else now_month+1; rows=[]
    for sym in ("ZW=F","ZC=F","ZS=F","KC=F","SB=F","CC=F","CT=F","LE=F","HE=F","GF=F","DC=F"):
        use=_com17_norm(market.get(sym,pd.DataFrame()))
        if len(use)<500: continue
        monthly=use.set_index("date")["value"].resample("ME").last().pct_change(fill_method=None)*100
        avg=monthly.groupby(monthly.index.month).mean()
        rows.append({"Instrument":_com17_market_label(sym),"Current month avg %":round(float(avg.get(now_month,np.nan)),2),"Next month avg %":round(float(avg.get(next_month,np.nan)),2),"History months":int(monthly.notna().sum())})
    return pd.DataFrame(rows)


