    _liq5_table_card("Commodities Chart Registry","All V17 charts plus the missing nested research components.",_com18_registry(),[("88 total charts","gold"),("34 V18 additions","live")],"Explicit origin and inputs",160)
    _liq5_table_card("Commodities Structural Audit","Automated invariants for counts, identity, scope and nesting.",_com18_structural_audit(),[("All checks must pass","gold")],"V18 freeze gate",20)
    st.download_button("Download Commodities V18 series registry",data=q.to_csv(index=False).encode("utf-8"),file_name="marketdesk_commodities_series_v18.csv",mime="text/csv",key="market_com18_download_quality")
