def _com18_header(main_view: str, subview: str = "") -> None:
    meta={
        "Dashboard":("PUBLIC PARITY · BENCHMARKS · CROSS-COMMODITY","Commodities dashboard","Public snapshot, benchmark tables and cross-commodity pulse."),
        "Metals":("PRECIOUS · BASE METALS · RELATIVE VALUE","Metals strategy","Precious and industrial metals, positioning, relative value and macro sensitivity."),
        "Agriculture":("GRAINS · OILSEEDS · SOFTS · LIVESTOCK · DAIRY","Agriculture strategy","Nested agriculture research matching the reference organization."),
        "Carbon & Bulk":("CARBON · COAL · IRON ORE · MATERIALS","Carbon and bulk commodities","Transparent carbon proxies, bulk benchmarks, valuation and macro sensitivity."),
        "Chart Book":("88 CHARTS · PUBLIC PARITY + RECONSTRUCTION + EXTENSIONS","Commodities chart book","Page-level lazy loading across all nested research domains."),
        "Data Quality":("AUDIT · FRESHNESS · LINEAGE · ORGANIZATION","Commodities data quality","Provider contracts, structure parity, source lineage and freeze gates."),
    }[main_view]
    # Render the section header directly.  The V18 patch must not depend on
    # a helper that was never part of the frozen Equity Strategy API.
    _html(
        f'<div class="eq14-group">{_escape(meta[0])}</div>'
        f'<div class="eq14-title">{_escape(meta[1])}</div>'
        f'<div class="eq14-sub">{_escape(meta[2])}</div>'
    )
    if subview: _html(f'<div class="com18-subnote"><b>{_escape(main_view)}</b> · {_escape(subview)}</div>')


def _render_commodities_page_v18(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css(); _eq14_css(); _com17_css(); _com18_css()
    main_view=st.segmented_control("Commodities main section",COM18_MAIN_VIEWS,key="market_com18_main_view",label_visibility="collapsed") or "Dashboard"
    subview=""
    if main_view=="Agriculture": subview=st.segmented_control("Agriculture section",COM18_AGRI_VIEWS,key="market_com18_agri_view",label_visibility="collapsed") or "Overview"
    elif main_view=="Metals": subview=st.segmented_control("Metals section",COM18_METALS_VIEWS,key="market_com18_metals_view",label_visibility="collapsed") or "Overview"
    elif main_view=="Carbon & Bulk": subview=st.segmented_control("Carbon and bulk section",COM18_CARBON_VIEWS,key="market_com18_carbon_view",label_visibility="collapsed") or "Overview"
    _com18_header(main_view,subview)
    if main_view=="Chart Book": controls=st.columns([.8,.8,1.15,1.0,.7],gap="medium")
    else: controls=st.columns([1.0,1.0,1.2,.75],gap="medium")
    with controls[0]: view_mode=st.selectbox("View",["Levels","YoY %"],key="market_com18_level_mode")
    with controls[1]: smoothing=st.selectbox("Smoothing",["Raw","7D","28D"],key="market_com18_smoothing")
    origin,family="All charts","All"
    if main_view=="Chart Book":
        with controls[2]: origin=st.selectbox("Chart set",list(COM18_ORIGINS),key="market_com18_origin")
        with controls[3]: family=st.selectbox("Research domain",["All","Dashboard","Metals","Agriculture","Carbon & Bulk","Positioning","Macro Sensitivity"],key="market_com18_family")
        with controls[4]: refresh=st.button("Refresh",key="market_com18_refresh",width="stretch")
    else:
        with controls[2]: st.caption("Only the active Commodities route and nested section are loaded.")
        with controls[3]: refresh=st.button("Refresh",key="market_com18_refresh",width="stretch")
    if refresh:
        st.session_state["market_com18_refresh_nonce"]=int(st.session_state.get("market_com18_refresh_nonce",0))+1; st.rerun()
    nonce=int(st.session_state.get("market_com18_refresh_nonce",0)); fred_ids,symbols,need_cftc,need_wasde=_com18_required(main_view,subview,origin,family)
    started=time.perf_counter()
    with st.spinner("Loading Commodities — bounded official/public providers..."):
        with _com18_ThreadPoolExecutor(max_workers=4) as ex:
            f_fred=ex.submit(_com17_load_fred,fred_ids,"1980-01-01",nonce)
            f_market=ex.submit(_com17_load_market,symbols,"max",nonce)
            f_cftc=ex.submit(_com17_load_cftc,nonce) if need_cftc else None
            f_wasde=ex.submit(_com18_load_wasde,nonce) if need_wasde else None
            fred,q_fred,d_fred=f_fred.result(); market,q_market,d_market=f_market.result()
            if f_cftc is not None: cftc,q_cftc,d_cftc=f_cftc.result()
            else: cftc,q_cftc,d_cftc={},pd.DataFrame(),{"provider":"not-requested"}
            if f_wasde is not None: wasde,q_wasde,d_wasde=f_wasde.result()
            else: wasde,q_wasde,d_wasde=pd.DataFrame(),pd.DataFrame(),{"provider":"not-requested"}
    elapsed=time.perf_counter()-started; parts=[x for x in (q_fred,q_market,q_cftc) if isinstance(x,pd.DataFrame) and not x.empty]; quality=pd.concat(parts,ignore_index=True) if parts else pd.DataFrame()
    _com17_kpis(fred,market,cftc)
    _html(f'<div class="eq14-note"><b>{_escape(COM18_VERSION)}</b> · 54 retained charts + 34 nested additions = 88 · Wall load {elapsed:.1f}s · FRED {_escape(str(d_fred.get("provider","FRED")))} · Market {_escape(str(d_market.get("provider","market")))} · CFTC {_escape(str(d_cftc.get("provider","not requested")))} · USDA {_escape(str(d_wasde.get("provider","not requested")))} · active {_escape(main_view)}{(" / "+_escape(subview)) if subview else ""}.</div>')
    try:
        if main_view=="Dashboard": _com17_dashboard(fred,market,cftc,view_mode,smoothing)
        elif main_view=="Metals": _com18_metals_view(subview,fred,market,cftc,wasde,view_mode,smoothing)
        elif main_view=="Agriculture": _com18_agriculture_view(subview,fred,market,cftc,wasde,view_mode,smoothing)
        elif main_view=="Carbon & Bulk": _com18_carbon_view(subview,fred,market,cftc,wasde,view_mode,smoothing)
        elif main_view=="Chart Book": _com18_chart_book(fred,market,cftc,wasde,origin,family,view_mode,smoothing)
        else: _com18_quality(quality,q_wasde,{"elapsed":elapsed,"fred":d_fred,"market":d_market,"cftc":d_cftc,"wasde":d_wasde})
    except Exception as exc:
        st.error(f"Commodities V18 route failed: {type(exc).__name__}: {exc}")
        with st.expander("Commodities V18 traceback",expanded=False):
            import traceback as _com18_traceback
            st.code(_com18_traceback.format_exc())


