def _com19_pick(work: pd.DataFrame, exact: Sequence[str], contains: Sequence[str] = ()) -> Optional[str]:
    cols = {str(c).strip().lower(): str(c) for c in work.columns}
    for candidate in exact:
        key = str(candidate).strip().lower()
        if key in cols:
            return cols[key]
    if contains:
        for key, original in cols.items():
            if all(token in key for token in contains):
                return original
    return None


def _com19_numeric(work: pd.DataFrame, col: Optional[str]) -> pd.Series:
    if not col or col not in work:
        return pd.Series(np.nan, index=work.index, dtype=float)
    return pd.to_numeric(work[col], errors="coerce")


def _com19_last_rank(values: np.ndarray) -> float:
    arr = pd.Series(values).dropna()
    if arr.empty:
        return np.nan
    return float(arr.rank(pct=True).iloc[-1] * 100.0)


def _com19_cftc_parse(raw: pd.DataFrame) -> pd.DataFrame:
    columns = [
        "date", "code", "name", "open_interest",
        "mm_long", "mm_short", "mm_spread", "mm_net",
        "producer_long", "producer_short", "producer_net",
        "swap_long", "swap_short", "swap_spread", "swap_net",
        "other_long", "other_short", "other_net",
        "weekly_change", "four_week_change", "long_weekly_change", "short_weekly_change",
        "zscore_104w", "percentile_52w", "net_pct_oi", "long_pct_oi",
        "short_pct_oi", "gross_pct_oi", "producer_net_pct_oi", "swap_net_pct_oi",
        # Legacy aliases retained for frozen V17/V18 renderers.
        "net", "zscore",
    ]
    if not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=columns)
    work = raw.copy()
    work.columns = [str(c).strip().lower() for c in work.columns]
    date_col = _com19_pick(work, ("report_date_as_yyyy_mm_dd", "report_date"), ("report", "date"))
    code_col = _com19_pick(work, ("cftc_contract_market_code", "contract_market_code"), ("contract", "market", "code"))
    name_col = _com19_pick(work, ("market_and_exchange_names", "market_and_exchange_name"), ("market", "exchange"))
    oi_col = _com19_pick(work, ("open_interest_all",), ("open_interest",))
    mm_long_col = _com19_pick(work, ("m_money_positions_long_all", "m_money_positions_long"), ("m_money", "positions", "long"))
    mm_short_col = _com19_pick(work, ("m_money_positions_short_all", "m_money_positions_short"), ("m_money", "positions", "short"))
    mm_spread_col = _com19_pick(work, ("m_money_positions_spread_all", "m_money_positions_spread"), ("m_money", "positions", "spread"))
    producer_long_col = _com19_pick(work, ("prod_merc_positions_long_all", "prod_merc_positions_long"), ("prod", "merc", "long"))
    producer_short_col = _com19_pick(work, ("prod_merc_positions_short_all", "prod_merc_positions_short"), ("prod", "merc", "short"))
    swap_long_col = _com19_pick(work, ("swap_positions_long_all", "swap_positions_long"), ("swap", "positions", "long"))
    swap_short_col = _com19_pick(work, ("swap_positions_short_all", "swap_positions_short"), ("swap", "positions", "short"))
    swap_spread_col = _com19_pick(work, ("swap_positions_spread_all", "swap_positions_spread"), ("swap", "positions", "spread"))
    other_long_col = _com19_pick(work, ("other_rept_positions_long_all", "other_rept_positions_long"), ("other", "rept", "long"))
    other_short_col = _com19_pick(work, ("other_rept_positions_short_all", "other_rept_positions_short"), ("other", "rept", "short"))
    if not all((date_col, code_col, mm_long_col, mm_short_col)):
        return pd.DataFrame(columns=columns)
    out = pd.DataFrame({
        "date": pd.to_datetime(work[date_col], errors="coerce"),
        "code": work[code_col].astype(str).str.strip().str.replace(r"\.0$", "", regex=True).str.zfill(6),
        "name": work[name_col].astype(str) if name_col else "",
        "open_interest": _com19_numeric(work, oi_col),
        "mm_long": _com19_numeric(work, mm_long_col),
        "mm_short": _com19_numeric(work, mm_short_col),
        "mm_spread": _com19_numeric(work, mm_spread_col),
        "producer_long": _com19_numeric(work, producer_long_col),
        "producer_short": _com19_numeric(work, producer_short_col),
        "swap_long": _com19_numeric(work, swap_long_col),
        "swap_short": _com19_numeric(work, swap_short_col),
        "swap_spread": _com19_numeric(work, swap_spread_col),
        "other_long": _com19_numeric(work, other_long_col),
        "other_short": _com19_numeric(work, other_short_col),
    })
    out["mm_net"] = out["mm_long"] - out["mm_short"]
    out["producer_net"] = out["producer_long"] - out["producer_short"]
    out["swap_net"] = out["swap_long"] - out["swap_short"]
    out["other_net"] = out["other_long"] - out["other_short"]
    out = out.dropna(subset=["date", "code", "mm_net"]).sort_values(["code", "date"]).drop_duplicates(["code", "date"], keep="last")
    grouped = out.groupby("code", group_keys=False)
    out["weekly_change"] = grouped["mm_net"].diff(1)
    out["four_week_change"] = grouped["mm_net"].diff(4)
    out["long_weekly_change"] = grouped["mm_long"].diff(1)
    out["short_weekly_change"] = grouped["mm_short"].diff(1)
    roll_mean = grouped["mm_net"].transform(lambda s: s.rolling(104, min_periods=52).mean())
    roll_std = grouped["mm_net"].transform(lambda s: s.rolling(104, min_periods=52).std(ddof=0)).replace(0, np.nan)
    out["zscore_104w"] = (out["mm_net"] - roll_mean) / roll_std
    out["percentile_52w"] = grouped["mm_net"].transform(
        lambda s: s.rolling(52, min_periods=26).apply(_com19_last_rank, raw=True)
    )
    oi = out["open_interest"].replace(0, np.nan)
    out["net_pct_oi"] = out["mm_net"] / oi * 100.0
    out["long_pct_oi"] = out["mm_long"] / oi * 100.0
    out["short_pct_oi"] = out["mm_short"] / oi * 100.0
    out["gross_pct_oi"] = (out["mm_long"] + out["mm_short"]) / oi * 100.0
    out["producer_net_pct_oi"] = out["producer_net"] / oi * 100.0
    out["swap_net_pct_oi"] = out["swap_net"] / oi * 100.0
    out["net"] = out["mm_net"]
    out["zscore"] = out["zscore_104w"]
    return out.reset_index(drop=True)[columns]


@st.cache_data(ttl=21600, show_spinner=False)
def _com19_load_cftc(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter()
    cache = COM19_CACHE_DIR / "cftc_agriculture_disaggregated.csv"
    raw = pd.DataFrame()
    status = "provider-unavailable"
    source = "CFTC Disaggregated Futures Only"
    message = ""
    age = _com17_cache_age_hours(cache)
    if not refresh_token and cache.exists() and age is not None and age <= 12.0:
        try:
            raw = pd.read_csv(cache, dtype={"cftc_contract_market_code": str, "code": str})
            status, message = "cache", "fresh disk cache"
        except Exception as exc:
            message = str(exc)
    if raw.empty and REQUESTS_AVAILABLE:
        try:
            codes = ",".join(f"'{x}'" for x in COM19_CFTC_CODES.values())
            params = {
                "$where": f"cftc_contract_market_code in ({codes}) AND report_date_as_yyyy_mm_dd >= '2014-01-01T00:00:00.000'",
                "$limit": "50000",
                "$order": "report_date_as_yyyy_mm_dd ASC",
            }
            response = requests.get(
                "https://publicreporting.cftc.gov/resource/72hh-3qpy.json",
                params=params,
                timeout=(4.0, 14.0),
                headers={"User-Agent": "Mozilla/5.0 QuantTerminal-MarketDesk/19.0", "Accept": "application/json"},
            )
            response.raise_for_status()
            raw = pd.DataFrame(response.json())
            parsed = _com19_cftc_parse(raw)
            if parsed.empty:
                raise ValueError("CFTC response did not contain compatible Disaggregated fields")
            raw.to_csv(cache, index=False)
            status, message = "live", "official Socrata API"
        except Exception as exc:
            message = str(exc)
    if raw.empty and cache.exists():
        try:
            raw = pd.read_csv(cache, dtype={"cftc_contract_market_code": str, "code": str})
            status, message = "stale-cache", message or "stale disk cache"
        except Exception:
            pass
    # Last compatibility fallback: use the V17 raw cache if it contains the richer columns.
    legacy_cache = COM17_CACHE_DIR / "cftc_disaggregated.csv"
    if raw.empty and legacy_cache.exists():
        try:
            candidate = pd.read_csv(legacy_cache, dtype={"cftc_contract_market_code": str, "code": str})
            if not _com19_cftc_parse(candidate).empty:
                raw = candidate
                status, message = "stale-cache", "compatible V17 raw cache"
        except Exception:
            pass
    parsed = _com19_cftc_parse(raw)
    frames: Dict[str, pd.DataFrame] = {}
    rows: List[Dict[str, Any]] = []
    for commodity, code in COM19_CFTC_CODES.items():
        use = parsed.loc[parsed["code"] == str(code).zfill(6)].copy() if not parsed.empty else pd.DataFrame()
        frames[commodity] = use.reset_index(drop=True)
        latest = pd.Timestamp(use["date"].max()) if not use.empty else None
        rows.append({
            "Series / Instrument": f"CFTC:{commodity}",
            "Label": f"{commodity} Disaggregated COT",
            "Category": "Agriculture Positioning",
            "Source": source,
            "Status": status if not use.empty else "provider-unavailable",
            "Freshness": _cr12_freshness(latest, 14) if latest is not None else "Missing",
            "Observations": len(use),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None else "—",
            "Unit": "Contracts / % OI",
            "Frequency": "Weekly",
            "Message": message,
        })
    # Preserve frozen V17/V18 consumers that use the shorter Wheat key.
    frames["Wheat"] = frames.get("Wheat SRW", pd.DataFrame()).copy()
    return frames, pd.DataFrame(rows), {
        "elapsed": time.perf_counter() - started,
        "provider": source,
        "status": status,
        "message": message,
        "coverage": sum(1 for name in COM19_CFTC_CODES if isinstance(frames.get(name), pd.DataFrame) and not frames.get(name).empty),
        "expected": len(COM19_CFTC_CODES),
    }


# The official USDA page publishes one consolidated CSV per release. V18 used the correct
# filename pattern but did not discover Drupal links and rejected valid files returned with
# text/plain or attachment headers. V19 validates the CSV signature instead of MIME metadata.
@st.cache_data(ttl=21600, show_spinner=False)
def _com19_load_wasde(refresh_token: int = 0) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    started = time.perf_counter()
    cache = COM19_CACHE_DIR / "wasde_consolidated_latest.csv"
    meta_file = COM19_CACHE_DIR / "wasde_consolidated_latest_meta.txt"
    raw = pd.DataFrame()
    source, status, message = "USDA Historical WASDE Report Data", "provider-unavailable", ""
    age = _com17_cache_age_hours(cache)
    if not refresh_token and cache.exists() and age is not None and age <= 240.0:
        try:
            raw = pd.read_csv(cache, low_memory=False)
            status, message = "cache", "fresh official disk cache"
        except Exception as exc:
            message = str(exc)
    if raw.empty and REQUESTS_AVAILABLE:
        headers = {
            "User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/126 Safari/537.36",
            "Accept": "text/csv,text/plain,*/*",
            "Referer": "https://www.usda.gov/historical-wasde-report-data-3",
        }
        now = pd.Timestamp.utcnow().tz_localize(None)
        candidates: List[str] = []
        for back in range(0, 8):
            d = now - pd.DateOffset(months=back)
            candidates.append(f"https://www.usda.gov/sites/default/files/documents/oce-wasde-report-data-{d.year}-{d.month:02d}.csv")
        # Discover the current Drupal links if the filename policy changes.
        try:
            page = requests.get("https://www.usda.gov/historical-wasde-report-data-3", timeout=(3.0, 10.0), headers=headers)
            if page.ok:
                found = _com19_re.findall(r'href=["\']([^"\']*oce-wasde-report-data-[0-9]{4}-[0-9]{2}\.csv[^"\']*)', page.text, flags=_com19_re.I)
                for href in found:
                    if href.startswith("/"):
                        href = "https://www.usda.gov" + href
                    if href not in candidates:
                        candidates.insert(0, href)
        except Exception:
            pass
        for url in candidates:
            try:
                r = requests.get(url, timeout=(4.0, 14.0), headers=headers, allow_redirects=True)
                content = r.content or b""
                signature = content[:250].decode("utf-8", errors="ignore").lower()
                if r.status_code < 400 and len(content) > 5000 and "wasdenumber" in signature and "reportdate" in signature:
                    candidate = pd.read_csv(io.BytesIO(content), low_memory=False)
                    if not candidate.empty:
                        raw = candidate
                        raw.to_csv(cache, index=False)
                        meta_file.write_text(url, encoding="utf-8")
                        status, message = "live", url
                        break
            except Exception as exc:
                message = str(exc)
    if raw.empty and cache.exists():
        try:
            raw = pd.read_csv(cache, low_memory=False)
            status = "stale-cache"
            message = meta_file.read_text(encoding="utf-8") if meta_file.exists() else (message or "stale official cache")
        except Exception as exc:
            message = str(exc)
    if raw.empty:
        quality = pd.DataFrame([{
            "Series / Instrument": "USDA:WASDE",
            "Label": "Historical WASDE report data",
            "Category": "Agriculture Fundamentals",
            "Source": source,
            "Status": status,
            "Freshness": "Missing",
            "Observations": 0,
            "Latest Date": "—",
            "Unit": "Mixed",
            "Frequency": "Monthly release",
            "Message": message or "Official CSV unavailable; no imputation.",
        }])
        return pd.DataFrame(), quality, {
            "elapsed": time.perf_counter() - started, "provider": source,
            "status": status, "message": message,
        }
    cols = list(raw.columns)
    mapping = {
        "wasde_number": _com18_pick_column(cols, ["WasdeNumber", "WASDE Number"]),
        "report_date": _com18_pick_column(cols, ["ReportDate", "Report Date"]),
        "report_title": _com18_pick_column(cols, ["ReportTitle", "Report Title"]),
        "attribute": _com18_pick_column(cols, ["Attribute", "Attribute Name", "Item"]),
        "commodity": _com18_pick_column(cols, ["Commodity", "Commodity Name"]),
        "region": _com18_pick_column(cols, ["Region", "Country", "Geography"]),
        "market_year": _com18_pick_column(cols, ["MarketYear", "Market Year", "Marketing Year"]),
        "proj_est_flag": _com18_pick_column(cols, ["ProjEstFlag", "Projection Estimate Flag"]),
        "annual_quarter_flag": _com18_pick_column(cols, ["AnnualQuarterFlag", "Annual Quarter Flag"]),
        "value": _com18_pick_column(cols, ["Value", "Forecast Value"]),
        "unit": _com18_pick_column(cols, ["Unit", "Units"]),
    }
    if not all(mapping.get(k) for k in ("report_date", "commodity", "attribute", "value")):
        quality = pd.DataFrame([{
            "Series / Instrument": "USDA:WASDE", "Label": "Historical WASDE report data",
            "Category": "Agriculture Fundamentals", "Source": source, "Status": "schema-error",
            "Freshness": "Missing", "Observations": len(raw), "Latest Date": "—", "Unit": "Mixed",
            "Frequency": "Monthly release", "Message": f"Unrecognized schema: {list(raw.columns)[:12]}",
        }])
        return pd.DataFrame(), quality, {"elapsed": time.perf_counter()-started, "provider": source, "status": "schema-error", "message": "unrecognized schema"}
    out = pd.DataFrame(index=raw.index)
    for target, original in mapping.items():
        if original:
            out[target] = raw[original]
    for col in ("report_title", "attribute", "commodity", "region", "market_year", "proj_est_flag", "annual_quarter_flag", "unit"):
        out[col] = out.get(col, pd.Series("", index=out.index)).astype(str).str.strip()
    out["release_date"] = pd.to_datetime(out["report_date"], errors="coerce")
    out["value"] = pd.to_numeric(out["value"].astype(str).str.replace(",", "", regex=False), errors="coerce")
    out = out.dropna(subset=["release_date", "value"]).sort_values("release_date").reset_index(drop=True)
    latest = out["release_date"].max()
    quality = pd.DataFrame([{
        "Series / Instrument": "USDA:WASDE", "Label": "Historical WASDE report data",
        "Category": "Agriculture Fundamentals", "Source": source, "Status": status,
        "Freshness": _cr12_freshness(latest, 45), "Observations": len(out),
        "Latest Date": latest.strftime("%Y-%m-%d"), "Unit": "Mixed",
        "Frequency": "Monthly release", "Message": message,
    }])
    return out, quality, {
        "elapsed": time.perf_counter() - started, "provider": source,
        "status": status, "message": message,
    }


def _com19_wasde_rows(wasde: pd.DataFrame, commodity: str, region: str = "United States") -> pd.DataFrame:
    if not isinstance(wasde, pd.DataFrame) or wasde.empty:
        return pd.DataFrame()
    use = wasde.copy()
    c = use["commodity"].astype(str).str.lower()
    aliases = {
        "corn": ("corn",),
        "wheat": ("wheat",),
        "soybeans": ("soybean",),
        "cotton": ("cotton",),
        "sugar": ("sugar",),
        "milk": ("milk",),
    }
    mask = pd.Series(False, index=use.index)
    for token in aliases.get(commodity.lower(), (commodity.lower(),)):
        mask |= c.str.contains(token, na=False)
    use = use.loc[mask].copy()
    if region and "region" in use:
        r = use["region"].astype(str).str.lower()
        preferred = r.str.contains(r"united states|u\.s\.|usa", regex=True, na=False)
        if preferred.any():
            use = use.loc[preferred].copy()
    return use


def _com19_attr_value(frame: pd.DataFrame, patterns: Sequence[str]) -> float:
    if frame.empty:
        return np.nan
    attr = frame["attribute"].astype(str).str.lower()
    for pattern in patterns:
        hit = frame.loc[attr.str.contains(pattern, regex=True, na=False)]
        if not hit.empty:
            return float(hit.sort_values("release_date")["value"].iloc[-1])
    return np.nan


def _com19_wasde_latest_balance(wasde: pd.DataFrame, commodity: str) -> pd.DataFrame:
    use = _com19_wasde_rows(wasde, commodity)
    if use.empty:
        return pd.DataFrame()
    latest_release = use["release_date"].max()
    use = use.loc[use["release_date"] == latest_release].copy()
    years = sorted(use["market_year"].dropna().astype(str).unique())[-4:]
    rows: List[Dict[str, Any]] = []
    for year in years:
        yy = use.loc[use["market_year"].astype(str) == year].copy()
        beginning = _com19_attr_value(yy, (r"^beginning stock",))
        production = _com19_attr_value(yy, (r"^production$", r"production"))
        imports = _com19_attr_value(yy, (r"^imports?$",))
        exports = _com19_attr_value(yy, (r"^exports?$",))
        ending = _com19_attr_value(yy, (r"^ending stock",))
        domestic = _com19_attr_value(yy, (r"domestic.*total", r"total domestic", r"domestic use", r"total use"))
        # Some U.S. grain tables publish demand components separately.
        if pd.isna(domestic):
            components = [
                _com19_attr_value(yy, (r"^feed.*residual",)),
                _com19_attr_value(yy, (r"^food",)),
                _com19_attr_value(yy, (r"^seed",)),
                _com19_attr_value(yy, (r"^crush",)),
                _com19_attr_value(yy, (r"^residual",)),
            ]
            finite = [x for x in components if pd.notna(x)]
            domestic = float(sum(finite)) if finite else np.nan
        total_use = domestic + exports if pd.notna(domestic) and pd.notna(exports) else domestic
        stocks_use = ending / total_use * 100.0 if pd.notna(ending) and pd.notna(total_use) and total_use != 0 else np.nan
        unit_values = yy["unit"].dropna().astype(str)
        rows.append({
            "Market year": year,
            "Beginning Stocks": beginning,
            "Production": production,
            "Imports": imports,
            "Domestic Use": domestic,
            "Exports": exports,
            "Total Use": total_use,
            "Ending Stocks": ending,
            "Stocks / Use %": stocks_use,
            "Unit": unit_values.iloc[-1] if not unit_values.empty else "Reported units",
            "Release": latest_release,
        })
    return pd.DataFrame(rows)


def _com19_wasde_stock_use_history(wasde: pd.DataFrame, commodity: str) -> pd.DataFrame:
    use = _com19_wasde_rows(wasde, commodity)
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    rows: List[Dict[str, Any]] = []
    for release, block in use.groupby("release_date"):
        years = sorted(block["market_year"].dropna().astype(str).unique())
        if not years:
            continue
        year = years[-1]
        yy = block.loc[block["market_year"].astype(str) == year]
        ending = _com19_attr_value(yy, (r"^ending stock",))
        domestic = _com19_attr_value(yy, (r"domestic.*total", r"total domestic", r"domestic use", r"total use"))
        if pd.isna(domestic):
            components = [
                _com19_attr_value(yy, (r"^feed.*residual",)),
                _com19_attr_value(yy, (r"^food",)),
                _com19_attr_value(yy, (r"^seed",)),
                _com19_attr_value(yy, (r"^crush",)),
            ]
            finite = [x for x in components if pd.notna(x)]
            domestic = float(sum(finite)) if finite else np.nan
        exports = _com19_attr_value(yy, (r"^exports?$",))
        total_use = domestic + exports if pd.notna(domestic) and pd.notna(exports) else domestic
        if pd.notna(ending) and pd.notna(total_use) and total_use != 0:
            rows.append({"date": pd.Timestamp(release), "value": ending / total_use * 100.0})
    return _eq14_norm(pd.DataFrame(rows))


def _com19_wasde_revision_history(wasde: pd.DataFrame, commodity: str, attribute: str = "Ending Stocks") -> pd.DataFrame:
    use = _com19_wasde_rows(wasde, commodity)
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    pattern = r"ending stock" if attribute.lower().startswith("ending") else attribute.lower()
    attr = use["attribute"].astype(str).str.lower()
    use = use.loc[attr.str.contains(pattern, regex=True, na=False)].copy()
    if use.empty:
        return pd.DataFrame(columns=["date", "value"])
    # For each release, use the furthest projected marketing year available.
    rows = []
    for release, block in use.groupby("release_date"):
        years = sorted(block["market_year"].dropna().astype(str).unique())
        if not years:
            continue
        value = block.loc[block["market_year"].astype(str) == years[-1], "value"]
        if not value.empty:
            rows.append({"date": pd.Timestamp(release), "value": float(value.iloc[-1])})
    return _eq14_norm(pd.DataFrame(rows))


def _com19_cftc_summary(cftc: Mapping[str, pd.DataFrame], names: Optional[Sequence[str]] = None) -> pd.DataFrame:
    selected = tuple(names) if names is not None else tuple(COM19_CFTC_CODES)
    rows: List[Dict[str, Any]] = []
    for name in selected:
        use = cftc.get(name, pd.DataFrame())
        if use is None or use.empty:
            continue
        row = use.iloc[-1]
        rows.append({
            "Commodity": name,
            "Managed Money Long": int(row["mm_long"]) if pd.notna(row["mm_long"]) else np.nan,
            "Managed Money Short": int(row["mm_short"]) if pd.notna(row["mm_short"]) else np.nan,
            "Net contracts": int(row["mm_net"]) if pd.notna(row["mm_net"]) else np.nan,
            "Weekly Δ": int(row["weekly_change"]) if pd.notna(row["weekly_change"]) else np.nan,
            "4W Δ": int(row["four_week_change"]) if pd.notna(row["four_week_change"]) else np.nan,
            "Net / OI %": round(float(row["net_pct_oi"]), 2) if pd.notna(row["net_pct_oi"]) else np.nan,
            "Long / OI %": round(float(row["long_pct_oi"]), 2) if pd.notna(row["long_pct_oi"]) else np.nan,
            "Short / OI %": round(float(row["short_pct_oi"]), 2) if pd.notna(row["short_pct_oi"]) else np.nan,
            "Gross / OI %": round(float(row["gross_pct_oi"]), 2) if pd.notna(row["gross_pct_oi"]) else np.nan,
            "52W percentile": round(float(row["percentile_52w"]), 1) if pd.notna(row["percentile_52w"]) else np.nan,
            "104W z-score": round(float(row["zscore_104w"]), 2) if pd.notna(row["zscore_104w"]) else np.nan,
            "Producer net / OI %": round(float(row["producer_net_pct_oi"]), 2) if pd.notna(row["producer_net_pct_oi"]) else np.nan,
            "Swap net / OI %": round(float(row["swap_net_pct_oi"]), 2) if pd.notna(row["swap_net_pct_oi"]) else np.nan,
            "Open interest": int(row["open_interest"]) if pd.notna(row["open_interest"]) else np.nan,
            "Latest": pd.Timestamp(row["date"]).strftime("%d %b %Y"),
        })
    return pd.DataFrame(rows)


def _com19_position_bar(title: str, subtitle: str, table: pd.DataFrame, field: str, unit: str, diverging: bool = True) -> None:
    if table.empty or field not in table:
        _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="CFTC positioning unavailable.")
        return
    use = table.dropna(subset=[field]).sort_values(field)
    fig = _fi10_base_figure(unit, 410)
    values = use[field].astype(float)
    colors = ["#72c48f" if v >= 0 else "#e87557" for v in values] if diverging else [COM18_COLORS[i % len(COM18_COLORS)] for i in range(len(use))]
    fig.add_trace(go.Bar(y=use["Commodity"], x=values, orientation="h", marker_color=colors, name=field, hovertemplate="%{y}<br>%{x:,.2f}<extra></extra>"))
    if diverging:
        fig.add_vline(x=0, line_color="rgba(255,255,255,.35)", line_width=1)
    _liq5_render_chart_card(title, subtitle, fig, [("CFTC Disaggregated Futures Only", "gold")], "Latest weekly report")


def _com19_position_history_heatmap(title: str, subtitle: str, cftc: Mapping[str, pd.DataFrame], names: Sequence[str], weeks: int = 52) -> None:
    series: Dict[str, pd.Series] = {}
    for name in names:
        frame = cftc.get(name, pd.DataFrame())
        if frame is None or frame.empty:
            continue
        use = frame[["date", "zscore_104w"]].dropna().tail(weeks)
        if not use.empty:
            series[name] = use.set_index("date")["zscore_104w"]
    if not series:
        _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="Positioning history unavailable.")
        return
    panel = pd.concat(series, axis=1).sort_index().tail(weeks).T
    dates = [pd.Timestamp(x).strftime("%b %y") for x in panel.columns]
    _fi10_heatmap_card(title, subtitle, panel.to_numpy(), dates, list(panel.index), ".2f", "104-week managed-money z-score", 0)


def _com19_selected_positioning_cards(name: str, frame: pd.DataFrame, price: pd.DataFrame) -> None:
    if frame is None or frame.empty:
        _liq5_render_chart_card(f"{name} positioning detail", "Managed Money, commercial hedgers and open interest.", None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="Selected contract unavailable.")
        return
    use = frame.copy()

    def gross_card() -> None:
        fig = _fi10_base_figure("Contracts", 410)
        fig.add_trace(go.Bar(x=use["date"], y=use["mm_long"], name="Managed Money long", marker_color="#72c48f"))
        fig.add_trace(go.Bar(x=use["date"], y=-use["mm_short"], name="Managed Money short", marker_color="#e87557"))
        fig.add_trace(go.Scatter(x=use["date"], y=use["mm_net"], name="Managed Money net", mode="lines", line=dict(color="#f0c94d", width=2.3)))
        fig.update_layout(barmode="relative")
        fig.add_hline(y=0, line_color="rgba(255,255,255,.3)", line_width=1)
        _liq5_render_chart_card(f"{name} - managed-money long, short and net", "Gross exposure and directional net positioning.", fig, [("CFTC Disaggregated Futures Only", "gold")], "Weekly futures-only report")

    def participants_card() -> None:
        fig = _fi10_base_figure("Net contracts", 410)
        fig.add_trace(go.Scatter(x=use["date"], y=use["mm_net"], name="Managed Money net", mode="lines", line=dict(color="#72b9e6", width=2.2)))
        if use["producer_net"].notna().any():
            fig.add_trace(go.Scatter(x=use["date"], y=use["producer_net"], name="Producer/Merchant net", mode="lines", line=dict(color="#e87557", width=1.8)))
        if use["swap_net"].notna().any():
            fig.add_trace(go.Scatter(x=use["date"], y=use["swap_net"], name="Swap Dealer net", mode="lines", line=dict(color="#f0c94d", width=1.5, dash="dot")))
        fig.add_hline(y=0, line_color="rgba(255,255,255,.3)", line_width=1)
        _liq5_render_chart_card(f"{name} - trader-category positioning", "Managed Money against Producer/Merchant and Swap Dealer net positions.", fig, [("CFTC Disaggregated Futures Only", "gold")], "Weekly participant categories")

    def regime_card() -> None:
        z = use[["date", "zscore_104w"]].rename(columns={"zscore_104w": "value"}).dropna()
        pct = use[["date", "percentile_52w"]].rename(columns={"percentile_52w": "value"}).dropna()
        _com17_line_card(
            f"{name} - positioning regime", "Rolling 104-week z-score and 52-week percentile.",
            [("104W z-score", z), ("52W percentile", pct)], "Z-score", "CFTC Disaggregated Futures Only", "Levels", "Raw",
            allow_yoy=False, second_axis=["52W percentile"], right_title="Percentile", y_policy="signed", y2_policy="positive",
        )

    def participation_card() -> None:
        oi = use[["date", "open_interest"]].rename(columns={"open_interest": "value"}).dropna()
        gross = use[["date", "gross_pct_oi"]].rename(columns={"gross_pct_oi": "value"}).dropna()
        _com17_line_card(
            f"{name} - open interest and participation", "Total open interest and Managed Money gross participation as a share of OI.",
            [("Open interest", oi), ("Managed Money gross / OI", gross)], "Contracts", "CFTC Disaggregated Futures Only", "Levels", "Raw",
            allow_yoy=False, second_axis=["Managed Money gross / OI"], right_title="% OI", y_policy="positive", y2_policy="positive",
        )

    _liq6_two_column([gross_card, participants_card, regime_card, participation_card])

    if isinstance(price, pd.DataFrame) and not price.empty:
        p = _com17_norm(price)
        aligned = pd.merge_asof(
            use[["date", "zscore_104w"]].dropna().sort_values("date"),
            p[["date", "value"]].dropna().sort_values("date"),
            on="date", direction="backward", tolerance=pd.Timedelta(days=7),
        ).dropna()
        if not aligned.empty:
            fig = _fi10_base_figure("Price", 420)
            fig.add_trace(go.Scatter(x=aligned["date"], y=aligned["value"], name="Futures price", mode="lines", line=dict(color="#72b9e6", width=2.1)))
            fig.add_trace(go.Scatter(x=aligned["date"], y=aligned["zscore_104w"], name="CFTC z-score", mode="lines", yaxis="y2", line=dict(color="#f0c94d", width=1.8)))
            fig.update_layout(yaxis2=dict(title="104W z-score", overlaying="y", side="right", showgrid=False, zeroline=True))
            _liq5_render_chart_card(f"{name} - price versus positioning", "Nearby continuous-futures proxy against Managed Money crowding.", fig, [("Yahoo/yfinance + CFTC", "gold")], "Weekly aligned observations")

def _com19_agri_kpis(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], wasde: pd.DataFrame, subview: str = "") -> None:
    coverage = sum(1 for name in COM19_CFTC_CODES if isinstance(cftc.get(name), pd.DataFrame) and not cftc.get(name).empty)
    cftc_requested = subview in ("Overview", "Positioning", "Valuation")
    wasde_requested = subview == "Fundamentals"
    latest_wasde = wasde["release_date"].max() if isinstance(wasde, pd.DataFrame) and not wasde.empty else None
    wheat = _com17_latest(market.get("ZW=F", pd.DataFrame()))
    corn = _com17_latest(market.get("ZC=F", pd.DataFrame()))
    beans = _com17_latest(market.get("ZS=F", pd.DataFrame()))
    coffee = _com17_latest(market.get("KC=F", pd.DataFrame()))
    cattle = _com17_latest(market.get("LE=F", pd.DataFrame()))
    cards = [
        ("WHEAT", _fmt(wheat, 2), "CBOT nearby continuous"),
        ("CORN", _fmt(corn, 2), "CBOT nearby continuous"),
        ("SOYBEANS", _fmt(beans, 2), "CBOT nearby continuous"),
        ("COFFEE", _fmt(coffee, 2), "ICE nearby continuous"),
        ("LIVE CATTLE", _fmt(cattle, 2), "CME nearby continuous"),
        ("CFTC COVERAGE", f"{coverage}/{len(COM19_CFTC_CODES)}" if cftc_requested else "LAZY", "Loaded only for Overview / Positioning / Valuation"),
        ("WASDE", _liq5_fmt_date(latest_wasde) if latest_wasde is not None else ("UNAVAILABLE" if wasde_requested else "LAZY"), "Loaded only for Fundamentals"),
        ("IMF FOOD", _fmt(_com17_latest(fred.get("PFOODINDEXM", pd.DataFrame())), 2), "Monthly benchmark index"),
    ]
    columns = st.columns(4)
    for i, (label, value, sub) in enumerate(cards):
        with columns[i % 4]:
            _kpi_card(label, value, sub)
        if i == 3:
            columns = st.columns(4)


