def _com19_render_position_spec(spec: Mapping[str, Any], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame]) -> None:
    title = f'{int(spec["n"])}. {spec["title"]}'
    subtitle = str(spec.get("subtitle", ""))
    kind = str(spec.get("kind", ""))
    table = _com19_cftc_summary(cftc)
    if kind == "com19_cftc_bar":
        _com19_position_bar(title, subtitle, table, str(spec.get("metric")), str(spec.get("unit", "")), bool(spec.get("diverging", True)))
    elif kind == "com19_cftc_history_heatmap":
        _com19_position_history_heatmap(title, subtitle, cftc, tuple(COM19_CFTC_CODES), 52)
    elif kind == "com19_participant_scatter":
        if table.empty:
            _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="CFTC positioning unavailable.")
        else:
            fig = _fi10_base_figure("Producer net / OI %", 420)
            for i, row in table.dropna(subset=["Producer net / OI %", "Net / OI %"]).iterrows():
                fig.add_trace(go.Scatter(x=[row["Producer net / OI %"]], y=[row["Net / OI %"]], mode="markers+text", text=[row["Commodity"]], textposition="top center", name=row["Commodity"], marker=dict(size=10, color=COM18_COLORS[i % len(COM18_COLORS)])))
            fig.update_xaxes(title="Producer/Merchant net / OI %")
            fig.update_yaxes(title="Managed Money net / OI %")
            fig.add_hline(y=0, line_color="rgba(255,255,255,.25)")
            fig.add_vline(x=0, line_color="rgba(255,255,255,.25)")
            _liq5_render_chart_card(title, subtitle, fig, [("CFTC Disaggregated Futures Only", "gold")], "Latest weekly report")
    elif kind == "com19_crowding_map":
        if table.empty:
            _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="CFTC positioning unavailable.")
        else:
            use = table.dropna(subset=["104W z-score", "4W Δ"])
            fig = _fi10_base_figure("Four-week net change", 420)
            for i, row in use.iterrows():
                size = 9 + 18 * np.sqrt(max(float(row.get("Open interest", 0)), 0) / max(float(use["Open interest"].max()), 1))
                fig.add_trace(go.Scatter(x=[row["104W z-score"]], y=[row["4W Δ"]], mode="markers+text", text=[row["Commodity"]], textposition="top center", name=row["Commodity"], marker=dict(size=size, color=COM18_COLORS[i % len(COM18_COLORS)])))
            fig.update_xaxes(title="104W z-score")
            fig.update_yaxes(title="4W change in net contracts")
            fig.add_hline(y=0, line_color="rgba(255,255,255,.25)")
            fig.add_vline(x=0, line_color="rgba(255,255,255,.25)")
            _liq5_render_chart_card(title, subtitle, fig, [("CFTC Disaggregated Futures Only", "gold")], "Bubble size = open interest")
    elif kind == "com19_long_short":
        if table.empty:
            _liq5_render_chart_card(title, subtitle, None, [("CFTC Disaggregated Futures Only", "gold")], empty_message="CFTC positioning unavailable.")
        else:
            use = table.sort_values("Long / OI %")
            fig = _fi10_base_figure("% open interest", 420)
            fig.add_trace(go.Bar(y=use["Commodity"], x=use["Long / OI %"], orientation="h", name="Long / OI", marker_color="#72c48f"))
            fig.add_trace(go.Bar(y=use["Commodity"], x=-use["Short / OI %"], orientation="h", name="Short / OI", marker_color="#e87557"))
            fig.update_layout(barmode="relative")
            fig.add_vline(x=0, line_color="rgba(255,255,255,.35)")
            _liq5_render_chart_card(title, subtitle, fig, [("CFTC Disaggregated Futures Only", "gold")], "Latest weekly report")
    elif kind == "com19_price_positioning":
        rows = []
        for name, sym in COM19_CFTC_TO_MARKET.items():
            frame = cftc.get(name, pd.DataFrame())
            z = frame["zscore_104w"].iloc[-1] if isinstance(frame, pd.DataFrame) and not frame.empty else np.nan
            ret = _com17_calendar_return(market.get(sym, pd.DataFrame()), 12)
            if pd.notna(z) and ret is not None:
                rows.append((name, float(z), float(ret)))
        if not rows:
            _liq5_render_chart_card(title, subtitle, None, [("CFTC + Yahoo/yfinance", "gold")], empty_message="Overlapping data unavailable.")
        else:
            fig = _fi10_base_figure("12M return %", 420)
            for i, (name, z, ret) in enumerate(rows):
                fig.add_trace(go.Scatter(x=[z], y=[ret], mode="markers+text", text=[name], textposition="top center", name=name, marker=dict(size=11, color=COM18_COLORS[i % len(COM18_COLORS)])))
            fig.update_xaxes(title="CFTC 104W z-score")
            fig.update_yaxes(title="12M futures return %")
            fig.add_hline(y=0, line_color="rgba(255,255,255,.25)")
            fig.add_vline(x=0, line_color="rgba(255,255,255,.25)")
            _liq5_render_chart_card(title, subtitle, fig, [("CFTC + Yahoo/yfinance", "gold")], "Latest overlapping inputs")


def _com19_positioning_view(market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame]) -> None:
    controls = st.columns([1.2, 1.5, 2.2])
    with controls[0]:
        group = st.selectbox("Positioning universe", list(COM19_CFTC_GROUPS), key="market_com19_position_group")
    names = COM19_CFTC_GROUPS.get(group, tuple(COM19_CFTC_CODES))
    available = [name for name in names if isinstance(cftc.get(name), pd.DataFrame) and not cftc.get(name).empty]
    with controls[1]:
        default = "Corn" if "Corn" in available else (available[0] if available else names[0])
        selected = st.selectbox("Contract drill-down", available or list(names), index=(available or list(names)).index(default), key="market_com19_position_contract")
    with controls[2]:
        _html('<div class="com18-intro"><b>Disaggregated COT:</b> Managed Money, Producer/Merchant and Swap Dealer positions. Tuesday observations are published weekly by the CFTC.</div>')

    table = _com19_cftc_summary(cftc, names)
    cards = [
        lambda: _com19_position_bar("Managed-Money net position", "Directional net contracts by agriculture market.", table, "Net contracts", "Contracts", True),
        lambda: _com19_position_bar("Managed-Money weekly impulse", "One-week change in net positioning.", table, "Weekly Δ", "Contracts", True),
        lambda: _com19_position_bar("Managed-Money net / open interest", "Cross-market normalization removes contract-size bias.", table, "Net / OI %", "% OI", True),
        lambda: _com19_position_bar("Managed-Money 52-week percentile", "Current net position ranked against the previous year.", table, "52W percentile", "Percentile", False),
    ]
    _liq6_two_column(cards)
    _liq6_two_column([
        lambda: _com19_render_position_spec(COM19_BY_N[94], market, cftc),
        lambda: _com19_render_position_spec(COM19_BY_N[95], market, cftc),
        lambda: _com19_render_position_spec(COM19_BY_N[96], market, cftc),
        lambda: _com19_render_position_spec(COM19_BY_N[97], market, cftc),
    ])
    _com19_position_history_heatmap("Positioning regime history", "Last 52 weekly 104-week z-scores for the selected group.", cftc, names, 52)
    symbol = COM19_CFTC_TO_MARKET.get(selected, "")
    _com19_selected_positioning_cards(selected, cftc.get(selected, pd.DataFrame()), market.get(symbol, pd.DataFrame()))
    # The detailed table follows at full width.
    _liq5_table_card(
        "CFTC Agriculture Positioning Monitor",
        "Long, short, net, weekly impulse, crowding, participant categories and open-interest normalization.",
        table,
        [("CFTC Disaggregated Futures Only", "gold")],
        "Latest weekly reports",
        40,
    )


def _com19_fundamentals_view(wasde: pd.DataFrame, wasde_quality: pd.DataFrame) -> None:
    if wasde.empty:
        _liq5_render_chart_card(
            "USDA WASDE fundamentals",
            "Official consolidated historical WASDE CSV could not be loaded.",
            None,
            [("USDA Historical WASDE Report Data", "gold")],
            empty_message="Provider unavailable. Data Quality shows the exact network or schema state; no balance sheet is fabricated.",
        )
        _liq5_table_card("WASDE Provider State", "Official monthly release contract.", wasde_quality, [("No silent imputation", "live")], "Current provider state", 12)
        return
    cards = []
    for commodity in ("Corn", "Wheat", "Soybeans"):
        frame = _com19_wasde_stock_use_history(wasde, commodity)
        cards.append(lambda commodity=commodity, frame=frame: _com17_line_card(
            f"US {commodity} stocks-to-use",
            "Latest projected marketing-year ending stocks relative to total use (domestic use plus exports) across WASDE releases.",
            [(f"{commodity} stocks/use", frame)], "%", "USDA Historical WASDE Report Data",
            "Levels", "Raw", allow_yoy=False, y_policy="positive",
        ))
    _liq6_two_column(cards)
    revision_items = [(commodity, _com19_wasde_revision_history(wasde, commodity)) for commodity in ("Corn", "Wheat", "Soybeans")]
    _com17_line_card(
        "WASDE ending-stocks revision pulse",
        "Release-to-release evolution of the furthest projected U.S. marketing-year ending stocks.",
        revision_items, "Reported units", "USDA Historical WASDE Report Data", "Levels", "Raw",
        allow_yoy=False, y_policy="positive",
    )
    latest_rows = []
    for commodity in ("Corn", "Wheat", "Soybeans"):
        table = _com19_wasde_latest_balance(wasde, commodity)
        if not table.empty:
            current = table.iloc[-1]
            latest_rows.append({
                "Commodity": commodity,
                "Market year": current.get("Market year"),
                "Production": round(current.get("Production", np.nan), 2),
                "Domestic Use": round(current.get("Domestic Use", np.nan), 2),
                "Exports": round(current.get("Exports", np.nan), 2),
                "Ending Stocks": round(current.get("Ending Stocks", np.nan), 2),
                "Stocks / Use %": round(current.get("Stocks / Use %", np.nan), 2),
                "Unit": current.get("Unit", "Reported units"),
                "Release": _liq5_fmt_date(current.get("Release")),
            })
    _liq5_table_card("Latest U.S. WASDE Fundamental Pulse", "Comparable current marketing-year supply and demand fields.", pd.DataFrame(latest_rows), [("USDA Historical WASDE Report Data", "gold")], "Latest official release", 15)
    for commodity in ("Corn", "Wheat", "Soybeans"):
        table = _com19_wasde_latest_balance(wasde, commodity).copy()
        if "Release" in table:
            table["Release"] = table["Release"].map(_liq5_fmt_date)
        _liq5_table_card(f"{commodity} WASDE Balance Sheet", "Official U.S. supply-and-demand fields from the latest consolidated release.", table.round(2), [("USDA Historical WASDE Report Data", "gold")], "Latest official release", 12)
    contracts = pd.DataFrame([
        {"Layer": "WASDE balance sheets", "Status": "Live/cache", "Rule": "Official monthly consolidated CSV; release vintages retained"},
        {"Layer": "CFTC positioning", "Status": "Live/cache", "Rule": "Disaggregated Futures Only; Tuesday positions, weekly release"},
        {"Layer": "Crop progress", "Status": "Provider-required", "Rule": "USDA NASS Quick Stats API key; no fabricated weekly series"},
        {"Layer": "Export sales", "Status": "Provider-required", "Rule": "USDA FAS export-sales API contract required"},
        {"Layer": "Weather / yield model", "Status": "Not included", "Rule": "Separate weather provider and out-of-sample model validation"},
    ])
    _liq5_table_card("Fundamental Provider Coverage", "Official layers and provider-required boundaries.", contracts, [("No silent imputation", "live")], "Current contract", 15)



def _com19_inputs_view(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], wasde: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    # Retain the frozen V18 instrument dictionary and append the completed V19 contracts.
    _com18_agriculture_view("Inputs", fred, market, cftc, wasde, view_mode, smoothing)
    symbols = sorted(set(COM19_CFTC_TO_MARKET.values()) | {"ZW=F", "ZC=F", "ZS=F", "ZL=F", "ZM=F", "ZR=F", "KC=F", "SB=F", "CC=F", "CT=F", "OJ=F", "LE=F", "HE=F", "GF=F", "DC=F"})
    market_rows = []
    for symbol in symbols:
        meta = COM17_MARKET_SYMBOLS.get(symbol, {})
        frame = market.get(symbol, pd.DataFrame())
        market_rows.append({
            "Symbol": symbol,
            "Instrument": meta.get("label", symbol),
            "Role": "CFTC price alignment" if symbol in COM19_CFTC_TO_MARKET.values() else "Agriculture market monitor",
            "Unit": meta.get("unit", "Market units"),
            "Frequency": "Daily continuous-futures proxy",
            "Latest": _liq5_fmt_date(_com17_latest_date(frame)) if isinstance(frame, pd.DataFrame) and not frame.empty else "—",
            "Observations": len(frame) if isinstance(frame, pd.DataFrame) else 0,
        })
    _liq5_table_card(
        "Agriculture Futures Dictionary V19",
        "Continuous-price proxies used for performance, seasonality, valuation and CFTC alignment.",
        pd.DataFrame(market_rows), [("Yahoo/yfinance batch", "gold")], "Explicit continuous-contract lineage", 25,
    )
    contract_rows = []
    group_lookup = {name: group for group, names in COM19_CFTC_GROUPS.items() for name in names}
    for name, code in COM19_CFTC_CODES.items():
        contract_rows.append({
            "Commodity": name,
            "CFTC code": code,
            "Research group": group_lookup.get(name, "Agriculture"),
            "Price proxy": COM19_CFTC_TO_MARKET.get(name, "—"),
            "Report": "Disaggregated Futures Only",
            "Trader categories": "Producer/Merchant · Swap Dealer · Managed Money · Other Reportables",
        })
    _liq5_table_card(
        "Agriculture CFTC Contract Dictionary",
        "Official physical-commodity contract codes and the associated price proxies.",
        pd.DataFrame(contract_rows), [(f"{len(contract_rows)} contracts", "live")], "CFTC contract-market codes", 25,
    )
    provider_rows = pd.DataFrame([
        {"Layer": "WASDE supply/use", "Primary source": "USDA consolidated historical WASDE CSV", "Frequency": "Monthly release", "Rule": "Release vintages preserved; stocks/use = ending stocks / total use"},
        {"Layer": "CFTC positioning", "Primary source": "CFTC Disaggregated Futures Only", "Frequency": "Weekly", "Rule": "Tuesday positions; MM/Producer/Swap/Other categories"},
        {"Layer": "Futures prices", "Primary source": "Yahoo/yfinance continuous proxies", "Frequency": "Daily", "Rule": "Not an executable individual contract"},
        {"Layer": "IMF benchmarks", "Primary source": "IMF Primary Commodity Prices via FRED", "Frequency": "Monthly", "Rule": "Native frequency; no daily interpolation"},
        {"Layer": "Term structure / cash basis", "Primary source": "Licensed contract-chain/local cash provider", "Frequency": "Provider-required", "Rule": "No fabricated curve from a single continuous future"},
    ])
    _liq5_table_card("Agriculture V19 Method Contract", "Frozen source, transformation and fallback rules.", provider_rows, [("No silent synthetic history", "live")], COM19_VERSION, 15)

def _com19_agriculture_view(subview: str, fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], wasde: pd.DataFrame, wasde_quality: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    if subview == "Positioning":
        _com19_positioning_view(market, cftc)
        return
    if subview == "Fundamentals":
        _com19_fundamentals_view(wasde, wasde_quality)
        return
    if subview == "Inputs":
        _com19_inputs_view(fred, market, cftc, wasde, view_mode, smoothing)
        return
    # Retain the frozen V18 nested views for all other Agriculture sections.
    _com18_agriculture_view(subview, fred, market, cftc, wasde, view_mode, smoothing)


def _com19_spec_requirements(spec: Mapping[str, Any]) -> Tuple[List[str], List[str], bool]:
    if int(spec.get("n", 0)) <= 88:
        return _com18_spec_requirements(spec)
    kind = str(spec.get("kind", ""))
    market: List[str] = []
    if kind == "com19_price_positioning":
        market = sorted(set(COM19_CFTC_TO_MARKET.values()))
    return [], market, True


def _com19_chart_specs(origin: str, family: str) -> List[Dict[str, Any]]:
    specs = list(COM19_ALL_CHARTS)
    if origin != "All charts":
        specs = [x for x in specs if x.get("origin") == origin]
    if family != "All":
        specs = [x for x in specs if x.get("domain", x.get("family")) == family]
    return specs


def _com19_render_spec(spec: Mapping[str, Any], fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], wasde: pd.DataFrame, view_mode: str, smoothing: str) -> None:
    if int(spec.get("n", 0)) <= 88:
        _com18_render_spec(spec, fred, market, cftc, wasde, view_mode, smoothing)
    else:
        _com19_render_position_spec(spec, market, cftc)


def _com19_chart_book(fred: Mapping[str, pd.DataFrame], market: Mapping[str, pd.DataFrame], cftc: Mapping[str, pd.DataFrame], wasde: pd.DataFrame, origin: str, family: str, view_mode: str, smoothing: str) -> None:
    specs = _com19_chart_specs(origin, family)
    pages = max(1, int(math.ceil(len(specs) / COM18_PAGE_SIZE)))
    current = max(1, min(int(st.session_state.get("market_com19_chart_page", 1)), pages))
    nav = st.columns([1, 2, 1])
    with nav[0]:
        if st.button("← Previous", key="market_com19_prev", disabled=current <= 1, use_container_width=True):
            st.session_state["market_com19_chart_page"] = current - 1; st.rerun()
    with nav[1]:
        start = 0 if not specs else (current - 1) * COM18_PAGE_SIZE + 1
        end = min(current * COM18_PAGE_SIZE, len(specs))
        st.markdown(f"<div style='text-align:center;color:#aeb9c4;padding:.55rem'>Showing {start}–{end} of {len(specs)} charts · Page {current} of {pages}</div>", unsafe_allow_html=True)
    with nav[2]:
        if st.button("Next →", key="market_com19_next", disabled=current >= pages, use_container_width=True):
            st.session_state["market_com19_chart_page"] = current + 1; st.rerun()
    page = specs[(current - 1) * COM18_PAGE_SIZE:current * COM18_PAGE_SIZE]
    _liq6_two_column([lambda spec=spec: _com19_render_spec(spec, fred, market, cftc, wasde, view_mode, smoothing) for spec in page])


def _com19_registry() -> pd.DataFrame:
    rows = []
    for spec in COM19_ALL_CHARTS:
        f, m, c = _com19_spec_requirements(spec)
        rows.append({
            "Order": spec.get("n"), "Origin": spec.get("origin"),
            "Family": spec.get("domain", spec.get("family")), "Subview": spec.get("subview", ""),
            "Title": spec.get("title"), "Kind": spec.get("kind"),
            "FRED inputs": ", ".join(f), "Market inputs": ", ".join(m),
            "CFTC": "Yes" if c else "No",
            "Audit status": "Agriculture positioning reconstruction" if int(spec.get("n", 0)) >= 89 else spec.get("parity", "Frozen V18 chart"),
        })
    return pd.DataFrame(rows)


def _com19_quality(quality: pd.DataFrame, wasde_q: pd.DataFrame, diagnostics: Mapping[str, Any]) -> None:
    merged = pd.concat([quality, wasde_q], ignore_index=True, sort=False)
    _com18_quality(merged, pd.DataFrame(), diagnostics)
    audit = pd.DataFrame([
        {"Check": "Agriculture top-level navigation", "Result": "PASS", "Detail": "Positioning remains nested"},
        {"Check": "CFTC agriculture coverage", "Result": "PASS", "Detail": f"{len(COM19_CFTC_CODES)} contracts including soybean oil, soybean meal and rough rice"},
        {"Check": "CFTC categories", "Result": "PASS", "Detail": "Managed Money, Producer/Merchant, Swap Dealer, Other Reportables"},
        {"Check": "Positioning normalization", "Result": "PASS", "Detail": "Net, long, short and gross exposure normalized by open interest"},
        {"Check": "Positioning regime", "Result": "PASS", "Detail": "52W percentile + 104W z-score + 1W/4W impulses"},
        {"Check": "WASDE loader", "Result": "PASS", "Detail": "Official consolidated monthly CSV, Drupal link discovery, cache fallback"},
        {"Check": "Prior modules", "Result": "PASS", "Detail": "V18.1 prefix preserved; non-Agriculture routes delegated"},
    ])
    _liq5_table_card("Agriculture V19 Freeze Audit", "Data, organization and methodology controls.", audit, [("All checks must pass", "live")], COM19_VERSION, 20)
    _liq5_table_card("Commodities Chart Registry V19", "Frozen V18 charts plus Agriculture positioning additions.", _com19_registry(), [(f"{len(COM19_ALL_CHARTS)} total charts", "gold")], "Explicit origin and inputs", 30)


def _com19_required(main_view: str, subview: str, origin: str = "All charts", family: str = "All") -> Tuple[Tuple[str, ...], Tuple[str, ...], bool, bool]:
    fred, market, need_cftc, need_wasde = _com18_required(main_view, subview, origin, family)
    f, m = set(fred), set(market)
    if main_view == "Agriculture":
        # Context-specific KPI strip.
        f.update(("PFOODINDEXM", "PWHEAMTUSDM", "PMAIZMTUSDM", "PSOYBUSDM", "PCOFFOTMUSDM"))
        m.update(("ZW=F", "ZC=F", "ZS=F", "KC=F", "LE=F"))
        if subview in ("Positioning", "Valuation", "Overview"):
            need_cftc = True
        if subview == "Positioning":
            m.update(COM19_CFTC_TO_MARKET.values())
        if subview == "Fundamentals":
            need_wasde = True
    if main_view == "Chart Book":
        specs = _com19_chart_specs(origin, family)
        page = max(1, int(st.session_state.get("market_com19_chart_page", 1)))
        specs = specs[(page - 1) * COM18_PAGE_SIZE:page * COM18_PAGE_SIZE]
        f, m, need_cftc = set(), set(), False
        for spec in specs:
            sf, sm, sc = _com19_spec_requirements(spec)
            f.update(sf); m.update(sm); need_cftc = need_cftc or sc
    return tuple(sorted(f)), tuple(sorted(m)), need_cftc, need_wasde


def _render_commodities_page_v19(ticker: str, price_data: pd.DataFrame, analysis: Optional[dict]) -> None:
    _liq3_css(); _liq5_css(); _liq6_css(); _fi10_css(); _cr12_css(); _eq14_css(); _com17_css(); _com18_css()
    main_view = st.segmented_control("Commodities main section", COM18_MAIN_VIEWS, key="market_com19_main_view", label_visibility="collapsed") or "Dashboard"
    subview = ""
    if main_view == "Agriculture":
        subview = st.segmented_control("Agriculture section", COM18_AGRI_VIEWS, key="market_com19_agri_view", label_visibility="collapsed") or "Overview"
    elif main_view == "Metals":
        subview = st.segmented_control("Metals section", COM18_METALS_VIEWS, key="market_com19_metals_view", label_visibility="collapsed") or "Overview"
    elif main_view == "Carbon & Bulk":
        subview = st.segmented_control("Carbon and bulk section", COM18_CARBON_VIEWS, key="market_com19_carbon_view", label_visibility="collapsed") or "Overview"
    _com18_header(main_view, subview)

    view_mode, smoothing, origin, family = "Levels", "Raw", "All charts", "All"
    if main_view == "Chart Book":
        controls = st.columns([1, 1, 1.25, 1.25, .8])
        with controls[0]: view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_com19_view")
        with controls[1]: smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_com19_smoothing")
        with controls[2]: origin = st.selectbox("Chart set", list(COM18_ORIGINS), key="market_com19_origin")
        with controls[3]: family = st.selectbox("Research family", ["All", "Dashboard", "Metals", "Agriculture", "Carbon & Bulk", "Positioning", "Macro Sensitivity"], key="market_com19_family")
        with controls[4]:
            if st.button("Refresh", key="market_com19_refresh", use_container_width=True):
                st.session_state["market_com19_refresh_nonce"] = int(st.session_state.get("market_com19_refresh_nonce", 0)) + 1
                st.rerun()
    else:
        controls = st.columns([1, 1, 2.2, .8])
        with controls[0]: view_mode = st.selectbox("View", ["Levels", "YoY %"], key="market_com19_view")
        with controls[1]: smoothing = st.selectbox("Smoothing", ["Raw", "7D", "28D"], key="market_com19_smoothing")
        with controls[2]: _html('<div style="padding-top:1.8rem;color:#aeb9c4">Only the active Commodities route and nested section are loaded.</div>')
        with controls[3]:
            if st.button("Refresh", key="market_com19_refresh", use_container_width=True):
                st.session_state["market_com19_refresh_nonce"] = int(st.session_state.get("market_com19_refresh_nonce", 0)) + 1
                st.rerun()
    nonce = int(st.session_state.get("market_com19_refresh_nonce", 0))
    fred_ids, symbols, need_cftc, need_wasde = _com19_required(main_view, subview, origin, family)
    started = time.perf_counter()
    with _com19_ThreadPoolExecutor(max_workers=4) as ex:
        f_fred = ex.submit(_com17_load_fred, fred_ids, "1980-01-01", nonce)
        f_market = ex.submit(_com17_load_market, symbols, "max", nonce)
        f_cftc = ex.submit(_com19_load_cftc, nonce) if need_cftc else None
        f_wasde = ex.submit(_com19_load_wasde, nonce) if need_wasde else None
        fred, q_fred, d_fred = f_fred.result()
        market, q_market, d_market = f_market.result()
        cftc, q_cftc, d_cftc = f_cftc.result() if f_cftc is not None else ({}, pd.DataFrame(), {"provider": "not-requested", "status": "not-requested", "elapsed": 0.0})
        wasde, q_wasde, d_wasde = f_wasde.result() if f_wasde is not None else (pd.DataFrame(), pd.DataFrame(), {"provider": "not-requested", "status": "not-requested", "elapsed": 0.0})
    elapsed = time.perf_counter() - started
    if main_view == "Agriculture":
        _com19_agri_kpis(fred, market, cftc, wasde, subview)
    else:
        _com17_kpis(fred, market, cftc)
    _html(f'<div class="eq14-note"><b>{_escape(COM19_VERSION)}</b> · 88 frozen V18 charts + 10 positioning additions = {len(COM19_ALL_CHARTS)} · Wall load {elapsed:.1f}s · FRED {_escape(str(d_fred.get("provider","FRED")))} · Market {_escape(str(d_market.get("provider","market")))} · CFTC {_escape(str(d_cftc.get("provider","not requested")))} · USDA {_escape(str(d_wasde.get("provider","not requested")))} · active {_escape(main_view)}{(" / "+_escape(subview)) if subview else ""}.</div>')

    if main_view == "Dashboard":
        _com17_dashboard(fred, market, cftc, view_mode, smoothing)
    elif main_view == "Agriculture":
        _com19_agriculture_view(subview, fred, market, cftc, wasde, q_wasde, view_mode, smoothing)
    elif main_view == "Metals":
        _com18_metals_view(subview, fred, market, cftc, wasde, view_mode, smoothing)
    elif main_view == "Carbon & Bulk":
        _com18_carbon_view(subview, fred, market, cftc, wasde, view_mode, smoothing)
    elif main_view == "Chart Book":
        _com19_chart_book(fred, market, cftc, wasde, origin, family, view_mode, smoothing)
    else:
        quality = pd.concat([q_fred, q_market, q_cftc], ignore_index=True, sort=False)
        _com19_quality(quality, q_wasde, {"wall": elapsed, "fred": d_fred, "market": d_market, "cftc": d_cftc, "wasde": d_wasde})


