# ============================================================
# MARKET INTELLIGENCE V19.2 - PANDAS DATETIME RESOLUTION HOTFIX
# Append-only compatibility correction over the frozen V19.1 module.
# Scope: Agriculture / Positioning only.
# - Canonicalises CFTC and market dates to timezone-naive datetime64[ns].
# - Prevents pandas merge_asof failures between datetime64[us] and datetime64[ns].
# - Leaves all charts, data contracts, routing and non-Commodities pages unchanged.
# ============================================================

_PREV_COM19_CFTC_PARSE_V192 = _com19_cftc_parse
_PREV_COM19_SELECTED_POSITIONING_CARDS_V192 = _com19_selected_positioning_cards


def _com19_cftc_parse(raw: pd.DataFrame) -> pd.DataFrame:
    """Preserve the V19 parser while enforcing one canonical date dtype."""
    parsed = _PREV_COM19_CFTC_PARSE_V192(raw)
    if not isinstance(parsed, pd.DataFrame) or parsed.empty or "date" not in parsed.columns:
        return parsed
    out = parsed.copy()
    out["date"] = _liq4_datetime_ns(out["date"])
    return (
        out.dropna(subset=["date"])
        .sort_values(["code", "date"] if "code" in out.columns else ["date"])
        .reset_index(drop=True)
    )


def _com19_selected_positioning_cards(
    name: str,
    frame: pd.DataFrame,
    price: pd.DataFrame,
) -> None:
    """Call the frozen V19 renderer with merge_asof-safe nanosecond dates."""
    safe_frame = _liq4_date_frame(frame)
    safe_price = _liq4_date_frame(_com17_norm(price))
    return _PREV_COM19_SELECTED_POSITIONING_CARDS_V192(name, safe_frame, safe_price)


