def _re25_s(key: str, label: str, provider: str = "fred", transform: str = "level", axis: str = "y", unit: str = "", frequency: str = "", note: str = "", candidates: Sequence[str] = ()) -> Dict[str, Any]:
    return {"key": key, "label": label, "provider": provider, "transform": transform, "axis": axis, "unit": unit, "frequency": frequency, "note": note, "candidates": tuple(candidates)}


def _re25_chart(n: int, section: str, title: str, series: Sequence[Mapping[str, Any]], ytitle: str, subtitle: str = "", source: str = "", kind: str = "lines", expected_curves: Optional[int] = None, limitation: str = "") -> Dict[str, Any]:
    return {"n": n, "section": section, "title": title, "series": [dict(x) for x in series], "ytitle": ytitle, "subtitle": subtitle, "source": source, "kind": kind, "expected_curves": expected_curves if expected_curves is not None else len(series), "limitation": limitation}

RE25_CHARTS: List[Dict[str, Any]] = []
_n = 1

def _add(section: str, title: str, series: Sequence[Mapping[str, Any]], ytitle: str, subtitle: str = "", source: str = "", kind: str = "lines", expected_curves: Optional[int] = None, limitation: str = "") -> None:
    global _n
    RE25_CHARTS.append(_re25_chart(_n, section, title, series, ytitle, subtitle, source, kind, expected_curves, limitation)); _n += 1

