def _re25_norm(frame: Any) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    if "date" not in frame.columns:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    value_col = "value" if "value" in frame.columns else "close" if "close" in frame.columns else None
    if value_col is None:
        return pd.DataFrame({"date": pd.Series(dtype="datetime64[ns]"), "value": pd.Series(dtype="float64")})
    out = frame[["date", value_col]].rename(columns={value_col: "value"}).copy()
    out["date"] = pd.to_datetime(out["date"], errors="coerce", utc=True).dt.tz_convert(None).astype("datetime64[ns]")
    out["value"] = pd.to_numeric(out["value"], errors="coerce")
    return out.replace([np.inf, -np.inf], np.nan).dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _re25_transform(frame: pd.DataFrame, transform: str) -> pd.DataFrame:
    out = _re25_norm(frame)
    if out.empty: return out
    t = str(transform or "level")
    if t == "level": return out
    if t == "existing_k":
        x = out.copy(); x["value"] = x["value"] / 1000.0 if float(x["value"].abs().median()) > 10000 else x["value"]; return x
    if t == "yoy":
        x = out.copy(); x["value"] = x["value"].pct_change(12, fill_method=None) * 100.0; return x.dropna()
    if t == "yoy_q":
        x = out.copy(); x["value"] = x["value"].pct_change(4, fill_method=None) * 100.0; return x.dropna()
    if t == "mom":
        x = out.copy(); x["value"] = x["value"].pct_change(1, fill_method=None) * 100.0; return x.dropna()
    if t == "rebase100":
        x = out.copy(); base = _safe_float(x.iloc[0]["value"]); x["value"] = x["value"] / base * 100.0 if base not in (None, 0) else np.nan; return x.dropna()
    if t == "saar12":
        x = out.copy(); x["value"] = x["value"] * 12.0; return x
    if t == "times1000":
        x = out.copy(); x["value"] = x["value"] * 1000.0; return x
    return out


def _re25_cache_path(token: str) -> _re25_Path:
    digest = _re25_hashlib.sha256(token.encode("utf-8")).hexdigest()[:24]
    return RE25_CACHE / f"{digest}.json"


def _re25_dbnomics_one(candidates: Sequence[str], refresh: int = 0) -> Tuple[pd.DataFrame, str, str]:
    for token in candidates:
        try:
            provider, dataset, series = str(token).split("/", 2)
        except Exception:
            continue
        url = f"https://api.db.nomics.world/v22/series/{_re25_quote(provider)}/{_re25_quote(dataset)}/{_re25_quote(series, safe='.+_-')}?observations=1"
        cache = _re25_cache_path(url)
        payload = None; state = "unavailable"
        if REQUESTS_AVAILABLE:
            try:
                response = requests.get(url, timeout=22, headers={"User-Agent": "QuantTerminal/RealEstateV25"})
                response.raise_for_status(); payload = response.json(); state = "live"
                try: cache.write_text(_re25_json.dumps(payload), encoding="utf-8")
                except Exception: pass
            except Exception: pass
        if payload is None and cache.exists():
            try: payload = _re25_json.loads(cache.read_text(encoding="utf-8")); state = "cache"
            except Exception: payload = None
        if not isinstance(payload, Mapping):
            continue
        docs = []
        try:
            docs = payload.get("series", {}).get("docs", []) or payload.get("dataset", {}).get("series", {}).get("docs", [])
        except Exception: docs = []
        for doc in docs if isinstance(docs, list) else []:
            periods = doc.get("period") or doc.get("periods") or []
            values = doc.get("value") or doc.get("values") or []
            rows = []
            for p, v in zip(periods, values):
                try:
                    ps = str(p)
                    if "Q" in ps.upper():
                        clean = ps.upper().replace("-", ""); year = int(clean[:4]); q = int(clean.split("Q", 1)[1][0]); dt = pd.Timestamp(year=year, month=(q-1)*3+1, day=1)
                    elif len(ps) == 7: dt = pd.Timestamp(ps + "-01")
                    else: dt = pd.Timestamp(ps)
                    val = float(v)
                    if np.isfinite(val): rows.append((dt, val))
                except Exception: continue
            frame = _re25_norm(pd.DataFrame(rows, columns=["date", "value"]))
            if not frame.empty: return frame, state, token
    return _re25_norm(pd.DataFrame()), "unavailable", ""


def _re25_boe_one(code: str, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    # IADB CSV endpoint; if a BOE code changes the panel becomes explicit unavailable.
    url = f"https://www.bankofengland.co.uk/boeapps/database/_iadb-fromshowcolumns.asp?csv.x=yes&Datefrom=01/Jan/1990&Dateto=now&SeriesCodes={_re25_quote(code)}&CSVF=TN&UsingCodes=Y&VPD=Y&VFD=N"
    cache = RE25_CACHE / f"boe_{code}.csv"
    raw = None; state = "unavailable"
    if REQUESTS_AVAILABLE:
        try:
            r = requests.get(url, timeout=24, headers={"User-Agent": "QuantTerminal/RealEstateV25"}); r.raise_for_status(); raw = r.text; state = "live"; cache.write_text(raw, encoding="utf-8")
        except Exception: pass
    if raw is None and cache.exists():
        try: raw = cache.read_text(encoding="utf-8"); state = "cache"
        except Exception: raw = None
    if not raw: return _re25_norm(pd.DataFrame()), state
    try:
        import io as _re25_io
        df = pd.read_csv(_re25_io.StringIO(raw))
        date_col = next((c for c in df.columns if "DATE" in str(c).upper()), df.columns[0])
        value_col = next((c for c in df.columns if str(c).strip().upper() == code.upper()), df.columns[-1])
        return _re25_norm(pd.DataFrame({"date": df[date_col], "value": df[value_col]})), state
    except Exception:
        return _re25_norm(pd.DataFrame()), "parse-error"


def _re25_oecd_one(metric: str, iso: str, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    code = f"{iso}.Q.{metric}.PT_AVG_L_TERM"
    frame, state, _ = _re25_dbnomics_one((f"OECD/DSD_AN_HOUSE_PRICES@DF_HOUSE_PRICES/{code}",), refresh)
    return frame, state


def _re25_yield_history(symbol: str, price: pd.DataFrame, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    cache = RE25_CACHE / f"yield_{symbol}.json"
    rows = None; state = "unavailable"
    if YFINANCE_AVAILABLE:
        try:
            ticker = yf.Ticker(symbol)
            div = ticker.dividends
            if isinstance(div, pd.Series) and not div.empty:
                d = div.copy(); d.index = pd.to_datetime(d.index, utc=True).tz_convert(None)
                monthly_div = d.resample("ME").sum()
                p = _re25_norm(price).set_index("date")["value"].resample("ME").last()
                ttm = monthly_div.reindex(p.index, fill_value=0.0).rolling(12, min_periods=4).sum()
                y = (ttm / p * 100.0).replace([np.inf, -np.inf], np.nan).dropna()
                rows = [{"date": str(k.date()), "value": float(v)} for k, v in y.items() if np.isfinite(v)]; state = "live"
                try: cache.write_text(_re25_json.dumps(rows), encoding="utf-8")
                except Exception: pass
        except Exception: pass
    if rows is None and cache.exists():
        try: rows = _re25_json.loads(cache.read_text(encoding="utf-8")); state = "cache"
        except Exception: rows = None
    return _re25_norm(pd.DataFrame(rows or [])), state



def _re25_http_payload(url: str, cache_name: str, refresh: int = 0, binary: bool = False) -> Tuple[Any, str]:
    """Fetch with disk cache; provider failures remain explicit."""
    cache = RE25_CACHE / cache_name
    payload = None; state = "unavailable"
    if REQUESTS_AVAILABLE:
        try:
            response = requests.get(url, timeout=35, headers={"User-Agent": "QuantTerminal/RealEstateV25"})
            response.raise_for_status(); payload = response.content if binary else response.text; state = "live"
            try:
                if binary: cache.write_bytes(payload)
                else: cache.write_text(payload, encoding="utf-8")
            except Exception: pass
        except Exception: pass
    if payload is None and cache.exists():
        try: payload = cache.read_bytes() if binary else cache.read_text(encoding="utf-8"); state = "cache"
        except Exception: payload = None
    return payload, state


def _re25_statcan_one(table: str, contract: str, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    import io as _re25_io, zipfile as _re25_zipfile
    url = f"https://www150.statcan.gc.ca/n1/tbl/csv/{table}-eng.zip"
    raw, state = _re25_http_payload(url, f"statcan_{table}.zip", refresh, binary=True)
    if not raw: return _re25_norm(pd.DataFrame()), state
    try:
        with _re25_zipfile.ZipFile(_re25_io.BytesIO(raw)) as zf:
            name = next(n for n in zf.namelist() if n.lower().endswith('.csv') and 'metadata' not in n.lower())
            df = pd.read_csv(zf.open(name), low_memory=False)
    except Exception:
        return _re25_norm(pd.DataFrame()), "parse-error"
    cols = {str(c).strip().upper(): c for c in df.columns}
    date_col = cols.get("REF_DATE") or next((c for c in df.columns if "DATE" in str(c).upper()), None)
    value_col = cols.get("VALUE") or next((c for c in df.columns if str(c).upper().endswith("VALUE")), None)
    if date_col is None or value_col is None: return _re25_norm(pd.DataFrame()), "schema-error"
    work = df.copy(); text_cols = [c for c in work.columns if c not in {date_col, value_col} and work[c].dtype == object]
    def mask_any(frame: pd.DataFrame, patterns: Sequence[str]) -> pd.Series:
        mask = pd.Series(False, index=frame.index)
        for c in text_cols:
            x = frame[c].astype(str)
            for pat in patterns: mask |= x.str.contains(pat, case=False, regex=False, na=False)
        return mask
    geo_col = next((c for c in text_cols if str(c).strip().upper() == "GEO"), None)
    if geo_col is not None:
        exact = work[geo_col].astype(str).str.strip().eq("Canada")
        if exact.any(): work = work.loc[exact].copy()
    if contract.upper() == "NHPI":
        specific = mask_any(work, ("Total (house and land)", "Total house and land"))
        if specific.any(): work = work.loc[specific].copy()
    elif contract.upper() == "STARTS":
        specific = mask_any(work, ("Total units", "Total, all dwelling types"))
        if specific.any(): work = work.loc[specific].copy()
    return _re25_norm(pd.DataFrame({"date": work[date_col], "value": work[value_col]})), state


def _re25_jsonstat_selected(payload: Mapping[str, Any]) -> pd.DataFrame:
    try:
        ids = list(payload.get("id") or payload.get("dimension", {}).get("id") or [])
        sizes = list(payload.get("size") or payload.get("dimension", {}).get("size") or [])
        dims = payload.get("dimension", {}); values = payload.get("value", [])
        if not ids or not sizes: return _re25_norm(pd.DataFrame())
        chosen=[]; time_pos=None; time_codes=[]; ordinals=[]
        for i, dim_id in enumerate(ids):
            cat=dims.get(dim_id,{}).get("category",{}); idx=cat.get("index",{}); labels=cat.get("label",{})
            order=list(idx) if isinstance(idx,list) else [k for k,_ in sorted(idx.items(),key=lambda kv:kv[1])] if isinstance(idx,Mapping) else list(labels)
            ordinals.append({k:j for j,k in enumerate(order)})
            display={k:str(labels.get(k,k)) for k in order}
            is_time=any((("M" in str(k) or "Q" in str(k)) and str(k)[:4].isdigit()) for k in order)
            if is_time: time_pos=i; time_codes=order; chosen.append(None); continue
            preferred=("annual percentage change","12 month percentage change","all residential properties","all property types","national","state")
            scored=[]
            for k in order:
                lab=display[k].lower(); score=max([100-r for r,t in enumerate(preferred) if t in lab] or [0]); scored.append((score,k))
            chosen.append(max(scored,default=(0,order[0] if order else None))[1])
        if time_pos is None:return _re25_norm(pd.DataFrame())
        rows=[]
        for tc in time_codes:
            coords=[ordinals[i].get(tc if i==time_pos else chosen[i],0) for i in range(len(ids))]
            linear=int(np.ravel_multi_index(tuple(coords),tuple(int(x) for x in sizes)))
            try: val=values.get(str(linear)) if isinstance(values,Mapping) else values[linear]
            except Exception: val=None
            if val is None:continue
            try:
                text=str(tc)
                if 'M' in text and text[:4].isdigit():dt=pd.Timestamp(year=int(text[:4]),month=int(text.split('M')[-1][:2]),day=1)
                elif 'Q' in text and text[:4].isdigit():dt=pd.Timestamp(year=int(text[:4]),month=(int(text.split('Q')[-1][0])-1)*3+1,day=1)
                else:dt=pd.Timestamp(text)
                rows.append((dt,float(val)))
            except Exception:continue
        return _re25_norm(pd.DataFrame(rows,columns=['date','value']))
    except Exception:return _re25_norm(pd.DataFrame())


def _re25_cso_one(dataset: str, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    url=f"https://ws.cso.ie/public/api.restful/PxStat.Data.Cube_API.ReadDataset/{dataset}/JSON-stat/2.0/en"
    raw,state=_re25_http_payload(url,f"cso_{dataset}.json",refresh)
    if not raw:return _re25_norm(pd.DataFrame()),state
    try:payload=_re25_json.loads(raw)
    except Exception:return _re25_norm(pd.DataFrame()),"parse-error"
    frame=_re25_jsonstat_selected(payload)
    return frame,state if not frame.empty else "schema-error"


def _re25_ukhpi_one(refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    import io as _re25_io, re as _re25_re
    html,state=_re25_http_payload("https://www.gov.uk/government/collections/uk-house-price-index-reports","ukhpi_collection.html",refresh)
    if not html:return _re25_norm(pd.DataFrame()),state
    pages=_re25_re.findall(r'href="([^"]*uk-house-price-index-data-downloads-[^"]+)"',html)
    page_url="https://www.gov.uk"+pages[0] if pages and pages[0].startswith('/') else (pages[0] if pages else "")
    if not page_url:return _re25_norm(pd.DataFrame()),"link-error"
    page,state2=_re25_http_payload(page_url,"ukhpi_latest.html",refresh)
    if not page:return _re25_norm(pd.DataFrame()),state2
    links=_re25_re.findall(r'https://publicdata\.landregistry\.gov\.uk/[^"< ]*UK-HPI-full-file-[0-9-]+\.csv[^"< ]*',page)
    if not links:return _re25_norm(pd.DataFrame()),"link-error"
    csv_text,state3=_re25_http_payload(links[0].replace('&amp;','&'),"ukhpi_full.csv",refresh)
    if not csv_text:return _re25_norm(pd.DataFrame()),state3
    try:df=pd.read_csv(_re25_io.StringIO(csv_text))
    except Exception:return _re25_norm(pd.DataFrame()),"parse-error"
    area_col=next((c for c in df.columns if str(c).lower() in {'regionname','area'}),None); date_col=next((c for c in df.columns if 'date' in str(c).lower()),None)
    value_col=next((c for c in df.columns if '12m' in str(c).lower() and 'change' in str(c).lower()),None) or next((c for c in df.columns if 'annual' in str(c).lower() and 'change' in str(c).lower()),None)
    if date_col is None or value_col is None:return _re25_norm(pd.DataFrame()),"schema-error"
    use=df[df[area_col].astype(str).str.strip().str.lower().eq('united kingdom')].copy() if area_col else df.copy()
    if use.empty:use=df.copy()
    return _re25_norm(pd.DataFrame({'date':use[date_col],'value':use[value_col]})),state3


def _re25_cbs_one(table: str, refresh: int = 0) -> Tuple[pd.DataFrame, str]:
    base=f"https://opendata.cbs.nl/ODataApi/OData/{table}"
    props_raw,state=_re25_http_payload(base+"/DataProperties?$format=json",f"cbs_{table}_props.json",refresh)
    data_raw,state2=_re25_http_payload(base+"/TypedDataSet?$format=json",f"cbs_{table}_data.json",refresh)
    if not data_raw:return _re25_norm(pd.DataFrame()),state2
    try:
        props=(_re25_json.loads(props_raw).get('value',[]) if props_raw else []);df=pd.DataFrame(_re25_json.loads(data_raw).get('value',[]))
    except Exception:return _re25_norm(pd.DataFrame()),"parse-error"
    title_by_key={str(x.get('Key')):str(x.get('Title','')) for x in props if isinstance(x,Mapping)}
    date_col=next((c for c in df.columns if 'period' in str(c).lower()),None)
    candidates=[c for c in df.columns if 'previous year' in title_by_key.get(str(c),'').lower() and ('price index' in title_by_key.get(str(c),'').lower() or 'changes compared' in title_by_key.get(str(c),'').lower())]
    value_col=candidates[0] if candidates else next((c for c in df.columns if 'ChangesComparedToThePreviousYear' in str(c)),None)
    if date_col is None or value_col is None:return _re25_norm(pd.DataFrame()),"schema-error"
    import re as _re25_re
    def parse_period(x: Any) -> Any:
        text=str(x);m=_re25_re.search(r'(\d{4}).*?(\d{2})',text)
        if m and 1<=int(m.group(2))<=12:return pd.Timestamp(year=int(m.group(1)),month=int(m.group(2)),day=1)
        return pd.to_datetime(text,errors='coerce')
    return _re25_norm(pd.DataFrame({'date':[parse_period(x) for x in df[date_col]],'value':df[value_col]})),state2

def _re25_required(section: str) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    fred, market = set(), set()
    specs = RE25_CHARTS if section in {"Dashboard", "Data Quality"} else [x for x in RE25_CHARTS if x["section"] == section]
    for spec in specs:
        for s in spec["series"]:
            if s["provider"] == "fred" and s["key"]: fred.add(s["key"])
            if s["provider"] in {"market", "yield"}: market.add(s["key"])
    if section == "Dashboard":
        fred.update(("CSUSHPINSA", "HOUST", "HSN1F", "MSACSR", "MORTGAGE30US", "DRSFRMACBS", "DGS10")); market.update(("VNQ", "SPY"))
    return tuple(sorted(fred)), tuple(sorted(market))


def _re25_load(section: str, refresh: int = 0) -> Dict[str, Any]:
    fred_ids, market_ids = _re25_required(section)
    fred, fq, fd = _cr12_load_fred(fred_ids, "1980-01-01", refresh) if fred_ids else ({}, pd.DataFrame(), {})
    market, mq, md = _cr12_load_market(market_ids, "max", refresh) if market_ids else ({}, pd.DataFrame(), {})
    frames: Dict[str, pd.DataFrame] = {k: _re25_norm(v) for k, v in fred.items()}
    frames.update({f"MKT:{k}": _re25_norm(v) for k, v in market.items()})
    states: Dict[str, str] = {}
    specs = RE25_CHARTS if section in {"Dashboard", "Data Quality"} else [x for x in RE25_CHARTS if x["section"] == section]
    for spec in specs:
        for s in spec["series"]:
            key, provider = s["key"], s["provider"]
            if provider == "dbnomics" and key not in frames:
                frame, state, selected = _re25_dbnomics_one(s.get("candidates", ()), refresh); frames[key] = frame; states[key] = f"{state}:{selected}"
            elif provider == "boe" and key not in frames:
                frame, state = _re25_boe_one(key, refresh); frames[key] = frame; states[key] = state
            elif provider == "oecd" and key not in frames:
                _, metric, iso = key.split(":", 2); frame, state = _re25_oecd_one(metric, iso, refresh); frames[key] = frame; states[key] = state
            elif provider == "yield" and key not in frames:
                frame, state = _re25_yield_history(key, market.get(key, pd.DataFrame()), refresh); frames[key] = frame; states[key] = state
            elif provider == "statcan" and key not in frames:
                _, table, contract = key.split(":", 2); frame, state = _re25_statcan_one(table, contract, refresh); frames[key] = frame; states[key] = state
            elif provider == "cso" and key not in frames:
                _, dataset, _ = key.split(":", 2); frame, state = _re25_cso_one(dataset, refresh); frames[key] = frame; states[key] = state
            elif provider == "ukhpi" and key not in frames:
                frame, state = _re25_ukhpi_one(refresh); frames[key] = frame; states[key] = state
            elif provider == "cbs" and key not in frames:
                _, table, _ = key.split(":", 2); frame, state = _re25_cbs_one(table, refresh); frames[key] = frame; states[key] = state
    return {"frames": frames, "fred_quality": fq, "market_quality": mq, "states": states, "fred_diag": fd, "market_diag": md}


def _re25_figure(ytitle: str, has_y2: bool = False) -> go.Figure:
    fig = _liq5_base_figure(ytitle, 465)
    fig.update_layout(margin=dict(l=55, r=55 if has_y2 else 30, t=48, b=55), legend=dict(orientation="h", y=-.20, x=0), hovermode="x unified")
    if has_y2:
        fig.update_layout(yaxis2=dict(overlaying="y", side="right", showgrid=False, title="Secondary axis"))
    return fig


def _re25_render_card(spec: Mapping[str, Any], pack: Mapping[str, Any]) -> Dict[str, Any]:
    frames = pack.get("frames", {})
    prepared = []
    for s in spec.get("series", []):
        raw = frames.get(f"MKT:{s['key']}", pd.DataFrame()) if s["provider"] == "market" else frames.get(s["key"], pd.DataFrame())
        use = _re25_transform(raw, s.get("transform", "level"))
        if not use.empty: prepared.append((s, use))
    expected = int(spec.get("expected_curves", len(spec.get("series", []))))
    actual = len(prepared)
    latest = max((f["date"].max() for _, f in prepared), default=None)
    title = f"{spec['n']}. {spec['title']}"
    subtitle = str(spec.get("subtitle") or "Native frequency and units are retained; no silent interpolation.")
    if spec.get("limitation"): subtitle += " " + str(spec["limitation"])
    try: ctx = st.container(border=True)
    except Exception: ctx = st.container()
    with ctx:
        _html('<div class="liq5-card-marker"></div>')
        _html(f'<div class="liq5-chart-title">{_escape(title)}</div><div class="liq5-chart-sub">{_escape(subtitle)}</div><div class="liq5-chart-asof">Latest public observation {_escape(_liq5_fmt_date(latest))}</div>')
        if not prepared:
            _html(f'<div class="re25-warning">{_escape(spec.get("limitation") or "No usable observations. Provider state is shown in Data Quality.")}</div>')
        else:
            has_y2 = any(s.get("axis") == "y2" for s, _ in prepared)
            fig = _re25_figure(spec.get("ytitle", ""), has_y2)
            for i, (s, use) in enumerate(prepared):
                fig.add_trace(go.Scatter(x=use["date"], y=use["value"], mode="lines", name=s["label"], yaxis=s.get("axis", "y"), line=dict(color=RE25_COLORS[i % len(RE25_COLORS)], width=2.6 if i == 0 else 2.1, dash="dot" if s.get("frequency") == "Quarterly" and any(x.get("frequency") == "Monthly" for x in spec.get("series", [])) else "solid"), connectgaps=False, hovertemplate="%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>"))
            key = f"re25_chart_{spec['n']}_{_re25_hashlib.sha1(spec['title'].encode()).hexdigest()[:8]}"
            st.plotly_chart(fig, width="stretch", key=key, config={"displaylogo": False, "responsive": True, "scrollZoom": True, "toImageButtonOptions": {"format": "png", "scale": 2}})
        badges = [(str(spec.get("source", "Public data")), "gold"), (f"{actual}/{expected} curves", "live" if actual == expected else "neg")]
        _html('<div class="liq5-badges">' + ''.join(f'<span class="liq5-badge {_escape(cls)}">{_escape(text)}</span>' for text, cls in badges) + '</div>')
    return {"No": spec["n"], "Section": spec["section"], "Panel": spec["title"], "Expected Curves": expected, "Loaded Curves": actual, "Status": "Complete" if actual == expected else "Unavailable" if actual == 0 else "Partial", "Latest Date": _liq5_fmt_date(latest), "Source": spec.get("source", ""), "Limitation": spec.get("limitation", "")}


def _re25_two_column(specs: Sequence[Mapping[str, Any]], pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    rows = []
    for i in range(0, len(specs), 2):
        cols = st.columns(2, gap="medium")
        for col, spec in zip(cols, specs[i:i+2]):
            with col: rows.append(_re25_render_card(spec, pack))
    return rows


def _re25_header(view: str) -> None:
    meta = {
        "Dashboard": ("GLOBAL HOUSING · US ACTIVITY · FINANCING", "Real Estate dashboard", "Reference panels are separated from Quant Terminal extensions."),
        "Developed Markets": ("15 REFERENCE PANELS", "Developed-market housing", "Eight fast national prints and seven cross-country real-price panels."),
        "Emerging Markets": ("5 REFERENCE PANELS", "Emerging-market housing", "Regional BIS panels plus the Indonesia tracker contract."),
        "United States": ("18 REFERENCE PANELS", "United States housing", "Prices, activity, inventory, listings and metro Case-Shiller panels."),
        "Mortgages & Credit": ("6 REFERENCE PANELS", "Mortgages and housing credit", "US rates and credit health plus UK rates and cross-country household leverage."),
        "Rents & Construction": ("12 REFERENCE PANELS", "Rents and construction", "Five US panels and seven international-construction panels."),
        "REITs & Commercial": ("21 REFERENCE PANELS", "Listed and commercial real estate", "Sector prices, yields, commercial-property diagnostics and homebuilders."),
        "Valuation": ("10 REFERENCE PANELS", "Housing valuation", "OECD price-to-income and price-to-rent ratios by region."),
        "Data Quality": ("87 CONTRACTS · PROVIDER AUDIT", "Real Estate data quality", "Curve counts, source states, limitations and exact registry."),
    }
    kicker, title, sub = meta[view]
    _html(f'<div class="re25-kicker">{_escape(kicker)}</div><div class="re25-title">{_escape(title)}</div><div class="re25-sub">{_escape(sub)}</div>')


def _re25_dashboard(pack: Mapping[str, Any]) -> None:
    frames = pack.get("frames", {})
    def latest(key: str, transform: str = "level") -> Optional[float]:
        f = _re25_transform(frames.get(key, pd.DataFrame()), transform); return _safe_float(f.iloc[-1]["value"]) if not f.empty else None
    cards = [
        ("Reference panels", "87", "Seven detailed sections"),
        ("Case-Shiller YoY", _fmt(latest("CSUSHPINSA", "yoy"), 2, "%"), "US national"),
        ("Housing starts", _fmt(latest("HOUST"), 0, "k"), "SAAR"),
        ("New-home sales", _fmt(latest("HSN1F"), 0, "k"), "SAAR"),
        ("Months supply", _fmt(latest("MSACSR"), 1), "New homes"),
        ("30Y mortgage", _fmt(latest("MORTGAGE30US"), 2, "%"), "Freddie Mac"),
        ("Delinquency", _fmt(latest("DRSFRMACBS"), 2, "%"), "Single-family"),
        ("VNQ", _fmt(latest("MKT:VNQ"), 2, "$"), "Broad listed real estate"),
    ]
    _html('<div class="re25-grid">' + ''.join(f'<div class="re25-kpi"><div class="re25-kpi-label">{_escape(a)}</div><div class="re25-kpi-value">{_escape(b)}</div><div class="re25-kpi-sub">{_escape(c)}</div></div>' for a,b,c in cards) + '</div>')
    counts = pd.DataFrame([{"Section": k, "Reference panels": v} for k,v in RE25_REFERENCE_COUNTS.items()])
    limitations = pd.DataFrame(RE25_LIMITATIONS)
    _liq6_two_column([
        lambda: _liq5_table_card("Reference-panel census", "The rebuild target is fixed at 87 panels.", counts, [("87 total", "live")], "Seven detailed sections", 20),
        lambda: _liq5_table_card("Exact-data limitations", "No substitute is silently relabelled as the benchmark series.", limitations, [(f"{len(limitations)} disclosed contracts", "gold")], "See Data Quality for full details", 20),
    ])



def _re25_quality(pack: Mapping[str, Any]) -> None:
    # Evaluate all 87 using the currently loaded data contract. This route loads every required input.
    rows = []
    for spec in RE25_CHARTS:
        actual = 0; dates = []
        for s in spec["series"]:
            raw = pack.get("frames", {}).get(f"MKT:{s['key']}", pd.DataFrame()) if s["provider"] == "market" else pack.get("frames", {}).get(s["key"], pd.DataFrame())
            use = _re25_transform(raw, s.get("transform", "level"))
            if not use.empty: actual += 1; dates.append(use["date"].max())
        expected = int(spec.get("expected_curves", len(spec["series"])))
        rows.append({"No": spec["n"], "Section": spec["section"], "Panel": spec["title"], "Expected": expected, "Loaded": actual, "Status": "Complete" if actual == expected else "Unavailable" if actual == 0 else "Partial", "Latest": _liq5_fmt_date(max(dates) if dates else None), "Source": spec["source"], "Limitation": spec.get("limitation", "")})
    audit = pd.DataFrame(rows)
    summary = audit.groupby(["Section", "Status"], dropna=False).size().unstack(fill_value=0).reset_index()
    _liq5_table_card("Section completeness", "Curve-level completeness across the fixed 87-panel registry.", summary, [("No silent substitution", "gold")], "Current provider state", 30)
    _liq5_table_card("87-panel contract audit", "Every panel, expected curve count, loaded curve count and limitation.", audit, [("87 contracts", "live")], "Current provider state", 120)
    _liq5_table_card("Documented exact-data limitations", "These items require licensed or non-stable source histories.", pd.DataFrame(RE25_LIMITATIONS), [("Explicit disclosure", "gold")], "No fabricated history", 30)
    quality_parts = [x for x in (pack.get("fred_quality"), pack.get("market_quality")) if isinstance(x, pd.DataFrame) and not x.empty]
    if quality_parts:
        _liq5_table_card("Provider registry", "Raw provider state for FRED/BIS and market inputs.", pd.concat(quality_parts, ignore_index=True, sort=False), [("Live/cache state", "gold")], "Active load", 250)



