_PREV_RE25_REQUIRED_EXT = _re25_required

def _re25_required(section: str) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    f, m = _PREV_RE25_REQUIRED_EXT(section); fred, market = set(f), set(m)
    ef, em = RE25_EXTENSION_INPUTS.get(section, (set(), set())); fred.update(ef); market.update(em)
    return tuple(sorted(x for x in fred if x)), tuple(sorted(x for x in market if x))

_PREV_RE25_TRANSFORM_EXT = _re25_transform

def _re25_transform(frame: pd.DataFrame, transform: str) -> pd.DataFrame:
    t = str(transform or "level")
    if t in {"indexed2021", "existing_indexed2021", "drawdown", "billions", "trillions"}:
        base_t = "existing_k" if t == "existing_indexed2021" else "level"
        out = _PREV_RE25_TRANSFORM_EXT(frame, base_t)
        if out.empty: return out
        if t in {"indexed2021", "existing_indexed2021"}:
            use = out.loc[out["date"] >= pd.Timestamp("2021-01-01")].copy()
            if use.empty: use = out.copy()
            base = _safe_float(use.iloc[0]["value"]); use["value"] = use["value"] / base * 100.0 if base not in (None, 0) else np.nan; return use.dropna()
        if t == "drawdown":
            x = out.copy(); x["value"] = (x["value"] / x["value"].cummax() - 1.0) * 100.0; return x.dropna()
        if t == "billions":
            x = out.copy(); x["value"] = x["value"] / 1000.0; return x
        if t == "trillions":
            x = out.copy(); x["value"] = x["value"] / 1_000_000.0; return x
    return _PREV_RE25_TRANSFORM_EXT(frame, t)


def _re25_add_spread(pack: Dict[str, Any]) -> None:
    frames = pack.setdefault("frames", {})
    m = _re25_norm(frames.get("MORTGAGE30US", pd.DataFrame())); t = _re25_norm(frames.get("DGS10", pd.DataFrame()))
    if m.empty or t.empty: frames["EXT:SPREAD"] = _re25_norm(pd.DataFrame()); return
    z = pd.merge_asof(m.sort_values("date"), t.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=8), suffixes=("_m","_t"))
    z["value"] = (z["value_m"] - z["value_t"]) * 100.0; frames["EXT:SPREAD"] = _re25_norm(z[["date","value"]])


def _re25_custom_frame(pack: Mapping[str, Any], kind: str) -> Dict[str, pd.DataFrame]:
    f = pack.get("frames", {})
    def align_ratio(a: str, b: str, scale: float = 100.0) -> pd.DataFrame:
        x = _re25_norm(f.get(a, pd.DataFrame())); y = _re25_norm(f.get(b, pd.DataFrame()))
        if x.empty or y.empty: return _re25_norm(pd.DataFrame())
        z = pd.merge_asof(x.sort_values("date"), y.sort_values("date"), on="date", direction="backward", tolerance=pd.Timedelta(days=400), suffixes=("_a","_b")); z["value"] = z["value_a"] / z["value_b"] * scale; return _re25_norm(z[["date","value"]])
    if kind == "real_price": return {"Real house-price index": _re25_transform(align_ratio("CSUSHPINSA","CPIAUCSL",100),"indexed2021")}
    if kind == "price_rent": return {"Price-to-rent": _re25_transform(align_ratio("CSUSHPINSA","CUSR0000SEHA",100),"indexed2021")}
    if kind == "price_income":
        price = _re25_norm(f.get("MSPUS",pd.DataFrame())); income = _re25_norm(f.get("MEHOINUSA646N",pd.DataFrame()))
        if price.empty or income.empty:return {}
        z=pd.merge_asof(price.sort_values("date"),income.sort_values("date"),on="date",direction="backward",tolerance=pd.Timedelta(days=800),suffixes=("_p","_i"));z["value"]=z["value_p"]/z["value_i"];return {"Price-to-income":_re25_norm(z[["date","value"]])}
    if kind == "payment_burden":
        price=_re25_norm(f.get("MSPUS",pd.DataFrame())); rate=_re25_norm(f.get("MORTGAGE30US",pd.DataFrame())); income=_re25_norm(f.get("MEHOINUSA646N",pd.DataFrame()))
        if price.empty or rate.empty or income.empty:return {}
        z=pd.merge_asof(price.sort_values("date"),rate.sort_values("date"),on="date",direction="backward",tolerance=pd.Timedelta(days=40),suffixes=("_p","_r"));z=pd.merge_asof(z.sort_values("date"),income.sort_values("date"),on="date",direction="backward",tolerance=pd.Timedelta(days=800));r=z["value_r"]/1200.0;n=360;loan=z["value_p"]*.8;payment=loan*r*(1+r)**n/((1+r)**n-1);z["value"]=payment*12/z["value"]*100;return {"Payment burden":_re25_norm(z[["date","value"]])}
    if kind == "pipeline_ratios":
        out={}
        pairs=[("Permits / Starts","PERMIT","HOUST"),("Completions / Starts","COMPUTSA","HOUST"),("Under construction / Starts","UNDCONTSA","HOUST")]
        for name,a,b in pairs: out[name]=align_ratio(a,b,100)
        return out
    if kind == "reit_relative":
        out={}; spy=_re25_norm(f.get("MKT:SPY",pd.DataFrame()))
        for s in ["VNQ","ITB","XHB"]:
            x=_re25_norm(f.get(f"MKT:{s}",pd.DataFrame()))
            if x.empty or spy.empty:continue
            z=pd.merge_asof(x.sort_values("date"),spy.sort_values("date"),on="date",direction="backward",tolerance=pd.Timedelta(days=4),suffixes=("_x","_s"));z["value"]=z["value_x"]/z["value_s"];out[f"{s}/SPY"]=_re25_transform(z[["date","value"]],"indexed2021")
        return out
    if kind == "affordability_decomposition":
        return {"Home prices":_re25_transform(f.get("CSUSHPINSA",pd.DataFrame()),"indexed2021"),"Rent CPI":_re25_transform(f.get("CUSR0000SEHA",pd.DataFrame()),"indexed2021"),"Income":_re25_transform(f.get("MEHOINUSA646N",pd.DataFrame()),"indexed2021"),"Mortgage rate":_re25_transform(f.get("MORTGAGE30US",pd.DataFrame()),"indexed2021")}
    return {}


def _re25_render_custom_extension(ext: Mapping[str, Any], pack: Mapping[str, Any]) -> None:
    kind=ext.get("custom","")
    if kind.startswith("breadth_"):
        developed=kind.endswith("developed"); names=[c for c in RE25_COUNTRIES if (c in {"United States","Canada","United Kingdom","Germany","France","Italy","Spain","Netherlands","Belgium","Austria","Ireland","Portugal","Greece","Finland","Sweden","Norway","Denmark","Switzerland","Australia","New Zealand","Japan","South Korea","Hong Kong","Singapore","Israel","Luxembourg"})==developed]
        rows=[]
        for c in names:
            fr=_re25_norm(pack.get("frames",{}).get(RE25_COUNTRIES[c],pd.DataFrame())); lag=4
            y=_re25_transform(fr,"yoy_q"); val=_safe_float(y.iloc[-1]["value"]) if not y.empty else None
            if val is not None:rows.append({"Country":c,"YoY %":val})
        df=pd.DataFrame(rows); summary=pd.DataFrame([{"Available":len(df),"Positive breadth %":float((df["YoY %"]>0).mean()*100) if not df.empty else np.nan,"Median YoY %":float(df["YoY %"].median()) if not df.empty else np.nan,"IQR":float(df["YoY %"].quantile(.75)-df["YoY %"].quantile(.25)) if not df.empty else np.nan}])
        _liq5_table_card(ext["id"]+". "+ext["title"],"Cross-sectional breadth and dispersion.",summary,[(ext["source"],"gold")],"Latest available BIS quarter",10);return
    if kind=="payment_sensitivity":
        price=_safe_float(_re25_norm(pack.get("frames",{}).get("MSPUS",pd.DataFrame())).iloc[-1]["value"]) if not _re25_norm(pack.get("frames",{}).get("MSPUS",pd.DataFrame())).empty else None
        income=_safe_float(_re25_norm(pack.get("frames",{}).get("MEHOINUSA646N",pd.DataFrame())).iloc[-1]["value"]) if not _re25_norm(pack.get("frames",{}).get("MEHOINUSA646N",pd.DataFrame())).empty else None
        rows=[]
        if price and income:
            for ltv in (.6,.7,.8,.9):
                row={"LTV":f"{ltv:.0%}"}
                for rate in (3,4,5,6,7,8,9):
                    r=rate/1200;n=360;loan=price*ltv;pay=loan*r*(1+r)**n/((1+r)**n-1);row[f"{rate}%"]=pay*12/income*100
                rows.append(row)
        _liq5_table_card(ext["id"]+". "+ext["title"],"Annual mortgage payment as a percentage of household income.",pd.DataFrame(rows),[(ext["source"],"gold")],"Latest public price and income inputs",20);return
    if kind=="valuation_z":
        rows=[]
        for name,key,tr in [("House prices","CSUSHPINSA","level"),("Rent CPI","CUSR0000SEHA","level"),("New-home price","MSPUS","level"),("Mortgage rate","MORTGAGE30US","level")]:
            fr=_re25_transform(pack.get("frames",{}).get(key,pd.DataFrame()),tr);z=np.nan
            if len(fr)>=12:
                series=fr.set_index("date")["value"]; cutoff=series.index.max()-pd.Timedelta(days=3650); s=series.loc[series.index>=cutoff]; z=float((s.iloc[-1]-s.mean())/s.std(ddof=1)) if len(s)>5 and s.std(ddof=1)>0 else np.nan
            rows.append({"Component":name,"10Y z-score":z})
        _liq5_table_card(ext["id"]+". "+ext["title"],"Rolling ten-year standardized valuation inputs.",pd.DataFrame(rows),[(ext["source"],"gold")],"Latest available observations",20);return
    frames=_re25_custom_frame(pack,kind)
    spec={"n":ext["id"],"section":"Extension","title":ext["title"],"series":[_re25_s(k,k) for k in frames],"ytitle":"Index / ratio","source":ext["source"],"expected_curves":len(frames),"subtitle":"Quant Terminal proprietary diagnostic; excluded from the 87-panel reference count.","limitation":""}
    ep={"frames":frames};_re25_render_card(spec,ep)


def _re25_render_extensions(section: str, pack: Dict[str, Any]) -> None:
    _re25_add_spread(pack)
    exts=[x for x in RE25_EXTENSIONS if x["section"]==section]
    for i in range(0,len(exts),2):
        cols=st.columns(2,gap="medium")
        for col,ext in zip(cols,exts[i:i+2]):
            with col:
                if ext.get("custom"):_re25_render_custom_extension(ext,pack)
                else:
                    spec={"n":ext["id"],"section":"Extension","title":ext["title"],"series":ext["series"],"ytitle":ext["ytitle"],"source":ext["source"],"expected_curves":len(ext["series"]),"subtitle":"Quant Terminal proprietary diagnostic; excluded from the 87-panel reference count.","limitation":""};_re25_render_card(spec,pack)


def _render_real_estate_page_v25(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, price_data, analysis
    _re25_css(); view=st.radio("Real Estate section",RE25_SECTIONS,horizontal=True,key="re25_view",label_visibility="collapsed")
    refresh=st.button("Refresh",key="re25_refresh");nonce=int(st.session_state.get("re25_nonce",0))
    if refresh:nonce+=1;st.session_state["re25_nonce"]=nonce
    _re25_header(view);_html(f'<div class="re25-note">{_escape(RE25_VERSION)} · {RE25_REFERENCE_TOTAL} reference panels · {len(RE25_EXTENSIONS)} Quant Terminal extensions preserved separately · neutral titles · native frequencies · unique Plotly keys.</div>')
    pack=_re25_load(view,nonce)
    if view=="Dashboard":_re25_dashboard(pack);_html('<div class="re25-group">Additional Quant Terminal extensions</div>');_re25_render_extensions("Dashboard",pack)
    elif view=="Data Quality":_re25_quality(pack)
    else:
        _re25_two_column([x for x in RE25_CHARTS if x["section"]==view],pack)
        _html('<div class="re25-group">Quant Terminal extensions preserved</div>');_re25_render_extensions(view,pack)

MARKET_INTELLIGENCE_INTEGRITY.update({"real_estate_quant_extensions_preserved":len(RE25_EXTENSIONS)})

