def _oil26_s(
    key: str,
    label: str,
    provider: str = "fred",
    transform: str = "level",
    axis: str = "y",
    style: str = "line",
) -> Dict[str, str]:
    return {"key": key, "label": label, "provider": provider, "transform": transform, "axis": axis, "style": style}


def _oil26_c(
    section: str,
    n: int,
    title: str,
    subtitle: str,
    frequency: str,
    source: str,
    series: Sequence[Mapping[str, str]],
    ytitle: str = "",
    y2title: str = "",
    limitation: str = "",
    provenance: str = "Reference PDF",
) -> Dict[str, Any]:
    return {
        "section": section,
        "n": int(n),
        "title": title,
        "subtitle": subtitle,
        "frequency": frequency,
        "source": source,
        "series": [dict(x) for x in series],
        "expected_curves": len(series),
        "ytitle": ytitle,
        "y2title": y2title,
        "limitation": limitation,
        "provenance": provenance,
    }


