# Guard the census at import time; an accidental registry omission must fail fast.
for _sec, _cnt in OIL26_REFERENCE_COUNTS.items():
    _actual = len(OIL26_FUTURES) if _sec == "Futures" else len([x for x in OIL26_CHARTS if x["section"] == _sec])
    _actual += len([x for x in OIL26_SPECIAL_PANELS if x["section"] == _sec])
    if _actual != _cnt:
        raise RuntimeError(f"Oil V26 registry mismatch for {_sec}: {_actual} != {_cnt}")


# -----------------------------------------------------------------------------
# Normalisation, providers and transforms
# -----------------------------------------------------------------------------

def _oil26_norm(frame: Any) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return pd.DataFrame(columns=["date", "value"])
    work = frame.copy()
    if "date" not in work.columns:
        if isinstance(work.index, pd.DatetimeIndex):
            work = work.reset_index().rename(columns={work.index.name or "index": "date"})
        else:
            return pd.DataFrame(columns=["date", "value"])
    if "value" not in work.columns:
        candidates = [c for c in work.columns if c != "date"]
        if not candidates:
            return pd.DataFrame(columns=["date", "value"])
        work = work.rename(columns={candidates[0]: "value"})
    work = work[["date", "value"]].copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce", utc=True).dt.tz_convert(None).astype("datetime64[ns]")
    work["value"] = pd.to_numeric(work["value"], errors="coerce")
    return work.dropna().drop_duplicates("date", keep="last").sort_values("date").reset_index(drop=True)


def _oil26_freq_lag(frame: pd.DataFrame) -> int:
    work = _oil26_norm(frame)
    if len(work) < 3:
        return 12
    delta = work["date"].diff().dropna().dt.days.median()
    if pd.isna(delta):
        return 12
    if delta <= 3:
        return 252
    if delta <= 10:
        return 52
    if delta <= 45:
        return 12
    if delta <= 120:
        return 4
    return 1


def _oil26_transform(frame: Any, transform: str = "level") -> pd.DataFrame:
    work = _oil26_norm(frame)
    if work.empty:
        return work
    tr = str(transform or "level").lower()
    if tr == "level":
        return work
    if tr == "yoy":
        lag = _oil26_freq_lag(work)
        work["value"] = work["value"].pct_change(lag, fill_method=None) * 100.0
    elif tr == "diff_yoy":
        lag = _oil26_freq_lag(work)
        work["value"] = work["value"].diff(lag)
    elif tr == "last5y":
        cutoff = work["date"].max() - pd.Timedelta(days=5 * 366)
        work = work.loc[work["date"] >= cutoff].copy()
    elif tr == "index100":
        base = _safe_float(work.iloc[0]["value"])
        if base not in (None, 0):
            work["value"] = work["value"] / base * 100.0
    elif tr == "monthly":
        work = work.set_index("date")["value"].resample("MS").mean().dropna().rename("value").reset_index()
    elif tr == "weekly":
        work = work.set_index("date")["value"].resample("W-FRI").mean().dropna().rename("value").reset_index()
    elif tr == "invert":
        work["value"] = -work["value"]
    elif tr == "k_to_million":
        work["value"] = work["value"] / 1000.0
    elif tr == "bpd_to_mbd":
        work["value"] = work["value"] / 1_000_000.0
    return work.replace([np.inf, -np.inf], np.nan).dropna().reset_index(drop=True)


def _oil26_asof_binary(a: Any, b: Any, op: str, tolerance_days: int = 45) -> pd.DataFrame:
    left = _oil26_norm(a).rename(columns={"value": "a"})
    right = _oil26_norm(b).rename(columns={"value": "b"})
    if left.empty or right.empty:
        return pd.DataFrame(columns=["date", "value"])
    left["date"] = left["date"].astype("datetime64[ns]")
    right["date"] = right["date"].astype("datetime64[ns]")
    merged = pd.merge_asof(
        left.sort_values("date"), right.sort_values("date"), on="date",
        direction="nearest", tolerance=pd.Timedelta(days=int(tolerance_days)),
    ).dropna(subset=["a", "b"])
    if merged.empty:
        return pd.DataFrame(columns=["date", "value"])
    if op == "sub":
        value = merged["a"] - merged["b"]
    elif op == "add":
        value = merged["a"] + merged["b"]
    elif op == "ratio":
        value = merged["a"] / merged["b"].replace(0, np.nan)
    elif op == "mul":
        value = merged["a"] * merged["b"]
    else:
        raise ValueError(op)
    return _oil26_norm(pd.DataFrame({"date": merged["date"], "value": value}))


def _oil26_barrel_equivalent(frame: Any) -> pd.DataFrame:
    work = _oil26_norm(frame)
    if not work.empty:
        work["value"] = work["value"] * 42.0
    return work


@st.cache_data(ttl=21600, show_spinner=False)
def _oil26_fetch_eia(series_id: str, refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    key = _secret_or_env("EIA_API_KEY", "")
    if not key:
        return pd.DataFrame(columns=["date", "value"]), {"status":"missing-key","source":"EIA API v2","message":"EIA_API_KEY is not configured"}
    if not REQUESTS_AVAILABLE:
        return pd.DataFrame(columns=["date", "value"]), {"status":"provider-unavailable","source":"EIA API v2","message":"requests is unavailable"}
    url = f"https://api.eia.gov/v2/seriesid/{quote(str(series_id), safe='.')}"
    try:
        response = requests.get(url, params={"api_key": key, "length": 5000, "sort[0][column]": "period", "sort[0][direction]": "asc"}, timeout=(5, 20), headers={"User-Agent":"QuantTerminal-Oil/26"})
        response.raise_for_status()
        payload = response.json()
        data = payload.get("response", {}).get("data", [])
        rows: List[Dict[str, Any]] = []
        for row in data if isinstance(data, list) else []:
            period = row.get("period") or row.get("date")
            value = _safe_float(row.get("value"))
            if value is None:
                # The compatibility endpoint normally exposes `value`. Some
                # legacy series use a named data column; prefer explicit data
                # fields and only then fall back to scanning the row.
                preferred = (
                    "price", "quantity", "inventory", "stocks", "production",
                    "imports", "exports", "utilization", "count", "data",
                )
                for k in preferred:
                    candidate = _safe_float(row.get(k))
                    if candidate is not None:
                        value = candidate
                        break
            if value is None:
                ignored = {
                    "period", "date", "series", "seriesDescription", "unit",
                    "units", "frequency", "name", "description", "product",
                    "process", "area", "duoarea", "duoareas", "location",
                }
                for k, v in row.items():
                    if k in ignored or str(k).lower().endswith("-name"):
                        continue
                    candidate = _safe_float(v)
                    if candidate is not None:
                        value = candidate
                        break
            if period is not None and value is not None:
                rows.append({"date": period, "value": value})
        frame = _oil26_norm(pd.DataFrame(rows))
        if frame.empty:
            raise ValueError("No EIA observations returned")
        return frame, {"status":"live","source":"EIA API v2 seriesid","message":""}
    except Exception as exc:
        return pd.DataFrame(columns=["date", "value"]), {"status":"provider-unavailable","source":"EIA API v2 seriesid","message":str(exc)[:220]}


@st.cache_data(ttl=300, show_spinner=False)
def _oil26_oilprice_json(endpoint: str, params_items: Tuple[Tuple[str, str], ...] = (), refresh_token: int = 0) -> Tuple[Any, Dict[str, Any]]:
    del refresh_token
    token = _secret_or_env("OILPRICE_KEY", "") or _secret_or_env("OILPRICEAPI_KEY", "")
    if not token:
        return None, {"status":"missing-key","source":"OilPriceAPI","message":"OILPRICE_KEY/OILPRICEAPI_KEY is not configured"}
    if not REQUESTS_AVAILABLE:
        return None, {"status":"provider-unavailable","source":"OilPriceAPI","message":"requests is unavailable"}
    url = "https://api.oilpriceapi.com" + (endpoint if str(endpoint).startswith("/") else "/" + str(endpoint))
    try:
        response = requests.get(url, params=dict(params_items), headers={"Authorization":f"Token {token}","User-Agent":"QuantTerminal-Oil/26"}, timeout=(5, 20))
        response.raise_for_status()
        return response.json(), {"status":"live","source":"OilPriceAPI","message":""}
    except Exception as exc:
        return None, {"status":"provider-unavailable","source":"OilPriceAPI","message":str(exc)[:220]}


def _oil26_walk_records(obj: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    if isinstance(obj, list):
        for item in obj:
            if isinstance(item, dict):
                records.append(item)
            else:
                records.extend(_oil26_walk_records(item))
    elif isinstance(obj, dict):
        for key in ("data", "prices", "results", "commodities", "contracts", "futures", "items"):
            if key in obj:
                records.extend(_oil26_walk_records(obj[key]))
        if not records and any(k in obj for k in ("price", "value", "code", "commodity")):
            records.append(obj)
    return records


def _oil26_parse_live(payload: Any) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for record in _oil26_walk_records(payload):
        code = record.get("code") or record.get("commodity") or record.get("symbol") or record.get("ticker") or record.get("name")
        price = _safe_float(record.get("price", record.get("value", record.get("close"))))
        if not code or price is None:
            continue
        meta = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
        rows.append({
            "code": str(code),
            "name": str(record.get("name") or meta.get("name") or code),
            "price": price,
            "change": _safe_float(record.get("change", record.get("change_absolute"))),
            "change_pct": _safe_float(record.get("change_percent", record.get("change_pct", record.get("percent_change")))),
            "unit": str(record.get("unit") or meta.get("unit") or ""),
            "currency": str(record.get("currency") or meta.get("currency") or ""),
            "category": str(record.get("category") or meta.get("category") or ""),
            "source": str(record.get("source") or meta.get("source_description") or "OilPriceAPI"),
            "timestamp": record.get("created_at") or record.get("timestamp") or record.get("date"),
        })
    return pd.DataFrame(rows).drop_duplicates("code", keep="last") if rows else pd.DataFrame(columns=["code","name","price","change","change_pct","unit","currency","category","source","timestamp"])


@st.cache_data(ttl=300, show_spinner=False)
def _oil26_load_live(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    attempts = [
        ("/v1/prices/latest", tuple()),
        ("/v1/prices/latest", (("by_code", ",".join(OIL26_LIVE_CODES)),)),
    ]
    messages: List[str] = []
    for endpoint, params in attempts:
        payload, meta = _oil26_oilprice_json(endpoint, params, refresh_token)
        frame = _oil26_parse_live(payload)
        if not frame.empty:
            return frame, meta
        messages.append(str(meta.get("message", "")))
    return pd.DataFrame(), {"status":"provider-unavailable","source":"OilPriceAPI","message":" | ".join(x for x in messages if x)[:300]}


def _oil26_extract_contracts(payload: Any) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for rec in _oil26_walk_records(payload):
        label = rec.get("contract") or rec.get("month") or rec.get("name") or rec.get("symbol") or rec.get("expiration")
        price = _safe_float(rec.get("price", rec.get("settlement", rec.get("close", rec.get("last")))))
        if label is None or price is None:
            continue
        rows.append({
            "contract": str(label),
            "price": price,
            "change": _safe_float(rec.get("change")),
            "volume": _safe_float(rec.get("volume", rec.get("open_interest"))),
            "expiration": rec.get("expiration") or rec.get("expiry") or rec.get("date"),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["expiration_dt"] = pd.to_datetime(out["expiration"], errors="coerce")
        out = out.sort_values(["expiration_dt", "contract"], na_position="last").drop_duplicates("contract")
    return out


def _oil26_fred_ids(section: str) -> Tuple[str, ...]:
    specs = OIL26_CHARTS if section in {"Dashboard", "Data Quality"} else [x for x in OIL26_CHARTS if x["section"] == section]
    ids: List[str] = []
    for spec in specs:
        for item in spec["series"]:
            if item.get("provider") == "fred" and not str(item.get("key", "")).startswith("DER:"):
                ids.append(str(item["key"]))
    return tuple(dict.fromkeys(ids))


def _oil26_eia_ids(section: str) -> Tuple[str, ...]:
    specs = OIL26_CHARTS if section in {"Dashboard", "Data Quality"} else [x for x in OIL26_CHARTS if x["section"] == section]
    ids: List[str] = []
    for spec in specs:
        for item in spec["series"]:
            if item.get("provider") == "eia":
                ids.append(str(item["key"]))
    # Refining/dashboard metrics also require these inputs.
    if section in {"Dashboard", "Refining", "Data Quality", "Crisis"}:
        ids.extend(["PET.WCESTUS1.W","PET.WCSSTUS1.W","PET.WCRSTUS1.W","PET.W_EPC0_SAX_YCUOK_MBBL.W","PET.WPULEUS3.W","PET.WCRRIUS2.W"])
    return tuple(dict.fromkeys(ids))


def _oil26_build_derived(frames: Dict[str, pd.DataFrame]) -> None:
    def get(key: str) -> pd.DataFrame:
        return _oil26_norm(frames.get(key, pd.DataFrame()))
    def put(key: str, frame: pd.DataFrame) -> None:
        frames[key] = _oil26_norm(frame)
    put("DER:BRENT_WTI_M", _oil26_asof_binary(get("MCOILBRENTEU"), get("MCOILWTICO"), "sub", 45))
    put("DER:BRENT_WTI_D", _oil26_asof_binary(get("DCOILBRENTEU"), get("DCOILWTICO"), "sub", 10))
    put("DER:BRENT_DUBAI_M", _oil26_asof_binary(get("POILBREUSDM"), get("POILDUBUSDM"), "sub", 45))
    put("DER:DUBAI_BRENT", _oil26_asof_binary(get("POILDUBUSDM"), get("POILBREUSDM"), "sub", 45))
    put("DER:DUBAI_WTI", _oil26_asof_binary(get("POILDUBUSDM"), get("POILWTIUSDM"), "sub", 45))
    put("DER:TTF_HH", _oil26_asof_binary(get("PNGASEUUSDM"), get("PNGASUSUSDM"), "sub", 45))
    put("DER:ASIA_EU_GAS", _oil26_asof_binary(get("PNGASJPUSDM"), get("PNGASEUUSDM"), "sub", 45))
    put("DER:SAUDI_GAP", _oil26_asof_binary(get("SAUNGDPMOMBD"), get("SAUNXGOCMBD"), "sub", 370))
    put("DER:SPR", _oil26_asof_binary(get("PET.WCRSTUS1.W"), get("PET.WCESTUS1.W"), "sub", 10))
    # CPI-deflated WTI, expressed in latest CPI dollars.
    wti = _oil26_transform(get("DCOILWTICO"), "monthly").rename(columns={"value":"wti"})
    cpi = get("CPIAUCSL").rename(columns={"value":"cpi"})
    if not wti.empty and not cpi.empty:
        m = pd.merge_asof(wti.sort_values("date"), cpi.sort_values("date"), on="date", direction="nearest", tolerance=pd.Timedelta(days=45)).dropna()
        if not m.empty and _safe_float(m.iloc[-1]["cpi"]) not in (None, 0):
            latest_cpi = float(m.iloc[-1]["cpi"])
            put("DER:REAL_OIL", pd.DataFrame({"date":m["date"],"value":m["wti"] * latest_cpi / m["cpi"]}))
    # Barrel equivalents and cracks.
    gasoline_bbl = _oil26_barrel_equivalent(get("GASREGW"))
    heating_bbl = _oil26_barrel_equivalent(get("DHOILNYH"))
    jet_bbl = _oil26_barrel_equivalent(get("DJFUELUSGULF"))
    propane_bbl = _oil26_barrel_equivalent(get("DPROPANEMBTX"))
    diesel_bbl = _oil26_barrel_equivalent(get("GASDESW"))
    put("DER:GASOLINE_BBL", gasoline_bbl); put("DER:HEATING_BBL", heating_bbl); put("DER:JET_BBL", jet_bbl); put("DER:PROPANE_BBL", propane_bbl)
    put("DER:GASOLINE_CRACK", _oil26_asof_binary(gasoline_bbl, get("DCOILWTICO"), "sub", 10))
    put("DER:HEATING_CRACK", _oil26_asof_binary(heating_bbl, get("DCOILWTICO"), "sub", 10))
    put("DER:DIESEL_CRACK", _oil26_asof_binary(diesel_bbl, get("DCOILWTICO"), "sub", 10))
    # 3-2-1 crack using gasoline and heating oil in barrel equivalents.
    gh = _oil26_asof_binary(gasoline_bbl, heating_bbl, "add", 10)
    if not gh.empty:
        # Correct weighting: (2*gasoline + heating)/3.
        g = gasoline_bbl.rename(columns={"value":"g"}); h = heating_bbl.rename(columns={"value":"h"})
        mh = pd.merge_asof(g.sort_values("date"), h.sort_values("date"), on="date", direction="nearest", tolerance=pd.Timedelta(days=10)).dropna()
        product = pd.DataFrame({"date":mh["date"],"value":(2.0*mh["g"]+mh["h"])/3.0})
        put("DER:CRACK_321", _oil26_asof_binary(product, get("DCOILWTICO"), "sub", 10))
    # LNG import/export contract candidates. Populated by optional EIA candidates below.
    exp_candidates = [get("NG.N9133US3.M"), get("NG.N9130US3.M")]
    imp_candidates = [get("NG.N9103US3.M"), get("NG.N9100US3.M")]
    put("DER:LNG_EXPORT_PRICE", next((x for x in exp_candidates if not x.empty), pd.DataFrame()))
    put("DER:LNG_IMPORT_PRICE", next((x for x in imp_candidates if not x.empty), pd.DataFrame()))
    put("DER:LNG_EXPORT_IMPORT_SPREAD", _oil26_asof_binary(get("DER:LNG_EXPORT_PRICE"), get("DER:LNG_IMPORT_PRICE"), "sub", 45))


def _oil26_load(section: str, refresh_token: int = 0) -> Dict[str, Any]:
    fred_ids = _oil26_fred_ids(section)
    fred_frames, fred_quality, fred_meta = _liq3_load_fred_pack(fred_ids, "1985-01-01", int(refresh_token)) if fred_ids else ({}, pd.DataFrame(), {})
    frames: Dict[str, pd.DataFrame] = {k:_oil26_norm(v) for k,v in fred_frames.items()}
    eia_rows: List[Dict[str, Any]] = []
    eia_ids = list(_oil26_eia_ids(section))
    if section in {"Trade Flows", "Data Quality"}:
        eia_ids.extend(["NG.N9133US3.M","NG.N9103US3.M","NG.N9130US3.M","NG.N9100US3.M"])
    for sid in dict.fromkeys(eia_ids):
        f, meta = _oil26_fetch_eia(sid, int(refresh_token))
        frames[sid] = _oil26_norm(f)
        latest = _latest_date(frames[sid])
        eia_rows.append({
            "Series / Instrument": sid,
            "Label": OIL26_EIA_META.get(sid, {}).get("label", sid),
            "Source": meta.get("source", "EIA"),
            "Status": meta.get("status", "unknown"),
            "Observations": len(frames[sid]),
            "Latest Date": latest.strftime("%Y-%m-%d") if latest is not None and not pd.isna(latest) else "—",
            "Message": meta.get("message", ""),
        })
    _oil26_build_derived(frames)
    live, live_meta = _oil26_load_live(int(refresh_token))
    return {
        "frames": frames,
        "fred_quality": fred_quality,
        "fred_meta": fred_meta,
        "eia_quality": pd.DataFrame(eia_rows),
        "live": live,
        "live_meta": live_meta,
    }


