@st.cache_data(ttl=21600, show_spinner=False)
def _oil26_hormuz(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if not REQUESTS_AVAILABLE:
        return pd.DataFrame(), {"status":"provider-unavailable","source":"IMF PortWatch","message":"requests is unavailable"}
    # Open mirror of the IMF PortWatch chokepoint6 daily-transit dataset.
    url = "https://straits.live/data/transits.csv"
    try:
        response = requests.get(url, timeout=(5, 20), headers={"User-Agent":"QuantTerminal-Oil/26"})
        response.raise_for_status()
        raw = pd.read_csv(io.StringIO(response.text))
        date_col = next((c for c in raw.columns if str(c).lower() in {"date","day","period"}), None)
        tanker_col = next((c for c in raw.columns if "tanker" in str(c).lower()), None)
        total_col = next((c for c in raw.columns if str(c).lower() in {"total","ships","transits","total_transits"}), None)
        if date_col is None or (tanker_col is None and total_col is None):
            raise ValueError("Transit columns not recognised")
        out = pd.DataFrame({"date":pd.to_datetime(raw[date_col], errors="coerce")})
        if tanker_col is not None:
            out["Tankers"] = pd.to_numeric(raw[tanker_col], errors="coerce")
        if total_col is not None:
            out["All vessels"] = pd.to_numeric(raw[total_col], errors="coerce")
        out = out.dropna(subset=["date"]).sort_values("date")
        if "Tankers" in out:
            out["Tankers 7D"] = out["Tankers"].rolling(7, min_periods=2).mean()
        if out.empty:
            raise ValueError("No transit observations")
        return out, {"status":"live","source":"IMF PortWatch via open CSV mirror","message":"Weekly source publication; daily observations"}
    except Exception as exc:
        return pd.DataFrame(), {"status":"provider-unavailable","source":"IMF PortWatch","message":str(exc)[:220]}


def _oil26_render_hormuz(refresh_token: int) -> None:
    frame, meta = _oil26_hormuz(refresh_token)
    _html('<div class="o26-group">Strait of Hormuz Transit Monitor</div>')
    if frame.empty:
        _html(f'<div class="o26-status"><strong>Transit history unavailable.</strong><br>{_escape(meta.get("message",""))}. The application does not turn raw AIS pings into a fabricated historical series.</div>')
        return
    fig = go.Figure()
    if "Tankers" in frame:
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["Tankers"], name="Tankers", mode="lines", line=dict(width=1.0), opacity=.48))
    if "Tankers 7D" in frame:
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["Tankers 7D"], name="Tankers 7D average", mode="lines", line=dict(width=2.5)))
    if "All vessels" in frame:
        fig.add_trace(go.Scatter(x=frame["date"], y=frame["All vessels"], name="All vessels", mode="lines", line=dict(width=1.4,dash="dot")))
    fig.update_layout(height=420,margin=dict(l=42,r=28,t=20,b=40),paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="rgba(7,19,31,.72)",font=dict(color="#cfd7df"),hovermode="x unified",legend=dict(orientation="h",y=-.2),xaxis=dict(gridcolor="rgba(137,156,177,.12)"),yaxis=dict(title="Transit calls",gridcolor="rgba(137,156,177,.14)"))
    st.plotly_chart(fig,use_container_width=True,config=_plot_config("oil26_hormuz_transits"),key="oil26_hormuz_transits")
    latest = frame.iloc[-1]
    _html(f'<div class="o26-meta"><span><b>Latest:</b> {_escape(pd.Timestamp(latest["date"]).strftime("%d %b %Y"))}</span><span><b>Tankers:</b> {_fmt(latest.get("Tankers"),0)}</span><span><b>7D average:</b> {_fmt(latest.get("Tankers 7D"),1)}</span><span><b>Source:</b> {_escape(meta.get("source",""))}</span></div>')


def _oil26_render_dashboard(refresh_token: int) -> None:
    live, live_meta = _oil26_load_live(refresh_token)
    _html(f'<div class="o26-note">Live provider: {_escape(live_meta.get("source","OilPriceAPI"))} · status {_escape(live_meta.get("status","unknown"))} · prices refresh on the provider cadence. Historical charts load only inside the selected section.</div>')
    _oil26_live_cards(live, 48)
    _html('<div class="o26-group">Key Spreads & Refinery-Derived Indicators</div>')
    spreads = _oil26_market_spreads(live)
    if not spreads.empty:
        cards = []
        for _, row in spreads.iterrows():
            val = _safe_float(row["Value"])
            klass = "o26-up" if val is not None and val > 0 else "o26-down" if val is not None and val < 0 else "o26-flat"
            cards.append('<div class="o26-kpi"><div class="o26-label">'+_escape(row["Indicator"])+f'</div><div class="o26-value {klass}">'+_fmt_signed(val,2)+f'</div><div class="o26-delta">{_escape(row["Interpretation"])} · {_escape(row["Unit"])}</div></div>')
        _html('<div class="o26-grid">'+''.join(cards)+'</div>')
    _oil26_render_news(compact=True)


def _oil26_render_drilling(refresh_token: int) -> None:
    rig_payload, rig_meta = _oil26_oilprice_json("/v1/rig-counts/latest", tuple(), refresh_token)
    drill_payload, drill_meta = _oil26_oilprice_json("/v1/drilling-intelligence/summary", tuple(), refresh_token)
    rig_records = _oil26_walk_records(rig_payload)
    _html('<div class="o26-group">Active Rig Counts</div>')
    cards: List[str] = []
    for rec in rig_records:
        name = rec.get("region") or rec.get("name") or rec.get("country")
        value = _safe_float(rec.get("rigs", rec.get("count", rec.get("value"))))
        if name and value is not None:
            change = _safe_float(rec.get("change", rec.get("wow_change")))
            klass = "o26-up" if change is not None and change > 0 else "o26-down" if change is not None and change < 0 else "o26-flat"
            cards.append(f'<div class="o26-kpi"><div class="o26-label">{_escape(name)}</div><div class="o26-value">{_fmt(value,0)}</div><div class="o26-delta {klass}">{_fmt_signed(change,0)} WoW · rigs</div></div>')
    if cards:
        _html('<div class="o26-grid">'+''.join(cards[:12])+'</div>')
    else:
        _html(f'<div class="o26-status"><strong>Rig-count endpoint unavailable.</strong><br>{_escape(rig_meta.get("message",""))}. This endpoint can require a premium OilPriceAPI entitlement.</div>')
    _html('<div class="o26-group">Basin Well Activity</div>')
    records = _oil26_walk_records(drill_payload)
    rows: List[Dict[str, Any]] = []
    for rec in records:
        basin = rec.get("basin") or rec.get("name") or rec.get("region")
        if not basin:
            continue
        drilled = _safe_float(rec.get("drilled", rec.get("wells_drilled")))
        completed = _safe_float(rec.get("completed", rec.get("wells_completed")))
        duc = _safe_float(rec.get("duc", rec.get("drilled_uncompleted")))
        if any(v is not None for v in (drilled, completed, duc)):
            rows.append({"Basin":basin,"Drilled":drilled,"Completed":completed,"DUC":duc})
    if rows:
        _liq5_table_card("Basin well activity","Monthly drilled, completed and drilled-but-uncompleted wells.",pd.DataFrame(rows),[("OilPriceAPI drilling intelligence","gold")],"Provider latest",30)
    else:
        _html(f'<div class="o26-status"><strong>Drilling-intelligence summary unavailable.</strong><br>{_escape(drill_meta.get("message",""))}. No zero values are inserted for missing basin fields.</div>')
    _html('<div class="o26-note">Well permits and frac-spread feeds remain provider-entitlement dependent. They appear only when served by the configured account.</div>')


def _oil26_render_fuels(refresh_token: int) -> None:
    catalog_payload, cat_meta = _oil26_oilprice_json("/v1/commodities", tuple(), refresh_token)
    live, live_meta = _oil26_load_live(refresh_token)
    catalog = pd.DataFrame(_oil26_walk_records(catalog_payload))
    if catalog.empty and live.empty:
        _html(f'<div class="o26-status"><strong>Regional fuel catalogue unavailable.</strong><br>{_escape(cat_meta.get("message", live_meta.get("message","")))}. The 69-market grid is entitlement dependent and is not replaced by hard-coded snapshot values.</div>')
        return
    if catalog.empty:
        catalog = live.copy()
    # Merge current prices where a code is available.
    work = catalog.copy()
    if "code" not in work.columns:
        work["code"] = work.get("commodity", work.get("symbol", work.get("name", "")))
    if "name" not in work.columns:
        work["name"] = work["code"]
    if not live.empty:
        keep = [c for c in ["code","price","change","change_pct","unit","currency","source","category"] if c in live.columns]
        work = work.merge(live[keep], on="code", how="left", suffixes=("","_live"))
    def region_of(row: pd.Series) -> str:
        text = " ".join(str(row.get(c,"")) for c in ["code","name","source","category","description","region","country"]).upper()
        if any(x in text for x in ["SINGAPORE","MOGAS","GASOIL"]): return "Singapore"
        if any(x in text for x in ["ROTTERDAM","NWE","EUROPE","TTF"]): return "Europe"
        if any(x in text for x in ["CANADA","NRCan".upper(),"BRITISH COLUMBIA","ONTARIO","QUEBEC"]): return "Canada"
        if any(x in text for x in ["BUNKER","VLSFO","HSFO","MGO","PORT"]): return "Maritime Bunkers"
        if any(x in text for x in ["DIESEL","GASOLINE","AAA","EIA","PADD","CALIFORNIA","TEXAS"]): return "United States"
        return str(row.get("region") or row.get("country") or "Other")
    work["Region"] = work.apply(region_of, axis=1)
    display_cols = [c for c in ["Region","name","code","price","change","change_pct","currency","unit","source"] if c in work.columns]
    work = work[display_cols].copy()
    work = work.drop_duplicates([c for c in ["Region","code"] if c in work.columns]).sort_values(["Region","name"] if "name" in work.columns else ["Region"])
    _liq5_table_card("Regional Fuel Prices","Dynamic OilPriceAPI catalogue. Market count follows the provider response rather than a hard-coded total.",work,[(f"{len(work)} served instruments","live")],"Current provider response",250)


def _oil26_render_forward_curve(spec: Mapping[str, str], refresh_token: int) -> None:
    payload, meta = _oil26_oilprice_json(spec["endpoint"], tuple(), refresh_token)
    contracts = _oil26_extract_contracts(payload)
    _html(f'<div class="o26-card-head"><div class="o26-card-k">{_escape(spec["market"])} Futures</div><div class="o26-card-t">{_escape(spec["n"])}. {_escape(spec["name"])} - Forward Curve</div><div class="o26-card-s">Contract prices with available volume/open-interest bars and term-structure diagnostics.</div></div>')
    if contracts.empty:
        _html(f'<div class="o26-status"><strong>Forward curve unavailable.</strong><br>{_escape(meta.get("message",""))}. Futures endpoints can require a higher provider entitlement.</div>')
        return
    x = contracts["contract"]
    front = _safe_float(contracts.iloc[0]["price"]); back = _safe_float(contracts.iloc[-1]["price"])
    spread = None if front in (None,0) or back is None else (back/front-1)*100
    structure = "CONTANGO" if spread is not None and spread > 0 else "BACKWARDATION" if spread is not None and spread < 0 else "FLAT"
    fig = go.Figure()
    if contracts["volume"].notna().any():
        fig.add_trace(go.Bar(x=x,y=contracts["volume"],name="Volume / OI",yaxis="y2",opacity=.28))
    fig.add_trace(go.Scatter(x=x,y=contracts["price"],name="Price",mode="lines+markers",line=dict(width=2.3)))
    fig.update_layout(height=420,margin=dict(l=42,r=54,t=20,b=70),paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="rgba(7,19,31,.72)",font=dict(color="#cfd7df"),legend=dict(orientation="h",y=-.25),xaxis=dict(gridcolor="rgba(137,156,177,.12)"),yaxis=dict(title=spec["unit"],gridcolor="rgba(137,156,177,.14)"),yaxis2=dict(title="Volume",overlaying="y",side="right",showgrid=False))
    st.plotly_chart(fig,use_container_width=True,config=_plot_config("oil26_futures_"+spec["n"]),key="oil26_futures_"+spec["n"])
    _html(f'<div class="o26-meta"><span><b>Front:</b> {_fmt(front,2)} { _escape(spec["unit"])}</span><span><b>Back:</b> {_fmt(back,2)}</span><span><b>Curve spread:</b> {_fmt_signed(spread,2,"%")}</span><span><b>Structure:</b> {_escape(structure)}</span><span><b>Contracts:</b> {len(contracts)}</span></div>')
    table = contracts[[c for c in ["contract","price","change","volume","expiration"] if c in contracts.columns]].copy()
    _liq5_table_card(spec["name"]+" - Individual Contracts","Provider-served strip; no interpolated contracts.",table,[(structure,"gold")],meta.get("source","OilPriceAPI"),30)


def _oil26_render_futures(refresh_token: int) -> None:
    _html('<div class="o26-note">Five audited forward curves. Each curve retains provider contract prices and available volume/open-interest fields; missing maturities are not interpolated.</div>')
    for spec in OIL26_FUTURES:
        _oil26_render_forward_curve(spec, refresh_token)


