def _oil26_fiscal_calc(row: Mapping[str, float], brent: float, jkm: float) -> Dict[str, float]:
    oil_net = max(float(row["oil_exports"]), 0.0)
    gas_net = max(float(row["gas_exports"]), 0.0)
    swf_income = float(row["swf_assets"]) * float(row["swf_return"]) / 100.0
    gas_revenue = gas_net * 365.0 * max(jkm, 0.0) / 1000.0
    non_oil = float(row["non_oil"])
    spend = float(row["budget"]) + float(row["off_budget"]) + float(row["subsidies"])
    oil_revenue = oil_net * 365.0 * max(brent - float(row.get("discount",0)),0.0) / 1000.0
    balance = oil_revenue + gas_revenue + swf_income + non_oil - spend
    required = spend - gas_revenue - swf_income - non_oil
    breakeven = (required * 1000.0 / (oil_net * 365.0) + float(row.get("discount",0))) if oil_net > 0 else np.nan
    return {"oil_revenue":oil_revenue,"gas_revenue":gas_revenue,"swf_income":swf_income,"spend":spend,"balance":balance,"breakeven":max(breakeven,0) if np.isfinite(breakeven) else np.nan,"balance_gdp":balance/float(row["gdp"])*100.0}


def _oil26_render_fiscal(live: pd.DataFrame) -> None:
    default_brent = _oil26_live_value(live,["BRENT_CRUDE_USD","BRENT"]) or 80.0
    default_jkm = _oil26_live_value(live,["NATURAL_GAS_ASIA","JKM"]) or 12.0
    c1,c2 = st.columns(2)
    with c1: brent = st.slider("Brent oil assumption (USD/bbl)",20.0,250.0,float(np.clip(default_brent,20,250)),1.0,key="o26_fiscal_brent")
    with c2: jkm = st.slider("JKM gas assumption (USD/MMBtu)",1.0,50.0,float(np.clip(default_jkm,1,50)),0.5,key="o26_fiscal_jkm")
    scenario = st.radio("Scenario preset",["Current","OPEC+ Cuts","Price War","Sanctions Relief"],horizontal=True,key="o26_fiscal_scenario")
    if scenario == "OPEC+ Cuts": brent = min(250.0, brent+15.0)
    elif scenario == "Price War": brent = max(20.0, brent-25.0)
    elif scenario == "Sanctions Relief": brent = max(20.0, brent-10.0)
    rows=[]
    for country, base in OIL26_FISCAL_BASE.items():
        calc=_oil26_fiscal_calc(base,brent,jkm)
        rows.append({"Country":country,"Oil production mb/d":base["oil_prod"],"Net oil exports mb/d":base["oil_exports"],"Gas exports bcf/d":base["gas_exports"],"Fiscal breakeven":calc["breakeven"],"Balance USD bn":calc["balance"],"Balance % GDP":calc["balance_gdp"]})
    df=pd.DataFrame(rows).sort_values("Fiscal breakeven")
    total_prod=sum(v["oil_prod"] for v in OIL26_FISCAL_BASE.values()); total_exp=sum(v["oil_exports"] for v in OIL26_FISCAL_BASE.values()); total_bal=float(df["Balance USD bn"].sum()); surplus=int((df["Balance USD bn"]>0).sum())
    cards=[("Total production",_fmt(total_prod,1," mb/d"),"Eight producers"),("Net oil exports",_fmt(total_exp,1," mb/d"),"Model assumptions"),("Weighted breakeven",_fmt(np.average(df["Fiscal breakeven"],weights=df["Net oil exports mb/d"]),0," USD/bbl"),"Export weighted"),("Aggregate balance",_fmt_signed(total_bal,0," USD bn"),f"{surplus} of 8 in surplus")]
    _html('<div class="o26-grid">'+''.join(f'<div class="o26-kpi"><div class="o26-label">{_escape(a)}</div><div class="o26-value">{_escape(b)}</div><div class="o26-delta">{_escape(c)}</div></div>' for a,b,c in cards)+'</div>')
    fig=go.Figure()
    fig.add_trace(go.Bar(y=df["Country"],x=df["Fiscal breakeven"],orientation="h",name="Breakeven"))
    fig.add_vline(x=brent,line_dash="dash",annotation_text=f"Brent {brent:.0f}")
    fig.update_layout(height=430,margin=dict(l=30,r=20,t=20,b=35),paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="rgba(7,19,31,.72)",font=dict(color="#cfd7df"),xaxis_title="USD/bbl",yaxis=dict(autorange="reversed"))
    st.plotly_chart(fig,use_container_width=True,config=_plot_config("oil26_fiscal_breakevens"),key="oil26_fiscal_breakevens")
    _liq5_table_card("Fiscal Breakeven Comparison","Editable scenario model. Green/red interpretation follows the computed balance at the selected assumptions.",df,[(f"Brent {brent:.0f}","gold"),(f"JKM {jkm:.1f}","live")],"Audited scenario assumptions",30)
    oil_prices=[40,60,80,100,120,150,180,210,250]
    sens=[]
    for country,base in OIL26_FISCAL_BASE.items():
        row={"Country":country}
        for p in oil_prices: row[f"${p}"]=_oil26_fiscal_calc(base,float(p),jkm)["balance"]
        sens.append(row)
    _liq5_table_card("Fiscal Balance at Different Oil Prices","USD bn; current gas assumption retained.",pd.DataFrame(sens),[("Sensitivity analysis","gold")],"Scenario model",30)
    gas_prices=[2,5,8,12,16,22,30,40,50]
    gs=[]
    for country,base in OIL26_FISCAL_BASE.items():
        row={"Country":country}
        for p in gas_prices: row[f"${p}"]=_oil26_fiscal_calc(base,brent,float(p))["balance"]
        gs.append(row)
    _liq5_table_card("Fiscal Balance at Different Gas Prices","USD bn; current oil assumption retained.",pd.DataFrame(gs),[("Gas sensitivity","gold")],"Scenario model",30)
    details=[]
    for country,base in OIL26_FISCAL_BASE.items():
        calc=_oil26_fiscal_calc(base,brent,jkm)
        details.append({"Country":country,"GDP USD bn":base["gdp"],"Debt % GDP":base["debt"],"SWF assets USD bn":base["swf_assets"],"Oil revenue":calc["oil_revenue"],"Gas revenue":calc["gas_revenue"],"SWF income":calc["swf_income"],"Total spending":calc["spend"],"Balance":calc["balance"]})
    _liq5_table_card("Individual Producer Profiles","Revenue, spending, SWF and balance components.",pd.DataFrame(details),[("All assumptions visible","live")],"Audited snapshot parameters",30)
    _html('<div class="o26-note">Model formula: breakeven = (budget + subsidies + off-budget - non-oil revenue - gas revenue - SWF income) / net oil export barrels + crude discount. This is a scenario engine, not a live sovereign-account database.</div>')


@st.cache_data(ttl=600, show_spinner=False)
def _oil26_news_data(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    rows: List[Dict[str, Any]] = []
    messages: List[str] = []
    news_key = _secret_or_env("NEWSAPI_KEY", "")
    if REQUESTS_AVAILABLE and news_key:
        try:
            response = requests.get(
                "https://newsapi.org/v2/everything",
                params={"q":"oil OR crude OR LNG OR natural gas OR refinery OR OPEC","language":"en","sortBy":"publishedAt","pageSize":60,"apiKey":news_key},
                timeout=(5,18), headers={"User-Agent":"QuantTerminal-Oil/26"},
            )
            response.raise_for_status()
            for item in response.json().get("articles",[]):
                rows.append({"Published":item.get("publishedAt"),"Source":(item.get("source") or {}).get("name","NewsAPI"),"Title":item.get("title"),"Description":item.get("description"),"URL":item.get("url")})
        except Exception as exc:
            messages.append(str(exc)[:160])
    # Public RSS fallbacks. Failures are isolated feed-by-feed.
    if REQUESTS_AVAILABLE:
        try:
            import xml.etree.ElementTree as ET
            feeds = [
                ("EIA", "https://www.eia.gov/rss/todayinenergy.xml"),
                ("OilPrice.com", "https://oilprice.com/rss/main"),
                ("BBC Business", "https://feeds.bbci.co.uk/news/business/rss.xml"),
            ]
            for source, url in feeds:
                try:
                    response=requests.get(url,timeout=(4,12),headers={"User-Agent":"QuantTerminal-Oil/26"}); response.raise_for_status()
                    root=ET.fromstring(response.content)
                    for item in root.findall(".//item")[:30]:
                        rows.append({"Published":item.findtext("pubDate"),"Source":source,"Title":item.findtext("title"),"Description":item.findtext("description"),"URL":item.findtext("link")})
                except Exception as exc:
                    messages.append(source+": "+str(exc)[:90])
        except Exception as exc:
            messages.append(str(exc)[:120])
    frame=pd.DataFrame(rows)
    if not frame.empty:
        frame["Published_dt"]=pd.to_datetime(frame["Published"],errors="coerce",utc=True)
        frame=frame.dropna(subset=["Title"]).drop_duplicates("Title").sort_values("Published_dt",ascending=False).reset_index(drop=True)
    status="live" if not frame.empty else "provider-unavailable"
    return frame,{"status":status,"source":"NewsAPI + public RSS","message":" | ".join(messages)[:300]}


def _oil26_render_news(compact: bool = False, refresh_token: int = 0) -> None:
    frame,meta=_oil26_news_data(refresh_token)
    _html('<div class="o26-group">Latest Energy News</div>')
    if frame.empty:
        _html(f'<div class="o26-status"><strong>News feeds unavailable.</strong><br>{_escape(meta.get("message",""))}</div>')
        return
    use=frame.head(8 if compact else 60).copy()
    for _,row in use.iterrows():
        published=row.get("Published_dt")
        date_text=published.strftime("%d %b %Y %H:%M UTC") if isinstance(published,pd.Timestamp) and not pd.isna(published) else str(row.get("Published") or "")
        url=str(row.get("URL") or "")
        title=_escape(row.get("Title") or "")
        title_html=f'<a href="{_escape(url)}" target="_blank" style="color:#eef2f6;text-decoration:none">{title}</a>' if url.startswith("http") else title
        desc=str(row.get("Description") or "")
        _html(f'<div class="o26-status" style="margin-bottom:7px"><div style="color:#d7c45a;font-size:10px;letter-spacing:.08em;text-transform:uppercase">{_escape(row.get("Source",""))} · {_escape(date_text)}</div><div style="font-family:Georgia,serif;font-size:16px;font-weight:700;margin:3px 0">{title_html}</div><div>{_escape(desc[:320])}</div></div>')


def _oil26_render_refining_intelligence(pack: Mapping[str, Any]) -> None:
    live=pack.get("live",pd.DataFrame()); spreads=_oil26_market_spreads(live)
    _html('<div class="o26-group">Refinery Market Intelligence</div>')
    if spreads.empty:
        _html('<div class="o26-status"><strong>Live refinery analytics unavailable.</strong><br>Historical public refinery panels below remain independent.</div>')
        return
    cushing=_oil26_norm(pack.get("frames",{}).get("PET.W_EPC0_SAX_YCUOK_MBBL.W",pd.DataFrame()))
    c_val,_= _oil26_latest(cushing)
    util=_oil26_norm(pack.get("frames",{}).get("PET.WPULEUS3.W",pd.DataFrame()))
    u_val,_=_oil26_latest(util)
    cards=[]
    for _,r in spreads.loc[spreads["Indicator"].isin(["3-2-1 Crack","2-1-1 Crack","Brent-WTI","Gasoline Crack","Diesel Crack"])].iterrows():
        cards.append((r["Indicator"],_fmt_signed(r["Value"],2," "+r["Unit"]),r["Interpretation"]))
    cards.extend([("Cushing stocks",_fmt(c_val,0," k bbl"),"WTI delivery point"),("Refinery utilisation",_fmt(u_val,1,"%"),"Weekly EIA")])
    _html('<div class="o26-grid">'+''.join(f'<div class="o26-kpi"><div class="o26-label">{_escape(a)}</div><div class="o26-value">{_escape(b)}</div><div class="o26-delta">{_escape(c)}</div></div>' for a,b,c in cards)+'</div>')


def _oil26_quality(refresh_token: int) -> None:
    pack=_oil26_load("Data Quality",refresh_token)
    rows=[]
    for spec in OIL26_CHARTS:
        loaded=0; dates=[]
        for item in spec["series"]:
            fr=_oil26_series_frame(item,pack)
            if not fr.empty:
                loaded+=1; dates.append(fr["date"].max())
        expected=int(spec.get("expected_curves",len(spec["series"])))
        rows.append({"Section":spec["section"],"No":spec["n"],"Panel":spec["title"],"Expected curves":expected,"Loaded curves":loaded,"Status":"Complete" if loaded==expected else "Unavailable" if loaded==0 else "Partial","Latest":max(dates).strftime("%Y-%m-%d") if dates else "—","Source":spec["source"],"Provenance":spec.get("provenance",""),"Limitation":spec.get("limitation","")})
    hormuz_frame, hormuz_meta = _oil26_hormuz(refresh_token)
    hormuz_loaded = 0
    if not hormuz_frame.empty:
        hormuz_loaded = int("Tankers" in hormuz_frame.columns) + int("Tankers 7D" in hormuz_frame.columns)
    rows.append({
        "Section":"Supply", "No":"H1", "Panel":"Strait of Hormuz Transit Calls: Tankers",
        "Expected curves":2, "Loaded curves":hormuz_loaded,
        "Status":"Complete" if hormuz_loaded >= 2 else "Unavailable" if hormuz_loaded == 0 else "Partial",
        "Latest":hormuz_frame["date"].max().strftime("%Y-%m-%d") if not hormuz_frame.empty else "—",
        "Source":hormuz_meta.get("source","IMF PortWatch"),
        "Provenance":"Supply page live transit monitor",
        "Limitation":hormuz_meta.get("message","") if hormuz_loaded < 2 else "",
    })
    for fut in OIL26_FUTURES:
        payload,meta=_oil26_oilprice_json(fut["endpoint"],tuple(),refresh_token); contracts=_oil26_extract_contracts(payload)
        rows.append({"Section":"Futures","No":fut["n"],"Panel":fut["name"],"Expected curves":1,"Loaded curves":int(not contracts.empty),"Status":"Complete" if not contracts.empty else "Unavailable","Latest":"provider current","Source":meta.get("source","OilPriceAPI"),"Provenance":"Reference PDF","Limitation":meta.get("message","") if contracts.empty else ""})
    audit=pd.DataFrame(rows)
    summary=audit.groupby(["Section","Status"]).size().unstack(fill_value=0).reset_index()
    _liq5_table_card("Section Completeness","Fixed reference registry including futures and repeated crisis panels.",summary,[(f"{OIL26_REFERENCE_TOTAL} panels","gold")],"Current provider state",40)
    _liq5_table_card("Reference Panel Audit","Expected curves, loaded curves, freshness, source and limitations.",audit,[("No silent substitutions","live")],"Current provider state",180)
    providers=[]
    for name in ["fred_quality","eia_quality"]:
        df=pack.get(name)
        if isinstance(df,pd.DataFrame) and not df.empty: providers.append(df)
    if providers:
        _liq5_table_card("Provider Registry","Raw public-provider load status.",pd.concat(providers,ignore_index=True,sort=False),[("FRED + EIA","gold")],"Active audit load",300)
    _liq5_table_card("Disclosed Limitations","Items that require entitlement, a non-rendered reference layer or scenario assumptions.",pd.DataFrame(OIL26_LIMITATIONS),[("Explicit disclosure","gold")],"No fabricated history",40)


def _oil26_render_reference_section(section: str, refresh_token: int) -> None:
    pack=_oil26_load(section,refresh_token)
    if section=="Supply":
        _oil26_render_hormuz(refresh_token)
    if section=="Refining":
        _oil26_render_refining_intelligence(pack)
    specs=[x for x in OIL26_CHARTS if x["section"]==section]
    if section=="Crisis":
        groups=[("Energy Supply",range(1,8)),("Commodities",range(8,20)),("Crack Spreads",range(20,26)),("Macro Impact",range(26,36))]
        for label,numbers in groups:
            _html(f'<div class="o26-group">Crisis - {_escape(label)}</div>')
            _oil26_render_grid([x for x in specs if x["n"] in numbers],pack,"o26_crisis")
    else:
        _oil26_render_grid(specs,pack)


def _render_oil_page_v26(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker,price_data,analysis
    _oil26_css()
    section=st.radio("Oil section",OIL26_SECTIONS,horizontal=True,key="oil26_section",label_visibility="collapsed")
    c1,c2=st.columns([1,7])
    with c1:
        refresh=st.button("Refresh",key="oil26_refresh")
    nonce=int(st.session_state.get("oil26_nonce",0))
    if refresh:
        nonce+=1; st.session_state["oil26_nonce"]=nonce
    _oil26_header(section)
    if section not in {"Dashboard","News","Data Quality"}:
        live,meta=_oil26_load_live(nonce)
        _html(f'<div class="o26-note">Live quote strip · {_escape(meta.get("status","unknown"))} · detailed section data remains sourced independently from FRED/EIA/IMF or the relevant licensed endpoint.</div>')
        _oil26_live_cards(live,16)
    if section=="Dashboard": _oil26_render_dashboard(nonce)
    elif section in {"Prices","Supply","Demand","Inventories","Refining","Trade Flows","Geopolitical","Crisis"}: _oil26_render_reference_section(section,nonce)
    elif section=="Drilling": _oil26_render_drilling(nonce)
    elif section=="Fuels": _oil26_render_fuels(nonce)
    elif section=="Futures": _oil26_render_futures(nonce)
    elif section=="Fiscal":
        live,_=_oil26_load_live(nonce); _oil26_render_fiscal(live)
    elif section=="News": _oil26_render_news(compact=False,refresh_token=nonce)
    elif section=="Data Quality": _oil26_quality(nonce)


