def _oil27_rgba(color: Any, alpha: float) -> str:
    """Return a Plotly-compatible rgba color without relying on CSS #RRGGBBAA."""
    raw = str(color or "").strip()
    try:
        a = max(0.0, min(1.0, float(alpha)))
    except Exception:
        a = 0.20

    match = re.fullmatch(r"#([0-9A-Fa-f]{6})", raw)
    if match:
        value = match.group(1)
        red = int(value[0:2], 16)
        green = int(value[2:4], 16)
        blue = int(value[4:6], 16)
        return f"rgba({red},{green},{blue},{a:.3f})"

    short_match = re.fullmatch(r"#([0-9A-Fa-f]{3})", raw)
    if short_match:
        value = short_match.group(1)
        red = int(value[0] * 2, 16)
        green = int(value[1] * 2, 16)
        blue = int(value[2] * 2, 16)
        return f"rgba({red},{green},{blue},{a:.3f})"

    if raw.lower().startswith("rgba("):
        return raw
    if raw.lower().startswith("rgb("):
        values = re.findall(r"[-+]?\d*\.?\d+", raw)
        if len(values) >= 3:
            return f"rgba({int(float(values[0]))},{int(float(values[1]))},{int(float(values[2]))},{a:.3f})"

    # Defensive fallback; OIL27_COLORS currently contains only #RRGGBB values.
    return f"rgba(121,197,246,{a:.3f})"


# -----------------------------------------------------------------------------
# Generic compatibility and formatting
# -----------------------------------------------------------------------------

def _oil27_secret() -> Tuple[str, str]:
    for name in OIL27_SECRET_NAMES:
        try:
            value = str(_secret_or_env(name, "") or "").strip()
        except Exception:
            value = ""
        if value:
            return value, name
    return "", ""


def _oil27_plotly(fig: go.Figure, *, key: str) -> None:
    config = _plot_config(key)
    try:
        st.plotly_chart(fig, width="stretch", config=config, key=key)
    except TypeError:  # Streamlit backward compatibility
        st.plotly_chart(fig, use_container_width=True, config=config, key=key)


def _oil27_dataframe(data: Any, *, key: str, height: Optional[int] = None) -> None:
    kwargs: Dict[str, Any] = {"hide_index": True, "key": key}
    if height is not None:
        kwargs["height"] = int(height)
    try:
        st.dataframe(data, width="stretch", **kwargs)
    except TypeError:
        st.dataframe(data, use_container_width=True, **kwargs)


def _oil27_container():
    try:
        return st.container(border=True)
    except TypeError:
        return st.container()


def _oil27_num(value: Any, decimals: int = 2, signed: bool = False) -> str:
    val = _safe_float(value)
    if val is None:
        return "—"
    prefix = "+" if signed and val > 0 else ""
    return f"{prefix}{val:,.{decimals}f}"


def _oil27_unit_text(row: Mapping[str, Any]) -> str:
    currency = str(row.get("currency") or "").strip().upper()
    unit = str(row.get("unit") or row.get("units") or "").strip()
    unit = unit.replace("metric_ton_co2", "tCO2").replace("metric_ton", "mt")
    if currency and unit:
        return f"{currency}/{unit}"
    return currency or unit


def _oil27_latest_date_text(value: Any) -> str:
    dt = pd.to_datetime(value, errors="coerce", utc=True)
    if pd.isna(dt):
        return "latest provider observation"
    return dt.strftime("%d %b %Y %H:%M UTC")


def _oil27_style_numeric(df: pd.DataFrame, decimals: int = 1, heat: bool = False):
    numeric = list(df.select_dtypes(include=[np.number]).columns)
    styler = df.style.format({c: f"{{:,.{decimals}f}}" for c in numeric}, na_rep="—")
    if heat and numeric:
        try:
            styler = styler.background_gradient(cmap="RdYlGn", subset=numeric, axis=None)
        except Exception:
            pass
    return styler


# -----------------------------------------------------------------------------
# OilPriceAPI: correct secret, endpoints, methods and nested response shapes
# -----------------------------------------------------------------------------

@st.cache_data(ttl=300, show_spinner=False)
def _oil27_api_call(
    method: str,
    endpoint: str,
    params_items: Tuple[Tuple[str, str], ...] = (),
    json_items: Tuple[Tuple[str, Any], ...] = (),
    refresh_token: int = 0,
) -> Tuple[Any, Dict[str, Any]]:
    del refresh_token
    token, secret_name = _oil27_secret()
    if not token:
        return None, {
            "status": "missing-key",
            "source": "OilPriceAPI",
            "message": "Configure OILPRICE_API_KEY in .streamlit/secrets.toml",
            "secret_name": "",
        }
    if requests is None:
        return None, {
            "status": "provider-unavailable",
            "source": "OilPriceAPI",
            "message": "requests is unavailable",
            "secret_name": secret_name,
        }

    url = "https://api.oilpriceapi.com" + (endpoint if endpoint.startswith("/") else "/" + endpoint)
    method = method.upper().strip()
    headers_base = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "User-Agent": "QuantTerminal-Oil/27",
    }
    payload_json = dict(json_items)
    last_message = ""
    last_status: Optional[int] = None

    # Token is the documented scheme. Bearer is attempted only after a 401 for
    # compatibility with older Swagger deployments.
    for scheme in ("Token", "Bearer"):
        headers = dict(headers_base)
        headers["Authorization"] = f"{scheme} {token}"
        try:
            if method == "POST":
                response = requests.post(
                    url,
                    params=dict(params_items),
                    json=payload_json,
                    headers=headers,
                    timeout=(4, 14),
                )
            else:
                response = requests.get(
                    url,
                    params=dict(params_items),
                    headers=headers,
                    timeout=(4, 14),
                )
            last_status = int(response.status_code)
            if response.status_code == 401 and scheme == "Token":
                last_message = "401 authentication rejected"
                continue
            if response.status_code in {402, 403}:
                detail = ""
                try:
                    body = response.json()
                    detail = str(body.get("message") or body.get("error") or body)[:180]
                except Exception:
                    detail = response.text[:180]
                return None, {
                    "status": "entitlement-required",
                    "source": "OilPriceAPI",
                    "message": detail or f"HTTP {response.status_code}: endpoint not included in the active package",
                    "status_code": response.status_code,
                    "secret_name": secret_name,
                    "endpoint": endpoint,
                }
            response.raise_for_status()
            return response.json(), {
                "status": "live",
                "source": "OilPriceAPI",
                "message": "",
                "status_code": response.status_code,
                "secret_name": secret_name,
                "endpoint": endpoint,
                "rate_remaining": response.headers.get("X-RateLimit-Remaining", ""),
            }
        except Exception as exc:
            last_message = str(exc)[:220]
            break

    return None, {
        "status": "provider-unavailable",
        "source": "OilPriceAPI",
        "message": last_message or "provider request failed",
        "status_code": last_status,
        "secret_name": secret_name,
        "endpoint": endpoint,
    }


# Preserve V26 call signature while adding the correct secret alias and method.
def _oil26_oilprice_json(
    endpoint: str,
    params_items: Tuple[Tuple[str, str], ...] = (),
    refresh_token: int = 0,
) -> Tuple[Any, Dict[str, Any]]:
    return _oil27_api_call("GET", endpoint, params_items, tuple(), refresh_token)


def _oil27_iter_records(obj: Any, inherited_code: Optional[str] = None) -> Iterable[Dict[str, Any]]:
    if isinstance(obj, list):
        for item in obj:
            yield from _oil27_iter_records(item, inherited_code)
        return
    if not isinstance(obj, dict):
        return

    direct_price_keys = {"price", "value", "last_price", "settlement", "close", "last"}
    if direct_price_keys.intersection(obj.keys()):
        record = dict(obj)
        if inherited_code and not any(record.get(k) for k in ("code", "symbol", "commodity", "ticker")):
            record["code"] = inherited_code
        yield record

    for key, value in obj.items():
        next_code = inherited_code
        if isinstance(value, dict) and re.fullmatch(r"[A-Z0-9_\-.]{3,80}", str(key)):
            next_code = str(key)
        yield from _oil27_iter_records(value, next_code)


def _oil27_catalog_records(obj: Any, inherited_code: Optional[str] = None) -> Iterable[Dict[str, Any]]:
    """Yield metadata records from the commodities catalogue even without a price field."""
    if isinstance(obj, list):
        for item in obj:
            yield from _oil27_catalog_records(item, inherited_code)
        return
    if not isinstance(obj, dict):
        return

    record = dict(obj)
    code = record.get("code") or record.get("commodity") or record.get("symbol") or inherited_code
    if code and any(record.get(k) is not None for k in ("name", "description", "category", "unit", "currency", "source")):
        record["code"] = str(code).upper().strip()
        yield record

    for key, value in obj.items():
        next_code = inherited_code
        if isinstance(value, dict) and re.fullmatch(r"[A-Z0-9_\-.]{3,80}", str(key)):
            next_code = str(key)
        yield from _oil27_catalog_records(value, next_code)


def _oil26_parse_live(payload: Any) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for record in _oil27_iter_records(payload):
        meta = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
        code = (
            record.get("code")
            or record.get("commodity")
            or record.get("symbol")
            or record.get("ticker")
            or record.get("name")
        )
        price = _safe_float(
            record.get(
                "price",
                record.get("last_price", record.get("value", record.get("settlement", record.get("close")))),
            )
        )
        if not code or price is None:
            continue
        code = str(code).upper().strip()
        change = _safe_float(
            record.get(
                "change",
                record.get("change_24h", record.get("change_absolute", record.get("price_change"))),
            )
        )
        change_pct = _safe_float(
            record.get(
                "change_percent",
                record.get(
                    "change_24h_percent",
                    record.get("change_pct", record.get("percent_change")),
                ),
            )
        )
        rows.append(
            {
                "code": code,
                "name": str(record.get("name") or meta.get("name") or OIL27_CODE_LABELS.get(code, code)),
                "price": price,
                "change": change,
                "change_pct": change_pct,
                "unit": str(record.get("unit") or record.get("units") or meta.get("unit") or ""),
                "currency": str(record.get("currency") or meta.get("currency") or ""),
                "category": str(record.get("category") or record.get("type") or meta.get("category") or ""),
                "source": str(record.get("source") or meta.get("source_description") or meta.get("source") or "OilPriceAPI"),
                "timestamp": record.get("updated_at") or record.get("created_at") or record.get("timestamp") or record.get("date"),
            }
        )
    if not rows:
        return pd.DataFrame(columns=["code", "name", "price", "change", "change_pct", "unit", "currency", "category", "source", "timestamp"])
    out = pd.DataFrame(rows)
    out["name"] = out.apply(lambda r: OIL27_CODE_LABELS.get(str(r["code"]), str(r["name"])), axis=1)
    return out.drop_duplicates("code", keep="last").reset_index(drop=True)


@st.cache_data(ttl=300, show_spinner=False)
def _oil26_load_live(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    codes_csv = ",".join(OIL27_LIVE_CODES)
    attempts: List[Tuple[str, str, Tuple[Tuple[str, str], ...], Tuple[Tuple[str, Any], ...]]] = [
        (
            "GET",
            "/v1/prices/all",
            (("codes", codes_csv), ("include_metadata", "true")),
            tuple(),
        ),
        (
            "POST",
            "/v1/prices/batch",
            tuple(),
            (
                ("codes", list(OIL27_LIVE_CODES)),
                ("fields", ["code", "name", "price", "currency", "unit", "units", "change", "change_pct", "change_24h", "change_24h_percent", "created_at", "updated_at", "source"]),
            ),
        ),
        (
            "GET",
            "/v1/prices/latest",
            (("by_code", codes_csv),),
            tuple(),
        ),
        ("GET", "/v1/prices/latest", tuple(), tuple()),
    ]

    messages: List[str] = []
    best = pd.DataFrame()
    best_meta: Dict[str, Any] = {}
    for method, endpoint, params, body in attempts:
        payload, meta = _oil27_api_call(method, endpoint, params, body, refresh_token)
        frame = _oil26_parse_live(payload)
        if len(frame) > len(best):
            best, best_meta = frame, meta
        if len(frame) >= 8:
            return frame, meta
        messages.append(f"{endpoint}: {meta.get('message', meta.get('status', ''))}")
        if meta.get("status") == "entitlement-required" and endpoint == "/v1/prices/all":
            continue

    if not best.empty:
        best_meta = dict(best_meta)
        best_meta["status"] = "partial-live"
        best_meta["message"] = " | ".join(messages)[:360]
        return best, best_meta
    return pd.DataFrame(), {
        "status": "provider-unavailable",
        "source": "OilPriceAPI",
        "message": " | ".join(messages)[:420],
    }


def _oil27_live_row(live: pd.DataFrame, aliases: Sequence[str]) -> Optional[pd.Series]:
    if not isinstance(live, pd.DataFrame) or live.empty:
        return None
    alias_set = {str(a).upper() for a in aliases}
    codes = live["code"].astype(str).str.upper()
    hit = live.loc[codes.isin(alias_set)]
    if hit.empty:
        names = live["name"].astype(str).str.upper()
        mask = pd.Series(False, index=live.index)
        for alias in alias_set:
            mask |= names.str.contains(re.escape(alias), na=False)
        hit = live.loc[mask]
    return None if hit.empty else hit.iloc[0]


def _oil27_live_value(live: pd.DataFrame, aliases: Sequence[str]) -> Optional[float]:
    row = _oil27_live_row(live, aliases)
    return None if row is None else _safe_float(row.get("price"))


