def _oil27_apply_view(frame: pd.DataFrame, item: Mapping[str, Any]) -> pd.DataFrame:
    work = _oil26_norm(frame)
    if work.empty:
        return work
    view = str(st.session_state.get("oil27_view_mode", "Levels"))
    smoothing = str(st.session_state.get("oil27_smoothing", "Raw"))
    transform = str(item.get("transform", "level")).lower()
    if view == "YoY %" and transform not in {"yoy", "diff_yoy"}:
        lag = _oil26_freq_lag(work)
        work = work.copy()
        work["value"] = work["value"].pct_change(lag, fill_method=None) * 100.0
        work = work.dropna()
    if smoothing in {"7D", "28D"} and not work.empty:
        days = 7 if smoothing == "7D" else 28
        series = work.set_index("date")["value"].sort_index()
        rolled = series.rolling(f"{days}D", min_periods=1).mean()
        work = rolled.rename("value").reset_index()
    return _oil26_norm(work)


def _oil26_plot(spec: Mapping[str, Any], pack: Mapping[str, Any]) -> Tuple[go.Figure, int, List[pd.Timestamp]]:
    fig = go.Figure()
    loaded = 0
    dates: List[pd.Timestamp] = []
    series_specs = list(spec.get("series", []))
    single_series = len(series_specs) == 1
    latest_values: List[Tuple[str, float, pd.Timestamp]] = []

    for idx, item in enumerate(series_specs):
        frame = _oil27_apply_view(_oil26_series_frame(item, pack), item)
        if frame.empty:
            continue
        loaded += 1
        dates.append(frame["date"].max())
        label = str(item.get("label", item.get("key", "Series")))
        latest_values.append((label, float(frame.iloc[-1]["value"]), pd.Timestamp(frame.iloc[-1]["date"])))
        axis = "y2" if item.get("axis") == "y2" else "y"
        style = str(item.get("style", "line"))
        color = OIL27_COLORS[idx % len(OIL27_COLORS)]
        common = {
            "x": frame["date"],
            "y": frame["value"],
            "name": label,
            "yaxis": axis,
            "hovertemplate": "%{x|%d %b %Y}<br>%{y:,.3f}<extra>%{fullData.name}</extra>",
        }
        if style == "bar":
            fig.add_trace(go.Bar(**common, marker_color=color, opacity=0.65))
        else:
            kwargs: Dict[str, Any] = {
                **common,
                "mode": "lines",
                "line": {"width": 2.2 if idx < 2 else 1.6, "color": color},
            }
            if style == "area":
                kwargs.update({"fill": "tozeroy", "fillcolor": _oil27_rgba(color, 0.20), "opacity": 0.75})
            elif single_series and axis == "y" and str(st.session_state.get("oil27_view_mode", "Levels")) == "Levels":
                kwargs.update({"fill": "tozeroy", "fillcolor": _oil27_rgba(color, 0.26)})
            fig.add_trace(go.Scatter(**kwargs))

    latest_public = max(dates) if dates else None
    range_buttons = [
        dict(count=1, label="1Y", step="year", stepmode="backward"),
        dict(count=3, label="3Y", step="year", stepmode="backward"),
        dict(count=5, label="5Y", step="year", stepmode="backward"),
        dict(count=10, label="10Y", step="year", stepmode="backward"),
        dict(count=20, label="20Y", step="year", stepmode="backward"),
        dict(step="all", label="Max"),
    ]
    fig.update_layout(
        height=465,
        margin=dict(l=50, r=62, t=62, b=58),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(3,13,24,.88)",
        font=dict(color="#d6dde6", size=11),
        hovermode="x unified",
        legend=dict(orientation="h", y=-0.20, x=0.02, font=dict(size=11)),
        xaxis=dict(
            showgrid=True,
            gridcolor="rgba(145,163,185,.13)",
            zeroline=False,
            rangeslider=dict(visible=False),
            rangeselector=dict(
                buttons=range_buttons,
                x=0.01,
                y=1.16,
                xanchor="left",
                yanchor="top",
                bgcolor="rgba(5,19,33,.96)",
                activecolor="#eef3f7",
                bordercolor="rgba(224,200,79,.72)",
                borderwidth=1,
                font=dict(color="#dbe2eb", size=11),
            ),
        ),
        yaxis=dict(
            title="YoY %" if st.session_state.get("oil27_view_mode") == "YoY %" else str(spec.get("ytitle", "")),
            showgrid=True,
            gridcolor="rgba(145,163,185,.15)",
            zeroline=True,
            zerolinecolor="rgba(202,211,222,.27)",
        ),
        yaxis2=dict(
            title=str(spec.get("y2title", "")),
            overlaying="y",
            side="right",
            showgrid=False,
            zeroline=False,
        ),
        annotations=(
            [
                dict(
                    text=f"Latest public observation {latest_public.strftime('%d %b %Y')}",
                    x=0.01,
                    y=1.04,
                    xref="paper",
                    yref="paper",
                    showarrow=False,
                    font=dict(color="#e2ca50", size=12),
                    xanchor="left",
                )
            ]
            if latest_public is not None
            else []
        ),
    )
    fig.update_layout(meta={"oil27_latest_values": [(label, float(value), date.isoformat()) for label, value, date in latest_values]})
    return fig, loaded, dates


def _oil26_render_card(spec: Mapping[str, Any], pack: Mapping[str, Any], key_prefix: str = "o27") -> None:
    expected = int(spec.get("expected_curves", len(spec.get("series", []))))
    fig, loaded, dates = _oil26_plot(spec, pack)
    chart_key = f"{key_prefix}_{spec.get('section','section')}_{spec.get('n','0')}_{abs(hash(str(spec.get('title','')))) % 10_000_000}"

    with _oil27_container():
        _html(
            '<div class="o26-card-head">'
            f'<div class="o26-card-k">{_escape(spec.get("section", ""))} · {_escape(spec.get("frequency", ""))}</div>'
            f'<div class="o26-card-t">{_escape(spec.get("n", ""))}. {_escape(spec.get("title", ""))}</div>'
            f'<div class="o26-card-s">{_escape(spec.get("subtitle", ""))}</div>'
            '</div>'
        )
        limitation = str(spec.get("limitation") or "").strip()
        if limitation:
            _html(f'<div class="o26-lim">{_escape(limitation)}</div>')
        if loaded:
            _oil27_plotly(fig, key=chart_key)
            chips: List[str] = []
            latest_payload = (fig.layout.meta or {}).get("oil27_latest_values", []) if isinstance(fig.layout.meta, dict) else []
            for label, value, date_text in latest_payload:
                date = pd.to_datetime(date_text, errors="coerce")
                date_label = date.strftime("%d %b %Y") if not pd.isna(date) else "—"
                chips.append(
                    f'<span class="o26-chip">{_escape(label)} {_oil27_num(value, 2)} · {_escape(date_label)}</span>'
                )
            chips.append(f'<span class="o26-chip o26-chip-source">{_escape(spec.get("source", ""))}</span>')
            _html('<div class="o26-meta">' + ''.join(chips) + '</div>')
        else:
            _html(
                '<div class="o26-status"><strong>Provider data unavailable.</strong><br>'
                'The audited panel remains registered. No proxy or synthetic history has been inserted.</div>'
            )
        latest = max(dates).strftime("%d %b %Y") if dates else "—"
        _html(
            '<div class="o27-small">'
            f'Frequency: {_escape(spec.get("frequency", ""))} · Series: {loaded}/{expected} · '
            f'Latest: {_escape(latest)} · Source: {_escape(spec.get("source", ""))}'
            '</div>'
        )


def _oil26_render_grid(specs: Sequence[Mapping[str, Any]], pack: Mapping[str, Any], key_prefix: str = "o27") -> None:
    specs = list(specs)
    for idx in range(0, len(specs), 2):
        cols = st.columns(2, gap="medium")
        for col, spec in zip(cols, specs[idx: idx + 2]):
            with col:
                _oil26_render_card(spec, pack, key_prefix)


