def _oil26_live_cards(live: pd.DataFrame, limit: int = 24) -> None:
    if not isinstance(live, pd.DataFrame) or live.empty:
        _html(
            '<div class="o26-status"><strong>Live price feed unavailable.</strong><br>'
            'The code now accepts OILPRICE_API_KEY, OILPRICEAPI_KEY or OILPRICE_KEY. '
            'Historical FRED/EIA charts remain independent.</div>'
        )
        return

    order = {code: idx for idx, code in enumerate(OIL27_PRIORITY_CODES + OIL27_LIVE_CODES)}
    work = live.copy()
    work["_order"] = work["code"].map(order).fillna(9999)
    work = work.sort_values(["_order", "name"]).head(int(limit))
    cards: List[str] = []
    for _, row in work.iterrows():
        pct = _safe_float(row.get("change_pct"))
        change = _safe_float(row.get("change"))
        klass = "o26-up" if pct is not None and pct > 0 else "o26-down" if pct is not None and pct < 0 else "o26-flat"
        code = str(row.get("code") or "")
        label = OIL27_CODE_LABELS.get(code, str(row.get("name") or code))
        unit = _oil27_unit_text(row)
        cards.append(
            '<div class="o26-kpi">'
            f'<div class="o26-label">{_escape(label)}</div>'
            f'<div class="o26-value">{_oil27_num(row.get("price"), 2)} '
            f'<span style="font-size:10px;color:#99a6b5">{_escape(unit)}</span></div>'
            f'<div class="o26-delta {klass}">{_oil27_num(change, 2, True)} · {_oil27_num(pct, 2, True)}%</div>'
            f'<div class="o27-small">{_escape(_oil27_latest_date_text(row.get("timestamp")))}</div>'
            '</div>'
        )
    _html('<div class="o27-live-grid">' + ''.join(cards) + '</div>')


def _oil26_market_spreads(live: pd.DataFrame) -> pd.DataFrame:
    wti = _oil27_live_value(live, ["WTI_USD", "WTI_CRUDE_USD", "WTI"])
    brent = _oil27_live_value(live, ["BRENT_CRUDE_USD", "BRENT"])
    dubai = _oil27_live_value(live, ["DUBAI_CRUDE_USD", "DUBAI"])
    oman = _oil27_live_value(live, ["OMAN_CRUDE_USD", "OMAN"])
    azeri = _oil27_live_value(live, ["AZERI_LIGHT_USD", "AZERI"])
    urals = _oil27_live_value(live, ["URALS_CRUDE_USD", "URALS"])
    wcs = _oil27_live_value(live, ["WCS_CRUDE_USD", "WCS"])
    gas = _oil27_live_value(live, ["NATURAL_GAS_USD", "HENRY HUB"])
    ttf = _oil27_live_value(live, ["DUTCH_TTF_EUR", "DUTCH_TTF_GAS_EUR", "TTF"])
    jkm = _oil27_live_value(live, ["JKM_LNG_USD", "NATURAL_GAS_ASIA", "JKM"])
    gasoline = _oil27_live_value(live, ["GASOLINE_RBOB_USD", "GASOLINE_USD", "RBOB"])
    heating = _oil27_live_value(live, ["HEATING_OIL_USD", "HEATING OIL"])
    diesel = _oil27_live_value(live, ["ULSD_DIESEL_USD", "DIESEL_USD", "DIESEL"])
    propane = _oil27_live_value(live, ["PROPANE_USD", "PROPANE"])
    gold = _oil27_live_value(live, ["GOLD_USD", "GOLD"])
    silver = _oil27_live_value(live, ["SILVER_USD", "SILVER"])
    platinum = _oil27_live_value(live, ["PLATINUM_USD", "PLATINUM"])
    palladium = _oil27_live_value(live, ["PALLADIUM_USD", "PALLADIUM"])
    singapore_gasoil = _oil27_live_value(live, ["SINGAPORE_GASOIL_USD", "SINGAPORE GASOIL"])

    def sub(a: Optional[float], b: Optional[float]) -> Optional[float]:
        return None if a is None or b is None else a - b

    rows = [
        ("Brent-WTI", sub(brent, wti), "Atlantic Basin premium", "USD/bbl"),
        ("Dubai-WTI", sub(dubai, wti), "Asian crude premium/discount", "USD/bbl"),
        ("Brent-Dubai", sub(brent, dubai), "East-West spread", "USD/bbl"),
        ("Urals-Brent", sub(urals, brent), "Russian crude discount", "USD/bbl"),
        ("Oman-Brent", sub(oman, brent), "Middle East premium/discount", "USD/bbl"),
        ("Azeri-Brent", sub(azeri, brent), "Caspian light premium", "USD/bbl"),
        ("WCS Discount", sub(wcs, wti), "Canadian heavy discount", "USD/bbl"),
        ("TTF-HH", sub(ttf, gas), "Europe vs US gas premium", "native-unit spread"),
        ("JKM-HH", sub(jkm, gas), "Asia vs US LNG premium", "USD/MMBtu"),
        ("3-2-1 Crack", None if None in (gasoline, heating, wti) else ((2 * gasoline * 42 + heating * 42) / 3 - wti), "Refinery margin proxy", "USD/bbl"),
        ("2-1-1 Crack", None if None in (gasoline, diesel, wti) else ((gasoline * 42 + diesel * 42) / 2 - wti), "Gasoline/diesel margin", "USD/bbl"),
        ("Gasoline Crack", None if None in (gasoline, wti) else gasoline * 42 - wti, "Gasoline refinery margin", "USD/bbl"),
        ("Diesel Crack", None if None in (diesel, wti) else diesel * 42 - wti, "ULSD diesel refinery margin", "USD/bbl"),
        ("Heating Oil Crack", None if None in (heating, wti) else heating * 42 - wti, "Heating-oil refinery margin", "USD/bbl"),
        ("Frac Spread", None if None in (propane, gas) else propane * 21.65 - gas, "Propane energy-equivalent minus HH", "USD/MMBtu"),
        ("Gold/Oil Ratio", None if None in (gold, brent) or brent == 0 else gold / brent, "Barrels of Brent per ounce of gold", "bbl/oz"),
        ("Gold/Silver Ratio", None if None in (gold, silver) or silver == 0 else gold / silver, "Ounces of silver per ounce of gold", "ratio"),
        ("Pt/Pd Ratio", None if None in (platinum, palladium) or palladium == 0 else platinum / palladium, "Platinum vs palladium", "ratio"),
        ("Singapore Gasoil-Brent", sub(singapore_gasoil, brent), "Singapore gasoil premium to Brent", "USD/bbl"),
    ]
    return pd.DataFrame(rows, columns=["Indicator", "Value", "Interpretation", "Unit"])


def _oil26_render_dashboard(refresh_token: int) -> None:
    live, meta = _oil26_load_live(refresh_token)
    token, secret_name = _oil27_secret()
    status_text = meta.get("status", "unknown")
    source_text = meta.get("source", "OilPriceAPI")
    _html(
        f'<div class="o26-note">Live provider: {_escape(source_text)} · status {_escape(status_text)} · '
        f'secret alias: {_escape(secret_name or "not configured")} · one-call/batch endpoint with 5-minute cache.</div>'
    )

    if not live.empty:
        pct = pd.to_numeric(live.get("change_pct"), errors="coerce")
        up = int((pct > 0).sum())
        down = int((pct < 0).sum())
        flat = int((pct.fillna(0) == 0).sum())
        _html(
            '<div class="o27-section-summary">'
            f'<span class="o26-chip">{len(live)} live instruments</span>'
            f'<span class="o26-chip">{up} up</span>'
            f'<span class="o26-chip" style="border-color:rgba(240,119,126,.45);color:#f0777e">{down} down</span>'
            f'<span class="o26-chip o26-chip-source">{flat} flat/unreported</span>'
            '</div>'
        )
    _oil26_live_cards(live, 48)

    _html('<div class="o26-group">Key Spreads & Refinery-Derived Indicators</div>')
    spreads = _oil26_market_spreads(live)
    cards: List[str] = []
    for _, row in spreads.iterrows():
        value = _safe_float(row["Value"])
        klass = "o26-up" if value is not None and value > 0 else "o26-down" if value is not None and value < 0 else "o26-flat"
        cards.append(
            '<div class="o26-kpi">'
            f'<div class="o26-label">{_escape(row["Indicator"])}</div>'
            f'<div class="o26-value {klass}">{_oil27_num(value, 2, True)}</div>'
            f'<div class="o26-delta">{_escape(row["Interpretation"])} · {_escape(row["Unit"])}</div>'
            '</div>'
        )
    _html('<div class="o26-grid">' + ''.join(cards) + '</div>')
    _oil26_render_news(compact=True, refresh_token=refresh_token)


# -----------------------------------------------------------------------------
# Drilling: correct premium route plus public/latest fallbacks
# -----------------------------------------------------------------------------

@st.cache_data(ttl=21600, show_spinner=False)
def _oil27_fetch_dpr_workbook(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if requests is None:
        return pd.DataFrame(), {"status": "provider-unavailable", "message": "requests unavailable"}
    url = "https://www.eia.gov/petroleum/drilling/xls/dpr-data.xlsx"
    try:
        response = requests.get(url, timeout=(5, 25), headers={"User-Agent": "QuantTerminal-Oil/27"})
        response.raise_for_status()
        xls = pd.ExcelFile(io.BytesIO(response.content))
        basins = ["Permian", "Bakken", "Eagle Ford", "Anadarko", "Appalachia", "Haynesville", "Niobrara"]
        output: List[Dict[str, Any]] = []
        for sheet in xls.sheet_names:
            if not any(b.lower() in sheet.lower() for b in basins) and "duc" not in sheet.lower():
                continue
            raw = pd.read_excel(xls, sheet_name=sheet, header=None)
            text = raw.astype(str).apply(lambda col: col.str.lower())
            basin = next((b for b in basins if b.lower() in sheet.lower()), None)
            if basin is None:
                joined = " ".join(raw.head(12).astype(str).fillna("").values.flatten()).lower()
                basin = next((b for b in basins if b.lower() in joined), None)
            if basin is None:
                continue
            # Search the latest numeric values near explicit Drilled/Completed/DUC labels.
            found: Dict[str, Optional[float]] = {"Drilled": None, "Completed": None, "DUC": None}
            for label, patterns in {
                "Drilled": ("drilled", "wells drilled"),
                "Completed": ("completed", "wells completed"),
                "DUC": ("duc", "drilled but uncompleted", "drilled uncompleted"),
            }.items():
                positions = np.argwhere(text.apply(lambda c: c.str.contains("|".join(patterns), regex=True, na=False)).values)
                for r, c in positions:
                    candidates: List[float] = []
                    for rr in range(max(0, r - 2), min(len(raw), r + 12)):
                        for cc in range(max(0, c - 2), min(raw.shape[1], c + 12)):
                            value = _safe_float(raw.iat[rr, cc])
                            if value is not None and value >= 0:
                                candidates.append(value)
                    if candidates:
                        found[label] = candidates[-1]
                        break
            if any(v is not None for v in found.values()):
                output.append({"Basin": basin, **found})
        result = pd.DataFrame(output).drop_duplicates("Basin", keep="last") if output else pd.DataFrame()
        return result, {"status": "public-archive", "source": "EIA DPR workbook", "message": "DPR archive; EIA moved ongoing regional forecasts into STEO in June 2024"}
    except Exception as exc:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "EIA DPR workbook", "message": str(exc)[:220]}


def _oil26_render_drilling(refresh_token: int) -> None:
    # Correct documented OilPriceAPI route.
    rig_payload, rig_meta = _oil27_api_call("GET", "/v1/ei/rig_counts/latest", tuple(), tuple(), refresh_token)
    drill_payload, drill_meta = _oil27_api_call("GET", "/v1/drilling-intelligence/summary", tuple(), tuple(), refresh_token)
    live, live_meta = _oil26_load_live(refresh_token)

    _html('<div class="o26-group">Active Rig Counts</div>')
    cards: List[Tuple[str, Optional[float], Optional[float], str]] = []
    data = rig_payload.get("data", {}) if isinstance(rig_payload, dict) else {}
    if isinstance(data, dict):
        us_total = _safe_float(data.get("us_total"))
        us_change = _safe_float(data.get("week_over_week"))
        if us_total is not None:
            cards.append(("United States", us_total, us_change, "Baker Hughes weekly"))
        for region, aliases in (
            ("Canada", ["CANADA_RIG_COUNT"]),
            ("International", ["INTERNATIONAL_RIG_COUNT"]),
        ):
            row = _oil27_live_row(live, aliases)
            if row is not None:
                cards.append((region, _safe_float(row.get("price")), _safe_float(row.get("change")), "OilPriceAPI latest"))
    if not cards:
        for region, aliases in (
            ("United States", ["US_RIG_COUNT"]),
            ("Canada", ["CANADA_RIG_COUNT"]),
            ("International", ["INTERNATIONAL_RIG_COUNT"]),
        ):
            row = _oil27_live_row(live, aliases)
            if row is not None:
                cards.append((region, _safe_float(row.get("price")), _safe_float(row.get("change")), "OilPriceAPI all-prices"))

    if cards:
        html_cards: List[str] = []
        for name, value, change, source in cards:
            klass = "o26-up" if change is not None and change > 0 else "o26-down" if change is not None and change < 0 else "o26-flat"
            html_cards.append(
                '<div class="o26-kpi">'
                f'<div class="o26-label">{_escape(name)}</div>'
                f'<div class="o26-value">{_oil27_num(value, 0)}</div>'
                f'<div class="o26-delta {klass}">{_oil27_num(change, 0, True)} WoW · rigs</div>'
                f'<div class="o27-small">{_escape(source)}</div>'
                '</div>'
            )
        _html('<div class="o26-grid">' + ''.join(html_cards) + '</div>')
    else:
        _html(
            '<div class="o26-status"><strong>Rig counts unavailable for the active plan.</strong><br>'
            f'{_escape(rig_meta.get("message", live_meta.get("message", "")))}. '
            'The route is now /v1/ei/rig_counts/latest; HTTP 402/403 is treated as entitlement, not as zero rigs.</div>'
        )

    _html('<div class="o26-group">Basin Well Activity</div>')
    rows: List[Dict[str, Any]] = []
    if isinstance(drill_payload, dict):
        for rec in _oil27_iter_records(drill_payload):
            basin = rec.get("basin") or rec.get("region") or rec.get("name")
            if not basin:
                continue
            drilled = _safe_float(rec.get("drilled", rec.get("wells_drilled")))
            completed = _safe_float(rec.get("completed", rec.get("wells_completed")))
            duc = _safe_float(rec.get("duc", rec.get("drilled_uncompleted", rec.get("duc_wells"))))
            if any(v is not None for v in (drilled, completed, duc)):
                rows.append({"Basin": str(basin).title(), "Drilled": drilled, "Completed": completed, "DUC": duc})
    basin_df = pd.DataFrame(rows).drop_duplicates("Basin") if rows else pd.DataFrame()
    basin_meta = drill_meta
    if basin_df.empty:
        basin_df, basin_meta = _oil27_fetch_dpr_workbook(refresh_token)

    if not basin_df.empty:
        cards_html: List[str] = []
        for _, row in basin_df.iterrows():
            cards_html.append(
                '<div class="o26-kpi">'
                f'<div class="o27-region-title">{_escape(row.get("Basin", ""))}</div>'
                f'<div class="o27-small">DRILLED</div><div class="o26-value" style="font-size:17px">{_oil27_num(row.get("Drilled"), 0)}</div>'
                f'<div class="o27-small">COMPLETED · {_oil27_num(row.get("Completed"), 0)} &nbsp; DUC · {_oil27_num(row.get("DUC"), 0)}</div>'
                '</div>'
            )
        _html('<div class="o26-grid">' + ''.join(cards_html) + '</div>')
        _html(f'<div class="o26-note">Source: {_escape(basin_meta.get("source", "OilPriceAPI / EIA"))} · {_escape(basin_meta.get("message", ""))}</div>')
    else:
        _html(
            '<div class="o26-status"><strong>Basin well activity unavailable.</strong><br>'
            f'{_escape(drill_meta.get("message", ""))}. No missing basin field is replaced by zero.</div>'
        )


# -----------------------------------------------------------------------------
# Fuels: prices, not catalog-only metadata
# -----------------------------------------------------------------------------

def _oil27_region(row: Mapping[str, Any]) -> str:
    text = " ".join(str(row.get(c, "")) for c in ("code", "name", "source", "category", "description", "region", "country")).upper()
    if any(x in text for x in ("SINGAPORE", "SGSIN", "MOGAS", "MOPS")):
        return "Singapore"
    if any(x in text for x in ("ROTTERDAM", "NLRTM", "NWE", "DUTCH TTF", "EUROPE")):
        return "Europe"
    if any(x in text for x in ("CANADA", "NRCAN", "BRITISH COLUMBIA", "ONTARIO", "QUEBEC")):
        return "Canada"
    if any(x in text for x in ("BUNKER", "VLSFO", "HFO", "MGO", "MARINE")):
        return "Maritime Bunkers"
    if any(x in text for x in ("DIESEL_RETAIL_US", "GASOLINE_RETAIL_US", "AAA", "PADD", "CALIFORNIA", "TEXAS", "UNITED STATES")):
        return "United States"
    return str(row.get("region") or row.get("country") or "Global / Other")


@st.cache_data(ttl=900, show_spinner=False)
def _oil27_full_fuel_prices(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    catalog_payload, catalog_meta = _oil27_api_call("GET", "/v1/commodities", tuple(), tuple(), refresh_token)
    live, live_meta = _oil26_load_live(refresh_token)
    catalog_records = list(_oil27_catalog_records(catalog_payload))
    catalog = pd.DataFrame(catalog_records)
    if not catalog.empty and "code" not in catalog.columns:
        catalog["code"] = catalog.get("commodity", catalog.get("symbol", catalog.get("name", "")))

    # Select actual fuel/rig/location price codes. The catalog itself contains no price.
    fuel_codes: List[str] = []
    if not catalog.empty:
        for _, row in catalog.iterrows():
            code = str(row.get("code") or "").upper()
            text = " ".join(str(row.get(c, "")) for c in ("code", "name", "category", "description", "unit")).upper()
            if any(k in text for k in ("DIESEL", "GASOLINE", "GASOIL", "MOGAS", "JET", "KEROSENE", "VLSFO", "HFO", "MGO", "BUNKER")):
                if code:
                    fuel_codes.append(code)
    fuel_codes = list(dict.fromkeys(fuel_codes))[:140]

    price_frames: List[pd.DataFrame] = [live]
    messages: List[str] = []
    # Batch endpoint is one request per chunk and returns actual price rows.
    for start in range(0, len(fuel_codes), 50):
        chunk = fuel_codes[start: start + 50]
        payload, meta = _oil27_api_call(
            "POST",
            "/v1/prices/batch",
            tuple(),
            (("codes", chunk), ("fields", ["code", "name", "price", "currency", "unit", "change", "change_pct", "change_24h", "change_24h_percent", "created_at", "updated_at", "source"])),
            refresh_token,
        )
        frame = _oil26_parse_live(payload)
        if not frame.empty:
            price_frames.append(frame)
        elif meta.get("message"):
            messages.append(str(meta.get("message"))[:120])
        if meta.get("status") in {"entitlement-required", "missing-key"}:
            break

    prices = pd.concat([x for x in price_frames if isinstance(x, pd.DataFrame) and not x.empty], ignore_index=True) if any(isinstance(x, pd.DataFrame) and not x.empty for x in price_frames) else pd.DataFrame()
    if prices.empty:
        return pd.DataFrame(), {
            "status": live_meta.get("status", catalog_meta.get("status", "provider-unavailable")),
            "source": "OilPriceAPI",
            "message": " | ".join(messages) or live_meta.get("message", catalog_meta.get("message", "")),
        }
    prices = prices.drop_duplicates("code", keep="last")
    if not catalog.empty:
        enrich_cols = [c for c in ("code", "name", "description", "category", "unit", "currency", "source", "region", "country") if c in catalog.columns]
        prices = prices.merge(catalog[enrich_cols].drop_duplicates("code"), on="code", how="left", suffixes=("", "_catalog"))
        for col in ("name", "unit", "currency", "source", "category"):
            cat_col = f"{col}_catalog"
            if cat_col in prices.columns:
                prices[col] = prices[col].replace("", np.nan).fillna(prices[cat_col])
    prices["Region"] = prices.apply(_oil27_region, axis=1)
    return prices, {"status": "live", "source": "OilPriceAPI prices/all + batch", "message": " | ".join(messages)[:240]}


def _oil26_render_fuels(refresh_token: int) -> None:
    work, meta = _oil27_full_fuel_prices(refresh_token)
    if work.empty:
        _html(
            '<div class="o26-status"><strong>Regional fuel prices unavailable.</strong><br>'
            f'{_escape(meta.get("message", ""))}. The page no longer displays a catalog table filled with dashes.</div>'
        )
        return

    _html(
        f'<div class="o26-note">{len(work)} priced instruments · {_escape(meta.get("source", "OilPriceAPI"))} · '
        'currency and unit are read from each returned record.</div>'
    )
    region_order = ["Singapore", "Europe", "Canada", "United States", "Maritime Bunkers", "Global / Other"]
    for region in region_order + sorted(set(work["Region"]) - set(region_order)):
        region_df = work.loc[work["Region"] == region].copy()
        if region_df.empty:
            continue
        _html(f'<div class="o26-group">{_escape(region)} · {len(region_df)} markets</div>')
        cards: List[str] = []
        for _, row in region_df.sort_values("price", ascending=False, na_position="last").head(18).iterrows():
            pct = _safe_float(row.get("change_pct"))
            change = _safe_float(row.get("change"))
            klass = "o26-up" if pct is not None and pct > 0 else "o26-down" if pct is not None and pct < 0 else "o26-flat"
            cards.append(
                '<div class="o26-kpi">'
                f'<div class="o26-label">{_escape(row.get("name") or row.get("code"))}</div>'
                f'<div class="o26-value">{_oil27_num(row.get("price"), 2)} <span style="font-size:10px;color:#99a6b5">{_escape(_oil27_unit_text(row))}</span></div>'
                f'<div class="o26-delta {klass}">{_oil27_num(change, 2, True)} · {_oil27_num(pct, 2, True)}%</div>'
                '</div>'
            )
        _html('<div class="o27-live-grid">' + ''.join(cards) + '</div>')
        display_cols = [c for c in ("name", "code", "price", "change", "change_pct", "currency", "unit", "source") if c in region_df.columns]
        with st.expander(f"Full {region} table ({len(region_df)})", expanded=False):
            _oil27_dataframe(_oil27_style_numeric(region_df[display_cols], 2), key=f"o27_fuels_{abs(hash(region)) % 10_000_000}", height=min(620, 42 + len(region_df) * 35))


