def _oil26_extract_contracts(payload: Any) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for rec in _oil27_iter_records(payload):
        label = rec.get("contract_month") or rec.get("contract") or rec.get("month") or rec.get("name") or rec.get("symbol") or rec.get("expiration")
        price = _safe_float(rec.get("last_price", rec.get("price", rec.get("settlement", rec.get("close", rec.get("last"))))))
        if label is None or price is None:
            continue
        rows.append(
            {
                "contract": str(label),
                "price": price,
                "change": _safe_float(rec.get("change", rec.get("change_percent", rec.get("change_pct")))),
                "volume": _safe_float(rec.get("volume")),
                "open_interest": _safe_float(rec.get("open_interest")),
                "expiration": rec.get("expiration") or rec.get("expiry") or rec.get("contract_month") or rec.get("date"),
                "updated_at": rec.get("updated_at") or rec.get("timestamp"),
            }
        )
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    # Contract month YYYY-MM is directly sortable after conversion.
    out["expiration_dt"] = pd.to_datetime(out["expiration"], errors="coerce")
    out = out.sort_values(["expiration_dt", "contract"], na_position="last").drop_duplicates("contract")
    return out.reset_index(drop=True)


def _oil27_future_months(count: int = 13) -> List[Tuple[datetime, str]]:
    now = datetime.now(timezone.utc)
    months: List[Tuple[datetime, str]] = []
    month_codes = "FGHJKMNQUVXZ"
    for offset in range(count + 2):
        month_index = now.month - 1 + offset
        year = now.year + month_index // 12
        month = month_index % 12 + 1
        dt = datetime(year, month, 1, tzinfo=timezone.utc)
        code = month_codes[month - 1]
        months.append((dt, f"{code}{str(year)[-2:]}"))
    return months


@st.cache_data(ttl=1800, show_spinner=False)
def _oil27_yahoo_curve(prefix: str, refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if yf is None:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": "yfinance unavailable"}
    rows: List[Dict[str, Any]] = []
    messages: List[str] = []
    for dt, month_code in _oil27_future_months(14):
        symbol = f"{prefix}{month_code}.NYM"
        try:
            hist = yf.Ticker(symbol).history(period="7d", interval="1d", auto_adjust=False)
            if hist is None or hist.empty or "Close" not in hist.columns:
                continue
            close = pd.to_numeric(hist["Close"], errors="coerce").dropna()
            if close.empty:
                continue
            volume = pd.to_numeric(hist.get("Volume"), errors="coerce").dropna() if "Volume" in hist.columns else pd.Series(dtype=float)
            change = None
            if len(close) >= 2 and close.iloc[-2] != 0:
                change = (close.iloc[-1] / close.iloc[-2] - 1.0) * 100.0
            rows.append(
                {
                    "contract": dt.strftime("%b %Y"),
                    "price": float(close.iloc[-1]),
                    "change": change,
                    "volume": float(volume.iloc[-1]) if not volume.empty else np.nan,
                    "open_interest": np.nan,
                    "expiration": dt,
                    "updated_at": close.index[-1],
                    "expiration_dt": pd.Timestamp(dt).tz_convert(None),
                    "symbol": symbol,
                }
            )
        except Exception as exc:
            messages.append(str(exc)[:70])
    return pd.DataFrame(rows), {
        "status": "fallback-live" if rows else "provider-unavailable",
        "source": "Yahoo/yfinance contract strip",
        "message": " | ".join(messages[:3]),
    }


def _oil27_load_curve(spec: Mapping[str, Any], refresh_token: int) -> Tuple[pd.DataFrame, Dict[str, Any], str]:
    messages: List[str] = []
    for endpoint in spec.get("routes", ()):
        payload, meta = _oil27_api_call("GET", str(endpoint), tuple(), tuple(), refresh_token)
        contracts = _oil26_extract_contracts(payload)
        if not contracts.empty:
            return contracts, meta, str(endpoint)
        messages.append(f"{endpoint}: {meta.get('status')} {meta.get('message', '')}"[:220])
        if meta.get("status") == "entitlement-required":
            # Other aliases may still be available under the same package.
            continue
    fallback, fallback_meta = _oil27_yahoo_curve(str(spec.get("yahoo_prefix", "")), refresh_token)
    if not fallback.empty:
        fallback_meta["message"] = "OilPriceAPI routes unavailable; Yahoo contract strip used. " + " | ".join(messages[:2])
        return fallback, fallback_meta, "Yahoo/yfinance"
    return pd.DataFrame(), {
        "status": "provider-unavailable",
        "source": "OilPriceAPI + Yahoo/yfinance",
        "message": " | ".join(messages)[:600] or fallback_meta.get("message", ""),
    }, ""


def _oil27_parse_history(payload: Any) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for rec in _oil27_iter_records(payload):
        date = rec.get("date") or rec.get("updated_at") or rec.get("timestamp")
        value = _safe_float(rec.get("settlement", rec.get("close", rec.get("last_price", rec.get("price")))))
        if date is not None and value is not None:
            rows.append({"date": date, "value": value, "volume": _safe_float(rec.get("volume"))})
    if not rows:
        return pd.DataFrame()
    out = pd.DataFrame(rows)
    out["date"] = pd.to_datetime(out["date"], errors="coerce", utc=True).dt.tz_convert(None)
    out["value"] = pd.to_numeric(out["value"], errors="coerce")
    out["volume"] = pd.to_numeric(out["volume"], errors="coerce")
    return out.dropna(subset=["date", "value"]).sort_values("date").drop_duplicates("date")


def _oil27_load_history(spec: Mapping[str, Any], contracts: pd.DataFrame, refresh_token: int) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    end = datetime.now(timezone.utc).date()
    start = end - timedelta(days=220)
    params = (("from", start.isoformat()), ("to", end.isoformat()))
    for endpoint in spec.get("history_routes", ()):
        payload, meta = _oil27_api_call("GET", str(endpoint), params, tuple(), refresh_token)
        history = _oil27_parse_history(payload)
        if not history.empty:
            return history, meta
    # Yahoo fallback: use the front contract symbol if available.
    if yf is not None and not contracts.empty and "symbol" in contracts.columns and pd.notna(contracts.iloc[0].get("symbol")):
        symbol = str(contracts.iloc[0]["symbol"])
        try:
            hist = yf.Ticker(symbol).history(period="8mo", interval="1d", auto_adjust=False)
            if hist is not None and not hist.empty:
                out = pd.DataFrame({"date": hist.index, "value": hist["Close"], "volume": hist.get("Volume")})
                out["date"] = pd.to_datetime(out["date"], errors="coerce", utc=True).tz_convert(None)
                return out.dropna(subset=["date", "value"]), {"status": "fallback-live", "source": "Yahoo/yfinance", "message": ""}
        except Exception as exc:
            return pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": str(exc)[:180]}
    return pd.DataFrame(), {"status": "provider-unavailable", "source": "OilPriceAPI", "message": "Historical endpoint unavailable"}


