        _html(
            '<div class="o26-meta">'
            f'<span class="o26-chip">Front {_oil27_num(front, 2)} {_escape(spec["unit"])}</span>'
            f'<span class="o26-chip">Back {_oil27_num(back, 2)}</span>'
            f'<span class="o26-chip">Spread {_oil27_num(curve_spread, 2, True)}%</span>'
            f'<span class="o26-chip o26-chip-source">{_escape(structure)} · {len(contracts)} contracts · {_escape(meta.get("source", endpoint))}</span>'
            '</div>'
        )

        contract_cards: List[str] = []
        for idx, row in contracts.head(18).iterrows():
            front_class = " o27-contract-front" if idx == contracts.index[0] else ""
            vol = _safe_float(row.get("volume"))
            oi = _safe_float(row.get("open_interest"))
            secondary = f"Vol {_oil27_num(vol, 0)}" if vol is not None else f"OI {_oil27_num(oi, 0)}" if oi is not None else ""
