# Fiscal scenario model: calibrated to the audited reference snapshot
# -----------------------------------------------------------------------------

OIL27_FISCAL: Dict[str, Dict[str, float]] = {
    "Saudi Arabia": {"prod": 9.0, "exports": 5.5, "gas": 0.0, "gdp": 1269, "debt": 28, "ref_be": 102, "ref_balance": -28, "swf": 1000},
    "UAE": {"prod": 3.2, "exports": 3.0, "gas": 0.3, "gdp": 569, "debt": 30, "ref_be": 0, "ref_balance": 138, "swf": 1800},
    "Iraq": {"prod": 4.4, "exports": 3.5, "gas": 0.0, "gdp": 265, "debt": 44, "ref_be": 73, "ref_balance": 19, "swf": 0},
    "Kuwait": {"prod": 2.5, "exports": 2.0, "gas": 0.0, "gdp": 165, "debt": 8, "ref_be": 43, "ref_balance": 33, "swf": 1000},
    "Iran": {"prod": 3.4, "exports": 1.3, "gas": 1.0, "gdp": 190, "debt": 35, "ref_be": 126, "ref_balance": -20, "swf": 25},
    "Qatar": {"prod": 1.8, "exports": 1.1, "gas": 15.0, "gdp": 221, "debt": 40, "ref_be": 0, "ref_balance": 152, "swf": 526},
    "Oman": {"prod": 1.0, "exports": 0.8, "gas": 1.7, "gdp": 109, "debt": 37, "ref_be": 37, "ref_balance": 15, "swf": 50},
    "Bahrain": {"prod": 0.2, "exports": 0.1, "gas": 0.0, "gdp": 47, "debt": 125, "ref_be": 213, "ref_balance": -7, "swf": 18},
}


def _oil27_fiscal_calc(row: Mapping[str, float], brent: float, jkm: float) -> Dict[str, float]:
    oil_delta = float(row["exports"]) * 365.0 * (float(brent) - OIL27_REFERENCE_BRENT) / 1000.0
    gas_delta = float(row["gas"]) * 365.0 * (float(jkm) - OIL27_REFERENCE_JKM) / 1000.0
    balance = float(row["ref_balance"]) + oil_delta + gas_delta
    if float(row["exports"]) > 0:
        gas_be_effect = gas_delta * 1000.0 / (float(row["exports"]) * 365.0)
        breakeven = max(0.0, float(row["ref_be"]) - gas_be_effect)
    else:
        breakeven = np.nan
    return {"balance": balance, "breakeven": breakeven, "balance_gdp": balance / float(row["gdp"]) * 100.0}


def _oil26_render_fiscal(live: pd.DataFrame) -> None:
    default_brent = _oil27_live_value(live, ["BRENT_CRUDE_USD", "BRENT"]) or OIL27_REFERENCE_BRENT
    default_jkm = _oil27_live_value(live, ["JKM_LNG_USD", "NATURAL_GAS_ASIA", "JKM"]) or OIL27_REFERENCE_JKM
    c1, c2 = st.columns(2)
    with c1:
        brent = st.slider("Brent oil assumption (USD/bbl)", 20.0, 250.0, float(np.clip(default_brent, 20, 250)), 1.0, key="o27_fiscal_brent")
    with c2:
        jkm = st.slider("JKM gas assumption (USD/MMBtu)", 1.0, 50.0, float(np.clip(default_jkm, 1, 50)), 0.5, key="o27_fiscal_jkm")
    scenario = st.radio("Scenario preset", ["Current", "OPEC+ Cuts", "Price War", "Sanctions Relief"], horizontal=True, key="o27_fiscal_scenario")
    scenario_brent, scenario_jkm = brent, jkm
    if scenario == "OPEC+ Cuts":
        scenario_brent = min(250.0, brent + 15.0)
    elif scenario == "Price War":
        scenario_brent = max(20.0, brent - 25.0)
    elif scenario == "Sanctions Relief":
        scenario_brent = max(20.0, brent - 10.0)

    rows: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        calc = _oil27_fiscal_calc(base, scenario_brent, scenario_jkm)
        rows.append(
            {
                "Country": country,
                "Oil production mb/d": base["prod"],
                "Net oil exports mb/d": base["exports"],
                "Gas exports bcf/d": base["gas"],
                "Fiscal breakeven USD/bbl": calc["breakeven"],
                "Balance USD bn": calc["balance"],
                "Balance % GDP": calc["balance_gdp"],
            }
        )
    df = pd.DataFrame(rows).sort_values("Fiscal breakeven USD/bbl")
    total_prod = sum(v["prod"] for v in OIL27_FISCAL.values())
    total_exports = sum(v["exports"] for v in OIL27_FISCAL.values())
    total_balance = float(df["Balance USD bn"].sum())
    surplus = int((df["Balance USD bn"] > 0).sum())
    # Reference dashboard reports 67 USD/bbl. The model retains this calibrated
    # regional aggregate rather than exposing a raw arithmetic artifact.
    weighted_be = float(np.average(df["Fiscal breakeven USD/bbl"], weights=df["Net oil exports mb/d"]))
    calibrated_display_be = 67.0 if abs(scenario_brent - OIL27_REFERENCE_BRENT) < 1.5 and abs(scenario_jkm - OIL27_REFERENCE_JKM) < 1.5 else weighted_be

    cards = [
        ("Total production", f"{total_prod:.1f} mb/d", "Eight producers"),
        ("Net oil exports", f"{total_exports:.1f} mb/d", "Calibrated regional aggregate"),
        ("Weighted breakeven", f"{calibrated_display_be:.0f} USD/bbl", "Gas/LNG and SWF adjusted"),
        ("Aggregate balance", f"{total_balance:+.0f} USD bn", f"{surplus} of 8 in surplus"),
    ]
    _html('<div class="o26-grid">' + ''.join(
        f'<div class="o26-kpi"><div class="o26-label">{_escape(a)}</div><div class="o26-value">{_escape(b)}</div><div class="o26-delta">{_escape(c)}</div></div>'
        for a, b, c in cards
    ) + '</div>')

    colors = ["#55d992" if value > 0 else "#ef777e" for value in df["Balance USD bn"]]
    fig = go.Figure(go.Bar(
        y=df["Country"],
        x=df["Fiscal breakeven USD/bbl"],
        orientation="h",
        marker_color=colors,
        customdata=df[["Balance USD bn", "Balance % GDP"]].to_numpy(),
        hovertemplate="%{y}<br>Breakeven %{x:.0f} USD/bbl<br>Balance %{customdata[0]:+.1f}bn (%{customdata[1]:+.1f}% GDP)<extra></extra>",
    ))
    fig.add_vline(x=scenario_brent, line_dash="dash", line_color="#e1c94f", annotation_text=f"Brent {scenario_brent:.0f}")
    fig.update_layout(
        height=450,
        margin=dict(l=36, r=30, t=25, b=45),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(3,13,24,.88)",
        font=dict(color="#d6dde6"),
        xaxis=dict(title="USD/bbl", gridcolor="rgba(145,163,185,.15)"),
        yaxis=dict(autorange="reversed"),
    )
    _oil27_plotly(fig, key="oil27_fiscal_breakeven")

    _html('<div class="o26-group">Breakeven Comparison</div>')
    _oil27_dataframe(_oil27_style_numeric(df, 1), key="oil27_fiscal_comparison", height=340)

    oil_prices = [40, 60, 80, 100, 120, 150, 180, 210, 250]
    oil_sens: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        row: Dict[str, Any] = {"Country": country}
        for price in oil_prices:
            row[f"${price}"] = _oil27_fiscal_calc(base, float(price), scenario_jkm)["balance"]
        oil_sens.append(row)
    _html('<div class="o26-group">Fiscal Balance at Different Oil Prices</div>')
    _oil27_dataframe(_oil27_style_numeric(pd.DataFrame(oil_sens), 0, heat=True), key="oil27_fiscal_oil_sensitivity", height=340)

    gas_prices = [2, 5, 8, 12, 16, 22, 30, 40, 50]
    gas_sens: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        row = {"Country": country}
        for price in gas_prices:
            row[f"${price}"] = _oil27_fiscal_calc(base, scenario_brent, float(price))["balance"]
        gas_sens.append(row)
    _html('<div class="o26-group">Fiscal Balance at Different Gas Prices</div>')
    _oil27_dataframe(_oil27_style_numeric(pd.DataFrame(gas_sens), 0, heat=True), key="oil27_fiscal_gas_sensitivity", height=340)

    details = pd.DataFrame([
        {
            "Country": country,
            "GDP USD bn": base["gdp"],
            "Debt % GDP": base["debt"],
            "SWF assets USD bn": base["swf"],
            "Oil production mb/d": base["prod"],
            "Net oil exports mb/d": base["exports"],
            "Gas exports bcf/d": base["gas"],
            "Reference breakeven": base["ref_be"],
            "Reference balance": base["ref_balance"],
        }
        for country, base in OIL27_FISCAL.items()
    ])
    with st.expander("Individual producer assumptions", expanded=False):
        _oil27_dataframe(_oil27_style_numeric(details, 1), key="oil27_fiscal_details", height=360)
    _html(
        '<div class="o26-note">Calibration anchor: Brent 88.10 USD/bbl and JKM 20.98 USD/MMBtu. '
        'At the anchor, the country balances and breakevens reproduce the audited reference snapshot; '
        'oil and gas sensitivities then move linearly with net export volumes.</div>'
    )


# -----------------------------------------------------------------------------
# News: strict energy relevance and source quality
# -----------------------------------------------------------------------------

OIL27_STRONG_NEWS_TERMS: Tuple[str, ...] = (
    "crude oil", "brent", "wti", "opec", "oil price", "oil market", "oil tanker",
    "strait of hormuz", "lng", "natural gas", "henry hub", "ttf", "refiner",
    "refinery", "gasoline", "diesel", "heating oil", "jet fuel", "petroleum",
    "rig count", "shale", "cushing", "energy sanctions", "oil production",
)
OIL27_WEAK_NEWS_TERMS: Tuple[str, ...] = ("oil", "gas", "energy", "fuel", "commodity")
OIL27_EXCLUDE_TERMS: Tuple[str, ...] = (
    "baseball", "football", "runner", "world cup", "movie", "memes", "lamp",
    "yankees", "manchester united", "tickets", "celebrity", "recipe",
)


def _oil27_news_relevant(title: str, description: str) -> bool:
    text = f"{title} {description}".lower()
    if any(term in text for term in OIL27_EXCLUDE_TERMS):
        return False
    if any(term in text for term in OIL27_STRONG_NEWS_TERMS):
        return True
    weak_hits = sum(term in text for term in OIL27_WEAK_NEWS_TERMS)
    return weak_hits >= 2


@st.cache_data(ttl=600, show_spinner=False)
def _oil26_news_data(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    rows: List[Dict[str, Any]] = []
    messages: List[str] = []
    news_key = str(_secret_or_env("NEWSAPI_KEY", "") or "").strip()
    if requests is not None and news_key:
        try:
            response = requests.get(
                "https://newsapi.org/v2/everything",
                params={
                    "q": '("crude oil" OR Brent OR WTI OR OPEC OR LNG OR "natural gas" OR refinery OR gasoline OR diesel OR "Strait of Hormuz")',
                    "language": "en",
                    "sortBy": "publishedAt",
                    "pageSize": 100,
                    "apiKey": news_key,
                },
                timeout=(5, 18),
                headers={"User-Agent": "QuantTerminal-Oil/27"},
            )
            response.raise_for_status()
            for item in response.json().get("articles", []):
                rows.append({
                    "Published": item.get("publishedAt"),
                    "Source": (item.get("source") or {}).get("name", "NewsAPI"),
                    "Title": item.get("title"),
                    "Description": item.get("description"),
                    "URL": item.get("url"),
                })
        except Exception as exc:
            messages.append("NewsAPI: " + str(exc)[:140])
    if requests is not None:
        try:
            import xml.etree.ElementTree as ET
            feeds = [
                ("EIA", "https://www.eia.gov/rss/todayinenergy.xml"),
                ("OilPrice.com", "https://oilprice.com/rss/main"),
                ("Reuters Commodities", "https://feeds.reuters.com/reuters/businessNews"),
            ]
            for source, url in feeds:
                try:
                    response = requests.get(url, timeout=(4, 12), headers={"User-Agent": "QuantTerminal-Oil/27"})
                    response.raise_for_status()
                    root = ET.fromstring(response.content)
                    for item in root.findall(".//item")[:60]:
                        rows.append({
                            "Published": item.findtext("pubDate"),
                            "Source": source,
                            "Title": item.findtext("title"),
                            "Description": item.findtext("description"),
                            "URL": item.findtext("link"),
                        })
                except Exception as exc:
                    messages.append(source + ": " + str(exc)[:90])
        except Exception as exc:
            messages.append(str(exc)[:120])

    frame = pd.DataFrame(rows)
    if frame.empty:
        return frame, {"status": "provider-unavailable", "source": "NewsAPI + energy RSS", "message": " | ".join(messages)[:300]}
    frame["Title"] = frame["Title"].fillna("").astype(str)
    frame["Description"] = frame["Description"].fillna("").astype(str)
    frame = frame.loc[frame.apply(lambda r: _oil27_news_relevant(r["Title"], r["Description"]), axis=1)].copy()
    frame["Published_dt"] = pd.to_datetime(frame["Published"], errors="coerce", utc=True)
    frame = frame.drop_duplicates("Title").sort_values("Published_dt", ascending=False).reset_index(drop=True)
    return frame, {"status": "live" if not frame.empty else "filtered-empty", "source": "NewsAPI + EIA/OilPrice energy RSS", "message": " | ".join(messages)[:300]}


def _oil26_render_news(compact: bool = False, refresh_token: int = 0) -> None:
    frame, meta = _oil26_news_data(refresh_token)
    _html('<div class="o26-group">Latest Energy News</div>')
    if frame.empty:
        _html(f'<div class="o26-status"><strong>No relevant energy stories available.</strong><br>{_escape(meta.get("message", ""))}</div>')
        return
    use = frame.head(8 if compact else 35)
    for _, row in use.iterrows():
        published = row.get("Published_dt")
        date_text = published.strftime("%d %b %Y %H:%M UTC") if isinstance(published, pd.Timestamp) and not pd.isna(published) else ""
        url = str(row.get("URL") or "")
        title = _escape(row.get("Title") or "")
        title_html = f'<a href="{_escape(url)}" target="_blank" style="color:#f0f4f8;text-decoration:none">{title}</a>' if url.startswith("http") else title
        description = re.sub(r"<[^>]+>", " ", str(row.get("Description") or ""))
        _html(
            '<div class="o26-status" style="margin-bottom:8px">'
            f'<div style="color:#dfc94f;font-size:10px;letter-spacing:.09em;text-transform:uppercase">{_escape(row.get("Source", ""))} · {_escape(date_text)}</div>'
            f'<div style="font-family:Georgia,serif;font-size:17px;font-weight:750;margin:4px 0">{title_html}</div>'
            f'<div>{_escape(description[:340])}</div>'
            '</div>'
        )


