def _oil27_quality(refresh_token: int) -> None:
    live, live_meta = _oil26_load_live(refresh_token)
    token, secret_name = _oil27_secret()
    endpoint_rows: List[Dict[str, Any]] = [
        {
            "Layer": "Live prices",
            "Provider": live_meta.get("source", "OilPriceAPI"),
            "Status": live_meta.get("status", "unknown"),
            "Loaded": len(live),
            "Endpoint": live_meta.get("endpoint", "/v1/prices/all or batch"),
            "Secret alias": secret_name or "not configured",
            "Message": live_meta.get("message", ""),
        }
    ]
    for spec in OIL27_FUTURES:
        contracts, meta, endpoint = _oil27_load_curve(spec, refresh_token)
        endpoint_rows.append(
            {
                "Layer": f"Futures {spec['name']}",
                "Provider": meta.get("source", "OilPriceAPI"),
                "Status": meta.get("status", "unknown"),
                "Loaded": len(contracts),
                "Endpoint": endpoint,
                "Secret alias": secret_name or "not configured",
                "Message": meta.get("message", ""),
            }
        )
    rig_payload, rig_meta = _oil27_api_call("GET", "/v1/ei/rig_counts/latest", tuple(), tuple(), refresh_token)
    endpoint_rows.append(
        {
            "Layer": "Rig counts",
            "Provider": rig_meta.get("source", "OilPriceAPI"),
            "Status": rig_meta.get("status", "unknown"),
            "Loaded": int(bool(rig_payload)),
            "Endpoint": "/v1/ei/rig_counts/latest",
            "Secret alias": secret_name or "not configured",
            "Message": rig_meta.get("message", ""),
        }
    )
    _html('<div class="o26-group">OilPriceAPI Endpoint Audit</div>')
    _oil27_dataframe(pd.DataFrame(endpoint_rows), key="oil27_quality_endpoints", height=360)

    # Keep the full V26 public-provider chart audit, but avoid its obsolete
    # futures route calls by reproducing the essential panel census here.
    pack = _oil26_load("Data Quality", refresh_token)
    rows: List[Dict[str, Any]] = []
    for spec in OIL26_CHARTS:
        loaded = 0
        dates: List[pd.Timestamp] = []
        for item in spec.get("series", []):
            frame = _oil26_series_frame(item, pack)
            if not frame.empty:
                loaded += 1
                dates.append(frame["date"].max())
        expected = int(spec.get("expected_curves", len(spec.get("series", []))))
        rows.append(
            {
                "Section": spec.get("section"),
                "No": spec.get("n"),
                "Panel": spec.get("title"),
                "Expected": expected,
                "Loaded": loaded,
                "Status": "Complete" if loaded == expected else "Unavailable" if loaded == 0 else "Partial",
                "Latest": max(dates).strftime("%Y-%m-%d") if dates else "—",
                "Source": spec.get("source"),
                "Limitation": spec.get("limitation", ""),
            }
        )
    audit = pd.DataFrame(rows)
    summary = audit.groupby(["Section", "Status"]).size().unstack(fill_value=0).reset_index()
    _html('<div class="o26-group">Reference Panel Completeness</div>')
    _oil27_dataframe(summary, key="oil27_quality_summary", height=420)
    with st.expander("Full panel registry", expanded=False):
        _oil27_dataframe(audit, key="oil27_quality_registry", height=720)


def _oil26_quality(refresh_token: int) -> None:
    _oil27_quality(refresh_token)


def _oil26_render_reference_section(section: str, refresh_token: int) -> None:
    _oil27_chart_controls()
    pack = _oil26_load(section, refresh_token)
    if section == "Supply":
        _oil26_render_hormuz(refresh_token)
    if section == "Refining":
        _oil26_render_refining_intelligence(pack)
    specs = [x for x in OIL26_CHARTS if x["section"] == section]
    if section == "Crisis":
        groups = [
            ("Energy Supply", range(1, 8)),
            ("Commodities", range(8, 20)),
            ("Crack Spreads", range(20, 26)),
            ("Macro Impact", range(26, 36)),
        ]
        for label, numbers in groups:
            _html(f'<div class="o26-group">Crisis - {_escape(label)}</div>')
            _oil26_render_grid([x for x in specs if x["n"] in numbers], pack, f"o27_crisis_{label}")
    else:
        _oil26_render_grid(specs, pack, f"o27_{section}")


def _render_oil_page_v26(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, price_data, analysis
    _oil26_css()
    section = st.radio("Oil section", OIL26_SECTIONS, horizontal=True, key="oil26_section", label_visibility="collapsed")
    c1, c2 = st.columns([1, 7])
    with c1:
        refresh = st.button("Refresh", key="oil27_refresh")
    nonce = int(st.session_state.get("oil27_nonce", 0))
    if refresh:
        nonce += 1
        st.session_state["oil27_nonce"] = nonce
        try:
            st.cache_data.clear()
        except Exception:
            pass

    _oil26_header(section)
    _html(f'<div class="o26-note">{_escape(OIL27_VERSION)} · Oil-only runtime override · all non-Oil routes remain delegated unchanged.</div>')

    if section not in {"Dashboard", "News", "Data Quality"}:
        live, meta = _oil26_load_live(nonce)
        _html(
            f'<div class="o26-note">Live quote strip · {_escape(meta.get("status", "unknown"))} · '
            'historical panels remain independently sourced from FRED/EIA/IMF.</div>'
        )
        _oil26_live_cards(live, 17)

    if section == "Dashboard":
        _oil26_render_dashboard(nonce)
    elif section in {"Prices", "Supply", "Demand", "Inventories", "Refining", "Trade Flows", "Geopolitical", "Crisis"}:
        _oil26_render_reference_section(section, nonce)
    elif section == "Drilling":
        _oil26_render_drilling(nonce)
    elif section == "Fuels":
        _oil26_render_fuels(nonce)
    elif section == "Futures":
        _oil26_render_futures(nonce)
    elif section == "Fiscal":
        live, _ = _oil26_load_live(nonce)
        _oil26_render_fiscal(live)
    elif section == "News":
        _oil26_render_news(compact=False, refresh_token=nonce)
    elif section == "Data Quality":
        _oil26_quality(nonce)


