def _oil28_section_intro(section: str, title: Optional[str] = None, count: Optional[str] = None, description: Optional[str] = None) -> None:
    meta = OIL28_SECTION_META.get(section, (section, "", ""))
    resolved_title = title or meta[0]
    resolved_count = count if count is not None else meta[1]
    resolved_description = description or meta[2]
    _html(
        '<div class="o28-section-head"><div class="o28-section-top"><div>'
        '<div class="o28-eyebrow">Global Energy Observatory</div>'
        f'<div class="o28-title">{_escape(resolved_title)}</div></div>'
        f'<div class="o28-count">{_escape(resolved_count)}</div></div>'
        f'<div class="o28-desc">{_escape(resolved_description)}</div></div>'
    )


