OIL28_RISK_PROXIES: Tuple[Tuple[str, str], ...] = (
    ("ITA", "US Aerospace & Defense"),
    ("XAR", "S&P Aerospace & Defense"),
    ("BDRY", "Dry Bulk Shipping"),
    ("SFL", "SFL Shipping"),
    ("XLE", "Energy Select Sector"),
    ("SPY", "S&P 500"),
    ("SAR=X", "USD / Saudi Riyal"),
    ("AED=X", "USD / UAE Dirham"),
    ("ILS=X", "USD / Israeli Shekel"),
    ("GC=F", "Gold Futures"),
    ("GLD", "SPDR Gold ETF"),
)


@st.cache_data(ttl=900, show_spinner=False)
def _oil28_risk_proxy_data(refresh_token: int = 0) -> pd.DataFrame:
    del refresh_token
    rows: List[Dict[str, Any]] = []
    for symbol, name in OIL28_RISK_PROXIES:
        try:
            frame, _ = _fetch_yahoo_history(symbol, "1mo")
            if frame is None or frame.empty:
                continue
            values = pd.to_numeric(frame["close"], errors="coerce").dropna()
            if values.empty:
                continue
            latest = float(values.iloc[-1])
            change = (latest / float(values.iloc[-2]) - 1.0) * 100.0 if len(values) > 1 and float(values.iloc[-2]) != 0 else np.nan
            rows.append({"Symbol": symbol, "Name": name, "Latest": latest, "Change %": change})
        except Exception:
            continue
    return pd.DataFrame(rows)


def _oil28_render_risk_snapshot(refresh_token: int) -> None:
    frame = _oil28_risk_proxy_data(refresh_token)
    _html('<div class="o26-group">Risk Proxy Snapshot</div>')
    if frame.empty:
        _html('<div class="o26-status"><strong>Risk proxy snapshot unavailable.</strong><br>The seven historical risk panels remain available below.</div>')
        return
    cards: List[str] = []
    for _, row in frame.iterrows():
        pct = _safe_float(row.get("Change %"))
        klass = "o28-positive" if pct is not None and pct > 0 else "o28-negative" if pct is not None and pct < 0 else ""
        cards.append(
            '<div class="o28-proxy">'
            f'<div class="o28-proxy-symbol">{_escape(row.get("Symbol", ""))}</div>'
            f'<div class="o28-proxy-name">{_escape(row.get("Name", ""))}</div>'
            f'<div class="o28-proxy-value">{_oil27_num(row.get("Latest"), 2)}</div>'
            f'<div class="o28-proxy-change {klass}">{_oil27_num(pct, 2, True)}%</div>'
            '</div>'
        )
    _html('<div class="o28-proxy-grid">' + ''.join(cards) + '</div>')


def _oil28_render_crisis_snapshot(refresh_token: int) -> None:
    live, meta = _oil26_load_live(refresh_token)
    _html('<div class="o26-group">Key Commodity Prices</div>')
    if isinstance(live, pd.DataFrame) and not live.empty:
        _oil26_live_cards(live, 12)
        spreads = _oil26_market_spreads(live)
        spreads = spreads.loc[pd.to_numeric(spreads["Value"], errors="coerce").notna()].head(16)
        _html('<div class="o26-group">Live Crude Spreads & Refinery Margins</div>')
        cards: List[str] = []
        for _, row in spreads.iterrows():
            cards.append(
                '<div class="o28-summary">'
                f'<div class="o28-summary-name">{_escape(row.get("Indicator", ""))}</div>'
                f'<div class="o28-summary-value">{_oil27_num(row.get("Value"), 2, True)}</div>'
                f'<div class="o28-summary-sub">{_escape(row.get("Unit", ""))} · {_escape(row.get("Interpretation", ""))}</div>'
                '</div>'
            )
        _html('<div class="o28-summary-grid">' + ''.join(cards) + '</div>')
    else:
        _html(f'<div class="o26-status"><strong>Live crisis snapshot unavailable.</strong><br>{_escape(meta.get("message", ""))}</div>')


# -----------------------------------------------------------------------------
# Reference sections: preserve the two-column Quant Terminal structure while
# matching RoboMacro titles, ordering, special snapshots and refining content.
# -----------------------------------------------------------------------------

def _oil26_render_reference_section(section: str, refresh_token: int) -> None:
    _oil28_section_intro(section)
    if section == "Supply":
        _oil26_render_hormuz(refresh_token)
    elif section == "Geopolitical":
        _oil28_render_risk_snapshot(refresh_token)
    elif section == "Crisis":
        _oil28_render_crisis_snapshot(refresh_token)

    _oil27_chart_controls()
    pack = _oil26_load(section, refresh_token)
    specs = [item for item in OIL26_CHARTS if item.get("section") == section]
    if section == "Crisis":
        groups = (
            ("Energy Supply", range(1, 8)),
            ("Commodities", range(8, 20)),
            ("Crack Spreads", range(20, 26)),
            ("Macro Impact", range(26, 36)),
        )
        for label, numbers in groups:
            group_specs = [item for item in specs if item.get("n") in numbers]
            _html(f'<div class="o26-group">Crisis - {_escape(label)} · {len(group_specs)} charts</div>')
            _oil26_render_grid(group_specs, pack, f"o28_crisis_{label}")
    else:
        _oil26_render_grid(specs, pack, f"o28_{section}")

    if section == "Refining":
        _html('<div class="o26-group">Refinery Market Intelligence</div>')
        _oil26_render_refining_intelligence(pack)


