# -----------------------------------------------------------------------------
# Futures: five-market summary, grouped curves, visible institutional tables,
# then front-month histories. This is the main V28 equivalence upgrade.
# -----------------------------------------------------------------------------

def _oil28_curve_structure(front: Optional[float], back: Optional[float]) -> Tuple[Optional[float], str, str]:
    spread = None if front in (None, 0) or back is None else (back / front - 1.0) * 100.0
    if spread is not None and spread > 0.15:
        return spread, "CONTANGO", "o28-contango"
    if spread is not None and spread < -0.15:
        return spread, "BACKWARDATION", "o28-backwardation"
    return spread, "FLAT", "o28-flat"


def _oil28_contract_table(contracts: pd.DataFrame) -> None:
    headers = ("Contract", "Price", "Change %", "Volume", "Open Interest", "Expiration", "Updated")
    rows: List[str] = []
    use = contracts.head(24).reset_index(drop=True)
    for idx, row in use.iterrows():
        change = _safe_float(row.get("change"))
        change_class = "o28-positive" if change is not None and change > 0 else "o28-negative" if change is not None and change < 0 else ""
        expiration = pd.to_datetime(row.get("expiration"), errors="coerce")
        updated = pd.to_datetime(row.get("updated_at"), errors="coerce", utc=True)
        expiration_text = expiration.strftime("%d %b %Y") if not pd.isna(expiration) else "—"
        updated_text = updated.strftime("%d %b %H:%M") if not pd.isna(updated) else "—"
        rows.append(
            f'<tr class="{"o28-front-row" if idx == 0 else ""}">'
            f'<td>{_escape(row.get("contract", ""))}</td>'
            f'<td>{_oil27_num(row.get("price"), 3)}</td>'
            f'<td class="{change_class}">{_oil27_num(change, 2, True)}%</td>'
            f'<td>{_oil27_num(row.get("volume"), 0)}</td>'
            f'<td>{_oil27_num(row.get("open_interest"), 0)}</td>'
            f'<td>{_escape(expiration_text)}</td>'
            f'<td>{_escape(updated_text)}</td></tr>'
        )
    head = ''.join(f'<th>{_escape(label)}</th>' for label in headers)
    _html('<div class="o28-table-title">Individual Contracts</div><div class="o28-table-wrap"><table class="o28-table"><thead><tr>' + head + '</tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div>')


def _oil28_render_forward_curve(spec: Mapping[str, Any], refresh_token: int, preloaded: Optional[Tuple[pd.DataFrame, Dict[str, Any], str]] = None) -> None:
    contracts, meta, endpoint = preloaded if preloaded is not None else _oil27_load_curve(spec, refresh_token)
    with _oil27_container():
        _html(
            '<div class="o26-card-head">'
            f'<div class="o26-card-k">{_escape(spec["market"])} FUTURES</div>'
            f'<div class="o26-card-t">{_escape(spec["n"])}. {_escape(spec["name"])} - Forward Curve</div>'
            '<div class="o26-card-s">Contract prices, volume/open interest, curve structure, individual maturities and front-month history.</div>'
            '</div>'
        )
        if contracts is None or contracts.empty:
            _html('<div class="o26-status"><strong>Forward curve unavailable after documented provider routes and fallback.</strong><br>' + _escape(meta.get("message", "")) + '</div>')
            return
        contracts = contracts.reset_index(drop=True)
        front = _safe_float(contracts.iloc[0].get("price"))
        back = _safe_float(contracts.iloc[-1].get("price"))
        spread, structure, structure_class = _oil28_curve_structure(front, back)
        front_contract = str(contracts.iloc[0].get("contract") or "—")
        back_contract = str(contracts.iloc[-1].get("contract") or "—")
        _html(
            '<div class="o28-stats">'
            f'<div class="o28-stat"><div class="o28-stat-label">Front Month</div><div class="o28-stat-value">{_oil27_num(front, 3)} { _escape(spec["unit"])}</div><div class="o28-summary-sub">{_escape(front_contract)}</div></div>'
            f'<div class="o28-stat"><div class="o28-stat-label">Back Month</div><div class="o28-stat-value">{_oil27_num(back, 3)} { _escape(spec["unit"])}</div><div class="o28-summary-sub">{_escape(back_contract)}</div></div>'
            f'<div class="o28-stat"><div class="o28-stat-label">Curve Spread</div><div class="o28-stat-value">{_oil27_num(spread, 2, True)}%</div><span class="o28-structure {structure_class}">{_escape(structure)}</span></div>'
            f'<div class="o28-stat"><div class="o28-stat-label">Contracts</div><div class="o28-stat-value">{len(contracts)}</div><div class="o28-summary-sub">{_escape(meta.get("source", endpoint))}</div></div>'
            '</div>'
        )

        volume_col = "volume" if "volume" in contracts.columns and contracts["volume"].notna().any() else "open_interest"
        fig = go.Figure()
        if volume_col in contracts.columns and contracts[volume_col].notna().any():
            fig.add_trace(go.Bar(x=contracts["contract"], y=contracts[volume_col], name="Volume / OI", yaxis="y2", marker_color="#d69a61", opacity=0.25))
        fig.add_trace(go.Scatter(x=contracts["contract"], y=contracts["price"], name="Price", mode="lines+markers", line=dict(color="#ef7f23", width=2.7), marker=dict(size=7, color="#f1c24f", line=dict(width=1, color="#06131f"))))
        fig.update_layout(
            height=420,
            margin=dict(l=48, r=64, t=22, b=72),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(3,13,24,.88)",
            font=dict(color="#d5dde7"),
            hovermode="x unified",
            legend=dict(orientation="h", y=-0.23),
            xaxis=dict(gridcolor="rgba(145,163,185,.13)"),
            yaxis=dict(title=spec["unit"], gridcolor="rgba(145,163,185,.15)"),
            yaxis2=dict(title="Volume / OI", overlaying="y", side="right", showgrid=False),
        )
        _oil27_plotly(fig, key=f"oil28_futures_curve_{spec['n']}")
        _oil28_contract_table(contracts)

        history, history_meta = _oil27_load_history(spec, contracts, refresh_token)
        if history is not None and not history.empty:
            _html(f'<div class="o28-table-title">{_escape(spec["name"])} - Front-Month History</div>')
            hfig = go.Figure()
            if "volume" in history.columns and history["volume"].notna().any():
                hfig.add_trace(go.Bar(x=history["date"], y=history["volume"], name="Volume", yaxis="y2", marker_color="#efb386", opacity=0.22))
            hfig.add_trace(go.Scatter(x=history["date"], y=history["value"], name="Front month", mode="lines", line=dict(color="#ef7f23", width=2.3), fill="tozeroy", fillcolor="rgba(239,127,35,.08)"))
            hfig.update_layout(
                height=300,
                margin=dict(l=48, r=62, t=15, b=50),
                paper_bgcolor="rgba(0,0,0,0)",
                plot_bgcolor="rgba(3,13,24,.88)",
                font=dict(color="#d5dde7"),
                hovermode="x unified",
                xaxis=dict(gridcolor="rgba(145,163,185,.13)"),
                yaxis=dict(title=spec["unit"], gridcolor="rgba(145,163,185,.15)"),
                yaxis2=dict(title="Volume", overlaying="y", side="right", showgrid=False),
                legend=dict(orientation="h", y=-0.22),
            )
            _oil27_plotly(hfig, key=f"oil28_futures_history_{spec['n']}")
            _html(f'<div class="o27-small">History source: {_escape(history_meta.get("source", ""))}</div>')
        else:
            _html('<div class="o26-status"><strong>Front-month history unavailable.</strong><br>The live term structure and individual contracts above remain valid.</div>')


def _oil26_render_futures(refresh_token: int) -> None:
    _oil28_section_intro(
        "Futures",
        "Futures Markets",
        "5 forward curves",
        "WTI, Brent, Henry Hub, Heating Oil/ULSD and RBOB term structures with volume, individual contracts and front-month histories.",
    )
    loaded: Dict[str, Tuple[pd.DataFrame, Dict[str, Any], str]] = {
        str(spec["n"]): _oil27_load_curve(spec, refresh_token) for spec in OIL27_FUTURES
    }
    summaries: List[str] = []
    for spec in OIL27_FUTURES:
        contracts, meta, endpoint = loaded[str(spec["n"])]
        if contracts is None or contracts.empty:
            summaries.append('<div class="o28-summary"><div class="o28-summary-name">' + _escape(spec["name"]) + '</div><div class="o28-summary-value">—</div><div class="o28-summary-sub">Curve unavailable</div></div>')
            continue
        front = _safe_float(contracts.iloc[0].get("price"))
        back = _safe_float(contracts.iloc[-1].get("price"))
        spread, structure, klass = _oil28_curve_structure(front, back)
        summaries.append(
            '<div class="o28-summary">'
            f'<div class="o28-summary-name">{_escape(spec["name"])}</div>'
            f'<div class="o28-summary-value">{_oil27_num(front, 3)}</div>'
            f'<div class="o28-summary-sub">{_escape(spec["unit"])} · {len(contracts)} contracts · {_oil27_num(spread, 2, True)}%</div>'
            f'<span class="o28-structure {klass}">{_escape(structure)}</span></div>'
        )
    _html('<div class="o28-summary-grid">' + ''.join(summaries) + '</div>')
    groups = (("Crude Oil", ("1", "2")), ("Natural Gas & LNG", ("3",)), ("Refined Products", ("4", "5")))
    for label, numbers in groups:
        _html(f'<div class="o26-group">{_escape(label)}</div>')
        for spec in OIL27_FUTURES:
            if str(spec["n"]) in numbers:
                _oil28_render_forward_curve(spec, refresh_token, loaded[str(spec["n"])])


# -----------------------------------------------------------------------------
# Fiscal renderer: retain the calibrated model and add the missing gas/SWF
# aggregates plus clearer sectioning around its four institutional tables.
# -----------------------------------------------------------------------------

def _oil26_render_fiscal(live: pd.DataFrame) -> None:
    _oil28_section_intro(
        "Fiscal",
        "OPEC & GCC Fiscal Breakevens",
        "8 producers · interactive",
        "Oil, gas/LNG and sovereign-wealth-adjusted fiscal scenario model with oil and gas sensitivity tables.",
    )
    default_brent = _oil27_live_value(live, ["BRENT_CRUDE_USD", "BRENT"]) or OIL27_REFERENCE_BRENT
    default_jkm = _oil27_live_value(live, ["JKM_LNG_USD", "NATURAL_GAS_ASIA", "JKM"]) or OIL27_REFERENCE_JKM
    c1, c2 = st.columns(2)
    with c1:
        brent = st.slider("Brent oil assumption (USD/bbl)", 20.0, 250.0, float(np.clip(default_brent, 20, 250)), 1.0, key="o28_fiscal_brent")
    with c2:
        jkm = st.slider("JKM gas assumption (USD/MMBtu)", 1.0, 50.0, float(np.clip(default_jkm, 1, 50)), 0.5, key="o28_fiscal_jkm")
    scenario = st.radio("Scenario preset", ["Current", "OPEC+ Cuts", "Price War", "Sanctions Relief"], horizontal=True, key="o28_fiscal_scenario")
    scenario_brent, scenario_jkm = brent, jkm
    if scenario == "OPEC+ Cuts":
        scenario_brent = min(250.0, brent + 15.0)
    elif scenario == "Price War":
        scenario_brent = max(20.0, brent - 25.0)
    elif scenario == "Sanctions Relief":
        scenario_brent = max(20.0, brent - 10.0)

    rows: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        calc = _oil27_fiscal_calc(base, scenario_brent, scenario_jkm)
        rows.append({
            "Country": country,
            "Oil production mb/d": base["prod"],
            "Net oil exports mb/d": base["exports"],
            "Gas exports bcf/d": base["gas"],
            "Fiscal breakeven USD/bbl": calc["breakeven"],
            "Balance USD bn": calc["balance"],
            "Balance % GDP": calc["balance_gdp"],
        })
    df = pd.DataFrame(rows).sort_values("Fiscal breakeven USD/bbl")
    total_prod = sum(value["prod"] for value in OIL27_FISCAL.values())
    total_exports = sum(value["exports"] for value in OIL27_FISCAL.values())
    total_balance = float(df["Balance USD bn"].sum())
    surplus = int((df["Balance USD bn"] > 0).sum())
    weighted_be = float(np.average(df["Fiscal breakeven USD/bbl"], weights=df["Net oil exports mb/d"]))
    calibrated_be = 67.0 if abs(scenario_brent - OIL27_REFERENCE_BRENT) < 1.5 and abs(scenario_jkm - OIL27_REFERENCE_JKM) < 1.5 else weighted_be
    gas_revenue = 148.0 * scenario_jkm / OIL27_REFERENCE_JKM
    swf_income = sum(value["swf"] for value in OIL27_FISCAL.values()) * 0.05
    cards = (
        ("Total Production", f"{total_prod:.1f} mb/d", "Eight producers"),
        ("Net Oil Exports", f"{total_exports:.1f} mb/d", "Regional aggregate"),
        ("Gas Revenue", f"{gas_revenue:.0f} USD bn", "JKM-linked annual estimate"),
        ("SWF Income", f"{swf_income:.0f} USD bn/yr", "5% portfolio yield"),
        ("Weighted Breakeven", f"{calibrated_be:.0f} USD/bbl", "Gas/LNG adjusted"),
        ("Aggregate Balance", f"{total_balance:+.0f} USD bn", f"{surplus} of 8 in surplus"),
    )
    _html('<div class="o28-summary-grid">' + ''.join(
        f'<div class="o28-summary"><div class="o28-summary-name">{_escape(a)}</div><div class="o28-summary-value">{_escape(b)}</div><div class="o28-summary-sub">{_escape(c)}</div></div>'
        for a, b, c in cards
    ) + '</div>')

    _html('<div class="o26-group">Breakeven Comparison</div>')
    colors = ["#55d992" if value > 0 else "#ef777e" for value in df["Balance USD bn"]]
    fig = go.Figure(go.Bar(y=df["Country"], x=df["Fiscal breakeven USD/bbl"], orientation="h", marker_color=colors, customdata=df[["Balance USD bn", "Balance % GDP"]].to_numpy(), hovertemplate="%{y}<br>Breakeven %{x:.0f} USD/bbl<br>Balance %{customdata[0]:+.1f}bn (%{customdata[1]:+.1f}% GDP)<extra></extra>"))
    fig.add_vline(x=scenario_brent, line_dash="dash", line_color="#e1c94f", annotation_text=f"Brent {scenario_brent:.0f}")
    fig.update_layout(height=450, margin=dict(l=36, r=30, t=25, b=45), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(3,13,24,.88)", font=dict(color="#d6dde6"), xaxis=dict(title="USD/bbl", gridcolor="rgba(145,163,185,.15)"), yaxis=dict(autorange="reversed"))
    _oil27_plotly(fig, key="oil28_fiscal_breakeven")
    _oil27_dataframe(_oil27_style_numeric(df, 1), key="oil28_fiscal_comparison", height=340)

    oil_prices = [40, 60, 80, 100, 120, 150, 180, 210, 250]
    oil_sens: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        row: Dict[str, Any] = {"Country": country}
        for price in oil_prices:
            row[f"${price}"] = _oil27_fiscal_calc(base, float(price), scenario_jkm)["balance"]
        oil_sens.append(row)
    _html('<div class="o26-group">Fiscal Balance at Different Oil Prices</div><div class="o28-desc">USD bn; green indicates surplus and red indicates deficit at the current gas assumption.</div>')
    _oil27_dataframe(_oil27_style_numeric(pd.DataFrame(oil_sens), 0, heat=True), key="oil28_fiscal_oil_sensitivity", height=340)

    gas_prices = [2, 5, 8, 12, 16, 22, 30, 40, 50]
    gas_sens: List[Dict[str, Any]] = []
    for country, base in OIL27_FISCAL.items():
        row = {"Country": country}
        for price in gas_prices:
            row[f"${price}"] = _oil27_fiscal_calc(base, scenario_brent, float(price))["balance"]
        gas_sens.append(row)
    _html('<div class="o26-group">Fiscal Balance at Different Gas Prices</div><div class="o28-desc">USD bn; current oil assumption retained.</div>')
    _oil27_dataframe(_oil27_style_numeric(pd.DataFrame(gas_sens), 0, heat=True), key="oil28_fiscal_gas_sensitivity", height=340)

    details = pd.DataFrame([{
        "Country": country,
        "GDP USD bn": base["gdp"],
        "Debt % GDP": base["debt"],
        "SWF assets USD bn": base["swf"],
        "Oil production mb/d": base["prod"],
        "Net oil exports mb/d": base["exports"],
        "Gas exports bcf/d": base["gas"],
        "Reference breakeven": base["ref_be"],
        "Reference balance": base["ref_balance"],
    } for country, base in OIL27_FISCAL.items()])
    with st.expander("Individual producer assumptions", expanded=False):
        _oil27_dataframe(_oil27_style_numeric(details, 1), key="oil28_fiscal_details", height=360)
    _html('<div class="o26-note">Calibration anchor: Brent 88.10 USD/bbl and JKM 20.98 USD/MMBtu. Country balances and breakevens reproduce the audited reference snapshot at that anchor; oil and gas sensitivities then move with net export volumes.</div>')


