# Pandas Styler defers background_gradient execution until Streamlit serializes
# the table. The Codespace intentionally has no matplotlib, so a try/except
# around background_gradient is insufficient. Use a dependency-free cell map.
def _oil27_style_numeric(df: pd.DataFrame, decimals: int = 1, heat: bool = False):
    numeric = list(df.select_dtypes(include=[np.number]).columns)
    styler = df.style.format({column: f"{{:,.{decimals}f}}" for column in numeric}, na_rep="—")
    if heat and numeric:
        def _oil28_heat_cell(value: Any) -> str:
            number = _safe_float(value)
            if number is None:
                return ""
            if number > 0:
                strength = min(0.34, 0.08 + abs(number) / 700.0)
                return f"background-color: rgba(46, 171, 111, {strength:.3f}); color: #dff9eb;"
            if number < 0:
                strength = min(0.34, 0.08 + abs(number) / 700.0)
                return f"background-color: rgba(205, 72, 83, {strength:.3f}); color: #ffe8ea;"
            return "background-color: rgba(139, 153, 169, .06);"
        try:
            styler = styler.map(_oil28_heat_cell, subset=numeric)
        except AttributeError:
            styler = styler.applymap(_oil28_heat_cell, subset=numeric)
    return styler


# Cold-start performance: the V27 fallback queried every futures contract in a
# serial loop. Fetch the complete strip in one yfinance batch and parse it into
# the same normalized contract schema.
@st.cache_data(ttl=1800, show_spinner=False)
def _oil27_yahoo_curve(prefix: str, refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if yf is None:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": "yfinance unavailable"}
    months = _oil27_future_months(12)[:13]
    symbol_rows = [(dt, f"{prefix}{month_code}.NYM") for dt, month_code in months]
    symbols = [symbol for _, symbol in symbol_rows]
    try:
        raw = yf.download(symbols, period="7d", interval="1d", group_by="ticker", progress=False, auto_adjust=False, threads=True)
    except Exception as exc:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance batch", "message": str(exc)[:240]}
    if raw is None or raw.empty:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance batch", "message": "No futures contracts returned"}

    rows: List[Dict[str, Any]] = []
    for dt, symbol in symbol_rows:
        try:
            if isinstance(raw.columns, pd.MultiIndex):
                first_level = set(str(value) for value in raw.columns.get_level_values(0))
                second_level = set(str(value) for value in raw.columns.get_level_values(1))
                if symbol in first_level:
                    block = raw[symbol]
                elif symbol in second_level:
                    block = raw.xs(symbol, axis=1, level=1)
                else:
                    continue
            else:
                block = raw
            close_col = next((column for column in block.columns if str(column).lower() == "close"), None)
            if close_col is None:
                continue
            close = pd.to_numeric(block[close_col], errors="coerce").dropna()
            if close.empty:
                continue
            volume_col = next((column for column in block.columns if str(column).lower() == "volume"), None)
            volume = pd.to_numeric(block[volume_col], errors="coerce").dropna() if volume_col is not None else pd.Series(dtype=float)
            change = (float(close.iloc[-1]) / float(close.iloc[-2]) - 1.0) * 100.0 if len(close) >= 2 and float(close.iloc[-2]) != 0 else np.nan
            updated_at = pd.to_datetime(close.index[-1], errors="coerce")
            rows.append({
                "contract": dt.strftime("%b %Y"),
                "price": float(close.iloc[-1]),
                "change": change,
                "volume": float(volume.iloc[-1]) if not volume.empty else np.nan,
                "open_interest": np.nan,
                "expiration": dt,
                "updated_at": updated_at,
                "expiration_dt": pd.Timestamp(dt).tz_convert(None),
                "symbol": symbol,
            })
        except Exception:
            continue
    return pd.DataFrame(rows), {
        "status": "fallback-live" if rows else "provider-unavailable",
        "source": "Yahoo/yfinance batch contract strip",
        "message": f"{len(rows)} of {len(symbols)} contracts returned in one batch",
    }


# Contextual handling for ambiguous finance words such as "Brent" (which is
# also a first name in US sports reporting).
def _oil27_news_relevant(title: str, description: str) -> bool:
    text = f"{title} {description}".lower()
    expanded_exclusions = OIL27_EXCLUDE_TERMS + (
        "brent venables", "oklahoma sooners", "sec media days", "offensively",
        "nfl coach", "baseball coach", "football coach",
    )
    if any(term in text for term in expanded_exclusions):
        return False
    unambiguous = tuple(term for term in OIL27_STRONG_NEWS_TERMS if term not in {"brent", "wti"})
    if any(term in text for term in unambiguous):
        return True
    if any(term in text for term in ("brent", "wti")) and any(
        context in text for context in ("oil", "crude", "barrel", "futures", "price", "opec", "refinery", "energy market")
    ):
        return True
    weak_hits = sum(term in text for term in OIL27_WEAK_NEWS_TERMS)
    return weak_hits >= 2

