# The DPR production workbook does not contain well completions/DUCs. The
# dedicated EIA duc-data.xlsx workbook does. The previous proximity parser
# selected natural-gas production values in the millions. Read the explicit
# region/metric matrix and validate physical ranges instead.

@st.cache_data(ttl=21600, show_spinner=False)
def _oil27_fetch_dpr_workbook(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if requests is None:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "EIA DUC workbook", "message": "requests unavailable"}
    url = "https://www.eia.gov/petroleum/drilling/xls/duc-data.xlsx"
    basins = ["Anadarko", "Appalachia", "Bakken", "Eagle Ford", "Haynesville", "Niobrara", "Permian"]
    try:
        response = requests.get(url, timeout=(5, 25), headers={"User-Agent": "QuantTerminal-Oil/28"})
        response.raise_for_status()
        raw = pd.read_excel(io.BytesIO(response.content), sheet_name="Data", header=None)
        if raw.shape[0] < 5 or raw.shape[1] < 28:
            raise ValueError("unexpected EIA DUC workbook layout")

        dates = pd.to_datetime(raw.iloc[4:, 0], errors="coerce")
        valid = dates.notna()
        if not valid.any():
            raise ValueError("no dated EIA DUC observations")
        latest_position = int(np.flatnonzero(valid.to_numpy())[-1]) + 4
        latest_date = pd.Timestamp(pd.to_datetime(raw.iat[latest_position, 0]))

        rows: List[Dict[str, Any]] = []
        # Column 0 is the observation date. Each basin then occupies three
        # metric columns plus one spacer: 1/2/3, 5/6/7, ... 25/26/27.
        # Region labels are on row 2 at those same starting columns.
        for start in range(1, 28, 4):
            basin = str(raw.iat[2, start]).strip()
            if basin not in basins:
                continue
            drilled = _safe_float(raw.iat[latest_position, start])
            completed = _safe_float(raw.iat[latest_position, start + 1])
            duc = _safe_float(raw.iat[latest_position, start + 2])
            if any(value is not None and not 0 <= value <= 20000 for value in (drilled, completed, duc)):
                continue
            rows.append({"Basin": basin, "Drilled": drilled, "Completed": completed, "DUC": duc, "Report date": latest_date})

        frame = pd.DataFrame(rows)
        return frame, {
            "status": "public-archive",
            "source": "EIA DUC data workbook",
            "message": f"Official DPR well inventory through {latest_date.strftime('%b %Y')}; ongoing DPR regional forecasts moved to STEO in June 2024",
        }
    except Exception as exc:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "EIA DUC workbook", "message": str(exc)[:220]}


@st.cache_data(ttl=1800, show_spinner=False)
def _oil28_fetch_baker_hughes_summary_v3(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if requests is None:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Baker Hughes", "message": "requests unavailable"}
    url = "https://rigcount.bakerhughes.com/rig-count-overview"
    try:
        # Baker Hughes' edge currently stalls selected custom user-agent
        # strings; the requests default receives the public HTML immediately.
        response = requests.get(url, timeout=(5, 15))
        response.raise_for_status()
        rows: List[Dict[str, Any]] = []
        summary = re.search(r'<table[^>]*summary-table[^>]*>(.*?)</table>', response.text, flags=re.I | re.S)
        if summary:
            for row_html in re.findall(r'<tr[^>]*>(.*?)</tr>', summary.group(1), flags=re.I | re.S):
                raw_cells = re.findall(r'<td[^>]*>(.*?)</td>', row_html, flags=re.I | re.S)
                if len(raw_cells) < 4:
                    continue
                cells = []
                for raw_cell in raw_cells:
                    cleaned = re.sub(r'<[^>]+>', ' ', raw_cell)
                    cleaned = re.sub(r'\s+', ' ', cleaned.replace('&nbsp;', ' ')).strip()
                    cells.append(cleaned)
                low = cells[0].lower().rstrip(" .")
                region = (
                    "United States" if low in {"u.s", "us", "usa", "united states"}
                    else "Canada" if low == "canada"
                    else "International" if low.startswith("international")
                    else None
                )
                value = _safe_float(cells[2])
                if region and value is not None:
                    rows.append({"Region": region, "Rigs": value, "Change": _safe_float(cells[3]), "Date": cells[1]})
        if not rows:
            raise ValueError("Baker Hughes overview table not found")
        return pd.DataFrame(rows), {"status": "public-live", "source": "Baker Hughes Rig Count", "message": "Official public summary"}
    except Exception as exc:
        return pd.DataFrame(), {"status": "provider-unavailable", "source": "Baker Hughes Rig Count", "message": str(exc)[:220]}


def _oil26_render_drilling(refresh_token: int) -> None:
    _oil28_section_intro(
        "Drilling",
        "US Drilling Intelligence",
        "3 rig regions · 7 basins",
        "Official Baker Hughes active-rig counts and EIA drilled, completed and drilled-but-uncompleted well inventory.",
    )
    rig_payload, rig_meta = _oil27_api_call("GET", "/v1/ei/rig_counts/latest", tuple(), tuple(), refresh_token)
    drill_payload, drill_meta = _oil27_api_call("GET", "/v1/drilling-intelligence/summary", tuple(), tuple(), refresh_token)
    live, live_meta = _oil26_load_live(refresh_token)

    _html('<div class="o26-group">Active Rig Counts</div>')
    cards: Dict[str, Tuple[Optional[float], Optional[float], str, str]] = {}
    public_rigs, public_meta = _oil28_fetch_baker_hughes_summary_v3(refresh_token)
    if not public_rigs.empty:
        for _, row in public_rigs.iterrows():
            cards[str(row["Region"])] = (
                _safe_float(row.get("Rigs")), _safe_float(row.get("Change")),
                public_meta.get("source", "Baker Hughes"), str(row.get("Date", "")),
            )

    # Premium/provider records are a fallback only; 402/403 is an entitlement
    # state and must never be interpreted as zero rigs.
    if not cards and isinstance(rig_payload, dict):
        for rec in _oil27_iter_records(rig_payload):
            raw_name = str(rec.get("region") or rec.get("name") or rec.get("country") or "").lower()
            region = (
                "United States" if raw_name in {"us", "u.s.", "usa", "united states"}
                else "Canada" if "canada" in raw_name
                else "International" if "international" in raw_name
                else None
            )
            value = _safe_float(rec.get("rigs", rec.get("count", rec.get("value", rec.get("us_total")))))
            if region and value is not None:
                cards[region] = (value, _safe_float(rec.get("change", rec.get("week_over_week"))), "OilPriceAPI Scale", str(rec.get("date", "")))

    if not cards:
        for region, aliases in (
            ("United States", ["US_RIG_COUNT"]),
            ("Canada", ["CANADA_RIG_COUNT"]),
            ("International", ["INTERNATIONAL_RIG_COUNT"]),
        ):
            row = _oil27_live_row(live, aliases)
            if row is not None:
                cards[region] = (_safe_float(row.get("price")), _safe_float(row.get("change")), "OilPriceAPI all-prices", str(row.get("date", "")))

    if cards:
        html_cards: List[str] = []
        for region in ("United States", "Canada", "International"):
            if region not in cards:
                continue
            value, change, source, date_text = cards[region]
            klass = "o26-up" if change is not None and change > 0 else "o26-down" if change is not None and change < 0 else "o26-flat"
            html_cards.append(
                '<div class="o26-kpi">'
                f'<div class="o26-label">{_escape(region)}</div>'
                f'<div class="o26-value">{_oil27_num(value, 0)}</div>'
                f'<div class="o26-delta {klass}">{_oil27_num(change, 0, True)} prior · rigs</div>'
                f'<div class="o27-small">{_escape(source)} · {_escape(date_text)}</div>'
                '</div>'
            )
        _html('<div class="o26-grid">' + ''.join(html_cards) + '</div>')
    else:
        message = public_meta.get("message") or rig_meta.get("message") or live_meta.get("message", "")
        _html(f'<div class="o26-status"><strong>Rig counts unavailable.</strong><br>{_escape(message)}. Premium entitlement errors are not converted to zero.</div>')

    _html('<div class="o26-group">Basin Well Activity</div>')
    rows: List[Dict[str, Any]] = []
    if isinstance(drill_payload, dict):
        for rec in _oil27_iter_records(drill_payload):
            basin = rec.get("basin") or rec.get("region") or rec.get("name")
            drilled = _safe_float(rec.get("drilled", rec.get("wells_drilled")))
            completed = _safe_float(rec.get("completed", rec.get("wells_completed")))
            duc = _safe_float(rec.get("duc", rec.get("drilled_uncompleted", rec.get("duc_wells"))))
            if basin and any(v is not None for v in (drilled, completed, duc)):
                rows.append({"Basin": str(basin).title(), "Drilled": drilled, "Completed": completed, "DUC": duc})
    basin_df = pd.DataFrame(rows).drop_duplicates("Basin") if rows else pd.DataFrame()
    basin_meta = drill_meta
    if basin_df.empty:
        basin_df, basin_meta = _oil27_fetch_dpr_workbook(refresh_token)

    if not basin_df.empty:
        cards_html: List[str] = []
        for _, row in basin_df.iterrows():
            cards_html.append(
                '<div class="o26-kpi">'
                f'<div class="o27-region-title">{_escape(row.get("Basin", ""))}</div>'
                f'<div class="o27-small">DRILLED</div><div class="o26-value" style="font-size:17px">{_oil27_num(row.get("Drilled"), 0)}</div>'
                f'<div class="o27-small">COMPLETED · {_oil27_num(row.get("Completed"), 0)} &nbsp; DUC · {_oil27_num(row.get("DUC"), 0)}</div>'
                '</div>'
            )
        _html('<div class="o26-grid">' + ''.join(cards_html) + '</div>')
        _html(f'<div class="o26-note">Source: {_escape(basin_meta.get("source", "OilPriceAPI / EIA"))} · {_escape(basin_meta.get("message", ""))}</div>')
    else:
        _html(f'<div class="o26-status"><strong>Basin well activity unavailable.</strong><br>{_escape(basin_meta.get("message", ""))}. Missing values are never replaced by zero.</div>')


_oil28_full_fuel_prices_unfiltered = _oil27_full_fuel_prices


def _oil27_region(row: Mapping[str, Any]) -> str:
    text = " ".join(str(row.get(c, "")) for c in ("code", "name", "source", "category", "description", "region", "country")).upper()
    if any(x in text for x in ("BUNKER", "VLSFO", "HFO", "MGO", "MARINE")):
        return "Maritime Bunkers"
    if any(x in text for x in ("SINGAPORE", "SGSIN", "MOGAS", "MOPS", "JKM")):
        return "Singapore"
    if any(x in text for x in ("ROTTERDAM", "NLRTM", "NWE", "DUTCH TTF", "EUROPE")):
        return "Europe"
    if any(x in text for x in ("CANADA", "NRCAN", "BRITISH COLUMBIA", "ONTARIO", "QUEBEC")):
        return "Canada"
    if any(x in text for x in (
        "DIESEL_RETAIL_US", "GASOLINE_RETAIL_US", "AAA", "PADD", "CALIFORNIA", "TEXAS",
        "UNITED STATES", "RBOB", "ULSD", "HEATING OIL", "HENRY HUB", "JET FUEL",
    )):
        return "United States"
    return str(row.get("region") or row.get("country") or "Global / Other")


@st.cache_data(ttl=900, show_spinner=False)
def _oil27_full_fuel_prices(refresh_token: int = 0) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    work, meta = _oil28_full_fuel_prices_unfiltered(refresh_token)
    if work.empty:
        return work, meta
    text = work.apply(
        lambda row: " ".join(str(row.get(c, "")) for c in ("code", "name", "category", "description", "source")).upper(),
        axis=1,
    )
    fuel_terms = (
        "GASOLINE", "DIESEL", "GASOIL", "MOGAS", "JET FUEL", "JET A", "KEROSENE",
        "HEATING OIL", "ULSD", "RBOB", "VLSFO", "HSFO", "HFO", "MGO", "BUNKER",
        "MARINE GAS", "HENRY HUB", "DUTCH TTF", "JKM LNG", "NATURAL GAS", "LNG",
    )
    exclusion_terms = (
        "RIG COUNT", "CRUDE", "BRENT", "WTI", "OPEC", "URALS", "DUBAI CRUDE",
        "OMAN CRUDE", "AZERI", "BASRAH", "WCS CRUDE", "GOLD", "SILVER", "PLATINUM",
        "PALLADIUM", "IRON ORE", "COKING COAL", "NEWCASTLE COAL", "EU CARBON",
    )
    keep = text.map(lambda value: any(term in value for term in fuel_terms) and not any(term in value for term in exclusion_terms))
    filtered = work.loc[keep].copy()
    if filtered.empty:
        meta = dict(meta)
        meta["message"] = ((meta.get("message") or "") + " | no served records matched the fuel taxonomy").strip(" |")
        return filtered, meta
    filtered["Region"] = filtered.apply(_oil27_region, axis=1)
    filtered = filtered.drop_duplicates("code", keep="last") if "code" in filtered.columns else filtered.drop_duplicates()
    meta = dict(meta)
    meta["message"] = ((meta.get("message") or "") + f" | {len(filtered)} fuel/LNG instruments after taxonomy filter").strip(" |")
    return filtered, meta


