def _autos_num(value: Any, decimals: int = 2, signed: bool = False, suffix: str = "") -> str:
    number = _safe_float(value)
    if number is None or not np.isfinite(number):
        return "—"
    prefix = "+" if signed and number > 0 else ""
    return f"{prefix}{number:,.{decimals}f}{suffix}"


def _autos_kpis(items: Sequence[Tuple[str, Any, str, Optional[float]]]) -> None:
    cards: List[str] = []
    for label, value, note, signal in items:
        klass = "a1-up" if signal is not None and signal > 0 else "a1-down" if signal is not None and signal < 0 else ""
        cards.append(
            '<div class="a1-kpi">'
            f'<div class="a1-label">{_escape(label)}</div>'
            f'<div class="a1-value {klass}">{_escape(value)}</div>'
            f'<div class="a1-delta">{_escape(note)}</div>'
            '</div>'
        )
    _html('<div class="a1-grid">' + ''.join(cards) + '</div>')


def _autos_window(frame: pd.DataFrame, window: str) -> pd.DataFrame:
    if frame is None or frame.empty:
        return pd.DataFrame()
    work = frame.copy()
    work.index = pd.to_datetime(work.index, errors="coerce")
    work = work.loc[work.index.notna()].sort_index()
    days = {"1Y": 365, "3Y": 1095, "5Y": 1825, "10Y": 3650}.get(window)
    if days and not work.empty:
        work = work.loc[work.index >= work.index.max() - pd.Timedelta(days=days)]
    return work


@st.cache_data(ttl=900, show_spinner=False)
def _autos_market_pack(refresh_token: int = 0) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    del refresh_token
    if yf is None:
        return pd.DataFrame(), pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": "yfinance unavailable"}
    symbols = list(AUTOS_MARKET_TICKERS)
    try:
        raw = yf.download(symbols, period="10y", interval="1d", group_by="ticker", progress=False, auto_adjust=True, threads=True)
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame(), {"status": "provider-unavailable", "source": "Yahoo/yfinance", "message": str(exc)[:240]}
    closes: Dict[str, pd.Series] = {}
    for symbol in symbols:
        try:
            if isinstance(raw.columns, pd.MultiIndex):
                first = set(str(x) for x in raw.columns.get_level_values(0))
                second = set(str(x) for x in raw.columns.get_level_values(1))
                block = raw[symbol] if symbol in first else raw.xs(symbol, axis=1, level=1) if symbol in second else pd.DataFrame()
            else:
                block = raw
            close_col = next((c for c in block.columns if str(c).lower() == "close"), None)
            if close_col is None:
                continue
            series = pd.to_numeric(block[close_col], errors="coerce").dropna()
            if not series.empty:
                series.index = pd.to_datetime(series.index, errors="coerce")
                closes[symbol] = series.loc[series.index.notna()]
        except Exception:
            continue
    close_frame = pd.DataFrame(closes).sort_index() if closes else pd.DataFrame()
    rows: List[Dict[str, Any]] = []
    for symbol in symbols:
        series = close_frame.get(symbol, pd.Series(dtype=float)).dropna() if not close_frame.empty else pd.Series(dtype=float)
        if series.empty:
            rows.append({"Ticker": symbol, "Name": AUTOS_NAMES.get(symbol, symbol), "Status": "missing"})
            continue
        returns = series.pct_change(fill_method=None).dropna()
        last = float(series.iloc[-1])
        def period_return(periods: int) -> float:
            return (last / float(series.iloc[-periods - 1]) - 1.0) * 100.0 if len(series) > periods and float(series.iloc[-periods - 1]) != 0 else np.nan
        ytd = series.loc[series.index.year == series.index.max().year]
        rows.append({
            "Ticker": symbol, "Name": AUTOS_NAMES.get(symbol, symbol), "Last": last,
            "1D %": period_return(1), "1W %": period_return(5), "1M %": period_return(21),
            "3M %": period_return(63), "1Y %": period_return(252),
            "YTD %": (last / float(ytd.iloc[0]) - 1.0) * 100.0 if len(ytd) else np.nan,
            "30D Vol %": float(returns.tail(30).std() * np.sqrt(252) * 100.0) if len(returns) >= 10 else np.nan,
            "Drawdown %": (last / float(series.tail(252).max()) - 1.0) * 100.0 if len(series) else np.nan,
            "Updated": pd.Timestamp(series.index[-1]), "Status": "live",
        })
    metrics = pd.DataFrame(rows)
    return close_frame, metrics, {"status": "live" if closes else "provider-unavailable", "source": "Yahoo/yfinance batch", "message": f"{len(closes)}/{len(symbols)} instruments loaded"}


@st.cache_data(ttl=21600, show_spinner=False)
def _autos_fred_series(series_id: str, refresh_token: int = 0) -> Tuple[pd.DataFrame, str]:
    del refresh_token
    if requests is None:
        return pd.DataFrame(), "requests unavailable"
    try:
        url = "https://fred.stlouisfed.org/graph/fredgraph.csv"
        request_kwargs = {
            "params": {"id": series_id},
            "timeout": (5, 25),
            "headers": {"User-Agent": "QuantTerminal-MarketDesk/1.0"},
        }
        try:
            response = requests.get(url, **request_kwargs)
        except requests.exceptions.SSLError:
            # Some hosted workspaces insert a local TLS proxy whose root
            # certificate is not available to Python. FRED is public,
            # read-only data, so retry only this narrowly identified failure.
            response = requests.get(url, verify=False, **request_kwargs)
        response.raise_for_status()
        raw = pd.read_csv(io.StringIO(response.text))
        if raw.shape[1] < 2:
            raise ValueError("unexpected FRED response")
        frame = pd.DataFrame({"date": pd.to_datetime(raw.iloc[:, 0], errors="coerce"), "value": pd.to_numeric(raw.iloc[:, 1], errors="coerce")}).dropna()
        return frame.sort_values("date"), ""
    except Exception as exc:
        return pd.DataFrame(), str(exc)[:180]


@st.cache_data(ttl=21600, show_spinner=False)
def _autos_fred_pack(refresh_token: int = 0) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame]:
    # Reuse Liquidity V3's proven FRED connector when available. It selects
    # the configured FRED API, keeps a disk cache and opens a circuit after a
    # failed probe instead of making every Autos panel wait on the provider.
    if "_liq3_load_fred_pack" in globals():
        try:
            pack, upstream, _provider = _liq3_load_fred_pack(tuple(AUTOS_FRED), "1990-01-01", refresh_token)
            upstream_rows: Dict[str, Mapping[str, Any]] = {}
            if isinstance(upstream, pd.DataFrame) and not upstream.empty and "Series / Instrument" in upstream.columns:
                upstream_rows = {
                    str(row["Series / Instrument"]): row
                    for _, row in upstream.iterrows()
                }
            now = pd.Timestamp.utcnow().tz_localize(None)
            quality: List[Dict[str, Any]] = []
            for sid, meta in AUTOS_FRED.items():
                frame = pack.get(sid, pd.DataFrame())
                latest = pd.Timestamp(frame["date"].max()).tz_localize(None) if not frame.empty else pd.NaT
                age = (now - latest).days if pd.notna(latest) else np.nan
                status = "live" if pd.notna(age) and age <= meta["expected_days"] else "stale" if pd.notna(age) else "unavailable"
                upstream_row = upstream_rows.get(sid, {})
                quality.append({
                    "Series": sid, "Label": meta["label"], "Family": meta["family"],
                    "Frequency": meta["frequency"], "Unit": meta["unit"], "Latest": latest,
                    "Age days": age, "Rows": len(frame), "Status": status,
                    "Source": upstream_row.get("Source", "FRED"),
                    "Message": upstream_row.get("Message", ""),
                })
            return pack, pd.DataFrame(quality)
        except Exception:
            pass

    pack: Dict[str, pd.DataFrame] = {}
    errors: Dict[str, str] = {}
    with _autos_ThreadPoolExecutor(max_workers=6) as pool:
        futures = {pool.submit(_autos_fred_series, sid, refresh_token): sid for sid in AUTOS_FRED}
        for future in _autos_as_completed(futures):
            sid = futures[future]
            try:
                frame, error = future.result()
            except Exception as exc:
                frame, error = pd.DataFrame(), str(exc)[:180]
            pack[sid] = frame
            errors[sid] = error
    now = pd.Timestamp.utcnow().tz_localize(None)
    quality: List[Dict[str, Any]] = []
    for sid, meta in AUTOS_FRED.items():
        frame = pack.get(sid, pd.DataFrame())
        latest = pd.Timestamp(frame["date"].max()).tz_localize(None) if not frame.empty else pd.NaT
        age = (now - latest).days if pd.notna(latest) else np.nan
        status = "live" if pd.notna(age) and age <= meta["expected_days"] else "stale" if pd.notna(age) else "unavailable"
        quality.append({"Series": sid, "Label": meta["label"], "Family": meta["family"], "Frequency": meta["frequency"], "Unit": meta["unit"], "Latest": latest, "Age days": age, "Rows": len(frame), "Status": status, "Message": errors.get(sid, "")})
    return pack, pd.DataFrame(quality)


def _autos_group_series(closes: pd.DataFrame, tickers: Sequence[str], window: str = "Max") -> pd.Series:
    if closes.empty:
        return pd.Series(dtype=float)
    work = _autos_window(closes[[t for t in tickers if t in closes.columns]].dropna(how="all"), window)
    normalized: List[pd.Series] = []
    for column in work.columns:
        series = work[column].dropna()
        if len(series) >= 2 and float(series.iloc[0]) != 0:
            normalized.append(series / float(series.iloc[0]) * 100.0)
    return pd.concat(normalized, axis=1).mean(axis=1).dropna() if normalized else pd.Series(dtype=float)


def _autos_group_metrics(closes: pd.DataFrame) -> pd.DataFrame:
    rows: List[Dict[str, Any]] = []
    for group, tickers in AUTOS_GROUPS.items():
        series = _autos_group_series(closes, tickers)
        if series.empty:
            continue
        ret = series.pct_change(fill_method=None).dropna()
        def change(periods: int) -> float:
            return (float(series.iloc[-1]) / float(series.iloc[-periods - 1]) - 1.0) * 100.0 if len(series) > periods else np.nan
        rows.append({"Group": group, "1D %": change(1), "1M %": change(21), "3M %": change(63), "1Y %": change(252), "30D Vol %": float(ret.tail(30).std() * np.sqrt(252) * 100.0) if len(ret) >= 10 else np.nan})
    return pd.DataFrame(rows)


def _autos_chart(series_map: Mapping[str, pd.Series], title: str, subtitle: str, ytitle: str, key: str, indexed: bool = False, height: int = 390) -> None:
    _html(f'<div class="a1-card-head"><div class="a1-card-title">{_escape(title)}</div><div class="a1-card-sub">{_escape(subtitle)}</div></div>')
    fig = go.Figure()
    latest_parts: List[str] = []
    for idx, (label, raw_series) in enumerate(series_map.items()):
        series = pd.to_numeric(raw_series, errors="coerce").dropna() if isinstance(raw_series, pd.Series) else pd.Series(dtype=float)
        if series.empty:
            continue
        if indexed and float(series.iloc[0]) != 0:
            series = series / float(series.iloc[0]) * 100.0
        color = AUTOS_COLORS[idx % len(AUTOS_COLORS)]
        fig.add_trace(go.Scatter(x=series.index, y=series.values, name=label, mode="lines", line=dict(width=2.1, color=color)))
        latest_parts.append(f"{label} {_autos_num(series.iloc[-1], 2)}")
    if not fig.data:
        _html('<div class="a1-warn">Data unavailable for this panel. Missing observations are not replaced by synthetic values.</div>')
        return
    fig.update_layout(
        height=height, margin=dict(l=42, r=26, t=22, b=50), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(7,19,31,.78)",
        font=dict(color="#cfd7df", size=10), hovermode="x unified", legend=dict(orientation="h", y=-.22),
        xaxis=dict(gridcolor="rgba(139,165,190,.11)", rangeselector=dict(buttons=[
            dict(count=1, label="1Y", step="year", stepmode="backward"), dict(count=3, label="3Y", step="year", stepmode="backward"),
            dict(count=5, label="5Y", step="year", stepmode="backward"), dict(step="all", label="Max")
        ])), yaxis=dict(title=ytitle, gridcolor="rgba(139,165,190,.13)"),
    )
    st.plotly_chart(fig, use_container_width=True, config={"displaylogo": False, "responsive": True}, key=key)
    _html(f'<div class="a1-source">Latest: {_escape(" · ".join(latest_parts))}</div>')


def _autos_fred_series_value(pack: Mapping[str, pd.DataFrame], sid: str) -> pd.Series:
    frame = pack.get(sid, pd.DataFrame())
    if frame.empty:
        return pd.Series(dtype=float)
    series = pd.Series(pd.to_numeric(frame["value"], errors="coerce").values, index=pd.to_datetime(frame["date"], errors="coerce"))
    return series.loc[series.index.notna()].dropna().sort_index()


def _autos_table(frame: pd.DataFrame, key: str, height: int = 420) -> None:
    if frame is None or frame.empty:
        _html('<div class="a1-warn">Table unavailable for the active provider response.</div>')
        return
    st.dataframe(frame, use_container_width=True, hide_index=True, height=height, key=key)


def _autos_render_overview(closes: pd.DataFrame, metrics: pd.DataFrame, window: str) -> None:
    group_metrics = _autos_group_metrics(closes)
    auto_series = _autos_group_series(closes, ("CARZ", "DRIV", "IDRV", "KARS"), window)
    ev_series = _autos_group_series(closes, ("TSLA", "RIVN", "LCID", "NIO", "XPEV", "LI"), window)
    legacy_series = _autos_group_series(closes, ("F", "GM", "STLA", "TM", "HMC", "VWAGY", "BMWYY"), window)
    supplier_series = _autos_group_series(closes, AUTOS_GROUPS["Suppliers"], window)
    commercial_series = _autos_group_series(closes, AUTOS_GROUPS["Commercial & Diesel"], window)
    spy_series = _autos_group_series(closes, ("SPY",), window)
    breadth = float((pd.to_numeric(metrics.get("1M %"), errors="coerce") > 0).mean() * 100.0) if not metrics.empty else np.nan
    dispersion = float(pd.to_numeric(metrics.get("1M %"), errors="coerce").std()) if not metrics.empty else np.nan
    ev_rel = (float(ev_series.iloc[-1]) / float(legacy_series.iloc[-1]) - 1.0) * 100.0 if not ev_series.empty and not legacy_series.empty and float(legacy_series.iloc[-1]) != 0 else np.nan
    auto_dd = (float(auto_series.iloc[-1]) / float(auto_series.max()) - 1.0) * 100.0 if not auto_series.empty else np.nan
    _autos_kpis([
        ("1M Breadth", _autos_num(breadth, 0, False, "%"), "Share of loaded auto instruments above their 1M starting level", breadth - 50 if np.isfinite(breadth) else None),
        ("1M Dispersion", _autos_num(dispersion, 1, False, " pp"), "Cross-sectional return dispersion", -dispersion if np.isfinite(dispersion) else None),
        ("EV vs Legacy", _autos_num(ev_rel, 1, True, "%"), "Indexed-window relative performance", ev_rel),
        ("Auto Drawdown", _autos_num(auto_dd, 1, True, "%"), "Sector basket versus window high", auto_dd),
        ("Loaded Universe", f"{int((metrics['Status'] == 'live').sum())}/{len(metrics)}" if not metrics.empty else "0/0", "OEMs, suppliers, batteries, commercial and macro proxies", None),
    ])
    _autos_chart({"Auto ETFs": auto_series, "EV Pure-Play": ev_series, "Legacy OEMs": legacy_series, "Suppliers": supplier_series, "Commercial/Diesel": commercial_series, "S&P 500": spy_series}, "Cross-Sector Performance", "Equal-weighted investable groups; each series indexed to 100 at the selected window start.", "Index", "autos1_overview_groups", indexed=False)
    _html('<div class="a1-group">Sector Pulse</div>')
    _autos_table(group_metrics.round(2), "autos1_group_metrics", min(410, 44 + len(group_metrics) * 35))
    _html('<div class="a1-group">OEM & Supply-Chain Market Board</div>')
    columns = [c for c in ("Ticker", "Name", "Last", "1D %", "1W %", "1M %", "3M %", "YTD %", "1Y %", "30D Vol %", "Drawdown %", "Status") if c in metrics.columns]
    _autos_table(metrics[columns].round(2), "autos1_market_board", 570)


