def _autos_render_production(pack: Mapping[str, pd.DataFrame], quality: pd.DataFrame, window: str) -> None:
    total = _autos_fred_series_value(pack, "TOTALSA")
    light = _autos_fred_series_value(pack, "ALTSALES")
    domestic = _autos_fred_series_value(pack, "DAUTOSA")
    production = _autos_fred_series_value(pack, "IPG3361T3S")
    new_cpi = _autos_fred_series_value(pack, "CUSR0000SETA01")
    used_cpi = _autos_fred_series_value(pack, "CUSR0000SETA02")
    loan_rate = _autos_fred_series_value(pack, "TERMCBAUTO48NS")
    delinquency = _autos_fred_series_value(pack, "DRCLACBS")
    loans = _autos_fred_series_value(pack, "MVLOAS")
    domestic_annualized = domestic * 12.0 / 1000.0 if not domestic.empty else pd.Series(dtype=float)
    _autos_kpis([
        ("Total Vehicle Sales", _autos_num(total.iloc[-1] if not total.empty else None, 1, False, "m"), "US SAAR · latest", None),
        ("Light Vehicle Sales", _autos_num(light.iloc[-1] if not light.empty else None, 1, False, "m"), "US SAAR · latest", None),
        ("Production Index", _autos_num(production.iloc[-1] if not production.empty else None, 1), "Motor vehicles & parts", None),
        ("New Vehicle CPI", _autos_num(new_cpi.iloc[-1] if not new_cpi.empty else None, 1), "Affordability pressure", None),
        ("Auto Loan Rate", _autos_num(loan_rate.iloc[-1] if not loan_rate.empty else None, 2, False, "%"), "48-month commercial-bank rate", None),
        ("Loan Delinquency", _autos_num(delinquency.iloc[-1] if not delinquency.empty else None, 2, False, "%"), "Consumer loan proxy", -float(delinquency.iloc[-1]) if not delinquency.empty else None),
    ])
    c1, c2 = st.columns(2, gap="large")
    with c1:
        _autos_chart({"Total Vehicles": _autos_window(total.to_frame("x"), window)["x"] if not total.empty else pd.Series(dtype=float), "Light Vehicles": _autos_window(light.to_frame("x"), window)["x"] if not light.empty else pd.Series(dtype=float), "Domestic Autos (annualized)": _autos_window(domestic_annualized.to_frame("x"), window)["x"] if not domestic_annualized.empty else pd.Series(dtype=float)}, "US Vehicle Demand", "Total and light vehicles are official SAAR series; domestic monthly SA retail sales are annualized and converted from thousands to millions for comparability.", "Million units annualized", "autos1_prod_sales")
    with c2:
        _autos_chart({"Motor Vehicles & Parts": _autos_window(production.to_frame("x"), window)["x"] if not production.empty else pd.Series(dtype=float)}, "US Automotive Production", "Federal Reserve industrial-production index for motor vehicles and parts.", "Index", "autos1_prod_output")
    c3, c4 = st.columns(2, gap="large")
    with c3:
        _autos_chart({"New Vehicles": _autos_window(new_cpi.to_frame("x"), window)["x"] if not new_cpi.empty else pd.Series(dtype=float), "Used Cars & Trucks": _autos_window(used_cpi.to_frame("x"), window)["x"] if not used_cpi.empty else pd.Series(dtype=float)}, "Vehicle Pricing", "Consumer price indices capture affordability and residual-value cycles.", "CPI index", "autos1_prod_cpi")
    with c4:
        _autos_chart({"48M Auto Loan Rate": _autos_window(loan_rate.to_frame("x"), window)["x"] if not loan_rate.empty else pd.Series(dtype=float), "Consumer Loan Delinquency": _autos_window(delinquency.to_frame("x"), window)["x"] if not delinquency.empty else pd.Series(dtype=float)}, "Auto Finance Conditions", "Financing cost and consumer-credit stress proxies.", "%", "autos1_prod_finance")
    _autos_chart({"Motor Vehicle Loans": _autos_window(loans.to_frame("x"), window)["x"] if not loans.empty else pd.Series(dtype=float)}, "Motor Vehicle Credit Outstanding", "Credit stock supporting US vehicle demand.", "USD bn", "autos1_prod_loans")
    _html('<div class="a1-group">Production & Demand Source Status</div>')
    _autos_table(quality.loc[quality["Family"].isin(["Demand", "Production", "Pricing", "Finance"])], "autos1_prod_quality", 390)


def _autos_render_powertrain(pack: Mapping[str, pd.DataFrame], window: str) -> None:
    gasoline = _autos_fred_series_value(pack, "GASREGW")
    diesel = _autos_fred_series_value(pack, "GASDESW")
    electricity = _autos_fred_series_value(pack, "APU000072610")
    gas_price = _safe_float(gasoline.iloc[-1]) if not gasoline.empty else None
    diesel_price = _safe_float(diesel.iloc[-1]) if not diesel.empty else None
    electricity_usd = _safe_float(electricity.iloc[-1]) if not electricity.empty else None
    electricity_cents = electricity_usd * 100.0 if electricity_usd is not None else None
    c1, c2, c3 = st.columns(3)
    with c1:
        gas_mpg = st.slider("Gasoline vehicle MPG", 15, 60, 30, 1, key="autos1_gas_mpg")
    with c2:
        diesel_mpg = st.slider("Diesel vehicle MPG", 15, 70, 36, 1, key="autos1_diesel_mpg")
    with c3:
        ev_kwh = st.slider("EV consumption kWh / 100 mi", 18, 55, 30, 1, key="autos1_ev_kwh")
    gas_cost = gas_price / gas_mpg * 100.0 if gas_price is not None else None
    diesel_cost = diesel_price / diesel_mpg * 100.0 if diesel_price is not None else None
    ev_cost = electricity_usd * ev_kwh if electricity_usd is not None else None
    ev_breakeven = gas_cost / ev_kwh * 100.0 if gas_cost is not None and ev_kwh else None
    _autos_kpis([
        ("Gasoline", _autos_num(gas_price, 2, False, "/gal"), f"{gas_mpg} mpg assumption", None),
        ("Diesel", _autos_num(diesel_price, 2, False, "/gal"), f"{diesel_mpg} mpg assumption", None),
        ("Electricity", _autos_num(electricity_cents, 1, False, "¢/kWh"), f"{ev_kwh} kWh/100mi assumption", None),
        ("Gas Cost / 100mi", _autos_num(gas_cost, 2, False, " USD"), "Energy cost only", -gas_cost if gas_cost is not None else None),
        ("Diesel Cost / 100mi", _autos_num(diesel_cost, 2, False, " USD"), "Energy cost only", -diesel_cost if diesel_cost is not None else None),
        ("EV Cost / 100mi", _autos_num(ev_cost, 2, False, " USD"), "Energy cost only", -ev_cost if ev_cost is not None else None),
        ("EV Electricity Breakeven", _autos_num(ev_breakeven, 1, False, "¢/kWh"), "Versus gasoline energy cost", None),
    ])
    cost_table = pd.DataFrame([
        {"Powertrain": "Gasoline ICE", "Reference price": gas_price, "Reference unit": "USD/gal", "Efficiency": f"{gas_mpg} mpg", "Energy cost / 100mi": gas_cost, "Cost / mile": gas_cost / 100 if gas_cost is not None else np.nan},
        {"Powertrain": "Diesel ICE", "Reference price": diesel_price, "Reference unit": "USD/gal", "Efficiency": f"{diesel_mpg} mpg", "Energy cost / 100mi": diesel_cost, "Cost / mile": diesel_cost / 100 if diesel_cost is not None else np.nan},
        {"Powertrain": "Battery EV", "Reference price": electricity_cents, "Reference unit": "cents/kWh", "Efficiency": f"{ev_kwh} kWh/100mi", "Energy cost / 100mi": ev_cost, "Cost / mile": ev_cost / 100 if ev_cost is not None else np.nan},
    ])
    _autos_table(cost_table.round(3), "autos1_powertrain_costs", 180)
    gas_w = _autos_window((gasoline / gas_mpg * 100.0).to_frame("x"), window)["x"] if not gasoline.empty else pd.Series(dtype=float)
    diesel_w = _autos_window((diesel / diesel_mpg * 100.0).to_frame("x"), window)["x"] if not diesel.empty else pd.Series(dtype=float)
    elec_w = _autos_window((electricity * ev_kwh).to_frame("x"), window)["x"] if not electricity.empty else pd.Series(dtype=float)
    c4, c5 = st.columns(2, gap="large")
    with c4:
        _autos_chart({"Gasoline ICE": gas_w, "Diesel ICE": diesel_w, "Battery EV": elec_w}, "Energy Cost per 100 Miles", "Common-distance comparison using the efficiency assumptions above.", "USD / 100 miles", "autos1_powertrain_levels")
    with c5:
        _autos_chart({"Gasoline ICE": gas_w, "Diesel ICE": diesel_w, "Battery EV": elec_w}, "Powertrain Energy-Cost Inflation", "Comparable cost per 100 miles rebased to 100.", "Indexed 100", "autos1_powertrain_index", indexed=True)
    if gas_price is not None and electricity_cents is not None:
        electric_scenarios = [10, 15, 20, 25, 30, 40, 50]
        scenario = pd.DataFrame({"Electricity cents/kWh": electric_scenarios})
        scenario["EV cost / 100mi"] = scenario["Electricity cents/kWh"] / 100.0 * ev_kwh
        scenario["Savings vs gasoline / 100mi"] = gas_cost - scenario["EV cost / 100mi"]
        scenario["Savings vs diesel / 100mi"] = diesel_cost - scenario["EV cost / 100mi"] if diesel_cost is not None else np.nan
        _html('<div class="a1-group">Electricity Sensitivity</div>')
        _autos_table(scenario.round(2), "autos1_powertrain_sensitivity", 300)
    _html('<div class="a1-note">Energy-cost comparison only. Purchase price, depreciation, insurance, charging losses, maintenance and taxes are deliberately excluded rather than silently assumed.</div>')


def _autos_render_trade(closes: pd.DataFrame, metrics: pd.DataFrame, window: str) -> None:
    tariff = st.slider("Tariff / localisation shock", 0, 30, 10, 1, key="autos1_tariff")
    energy = st.slider("Energy & freight shock", 0, 50, 15, 1, key="autos1_energy_shock")
    battery = st.slider("Battery-material shock", 0, 50, 15, 1, key="autos1_battery_shock")
    rates = st.slider("Consumer-rate shock (bp)", 0, 250, 75, 25, key="autos1_rate_shock")
    exposure = pd.DataFrame([
        {"Sector": "US OEMs", "Tariff": .75, "Energy/Freight": .55, "Battery": .45, "Rates": .75},
        {"Sector": "European OEMs", "Tariff": .90, "Energy/Freight": .65, "Battery": .50, "Rates": .70},
        {"Sector": "Asian OEMs", "Tariff": 1.00, "Energy/Freight": .70, "Battery": .55, "Rates": .55},
        {"Sector": "EV Pure-Play", "Tariff": .65, "Energy/Freight": .35, "Battery": 1.00, "Rates": 1.00},
        {"Sector": "Suppliers", "Tariff": 1.00, "Energy/Freight": .80, "Battery": .45, "Rates": .60},
        {"Sector": "Commercial & Diesel", "Tariff": .55, "Energy/Freight": 1.00, "Battery": .20, "Rates": .70},
    ])
    exposure["Scenario Stress / 100"] = (
        exposure["Tariff"] * tariff / 30 * 30 + exposure["Energy/Freight"] * energy / 50 * 25 +
        exposure["Battery"] * battery / 50 * 25 + exposure["Rates"] * rates / 250 * 20
    ).clip(0, 100)
    exposure["Risk State"] = pd.cut(exposure["Scenario Stress / 100"], [-1, 25, 50, 75, 101], labels=["LOW", "MEDIUM", "HIGH", "EXTREME"])
    _autos_kpis([
        ("Tariff Shock", f"{tariff}%", "Cross-border content / localisation scenario", -tariff),
        ("Energy & Freight", f"{energy}%", "Oil, diesel, power and logistics scenario", -energy),
        ("Battery Materials", f"{battery}%", "Lithium, copper and rare-earth scenario", -battery),
        ("Consumer Rates", f"+{rates} bp", "Financing-affordability scenario", -rates),
    ])
    _autos_table(exposure.round(2), "autos1_trade_stress", 310)
    _html('<div class="a1-note">Scenario Stress is a transparent internal risk score, not a forecast of equity returns or margins. Factor weights are analytical assumptions shown in the table.</div>')
    supply_tickers = ("SOXX", "REMX", "LIT", "HG=F", "PA=F", "PL=F", "SLX", "BDRY", "CL=F", "HO=F")
    supply_series = {AUTOS_NAMES.get(t, t): _autos_window(closes[[t]], window)[t] for t in supply_tickers if t in closes.columns}
    _autos_chart(supply_series, "Automotive Supply-Chain Proxies", "Semiconductors, rare earths, batteries, copper, catalysts, steel, freight and energy.", "Indexed 100", "autos1_trade_proxies", indexed=True)
    group_metrics = _autos_group_metrics(closes)
    _html('<div class="a1-group">Regional & Business-Model Performance</div>')
    _autos_table(group_metrics.round(2), "autos1_trade_groups", min(410, 44 + len(group_metrics) * 35))
    supplier_set = set(AUTOS_GROUPS["Suppliers"] + AUTOS_GROUPS["Commercial & Diesel"] + AUTOS_GROUPS["European OEMs"] + AUTOS_GROUPS["Asian OEMs"])
    supplier_table = metrics.loc[metrics["Ticker"].isin(supplier_set)].copy() if not metrics.empty else pd.DataFrame()
    _autos_table(supplier_table[[c for c in ("Ticker", "Name", "Last", "1D %", "1M %", "3M %", "1Y %", "30D Vol %", "Drawdown %", "Status") if c in supplier_table.columns]].round(2), "autos1_trade_board", 520)


def _autos_render_quality(metrics: pd.DataFrame, market_meta: Mapping[str, Any], quality: pd.DataFrame) -> None:
    loaded_market = int((metrics.get("Status") == "live").sum()) if not metrics.empty else 0
    fred_live = int((quality.get("Status") == "live").sum()) if not quality.empty else 0
    fred_stale = int((quality.get("Status") == "stale").sum()) if not quality.empty else 0
    _autos_kpis([
        ("Market Instruments", f"{loaded_market}/{len(metrics)}", market_meta.get("source", "Yahoo/yfinance"), None),
        ("FRED Live", f"{fred_live}/{len(quality)}", "Within series-specific freshness tolerance", None),
        ("FRED Stale", str(fred_stale), "Visible and explicitly labelled", -fred_stale),
        ("IEA Snapshot", "2025", "Global EV Outlook 2026 · updated May 2026", None),
        ("Synthetic History", "NONE", "Missing data remains missing", 1),
    ])
    if fred_live == 0 and not quality.empty and "Message" in quality.columns:
        messages = quality["Message"].dropna().astype(str)
        messages = messages.loc[messages.str.len() > 0]
        if not messages.empty:
            _html(f'<div class="a1-warn">FRED connection status · {_escape(messages.iloc[0][:320])}</div>')
    _html('<div class="a1-group">Market Data Registry</div>')
    _autos_table(metrics[[c for c in ("Ticker", "Name", "Updated", "Status") if c in metrics.columns]], "autos1_quality_market", 500)
    _html('<div class="a1-group">Macro & Energy Registry</div>')
    _autos_table(quality, "autos1_quality_fred", 500)
    contract = pd.DataFrame([
        {"Layer": "OEM / supplier / ETF pricing", "Primary": "Yahoo/yfinance batch", "Frequency": "Daily", "Fallback": "Unavailable; no stale quote invented"},
        {"Layer": "US production / demand / finance", "Primary": "FRED official/public mirrors", "Frequency": "Monthly / quarterly", "Fallback": "Visible missing state"},
        {"Layer": "Gasoline / diesel / electricity", "Primary": "EIA/BLS via FRED", "Frequency": "Weekly / monthly", "Fallback": "No cross-unit substitution"},
        {"Layer": "Global EV adoption", "Primary": "IEA Global EV Outlook 2026", "Frequency": "Annual snapshot", "Fallback": "Static 2025 observation, explicitly dated"},
        {"Layer": "Trade / supply-chain stress", "Primary": "User scenario + disclosed exposure weights", "Frequency": "Scenario", "Fallback": "Not presented as historical fact"},
        {"Layer": "Newsletter / article feed", "Primary": "Disabled by design", "Frequency": "—", "Fallback": "None"},
    ])
    _html('<div class="a1-group">Provider Contract</div>')
    _autos_table(contract, "autos1_quality_contract", 280)


def _render_autos_page_v1(ticker: str, price_data: pd.DataFrame, analysis: Mapping[str, Any]) -> None:
    del ticker, price_data, analysis
    _autos_css()
    section = st.radio("Autos section", AUTOS_SECTIONS, horizontal=True, key="autos1_section", label_visibility="collapsed")
    controls = st.columns([1, 1, 1, 5])
    with controls[0]:
        refresh = st.button("Refresh", key="autos1_refresh")
    nonce = int(st.session_state.get("autos1_nonce", 0))
    if refresh:
        nonce += 1
        st.session_state["autos1_nonce"] = nonce
    with controls[1]:
        window = st.selectbox("Window", ("1Y", "3Y", "5Y", "10Y", "Max"), index=1, key="autos1_window")
    with controls[2]:
        st.selectbox("Frequency", ("Native",), index=0, key="autos1_frequency", disabled=True)
    _autos_header(section)
    _html(f'<div class="a1-note">{_escape(AUTOS_VERSION)} · Direct analytical layout · no newsletter module · Autos-only append-only override.</div>')

    closes, metrics, market_meta = _autos_market_pack(nonce)
    needs_fred = section in {"Production & Demand", "Powertrain Economics", "Data Quality"}
    fred_pack, fred_quality = _autos_fred_pack(nonce) if needs_fred else ({}, pd.DataFrame())
    if section == "Overview":
        _autos_render_overview(closes, metrics, window)
    elif section == "EV & Batteries":
        _autos_render_ev(closes, metrics, window)
    elif section == "Production & Demand":
        _autos_render_production(fred_pack, fred_quality, window)
    elif section == "Powertrain Economics":
        _autos_render_powertrain(fred_pack, window)
    elif section == "Trade & Supply Chain":
        _autos_render_trade(closes, metrics, window)
    elif section == "Data Quality":
        _autos_render_quality(metrics, market_meta, fred_quality)


